// @ts-nocheck
/* eslint-disable */
// ARQUIVO GERADO por tools/erp/gerar_templates.mjs — não editar à mão.
export const FONTES: Record<string, string> = {
  "_validacao_sistema_cliente.html": "{# ═══════════════════════════════════════════════════════════════\n   NÍVEL 2 — DETALHAMENTO DE UM CLIENTE\n   Parcial carregado sob demanda ao clicar no cliente.\n   Mostra primeiro a previsão mês a mês consolidada (com os vencimentos\n   identificados) e depois a quebra por condomínio.\n   Recebe: cli, codes_cliente, meses, inicio_label, agro_special_label\n   ═══════════════════════════════════════════════════════════════ #}\n{% import \"_validacao_sistema_macros.html\" as vsm with context %}\n\n<div style=\"padding:16px 18px 20px;\">\n\n  {# ── 2.1 · Previsão mês a mês consolidada do cliente ── #}\n  <div class=\"section-label\" style=\"margin-bottom:8px;\">\n    Previsão mês a mês — {{ cli.client_name }}\n    <span style=\"color:#888;font-weight:400;text-transform:none;letter-spacing:0;\">\n      · {{ meses }} meses a partir de {{ inicio_label }} ·\n    </span>\n    <span style=\"color:#4ade80;font-weight:700;\">\n      total no horizonte {{ formatar_moeda(cli.yield_horizon) }}\n    </span>\n  </div>\n\n  <div style=\"font-size:11px;color:#666;margin-bottom:10px;\">\n    Simulação assumindo retirada de cada cota no vencimento. As linhas destacadas\n    em <span style=\"color:#f0ad4e;\">âmbar</span> têm cota vencendo no mês.\n  </div>\n\n  <table style=\"width:100%;border-collapse:collapse;font-size:12.5px;margin-bottom:24px;\">\n    <thead>\n      <tr style=\"border-bottom:1px solid rgba(255,255,255,.12);\">\n        <th style=\"padding:7px 8px;text-align:left;color:#777;font-weight:500;\">Mês/Ano</th>\n        <th style=\"padding:7px 8px;text-align:right;color:#777;font-weight:500;\">Valor base</th>\n        {% for code in codes_cliente %}\n        <th style=\"padding:7px 8px;text-align:right;color:#777;font-weight:500;\">\n          {{ vsm.cond_icon(code) }}\n          {% if code == 'civil' %}Civil{% elif code == 'agro' %}Agro{% elif code == 'saude' %}Saúde{% else %}{{ code }}{% endif %}\n        </th>\n        {% endfor %}\n        <th style=\"padding:7px 8px;text-align:right;color:#d4af37;font-weight:600;\">Rendimento total</th>\n        <th style=\"padding:7px 8px;text-align:center;color:#777;font-weight:500;\">Cotas ativas</th>\n        <th style=\"padding:7px 8px;text-align:left;color:#777;font-weight:500;\">Vencimentos no mês</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for m in cli.monthly_totals %}\n      <tr style=\"border-bottom:1px solid rgba(255,255,255,.05);\n                 {% if m.shares_included == 0 %}opacity:.45;{% endif %}\n                 {% if m.maturing_shares %}background:rgba(240,173,78,.07);{% endif %}\">\n\n        <td style=\"padding:7px 8px;font-weight:700;color:#F5F5F5;\">{{ m.month_label }}</td>\n\n        <td style=\"padding:7px 8px;text-align:right;color:#ccc;\">{{ formatar_moeda(m.base_amount) }}</td>\n\n        {% for code in codes_cliente %}\n        {% set v = m.by_condominium.get(code) %}\n        <td style=\"padding:7px 8px;text-align:right;color:{{ '#ddd' if v else '#3a3a3a' }};\">\n          {{ formatar_moeda(v) if v else '—' }}\n        </td>\n        {% endfor %}\n\n        <td style=\"padding:7px 8px;text-align:right;font-weight:700;font-size:13.5px;\n                   color:{{ '#4ade80' if m.yield_amount > 0 else '#555' }};\">\n          {{ formatar_moeda(m.yield_amount) }}\n        </td>\n\n        <td style=\"padding:7px 8px;text-align:center;color:#aaa;\">{{ m.shares_included }}</td>\n\n        <td style=\"padding:7px 8px;\">\n          {% if m.maturing_shares %}\n            {% for c in m.maturing_shares %}{{ vsm.cota_venc_badge(c) }}{% endfor %}\n          {% elif m.shares_included == 0 %}\n            <span class=\"badge badge-danger\">⛔ Fora da base</span>\n          {% else %}\n            <span style=\"color:#555;\">—</span>\n          {% endif %}\n\n          {% if m.ending_shares %}\n            <div style=\"font-size:10px;color:#f0ad4e;margin-top:3px;line-height:1.5;\">\n              ↳ último rendimento da(s) cota(s)\n              {{ m.ending_shares | map(attribute='share_number') | join(', ') }}\n              — sai(em) da base no mês seguinte\n            </div>\n          {% endif %}\n        </td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n\n  {# ── 2.2 · Quebra por condomínio (abre o nível 3) ── #}\n  <div class=\"section-label\" style=\"margin-bottom:10px;\">\n    Condomínios de {{ cli.client_name }} — clique para ver cotas e projeção do condomínio\n  </div>\n\n  <table style=\"width:100%;border-collapse:collapse;font-size:13px;\">\n    <thead>\n      <tr style=\"border-bottom:1px solid rgba(255,255,255,.1);\">\n        <th style=\"padding:7px 8px;width:30px;\"></th>\n        <th style=\"padding:7px 8px;text-align:left;color:#888;font-weight:500;\">Condomínio</th>\n        <th style=\"padding:7px 8px;text-align:right;color:#888;font-weight:500;\">Total investido</th>\n        <th style=\"padding:7px 8px;text-align:center;color:#888;font-weight:500;\">Cotas</th>\n        <th style=\"padding:7px 8px;text-align:center;color:#888;font-weight:500;\">Taxa normal</th>\n        <th style=\"padding:7px 8px;text-align:right;color:#888;font-weight:500;\">Rend. mensal atual</th>\n        <th style=\"padding:7px 8px;text-align:center;color:#888;font-weight:500;\">Próx. vencimento</th>\n        <th style=\"padding:7px 8px;text-align:center;color:#888;font-weight:500;\">Último mês c/ rend.</th>\n        <th style=\"padding:7px 8px;text-align:right;color:#888;font-weight:500;\">Rend. 12 meses</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for b in cli.condominiums %}\n      {% set bid = 'c' ~ cli.client_id ~ '-k' ~ b.condominium_id %}\n      <tr onclick=\"vsToggle('{{ bid }}')\" style=\"cursor:pointer;border-bottom:1px solid rgba(255,255,255,.05);\">\n        <td style=\"padding:8px;text-align:center;\">\n          <span id=\"arrow-{{ bid }}\" style=\"color:#d4af37;font-size:10px;\">▶</span>\n        </td>\n        <td style=\"padding:8px;\">{{ vsm.cond_badge(b.condominium_code, b.condominium_name) }}</td>\n        <td style=\"padding:8px;text-align:right;font-weight:700;color:#d4af37;\">{{ formatar_moeda(b.total_invested) }}</td>\n        <td style=\"padding:8px;text-align:center;color:#888;\">{{ b.shares_count }}</td>\n        <td style=\"padding:8px;text-align:center;color:#ccc;\">{{ b.normal_rate_label }}</td>\n        <td style=\"padding:8px;text-align:right;color:#4ade80;font-weight:600;\">{{ formatar_moeda(b.current_month_yield) }}</td>\n        <td style=\"padding:8px;text-align:center;color:{{ '#f87171' if b.next_maturity_overdue else '#ccc' }};\">\n          {{ vsm.data_br(b.next_maturity_date) }}\n        </td>\n        <td style=\"padding:8px;text-align:center;color:#a78bfa;\">{{ b.last_yield_month_label }}</td>\n        <td style=\"padding:8px;text-align:right;color:#4ade80;\">{{ formatar_moeda(b.yield_12m) }}</td>\n      </tr>\n\n      {# ═══ NÍVEL 3 — carregado sob demanda ═══ #}\n      <tr id=\"det-{{ bid }}\" style=\"display:none;background:rgba(212,175,55,0.035);\">\n        <td colspan=\"9\" style=\"padding:0;\">\n          <div class=\"vs-lazy\" id=\"lazy-{{ bid }}\"\n               data-client-id=\"{{ cli.client_id }}\"\n               data-condominium-id=\"{{ b.condominium_id }}\"\n               data-loaded=\"0\"\n               style=\"padding:18px;color:#666;font-size:12px;\">\n            Carregando detalhamento do condomínio…\n          </div>\n        </td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n\n</div>\n",
  "_validacao_sistema_detalhe.html": "{# ═══════════════════════════════════════════════════════════════\n   NÍVEL 3 — DETALHAMENTO DE UM CONDOMÍNIO DE UM CLIENTE\n   Parcial carregado sob demanda (AJAX) pela tela Validação Sistema.\n   Recebe: b (bloco do condomínio), meses, inicio_label, agro_special_label\n   ═══════════════════════════════════════════════════════════════ #}\n{% import \"_validacao_sistema_macros.html\" as vsm with context %}\n\n<div style=\"padding:14px 16px 18px;border-left:2px solid rgba(212,175,55,.35);margin-left:8px;\">\n\n  <div class=\"note-box\" style=\"margin-bottom:14px;font-size:12px;\">\n    <strong style=\"color:#d4af37;\">Regra aplicada:</strong> {{ b.withdrawal_rule }}\n    {% if b.shares_without_maturity %}\n      <br><span style=\"color:#f0ad4e;\">⚠️ {{ b.shares_without_maturity }} cota(s) sem\n      vencimento cadastrado — consideradas ativas em todo o horizonte, com a taxa normal.</span>\n    {% endif %}\n  </div>\n\n  {# ── 3.1 · Cotas do cliente neste condomínio ── #}\n  <div class=\"section-label\" style=\"margin-bottom:8px;\">\n    Cotas · {{ b.shares_count }} cota(s) · {{ formatar_moeda(b.total_invested) }}\n  </div>\n  <table style=\"width:100%;border-collapse:collapse;font-size:12px;margin-bottom:20px;\">\n    <thead>\n      <tr style=\"border-bottom:1px solid rgba(255,255,255,.1);\">\n        <th style=\"padding:6px 8px;text-align:left;color:#777;font-weight:500;\">Nº Cota</th>\n        <th style=\"padding:6px 8px;text-align:right;color:#777;font-weight:500;\">Valor</th>\n        <th style=\"padding:6px 8px;text-align:center;color:#777;font-weight:500;\">Aquisição</th>\n        <th style=\"padding:6px 8px;text-align:center;color:#777;font-weight:500;\">Vencimento</th>\n        <th style=\"padding:6px 8px;text-align:center;color:#777;font-weight:500;\">Status</th>\n        <th style=\"padding:6px 8px;text-align:left;color:#777;font-weight:500;\">Regra de retirada</th>\n        <th style=\"padding:6px 8px;text-align:center;color:#777;font-weight:500;\">Último mês c/ rend.</th>\n        <th style=\"padding:6px 8px;text-align:left;color:#777;font-weight:500;\">Observações</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for s in b.shares %}\n      <tr style=\"border-bottom:1px solid rgba(255,255,255,.04);\">\n        <td style=\"padding:6px 8px;font-weight:700;color:#d4af37;font-size:14px;\">{{ s.share_number }}</td>\n        <td style=\"padding:6px 8px;text-align:right;color:#ddd;font-weight:600;\">{{ formatar_moeda(s.share_value) }}</td>\n        <td style=\"padding:6px 8px;text-align:center;color:#888;\">{{ vsm.data_br(s.acquisition_date) }}</td>\n        <td style=\"padding:6px 8px;text-align:center;font-weight:600;color:{{ '#f0ad4e' if s.has_maturity else '#f87171' }};\">\n          {% if s.has_maturity %}{{ vsm.data_br(s.maturity_date) }}\n          {% else %}<span class=\"badge badge-extended\">Sem vencimento</span>{% endif %}\n        </td>\n        <td style=\"padding:6px 8px;text-align:center;\">\n          {% if s.withdrawal_requested %}\n            <span class=\"badge badge-retirada\">Em retirada</span>\n          {% else %}\n            <span class=\"badge badge-active\">{{ s.status }}</span>\n          {% endif %}\n        </td>\n        <td style=\"padding:6px 8px;color:#999;font-size:11px;\">{{ s.withdrawal_rule }}</td>\n        <td style=\"padding:6px 8px;text-align:center;color:#a78bfa;font-weight:600;\">{{ s.last_yield_month_label }}</td>\n        <td style=\"padding:6px 8px;color:#888;font-size:11px;\">\n          {% if s.notes %}{{ s.notes | join(' · ') }}{% else %}—{% endif %}\n        </td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n\n  {# ── 3.2 · Previsão mês a mês ── #}\n  <div class=\"section-label\" style=\"margin-bottom:8px;\">\n    Previsão mês a mês · {{ meses }} meses a partir de {{ inicio_label }}\n    <span style=\"color:#4ade80;font-weight:700;margin-left:8px;\">\n      Total no horizonte: {{ formatar_moeda(b.yield_horizon) }}\n    </span>\n  </div>\n  <table style=\"width:100%;border-collapse:collapse;font-size:12px;\">\n    <thead>\n      <tr style=\"border-bottom:1px solid rgba(255,255,255,.1);\">\n        <th style=\"padding:6px 8px;text-align:left;color:#777;font-weight:500;\">Mês/Ano</th>\n        <th style=\"padding:6px 8px;text-align:right;color:#777;font-weight:500;\">Valor base</th>\n        <th style=\"padding:6px 8px;text-align:center;color:#777;font-weight:500;\">Taxa aplicada</th>\n        <th style=\"padding:6px 8px;text-align:right;color:#777;font-weight:500;\">Rendimento previsto</th>\n        <th style=\"padding:6px 8px;text-align:center;color:#777;font-weight:500;\">Cotas consideradas</th>\n        <th style=\"padding:6px 8px;text-align:center;color:#777;font-weight:500;\">Cotas vencendo</th>\n        <th style=\"padding:6px 8px;text-align:left;color:#777;font-weight:500;\">Regra aplicada no mês</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for m in b.monthly_projection %}\n      <tr style=\"border-bottom:1px solid rgba(255,255,255,.04);\n                 {% if m.shares_included == 0 %}opacity:.45;{% endif %}\n                 {% if m.shares_maturing %}background:rgba(240,173,78,.06);{% endif %}\">\n        <td style=\"padding:6px 8px;font-weight:700;color:#F5F5F5;\">{{ m.month_label }}</td>\n        <td style=\"padding:6px 8px;text-align:right;color:#ccc;\">{{ formatar_moeda(m.base_amount) }}</td>\n        <td style=\"padding:6px 8px;text-align:center;color:#d4af37;font-weight:600;\">\n          {{ m.rates_applied | join(' + ') if m.rates_applied else '—' }}\n        </td>\n        <td style=\"padding:6px 8px;text-align:right;font-weight:700;\n                   color:{{ '#4ade80' if m.yield_amount > 0 else '#555' }};\">\n          {{ formatar_moeda(m.yield_amount) }}\n          {% if m.special_yield_amount > 0 %}\n            <div style=\"font-size:10px;color:#fbbf24;font-weight:500;\">\n              especial: {{ formatar_moeda(m.special_yield_amount) }}\n            </div>\n          {% endif %}\n        </td>\n        <td style=\"padding:6px 8px;text-align:center;color:#aaa;\">{{ m.shares_included }}</td>\n        <td style=\"padding:6px 8px;text-align:center;color:{{ '#f0ad4e' if m.shares_maturing else '#555' }};font-weight:600;\">\n          {% if m.maturing_shares %}\n            {{ m.shares_maturing }}\n            <div style=\"font-size:10px;font-weight:500;color:#f0ad4e;line-height:1.5;\">\n              nº {{ m.maturing_shares | map(attribute='share_number') | join(', nº ') }}\n            </div>\n          {% else %}—{% endif %}\n        </td>\n        <td style=\"padding:6px 8px;\">\n          <div style=\"display:flex;flex-wrap:wrap;gap:4px;margin-bottom:3px;\">\n            {% for bg in m.badges %}{{ vsm.proj_badge(bg, agro_special_label) }}{% endfor %}\n          </div>\n          {% if m.notes %}\n            <div style=\"color:#888;font-size:10px;line-height:1.5;\">{{ m.notes | join(' · ') }}</div>\n          {% endif %}\n        </td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n\n</div>\n",
  "_validacao_sistema_macros.html": "{# Macros compartilhados — tela Validação Sistema e seu parcial de detalhe #}\n\n{% macro cond_badge(code, name) %}\n  {% if code == 'civil' %}<span class=\"badge badge-civil\">🏗️ {{ name or 'Construção Civil' }}</span>\n  {% elif code == 'agro' %}<span class=\"badge badge-agro\">🌾 {{ name or 'Agronegócio' }}</span>\n  {% elif code == 'saude' %}<span class=\"badge badge-saude\">🏥 {{ name or 'Saúde' }}</span>\n  {% else %}<span class=\"badge\">{{ name or code }}</span>{% endif %}\n{% endmacro %}\n\n{% macro proj_badge(chave, agro_label) %}\n  {% if chave == 'normal' %}\n    <span class=\"badge\" style=\"background:rgba(255,255,255,.05);color:#9ca3af;border:1px solid rgba(255,255,255,.1);\">Normal</span>\n  {% elif chave == 'venc_civil' %}\n    <span class=\"badge badge-warning\">🏗️ Vencimento Civil</span>\n  {% elif chave == 'venc_agro' %}\n    <span class=\"badge badge-warning\">🌾 Vencimento Agro {{ agro_label or '3,5%' }}</span>\n  {% elif chave == 'venc_saude' %}\n    <span class=\"badge badge-warning\">🏥 Vencimento Saúde</span>\n  {% elif chave == 'mes_extra' %}\n    <span class=\"badge badge-retirada\">📤 Mês extra retirada</span>\n  {% elif chave == 'sem_vencimento' %}\n    <span class=\"badge badge-extended\">⚠️ Sem vencimento</span>\n  {% elif chave == 'fora' %}\n    <span class=\"badge badge-danger\">⛔ Fora da base</span>\n  {% endif %}\n{% endmacro %}\n\n{% macro data_br(iso) %}{{ formatar_data(iso) if iso else '—' }}{% endmacro %}\n\n{% macro cond_icon(code) %}{% if code == 'civil' %}🏗️{% elif code == 'agro' %}🌾{% elif code == 'saude' %}🏥{% else %}📄{% endif %}{% endmacro %}\n\n{% macro cond_class(code) %}{% if code == 'civil' %}badge-civil{% elif code == 'agro' %}badge-agro{% elif code == 'saude' %}badge-saude{% else %}badge-warning{% endif %}{% endmacro %}\n\n{# Badge de uma cota que vence no mês — usado no detalhamento mensal do cliente #}\n{% macro cota_venc_badge(c) %}\n  <span class=\"badge {{ cond_class(c.condominium_code) }}\" style=\"margin:2px 3px 2px 0;\">\n    {{ cond_icon(c.condominium_code) }} nº {{ c.share_number }} ·\n    {{ formatar_moeda(c.share_value) }} · vence {{ formatar_data(c.maturity_date) }}\n  </span>\n{% endmacro %}\n",
  "apuracao.html": "{% extends \"base.html\" %}\n{% block title %}Apuração Mensal — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n\n<div class=\"page-header\">\n  <div class=\"page-header-icon\">📐</div>\n  <div class=\"page-header-title\">Apuração Mensal</div>\n  <div class=\"page-header-sub\">Calcule os rendimentos mensais e consolide os valores por cliente.</div>\n</div>\n\n<!-- FORMULÁRIO -->\n<div class=\"card-gold\" style=\"margin-bottom:24px;\">\n  <form method=\"post\" id=\"form-apuracao\">\n    <div class=\"form-section\">\n      <div class=\"form-section-title\">Período e Produto</div>\n      <div class=\"form-row\">\n\n        <div class=\"form-group\" style=\"max-width:140px;\">\n          <label>Mês *</label>\n          <select name=\"mes\" class=\"form-control\" id=\"sel-mes\">\n            {% for m in range(1,13) %}\n            {% set nomes = ['','Janeiro','Fevereiro','Março','Abril','Maio','Junho',\n                             'Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'] %}\n            <option value=\"{{ m }}\" {{ 'selected' if mes == m else '' }}>{{ nomes[m] }}</option>\n            {% endfor %}\n          </select>\n        </div>\n\n        <div class=\"form-group\" style=\"max-width:120px;\">\n          <label>Ano *</label>\n          <input type=\"number\" name=\"ano\" value=\"{{ ano }}\" min=\"2020\" max=\"2099\"\n                 class=\"form-control\" id=\"inp-ano\">\n        </div>\n\n        <div class=\"form-group\">\n          <label>Produto</label>\n          <select name=\"produto\" class=\"form-control\" id=\"sel-produto\">\n            <option value=\"\" {{ 'selected' if not produto_sel else '' }}>Todos os produtos</option>\n            {% for c in conds %}\n            <option value=\"{{ c.code }}\" {{ 'selected' if produto_sel == c.code else '' }}>{{ c.name }}</option>\n            {% endfor %}\n          </select>\n        </div>\n\n        <div class=\"form-group\" id=\"div-agro-rate\"\n             style=\"{% if not (produto_sel == 'agro' or not produto_sel) %}display:none;{% endif %}\">\n          <label>Taxa especial Agro <span style=\"color:#888;font-size:11px;\">(%)</span></label>\n          <input type=\"text\" name=\"agro_special_rate\" id=\"inp-agro-rate\"\n                 value=\"{{ resultado.agro_rate | float * 100 if resultado and resultado.agro_rate else '' }}\"\n                 class=\"form-control\" placeholder=\"Ex: 4 ou 4,0\" style=\"max-width:160px;\">\n          <div style=\"font-size:11px;color:#888;margin-top:4px;\">Aceita: 3,5% a 4,5%</div>\n        </div>\n\n      </div>\n    </div>\n    <div class=\"page-actions\" style=\"padding-top:0;margin-top:0;\">\n      <a href=\"{{ url_for('apuracao') }}\" class=\"btn btn-secondary\">Limpar</a>\n      <button type=\"submit\" class=\"btn btn-primary\">📐 Calcular</button>\n    </div>\n  </form>\n</div>\n\n<!-- ERRO -->\n{% if erro %}\n<div class=\"alert alert-error\" style=\"margin-bottom:20px;\">⚠️ {{ erro }}</div>\n{% endif %}\n\n<!-- RESULTADO -->\n{% if resultado %}\n{% set r = resultado %}\n{% set meses_nome = ['','Janeiro','Fevereiro','Março','Abril','Maio','Junho',\n                      'Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'] %}\n\n<div style=\"display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;margin-bottom:16px;\">\n  <div>\n    <div style=\"font-size:11px;color:#888;text-transform:uppercase;letter-spacing:1px;\">Resultado da Apuração</div>\n    <div style=\"font-size:18px;font-weight:700;color:#d4af37;\">\n      {{ meses_nome[r.mes] }}/{{ r.ano }}\n      {% if r.produto %}— {{ conds|selectattr('code','equalto',r.produto)|map(attribute='name')|first }}{% else %}— Todos os Produtos{% endif %}\n    </div>\n  </div>\n  {% if r.duplicata %}\n  <div class=\"note-box\" style=\"border-color:rgba(251,191,36,0.4);background:rgba(251,191,36,0.06);margin:0;max-width:360px;\">\n    <strong style=\"color:#fbbf24;\">⚠️ Atenção:</strong> Já existe apuração salva para este período.\n    <a href=\"{{ url_for('historico') }}\" style=\"color:#d4af37;\">Ver histórico</a>\n  </div>\n  {% endif %}\n</div>\n\n<!-- KPIs -->\n<div class=\"metrics-grid\" style=\"grid-template-columns:repeat(4,1fr);margin-bottom:20px;\">\n  <div class=\"metric-card\">\n    <div class=\"metric-value text-gold\">{{ formatar_moeda(r.total_geral) }}</div>\n    <div class=\"metric-label\">Total a Pagar</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#4ade80;\">{{ r.consolidado|length }}</div>\n    <div class=\"metric-label\">Clientes</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\">{{ r.qty_cotas }}</div>\n    <div class=\"metric-label\">Cotas</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#888;font-size:13px;\">\n      {% if r.produto %}{{ conds|selectattr('code','equalto',r.produto)|map(attribute='name')|first }}{% else %}Todos{% endif %}\n    </div>\n    <div class=\"metric-label\">Produto</div>\n  </div>\n</div>\n\n{% if r.total_agro > 0 %}\n<div class=\"note-box\" style=\"margin-bottom:16px;\">\n  <span style=\"color:#fbbf24;font-weight:600;\">🌾 Agronegócio: </span>{{ formatar_moeda(r.total_agro) }}\n  {% if r.agro_rate %} · taxa especial {{ \"%.2f\"|format(r.agro_rate|float * 100) }}%{% endif %}\n</div>\n{% endif %}\n\n<!-- Botão Salvar -->\n{% if not r.duplicata %}\n<form method=\"post\" action=\"{{ url_for('apuracao_salvar') }}\" id=\"form-salvar\" style=\"margin-bottom:24px;\">\n  <input type=\"hidden\" name=\"mes\"        value=\"{{ r.mes }}\">\n  <input type=\"hidden\" name=\"ano\"        value=\"{{ r.ano }}\">\n  <input type=\"hidden\" name=\"produto\"    value=\"{{ r.produto }}\">\n  <input type=\"hidden\" name=\"agro_rate\"  value=\"{{ r.agro_rate|float if r.agro_rate else '' }}\">\n  <input type=\"hidden\" name=\"items_json\" id=\"items-json-hidden\" value=\"\">\n  <div style=\"display:flex;gap:12px;align-items:center;padding:14px 16px;background:rgba(212,175,55,0.06);border:1px solid rgba(212,175,55,0.2);border-radius:8px;\">\n    <button type=\"submit\" class=\"btn btn-primary\" id=\"btn-salvar\">💾 Salvar no Histórico</button>\n    <span style=\"color:#888;font-size:13px;\">A apuração será salva para consulta posterior. Durante a fase de implantação, ela poderá ser excluída e refeita se necessário.</span>\n  </div>\n</form>\n{% else %}\n<div style=\"margin-bottom:24px;padding:12px 16px;background:rgba(251,191,36,0.06);border:1px solid rgba(251,191,36,0.25);border-radius:8px;font-size:13px;color:#fbbf24;\">\n  ⚠️ Apuração já salva para este período. <a href=\"{{ url_for('historico') }}\" style=\"color:#d4af37;font-weight:600;\">Abrir Histórico</a>\n</div>\n{% endif %}\n\n<!-- CONSOLIDADO POR CLIENTE -->\n<div class=\"section-label\" style=\"margin-bottom:12px;\">● Consolidado por Cliente</div>\n<div class=\"table-wrap\" style=\"margin-bottom:8px;\">\n  <table>\n    <thead>\n      <tr>\n        <th style=\"width:28px;\"></th>\n        <th>Cliente</th>\n        <th>CPF</th>\n        <th>Pix</th>\n        <th>Produto</th>\n        <th style=\"text-align:center;\">Cotas</th>\n        <th style=\"text-align:right;\">Capital Investido</th>\n        <th style=\"text-align:right;color:#d4af37;\">Rendimento</th>\n        <th style=\"text-align:center;\">Detalhes</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for cli in r.consolidado %}\n      {% set rid = loop.index0 %}\n      <tr>\n        <td style=\"text-align:center;color:#888;font-size:12px;\">{{ loop.index }}</td>\n        <td style=\"font-weight:600;color:#F5F5F5;\">{{ cli.client_name }}</td>\n        <td class=\"text-mono text-dim\">{{ cli.client_cpf }}</td>\n        <td class=\"text-dim\" style=\"font-size:12px;\">{{ cli.client_pix or '—' }}</td>\n        <td>\n          {% if cli.condominium_code == 'civil' %}<span class=\"badge badge-civil\">🏗️ Civil</span>\n          {% elif cli.condominium_code == 'agro' %}<span class=\"badge badge-agro\">🌾 Agro</span>\n          {% else %}<span class=\"badge badge-saude\">🏥 Saúde</span>\n          {% endif %}\n        </td>\n        <td style=\"text-align:center;color:#888;\">\n          {{ cli.active_shares_count if cli.active_shares_count is defined else cli.shares_count }}\n          {% if cli.withdrawn_count %}<br><small style=\"color:#38bdf8;\">+{{ cli.withdrawn_count }} retirada(s)</small>{% endif %}\n        </td>\n        <td style=\"text-align:right;color:#aaa;\">\n          {{ formatar_moeda(cli.total_share_value) }}\n          {% if cli.withdrawn_count %}<br><small style=\"color:#38bdf8;\" title=\"Capital retirado dentro do período — rendeu proporcional, mas saiu do ativo\">− {{ formatar_moeda(cli.total_withdrawn_value) }} retirado</small>{% endif %}\n        </td>\n        <td style=\"text-align:right;font-weight:700;color:#d4af37;font-size:16px;\">{{ formatar_moeda(cli.total_income) }}</td>\n        <td style=\"text-align:center;\">\n          <button type=\"button\" class=\"btn btn-secondary btn-sm\"\n                  onclick=\"toggleCotas({{ rid }})\" id=\"btn-{{ rid }}\">▶ Ver cotas</button>\n        </td>\n      </tr>\n      <tr id=\"detalhe-{{ rid }}\" style=\"display:none;background:rgba(0,0,0,0.25);\">\n        <td colspan=\"9\" style=\"padding:0;\">\n          <div style=\"padding:12px 16px 16px;\">\n            <div style=\"font-size:11px;color:#888;text-transform:uppercase;letter-spacing:1px;margin-bottom:10px;\">\n              Cotas de {{ cli.client_name }} · {{ cli.condominium_name }}\n            </div>\n            <table style=\"width:100%;border-collapse:collapse;font-size:13px;\">\n              <thead>\n                <tr style=\"border-bottom:1px solid rgba(255,255,255,0.08);\">\n                  <th style=\"padding:6px 8px;text-align:left;color:#888;font-weight:500;\">Nº Cota</th>\n                  <th style=\"padding:6px 8px;text-align:right;color:#888;font-weight:500;\">Valor</th>\n                  <th style=\"padding:6px 8px;color:#888;font-weight:500;\">Aquisição</th>\n                  <th style=\"padding:6px 8px;color:#888;font-weight:500;\">Vencimento</th>\n                  <th style=\"padding:6px 8px;color:#888;font-weight:500;\">Ú. Renovação</th>\n                  <th style=\"padding:6px 8px;color:#888;font-weight:500;\">Período</th>\n                  <th style=\"padding:6px 8px;text-align:center;color:#888;font-weight:500;\">Dias</th>\n                  <th style=\"padding:6px 8px;text-align:right;color:#888;font-weight:500;\">Taxa</th>\n                  <th style=\"padding:6px 8px;text-align:right;color:#d4af37;font-weight:500;\">Rendimento</th>\n                  <th style=\"padding:6px 8px;color:#888;font-weight:500;\">Tipo</th>\n                </tr>\n              </thead>\n              <tbody>\n                {% for it in cli[\"shares_detail\"] %}\n                <tr style=\"border-bottom:1px solid rgba(255,255,255,0.04);\">\n                  <td style=\"padding:6px 8px;font-weight:700;color:#d4af37;\">{{ it.share_number }}</td>\n                  <td style=\"padding:6px 8px;text-align:right;color:#ccc;\">{{ formatar_moeda(it.share_value) }}</td>\n                  <td style=\"padding:6px 8px;color:#888;\">{{ it.acquisition_date or '—' }}</td>\n                  <td style=\"padding:6px 8px;color:#888;\">{{ it.maturity_date or '—' }}</td>\n                  <td style=\"padding:6px 8px;color:#888;\">{{ it.last_renewal_date or '—' }}</td>\n                  <td style=\"padding:6px 8px;color:#888;font-size:11px;\">{{ it.period_start }} →<br>{{ it.period_end }}</td>\n                  <td style=\"padding:6px 8px;text-align:center;color:#888;\">{{ it.active_days }}/{{ it.total_period_days }}</td>\n                  <td style=\"padding:6px 8px;text-align:right;color:#888;\">{{ \"%.2f\"|format(it.applied_rate * 100) }}%</td>\n                  <td style=\"padding:6px 8px;text-align:right;font-weight:700;color:#d4af37;\">{{ formatar_moeda(it.income_value) }}</td>\n                  <td style=\"padding:6px 8px;font-size:11px;\">\n                    {% if it.calc_type == 'Integral' %}<span style=\"color:#4ade80;\">✓ Integral</span>\n                    {% elif it.calc_type == 'Proporcional' %}<span style=\"color:#fbbf24;\">⊘ Proporcional</span>\n                    {% elif 'até retirada' in it.calc_type %}<span style=\"color:#38bdf8;\" title=\"{{ it.calculation_details }}\">↩ Proporc. até retirada{% if it.withdrawal_date %}<br><small style=\"color:#64748b;\">retirada {{ it.withdrawal_date }}</small>{% endif %}</span>\n                    {% elif 'Especial' in it.calc_type %}<span style=\"color:#f97316;\">★ Especial Agro</span>\n                    {% else %}<span style=\"color:#fbbf24;\">⊘ {{ it.calc_type }}</span>\n                    {% endif %}\n                  </td>\n                </tr>\n                {% endfor %}\n              </tbody>\n              <tfoot>\n                <tr style=\"border-top:1px solid rgba(212,175,55,0.3);\">\n                  <td colspan=\"8\" style=\"padding:8px;text-align:right;color:#888;font-weight:600;\">Total {{ cli.client_name }}</td>\n                  <td style=\"padding:8px;text-align:right;font-weight:700;color:#d4af37;\">{{ formatar_moeda(cli.total_income) }}</td>\n                  <td></td>\n                </tr>\n              </tfoot>\n            </table>\n          </div>\n        </td>\n      </tr>\n      {% endfor %}\n    </tbody>\n    <tfoot>\n      <tr style=\"border-top:2px solid rgba(212,175,55,0.3);\">\n        <td colspan=\"6\" style=\"font-weight:600;color:#d4af37;padding:10px 12px;\">TOTAL GERAL</td>\n        <td style=\"text-align:right;font-weight:600;color:#aaa;padding:10px 12px;\">\n          {{ formatar_moeda(r.consolidado | sum(attribute='total_share_value')) }}\n        </td>\n        <td style=\"text-align:right;font-weight:700;color:#d4af37;font-size:18px;padding:10px 12px;\">\n          {{ formatar_moeda(r.total_geral) }}\n        </td>\n        <td></td>\n      </tr>\n    </tfoot>\n  </table>\n</div>\n<div style=\"font-size:11px;color:#555;margin-bottom:28px;text-align:right;\">\n  {{ r.consolidado|length }} cliente(s) · {{ r.qty_cotas }} cota(s)\n</div>\n\n<script>\n(function(){\n  var items = {{ r[\"items\"] | tojson }};\n  var el = document.getElementById('items-json-hidden');\n  if (el) el.value = JSON.stringify(items);\n})();\n</script>\n\n{% endif %}\n\n{% endblock %}\n\n{% block scripts %}\n<script>\nfunction toggleCotas(idx) {\n  var row = document.getElementById('detalhe-' + idx);\n  var btn = document.getElementById('btn-' + idx);\n  if (!row) return;\n  var open = row.style.display === 'none' || row.style.display === '';\n  row.style.display = open ? 'table-row' : 'none';\n  btn.textContent = open ? '▼ Ocultar' : '▶ Ver cotas';\n}\n\n(function(){\n  var sel = document.getElementById('sel-produto');\n  var div = document.getElementById('div-agro-rate');\n  if (!sel || !div) return;\n  function toggle(){\n    div.style.display = (sel.value === '' || sel.value === 'agro') ? '' : 'none';\n  }\n  sel.addEventListener('change', toggle);\n  toggle();\n})();\n\n</script>\n{% endblock %}\n",
  "auditoria.html": "{% extends \"base.html\" %}\n{% block title %}Auditoria — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n\n<div class=\"page-header\" style=\"display:flex;justify-content:space-between;align-items:flex-start;\">\n  <div>\n    <div class=\"page-header-icon\">🔍</div>\n    <div class=\"page-header-title\">Auditoria</div>\n    <div class=\"page-header-sub\">Registro de todas as operações do sistema</div>\n  </div>\n</div>\n\n<!-- Filtros -->\n<form method=\"get\" class=\"toolbar\">\n  <div class=\"toolbar-left\">\n    <select name=\"entity\" class=\"form-control form-control-sm\" style=\"width:180px;\">\n      <option value=\"\">Todas as entidades</option>\n      <option value=\"clients\" {{ 'selected' if entity_filtro == 'clients' else '' }}>Clientes</option>\n      <option value=\"shares\"  {{ 'selected' if entity_filtro == 'shares'  else '' }}>Cotas</option>\n    </select>\n    <button type=\"submit\" class=\"btn btn-secondary btn-sm\">Filtrar</button>\n    {% if entity_filtro %}\n      <a href=\"{{ url_for('auditoria') }}\" class=\"btn btn-secondary btn-sm\">Limpar</a>\n    {% endif %}\n  </div>\n</form>\n\n{% if logs %}\n<div class=\"table-wrap\">\n  <table>\n    <thead>\n      <tr>\n        <th>Data/Hora</th>\n        <th>Entidade</th>\n        <th>ID</th>\n        <th>Ação</th>\n        <th>Observação</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for log in logs %}\n      <tr>\n        <td class=\"text-mono text-dim\" style=\"font-size:12px;\">{{ log.created_at }}</td>\n        <td>\n          {% if log.entity_type == 'clients' %}\n            <span class=\"badge badge-civil\">👤 Clientes</span>\n          {% elif log.entity_type == 'shares' %}\n            <span class=\"badge badge-agro\">📄 Cotas</span>\n          {% else %}\n            <span class=\"badge badge-inactive\">{{ log.entity_type }}</span>\n          {% endif %}\n        </td>\n        <td class=\"text-dim\">{{ log.entity_id or '—' }}</td>\n        <td style=\"font-weight:500;color:#ccc;\">{{ log.action }}</td>\n        <td class=\"text-dim\" style=\"font-size:12px;\">{{ log.user_note or '—' }}</td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n<div class=\"text-dim\" style=\"font-size:12px;margin-top:10px;text-align:right;\">\n  {{ logs | length }} registro(s)\n</div>\n{% else %}\n<div class=\"empty-state\">\n  <div class=\"empty-state-icon\">🔍</div>\n  <div class=\"empty-state-title\">Nenhum registro de auditoria</div>\n  <div class=\"empty-state-sub\">As operações realizadas no sistema aparecerão aqui.</div>\n</div>\n{% endif %}\n\n{% endblock %}\n",
  "backup.html": "{% extends \"base.html\" %}\n{% block title %}Backup — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n\n<div class=\"page-header\" style=\"display:flex;justify-content:space-between;align-items:flex-start;\">\n  <div>\n    <div class=\"page-header-icon\">💾</div>\n    <div class=\"page-header-title\">Backup</div>\n    <div class=\"page-header-sub\">Gerenciamento de backups do banco de dados</div>\n  </div>\n  <form method=\"post\" action=\"{{ url_for('backup_criar') }}\">\n    <button type=\"submit\" class=\"btn btn-primary\" style=\"margin-top:14px;\">\n      + Criar Backup Agora\n    </button>\n  </form>\n</div>\n\n{% if backups %}\n<div class=\"table-wrap\">\n  <table>\n    <thead>\n      <tr>\n        <th>Arquivo</th>\n        <th>Tamanho</th>\n        <th>Data</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for b in backups %}\n      <tr>\n        <td class=\"backup-name\">{{ b.nome }}</td>\n        <td class=\"text-dim\">{{ b.tamanho_kb }} KB</td>\n        <td class=\"text-dim\">{{ b.data }}</td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n<div class=\"text-dim\" style=\"font-size:12px;margin-top:10px;text-align:right;\">\n  {{ backups | length }} backup(s) encontrado(s)\n</div>\n{% else %}\n<div class=\"empty-state\">\n  <div class=\"empty-state-icon\">💾</div>\n  <div class=\"empty-state-title\">Nenhum backup encontrado</div>\n  <div class=\"empty-state-sub\">Crie o primeiro backup agora.</div>\n</div>\n{% endif %}\n\n{% endblock %}\n",
  "base.html": "<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>{% block title %}Grupo Capuzzo — Gestão de Investimentos{% endblock %}</title>\n  <link rel=\"stylesheet\" href=\"{{ url_for('static', filename='style.css') }}\">\n  {% block head %}{% endblock %}\n</head>\n<body>\n<div class=\"app-wrapper\">\n\n  <!-- ═══════════════════════════════════════════════\n       SIDEBAR\n  ═══════════════════════════════════════════════ -->\n  <aside class=\"sidebar\">\n\n    <!-- Brand -->\n    <div class=\"sidebar-brand\">\n      <div class=\"sidebar-brand-name\">GRUPO CAPUZZO</div>\n      <div class=\"sidebar-brand-sub\">Gestão de Investimentos</div>\n      <div class=\"sidebar-brand-label\">Painel de Gestão</div>\n    </div>\n\n    <!-- Volta para a Central de Operações do Grupo -->\n    <a href=\"/erp/central\" class=\"sidebar-link\">\n      <span class=\"sidebar-link-icon\">&#8592;</span> Central do Grupo\n    </a>\n\n    <!-- Nav -->\n    <nav class=\"sidebar-nav\">\n\n      {# ── Detecta se alguma sub-página de Condomínios está ativa ── #}\n      {% set cond_active = active_page in [\n           'produto_civil','produto_agro','produto_saude',\n           'apuracao','historico','relatorios','vencimentos',\n           'validacao_sistema'\n         ] %}\n\n      {# ── Detecta se alguma sub-página de Títulos Privados está ativa ── #}\n      {% set titulos_active = active_page in [\n           'titulos_privados_dashboard','titulos_privados_clientes',\n           'titulos_privados_emprestimos','titulos_privados_parcelas',\n           'titulos_privados_prorrogacoes','titulos_privados_amortizacoes',\n           'titulos_privados_calculadora_price'\n         ] %}\n\n      <!-- ── VISÃO GERAL ──────────────────────── -->\n      <div class=\"sidebar-section-label\">VISÃO GERAL</div>\n      <a href=\"{{ url_for('dashboard') }}\"\n         class=\"sidebar-link {% if active_page == 'dashboard' %}active{% endif %}\">\n        <span class=\"sidebar-link-icon\">🏠</span> Dashboard Executivo\n      </a>\n\n      <div class=\"sidebar-divider\"></div>\n\n      <!-- ── CADASTROS ────────────────────────── -->\n      <div class=\"sidebar-section-label\">CADASTROS</div>\n      <a href=\"{{ url_for('clientes_lista') }}\"\n         class=\"sidebar-link {% if active_page == 'clientes' %}active{% endif %}\">\n        <span class=\"sidebar-link-icon\">👤</span> Clientes\n      </a>\n      <a href=\"{{ url_for('cotas_lista') }}\"\n         class=\"sidebar-link {% if active_page == 'cotas' %}active{% endif %}\">\n        <span class=\"sidebar-link-icon\">📄</span> Todas as Cotas\n      </a>\n      <a href=\"/erp/contratos/\"\n         class=\"sidebar-link {% if active_page == 'contratos' %}active{% endif %}\">\n        <span class=\"sidebar-link-icon\">✍️</span> Contratos e Assinaturas\n      </a>\n\n      <div class=\"sidebar-divider\"></div>\n\n      <!-- ── OPERAÇÕES ────────────────────────── -->\n      <div class=\"sidebar-section-label\">OPERAÇÕES</div>\n\n      <!-- Condomínios — grupo expansível -->\n      <button class=\"sidebar-group-btn {% if cond_active %}group-open{% endif %}\"\n              id=\"group-condominios-btn\"\n              data-target=\"group-condominios-items\"\n              type=\"button\">\n        <span class=\"sidebar-link-icon\">🏛️</span>\n        <span class=\"sidebar-group-label\">Condomínios</span>\n        <span class=\"sidebar-group-arrow\">&#9660;</span>\n      </button>\n\n      <div class=\"sidebar-subitems {% if cond_active %}open{% endif %}\"\n           id=\"group-condominios-items\">\n\n        <a href=\"{{ url_for('condominio', code='civil') }}\"\n           class=\"sidebar-sublink {% if active_page == 'produto_civil' %}active{% endif %}\">\n          <span class=\"sidebar-link-icon\">🏗️</span> Construção Civil\n        </a>\n        <a href=\"{{ url_for('condominio', code='agro') }}\"\n           class=\"sidebar-sublink {% if active_page == 'produto_agro' %}active{% endif %}\">\n          <span class=\"sidebar-link-icon\">🌾</span> Agronegócio\n        </a>\n        <a href=\"{{ url_for('condominio', code='saude') }}\"\n           class=\"sidebar-sublink {% if active_page == 'produto_saude' %}active{% endif %}\">\n          <span class=\"sidebar-link-icon\">🏥</span> Saúde\n        </a>\n        <a href=\"{{ url_for('condominios_vencimentos') }}\"\n           class=\"sidebar-sublink {% if active_page == 'vencimentos' %}active{% endif %}\">\n          <span class=\"sidebar-link-icon\">⏰</span> Vencimentos e Retiradas\n        </a>\n        <a href=\"{{ url_for('apuracao') }}\"\n           class=\"sidebar-sublink {% if active_page == 'apuracao' %}active{% endif %}\">\n          <span class=\"sidebar-link-icon\">📐</span> Apuração\n        </a>\n        <a href=\"{{ url_for('historico') }}\"\n           class=\"sidebar-sublink {% if active_page == 'historico' %}active{% endif %}\">\n          <span class=\"sidebar-link-icon\">📈</span> Histórico\n        </a>\n        <a href=\"{{ url_for('condominios_validacao_sistema') }}\"\n           class=\"sidebar-sublink {% if active_page == 'validacao_sistema' %}active{% endif %}\">\n          <span class=\"sidebar-link-icon\">🧾</span> Validação Sistema\n        </a>\n\n      </div>\n\n      <!-- Títulos Privados — grupo expansível -->\n      <button class=\"sidebar-group-btn {% if titulos_active %}group-open{% endif %}\"\n              id=\"group-titulos-btn\"\n              data-target=\"group-titulos-items\"\n              type=\"button\">\n        <span class=\"sidebar-link-icon\">📜</span>\n        <span class=\"sidebar-group-label\">Títulos Privados</span>\n        <span class=\"sidebar-group-arrow\">&#9660;</span>\n      </button>\n\n      <div class=\"sidebar-subitems {% if titulos_active %}open{% endif %}\"\n           id=\"group-titulos-items\">\n\n        <a href=\"{{ url_for('titulos_privados') }}\"\n           class=\"sidebar-sublink {% if active_page == 'titulos_privados_dashboard' %}active{% endif %}\">\n          <span class=\"sidebar-link-icon\">📊</span> Dashboard\n        </a>\n        <a href=\"{{ url_for('titulos_privados_clientes') }}\"\n           class=\"sidebar-sublink {% if active_page == 'titulos_privados_clientes' %}active{% endif %}\">\n          <span class=\"sidebar-link-icon\">👤</span> Clientes de Títulos\n        </a>\n        <a href=\"{{ url_for('titulos_privados_emprestimos') }}\"\n           class=\"sidebar-sublink {% if active_page == 'titulos_privados_emprestimos' %}active{% endif %}\">\n          <span class=\"sidebar-link-icon\">💰</span> Empréstimos\n        </a>\n        <a href=\"{{ url_for('titulos_privados_parcelas') }}\"\n           class=\"sidebar-sublink {% if active_page == 'titulos_privados_parcelas' %}active{% endif %}\">\n          <span class=\"sidebar-link-icon\">🧾</span> Parcelas / Recebimentos\n        </a>\n        <a href=\"{{ url_for('titulos_privados_prorrogacoes') }}\"\n           class=\"sidebar-sublink {% if active_page == 'titulos_privados_prorrogacoes' %}active{% endif %}\">\n          <span class=\"sidebar-link-icon\">⏳</span> Prorrogações\n        </a>\n        <a href=\"{{ url_for('titulos_privados_amortizacoes') }}\"\n           class=\"sidebar-sublink {% if active_page == 'titulos_privados_amortizacoes' %}active{% endif %}\">\n          <span class=\"sidebar-link-icon\">📉</span> Amortizações\n        </a>\n        <a href=\"{{ url_for('titulos_privados_calculadora_price') }}\"\n           class=\"sidebar-sublink {% if active_page == 'titulos_privados_calculadora_price' %}active{% endif %}\">\n          <span class=\"sidebar-link-icon\">🧮</span> Calculadora Price\n        </a>\n\n      </div>\n\n      <div class=\"sidebar-divider\"></div>\n\n      <!-- ── SISTEMA ──────────────────────────── -->\n      <div class=\"sidebar-section-label\">SISTEMA</div>\n      <a href=\"{{ url_for('backup_page') }}\"\n         class=\"sidebar-link {% if active_page == 'backup' %}active{% endif %}\">\n        <span class=\"sidebar-link-icon\">💾</span> Backup\n      </a>\n      <a href=\"{{ url_for('configuracoes') }}\"\n         class=\"sidebar-link {% if active_page == 'configuracoes' %}active{% endif %}\">\n        <span class=\"sidebar-link-icon\">⚙️</span> Configurações\n      </a>\n      <a href=\"{{ url_for('auditoria') }}\"\n         class=\"sidebar-link {% if active_page == 'auditoria' %}active{% endif %}\">\n        <span class=\"sidebar-link-icon\">🔍</span> Auditoria\n      </a>\n      <a href=\"{{ url_for('exportacao_supabase') }}\"\n         class=\"sidebar-link {% if active_page == 'exportacao_supabase' %}active{% endif %}\">\n        <span class=\"sidebar-link-icon\">🛰️</span> Exportação Supabase\n      </a>\n\n    </nav>\n\n    <!-- Footer -->\n    <div class=\"sidebar-footer\">\n      <div class=\"sidebar-footer-dot\"></div>\n      <div class=\"sidebar-footer-text\">Grupo Capuzzo &copy; 2026 &middot; v2.0</div>\n    </div>\n\n  </aside>\n\n  <!-- ═══════════════════════════════════════════════\n       MAIN CONTENT\n  ═══════════════════════════════════════════════ -->\n  <main class=\"main-content\">\n    <div class=\"page-container\">\n\n      <!-- Flash messages -->\n      {% with messages = get_flashed_messages(with_categories=true) %}\n        {% if messages %}\n          {% for category, message in messages %}\n            <div class=\"alert alert-{{ category }}\">{{ message }}</div>\n          {% endfor %}\n        {% endif %}\n      {% endwith %}\n\n      {% block content %}{% endblock %}\n\n    </div>\n  </main>\n\n</div>\n\n<script src=\"{{ url_for('static', filename='app.js') }}?v=6\"></script>\n{% block scripts %}{% endblock %}\n</body>\n</html>\n",
  "clientes_detalhe.html": "{% extends \"base.html\" %}\n{% block title %}{{ cliente.full_name }} — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n\n<a href=\"{{ url_for('clientes_lista') }}\" class=\"back-link\">← Voltar para Clientes</a>\n\n<div class=\"page-header\" style=\"display:flex;justify-content:space-between;align-items:flex-start;\">\n  <div>\n    <div class=\"page-header-title\">{{ cliente.full_name }}</div>\n    <div class=\"page-header-sub\" style=\"margin-top:6px;\">\n      {% if cliente.status == 'ativo' %}\n        <span class=\"badge badge-active\">● Ativo</span>\n      {% else %}\n        <span class=\"badge badge-inactive\">● Inativo</span>\n      {% endif %}\n      &nbsp;\n      <span class=\"text-mono text-dim\">{{ cliente.cpf }}</span>\n    </div>\n  </div>\n  <div style=\"display:flex;gap:8px;flex-shrink:0;flex-wrap:wrap;justify-content:flex-end;\">\n    <a href=\"{{ url_for('clientes_editar', cid=cliente.id) }}\" class=\"btn btn-secondary\">✏️ Editar</a>\n    {% if cliente.status == 'ativo' %}\n      <form method=\"post\" action=\"{{ url_for('clientes_inativar', cid=cliente.id) }}\" style=\"display:inline;\">\n        <button type=\"submit\" class=\"btn btn-danger\"\n                data-confirm=\"Inativar o cliente {{ cliente.full_name }}?\">\n          🔒 Inativar\n        </button>\n      </form>\n    {% else %}\n      <form method=\"post\" action=\"{{ url_for('clientes_reativar', cid=cliente.id) }}\" style=\"display:inline;\">\n        <button type=\"submit\" class=\"btn btn-success\">🔓 Reativar</button>\n      </form>\n    {% endif %}\n    {% if cotas | length == 0 %}\n    <form method=\"post\" action=\"{{ url_for('clientes_excluir', cid=cliente.id) }}\" style=\"display:inline;\"\n          onsubmit=\"return confirm('Excluir o cliente {{ cliente.full_name }} permanentemente?\\nEsta ação não pode ser desfeita.');\">\n      <button type=\"submit\" class=\"btn btn-danger\">🗑️ Excluir</button>\n    </form>\n    {% endif %}\n  </div>\n</div>\n\n<!-- Dados Pessoais -->\n<div class=\"card-gold\" style=\"margin-bottom:20px;\">\n  <div class=\"form-section-title\" style=\"margin-bottom:12px;\">Dados Pessoais</div>\n  <div class=\"detail-grid\">\n    <div>\n      <div class=\"detail-item-label\">Nome Completo</div>\n      <div class=\"detail-item-value\">{{ cliente.full_name }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">CPF/CNPJ</div>\n      <div class=\"detail-item-value text-mono\">{{ cliente.cpf }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">E-mail</div>\n      <div class=\"detail-item-value\">{{ cliente.email or '—' }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Telefone</div>\n      <div class=\"detail-item-value\">{{ cliente.phone or '—' }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Status</div>\n      <div class=\"detail-item-value\">\n        {% if cliente.status == 'ativo' %}\n          <span class=\"badge badge-active\">● Ativo</span>\n        {% else %}\n          <span class=\"badge badge-inactive\">● Inativo</span>\n        {% endif %}\n      </div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Cadastrado em</div>\n      <div class=\"detail-item-value text-dim\">{{ cliente.created_at or '—' }}</div>\n    </div>\n  </div>\n  {% if cliente.notes %}\n  <div style=\"margin-top:14px;\">\n    <div class=\"detail-item-label\">Observações</div>\n    <div class=\"detail-item-value text-dim\" style=\"margin-top:4px;\">{{ cliente.notes }}</div>\n  </div>\n  {% endif %}\n</div>\n\n<!-- Dados para contrato -->\n{% set _end = [cliente.address_street, cliente.address_district,\n               ((cliente.address_city or '') ~ ('-' ~ cliente.address_state if cliente.address_state else ''))]\n              | select | join(', ') %}\n<div class=\"card-gold\" style=\"margin-bottom:20px;\" id=\"dados-contrato\">\n  <div class=\"form-section-title\" style=\"margin-bottom:12px;display:flex;justify-content:space-between;align-items:center;\">\n    <span>Dados para Contrato</span>\n    <a href=\"/erp/contratos/?q={{ cliente.cpf }}\" class=\"btn btn-secondary btn-sm\">✍️ Contratos do cliente</a>\n  </div>\n  <div class=\"detail-grid\">\n    <div><div class=\"detail-item-label\">Nacionalidade</div><div class=\"detail-item-value\">{{ cliente.nationality or '—' }}</div></div>\n    <div><div class=\"detail-item-label\">Estado Civil</div><div class=\"detail-item-value\">{{ cliente.marital_status or '—' }}</div></div>\n    <div><div class=\"detail-item-label\">Profissão</div><div class=\"detail-item-value\">{{ cliente.profession or '—' }}</div></div>\n    <div><div class=\"detail-item-label\">Endereço</div><div class=\"detail-item-value\">{{ _end or '—' }}</div></div>\n    <div><div class=\"detail-item-label\">CEP</div><div class=\"detail-item-value text-mono\">{{ cliente.address_zip or '—' }}</div></div>\n  </div>\n</div>\n\n<!-- Dados Financeiros -->\n<div class=\"card-gold\" style=\"margin-bottom:20px;\">\n  <div class=\"form-section-title\" style=\"margin-bottom:12px;\">Dados Financeiros</div>\n  <div class=\"detail-grid\">\n    <div>\n      <div class=\"detail-item-label\">Chave PIX</div>\n      <div class=\"detail-item-value text-mono\">{{ cliente.pix_key or '—' }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Banco</div>\n      <div class=\"detail-item-value\">{{ cliente.bank_name or '—' }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Agência</div>\n      <div class=\"detail-item-value\">{{ cliente.bank_agency or '—' }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Conta</div>\n      <div class=\"detail-item-value\">\n        {% if cliente.bank_account %}\n          {{ cliente.bank_account }}{% if cliente.bank_account_digit %}-{{ cliente.bank_account_digit }}{% endif %}\n        {% else %}—{% endif %}\n      </div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Tipo de Conta</div>\n      <div class=\"detail-item-value\">{{ cliente.bank_account_type or '—' }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Titular da Conta</div>\n      <div class=\"detail-item-value\">{{ cliente.bank_holder_name or '—' }}</div>\n    </div>\n    {% if cliente.bank_holder_document %}\n    <div>\n      <div class=\"detail-item-label\">CPF/CNPJ do Titular</div>\n      <div class=\"detail-item-value text-mono\">{{ cliente.bank_holder_document }}</div>\n    </div>\n    {% endif %}\n  </div>\n  {% if cliente.bank_notes %}\n  <div style=\"margin-top:12px;\">\n    <div class=\"detail-item-label\">Observações Bancárias</div>\n    <div class=\"detail-item-value text-dim\" style=\"margin-top:4px;\">{{ cliente.bank_notes }}</div>\n  </div>\n  {% endif %}\n</div>\n\n<!-- Cotas vinculadas -->\n<div class=\"section-label\">📄 &nbsp;Cotas Vinculadas ({{ cotas | length }})</div>\n\n{% if cotas %}\n<div class=\"table-wrap\">\n  <table>\n    <thead>\n      <tr>\n        <th>Nº Cota</th>\n        <th>Produto</th>\n        <th>Valor</th>\n        <th>Aquisição</th>\n        <th>Vencimento</th>\n        <th>Status</th>\n        <th style=\"text-align:right;\">Ações</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for cota in cotas %}\n      <tr>\n        <td style=\"font-size:18px;font-weight:700;color:#d4af37;\">{{ cota.share_number }}</td>\n        <td>\n          {% if cota.condominium_code == 'civil' %}\n            <span class=\"badge badge-civil\">🏗️ Civil</span>\n          {% elif cota.condominium_code == 'agro' %}\n            <span class=\"badge badge-agro\">🌾 Agro</span>\n          {% else %}\n            <span class=\"badge badge-saude\">🏥 Saúde</span>\n          {% endif %}\n        </td>\n        <td style=\"font-weight:600;\">{{ formatar_moeda(cota.share_value) }}</td>\n        <td class=\"text-dim\">{{ cota.acquisition_date or '—' }}</td>\n        <td class=\"text-dim\">{{ cota.maturity_date or '—' }}</td>\n        <td>\n          {% if cota.status == 'ativa' %}\n            <span class=\"badge badge-active\">● Ativa</span>\n          {% elif cota.status == 'pendente' %}\n            <span class=\"badge badge-pending\">● Pendente</span>\n          {% else %}\n            <span class=\"badge badge-inactive\">● Inativa</span>\n          {% endif %}\n        </td>\n        <td style=\"text-align:right;\">\n          <a href=\"{{ url_for('cotas_editar', sid=cota.id) }}\" class=\"btn btn-secondary btn-sm\">Editar</a>\n        </td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n{% else %}\n<div class=\"empty-state\">\n  <div class=\"empty-state-icon\">📄</div>\n  <div class=\"empty-state-title\">Nenhuma cota cadastrada</div>\n  <div class=\"empty-state-sub\">Este cliente ainda não possui cotas vinculadas.</div>\n</div>\n{% endif %}\n\n<div style=\"margin-top:16px;\">\n  <a href=\"{{ url_for('cotas_nova') }}\" class=\"btn btn-primary\">+ Nova Cota para este Cliente</a>\n</div>\n\n{% endblock %}\n",
  "clientes_form.html": "{% extends \"base.html\" %}\n{% block title %}{{ 'Novo Cliente' if modo == 'novo' else 'Editar Cliente' }} — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n\n<a href=\"{{ url_for('clientes_lista') }}\" class=\"back-link\">← Voltar para Clientes</a>\n\n<div class=\"page-header\">\n  <div class=\"page-header-icon\">{{ '➕' if modo == 'novo' else '✏️' }}</div>\n  <div class=\"page-header-title\">{{ 'Novo Cliente' if modo == 'novo' else 'Editar Cliente' }}</div>\n  <div class=\"page-header-sub\">\n    {{ 'Preencha os dados do novo cotista.' if modo == 'novo' else 'Atualize os dados do cotista.' }}\n  </div>\n</div>\n\n<div class=\"card-gold\">\n  <form method=\"post\">\n\n    <!-- Dados pessoais -->\n    <div class=\"form-section\">\n      <div class=\"form-section-title\">Dados Pessoais</div>\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label>Nome Completo *</label>\n          <input type=\"text\" name=\"full_name\" value=\"{{ cliente.get('full_name','') }}\"\n                 class=\"form-control\" required placeholder=\"Nome do cotista\">\n        </div>\n        <div class=\"form-group\">\n          <label>CPF/CNPJ *</label>\n          <input type=\"text\" name=\"cpf\" value=\"{{ cliente.get('cpf','') }}\"\n                 class=\"form-control\" required data-mask=\"cpfcnpj\"\n                 placeholder=\"000.000.000-00 ou 00.000.000/0000-00\">\n          <div style=\"font-size:11px;color:#666;margin-top:4px;\">CPF (11 dígitos) ou CNPJ (14 dígitos) — formatação automática</div>\n        </div>\n      </div>\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label>E-mail</label>\n          <input type=\"email\" name=\"email\" value=\"{{ cliente.get('email','') }}\"\n                 class=\"form-control\" placeholder=\"email@exemplo.com\">\n        </div>\n        <div class=\"form-group\">\n          <label>Telefone</label>\n          <input type=\"text\" name=\"phone\" value=\"{{ cliente.get('phone','') }}\"\n                 class=\"form-control\" data-mask=\"phone\"\n                 placeholder=\"(00) 00000-0000\">\n        </div>\n      </div>\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label>Status</label>\n          <select name=\"status\" class=\"form-control\" style=\"max-width:200px;\">\n            <option value=\"ativo\"   {{ 'selected' if cliente.get('status','ativo') == 'ativo' else '' }}>Ativo</option>\n            <option value=\"inativo\" {{ 'selected' if cliente.get('status') == 'inativo' else '' }}>Inativo</option>\n          </select>\n        </div>\n      </div>\n    </div>\n\n    <!-- Dados para contrato -->\n    <div class=\"form-section\" id=\"secao-contrato\">\n      <div class=\"form-section-title\">Dados para Contrato\n        <span style=\"color:#555;font-size:12px;font-weight:400;\">(usados no Termo de Aquisição e demais contratos)</span></div>\n      <div class=\"form-row\">\n        <div class=\"form-group\" style=\"max-width:220px;\">\n          <label>Nacionalidade</label>\n          <input type=\"text\" name=\"nationality\" value=\"{{ cliente.get('nationality') or 'brasileiro(a)' }}\"\n                 class=\"form-control\" placeholder=\"brasileiro(a)\">\n        </div>\n        <div class=\"form-group\" style=\"max-width:240px;\">\n          <label>Estado Civil</label>\n          <select name=\"marital_status\" class=\"form-control\">\n            <option value=\"\">—</option>\n            <option value=\"Solteiro(a)\" {{ 'selected' if cliente.get('marital_status') == 'Solteiro(a)' else '' }}>Solteiro(a)</option>\n            <option value=\"Casado(a)\" {{ 'selected' if cliente.get('marital_status') == 'Casado(a)' else '' }}>Casado(a)</option>\n            <option value=\"União estável\" {{ 'selected' if cliente.get('marital_status') == 'União estável' else '' }}>União estável</option>\n            <option value=\"Divorciado(a)\" {{ 'selected' if cliente.get('marital_status') == 'Divorciado(a)' else '' }}>Divorciado(a)</option>\n            <option value=\"Separado(a)\" {{ 'selected' if cliente.get('marital_status') == 'Separado(a)' else '' }}>Separado(a)</option>\n            <option value=\"Viúvo(a)\" {{ 'selected' if cliente.get('marital_status') == 'Viúvo(a)' else '' }}>Viúvo(a)</option>\n          </select>\n        </div>\n        <div class=\"form-group\">\n          <label>Profissão</label>\n          <input type=\"text\" name=\"profession\" value=\"{{ cliente.get('profession') or '' }}\"\n                 class=\"form-control\" placeholder=\"Ex.: Psicóloga, Engenheiro, Empresário\">\n        </div>\n      </div>\n      <div class=\"form-row\">\n        <div class=\"form-group\" style=\"max-width:170px;\">\n          <label>CEP</label>\n          <input type=\"text\" name=\"address_zip\" id=\"cli-cep\" value=\"{{ cliente.get('address_zip') or '' }}\"\n                 class=\"form-control\" placeholder=\"00000-000\" maxlength=\"9\" inputmode=\"numeric\">\n          <div id=\"cli-cep-status\" style=\"font-size:11px;color:#666;margin-top:4px;\">Preenche o endereço automaticamente</div>\n        </div>\n        <div class=\"form-group\">\n          <label>Endereço (logradouro, número e complemento)</label>\n          <input type=\"text\" name=\"address_street\" id=\"cli-rua\" value=\"{{ cliente.get('address_street') or '' }}\"\n                 class=\"form-control\" placeholder=\"Ex.: SQN 406 Bloco K Apt 208\">\n        </div>\n      </div>\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label>Bairro</label>\n          <input type=\"text\" name=\"address_district\" id=\"cli-bairro\" value=\"{{ cliente.get('address_district') or '' }}\"\n                 class=\"form-control\" placeholder=\"Ex.: Asa Norte\">\n        </div>\n        <div class=\"form-group\">\n          <label>Cidade</label>\n          <input type=\"text\" name=\"address_city\" id=\"cli-cidade\" value=\"{{ cliente.get('address_city') or '' }}\"\n                 class=\"form-control\" placeholder=\"Ex.: Brasília\">\n        </div>\n        <div class=\"form-group\" style=\"max-width:90px;\">\n          <label>UF</label>\n          <input type=\"text\" name=\"address_state\" id=\"cli-uf\" value=\"{{ cliente.get('address_state') or '' }}\"\n                 class=\"form-control\" placeholder=\"DF\" maxlength=\"2\" style=\"text-transform:uppercase;\">\n        </div>\n      </div>\n    </div>\n    <script>\n    (function(){\n      var cep = document.getElementById('cli-cep'), st = document.getElementById('cli-cep-status');\n      if(!cep) return;\n      function fmt(){ var d = cep.value.replace(/\\D/g,'').slice(0,8); cep.value = d.length > 5 ? d.slice(0,5)+'-'+d.slice(5) : d; return d; }\n      cep.addEventListener('input', fmt);\n      cep.addEventListener('blur', function(){\n        var d = fmt(); if(d.length !== 8) return;\n        st.textContent = 'Buscando endereço…';\n        fetch('https://viacep.com.br/ws/'+d+'/json/').then(function(r){ return r.json(); }).then(function(j){\n          if(j.erro){ st.textContent = 'CEP não encontrado — preencha manualmente.'; return; }\n          var rua = document.getElementById('cli-rua');\n          if(!rua.value && j.logradouro) rua.value = j.logradouro + (j.complemento ? ' ' + j.complemento : '');\n          document.getElementById('cli-bairro').value = j.bairro || document.getElementById('cli-bairro').value;\n          document.getElementById('cli-cidade').value = j.localidade || '';\n          document.getElementById('cli-uf').value = j.uf || '';\n          st.textContent = 'Endereço preenchido — confira número e complemento.';\n        }).catch(function(){ st.textContent = 'Sem conexão com o ViaCEP — preencha manualmente.'; });\n      });\n    })();\n    </script>\n\n    <!-- Dados Financeiros / Pix -->\n    <div class=\"form-section\">\n      <div class=\"form-section-title\">Dados Financeiros</div>\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label>Chave PIX</label>\n          <input type=\"text\" name=\"pix_key\" value=\"{{ cliente.get('pix_key','') }}\"\n                 class=\"form-control\" placeholder=\"CPF, e-mail ou chave aleatória\">\n        </div>\n      </div>\n    </div>\n\n    <!-- Dados Bancários -->\n    <div class=\"form-section\">\n      <div class=\"form-section-title\">Dados Bancários <span style=\"color:#555;font-size:12px;font-weight:400;\">(opcional — para clientes sem Pix)</span></div>\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label>Banco</label>\n          <input type=\"text\" name=\"bank_name\" value=\"{{ cliente.get('bank_name','') }}\"\n                 class=\"form-control\" placeholder=\"Ex: Bradesco, Itaú, Caixa\">\n        </div>\n        <div class=\"form-group\" style=\"max-width:160px;\">\n          <label>Agência</label>\n          <input type=\"text\" name=\"bank_agency\" value=\"{{ cliente.get('bank_agency','') }}\"\n                 class=\"form-control\" placeholder=\"0000\">\n        </div>\n        <div class=\"form-group\" style=\"max-width:200px;\">\n          <label>Conta</label>\n          <input type=\"text\" name=\"bank_account\" value=\"{{ cliente.get('bank_account','') }}\"\n                 class=\"form-control\" placeholder=\"00000\">\n        </div>\n        <div class=\"form-group\" style=\"max-width:100px;\">\n          <label>Dígito</label>\n          <input type=\"text\" name=\"bank_account_digit\" value=\"{{ cliente.get('bank_account_digit','') }}\"\n                 class=\"form-control\" placeholder=\"0\" maxlength=\"2\">\n        </div>\n        <div class=\"form-group\" style=\"max-width:180px;\">\n          <label>Tipo de Conta</label>\n          <select name=\"bank_account_type\" class=\"form-control\">\n            <option value=\"\">—</option>\n            <option value=\"Corrente\"  {{ 'selected' if cliente.get('bank_account_type') == 'Corrente'  else '' }}>Corrente</option>\n            <option value=\"Poupança\"  {{ 'selected' if cliente.get('bank_account_type') == 'Poupança'  else '' }}>Poupança</option>\n          </select>\n        </div>\n      </div>\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label>Titular da Conta</label>\n          <input type=\"text\" name=\"bank_holder_name\" value=\"{{ cliente.get('bank_holder_name','') }}\"\n                 class=\"form-control\" placeholder=\"Nome do titular (se diferente do cliente)\">\n        </div>\n        <div class=\"form-group\">\n          <label>CPF/CNPJ do Titular <span style=\"color:#555;font-size:12px;\">(se diferente)</span></label>\n          <input type=\"text\" name=\"bank_holder_document\" value=\"{{ cliente.get('bank_holder_document','') }}\"\n                 class=\"form-control\" data-mask=\"cpfcnpj\"\n                 placeholder=\"CPF ou CNPJ do titular\">\n        </div>\n      </div>\n      <div class=\"form-group\">\n        <label>Observações Bancárias</label>\n        <input type=\"text\" name=\"bank_notes\" value=\"{{ cliente.get('bank_notes','') }}\"\n               class=\"form-control\" placeholder=\"Informações adicionais sobre pagamento\">\n      </div>\n    </div>\n\n    <!-- Observações -->\n    <div class=\"form-section\">\n      <div class=\"form-section-title\">Observações</div>\n      <div class=\"form-group\">\n        <textarea name=\"notes\" class=\"form-control\" rows=\"3\"\n                  placeholder=\"Anotações internas (opcional)\">{{ cliente.get('notes','') }}</textarea>\n      </div>\n    </div>\n\n    <div class=\"page-actions\">\n      <a href=\"{{ url_for('clientes_lista') }}\" class=\"btn btn-secondary\">Cancelar</a>\n      <button type=\"submit\" class=\"btn btn-primary\">\n        {{ '✓ Cadastrar Cliente' if modo == 'novo' else '✓ Salvar Alterações' }}\n      </button>\n    </div>\n\n  </form>\n</div>\n\n{% endblock %}\n",
  "clientes_importar.html": "{% extends \"base.html\" %}\n{% block title %}Importar Clientes — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n\n<div class=\"page-header\">\n  <div class=\"page-header-icon\">📥</div>\n  <div class=\"page-header-title\">Importar Clientes</div>\n  <div class=\"page-header-sub\">Cadastro em lote via planilha Excel — Grupo Capuzzo</div>\n</div>\n\n<!-- Toolbar de navegação -->\n<div style=\"display:flex;gap:10px;margin-bottom:24px;\">\n  <a href=\"{{ url_for('clientes_lista') }}\" class=\"btn btn-secondary btn-sm\">← Voltar para Clientes</a>\n  <a href=\"{{ url_for('clientes_modelo_importacao') }}\" class=\"btn btn-secondary btn-sm\">⬇ Baixar Modelo da Planilha</a>\n</div>\n\n{% if not importado %}\n<!-- ════════════════════════════════════════════\n     TELA DE UPLOAD\n════════════════════════════════════════════ -->\n\n<!-- Instruções -->\n<div class=\"card\" style=\"margin-bottom:24px;\">\n  <div class=\"card-header\">📋 Instruções de Importação</div>\n  <div class=\"card-body\" style=\"font-size:14px;line-height:1.8;color:#ccc;\">\n    <ul style=\"margin:0;padding-left:20px;\">\n      <li><strong>Nome Completo</strong> é obrigatório — linhas sem nome serão ignoradas.</li>\n      <li><strong>Status</strong> vazio será considerado <em>ativo</em> automaticamente.</li>\n      <li><strong>CPF/CNPJ</strong> não precisa ter máscara (pode enviar só os dígitos).</li>\n      <li>Se o <strong>CPF/CNPJ já existir</strong> no sistema, o cliente não será duplicado.</li>\n      <li><strong>Dados bancários</strong> são todos opcionais.</li>\n      <li>Use o modelo oficial para garantir que as colunas sejam reconhecidas.</li>\n      <li>Apenas arquivos <strong>.xlsx</strong> são aceitos.</li>\n    </ul>\n  </div>\n</div>\n\n<!-- Colunas do modelo -->\n<div class=\"card\" style=\"margin-bottom:24px;\">\n  <div class=\"card-header\">📊 Colunas do Modelo</div>\n  <div class=\"card-body\">\n    <div style=\"display:flex;flex-wrap:wrap;gap:8px;\">\n      {% for col in [\"Nome Completo\",\"CPF/CNPJ\",\"Email\",\"Telefone\",\"Chave Pix\",\"Status\",\"Observações\",\n                     \"Banco\",\"Agência\",\"Conta\",\"Dígito da Conta\",\"Tipo de Conta\",\n                     \"Titular da Conta\",\"CPF/CNPJ do Titular\",\"Observações Bancárias\"] %}\n      <span style=\"background:#1a1a2e;border:1px solid #333;border-radius:4px;\n                   padding:4px 10px;font-size:12px;color:#ccc;\">{{ col }}</span>\n      {% endfor %}\n    </div>\n  </div>\n</div>\n\n<!-- Formulário de upload -->\n<div class=\"card\">\n  <div class=\"card-header\">📤 Enviar Planilha</div>\n  <div class=\"card-body\">\n    <form method=\"post\" enctype=\"multipart/form-data\"\n          onsubmit=\"document.getElementById('btn-importar').disabled=true;\n                    document.getElementById('btn-importar').textContent='Importando...';\">\n      <div class=\"form-group\" style=\"margin-bottom:20px;\">\n        <label class=\"form-label\">Selecione o arquivo .xlsx</label>\n        <input type=\"file\" name=\"arquivo\" accept=\".xlsx\"\n               class=\"form-control\" required\n               style=\"background:#1a1a2e;border:1px solid #333;color:#F5F5F5;\n                      padding:10px;border-radius:6px;\">\n      </div>\n      <div style=\"display:flex;gap:12px;align-items:center;\">\n        <button type=\"submit\" id=\"btn-importar\" class=\"btn btn-primary\">\n          📥 Importar Clientes\n        </button>\n        <a href=\"{{ url_for('clientes_modelo_importacao') }}\" class=\"btn btn-secondary\">\n          ⬇ Baixar Modelo\n        </a>\n      </div>\n    </form>\n  </div>\n</div>\n\n{% else %}\n<!-- ════════════════════════════════════════════\n     RESULTADO DA IMPORTAÇÃO\n════════════════════════════════════════════ -->\n\n<!-- Cards de resumo -->\n<div class=\"metrics-grid\" style=\"grid-template-columns:repeat(4,1fr);margin-bottom:24px;\">\n  <div class=\"metric-card\">\n    <div class=\"metric-value\">{{ total }}</div>\n    <div class=\"metric-label\">Linhas Lidas</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#4ade80;\">{{ criados }}</div>\n    <div class=\"metric-label\">Criados</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#facc15;\">{{ ignorados }}</div>\n    <div class=\"metric-label\">Ignorados</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#f87171;\">{{ erros }}</div>\n    <div class=\"metric-label\">Erros</div>\n  </div>\n</div>\n\n<!-- Tabela de resultados -->\n<div class=\"card\">\n  <div class=\"card-header\">📋 Detalhamento por Linha</div>\n  <div class=\"card-body\" style=\"padding:0;\">\n    <div class=\"table-wrap\" style=\"margin:0;\">\n      <table>\n        <thead>\n          <tr>\n            <th style=\"width:60px;text-align:center;\">Linha</th>\n            <th>Nome</th>\n            <th>CPF/CNPJ</th>\n            <th style=\"width:110px;text-align:center;\">Resultado</th>\n            <th>Mensagem</th>\n          </tr>\n        </thead>\n        <tbody>\n          {% for r in resultados %}\n          <tr>\n            <td style=\"text-align:center;color:#888;\">{{ r.linha }}</td>\n            <td>{{ r.nome }}</td>\n            <td class=\"text-mono text-dim\">{{ r.cpf_cnpj or '—' }}</td>\n            <td style=\"text-align:center;\">\n              {% if r.resultado == 'Criado' %}\n                <span class=\"badge badge-active\">✓ Criado</span>\n              {% elif r.resultado == 'Ignorado' %}\n                <span class=\"badge\" style=\"background:#2a2a00;color:#facc15;border:1px solid #555;\">\n                  ⚠ Ignorado\n                </span>\n              {% else %}\n                <span class=\"badge badge-inactive\">✗ Erro</span>\n              {% endif %}\n            </td>\n            <td style=\"font-size:13px;color:#aaa;\">{{ r.mensagem }}</td>\n          </tr>\n          {% endfor %}\n        </tbody>\n      </table>\n    </div>\n  </div>\n</div>\n\n<!-- Ações pós-importação -->\n<div style=\"display:flex;gap:12px;margin-top:20px;\">\n  <a href=\"{{ url_for('clientes_lista') }}\" class=\"btn btn-primary\">Ver Lista de Clientes</a>\n  <a href=\"{{ url_for('clientes_importar') }}\" class=\"btn btn-secondary\">Nova Importação</a>\n  <a href=\"{{ url_for('clientes_modelo_importacao') }}\" class=\"btn btn-secondary\">⬇ Baixar Modelo</a>\n</div>\n\n{% endif %}\n\n{% endblock %}\n",
  "clientes_lista.html": "{% extends \"base.html\" %}\n{% block title %}Clientes — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n\n<div class=\"page-header\">\n  <div class=\"page-header-icon\">👤</div>\n  <div class=\"page-header-title\">Clientes</div>\n  <div class=\"page-header-sub\">Gestão de cotistas — Grupo Capuzzo</div>\n</div>\n\n<!-- KPIs -->\n<div class=\"metrics-grid\" style=\"grid-template-columns: repeat(4,1fr);\">\n  <div class=\"metric-card\">\n    <div class=\"metric-value\">{{ resumo.total }}</div>\n    <div class=\"metric-label\">Total de Clientes</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#4ade80;\">{{ resumo.ativos }}</div>\n    <div class=\"metric-label\">Ativos</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#555;\">{{ resumo.inativos }}</div>\n    <div class=\"metric-label\">Inativos</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\">{{ resumo.com_cotas }}</div>\n    <div class=\"metric-label\">Com Cotas</div>\n  </div>\n</div>\n\n<!-- Toolbar -->\n<form method=\"get\" class=\"toolbar\">\n  <div class=\"toolbar-left\">\n    <div class=\"search-wrap\">\n      <input type=\"text\" name=\"q\" value=\"{{ q }}\"\n             placeholder=\"Buscar por nome ou CPF/CNPJ…\"\n             class=\"form-control\" style=\"width:260px;\">\n    </div>\n    <select name=\"status\" class=\"form-control form-control-sm\" style=\"width:160px;\">\n      <option value=\"\">Todos os status</option>\n      <option value=\"ativo\"   {% if status_filtro == 'ativo' %}selected{% endif %}>Ativos</option>\n      <option value=\"inativo\" {% if status_filtro == 'inativo' %}selected{% endif %}>Inativos</option>\n    </select>\n    <button type=\"submit\" class=\"btn btn-secondary btn-sm\">Filtrar</button>\n    {% if q or status_filtro %}\n      <a href=\"{{ url_for('clientes_lista') }}\" class=\"btn btn-secondary btn-sm\">Limpar</a>\n    {% endif %}\n  </div>\n  <div class=\"toolbar-right\" style=\"gap:8px;\">\n    <a href=\"{{ url_for('clientes_novo') }}\" class=\"btn btn-primary\">\n      + Novo Cliente\n    </a>\n    <a href=\"{{ url_for('clientes_importar') }}\" class=\"btn btn-secondary\">\n      📥 Importar Clientes\n    </a>\n    <a href=\"{{ url_for('clientes_modelo_importacao') }}\" class=\"btn btn-secondary\">\n      ⬇ Baixar Modelo\n    </a>\n  </div>\n</form>\n\n<!-- Tabela -->\n{% if clientes %}\n<div class=\"table-wrap\">\n  <table>\n    <thead>\n      <tr>\n        <th>Nome</th>\n        <th>CPF/CNPJ</th>\n        <th>E-mail</th>\n        <th>Telefone</th>\n        <th>Chave PIX</th>\n        <th>Status</th>\n        <th style=\"text-align:right;\">Ações</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for c in clientes %}\n      <tr>\n        <td>\n          <a href=\"{{ url_for('clientes_detalhe', cid=c.id) }}\"\n             style=\"color:#F5F5F5;font-weight:500;\">{{ c.full_name }}</a>\n        </td>\n        <td class=\"text-mono text-dim\">{{ c.cpf }}</td>\n        <td class=\"text-dim\">{{ c.email or '—' }}</td>\n        <td class=\"text-dim\">{{ c.phone or '—' }}</td>\n        <td class=\"text-dim\">{{ c.pix_key or '—' }}</td>\n        <td>\n          {% if c.status == 'ativo' %}\n            <span class=\"badge badge-active\">● Ativo</span>\n          {% else %}\n            <span class=\"badge badge-inactive\">● Inativo</span>\n          {% endif %}\n        </td>\n        <td style=\"text-align:right;white-space:nowrap;\">\n          <a href=\"{{ url_for('clientes_detalhe', cid=c.id) }}\"\n             class=\"btn btn-secondary btn-sm\">Ver</a>\n          <a href=\"{{ url_for('clientes_editar', cid=c.id) }}\"\n             class=\"btn btn-secondary btn-sm\">Editar</a>\n          <form method=\"post\" action=\"{{ url_for('clientes_excluir', cid=c.id) }}\"\n                style=\"display:inline;\"\n                onsubmit=\"return confirm('Excluir o cliente {{ c.full_name }}?\\nEsta ação é permanente e só é possível se o cliente não tiver cotas.');\">\n            <button type=\"submit\" class=\"btn btn-danger btn-sm\">Excluir</button>\n          </form>\n        </td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n<div class=\"text-dim\" style=\"font-size:12px;margin-top:10px;text-align:right;\">\n  {{ clientes | length }} cliente(s) encontrado(s)\n</div>\n{% else %}\n<div class=\"empty-state\">\n  <div class=\"empty-state-icon\">👤</div>\n  <div class=\"empty-state-title\">Nenhum cliente encontrado</div>\n  <div class=\"empty-state-sub\">\n    {% if q or status_filtro %}\n      Tente ajustar os filtros de busca.\n    {% else %}\n      Cadastre o primeiro cliente para começar.\n    {% endif %}\n  </div>\n</div>\n{% endif %}\n\n{% endblock %}\n",
  "condominio.html": "{% extends \"base.html\" %}\n{% block title %}{{ cond.name }} — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n\n<a href=\"{{ url_for('dashboard') }}\" class=\"back-link\">← Voltar para Dashboard</a>\n\n<!-- Hero do Produto -->\n<div class=\"cond-hero\">\n  <div class=\"cond-hero-header\">\n    <div>\n      <div style=\"font-size:11px;color:#555;font-weight:600;text-transform:uppercase;letter-spacing:1px;margin-bottom:4px;\">\n        Condomínio de Investimento · {{ cond.code.upper() }}\n      </div>\n      <div class=\"cond-hero-title\">\n        {% if cond.code == 'civil' %}🏗️\n        {% elif cond.code == 'agro' %}🌾\n        {% else %}🏥\n        {% endif %}\n        &nbsp;{{ cond.name }}\n      </div>\n    </div>\n    <div class=\"cond-hero-actions\">\n      <a href=\"{{ url_for('cotas_nova', produto=cond.code) }}\" class=\"btn btn-primary\">\n        + Nova Cota\n      </a>\n      <a href=\"{{ url_for('apuracao', produto=cond.code) }}\" class=\"btn btn-secondary\">\n        📐 Cálculo do Mês\n      </a>\n    </div>\n  </div>\n\n  <div class=\"cond-stats\">\n    <div class=\"cond-stat\">\n      <div class=\"cond-stat-value text-gold\">{{ formatar_moeda(valor_total) }}</div>\n      <div class=\"cond-stat-label\">Patrimônio Ativo</div>\n    </div>\n    <div class=\"cond-stat\">\n      <div class=\"cond-stat-value\" style=\"color:#4ade80;\">{{ ativas | length }}</div>\n      <div class=\"cond-stat-label\">Cotas Ativas</div>\n    </div>\n    <div class=\"cond-stat\">\n      <div class=\"cond-stat-value\" style=\"color:#fbbf24;\">{{ pendentes | length }}</div>\n      <div class=\"cond-stat-label\">Pendentes</div>\n    </div>\n    <div class=\"cond-stat\">\n      <div class=\"cond-stat-value\" style=\"color:#6b7280;\">{{ inativas | length }}</div>\n      <div class=\"cond-stat-label\">Inativas</div>\n    </div>\n    <div class=\"cond-stat\">\n      <div class=\"cond-stat-value\" style=\"color:#60a5fa;\">{{ clientes_ativos }}</div>\n      <div class=\"cond-stat-label\">Clientes Ativos</div>\n    </div>\n    <div class=\"cond-stat\">\n      <div class=\"cond-stat-value\">{{ formatar_percentual(cond.default_monthly_rate) }}</div>\n      <div class=\"cond-stat-label\">Taxa Mensal</div>\n    </div>\n  </div>\n\n  {% if cond.code == 'agro' %}\n  <div class=\"note-box\" style=\"margin-top:14px;\">\n    <span style=\"color:#fbbf24;font-weight:600;\">⚠️ Taxa especial no vencimento: </span>\n    <span>3,5% a 4,5% — verificar a cada operação</span>\n  </div>\n  {% endif %}\n</div>\n\n{% if cotas %}\n<!-- Barra de Busca e Filtros -->\n<div style=\"background:#111;border:1px solid #222;border-radius:8px;padding:14px 16px;margin-bottom:18px;display:flex;flex-direction:column;gap:10px;\">\n  <div style=\"display:flex;align-items:center;gap:12px;flex-wrap:wrap;\">\n    <div style=\"flex:1;min-width:220px;position:relative;\">\n      <span style=\"position:absolute;left:10px;top:50%;transform:translateY(-50%);color:#555;pointer-events:none;\">🔍</span>\n      <input type=\"text\" id=\"cond-search\"\n             placeholder=\"Buscar por cliente, CPF/CNPJ, Pix ou número da cota…\"\n             style=\"width:100%;padding:8px 12px 8px 32px;background:#1a1a1a;color:#F5F5F5;\n                    border:1px solid #333;border-radius:6px;font-size:13px;box-sizing:border-box;outline:none;\"\n             onfocus=\"this.style.borderColor='#d4af37'\" onblur=\"this.style.borderColor='#333'\">\n    </div>\n    <div style=\"display:flex;gap:6px;flex-shrink:0;\">\n      <button class=\"filter-btn active\" data-filter-status=\"todos\"\n              style=\"padding:7px 14px;font-size:12px;font-weight:600;border:1px solid #333;\n                     border-radius:5px;cursor:pointer;background:#1e1e1e;color:#aaa;transition:all .15s;\">\n        Todos\n      </button>\n      <button class=\"filter-btn\" data-filter-status=\"ativa\"\n              style=\"padding:7px 14px;font-size:12px;font-weight:600;border:1px solid #333;\n                     border-radius:5px;cursor:pointer;background:#1e1e1e;color:#4ade80;transition:all .15s;\">\n        Ativas\n      </button>\n      <button class=\"filter-btn\" data-filter-status=\"pendente\"\n              style=\"padding:7px 14px;font-size:12px;font-weight:600;border:1px solid #333;\n                     border-radius:5px;cursor:pointer;background:#1e1e1e;color:#fbbf24;transition:all .15s;\">\n        Pendentes\n      </button>\n      <button class=\"filter-btn\" data-filter-status=\"inativa\"\n              style=\"padding:7px 14px;font-size:12px;font-weight:600;border:1px solid #333;\n                     border-radius:5px;cursor:pointer;background:#1e1e1e;color:#6b7280;transition:all .15s;\">\n        Inativas\n      </button>\n    </div>\n  </div>\n  <div id=\"cond-filter-counter\" style=\"font-size:12px;color:#555;padding-left:2px;\">\n    Exibindo todas as {{ cotas | length }} cotas\n  </div>\n</div>\n\n<!-- Barra de seleção em lote -->\n<div class=\"bulk-toolbar\" id=\"cond-bulk-toolbar\">\n  <label class=\"bulk-toolbar-select-all\">\n    <input type=\"checkbox\" id=\"cond-select-all-visiveis\">\n    Selecionar todas as cotas exibidas\n  </label>\n  <div class=\"bulk-toolbar-count\" id=\"bulk-selected-count\">0 cota(s) selecionada(s)</div>\n  <div class=\"bulk-toolbar-actions\">\n    <button type=\"button\" class=\"btn btn-secondary btn-sm\" id=\"btn-limpar-selecao\">\n      Limpar seleção\n    </button>\n    <button type=\"button\" class=\"btn btn-primary btn-sm\" id=\"btn-editar-lote\" disabled>\n      ✏️ Editar selecionadas em lote\n    </button>\n  </div>\n</div>\n\n<!-- Form usado só para levar as cotas selecionadas ao grid de edição em lote -->\n<form method=\"post\" action=\"{{ url_for('cotas_editar_lote') }}\" id=\"form-cond-editar-lote\"\n      style=\"display:none;\">\n  <input type=\"hidden\" name=\"referrer\" value=\"{{ request.url }}\">\n  <div id=\"cond-lote-share-ids\"></div>\n</form>\n{% endif %}\n\n<style>\n.filter-btn.active { background:#d4af37!important;color:#000!important;border-color:#d4af37!important; }\n.filter-btn:hover:not(.active) { border-color:#555!important; }\n</style>\n\n<!-- Cotas Ativas -->\n<div class=\"cond-section-wrap\" id=\"section-ativas\">\n{% if ativas %}\n<div class=\"section-label\">● Cotas Ativas ({{ ativas | length }})</div>\n<div class=\"table-wrap\" style=\"margin-bottom:20px;\">\n  <table>\n    <thead>\n      <tr>\n        <th style=\"width:30px;\">\n          <input type=\"checkbox\" class=\"cond-select-all-table\" title=\"Selecionar as ativas exibidas\">\n        </th>\n        <th>Nº</th>\n        <th>Cotista</th>\n        <th>CPF</th>\n        <th>Valor</th>\n        <th>Aquisição</th>\n        <th>Vencimento</th>\n        <th style=\"text-align:right;\">Ações</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for cota in ativas %}\n      <tr data-status=\"ativa\"\n          data-share-number=\"{{ cota.share_number | lower }}\"\n          data-client-name=\"{{ cota.client_name | lower }}\"\n          data-client-document=\"{{ cota.client_cpf | lower }}\"\n          data-pix=\"{{ (cota.client_pix or '') | lower }}\">\n        <td>\n          <input type=\"checkbox\" class=\"row-select\" data-share-id=\"{{ cota.id }}\"\n                 title=\"Selecionar cota {{ cota.share_number }}\">\n        </td>\n        <td style=\"font-size:20px;font-weight:700;color:#d4af37;\">\n          {{ cota.share_number }}\n          {% if cota.withdrawal_requested %}\n            <span class=\"badge badge-retirada\" style=\"font-size:10px;vertical-align:middle;\"\n                  title=\"Retirada efetiva em {{ cota.withdrawal_effective_date or '—' }}\">📤 Em retirada</span>\n          {% endif %}\n        </td>\n        <td>\n          <a href=\"{{ url_for('clientes_detalhe', cid=cota.client_id) }}\"\n             style=\"color:#F5F5F5;font-weight:500;\">{{ cota.client_name }}</a>\n        </td>\n        <td class=\"text-mono text-dim\">{{ cota.client_cpf }}</td>\n        <td style=\"font-weight:600;\">{{ formatar_moeda(cota.share_value) }}</td>\n        <td class=\"text-dim\">{{ cota.acquisition_date or '—' }}</td>\n        <td class=\"text-dim\">{{ cota.maturity_date or '—' }}</td>\n        <td style=\"text-align:right;white-space:nowrap;\">\n          <a href=\"{{ url_for('cotas_editar', sid=cota.id) }}\" class=\"btn btn-secondary btn-sm\">Editar</a>\n          <button type=\"button\" class=\"btn btn-danger btn-sm\"\n                  onclick=\"openInativarModal(this)\"\n                  data-share-id=\"{{ cota.id }}\"\n                  data-share-num=\"{{ cota.share_number | e }}\"\n                  data-client-name=\"{{ cota.client_name | e }}\"\n                  data-share-value=\"{{ cota.share_value }}\"\n                  data-acquisition-date=\"{{ cota.acquisition_date or '' }}\">\n            Inativar\n          </button>\n          <button type=\"button\" class=\"btn btn-delete btn-sm\"\n                  onclick=\"openDeleteModal({{ cota.id }}, '{{ cota.share_number }}')\">\n            Excluir\n          </button>\n        </td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n{% endif %}\n</div>\n\n<!-- Cotas Pendentes -->\n<div class=\"cond-section-wrap\" id=\"section-pendentes\">\n{% if pendentes %}\n<div class=\"section-label\" style=\"color:#fbbf24;\">⏳ Pendentes ({{ pendentes | length }})</div>\n<div class=\"table-wrap\" style=\"margin-bottom:20px;\">\n  <table>\n    <thead>\n      <tr>\n        <th style=\"width:30px;\">\n          <input type=\"checkbox\" class=\"cond-select-all-table\" title=\"Selecionar as pendentes exibidas\">\n        </th>\n        <th>Nº</th>\n        <th>Cotista</th>\n        <th>Valor</th>\n        <th>Aquisição</th>\n        <th style=\"text-align:right;\">Ações</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for cota in pendentes %}\n      <tr data-status=\"pendente\"\n          data-share-number=\"{{ cota.share_number | lower }}\"\n          data-client-name=\"{{ cota.client_name | lower }}\"\n          data-client-document=\"{{ cota.client_cpf | lower }}\"\n          data-pix=\"{{ (cota.client_pix or '') | lower }}\">\n        <td>\n          <input type=\"checkbox\" class=\"row-select\" data-share-id=\"{{ cota.id }}\"\n                 title=\"Selecionar cota {{ cota.share_number }}\">\n        </td>\n        <td style=\"font-size:18px;font-weight:700;color:#fbbf24;\">{{ cota.share_number }}</td>\n        <td>\n          <a href=\"{{ url_for('clientes_detalhe', cid=cota.client_id) }}\"\n             style=\"color:#F5F5F5;\">{{ cota.client_name }}</a>\n        </td>\n        <td style=\"font-weight:600;\">{{ formatar_moeda(cota.share_value) }}</td>\n        <td class=\"text-dim\">{{ cota.acquisition_date or '—' }}</td>\n        <td style=\"text-align:right;white-space:nowrap;\">\n          <a href=\"{{ url_for('cotas_editar', sid=cota.id) }}\" class=\"btn btn-secondary btn-sm\">Editar</a>\n          <form method=\"post\" action=\"{{ url_for('cotas_reativar', sid=cota.id) }}\" style=\"display:inline;\">\n            <input type=\"hidden\" name=\"referrer\" value=\"{{ request.url }}\">\n            <button type=\"submit\" class=\"btn btn-success btn-sm\">Ativar</button>\n          </form>\n          <button type=\"button\" class=\"btn btn-delete btn-sm\"\n                  onclick=\"openDeleteModal({{ cota.id }}, '{{ cota.share_number }}')\">\n            Excluir\n          </button>\n        </td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n{% endif %}\n</div>\n\n<!-- Cotas Inativas -->\n<div class=\"cond-section-wrap\" id=\"section-inativas\">\n{% if inativas %}\n<details>\n  <summary style=\"cursor:pointer;color:#555;font-size:13px;margin-bottom:12px;user-select:none;\">\n    🔒 Inativas ({{ inativas | length }}) — clique para expandir\n  </summary>\n  <div class=\"table-wrap\" style=\"margin-top:10px;\">\n    <table>\n      <thead>\n        <tr>\n          <th style=\"width:30px;\">\n            <input type=\"checkbox\" class=\"cond-select-all-table\" title=\"Selecionar as inativas exibidas\">\n          </th>\n          <th>Nº</th>\n          <th>Cotista</th>\n          <th>Valor</th>\n          <th>Retirada</th>\n          <th style=\"text-align:right;\">Ações</th>\n        </tr>\n      </thead>\n      <tbody>\n        {% for cota in inativas %}\n        <tr style=\"opacity:0.6;\"\n            data-status=\"inativa\"\n            data-share-number=\"{{ cota.share_number | lower }}\"\n            data-client-name=\"{{ cota.client_name | lower }}\"\n            data-client-document=\"{{ cota.client_cpf | lower }}\"\n            data-pix=\"{{ (cota.client_pix or '') | lower }}\">\n          <td>\n            <input type=\"checkbox\" class=\"row-select\" data-share-id=\"{{ cota.id }}\"\n                   title=\"Selecionar cota {{ cota.share_number }}\">\n          </td>\n          <td style=\"font-size:16px;font-weight:600;color:#555;\">{{ cota.share_number }}</td>\n          <td class=\"text-dim\">{{ cota.client_name }}</td>\n          <td>{{ formatar_moeda(cota.share_value) }}</td>\n          <td class=\"text-dim\">{{ cota.withdrawal_date or '—' }}</td>\n          <td style=\"text-align:right;white-space:nowrap;\">\n            <a href=\"{{ url_for('cotas_editar', sid=cota.id) }}\" class=\"btn btn-secondary btn-sm\">Editar</a>\n            <form method=\"post\" action=\"{{ url_for('cotas_reativar', sid=cota.id) }}\" style=\"display:inline;\">\n              <input type=\"hidden\" name=\"referrer\" value=\"{{ request.url }}\">\n              <button type=\"submit\" class=\"btn btn-secondary btn-sm\">Reativar</button>\n            </form>\n            <button type=\"button\" class=\"btn btn-delete btn-sm\"\n                    onclick=\"openDeleteModal({{ cota.id }}, '{{ cota.share_number }}')\">\n              Excluir\n            </button>\n          </td>\n        </tr>\n        {% endfor %}\n      </tbody>\n    </table>\n  </div>\n</details>\n{% endif %}\n</div>\n\n{% if not cotas %}\n<div class=\"empty-state\">\n  <div class=\"empty-state-icon\">📄</div>\n  <div class=\"empty-state-title\">Nenhuma cota cadastrada</div>\n  <div class=\"empty-state-sub\">Cadastre a primeira cota para este produto.</div>\n</div>\n{% endif %}\n\n<!-- Modal: Inativar Cota -->\n<div class=\"modal-overlay\" id=\"modal-inativar-cota\" style=\"display:none;\">\n  <div class=\"modal\">\n    <div class=\"modal-title\" style=\"color:#fbbf24;\">⏸️ Inativar Cota</div>\n    <div style=\"margin-bottom:16px;\">\n      <table style=\"width:100%;border-collapse:collapse;font-size:13px;line-height:1.8;\">\n        <tr>\n          <td style=\"color:#888;width:110px;\">Cota nº</td>\n          <td style=\"color:#d4af37;font-weight:700;font-size:16px;\" id=\"modal-inativar-share-num\"></td>\n        </tr>\n        <tr>\n          <td style=\"color:#888;\">Cliente</td>\n          <td style=\"color:#ccc;\" id=\"modal-inativar-client\"></td>\n        </tr>\n        <tr>\n          <td style=\"color:#888;\">Valor</td>\n          <td style=\"color:#ccc;\" id=\"modal-inativar-value\"></td>\n        </tr>\n        <tr>\n          <td style=\"color:#888;\">Aquisição</td>\n          <td style=\"color:#ccc;\" id=\"modal-inativar-acq\"></td>\n        </tr>\n      </table>\n    </div>\n    <form id=\"modal-inativar-form\" method=\"post\" action=\"\">\n      <input type=\"hidden\" name=\"referrer\" id=\"modal-inativar-referrer\" value=\"\">\n      <div class=\"form-group\" style=\"margin-bottom:14px;\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">\n          Data de retirada <span style=\"color:#f87171;\">*</span>\n        </label>\n        <input type=\"date\" name=\"withdrawal_date\" id=\"modal-inativar-withdrawal-date\"\n               class=\"form-control\" required>\n      </div>\n      <div class=\"form-group\" style=\"margin-bottom:20px;\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">\n          Observação <span style=\"color:#666;\">(opcional)</span>\n        </label>\n        <input type=\"text\" name=\"user_note\" id=\"modal-inativar-user-note\"\n               class=\"form-control\" placeholder=\"Motivo da inativação…\" maxlength=\"200\">\n      </div>\n      <div style=\"margin-bottom:20px;padding:12px 14px;border:1px solid #6b4f12;\n                  border-radius:6px;background:rgba(251,191,36,0.07);\">\n        <label style=\"display:flex;align-items:flex-start;gap:10px;cursor:pointer;margin:0;\">\n          <input type=\"checkbox\" name=\"accrual_until_withdrawal\"\n                 id=\"modal-inativar-prop\" value=\"on\"\n                 style=\"margin-top:3px;flex:0 0 auto;\">\n          <span style=\"color:#ccc;font-size:13px;line-height:1.5;\">\n            <strong style=\"color:#fbbf24;\">Retirada fora do período — considerar proporcional até a retirada</strong><br>\n            <small style=\"color:#999;\">\n              Marque <u>somente</u> quando a retirada ocorreu dentro da janela de apuração.\n              A cota continua entrando na apuração e rende proporcionalmente de\n              <em>até o dia anterior</em> à data de retirada (o dia da retirada não rende).<br>\n              <strong style=\"color:#888;\">Desmarcado = regra padrão do condomínio:</strong>\n              cota inativada não rende nada no período.\n            </small>\n          </span>\n        </label>\n      </div>\n      <div class=\"page-actions\" style=\"margin-top:0;padding-top:0;\">\n        <button type=\"button\" onclick=\"closeModal('modal-inativar-cota')\"\n                class=\"btn btn-secondary\">Cancelar</button>\n        <button type=\"submit\" class=\"btn btn-danger\">⏸️ Confirmar inativação</button>\n      </div>\n    </form>\n  </div>\n</div>\n\n<!-- Modal: Confirmar Exclusão de Cota -->\n<div class=\"modal-overlay\" id=\"modal-excluir-cota\" style=\"display:none;\">\n  <div class=\"modal\">\n    <div class=\"modal-title\" style=\"color:#f87171;\">🗑️ Excluir Cota</div>\n    <p style=\"color:#ccc;margin-bottom:14px;\">\n      Você está prestes a excluir a cota\n      <strong id=\"modal-delete-share-num\" style=\"color:#d4af37;font-size:18px;\"></strong>.\n    </p>\n    <div class=\"note-box\" style=\"border-color:rgba(239,68,68,0.35);background:rgba(239,68,68,0.06);margin-bottom:20px;\">\n      <strong style=\"color:#f87171;\">⚠️ Atenção:</strong>\n      Tem certeza que deseja excluir esta cota?\n      Esta ação deve ser usada apenas para corrigir cadastros feitos por engano.\n      A cota será removida permanentemente e a exclusão ficará registrada no log de auditoria.\n    </div>\n    <form id=\"form-excluir-cota\" method=\"post\" action=\"\">\n      <input type=\"hidden\" name=\"referrer\" id=\"modal-delete-referrer\" value=\"\">\n      <div class=\"page-actions\" style=\"margin-top:0;padding-top:0;\">\n        <button type=\"button\" onclick=\"closeModal('modal-excluir-cota')\"\n                class=\"btn btn-secondary\">Cancelar</button>\n        <button type=\"submit\" class=\"btn btn-delete\">🗑️ Confirmar exclusão</button>\n      </div>\n    </form>\n  </div>\n</div>\n\n{% endblock %}\n",
  "condominios_vencimentos.html": "{% extends \"base.html\" %}\n{% block title %}Vencimentos e Retiradas — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n\n<div class=\"page-header\">\n  <div class=\"page-header-icon\">⏰</div>\n  <div class=\"page-header-title\">Vencimentos e Retiradas</div>\n  <div class=\"page-header-sub\">Cotas vencendo, vencidas, em retirada e prontas para inativar</div>\n</div>\n\n<!-- KPIs -->\n<div class=\"metrics-grid\" style=\"grid-template-columns: repeat(4,1fr);\">\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#fbbf24;\">{{ vencendo_mes | length }}</div>\n    <div class=\"metric-label\">Vencendo em {{ '%02d' % mes }}/{{ ano }}</div>\n    <div style=\"font-size:12px;color:#d4af37;font-weight:600;margin-top:2px;\">\n      {{ formatar_moeda(total_vencendo) }} · {{ vencendo_por_cliente | length }} cliente(s)\n    </div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#f87171;\">{{ vencidas_ativas | length }}</div>\n    <div class=\"metric-label\">Vencidas ainda ativas</div>\n    <div style=\"font-size:12px;color:#d4af37;font-weight:600;margin-top:2px;\">\n      {{ formatar_moeda(total_vencidas) }} · {{ vencidas_por_cliente | length }} cliente(s)\n    </div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#60a5fa;\">{{ em_retirada | length }}</div>\n    <div class=\"metric-label\">Em retirada</div>\n    <div style=\"font-size:12px;color:#d4af37;font-weight:600;margin-top:2px;\">\n      {{ formatar_moeda(total_retirada) }}\n    </div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#a78bfa;\">{{ prontas_inativar | length }}</div>\n    <div class=\"metric-label\">Prontas para inativar</div>\n  </div>\n</div>\n\n<!-- Filtros -->\n<form method=\"get\" class=\"toolbar\">\n  <div class=\"toolbar-left\">\n    <div class=\"search-wrap\">\n      <input type=\"text\" name=\"q\" value=\"{{ q }}\"\n             placeholder=\"Buscar por cliente, CPF/CNPJ ou nº da cota…\"\n             class=\"form-control\" style=\"width:280px;\">\n    </div>\n    <select name=\"produto\" class=\"form-control form-control-sm\" style=\"width:160px;\">\n      <option value=\"\">Todos os produtos</option>\n      {% for c in conds %}\n      <option value=\"{{ c.code }}\" {{ 'selected' if produto_filtro == c.code else '' }}>{{ c.name }}</option>\n      {% endfor %}\n    </select>\n    <select name=\"mes\" class=\"form-control form-control-sm\" style=\"width:110px;\">\n      {% for m in range(1, 13) %}\n      <option value=\"{{ m }}\" {{ 'selected' if mes == m else '' }}>{{ '%02d' % m }}</option>\n      {% endfor %}\n    </select>\n    <select name=\"ano\" class=\"form-control form-control-sm\" style=\"width:110px;\">\n      {% for a in range(ano - 3, ano + 4) %}\n      <option value=\"{{ a }}\" {{ 'selected' if ano == a else '' }}>{{ a }}</option>\n      {% endfor %}\n    </select>\n    <button type=\"submit\" class=\"btn btn-secondary btn-sm\">Filtrar</button>\n    {% if q or produto_filtro %}\n      <a href=\"{{ url_for('condominios_vencimentos') }}\" class=\"btn btn-secondary btn-sm\">Limpar</a>\n    {% endif %}\n  </div>\n</form>\n\n<!-- ═══ Barra de ações em lote ═══ -->\n<div class=\"bulk-toolbar\" id=\"bulk-toolbar\">\n  <label class=\"bulk-toolbar-select-all\">\n    <input type=\"checkbox\" id=\"select-all-cotas\" class=\"select-all\">\n    <span>Selecionar todos</span>\n  </label>\n  <span class=\"bulk-toolbar-count\" id=\"bulk-selected-count\">0 cota(s) selecionada(s)</span>\n  <div class=\"bulk-toolbar-actions\">\n    <button type=\"button\" class=\"btn btn-primary btn-sm\" id=\"btn-renovar-lote\" disabled\n            onclick=\"openRenovarLoteModal()\">🔄 Renovar selecionadas</button>\n    <button type=\"button\" class=\"btn btn-danger btn-sm\" id=\"btn-retirada-lote\" disabled\n            onclick=\"openRetiradaLoteModal()\">📤 Marcar retirada selecionadas</button>\n    <button type=\"button\" class=\"btn btn-secondary btn-sm\" id=\"btn-email-lote\" disabled\n            onclick=\"openEmailPreviewModal()\">✉️ Preparar e-mail de renovação</button>\n  </div>\n</div>\n\n{% macro produto_badge(cota) %}\n  {% if cota.condominium_code == 'civil' %}\n    <span class=\"badge badge-civil\">🏗️ Civil</span>\n  {% elif cota.condominium_code == 'agro' %}\n    <span class=\"badge badge-agro\">🌾 Agro</span>\n  {% else %}\n    <span class=\"badge badge-saude\">🏥 Saúde</span>\n  {% endif %}\n{% endmacro %}\n\n{% macro btn_renovar(cota) %}\n  <button type=\"button\" class=\"btn btn-secondary btn-sm\"\n          title=\"Renovar escolhendo as datas manualmente\"\n          onclick=\"openRenovarModal(this)\"\n          data-share-id=\"{{ cota.id }}\"\n          data-share-num=\"{{ cota.share_number | e }}\"\n          data-client-name=\"{{ cota.client_name | e }}\"\n          data-maturity-date=\"{{ cota.maturity_parsed or '' }}\"\n          data-acquisition-date=\"{{ cota.acquisition_date or '' }}\">\n    ✏️\n  </button>\n{% endmacro %}\n\n{% macro btn_retirada(cota) %}\n  <button type=\"button\" class=\"btn btn-secondary btn-sm\"\n          title=\"Marcar retirada escolhendo as datas manualmente\"\n          onclick=\"openRetiradaModal(this)\"\n          data-share-id=\"{{ cota.id }}\"\n          data-share-num=\"{{ cota.share_number | e }}\"\n          data-client-name=\"{{ cota.client_name | e }}\"\n          data-cond-code=\"{{ cota.condominium_code }}\"\n          data-maturity-date=\"{{ cota.maturity_parsed or '' }}\">\n    ✏️\n  </button>\n{% endmacro %}\n\n{# ── Ação direta: \"Vai renovar\" — já grava vencimento e última renovação ── #}\n{% macro btn_vai_renovar(cota) %}\n  <form method=\"post\" action=\"{{ url_for('cotas_renovar_rapido', sid=cota.id) }}\" style=\"display:inline;\">\n    <input type=\"hidden\" name=\"referrer\" value=\"{{ request.url }}\">\n    <button type=\"submit\" class=\"btn btn-primary btn-sm\"\n            data-confirm=\"Renovar agora a cota {{ cota.share_number | e }} — {{ cota.client_name | e }}?&#10;&#10;Última renovação: {{ cota.sug_renovacao_data }}&#10;Novo vencimento: {{ cota.sug_novo_vencimento }}&#10;&#10;A base da cota será atualizada e o log de auditoria registrado.\">\n      🔄 Vai renovar\n    </button>\n  </form>\n{% endmacro %}\n\n{# ── Ação direta: \"Vai retirar\" — marca a retirada com o prazo do produto ── #}\n{% macro btn_vai_retirar(cota) %}\n  <form method=\"post\" action=\"{{ url_for('cotas_retirar_rapido', sid=cota.id) }}\" style=\"display:inline;\">\n    <input type=\"hidden\" name=\"referrer\" value=\"{{ request.url }}\">\n    <button type=\"submit\" class=\"btn btn-danger btn-sm\"\n            data-confirm=\"Marcar retirada da cota {{ cota.share_number | e }} — {{ cota.client_name | e }}?&#10;&#10;Pedido: {{ cota.sug_retirada_pedido }}&#10;Retirada efetiva: {{ cota.sug_retirada_efetiva }} (vencimento + {{ cota.sug_retirada_dias }} dias)&#10;&#10;A cota continua ativa e entra na apuração até a data efetiva.\">\n      📤 Vai retirar\n    </button>\n  </form>\n{% endmacro %}\n\n{# ═══ Bloco consolidado por cliente, com detalhamento por cota ═══ #}\n{% macro bloco_por_cliente(grupos, prefix, cor, total) %}\n<div class=\"table-wrap\" style=\"margin-bottom:8px;\">\n  <table>\n    <thead>\n      <tr>\n        <th style=\"width:36px;\"></th>\n        <th>Cliente</th>\n        <th>Produto</th>\n        <th>CPF/CNPJ</th>\n        <th style=\"text-align:center;\">Cotas</th>\n        <th style=\"text-align:right;\">Valor total</th>\n        <th style=\"text-align:center;\">Detalhes</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for g in grupos %}\n      {% set gid = prefix ~ '-' ~ loop.index0 %}\n      <tr>\n        <td>\n          <input type=\"checkbox\" class=\"group-select-all\" data-group=\"{{ gid }}\"\n                 title=\"Selecionar todas as cotas deste cliente\">\n        </td>\n        <td>\n          <a href=\"{{ url_for('clientes_detalhe', cid=g.client_id) }}\"\n             style=\"color:#F5F5F5;font-weight:600;\">{{ g.client_name }}</a>\n        </td>\n        <td>{{ produto_badge(g) }}</td>\n        <td class=\"text-mono text-dim\">{{ g.client_cpf }}</td>\n        <td style=\"text-align:center;color:#888;\">{{ g.qty_cotas }}</td>\n        <td style=\"text-align:right;font-weight:700;color:#d4af37;font-size:16px;\">\n          {{ formatar_moeda(g.total_value) }}\n        </td>\n        <td style=\"text-align:center;\">\n          <button type=\"button\" class=\"btn btn-secondary btn-sm\"\n                  id=\"btn-{{ gid }}\" onclick=\"toggleCotasCliente('{{ gid }}')\">▶ Ver cotas</button>\n        </td>\n      </tr>\n      <tr id=\"detalhe-{{ gid }}\" style=\"display:none;background:rgba(0,0,0,0.25);\">\n        <td colspan=\"7\" style=\"padding:0;\">\n          <div style=\"padding:12px 16px 16px;\" data-group-body=\"{{ gid }}\">\n            <div style=\"font-size:11px;color:#888;text-transform:uppercase;letter-spacing:1px;margin-bottom:10px;\">\n              Cotas de {{ g.client_name }} · {{ g.condominium_name }}\n            </div>\n            <table style=\"width:100%;border-collapse:collapse;font-size:13px;\">\n              <thead>\n                <tr style=\"border-bottom:1px solid rgba(255,255,255,0.08);\">\n                  <th style=\"padding:6px 8px;width:32px;\"></th>\n                  <th style=\"padding:6px 8px;text-align:left;color:#888;font-weight:500;\">Nº Cota</th>\n                  <th style=\"padding:6px 8px;text-align:right;color:#888;font-weight:500;\">Valor</th>\n                  <th style=\"padding:6px 8px;color:#888;font-weight:500;\">Aquisição</th>\n                  <th style=\"padding:6px 8px;color:#888;font-weight:500;\">Vencimento</th>\n                  <th style=\"padding:6px 8px;color:#888;font-weight:500;\">Ú. Renovação</th>\n                  <th style=\"padding:6px 8px;color:#888;font-weight:500;\">Se renovar</th>\n                  <th style=\"padding:6px 8px;color:#888;font-weight:500;\">Se retirar</th>\n                  <th style=\"padding:6px 8px;text-align:right;color:#888;font-weight:500;\">Decisão</th>\n                </tr>\n              </thead>\n              <tbody>\n                {% for c in g.cotas %}\n                <tr style=\"border-bottom:1px solid rgba(255,255,255,0.04);\">\n                  <td style=\"padding:6px 8px;\">\n                    <input type=\"checkbox\" class=\"row-select\" data-group=\"{{ gid }}\"\n                           data-share-id=\"{{ c.id }}\"\n                           data-cond-code=\"{{ c.condominium_code }}\"\n                           data-client-name=\"{{ c.client_name | e }}\">\n                  </td>\n                  <td style=\"padding:6px 8px;font-weight:700;color:#d4af37;font-size:15px;\">{{ c.share_number }}</td>\n                  <td style=\"padding:6px 8px;text-align:right;color:#ccc;font-weight:600;\">{{ formatar_moeda(c.share_value) }}</td>\n                  <td style=\"padding:6px 8px;color:#888;\">{{ c.acquisition_date or '—' }}</td>\n                  <td style=\"padding:6px 8px;color:{{ cor }};font-weight:600;\">{{ c.maturity_date or '—' }}</td>\n                  <td style=\"padding:6px 8px;color:#888;\">{{ c.last_renewal_date or '—' }}</td>\n                  <td style=\"padding:6px 8px;color:#4ade80;font-size:12px;\">\n                    novo venc.<br>{{ c.sug_novo_vencimento }}\n                  </td>\n                  <td style=\"padding:6px 8px;color:#60a5fa;font-size:12px;\">\n                    efetiva<br>{{ c.sug_retirada_efetiva }}\n                  </td>\n                  <td style=\"padding:6px 8px;text-align:right;white-space:nowrap;\">\n                    {{ btn_vai_renovar(c) }}{{ btn_renovar(c) }}\n                    <span style=\"display:inline-block;width:6px;\"></span>\n                    {{ btn_vai_retirar(c) }}{{ btn_retirada(c) }}\n                  </td>\n                </tr>\n                {% endfor %}\n              </tbody>\n              <tfoot>\n                <tr style=\"border-top:1px solid rgba(212,175,55,0.3);\">\n                  <td colspan=\"2\" style=\"padding:8px;color:#888;font-weight:600;\">Total {{ g.client_name }}</td>\n                  <td style=\"padding:8px;text-align:right;font-weight:700;color:#d4af37;\">{{ formatar_moeda(g.total_value) }}</td>\n                  <td colspan=\"6\"></td>\n                </tr>\n              </tfoot>\n            </table>\n          </div>\n        </td>\n      </tr>\n      {% endfor %}\n    </tbody>\n    <tfoot>\n      <tr style=\"border-top:2px solid rgba(212,175,55,0.3);\">\n        <td colspan=\"4\" style=\"padding:10px 12px;font-weight:600;color:#d4af37;\">TOTAL</td>\n        <td style=\"padding:10px 12px;text-align:center;color:#aaa;font-weight:600;\">\n          {{ grupos | sum(attribute='qty_cotas') }}\n        </td>\n        <td style=\"padding:10px 12px;text-align:right;font-weight:700;color:#d4af37;font-size:17px;\">\n          {{ formatar_moeda(total) }}\n        </td>\n        <td></td>\n      </tr>\n    </tfoot>\n  </table>\n</div>\n<div style=\"font-size:11px;color:#555;margin-bottom:24px;text-align:right;\">\n  {{ grupos | length }} cliente(s) · {{ grupos | sum(attribute='qty_cotas') }} cota(s)\n</div>\n{% endmacro %}\n\n<!-- ═══ Vencendo neste mês — consolidado por cliente ═══ -->\n<div class=\"section-label\" style=\"color:#fbbf24;\">\n  ⏰ Vencendo em {{ '%02d' % mes }}/{{ ano }} —\n  {{ vencendo_por_cliente | length }} cliente(s) · {{ vencendo_mes | length }} cota(s) ·\n  <span style=\"color:#d4af37;\">{{ formatar_moeda(total_vencendo) }}</span>\n</div>\n{% if vencendo_por_cliente %}\n<div class=\"note-box\" style=\"margin-bottom:12px;\">\n  <span style=\"color:#fbbf24;font-weight:600;\">ℹ️ </span>\n  Clique em <strong>Ver cotas</strong> para abrir o detalhamento do cliente e decidir cota por cota.\n  <strong>🔄 Vai renovar</strong> já grava a nova data de vencimento e a última renovação da cota.\n  <strong>📤 Vai retirar</strong> registra o pedido de retirada (a cota segue ativa até a data efetiva).\n  Use <strong>✏️</strong> para informar datas diferentes das sugeridas.\n</div>\n{{ bloco_por_cliente(vencendo_por_cliente, 'venc', '#fbbf24', total_vencendo) }}\n{% else %}\n<div class=\"text-dim\" style=\"font-size:13px;margin-bottom:24px;\">Nenhuma cota vencendo no mês selecionado.</div>\n{% endif %}\n\n<!-- ═══ Vencidas ainda ativas — consolidado por cliente ═══ -->\n<div class=\"section-label\" style=\"color:#f87171;\">\n  ⚠️ Vencidas ainda ativas —\n  {{ vencidas_por_cliente | length }} cliente(s) · {{ vencidas_ativas | length }} cota(s) ·\n  <span style=\"color:#d4af37;\">{{ formatar_moeda(total_vencidas) }}</span>\n</div>\n{% if vencidas_por_cliente %}\n{{ bloco_por_cliente(vencidas_por_cliente, 'venci', '#f87171', total_vencidas) }}\n{% else %}\n<div class=\"text-dim\" style=\"font-size:13px;margin-bottom:24px;\">Nenhuma cota vencida ainda ativa.</div>\n{% endif %}\n\n<!-- ═══ Em retirada ═══ -->\n<div class=\"section-label\" style=\"color:#60a5fa;\">📤 Em retirada ({{ em_retirada | length }})</div>\n{% if em_retirada %}\n<div class=\"note-box\" style=\"margin-bottom:12px;\">\n  <span style=\"color:#60a5fa;font-weight:600;\">ℹ️ </span>\n  Cotas em retirada continuam <strong>ativas</strong> e entram na apuração até a data efetiva.\n</div>\n<div class=\"table-wrap\" style=\"margin-bottom:24px;\">\n  <table>\n    <thead>\n      <tr>\n        <th>Nº</th><th>Produto</th><th>Cotista</th>\n        <th>Valor</th><th>Vencimento</th><th>Pedido</th><th>Retirada efetiva</th>\n        <th style=\"text-align:right;\">Ações</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for cota in em_retirada %}\n      <tr>\n        <td style=\"font-size:18px;font-weight:700;color:#d4af37;\">\n          {{ cota.share_number }}\n          <span class=\"badge badge-retirada\" style=\"font-size:10px;vertical-align:middle;\">📤 Em retirada</span>\n        </td>\n        <td>{{ produto_badge(cota) }}</td>\n        <td><a href=\"{{ url_for('clientes_detalhe', cid=cota.client_id) }}\" style=\"color:#F5F5F5;\">{{ cota.client_name }}</a></td>\n        <td style=\"font-weight:600;\">{{ formatar_moeda(cota.share_value) }}</td>\n        <td class=\"text-dim\">{{ cota.maturity_date or '—' }}</td>\n        <td class=\"text-dim\">{{ cota.withdrawal_request_date or '—' }}</td>\n        <td style=\"color:#60a5fa;font-weight:600;\">{{ cota.withdrawal_effective_date or '—' }}</td>\n        <td style=\"text-align:right;white-space:nowrap;\">\n          <button type=\"button\" class=\"btn btn-secondary btn-sm\"\n                  onclick=\"openEditarDataModal(this)\"\n                  data-share-id=\"{{ cota.id }}\"\n                  data-share-num=\"{{ cota.share_number | e }}\"\n                  data-effective-date=\"{{ cota.withdrawal_effective_date or '' }}\">\n            ✏️ Data\n          </button>\n          <form method=\"post\" action=\"{{ url_for('cotas_cancelar_retirada', sid=cota.id) }}\" style=\"display:inline;\">\n            <input type=\"hidden\" name=\"referrer\" value=\"{{ request.url }}\">\n            <button type=\"submit\" class=\"btn btn-secondary btn-sm\"\n                    data-confirm=\"Cancelar o pedido de retirada da cota {{ cota.share_number }}?\">\n              Cancelar retirada\n            </button>\n          </form>\n        </td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n{% else %}\n<div class=\"text-dim\" style=\"font-size:13px;margin-bottom:24px;\">Nenhuma cota em retirada.</div>\n{% endif %}\n\n<!-- ═══ Prontas para inativar ═══ -->\n<div class=\"section-label\" style=\"color:#a78bfa;\">✅ Prontas para inativar ({{ prontas_inativar | length }})</div>\n{% if prontas_inativar %}\n<div class=\"note-box\" style=\"margin-bottom:12px;\">\n  <span style=\"color:#a78bfa;font-weight:600;\">ℹ️ </span>\n  Cotas com retirada solicitada e data efetiva até hoje ({{ hoje }}).\n  Ao inativar, a data de retirada da cota será a data efetiva.\n</div>\n<div class=\"table-wrap\" style=\"margin-bottom:24px;\">\n  <table>\n    <thead>\n      <tr>\n        <th>Nº</th><th>Produto</th><th>Cotista</th>\n        <th>Valor</th><th>Pedido</th><th>Retirada efetiva</th>\n        <th style=\"text-align:right;\">Ações</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for cota in prontas_inativar %}\n      <tr>\n        <td style=\"font-size:18px;font-weight:700;color:#d4af37;\">{{ cota.share_number }}</td>\n        <td>{{ produto_badge(cota) }}</td>\n        <td><a href=\"{{ url_for('clientes_detalhe', cid=cota.client_id) }}\" style=\"color:#F5F5F5;\">{{ cota.client_name }}</a></td>\n        <td style=\"font-weight:600;\">{{ formatar_moeda(cota.share_value) }}</td>\n        <td class=\"text-dim\">{{ cota.withdrawal_request_date or '—' }}</td>\n        <td style=\"color:#a78bfa;font-weight:600;\">{{ cota.withdrawal_effective_date or '—' }}</td>\n        <td style=\"text-align:right;white-space:nowrap;\">\n          <form method=\"post\" action=\"{{ url_for('cotas_inativar_retirada', sid=cota.id) }}\" style=\"display:inline;\">\n            <input type=\"hidden\" name=\"referrer\" value=\"{{ request.url }}\">\n            <button type=\"submit\" class=\"btn btn-danger btn-sm\"\n                    data-confirm=\"Inativar a cota {{ cota.share_number }} com retirada em {{ cota.withdrawal_effective_date }}?\">\n              ⏸️ Inativar retirada\n            </button>\n          </form>\n        </td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n{% else %}\n<div class=\"text-dim\" style=\"font-size:13px;margin-bottom:24px;\">Nenhuma cota pronta para inativar.</div>\n{% endif %}\n\n<!-- ═══ Resumo para comunicação aos investidores ═══ -->\n<div class=\"section-label\" style=\"color:#d4af37;\">✉️ Resumo para comunicação aos investidores</div>\n<div class=\"card\" style=\"margin-bottom:24px;\">\n  <div class=\"note-box\" style=\"margin-bottom:14px;\">\n    <span style=\"color:#d4af37;font-weight:600;\">ℹ️ </span>\n    Consolidado <strong>por cliente</strong> (não por cota) das cotas vencendo em\n    {{ '%02d' % mes }}/{{ ano }}{{ ' — ' + produto_filtro if produto_filtro else '' }}.\n    Preparado para o futuro envio via Gmail — <strong>nenhum e-mail é enviado aqui</strong>.\n  </div>\n  {% if resumo_comunicacao %}\n  <div class=\"table-wrap\">\n    <table>\n      <thead>\n        <tr>\n          <th>Cliente</th><th>E-mail</th><th>Condomínio</th>\n          <th>Quantidade de cotas</th><th>Valor total vencendo</th>\n          <th>Datas de vencimento</th><th>Status</th>\n          <th style=\"text-align:right;\">Ações</th>\n        </tr>\n      </thead>\n      <tbody>\n        {% for item in resumo_comunicacao %}\n        <tr>\n          <td><a href=\"{{ url_for('clientes_detalhe', cid=item.client_id) }}\" style=\"color:#F5F5F5;\">{{ item.client_name }}</a></td>\n          <td class=\"text-mono text-dim\">{{ item.email or '—' }}</td>\n          <td>{{ item.condominium_name }}</td>\n          <td>{{ item.total_shares }}</td>\n          <td style=\"font-weight:600;\">{{ formatar_moeda(item.total_value) }}</td>\n          <td class=\"text-dim\">{{ item.maturity_dates | join(', ') }}</td>\n          <td>\n            {% if item.status_email == 'pronto' %}\n              <span class=\"badge badge-active\">✓ Pronto</span>\n            {% else %}\n              <span class=\"badge badge-inactive\">✗ Sem e-mail</span>\n            {% endif %}\n          </td>\n          <td style=\"text-align:right;white-space:nowrap;\">\n            <button type=\"button\" class=\"btn btn-secondary btn-sm\"\n                    onclick='openEmailPreviewModal({{ item.share_ids | tojson }})'>\n              ✉️ Ver rascunho\n            </button>\n          </td>\n        </tr>\n        {% endfor %}\n      </tbody>\n    </table>\n  </div>\n  {% else %}\n  <div class=\"text-dim\" style=\"font-size:13px;\">Nenhuma cota vencendo no mês selecionado para comunicação.</div>\n  {% endif %}\n</div>\n\n<!-- Modal: Renovar Cota -->\n<div class=\"modal-overlay\" id=\"modal-renovar-cota\" style=\"display:none;\">\n  <div class=\"modal\">\n    <div class=\"modal-title\" style=\"color:#4ade80;\">🔄 Renovar Cota</div>\n    <div style=\"margin-bottom:16px;\">\n      <table style=\"width:100%;border-collapse:collapse;font-size:13px;line-height:1.8;\">\n        <tr>\n          <td style=\"color:#888;width:130px;\">Cota nº</td>\n          <td style=\"color:#d4af37;font-weight:700;font-size:16px;\" id=\"modal-renovar-share-num\"></td>\n        </tr>\n        <tr>\n          <td style=\"color:#888;\">Cliente</td>\n          <td style=\"color:#ccc;\" id=\"modal-renovar-client\"></td>\n        </tr>\n        <tr>\n          <td style=\"color:#888;\">Vencimento atual</td>\n          <td style=\"color:#ccc;\" id=\"modal-renovar-mat\"></td>\n        </tr>\n      </table>\n    </div>\n    <form id=\"modal-renovar-form\" method=\"post\" action=\"\">\n      <input type=\"hidden\" name=\"referrer\" id=\"modal-renovar-referrer\" value=\"\">\n      <div class=\"form-group\" style=\"margin-bottom:14px;\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">\n          Data da renovação <span style=\"color:#f87171;\">*</span>\n        </label>\n        <input type=\"date\" name=\"renewal_date\" id=\"modal-renovar-renewal-date\"\n               class=\"form-control\" required>\n      </div>\n      <div class=\"form-group\" style=\"margin-bottom:14px;\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">\n          Novo vencimento <span style=\"color:#f87171;\">*</span>\n        </label>\n        <input type=\"date\" name=\"new_maturity_date\" id=\"modal-renovar-maturity-date\"\n               class=\"form-control\" required>\n      </div>\n      <div class=\"form-group\" style=\"margin-bottom:20px;\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">\n          Observação <span style=\"color:#666;\">(opcional)</span>\n        </label>\n        <input type=\"text\" name=\"user_note\" id=\"modal-renovar-user-note\"\n               class=\"form-control\" placeholder=\"Motivo/detalhes da renovação…\" maxlength=\"200\">\n      </div>\n      <div class=\"page-actions\" style=\"margin-top:0;padding-top:0;\">\n        <button type=\"button\" onclick=\"closeModal('modal-renovar-cota')\"\n                class=\"btn btn-secondary\">Cancelar</button>\n        <button type=\"submit\" class=\"btn btn-primary\">🔄 Confirmar renovação</button>\n      </div>\n    </form>\n  </div>\n</div>\n\n<!-- Modal: Marcar Retirada -->\n<div class=\"modal-overlay\" id=\"modal-retirada-cota\" style=\"display:none;\">\n  <div class=\"modal\">\n    <div class=\"modal-title\" style=\"color:#60a5fa;\">📤 Marcar Retirada</div>\n    <div style=\"margin-bottom:12px;\">\n      <table style=\"width:100%;border-collapse:collapse;font-size:13px;line-height:1.8;\">\n        <tr>\n          <td style=\"color:#888;width:130px;\">Cota nº</td>\n          <td style=\"color:#d4af37;font-weight:700;font-size:16px;\" id=\"modal-retirada-share-num\"></td>\n        </tr>\n        <tr>\n          <td style=\"color:#888;\">Cliente</td>\n          <td style=\"color:#ccc;\" id=\"modal-retirada-client\"></td>\n        </tr>\n        <tr>\n          <td style=\"color:#888;\">Vencimento</td>\n          <td style=\"color:#ccc;\" id=\"modal-retirada-mat\"></td>\n        </tr>\n      </table>\n    </div>\n    <div class=\"note-box\" style=\"margin-bottom:14px;\">\n      <span style=\"color:#60a5fa;font-weight:600;\">ℹ️ </span>\n      A cota permanece <strong>ativa</strong> e entra na apuração até a data efetiva da retirada.\n      <span id=\"modal-retirada-sugestao-txt\" style=\"display:block;color:#888;margin-top:4px;\"></span>\n    </div>\n    <form id=\"modal-retirada-form\" method=\"post\" action=\"\">\n      <input type=\"hidden\" name=\"referrer\" id=\"modal-retirada-referrer\" value=\"\">\n      <div class=\"form-group\" style=\"margin-bottom:14px;\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">\n          Data do pedido <span style=\"color:#f87171;\">*</span>\n        </label>\n        <input type=\"date\" name=\"withdrawal_request_date\" id=\"modal-retirada-request-date\"\n               class=\"form-control\" required>\n      </div>\n      <div class=\"form-group\" style=\"margin-bottom:14px;\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">\n          Data efetiva da retirada <span style=\"color:#f87171;\">*</span>\n          <span style=\"color:#666;font-weight:400;\">(sugerida — pode editar)</span>\n        </label>\n        <input type=\"date\" name=\"withdrawal_effective_date\" id=\"modal-retirada-effective-date\"\n               class=\"form-control\" required>\n      </div>\n      <div class=\"form-group\" style=\"margin-bottom:20px;\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">\n          Observação <span style=\"color:#666;\">(opcional)</span>\n        </label>\n        <input type=\"text\" name=\"withdrawal_notes\" id=\"modal-retirada-notes\"\n               class=\"form-control\" placeholder=\"Detalhes do pedido de retirada…\" maxlength=\"200\">\n      </div>\n      <div class=\"page-actions\" style=\"margin-top:0;padding-top:0;\">\n        <button type=\"button\" onclick=\"closeModal('modal-retirada-cota')\"\n                class=\"btn btn-secondary\">Cancelar</button>\n        <button type=\"submit\" class=\"btn btn-danger\">📤 Confirmar retirada</button>\n      </div>\n    </form>\n  </div>\n</div>\n\n<!-- Modal: Editar data efetiva da retirada -->\n<div class=\"modal-overlay\" id=\"modal-editar-data-retirada\" style=\"display:none;\">\n  <div class=\"modal\">\n    <div class=\"modal-title\" style=\"color:#60a5fa;\">✏️ Alterar data efetiva</div>\n    <p style=\"color:#ccc;margin-bottom:14px;\">\n      Cota <strong id=\"modal-editar-data-share-num\" style=\"color:#d4af37;\"></strong>\n    </p>\n    <form id=\"modal-editar-data-form\" method=\"post\" action=\"\">\n      <input type=\"hidden\" name=\"referrer\" id=\"modal-editar-data-referrer\" value=\"\">\n      <div class=\"form-group\" style=\"margin-bottom:20px;\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">\n          Nova data efetiva <span style=\"color:#f87171;\">*</span>\n        </label>\n        <input type=\"date\" name=\"withdrawal_effective_date\" id=\"modal-editar-data-input\"\n               class=\"form-control\" required>\n      </div>\n      <div class=\"page-actions\" style=\"margin-top:0;padding-top:0;\">\n        <button type=\"button\" onclick=\"closeModal('modal-editar-data-retirada')\"\n                class=\"btn btn-secondary\">Cancelar</button>\n        <button type=\"submit\" class=\"btn btn-primary\">✓ Salvar</button>\n      </div>\n    </form>\n  </div>\n</div>\n\n<!-- Modal: Renovar em lote -->\n<div class=\"modal-overlay\" id=\"modal-renovar-lote\" style=\"display:none;\">\n  <div class=\"modal\">\n    <div class=\"modal-title\" style=\"color:#4ade80;\">🔄 Renovar cotas selecionadas</div>\n    <p class=\"text-dim\" style=\"font-size:13px;margin-bottom:16px;\">\n      <strong id=\"lote-renovar-count\">0</strong> cota(s) selecionada(s) serão renovadas com os\n      mesmos dados abaixo.\n    </p>\n    <form id=\"modal-renovar-lote-form\" method=\"post\" action=\"{{ url_for('cotas_renovar_lote') }}\">\n      <input type=\"hidden\" name=\"referrer\" value=\"{{ request.url }}\">\n      <div id=\"lote-renovar-share-ids\"></div>\n      <div class=\"form-group\" style=\"margin-bottom:14px;\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">\n          Nova data de renovação <span style=\"color:#f87171;\">*</span>\n        </label>\n        <input type=\"date\" name=\"renewal_date\" id=\"lote-renovar-renewal-date\"\n               class=\"form-control\" required>\n      </div>\n      <div class=\"form-group\" style=\"margin-bottom:14px;\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">\n          Nova data de vencimento <span style=\"color:#f87171;\">*</span>\n        </label>\n        <input type=\"date\" name=\"new_maturity_date\" id=\"lote-renovar-maturity-date\"\n               class=\"form-control\" required>\n      </div>\n      <div class=\"form-group\" style=\"margin-bottom:20px;\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">\n          Observação <span style=\"color:#666;\">(opcional)</span>\n        </label>\n        <input type=\"text\" name=\"notes\" id=\"lote-renovar-notes\"\n               class=\"form-control\" placeholder=\"Motivo/detalhes da renovação em lote…\" maxlength=\"200\">\n      </div>\n      <div class=\"page-actions\" style=\"margin-top:0;padding-top:0;\">\n        <button type=\"button\" onclick=\"closeModal('modal-renovar-lote')\"\n                class=\"btn btn-secondary\">Cancelar</button>\n        <button type=\"submit\" class=\"btn btn-primary\">🔄 Confirmar renovação em lote</button>\n      </div>\n    </form>\n  </div>\n</div>\n\n<!-- Modal: Marcar retirada em lote -->\n<div class=\"modal-overlay\" id=\"modal-retirada-lote\" style=\"display:none;\">\n  <div class=\"modal\">\n    <div class=\"modal-title\" style=\"color:#60a5fa;\">📤 Marcar retirada em lote</div>\n    <p class=\"text-dim\" style=\"font-size:13px;margin-bottom:12px;\">\n      <strong id=\"lote-retirada-count\">0</strong> cota(s) selecionada(s).\n    </p>\n    <div class=\"note-box\" id=\"lote-retirada-warning\" style=\"display:none;margin-bottom:14px;color:#fbbf24;border-color:rgba(251,191,36,0.25);\">\n      ⚠️ Você selecionou cotas de produtos diferentes. A data efetiva será aplicada manualmente para todas.\n    </div>\n    <form id=\"modal-retirada-lote-form\" method=\"post\" action=\"{{ url_for('cotas_marcar_retirada_lote') }}\">\n      <input type=\"hidden\" name=\"referrer\" value=\"{{ request.url }}\">\n      <div id=\"lote-retirada-share-ids\"></div>\n      <div class=\"form-group\" style=\"margin-bottom:14px;\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">\n          Data do pedido <span style=\"color:#f87171;\">*</span>\n        </label>\n        <input type=\"date\" name=\"request_date\" id=\"lote-retirada-request-date\"\n               class=\"form-control\" required>\n      </div>\n      <div class=\"form-group\" style=\"margin-bottom:14px;\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">\n          Data efetiva da retirada (única para todas) <span style=\"color:#f87171;\">*</span>\n        </label>\n        <input type=\"date\" name=\"effective_date\" id=\"lote-retirada-effective-date\"\n               class=\"form-control\" required>\n      </div>\n      <div class=\"form-group\" style=\"margin-bottom:20px;\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">\n          Observação <span style=\"color:#666;\">(opcional)</span>\n        </label>\n        <input type=\"text\" name=\"notes\" id=\"lote-retirada-notes\"\n               class=\"form-control\" placeholder=\"Detalhes do pedido de retirada em lote…\" maxlength=\"200\">\n      </div>\n      <div class=\"page-actions\" style=\"margin-top:0;padding-top:0;\">\n        <button type=\"button\" onclick=\"closeModal('modal-retirada-lote')\"\n                class=\"btn btn-secondary\">Cancelar</button>\n        <button type=\"submit\" class=\"btn btn-danger\">📤 Confirmar retirada em lote</button>\n      </div>\n    </form>\n  </div>\n</div>\n\n<!-- Modal: Preview de e-mail de renovação (por cliente) -->\n<div class=\"modal-overlay\" id=\"modal-email-preview\" style=\"display:none;\">\n  <div class=\"modal modal-wide\">\n    <div class=\"modal-title\" style=\"color:#d4af37;\">✉️ Preparar e-mail de renovação</div>\n    <div class=\"note-box\" style=\"margin-bottom:14px;\">\n      <span style=\"color:#d4af37;font-weight:600;\">ℹ️ </span>\n      Por cliente, há duas opções: <strong>\"Criar rascunho no Gmail\"</strong> (padrão, mais seguro —\n      salva o rascunho na sua própria caixa de e-mail para revisão; o envio continua manual, pelo Gmail)\n      ou <strong>\"Enviar e-mail agora\"</strong> (envia imediatamente, com confirmação obrigatória antes\n      do envio). Se o Gmail ainda não estiver autenticado, configure\n      em <a href=\"{{ url_for('configuracoes') }}\" style=\"color:#d4af37;\">Configurações</a>.\n    </div>\n    <div id=\"email-preview-loading\" class=\"text-dim\" style=\"font-size:13px;\">Carregando…</div>\n    <div id=\"email-preview-list\"></div>\n    <div class=\"page-actions\" style=\"margin-top:16px;padding-top:16px;\">\n      <button type=\"button\" onclick=\"closeModal('modal-email-preview')\"\n              class=\"btn btn-secondary\">Fechar</button>\n    </div>\n  </div>\n</div>\n\n{% endblock %}\n\n{% block scripts %}\n<script>\n  /* Dias sugeridos por produto (Civil +3 · Agro/Saúde +30) */\n  window.WITHDRAWAL_SUGGESTION_DAYS = {{ withdrawal_days | tojson }};\n  window.HOJE_ISO = \"{{ hoje }}\";\n  window.REF_MES = {{ mes | tojson }};\n  window.REF_ANO = {{ ano | tojson }};\n\n  /* ── Abrir/fechar o detalhamento de cotas de um cliente ── */\n  function toggleCotasCliente(gid) {\n    var row = document.getElementById('detalhe-' + gid);\n    var btn = document.getElementById('btn-' + gid);\n    if (!row) return;\n    var abrir = (row.style.display === 'none' || row.style.display === '');\n    row.style.display = abrir ? 'table-row' : 'none';\n    if (btn) btn.textContent = abrir ? '▼ Ocultar cotas' : '▶ Ver cotas';\n  }\n  window.toggleCotasCliente = toggleCotasCliente;\n\n  /* ── Checkbox do cliente marca/desmarca as cotas dele ── */\n  (function () {\n    function cotasDoGrupo(gid) {\n      return Array.from(document.querySelectorAll('.row-select[data-group=\"' + gid + '\"]'));\n    }\n\n    document.addEventListener('change', function (e) {\n      var el = e.target;\n      if (!el || !el.classList) return;\n\n      /* Master do cliente → replica nas cotas */\n      if (el.classList.contains('group-select-all')) {\n        var gid = el.dataset.group;\n        cotasDoGrupo(gid).forEach(function (c) {\n          if (c.checked !== el.checked) {\n            c.checked = el.checked;\n            c.dispatchEvent(new Event('change', { bubbles: true }));\n          }\n        });\n        return;\n      }\n\n      /* Cota → atualiza o master do cliente */\n      if (el.classList.contains('row-select') && el.dataset.group) {\n        var master = document.querySelector('.group-select-all[data-group=\"' + el.dataset.group + '\"]');\n        if (!master) return;\n        var cotas = cotasDoGrupo(el.dataset.group);\n        var marcadas = cotas.filter(function (c) { return c.checked; }).length;\n        master.checked = marcadas === cotas.length && cotas.length > 0;\n        master.indeterminate = marcadas > 0 && marcadas < cotas.length;\n      }\n    });\n\n    /* \"Selecionar todos\" da barra de ações → sincroniza os masters de cliente */\n    var geral = document.getElementById('select-all-cotas');\n    if (geral) {\n      geral.addEventListener('change', function () {\n        document.querySelectorAll('.group-select-all').forEach(function (m) {\n          m.checked = geral.checked;\n          m.indeterminate = false;\n        });\n      });\n    }\n  })();\n</script>\n{% endblock %}\n",
  "configuracoes.html": "{% extends \"base.html\" %}\n{% block title %}Configurações — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n\n<div class=\"page-header\">\n  <div class=\"page-header-icon\">⚙️</div>\n  <div class=\"page-header-title\">Configurações</div>\n  <div class=\"page-header-sub\">Parâmetros do sistema e integrações</div>\n</div>\n\n<!-- ═══ Integração Gmail ═══ -->\n<div class=\"section-label\" style=\"color:#d4af37;\">✉️ Status da integração Gmail</div>\n<div class=\"card\" style=\"margin-bottom:24px;\">\n  <div class=\"detail-grid\" style=\"margin-bottom:18px;\">\n    <div>\n      <div class=\"detail-item-label\">Credenciais encontradas</div>\n      <div class=\"detail-item-value\">\n        {% if gmail_status.credentials_found %}\n          <span class=\"badge badge-active\">✓ Sim</span>\n        {% else %}\n          <span class=\"badge badge-inactive\">✗ Não</span>\n        {% endif %}\n      </div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Token autorizado</div>\n      <div class=\"detail-item-value\">\n        {% if gmail_status.token_valid %}\n          <span class=\"badge badge-active\">✓ Sim</span>\n        {% elif gmail_status.token_found %}\n          <span class=\"badge badge-pending\">⚠ Expirado</span>\n        {% else %}\n          <span class=\"badge badge-inactive\">✗ Não</span>\n        {% endif %}\n      </div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Método de integração</div>\n      <div class=\"detail-item-value\">\n        <span class=\"badge badge-active\">{{ gmail_status.auth_method or 'REST OAuth manual' }}</span>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"note-box\" style=\"margin-bottom:16px;\">\n    ℹ️ Integração Gmail: OAuth REST manual, sem bibliotecas Google externas.\n  </div>\n\n  {% if not gmail_status.credentials_found %}\n  <div class=\"note-box\" style=\"margin-bottom:16px;color:#f87171;border-color:rgba(239,68,68,0.25);\">\n    ⚠️ Arquivo config/gmail_credentials.json não encontrado. Configure\n    <span class=\"text-mono\">config/gmail_credentials.json</span>.<br>\n    Baixe o arquivo de credenciais OAuth (tipo \"App para computador\") no\n    <strong>Google Cloud Console</strong> → APIs e serviços → Credenciais, e salve exatamente\n    nesse caminho, dentro da pasta do projeto.\n  </div>\n  {% elif not gmail_status.token_valid %}\n  <div class=\"note-box\" style=\"margin-bottom:16px;\">\n    ℹ️ Gmail ainda não autenticado. Autentique com sua conta Gmail para poder criar rascunhos\n    de e-mail diretamente na tela Vencimentos e Retiradas. Nenhum e-mail é enviado no processo.\n  </div>\n  {% else %}\n  <div class=\"note-box\" style=\"margin-bottom:16px;color:#4ade80;border-color:rgba(74,222,128,0.2);\">\n    ✓ Gmail autenticado. Os rascunhos criados na tela Vencimentos e Retiradas sairão da sua\n    própria caixa de e-mail — nada é enviado automaticamente, apenas o rascunho fica pronto\n    para revisão no Gmail.\n  </div>\n  {% endif %}\n\n  <form method=\"post\" action=\"{{ url_for('configuracoes_gmail_autenticar') }}\">\n    <button type=\"submit\" class=\"btn btn-primary\"\n            {{ 'disabled' if not gmail_status.credentials_found else '' }}>\n      🔐 {{ 'Reautenticar Gmail' if gmail_status.token_valid else 'Autenticar Gmail' }}\n    </button>\n  </form>\n  <p class=\"text-dim\" style=\"font-size:12px;margin-top:10px;\">\n    Ao clicar, uma janela do navegador será aberta para você fazer login e autorizar o acesso\n    — somente para <strong>criar rascunhos</strong> (escopo\n    <span class=\"text-mono\">gmail.compose</span>). O app nunca envia e-mails automaticamente,\n    e o conteúdo do token de acesso nunca é exibido na tela.\n  </p>\n</div>\n\n<!-- ═══ Configuração Banco Inter - Remessa CNAB ═══ -->\n<div class=\"section-label\" style=\"color:#d4af37;\">🏦 Configuração Banco Inter - Remessa CNAB</div>\n<div class=\"card\" style=\"margin-bottom:24px;\">\n  <div class=\"detail-grid\" style=\"margin-bottom:18px;\">\n    <div>\n      <div class=\"detail-item-label\">Código do banco</div>\n      <div class=\"detail-item-value text-mono\">077</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Próximo sequencial de remessa</div>\n      <div class=\"detail-item-value text-mono\">{{ bank_inter_config.remittance_sequence if bank_inter_config else 1 }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Cadastro completo</div>\n      <div class=\"detail-item-value\">\n        {% if bank_inter_config and bank_inter_config.company_name and bank_inter_config.company_document and bank_inter_config.account_number and bank_inter_config.account_digit %}\n          <span class=\"badge badge-active\">✓ Sim</span>\n        {% else %}\n          <span class=\"badge badge-inactive\">✗ Incompleto</span>\n        {% endif %}\n      </div>\n    </div>\n  </div>\n\n  <div class=\"note-box\" style=\"margin-bottom:16px;\">\n    ℹ️ Esses dados identificam a empresa pagadora no arquivo de remessa CNAB240 (Pix) do Inter,\n    usado para agendar o pagamento dos rendimentos de Construção Civil e Saúde. O sequencial de\n    remessa só avança quando um arquivo é gerado com sucesso. Enquanto os campos obrigatórios\n    abaixo não estiverem preenchidos, a geração do arquivo bancário fica bloqueada.\n  </div>\n\n  <form method=\"post\" action=\"{{ url_for('configuracoes_banco_inter_salvar') }}\">\n    <div class=\"form-grid\" style=\"display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin-bottom:14px;\">\n      <div class=\"form-group\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">Nome da empresa <span style=\"color:#f87171;\">*</span></label>\n        <input type=\"text\" name=\"company_name\" class=\"form-control\"\n               value=\"{{ bank_inter_config.company_name if bank_inter_config else '' }}\">\n      </div>\n      <div class=\"form-group\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">CNPJ da empresa <span style=\"color:#f87171;\">*</span></label>\n        <input type=\"text\" name=\"company_document\" class=\"form-control\"\n               value=\"{{ bank_inter_config.company_document if bank_inter_config else '' }}\">\n      </div>\n      <div class=\"form-group\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">Agência</label>\n        <input type=\"text\" name=\"agency\" class=\"form-control\"\n               value=\"{{ bank_inter_config.agency if bank_inter_config else '00001' }}\">\n      </div>\n      <div class=\"form-group\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">Dígito agência</label>\n        <input type=\"text\" name=\"agency_digit\" class=\"form-control\" maxlength=\"1\"\n               value=\"{{ bank_inter_config.agency_digit if bank_inter_config else '9' }}\">\n      </div>\n      <div class=\"form-group\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">Conta <span style=\"color:#f87171;\">*</span></label>\n        <input type=\"text\" name=\"account_number\" class=\"form-control\"\n               value=\"{{ bank_inter_config.account_number if bank_inter_config else '' }}\">\n      </div>\n      <div class=\"form-group\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">Dígito conta <span style=\"color:#f87171;\">*</span></label>\n        <input type=\"text\" name=\"account_digit\" class=\"form-control\" maxlength=\"1\"\n               value=\"{{ bank_inter_config.account_digit if bank_inter_config else '' }}\">\n      </div>\n      <div class=\"form-group\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">Endereço (rua/av)</label>\n        <input type=\"text\" name=\"address_street\" class=\"form-control\"\n               value=\"{{ bank_inter_config.address_street if bank_inter_config else '' }}\">\n      </div>\n      <div class=\"form-group\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">Número</label>\n        <input type=\"text\" name=\"address_number\" class=\"form-control\"\n               value=\"{{ bank_inter_config.address_number if bank_inter_config else '' }}\">\n      </div>\n      <div class=\"form-group\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">Complemento</label>\n        <input type=\"text\" name=\"address_complement\" class=\"form-control\"\n               value=\"{{ bank_inter_config.address_complement if bank_inter_config else '' }}\">\n      </div>\n      <div class=\"form-group\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">Cidade</label>\n        <input type=\"text\" name=\"city\" class=\"form-control\"\n               value=\"{{ bank_inter_config.city if bank_inter_config else '' }}\">\n      </div>\n      <div class=\"form-group\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">CEP</label>\n        <input type=\"text\" name=\"zip_code\" class=\"form-control\"\n               value=\"{{ bank_inter_config.zip_code if bank_inter_config else '' }}\">\n      </div>\n      <div class=\"form-group\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">UF</label>\n        <input type=\"text\" name=\"state\" class=\"form-control\" maxlength=\"2\"\n               value=\"{{ bank_inter_config.state if bank_inter_config else '' }}\">\n      </div>\n    </div>\n    <button type=\"submit\" class=\"btn btn-primary\">💾 Salvar dados do Inter</button>\n  </form>\n</div>\n\n<!-- ═══ Configuração Banco Itaú (Agronegócio) ═══ -->\n<div class=\"section-label\" style=\"color:#d4af37;\">🏦 Configuração Banco Itaú - Remessa CNAB (Agronegócio)</div>\n<div class=\"card\" style=\"margin-bottom:24px;\">\n  <div class=\"detail-grid\" style=\"margin-bottom:18px;\">\n    <div>\n      <div class=\"detail-item-label\">Código do banco</div>\n      <div class=\"detail-item-value text-mono\">341</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Próximo sequencial de remessa</div>\n      <div class=\"detail-item-value text-mono\">{{ bank_itau_config.remittance_sequence if bank_itau_config else 1 }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Cadastro completo</div>\n      <div class=\"detail-item-value\">\n        {% if bank_itau_config and bank_itau_config.company_name and bank_itau_config.company_document and bank_itau_config.agency and bank_itau_config.account_number and bank_itau_config.account_digit %}\n          <span class=\"badge badge-active\">✓ Sim</span>\n        {% else %}\n          <span class=\"badge badge-inactive\">✗ Incompleto</span>\n        {% endif %}\n      </div>\n    </div>\n  </div>\n\n  <div class=\"note-box\" style=\"margin-bottom:16px;\">\n    ℹ️ Esses dados identificam a empresa pagadora no arquivo de remessa CNAB240 SISPAG do Itaú,\n    usado para agendar o pagamento por dados bancários (crédito em conta corrente) dos rendimentos\n    do Agronegócio. O sequencial de remessa só avança quando um arquivo é gerado com sucesso.\n    Enquanto os campos obrigatórios abaixo não estiverem preenchidos, a geração do arquivo bancário\n    fica bloqueada.\n  </div>\n\n  <form method=\"post\" action=\"{{ url_for('configuracoes_banco_itau_salvar') }}\">\n    <div class=\"form-grid\" style=\"display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin-bottom:14px;\">\n      <div class=\"form-group\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">Nome da empresa <span style=\"color:#f87171;\">*</span></label>\n        <input type=\"text\" name=\"company_name\" class=\"form-control\"\n               value=\"{{ bank_itau_config.company_name if bank_itau_config else '' }}\">\n      </div>\n      <div class=\"form-group\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">CNPJ da empresa <span style=\"color:#f87171;\">*</span></label>\n        <input type=\"text\" name=\"company_document\" class=\"form-control\"\n               value=\"{{ bank_itau_config.company_document if bank_itau_config else '' }}\">\n      </div>\n      <div class=\"form-group\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">Agência <span style=\"color:#f87171;\">*</span></label>\n        <input type=\"text\" name=\"agency\" class=\"form-control\"\n               value=\"{{ bank_itau_config.agency if bank_itau_config else '' }}\">\n      </div>\n      <div class=\"form-group\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">Dígito agência</label>\n        <input type=\"text\" name=\"agency_digit\" class=\"form-control\" maxlength=\"1\"\n               value=\"{{ bank_itau_config.agency_digit if bank_itau_config else '' }}\">\n      </div>\n      <div class=\"form-group\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">Conta <span style=\"color:#f87171;\">*</span></label>\n        <input type=\"text\" name=\"account_number\" class=\"form-control\"\n               value=\"{{ bank_itau_config.account_number if bank_itau_config else '' }}\">\n      </div>\n      <div class=\"form-group\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">Dígito conta <span style=\"color:#f87171;\">*</span></label>\n        <input type=\"text\" name=\"account_digit\" class=\"form-control\" maxlength=\"1\"\n               value=\"{{ bank_itau_config.account_digit if bank_itau_config else '' }}\">\n      </div>\n      <div class=\"form-group\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">Convênio/código da empresa no Itaú</label>\n        <input type=\"text\" name=\"agreement_code\" class=\"form-control\"\n               value=\"{{ bank_itau_config.agreement_code if bank_itau_config else '' }}\">\n      </div>\n    </div>\n    <button type=\"submit\" class=\"btn btn-primary\">💾 Salvar dados do Itaú</button>\n  </form>\n\n  <div class=\"note-box\" style=\"margin-top:16px;color:#f0ad4e;border-color:rgba(240,173,78,0.25);\">\n    ⚠️ Este layout segue o padrão público Febraban CNAB240 para pagamento por dados bancários\n    (crédito em conta corrente) que o Itaú documenta seguir no SISPAG — nenhum manual técnico\n    específico do Itaú foi anexado para conferência campo a campo. Rode um arquivo de teste e\n    valide no ambiente de homologação do Itaú (ou com o gerente da conta) antes de transmitir um\n    arquivo real.\n  </div>\n</div>\n\n<!-- ═══ Parâmetros dos condomínios ═══ -->\n<div class=\"section-label\" style=\"color:#d4af37;\">🏛️ Parâmetros dos condomínios</div>\n<div class=\"table-wrap\" style=\"margin-bottom:24px;\">\n  <table>\n    <thead>\n      <tr>\n        <th>Produto</th><th>Taxa padrão</th><th>Dia de pagamento</th>\n        <th>Início do período</th><th>Fim do período</th><th>Status</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for c in conds %}\n      <tr>\n        <td>{{ c.name }}</td>\n        <td>{{ formatar_percentual(c.default_monthly_rate) }}</td>\n        <td>Dia {{ c.payment_day }}</td>\n        <td>Dia {{ c.accrual_start_day }}</td>\n        <td>Dia {{ c.accrual_end_day }}</td>\n        <td>\n          {% if c.active %}\n            <span class=\"badge badge-active\">Ativo</span>\n          {% else %}\n            <span class=\"badge badge-inactive\">Inativo</span>\n          {% endif %}\n        </td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n\n{% endblock %}\n",
  "contratos/_estilo.html": "<style>\n.ct-kpis{grid-template-columns:repeat(5,1fr)}\n.ct-kpi{display:block;transition:border-color .15s}\n.ct-kpi:hover,.ct-kpi.on{border-color:#d4af37}\n.ct-badge{display:inline-block;font-size:11px;font-weight:600;padding:3px 9px;border-radius:99px;white-space:nowrap;\n  color:var(--c);border:1px solid color-mix(in srgb,var(--c) 45%,transparent);background:color-mix(in srgb,var(--c) 10%,transparent)}\n.ct-prog{height:5px;border-radius:99px;background:#2a2a2a;overflow:hidden;width:90px;margin-bottom:3px}\n.ct-prog i{display:block;height:100%;background:#4ade80}\n.ct-grid{display:grid;grid-template-columns:minmax(0,1fr) 380px;gap:20px;align-items:start}\n.ct-doc{border:1px solid #2a2a2a;border-radius:8px;overflow:hidden;background:#e9e6df}\n.ct-doc iframe{display:block;width:100%;height:78vh;border:0}\n.ct-side .card-gold{margin-bottom:16px}\n.ct-sig{display:flex;gap:10px;padding:10px 0;border-top:1px solid #222}\n.ct-sig:first-of-type{border-top:0}\n.ct-dot{width:20px;height:20px;border-radius:50%;border:2px solid #555;flex:none;display:grid;place-items:center;font-size:11px;color:#111;margin-top:2px}\n.ct-dot.ok{background:#4ade80;border-color:#4ade80}\n.ct-ev{position:relative;padding:0 0 12px 18px;border-left:2px solid #2a2a2a;margin-left:6px}\n.ct-ev::before{content:\"\";position:absolute;left:-6px;top:4px;width:10px;height:10px;border-radius:50%;background:#d4af37}\n.ct-ev.erro::before{background:#f87171}\n.ct-ev b{display:block;font-size:13px}\n.ct-ev span{font-size:11.5px;color:#888}\n.ct-link{display:flex;gap:6px}\n.ct-link input{flex:1;font-size:12px}\n.ct-acoes{display:flex;flex-direction:column;gap:8px}\n.ct-acoes .btn{justify-content:center;width:100%}\n.ct-cotas td,.ct-cotas th{padding:6px 8px;font-size:13px}\n@media (max-width:1200px){.ct-grid{grid-template-columns:1fr}.ct-kpis{grid-template-columns:repeat(2,1fr)}}\n</style>\n",
  "contratos/configuracoes.html": "{% extends \"base.html\" %}\n{% block title %}Configurações de contratos — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n<a href=\"{{ url_for('contratos.painel') }}\" class=\"back-link\">← Voltar para Contratos</a>\n<div class=\"page-header\">\n  <div class=\"page-header-icon\">⚙️</div>\n  <div class=\"page-header-title\">Configurações dos contratos</div>\n  <div class=\"page-header-sub\">Valem para os próximos contratos gerados. Contratos já gerados não mudam (ficam protegidos pelo hash).</div>\n</div>\n\n<form method=\"post\" class=\"card-gold\">\n  <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n\n  <div class=\"form-section\">\n    <div class=\"form-section-title\">Link de assinatura</div>\n    <div class=\"form-group\">\n      <label>Endereço público do app</label>\n      <input type=\"url\" name=\"url_publica\" value=\"{{ cfg.url_publica }}\" class=\"form-control\" placeholder=\"https://assinar.capuzzo.com.br\">\n      <div class=\"text-dim\" style=\"font-size:12px;margin-top:4px;\">É o começo do link que vai no e-mail do cliente\n        (ex.: <span class=\"text-mono\">{{ cfg.url_publica }}/contratos/assinar/…</span>).\n        Enquanto estiver <span class=\"text-mono\">127.0.0.1</span>, o link só abre neste computador.</div>\n    </div>\n  </div>\n\n  <div class=\"form-section\">\n    <div class=\"form-section-title\">Empresa (Contratada)</div>\n    <div class=\"form-row\">\n      <div class=\"form-group\"><label>Razão social</label><input name=\"empresa_nome\" value=\"{{ cfg.empresa_nome }}\" class=\"form-control\"></div>\n      <div class=\"form-group\" style=\"max-width:240px\"><label>CNPJ</label><input name=\"empresa_cnpj\" value=\"{{ cfg.empresa_cnpj }}\" class=\"form-control\"></div>\n    </div>\n    <div class=\"form-group\"><label>Sede</label><input name=\"empresa_endereco\" value=\"{{ cfg.empresa_endereco }}\" class=\"form-control\"></div>\n    <div class=\"form-row\">\n      <div class=\"form-group\"><label>Nome na assinatura da empresa</label><input name=\"empresa_assinante\" value=\"{{ cfg.empresa_assinante }}\" class=\"form-control\"></div>\n      <div class=\"form-group\"><label>E-mail do signatário da empresa</label><input name=\"empresa_email\" value=\"{{ cfg.empresa_email }}\" class=\"form-control\"></div>\n      <div class=\"form-group\" style=\"max-width:220px\"><label>Local da assinatura</label><input name=\"cidade_assinatura\" value=\"{{ cfg.cidade_assinatura }}\" class=\"form-control\"></div>\n    </div>\n  </div>\n\n  <div class=\"form-section\">\n    <div class=\"form-section-title\">Testemunhas</div>\n    {% for i in (1, 2) %}\n    <div class=\"form-row\">\n      <div class=\"form-group\"><label>Testemunha {{ i }} — nome</label><input name=\"testemunha{{ i }}_nome\" value=\"{{ cfg['testemunha%d_nome' % i] }}\" class=\"form-control\"></div>\n      <div class=\"form-group\" style=\"max-width:220px\"><label>CPF</label><input name=\"testemunha{{ i }}_cpf\" value=\"{{ cfg['testemunha%d_cpf' % i] }}\" class=\"form-control\"></div>\n    </div>\n    {% endfor %}\n  </div>\n\n  <div class=\"form-section\">\n    <div class=\"form-section-title\">Comunicação com o cliente</div>\n    <div class=\"form-group\"><label>E-mail de atendimento / cópia dos comprovantes</label>\n      <input name=\"email_copia\" value=\"{{ cfg.email_copia }}\" class=\"form-control\"></div>\n    <div class=\"form-group\"><label>Dados para depósito (aparecem para o cliente depois que ele assina)</label>\n      <textarea name=\"instrucoes_deposito\" rows=\"4\" class=\"form-control\" placeholder=\"Banco, agência, conta, titular, CNPJ ou chave PIX da Capuzzo\">{{ cfg.instrucoes_deposito }}</textarea></div>\n  </div>\n\n  <div class=\"page-actions\"><button class=\"btn btn-primary\">✓ Salvar</button></div>\n</form>\n{% endblock %}\n",
  "contratos/detalhe.html": "{% extends \"base.html\" %}\n{% block title %}{{ c.cliente_nome }} · Contrato — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n{% include \"contratos/_estilo.html\" %}\n{% set st = STATUS[c.status] %}\n<style>\n.ct-dlg{margin:auto;border:1px solid #333;border-radius:10px;background:#141414;color:#eee;padding:0;width:min(520px,94vw)}\n.ct-dlg::backdrop{background:rgba(0,0,0,.7)}\n.ct-dlg form{padding:22px}\n.ct-dlg h3{margin:0 0 6px;font-size:18px}\n.ct-dlg p{color:#aaa;font-size:13px;margin:0 0 12px}\n.ct-dlg .opc{display:flex;gap:10px;align-items:flex-start;font-size:13px;margin:10px 0;cursor:pointer}\n.ct-dlg .opc input{width:16px;height:16px;margin-top:2px;accent-color:#d4af37}\n.ct-dlg .bts{display:flex;flex-wrap:wrap;gap:8px;justify-content:flex-end;margin-top:16px}\n</style>\n\n<a href=\"{{ url_for('contratos.painel') }}\" class=\"back-link\">← Voltar para Contratos</a>\n\n<div class=\"page-header\" style=\"display:flex;justify-content:space-between;align-items:flex-start;gap:16px;flex-wrap:wrap;\">\n  <div>\n    <div class=\"page-header-title\">{{ TIPOS[c.tipo] }} · {{ c.cliente_nome }}</div>\n    <div class=\"page-header-sub\" style=\"margin-top:6px;\">\n      <span class=\"ct-badge\" style=\"--c:{{ st.cor }}\">{{ st.nome }}</span>\n      &nbsp;{{ c.produto_nome }} · {{ c.dados.qtd }} cota(s) · <span class=\"text-gold\">{{ moeda(c.dados.valor_total) }}</span>\n      · <span class=\"text-mono text-dim\" style=\"font-size:11px\">{{ c.codigo }}</span>\n    </div>\n  </div>\n  <div style=\"display:flex;gap:8px;flex-wrap:wrap;\">\n    <a href=\"{{ url_for('contratos.documento', cid=c.id) }}\" target=\"_blank\" class=\"btn btn-secondary\">↗ Abrir documento</a>\n    <a href=\"{{ url_for('contratos.documento', cid=c.id, imprimir=1) }}\" target=\"_blank\" class=\"btn btn-secondary\">⬇ PDF</a>\n    <a href=\"{{ url_for('clientes_detalhe', cid=c.client_id) }}\" class=\"btn btn-secondary\">👤 Cliente</a>\n    {% if c.status in ('rascunho', 'aguardando', 'assinado') %}\n    <button type=\"button\" class=\"btn btn-danger\" data-abrir=\"dlg-cancelar\">⛔ Cancelar envio</button>\n    {% endif %}\n    {% if c.status != 'concluido' %}\n    <button type=\"button\" class=\"btn btn-secondary\" data-abrir=\"dlg-excluir\" title=\"Apagar contrato de teste ou gerado por engano\">🗑️ Apagar</button>\n    {% endif %}\n  </div>\n</div>\n\n<div class=\"ct-grid\">\n  <div class=\"ct-doc\"><iframe src=\"{{ url_for('contratos.documento', cid=c.id) }}\" title=\"Documento\"></iframe></div>\n\n  <div class=\"ct-side\">\n\n    {# ── Ações por etapa ── #}\n    <div class=\"card-gold\">\n      {% if c.status in ('rascunho', 'aguardando') %}\n        <div class=\"form-section-title\" style=\"margin-bottom:10px;\">\n          {{ '1. Enviar para assinatura' if c.status == 'rascunho' else 'Aguardando assinatura do cliente' }}</div>\n        {% if link_local %}\n          <div class=\"alert alert-warning\" style=\"font-size:12px;margin-bottom:10px;\"><span>O link ainda aponta para este computador — o cliente não conseguirá abrir de fora.\n            Configure o <a class=\"text-gold\" href=\"{{ url_for('contratos.configuracoes') }}\">link público</a>.</span></div>\n        {% endif %}\n        <div class=\"ct-acoes\">\n          <form method=\"post\" action=\"{{ url_for('contratos.enviar', cid=c.id) }}\">\n            <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n            <button class=\"btn btn-primary\" style=\"width:100%\" {{ 'disabled' if not cli.email }}>\n              ✉️ {{ 'Enviar para assinatura' if c.status == 'rascunho' else 'Reenviar e-mail' }}</button>\n            <div class=\"text-dim\" style=\"font-size:11px;margin-top:4px;text-align:center\">para {{ cli.email or 'cliente sem e-mail' }}</div>\n          </form>\n          {% if fone_wpp %}\n          <a class=\"btn btn-secondary js-manual\" data-canal=\"WhatsApp\" target=\"_blank\" rel=\"noopener\"\n             href=\"https://wa.me/{{ fone_wpp }}?text={{ msg_wpp | urlencode }}\">🟢 Enviar link pelo WhatsApp</a>\n          {% endif %}\n          <div class=\"ct-link\">\n            <input class=\"form-control form-control-sm\" id=\"ct-link\" value=\"{{ link }}\" readonly>\n            <button type=\"button\" class=\"btn btn-secondary btn-sm\" id=\"ct-copiar\">Copiar</button>\n          </div>\n        </div>\n      {% elif c.status == 'assinado' %}\n        <div class=\"form-section-title\" style=\"margin-bottom:8px;\">2. Confirmar depósito e ativar cotas</div>\n        <p class=\"text-dim\" style=\"font-size:12.5px;margin-bottom:10px;\">O cliente assinou. As cotas seguem <b>pendentes</b> até você confirmar o depósito.</p>\n        <form method=\"post\" action=\"{{ url_for('contratos.ativar', cid=c.id) }}\" id=\"f-ativar\">\n          <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n          <div class=\"form-group\"><label>Data do depósito</label>\n            <input type=\"date\" name=\"data_deposito\" id=\"dt-dep\" value=\"{{ hoje }}\" class=\"form-control\"></div>\n          <table class=\"ct-cotas\" style=\"width:100%;margin:6px 0 12px;\">\n            <thead><tr><th>Cota</th><th>Aquisição</th><th>Vencimento</th></tr></thead>\n            <tbody>\n            {% for ct in c.cotas %}\n              <tr><td class=\"text-mono\">{{ ct.share_number }}</td>\n                <td><input type=\"date\" name=\"aq_{{ ct.id }}\" value=\"{{ aq_sugerida }}\" class=\"form-control form-control-sm js-aq\"></td>\n                <td><input type=\"date\" name=\"venc_{{ ct.id }}\" value=\"{{ venc_sugerido }}\" class=\"form-control form-control-sm js-venc\"></td></tr>\n            {% endfor %}\n            </tbody>\n          </table>\n          <div class=\"text-dim\" style=\"font-size:11px;margin-bottom:10px;\">Vencimento sugerido = aquisição + {{ c.dados.prazo_meses }} meses (prazo mínimo do termo).</div>\n          <button class=\"btn btn-success\" style=\"width:100%\" data-confirm=\"Confirmar o depósito e ativar {{ c.cotas|length }} cota(s)?\">✔ Confirmar depósito e ativar cotas</button>\n        </form>\n      {% elif c.status == 'concluido' %}\n        <div class=\"form-section-title\" style=\"margin-bottom:8px;\">✅ Concluído</div>\n        <p class=\"text-dim\" style=\"font-size:13px;\">Depósito confirmado e cotas ativadas em {{ c.concluido_em | ct_data(True) }}.</p>\n      {% else %}\n        <div class=\"form-section-title\" style=\"margin-bottom:8px;\">Contrato cancelado</div>\n        <p class=\"text-dim\" style=\"font-size:13px;\">{{ c.cancelado_em | ct_data(True) }}{% if c.motivo_cancelamento %} — {{ c.motivo_cancelamento }}{% endif %}</p>\n        <a href=\"{{ url_for('contratos.novo', client_id=c.client_id) }}\" class=\"btn btn-secondary btn-sm\" style=\"margin-top:8px\">Gerar novo contrato</a>\n      {% endif %}\n    </div>\n\n    {# ── Signatários ── #}\n    <div class=\"card-gold\">\n      <div class=\"form-section-title\" style=\"margin-bottom:6px;\">Signatários</div>\n      {% for s in c.signatarios %}\n      <div class=\"ct-sig\">\n        <span class=\"ct-dot {{ 'ok' if s.status == 'assinado' }}\">{{ '✔' if s.status == 'assinado' }}</span>\n        <div style=\"min-width:0\">\n          <b>{{ s.nome }}</b> <span class=\"text-dim\" style=\"font-size:11px\">· {{ 'Empresa' if s.papel == 'empresa' else 'Investidor(a)' }}</span>\n          <div class=\"text-dim\" style=\"font-size:12px\">{{ s.email or '—' }}</div>\n          <div style=\"font-size:12px;color:{{ '#4ade80' if s.status == 'assinado' else '#fbbf24' }}\">\n            {{ 'Assinou em ' ~ (s.assinado_em | ct_data(True)) ~ (' · IP ' ~ s.ip if s.ip else '') if s.status == 'assinado' else 'Aguardando assinatura' }}</div>\n        </div>\n      </div>\n      {% endfor %}\n    </div>\n\n    {# ── Cotas ── #}\n    <div class=\"card-gold\">\n      <div class=\"form-section-title\" style=\"margin-bottom:6px;\">Cotas deste contrato</div>\n      {% for ct in c.cotas %}\n      <div style=\"display:flex;justify-content:space-between;font-size:13px;padding:4px 0;border-top:1px solid #222\">\n        <span class=\"text-mono\">nº {{ ct.share_number }}</span>\n        <span>{{ moeda(ct.share_value) }}</span>\n        <span class=\"badge {{ 'badge-active' if ct.status == 'ativa' else ('badge-pending' if ct.status == 'pendente' else 'badge-inactive') }}\">{{ ct.status }}</span>\n      </div>\n      {% endfor %}\n    </div>\n\n    {# ── Histórico ── #}\n    <div class=\"card-gold\">\n      <div class=\"form-section-title\" style=\"margin-bottom:10px;\">Histórico</div>\n      {% for e in c.eventos | reverse %}\n      <div class=\"ct-ev {{ 'erro' if e.tipo in ('email_erro', 'codigo_invalido', 'cancelado') }}\">\n        <b>{{ EVENTOS.get(e.tipo, e.tipo) }}</b>\n        <span>{{ e.criado_em | ct_data(True) }}{% if e.ip %} · IP {{ e.ip }}{% endif %}</span>\n        {% if e.descricao %}<div style=\"font-size:12px;color:#aaa\">{{ e.descricao }}</div>{% endif %}\n      </div>\n      {% endfor %}\n    </div>\n\n  </div>\n</div>\n\n\n{# ── Cancelar envio ── #}\n<dialog class=\"ct-dlg\" id=\"dlg-cancelar\">\n  <form method=\"post\" action=\"{{ url_for('contratos.cancelar', cid=c.id) }}\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n    <h3>⛔ Cancelar envio do contrato</h3>\n    <p>O link de assinatura deixa de funcionar e o documento passa a mostrar <b>CANCELADO</b>.\n      {% if c.status == 'assinado' %}<b style=\"color:#f87171\">A assinatura já feita pelo cliente perde a validade.</b>{% endif %}\n      As cotas continuam pendentes.</p>\n    <div class=\"form-group\"><label>Motivo</label>\n      <input name=\"motivo\" class=\"form-control\" placeholder=\"Ex.: CPF digitado errado, valor incorreto…\" maxlength=\"300\"></div>\n    {% if c.status in ('aguardando', 'assinado') and cli.email %}\n    <label class=\"opc\"><input type=\"checkbox\" name=\"avisar\" value=\"1\" checked>\n      <span>Avisar o cliente por e-mail que o documento foi cancelado ({{ cli.email }})</span></label>\n    {% endif %}\n    <div class=\"note-box\" style=\"font-size:12px;margin-top:8px\">💡 Se o erro é no cadastro do cliente, primeiro\n      <a class=\"text-gold\" href=\"{{ url_for('clientes_editar', cid=c.client_id) }}#secao-contrato\">corrija o cadastro</a>\n      e depois use <b>Cancelar e gerar novo</b>: o novo contrato sai com as mesmas cotas e os dados atualizados.</div>\n    <div class=\"bts\">\n      <button type=\"button\" class=\"btn btn-secondary\" data-fechar>Voltar</button>\n      <button name=\"acao\" value=\"cancelar\" class=\"btn btn-danger\">Só cancelar</button>\n      <button name=\"acao\" value=\"regerar\" class=\"btn btn-primary\">Cancelar e gerar novo</button>\n    </div>\n  </form>\n</dialog>\n\n{# ── Apagar ── #}\n<dialog class=\"ct-dlg\" id=\"dlg-excluir\">\n  <form method=\"post\" action=\"{{ url_for('contratos.excluir', cid=c.id) }}\" id=\"f-excluir\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n    <h3>🗑️ Apagar contrato</h3>\n    <p>Use para contratos de <b>teste</b> ou gerados por engano. O contrato e todo o histórico de assinatura são\n      apagados definitivamente (fica só o registro na Auditoria). O link enviado para o cliente deixa de existir.</p>\n    {% set pend = c.cotas | selectattr('status','equalto','pendente') | list %}\n    {% if pend %}\n    <label class=\"opc\"><input type=\"checkbox\" name=\"excluir_cotas\" value=\"1\">\n      <span>Apagar também as cotas pendentes deste contrato ({{ pend | map(attribute='share_number') | join(', ') }})</span></label>\n    {% endif %}\n    <div class=\"form-group\" style=\"margin-top:10px\"><label>Digite <b>APAGAR</b> para confirmar</label>\n      <input class=\"form-control\" id=\"conf-apagar\" autocomplete=\"off\"></div>\n    <div class=\"bts\">\n      <button type=\"button\" class=\"btn btn-secondary\" data-fechar>Voltar</button>\n      <button class=\"btn btn-danger\" id=\"bt-apagar\" disabled>Apagar definitivamente</button>\n    </div>\n  </form>\n</dialog>\n<script>\n(function(){\n  document.querySelectorAll('[data-abrir]').forEach(function(b){ b.addEventListener('click', function(){\n    var dl = document.getElementById(b.dataset.abrir); if(dl && dl.showModal) dl.showModal(); }); });\n  document.querySelectorAll('[data-fechar]').forEach(function(b){ b.addEventListener('click', function(){ b.closest('dialog').close(); }); });\n  var ca = document.getElementById('conf-apagar'), ba = document.getElementById('bt-apagar');\n  if(ca) ca.addEventListener('input', function(){ ba.disabled = ca.value.trim().toUpperCase() !== 'APAGAR'; });\n  var csrf = '{{ csrf_token() }}';\n  function manual(canal){\n    var fd = new FormData(); fd.append('_csrf', csrf); fd.append('canal', canal);\n    fetch('{{ url_for(\"contratos.enviado_manual\", cid=c.id) }}', {method:'POST', body:fd, credentials:'same-origin'});\n  }\n  var cp = document.getElementById('ct-copiar');\n  if(cp) cp.addEventListener('click', function(){\n    var i = document.getElementById('ct-link'); i.select();\n    (navigator.clipboard ? navigator.clipboard.writeText(i.value) : Promise.resolve(document.execCommand('copy')))\n      .then(function(){ cp.textContent = 'Copiado ✓'; manual('link copiado'); });\n  });\n  document.querySelectorAll('.js-manual').forEach(function(a){ a.addEventListener('click', function(){ manual(a.dataset.canal); }); });\n\n\n  /* datas de ativação: aquisição = depósito; vencimento = aquisição + prazo */\n  var dep = document.getElementById('dt-dep'), prazo = {{ c.dados.prazo_meses | int }};\n  function somaMeses(iso, n){\n    var p = iso.split('-').map(Number), d = new Date(p[0], p[1]-1+n, 1), ult = new Date(d.getFullYear(), d.getMonth()+1, 0).getDate();\n    d.setDate(Math.min(p[2], ult));\n    return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');\n  }\n  if(dep) dep.addEventListener('change', function(){\n    if(!dep.value) return;\n    document.querySelectorAll('.js-aq').forEach(function(i){ i.value = dep.value; });\n    document.querySelectorAll('.js-venc').forEach(function(i){ i.value = somaMeses(dep.value, prazo); });\n  });\n  document.querySelectorAll('.js-aq').forEach(function(i){\n    i.addEventListener('change', function(){\n      var v = i.closest('tr').querySelector('.js-venc'); if(i.value) v.value = somaMeses(i.value, prazo);\n    });\n  });\n})();\n</script>\n{% endblock %}\n",
  "contratos/doc/_item_corretoras.html": "<li>Autoriza a Contratada a representar o Condomínio perante quaisquer corretoras de câmbio, títulos, ativos e\n  valores mobiliários, nacionais e/ou internacionais, inclusive com poderes para elaborar cadastros, obter e\n  prestar informações, podendo negociar, comprar, vender, endossar, ceder, onerar, transferir, resgatar,\n  reinvestir, tomar emprestado e emprestar títulos, valores mobiliários e ativos financeiros, incluindo-se ações,\n  títulos de dívida, cotas de fundos, derivativos ou quaisquer outros ativos disponíveis nos Mercados; a requerer\n  a emissão de cautelas e títulos múltiplos, depositar, custodiar ou solicitar a custódia, agrupar, desdobrar,\n  subscrever ações ou quaisquer outros ativos; a resgatar títulos, retirar cautelas e títulos múltiplos\n  representativos de ações e debêntures; aplicar e resgatar valores em fundos de renda fixa ou variável ou\n  qualquer outro tipo de investimento; abrir, movimentar e encerrar contas de custódia; fechar operações de\n  compra e venda de moeda estrangeira; executar quaisquer operações de mercado à vista, disponível, a termo, a\n  futuro, de índice e de opções, sendo os custos relacionados ao exercício de tais direitos suportados\n  integralmente pela própria Contratada.</li>\n",
  "contratos/doc/documento.html": "<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<title>{{ d.arquivo or 'contrato' }}</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Carlito:ital,wght@0,400;0,700;1,400&family=Great+Vibes&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{--ouro:#B8962E;--tinta:#141414;--cinza:#5f5f5f;--linha:#d9d4c7}\n  *{box-sizing:border-box}\n  html,body{margin:0;background:#e9e6df;color:var(--tinta)}\n  body{font-family:Calibri,Carlito,\"Segoe UI\",Arial,sans-serif;font-size:14.5px;line-height:1.45}\n  .barra{position:sticky;top:0;z-index:5;display:flex;gap:10px;align-items:center;justify-content:space-between;\n         padding:10px 16px;background:#111;color:#eee;font:13px \"Segoe UI\",Arial,sans-serif}\n  .barra b{color:#d4af37}\n  .barra button{background:#d4af37;color:#111;border:0;border-radius:6px;padding:8px 14px;font-weight:700;cursor:pointer}\n  .folha{position:relative;width:210mm;min-height:297mm;margin:18px auto;background:#fff;padding:16mm 20mm 22mm;\n         box-shadow:0 2px 14px rgba(0,0,0,.18);overflow:hidden}\n  .folha.termo{min-height:auto;padding-bottom:2mm;margin-bottom:0;box-shadow:0 -2px 14px rgba(0,0,0,.12)}\n  .folha.continua{min-height:auto;margin-top:0;padding-top:2mm;padding-bottom:26mm;box-shadow:0 8px 14px -6px rgba(0,0,0,.18)}\n  .rodape{position:absolute;left:20mm;right:20mm;bottom:7mm;font:9px/1.35 Arial,sans-serif;color:#8a8a8a;\n          border-top:1px solid #eee;padding-top:4px}\n  /* termo */\n  .cab-termo{display:block;width:100%;max-width:165mm;margin:-6mm auto 6mm}\n  .t-titulo{font-size:27px;margin:8mm 0 7mm;font-weight:700;letter-spacing:-.3px}\n  .t-abre{font-family:\"Times New Roman\",serif;font-size:15.5px;margin:0 0 5mm}\n  .t-just{text-align:justify;margin:0 0 4mm}\n  .t-lista{padding-left:0;margin:0 0 5mm;counter-reset:it;list-style:none}\n  .t-lista>li{counter-increment:it;text-align:justify;margin:0 0 1.5mm;padding-left:0}\n  .t-lista>li::before{content:counter(it) \".\";display:inline-block;min-width:11mm;padding-left:2mm}\n  .t-cotas{border-collapse:collapse;margin:5mm auto 5mm;width:92%;font-size:13.5px}\n  .t-cotas th{background:#cfe2cf;color:#3b5b3b;font-weight:700;border:1px solid #333;padding:3px 6px;text-align:center}\n  .t-cotas td{border:1px solid #333;padding:2px 6px;text-align:center}\n  .t-cotas tr.tot td{font-weight:700;background:#f6f6f6}\n  .t-cotas td.t-rent{font-size:12px;max-width:62mm}\n  .t-data{text-align:right;font-weight:700;margin:6mm 0 0}\n  /* assinaturas */\n  .assin{margin:6mm 0 0 6mm;max-width:120mm}\n  .assin .bloco{margin:0 0 7mm}\n  .assin .visual{height:20mm;display:flex;align-items:flex-end;gap:10px;position:relative}\n  .assin .visual img{max-height:19mm;max-width:80mm}\n  .assin .cursiva{font-family:\"Great Vibes\",\"Segoe Script\",\"Brush Script MT\",cursive;font-size:28px;line-height:1.1;color:#1d2a5a;white-space:nowrap}\n  .assin .selo{display:inline-flex;align-items:center;gap:6px;border:1.5px solid #3aa35b;border-left-width:5px;color:#2d7d46;\n               border-radius:4px;padding:2px 7px;font:10px/1.25 Arial,sans-serif;background:#f4fbf6;white-space:nowrap}\n  .assin .selo.pend{border-color:#c9a227;color:#8a6d0f;background:#fffaf0}\n  .assin .linha{border-top:1px solid #222;padding-top:1mm;font-weight:700}\n  .assin .meta{font:10px Arial,sans-serif;color:#777}\n  .testemunhas{margin:4mm 0 0 6mm}\n  .testemunhas p{margin:0}\n  /* regulamento */\n  .regulamento{font-family:Tahoma,Verdana,\"Segoe UI\",sans-serif;font-size:12.6px;line-height:1.55}\n  .regulamento::before{content:\"\";position:absolute;inset:45mm 0 20mm;background-image:var(--marca);background-repeat:repeat-y;\n                       background-size:150mm auto;background-position:center top;opacity:.32;pointer-events:none}\n  .regulamento>*{position:relative}\n  .cab-reg{display:block;width:62mm;margin:-6mm auto 8mm}\n  .r-titulo{font-size:15px;margin:6mm 0 10mm;line-height:1.6}\n  .regulamento h2{font-size:13px;margin:7mm 0 3mm}\n  .regulamento p{text-align:justify;margin:0 0 3mm}\n  .regulamento p.inc{margin-left:6mm}\n  .regulamento ul{margin:0 0 3mm 16mm;padding:0}\n  .regulamento ul.sub{margin-left:12mm}\n  .regulamento li{margin:0 0 1.2mm}\n  .r-series{border-collapse:collapse;width:100%;font-size:10px;margin:2mm 0 5mm;background:#fff}\n  .r-series th,.r-series td{border:1px solid #333;padding:2px 4px}\n  .r-series th{font-weight:700;text-align:center}\n  .r-data{margin-top:10mm;font-size:14px}\n  /* certificado */\n  .cert{font-family:\"Segoe UI\",Arial,sans-serif;font-size:12.5px;border:9px double #c9b46a;padding:12mm 14mm 22mm}\n  .cert h1{font-size:20px;margin:0}\n  .cert .topo{display:flex;justify-content:space-between;gap:12px;border-bottom:2px solid #eee;padding-bottom:4mm;margin-bottom:5mm}\n  .cert .topo small{color:#777;display:block}\n  .cert h2{font-size:16px;font-weight:600;margin:6mm 0 3mm}\n  .cert .sig{display:flex;gap:10px;align-items:flex-start;margin:0 0 3mm}\n  .cert .bola{width:22px;height:22px;border-radius:50%;border:2.5px solid #bbb;flex:none;display:grid;place-items:center;font-size:12px;color:#fff}\n  .cert .bola.ok{border-color:#3aa35b;background:#3aa35b}\n  .cert .ev{margin:0 0 3.5mm}\n  .cert .ev b{display:block}\n  .cert .ev span{color:#555}\n  .cert .hash{font:9.5px/1.4 Consolas,\"Courier New\",monospace;word-break:break-all;color:#444}\n  .cert .aviso{margin-top:6mm;font-size:11px;color:#555;border-top:1px solid #eee;padding-top:3mm}\n  .cancelado-aviso{max-width:210mm;margin:14px auto 0;background:#fdecec;border:2px solid #b42318;color:#7a1610;\n                   border-radius:6px;padding:10px 14px;font:14px \"Segoe UI\",Arial,sans-serif}\n  body.cancelado .folha::after{content:\"CANCELADO\";position:absolute;top:38%;left:50%;transform:translate(-50%,-50%) rotate(-30deg);\n       font:800 120px/1 Arial,sans-serif;color:rgba(180,35,24,.16);letter-spacing:10px;pointer-events:none;white-space:nowrap}\n  @page{size:A4;margin:0}\n  @media print{\n    html,body{background:#fff}\n    .barra{display:none}\n    .folha{margin:0;box-shadow:none;page-break-after:always;break-after:page}\n    .folha.continua{margin:0;page-break-before:avoid}\n    .termo{page-break-after:avoid;break-after:avoid;min-height:auto}\n    .folha:last-child{page-break-after:auto}\n  }\n  @media (max-width:820px){\n    .folha{width:auto;min-height:0;margin:10px;padding:18px 16px 40px}\n    .rodape{left:16px;right:16px}\n    .t-cotas{width:100%;font-size:12px}\n  }\n</style>\n</head>\n<body class=\"{{ 'cancelado' if c.status == 'cancelado' }}\">\n{% set cli = c.signatarios | selectattr('papel','equalto','cliente') | first %}\n{% set emps = c.signatarios | selectattr('papel','equalto','empresa') | list %}{% set emp = emps[0] if emps else none %}\n<div class=\"barra\">\n  <span>📄 <b>{{ d.investidor.nome }}</b> · {{ TIPOS[c.tipo] }}{{ ' + Regulamento' if c.html_anexo }}</span>\n  <button type=\"button\" onclick=\"window.print()\">⬇ Baixar PDF / Imprimir</button>\n</div>\n\n{% if c.status == 'cancelado' %}\n<div class=\"cancelado-aviso\"><b>⛔ DOCUMENTO CANCELADO em {{ c.cancelado_em | ct_data(True) }}</b> — sem validade; assinaturas invalidadas.\n  {% if c.motivo_cancelamento and not publico %}Motivo: {{ c.motivo_cancelamento }}{% endif %}</div>\n{% endif %}\n{# ═══ 1. Termo (conteúdo original, protegido por hash) ═══ #}\n{{ c.html_termo | safe }}\n\n{# ═══ Assinaturas ═══ #}\n<section class=\"folha continua\">\n  <div class=\"assin\">\n    {% for s in [cli, emp] if s %}\n    <div class=\"bloco\">\n      <div class=\"visual\">\n        {% if s.status == 'assinado' %}\n          {% if s.assinatura_img %}<img src=\"{{ s.assinatura_img }}\" alt=\"Assinatura\">{% else %}<span class=\"cursiva\">{{ s.assinatura_texto }}</span>{% endif %}\n          <span class=\"selo\">✔ Assinado eletronicamente<br>{{ s.assinado_em | ct_data(True) }}</span>\n        {% else %}\n          <span class=\"selo pend\">⏳ Aguardando assinatura</span>\n        {% endif %}\n      </div>\n      <div class=\"linha\">{{ s.nome if s.papel == 'cliente' else d.empresa.empresa_nome }}</div>\n      <div class=\"meta\">{{ mascarar(s.email) if publico else s.email }}</div>\n    </div>\n    {% endfor %}\n  </div>\n  {% if d.testemunhas %}\n  <div class=\"testemunhas\">\n    <p><b>Testemunhas:</b></p><br>\n    {% for t in d.testemunhas %}<p>Nome: {{ t.nome }}</p><p>CPF: {{ t.cpf }}</p>{% endfor %}\n  </div>\n  {% endif %}\n  <div class=\"rodape\">Documento {{ c.codigo }} · Assinatura eletrônica conforme MP 2.200-2/2001, art. 10, §2º, e Lei 14.063/2020.\n    Verificação no certificado de assinaturas ao final deste documento.</div>\n</section>\n\n{# ═══ 2. Regulamento (anexo) ═══ #}\n{{ c.html_anexo | safe }}\n\n{# ═══ 3. Certificado de assinaturas ═══ #}\n<section class=\"folha cert\">\n  <div class=\"topo\">\n    <div><h1>Certificado de Assinaturas</h1><small>Capuzzo Assessoria Empresarial · horários de Brasília</small></div>\n    <div style=\"text-align:right\"><small>Gerado em</small>{{ c.assinado_em | ct_data(True) if c.assinado_em else '—' }}</div>\n  </div>\n  <div style=\"font-size:15px\">{{ d.arquivo }}</div>\n  <div>Código do documento <b>{{ c.codigo }}</b></div>\n  {% if d.anexo_nome %}<div style=\"font-size:11px;color:#666;margin-top:2mm\">Anexo: {{ d.anexo_nome }}</div>{% endif %}\n\n  <h2>Assinaturas</h2>\n  {% for s in [cli, emp] if s %}\n  <div class=\"sig\">\n    <div class=\"bola {{ 'ok' if s.status == 'assinado' }}\">{{ '✔' if s.status == 'assinado' }}</div>\n    <div><b>{{ s.nome }}</b><br>{{ mascarar(s.email) if publico else s.email }}<br>\n      {% if s.status == 'assinado' %}Assinou em {{ s.assinado_em | ct_data(True) }} · IP {{ s.ip or '—' }}\n        <br><span style=\"color:#666;font-size:11px\">Verificação: {{ s.verificacao }}</span>\n      {% else %}<span style=\"color:#8a6d0f\">Assinatura pendente</span>{% endif %}</div>\n  </div>\n  {% endfor %}\n\n  <h2>Eventos do documento</h2>\n  {% for e in c.eventos if e.tipo not in ('codigo_invalido', 'email_erro') %}\n  <div class=\"ev\"><b>{{ e.criado_em | ct_data(True) }}</b>\n    <span>{{ EVENTOS.get(e.tipo, e.tipo) }}{% if e.descricao and not publico %} — {{ e.descricao }}{% endif %}{% if e.ip %} · IP {{ e.ip }}{% endif %}</span></div>\n  {% endfor %}\n\n  <h2>Hash do documento original ({{ 'Termo + Regulamento' if c.html_anexo else 'Termo' }})</h2>\n  <div class=\"hash\">(SHA256) {{ c.hash_original }}</div>\n  {% if c.hash_final %}\n  <h2>Hash do registro de assinatura</h2>\n  <div class=\"hash\">(SHA256) {{ c.hash_final }}</div>\n  {% endif %}\n  <div class=\"aviso\">Documento assinado eletronicamente. A autoria e a integridade são comprovadas pelos registros acima\n    (e-mail com código de verificação, confirmação do CPF/CNPJ, data, hora e IP), nos termos da MP 2.200-2/2001,\n    art. 10, §2º, e da Lei 14.063/2020. Este log pertence única e exclusivamente ao documento de hash acima.</div>\n</section>\n\n<script>if(window.self !== window.top){ var b=document.querySelector('.barra'); if(b) b.style.display='none'; }</script>\n{% if imprimir %}<script>window.addEventListener('load',function(){setTimeout(function(){window.print()},400)})</script>{% endif %}\n</body>\n</html>\n",
  "contratos/doc/regulamento_civil_2026.html": "<section class=\"folha regulamento\" style=\"--marca:url('{{ marca }}')\">\n  <img class=\"cab-reg\" src=\"{{ cab }}\" alt=\"Capuzzo Assessoria Empresarial\">\n  <h1 class=\"r-titulo\">REGULAMENTO DO CONDOMÍNIO DE<br>INVESTIMENTO PRIVADO FECHADO</h1>\n\n  <h2>CAPÍTULO I – DISPOSIÇÕES INICIAIS</h2>\n  <p><b>Artigo 1º –</b> O Condomínio de Investimento Privado Fechado, doravante denominado “Condomínio”, é organizado sob a forma de condomínio fechado, sendo suas cotas resgatáveis nos termos e condições deste Regulamento e do respectivo Termo de Aquisição de Cotas, observado o Prazo de Duração aplicável.</p>\n  <p><b>Artigo 2º –</b> O Condomínio destina-se a receber aplicações exclusivamente de grupo reservado de investidores, por meio de oferta privada, conforme disponibilização de cotas pela Gestora.</p>\n  <p><b>Artigo 3º –</b> A adesão do investidor às regras deste Regulamento dar-se-á mediante (i) assinatura do Termo de Aquisição de Cotas e (ii) efetiva integralização da(s) cota(s), ocasião em que será realizado o respectivo registro no Livro/Registro de Cotistas.</p>\n  <p><b>Artigo 4º –</b> Para fins deste Regulamento, aplicam-se as seguintes definições:</p>\n  <p>“Gestora”: CAPUZZO ASSESSORIA EMPRESARIAL LTDA, responsável pela administração e gestão do Condomínio.</p>\n  <p>“Cota Única Garantidora”: cota da série “Garantidora”, com valor nominal de R$ 1.000.000,00 (um milhão de reais), destinada a compor categoria adicional de garantia.</p>\n  <p>“Cotas Seriadas”: cotas da série “Pré-fixada”, com valor nominal unitário de R$ 10.000,00 (dez mil reais).</p>\n  <p>“Rentabilidade”: remuneração mensal devida aos cotistas conforme série, calculada pro rata die.</p>\n  <p>“Prazo de Duração”: prazo contratual mínimo e/ou prazo de vigência pactuado no Termo de Aquisição, observado o mínimo definido neste Regulamento.</p>\n  <p>“Prazo de Manifestação”: prazo mínimo de 30 (trinta) dias corridos anteriores à Data de Vencimento, para que o cotista manifeste, pelos canais de atendimento da Gestora, sua opção por resgate, por não renovação, ou por quaisquer instruções aplicáveis ao encerramento/renovação do Prazo de Duração.</p>\n  <p>“Dia de Pagamento”: dia-base mensal para pagamento da Rentabilidade (dia 6), conforme Capítulo IV.</p>\n  <p>“Renovação Automática”: renovação do Prazo de Duração por igual período, na ausência de manifestação tempestiva do cotista no Prazo de Manifestação, na forma do Artigo 24-A.</p>\n\n  <h2>CAPÍTULO II – ADMINISTRAÇÃO, GOVERNANÇA E PRESTADORES DE SERVIÇOS</h2>\n  <p><b>Artigo 5º –</b> O Condomínio é administrado e gerido pela Gestora, que poderá, observadas as disposições e limitações legais e regulamentares, às suas expensas, nos termos deste Regulamento:</p>\n  <ul>\n    <li>Negociar e contratar, em nome do Condomínio, os ativos financeiros descritos em sua política de investimentos;</li>\n    <li>Exercer atividades de tesouraria e controle dos ativos financeiros;</li>\n    <li>Praticar todos os atos necessários ao bom funcionamento e manutenção do Condomínio;</li>\n    <li>Abrir e movimentar contas bancárias e contas em corretoras de câmbio, títulos e valores mobiliários.</li>\n  </ul>\n  <p><b>Artigo 6º –</b> São obrigações da gestora:</p>\n  <p class=\"inc\">I – Diligenciar para que sejam mantidos, às suas expensas, atualizados e em perfeita ordem:</p>\n  <ul class=\"sub\">\n    <li>o registro de cotistas;</li>\n    <li>os registros contábeis referentes às operações e ao patrimônio do Condomínio;</li>\n    <li>a documentação relativa às operações do Condomínio.</li>\n  </ul>\n  <p class=\"inc\">II – Pagar a multa cominatória por dia de atraso, nos termos deste Regulamento, nos casos de descumprimento dos prazos fixados;</p>\n  <p class=\"inc\">III – Elaborar e divulgar as informações previstas neste Regulamento aos cotistas periodicamente e;</p>\n  <p class=\"inc\">IV – Manter o serviço de atendimento ao cotista, responsável pelo esclarecimento de dúvidas e pelo recebimento de relamações;</p>\n  <p><b>Artigo 7º –</b> A Gestora deverá observar normas de conduta pautadas por diligência, lealdade e atuação no melhor interesse do Condomínio e dos cotistas, adotando as medidas cabíveis para defesa de seus direitos e da higidez operacional.</p>\n  <p><b>Artigo 8º –</b> É vedado à Gestora, no que aplicável, praticar os seguintes atos em nome do Condomínio:</p>\n  <p class=\"inc\">I – Prestar fiança, aval, aceite ou coobrigar-se sob qualquer outra forma;</p>\n  <p class=\"inc\">II – Utilizar recursos do Condomínio para pagamento de seguro contra perdas financeiras de cotistas; e</p>\n  <p class=\"inc\">III – Praticar qualquer ato de liberalidade.</p>\n  <p><b>Artigo 9º –</b> Os serviços de auditoria poderão ser realizados a qualquer tempo por empresa independente externa, e, adicionalmente, a Gestora poderá realizar auditorias internas periódicas, inclusive mensais, a seu critério.</p>\n\n  <h2>CAPÍTULO III – OBJETIVO E POLÍTICA DE INVESTIMENTOS</h2>\n  <p><b>Artigo 10º –</b> O Condomínio tem por objetivo a comunhão de recursos destinados à realização de operações financeiras e investimentos, buscando rentabilidade compatível com o risco assumido, observadas as condições deste Regulamento e do Termo de Aquisição.</p>\n  <p><b>Artigo 11º –</b> O Condomínio poderá aplicar seus recursos, conforme estratégia definida pela Gestora, em ativos financeiros, tais como:</p>\n  <ul>\n    <li>Antecipação de recebíveis de títulos de crédito públicos e privados;</li>\n    <li>Ações, ETFs e índices;</li>\n    <li>Câmbio e commodities;</li>\n    <li>Debêntures e renda fixa;</li>\n    <li>Participação/constituição de Sociedades de Propósito Específico (SPEs), inclusive voltadas à construção civil.</li>\n  </ul>\n  <p><b>Artigo 12º –</b> A distribuição dos ativos deverá observar critério de diversificação, de modo que a concentração máxima em cada classe/ativo não ultrapasse 30% (trinta por cento) do volume financeiro total do Condomínio, salvo deliberação justificada da Gestora em cenário excepcional, devidamente comunicada aos cotistas.</p>\n\n  <h2>CAPÍTULO IV – COTAS, INTEGRALIZAÇÃO, RENTABILIDADE E LIMITES</h2>\n  <p><b>Artigo 13º –</b> O patrimônio do Condomínio será composto pelas seguintes séries, na proporção e características abaixo, podendo ser alterado por aditivo nos termos do Capítulo X:</p>\n  <table class=\"r-series\">\n    <thead><tr><th>NOME</th><th>RENTABILIDADE</th><th>VALOR</th><th>Nº COTAS</th><th>TIPO</th><th>TOTAL SÉRIE</th><th>PART. %</th></tr></thead>\n    <tbody>\n      <tr><td>Cota Única</td><td>-</td><td>R$ 1.000.000,00</td><td>1</td><td>Garantidora</td><td>R$ 1.000.000,00</td><td>10%</td></tr>\n      <tr><td>Cotas Seriadas</td><td>1,70% a.m.</td><td>R$ 10.000,00</td><td>900</td><td>Pré-fixada</td><td>R$ 9.000.000,00</td><td>90%</td></tr>\n    </tbody>\n  </table>\n  <p><b>Artigo 14º –</b> As Rentabilidades serão pagas na modalidade pro rata die, tendo como Dia de Pagamento o dia 6 (seis) dos meses subsequentes. A Gestora poderá, a seu critério, antecipar o pagamento quando o dia 6 recair em dia não útil; não havendo antecipação, o pagamento ocorrerá no primeiro dia útil subsequente.</p>\n  <p>Parágrafo Único: Verificado atraso no pagamento, e ressalvadas as hipóteses do Artigo 29º, a Gestora ficará obrigada a pagar ao cotista, sobre o valor da Rentabilidade em atraso juros moratórios de 1% (um por cento) ao mês, calculados pro rata die, com base em mês comercial de 30 (trinta) dias, incidentes desde o dia subsequente ao vencimento até a data do efetivo pagamento.</p>\n  <p><b>Artigo 15º –</b> Para aquisições efetuadas após o Dia de Pagamento do mês corrente, a data-base de início de contagem da Rentabilidade será o Dia de Pagamento do mês subsequente, aplicando-se o pro rata die conforme o período efetivo.</p>\n  <p><b>Artigo 16º –</b> O investidor que adquirir até 25 (vinte e cinco) cotas compromete-se a manter o investimento pelo período mínimo de 6 (seis) meses. A aquisição de 26 (vinte e seis) ou mais cotas impõe período mínimo de 12 (doze) meses, ambos contados da data de assinatura do respectivo Termo de Aquisição.</p>\n  <p><b>Artigo 17º –</b> Limite por investidor: a soma do valor nominal total de cotas detidas por cotista não poderá ultrapassar R$ 1.000.000,00 (um milhão de reais), salvo deliberação expressa e escrita da Gestora em sentido diverso.</p>\n  <p><b>Artigo 18º –</b> Será admitido investimento conjunto e solidário por duas pessoas físicas para aquisição de uma mesma cota; nessa hipótese, os coinvestidores serão considerados, em conjunto, como um único titular, devendo indicar um responsável pelo recebimento integral da Rentabilidade e do resgate.</p>\n  <p><b>Artigo 19º –</b> As cotas são escriturais e nominativas, conferem iguais direitos e obrigações aos cotistas e não podem ser objeto de cessão ou transferência, salvo se a Gestora, por escrito, admitir excepcionalmente a substituição do titular mediante novo cadastro e aceite.</p>\n  <p><b>Artigo 20º –</b> A integralização de cotas ocorrerá obrigatoriamente por tranferência (TED/PIX) para conta bancária indicada pela Gestora.</p>\n  <p><b>Artigo 21º –</b> A Gestora poderá recusar proposta de investimento inicial ou nova integralização, a seu critério, em razão de políticas internas e/ou de prevenção e combate à lavagem de dinheiro e ao financiamento do terrorismo, ou por não enquadramento do investidor no público-alvo do Condomínio, sem necessidade de justificar sua recusa.</p>\n  <p><b>Artigo 22º –</b> O período de oferta inicial de cotas terá início em 01/01/2024 e término por ocasião da subscrição da totalidade das cotas ofertadas ou por decisão da Gestora. A Gestora poderá suspender, a qualquer tempo, novas aplicações, desde que a suspensão seja aplicada de forma indistinta.</p>\n  <p><b>Artigo 23º –</b> Na hipótese de emissão de novas cotas, estas serão ofertadas preferencialmente aos cotistas já participantes, mediante comunicação eletrônica da Gestora, que assegurará prazo mínimo de 5 (cinco) dias úteis para exercício da preferência, antes de ofertar a terceiros.</p>\n\n  <h2>CAPÍTULO V – RESGATE, RENOVAÇÃO, LIQUIDAÇÃO E MULTAS</h2>\n  <p><b>Artigo 24º –</b> As cotas poderão ser resgatadas integralmente ao término do Prazo de Duração aplicável ou renovadas por igual período, conforme instrução do cotista nos canais de atendimento, sendo os recursos entregues ao cotista em D+3 (dias úteis) da data de vencimento/encerramento.</p>\n  <p><b>§1º</b> Na ausência de manifestação expressa do cotista, pelos canais de atendimento da Gestora, até o Prazo de Manifestação, presume-se a opção pela Renovação Automática do investimento por igual período ao Prazo de Duração aplicável ao respectivo Termo de Aquisição, observado o prazo mínimo do Artigo 16º.</p>\n  <p><b>§2º</b> A Renovação Automática produzirá efeitos a partir do primeiro dia subsequente à Data de Vencimento, mantendo-se as condições aplicáveis, inclusive quanto à Rentabilidade, salvo se houver alteração formalizada por aditivo na forma do Capítulo X, hipótese em que será assegurado ao cotista o direito de não aderir à alteração e solicitar o resgate no vencimento, mediante manifestação no Prazo de Manifestação.</p>\n  <p><b>Artigo 25º –</b> Na hipótese de o Prazo de Duração encerrar-se em dia não útil, a liquidação dar-se-á no terceiro dia útil subsequente, preservando-se a regra de D+3.</p>\n  <p><b>Artigo 26º –</b> Os recursos provenientes do resgate e as Rentabilidades mensais serão pagos exclusivamente em conta bancária de titularidade do cotista (ou do coinvestidor responsável), previamente cadastrada, podendo ser alterada mediante solicitação com antecedência mínima de 5 (cinco) dias úteis em relação ao Dia de Pagamento.</p>\n  <p><b>Artigo 27º –</b> Pedidos de aplicação e resgate poderão deixar de ser processados em dias em que o sistema financeiro e/ou as praças de negociação relevantes não estiverem operando, hipótese em que serão processados no primeiro dia útil subsequente.</p>\n  <p><b>Artigo 28º –</b> Resgate antecipado: as cotas resgatadas antes do término do Prazo de Duração mínimo sofrerão multa calculada sobre o valor integralizado e os rendimentos, conforme o número de cotas detidas pelo cotista, da seguinte forma:</p>\n  <p><b>I –</b> Para cotistas com até 25 (vinte e cinco) cotas: multa progressiva de até 10%, aplicada conforme tempo decorrido:</p>\n  <ul class=\"sub\">\n    <li>1º mês: 10% (dez por cento);</li>\n    <li>2º mês: 9% (nove por cento);</li>\n    <li>3º mês: 8% (oito por cento);</li>\n    <li>4º mês: 7,5% (sete e meio por cento);</li>\n    <li>5º mês: 7% (sete por cento);</li>\n    <li>A partir do 6º mês: sem multa (observado o prazo mínimo).</li>\n  </ul>\n  <p><b>II –</b> Para cotistas com 26 (vinte e seis) cotas ou mais: multa progressiva de até 20%, aplicada conforme tempo decorrido:</p>\n  <ul class=\"sub\">\n    <li>1º mês: 20% (vinte por cento);</li>\n    <li>2º mês: 18% (dezoito por cento);</li>\n    <li>3º mês: 16% (dezesseis por cento);</li>\n    <li>4º mês: 15% (quinze por cento);</li>\n    <li>5º mês: 14% (quatorze por cento);</li>\n    <li>6º mês: 13% (treze por cento);</li>\n    <li>7º mês: 12% (doze por cento);</li>\n    <li>8º mês: 11% (onze por cento);</li>\n    <li>9º mês: 10% (dez por cento);</li>\n    <li>10º mês: 9% (nove por cento);</li>\n    <li>11º mês: 8% (oito por cento);</li>\n    <li>A partir do 12º mês: sem multa (observado o prazo mínimo).</li>\n  </ul>\n  <p><b>Artigo 29º –</b> Caso fortuito e força maior: ocorrendo evento imprevisível e inevitável que impeça ou atrase o cumprimento de obrigações, as obrigações afetadas poderão ser suspensas enquanto perdurarem os efeitos do evento, sem penalidades para a parte afetada, devendo as partes envidar melhores esforços para mitigar seus efeitos. Se necessário, a Gestora poderá suspender resgates por até 90 (noventa) dias, comunicando os cotistas.</p>\n\n  <h2>CAPÍTULO VI – ENCARGOS E TRIBUTAÇÃO</h2>\n  <p><b>Artigo 30º –</b> Todos os encargos do Condomínio, incluindo tarifas bancárias, manutenção de contas e despesas gerais de operação, serão suportados pela Gestora.</p>\n  <p><b>Artigo 31º –</b> A responsabilidade por eventual declaração e recolhimento de tributos incidentes sobre rendimentos é de cada cotista, conforme sua situação fiscal e as regras aplicáveis.</p>\n\n  <h2>CAPÍTULO VII – PRESTAÇÃO DE INFORMAÇÕES, COMUNICAÇÕES E CONFIDENCIALIDADE</h2>\n  <p><b>Artigo 32º –</b> A demonstração de resultados será realizada por relatório eletrônico contendo, no mínimo, informações sobre movimentações de carteira, volume transacionado, valores futuros de recebíveis, volume mensal de vencimentos, total de cotas negociadas e total de cotas disponíveis.</p>\n  <p><b>Artigo 33º –</b> Será divulgado imediatamente aos cotistas, por correio eletrônico ou canal eletrônico equivalente, qualquer ato ou fato relevante relacionado ao funcionamento do Condomínio ou aos ativos integrantes de sua carteira.</p>\n  <p><b>Artigo 34º –</b> O cotista obriga-se a manter total confidencialidade sobre as informações e documentos recebidos em razão do Condomínio, em especial relatórios e informes de resultados, abstendo-se de divulgá-los a terceiros por qualquer meio, inclusive redes sociais, salvo por exigência legal ou em demandas judiciais, sob pena de perdas e danos.</p>\n  <p><b>Artigo 35º –</b> O serviço de atendimento ao cotista será prestado pelos canais indicados pela Gestora, inclusive telefone e e-mail corporativo.</p>\n  <ul>\n    <li>Tel.: (61) 4042-9355</li>\n    <li>E-mail: financeiro@grupocapuzzo.com</li>\n  </ul>\n  <p><b>Artigo 36º –</b> A Gestora e/ou prestadores de serviços poderão gravar comunicações e ligações mantidas com cotistas, para fins de prova e segurança operacional, observada a legislação aplicável.</p>\n\n  <h2>CAPÍTULO VIII – GARANTIAS</h2>\n  <p><b>Artigo 37º –</b> As garantias do Condomínio se estruturam, cumulativamente ou alternativamente, conforme a operação:</p>\n  <ul>\n    <li>Recebíveis futuros custodiados em nome do Condomínio ou da Gestora;</li>\n    <li>Cota Única Garantidora participante do Condomínio, garantida pela empresa Gestora;</li>\n    <li>Bens e ativos da Gestora.</li>\n  </ul>\n\n  <h2>CAPÍTULO IX – PRIVACIDADE, PROTEÇÃO DE DADOS E SEGURANÇA DA INFORMAÇÃO</h2>\n  <p><b>Artigo 38º –</b> A Gestora compromete-se a cumprir a Lei Geral de Proteção de Dados (Lei nº 13.709/2018) e demais normas aplicáveis, tratando dados pessoais de cotistas e potenciais cotistas para finalidades legítimas, específicas e informadas.</p>\n  <p><b>Artigo 39º –</b> A Gestora adotará medidas técnicas e administrativas adequadas para proteção de dados contra acessos não autorizados, uso indevido, divulgação, alteração ou destruição, e cooperará para o exercício dos direitos dos titulares de dados.</p>\n  <p><b>Artigo 40º –</b> O descumprimento das disposições de proteção de dados será considerado violação material, sujeitando o infrator às medidas cabíveis, sem prejuízo de indenização por danos eventualmente causados.</p>\n\n  <h2>CAPÍTULO X – ALTERAÇÕES, ADITIVOS E DISPOSIÇÕES FINAIS</h2>\n  <p><b>Artigo 41º –</b> Este Regulamento poderá ser alterado por iniciativa da Gestora, mediante comunicação eletrônica aos cotistas. Alterações que impliquem mudança de quadro de cotas, limites ou condições de preferência poderão ser formalizadas por aditivo específico.</p>\n  <p><b>Artigo 42º –</b> As comunicações previstas neste Regulamento serão consideradas válidas quando realizadas por e-mail, aplicativos de mensagem ou outros canais eletrônicos previamente indicados pelo cotista à Gestora.</p>\n  <p><b>Artigo 43º –</b> Fica eleito o foro da Circunscrição Judiciária de Brasília/DF, com renúncia expressa de qualquer outro, por mais privilegiado que seja, para dirimir questões oriundas deste Regulamento e das relações dele decorrentes.</p>\n\n  <p class=\"r-data\">Brasília, 09 de janeiro de 2026.</p>\n</section>\n",
  "contratos/doc/termo_aquisicao_civil.html": "<section class=\"folha termo\">\n  <img class=\"cab-termo\" src=\"{{ cab }}\" alt=\"Capuzzo\">\n  <h1 class=\"t-titulo\">Termo de Aquisição de Cotas</h1>\n\n  <p class=\"t-abre\">Por meio deste instrumento,</p>\n\n  <p class=\"t-just\"><b>{{ d.investidor.nome }}</b>, {{ d.investidor.nacionalidade }}, {{ d.investidor.estado_civil }},\n    {{ d.investidor.profissao }}, portador(a) do {{ d.investidor.documento_tipo }} nº {{ d.investidor.documento }},\n    residente e domiciliado(a) em {{ d.investidor.endereco }}, CEP: {{ d.investidor.cep }},\n    (“<b>Investidor(a)</b>”), formaliza a aquisição de {{ d.qtd }}({{ d.qtd_extenso }}) cota(s) do\n    <b>CONDOMÍNIO PRIVADO DE INVESTIMENTOS</b> (“<b>CONDOMÍNIO</b>”) administrado por\n    <b>{{ d.empresa.empresa_nome }}</b>, inscrita no CNPJ: {{ d.empresa.empresa_cnpj }}, com sede na\n    {{ d.empresa.empresa_endereco }}, neste ato representada na forma de seu Contrato Social (“<b>Contratada</b>”)\n    e <b>ADERE</b> para todos os fins e efeitos de direito ao <b>REGULAMENTO DO CONDOMÍNIO DE INVESTIMENTO\n    PRIVADO FECHADO</b> (“<b>Regulamento</b>”), do qual este instrumento é parte integrante e indissociável e\n    declara que:</p>\n\n  <ol class=\"t-lista\">\n    <li>Adquire as cotas descritas abaixo, com as seguintes condições:\n      <table class=\"t-cotas\">\n        <thead><tr><th>Cota(s) nº</th><th>Rentabilidade</th><th>Valor total</th><th>Prazo mínimo resgate</th><th>Tipo</th></tr></thead>\n        <tbody>\n        {% for ct in d.cotas %}\n          <tr><td>{{ ct.numero }}</td><td>{{ d.rentabilidade }}</td><td>{{ valor_br(ct.valor) }}</td>\n              <td>{{ d.prazo_meses }} meses</td><td>{{ d.tipo_cota }}</td></tr>\n        {% endfor %}\n        {% if d.cotas|length > 1 %}\n          <tr class=\"tot\"><td>{{ d.qtd }} cotas</td><td></td><td>{{ valor_br(d.valor_total) }}</td><td></td><td></td></tr>\n        {% endif %}\n        </tbody>\n      </table>\n    </li>\n    <li>Tem consciência de que a Contratada tem amplos poderes para exercer a total administração do CONDOMÍNIO;</li>\n    <li>Recebeu uma cópia, leu, compreendeu e está plenamente de acordo com os termos e condições do Regulamento e\n      reitera, assim, as declarações dispostas no referido documento;</li>\n    <li>Teve a oportunidade de questionar e de esclarecer dúvidas sobre o conteúdo dos termos e condições do\n      Regulamento;</li>\n    <li>Está ciente de que a remuneração mensal e o resgate da cota serão pagos apenas para contas bancárias de sua\n      própria titularidade {{ d.investidor.pagamento }};</li>\n    <li>As remunerações serão pagas na modalidade pro rata die, sendo fixado o dia 6 (seis) dos meses subsequentes,\n      podendo ou não, a critério da gestora, ser antecipado em caso de dia não útil;</li>\n    <li>Está ciente de que o prazo mínimo para resgate começa a contar a partir do dia 6 (seis) do mês subsequente\n      à assinatura deste termo;</li>\n    <li>Autoriza a Contratada a representar o CONDOMÍNIO perante administradores, custodiantes, escrituradores e\n      gestores de fundos de investimentos, inclusive com poderes para dar e receber quitação, celebrar acordos e\n      transigir, solicitar informações, sempre nos limites necessários para a prestação dos serviços objeto do\n      Regulamento;</li>\n    <li>Sua concordância, por escrito, via e-mail ou WhatsApp, é válida também como assinatura deste termo;</li>\n    <li>Autoriza a Contratada a representar o CONDOMÍNIO perante quaisquer corretoras de câmbio, títulos, ativos e\n      valores mobiliários, nacionais e/ou internacionais, inclusive com poderes para elaborar cadastros, obter e\n      prestar informações, podendo negociar, comprar, vender, endossar, ceder, onerar, transferir, resgatar,\n      reinvestir, tomar emprestado e emprestar títulos, valores mobiliários e ativos financeiros, incluindo-se ações,\n      títulos de dívida, cotas de fundos, derivativos ou quaisquer outros ativos disponíveis nos Mercados; a requerer\n      a emissão de cautelas e títulos múltiplos, depositar, custodiar ou solicitar a custódia, agrupar, desdobrar,\n      subscrever ações ou quaisquer outros ativos; a resgatar títulos, retirar cautelas e títulos múltiplos\n      representativos de ações e debêntures; aplicar e resgatar valores em fundos de renda fixa ou variável ou\n      qualquer outro tipo de investimento; abrir, movimentar e encerrar contas de custódia; fechar operações de\n      compra e venda de moeda estrangeira; executar quaisquer operações de mercado à vista, disponível, a termo, a\n      futuro, de índice e de opções, sendo os custos relacionados ao exercício de tais direitos suportados\n      integralmente pela própria Contratada.</li>\n  </ol>\n\n  <p class=\"t-just\">Este Termo de Adesão e seus anexos são parte integrante e indissociável do Regulamento. Na\n    hipótese de qualquer conflito entre as disposições, prevalecerão as disposições do Regulamento.</p>\n\n  <p class=\"t-data\">{{ d.local_data }}.</p>\n</section>\n",
  "contratos/doc/termo_aquisicao_padrao.html": "{# Termo de Aquisição — modelo do Agronegócio (D4Sign 2026), usado também pelo Saúde. #}\n<section class=\"folha termo\">\n  <img class=\"cab-termo\" src=\"{{ cab }}\" alt=\"Capuzzo\">\n  <h1 class=\"t-titulo\">Termo de Aquisição de Cotas</h1>\n\n  <p class=\"t-abre\">Por meio deste instrumento,</p>\n\n  <p class=\"t-just\"><b>{{ d.investidor.nome }}</b>, {{ d.investidor.nacionalidade }}{% if d.investidor.estado_civil %}, {{ d.investidor.estado_civil }}{% endif %}{% if d.investidor.profissao %}, {{ d.investidor.profissao }}{% endif %},\n    portador(a) do {{ d.investidor.documento_tipo }} nº {{ d.investidor.documento }}, residente e domiciliado(a) em\n    {{ d.investidor.endereco }}, CEP: {{ d.investidor.cep }}, (“<b>Investidor(a)</b>”), formaliza a aquisição de\n    {{ d.qtd }} ({{ d.qtd_extenso|lower }}) cota(s) do <b>{{ p.condominio }}</b> (“<b>Condomínio</b>”) administrado por\n    <b>{{ d.empresa.empresa_nome }}</b>, inscrita no CNPJ: {{ d.empresa.empresa_cnpj }}, com sede na\n    {{ d.empresa.empresa_endereco }}, neste ato representada na forma de seu Contrato Social (“<b>Contratada</b>”)\n    e <b>ADERE</b> para todos os fins e efeitos de direito ao <b>{{ p.regulamento }}</b> (“<b>Regulamento</b>”),\n    do qual este instrumento é parte integrante e indissociável e declara que:</p>\n\n  <ol class=\"t-lista\">\n    <li>Adquire as cotas descritas abaixo, com as seguintes condições:\n      <table class=\"t-cotas\">\n        <thead><tr><th>Número da(s) cota(s)</th><th>Rentabilidade</th><th>Valor total</th><th>Prazo mínimo de resgate</th><th>Tipo</th></tr></thead>\n        <tbody><tr><td>{{ d.faixa }}</td><td class=\"t-rent\">{{ p.rentabilidade }}</td><td>{{ moeda(d.valor_total) }}</td>\n          <td>{{ d.prazo_meses }} meses</td><td>{{ p.tipo }}</td></tr></tbody>\n      </table>\n    </li>\n    <li>Tem consciência de que a Contratada tem amplos poderes para exercer a total administração do Condomínio;</li>\n    <li>Recebeu uma cópia, leu, compreendeu e está plenamente de acordo com os termos e condições do Regulamento e\n      reitera, assim, as declarações dispostas no referido documento;</li>\n    <li>Teve a oportunidade de questionar e de esclarecer dúvidas sobre o conteúdo dos termos e condições do\n      Regulamento;</li>\n    <li>Está ciente de que a remuneração mensal e o resgate da cota serão pagos apenas para contas bancárias de sua\n      própria titularidade, {{ d.investidor.pagamento }} informada no ato de aquisição das cotas, podendo esta ser\n      alterada a critério do investidor desde que a solicitação de alteração ocorra com, pelo menos, cinco dias úteis\n      de antecedência à data de pagamento da rentabilidade;</li>\n    <li>As remunerações serão pagas na modalidade pro rata die, sendo fixado o dia {{ p.dia }} ({{ p.dia_extenso }})\n      dos meses subsequentes, podendo ou não, a critério da gestora, ser antecipado em caso de dia não útil. Em caso\n      de não antecipação, o valor será pago no dia útil subsequente ao {{ p.dia }}º dia do mês;</li>\n    <li>Fica ciente que, para aquisições realizadas até o dia {{ p.dia_corte }} do mês corrente, a data-base para o\n      cálculo do prazo mínimo de resgate será o dia {{ p.dia }} do mesmo mês. Para aquisições efetuadas após o dia\n      {{ p.dia_corte }} do mês corrente, a data-base será o dia {{ p.dia }} do mês subsequente.</li>\n    <li>Autoriza a Contratada a representar o Condomínio perante administradores, custodiantes, escrituradores e\n      gestores de fundos de investimentos, inclusive com poderes para dar e receber quitação, celebrar acordos e\n      transigir, solicitar informações, sempre nos limites necessários para a prestação dos serviços objeto do\n      Regulamento;</li>\n    <li>Sua concordância, por escrito, via e-mail ou WhatsApp, é válida também como assinatura deste termo;</li>\n    {% include \"contratos/doc/_item_corretoras.html\" %}\n  </ol>\n\n  <p class=\"t-just\">Este Termo de Adesão e seus anexos são parte integrante e indissociável do Regulamento. Na\n    hipótese de qualquer conflito entre as disposições, prevalecerão as disposições do Regulamento.</p>\n\n  <p class=\"t-data\">{{ d.local_data }}.</p>\n</section>\n",
  "contratos/doc/termo_renovacao.html": "{# Termo de Renovação de Cotas — modelos Civil e Agronegócio (D4Sign 2026); Saúde segue o Agronegócio. #}\n<section class=\"folha termo\">\n  <img class=\"cab-termo\" src=\"{{ cab }}\" alt=\"Capuzzo\">\n  <h1 class=\"t-titulo\">Termo de Renovação<br>de Cotas</h1>\n\n  <p class=\"t-abre\">Por meio deste instrumento,</p>\n\n  <p class=\"t-just\"><b>{{ d.investidor.nome }}</b>, {{ d.investidor.nacionalidade }}, portador(a) do\n    {{ d.investidor.documento_tipo }} nº {{ d.investidor.documento }}, residente e domiciliado(a) à\n    {{ d.investidor.endereco }}, CEP: {{ d.investidor.cep }} (“<b>Investidor(a)</b>”), formaliza a renovação de\n    {{ d.qtd }} ({{ d.qtd_extenso|lower }}) cota(s) do <b>{{ p.condominio }}</b> (“<b>Condomínio</b>”) administrado\n    por <b>{{ d.empresa.empresa_nome }}</b>, inscrita no CNPJ: {{ d.empresa.empresa_cnpj }}, com sede na\n    {{ d.empresa.empresa_endereco }}, neste ato representada na forma de seu Contrato Social (“<b>Contratada</b>”)\n    e <b>ADERE</b> para todos os fins e efeitos de direito ao <b>{{ p.regulamento }}</b> (“<b>Regulamento</b>”),\n    do qual este instrumento é parte integrante e indissociável e declara que:</p>\n\n  <ol class=\"t-lista\">\n    <li>Renova a(s) cota(s) descrita(s) abaixo, com as seguintes condições:\n      <table class=\"t-cotas\">\n        <thead><tr><th>Cota(s) nº</th><th>Rentabilidade</th><th>Valor total</th><th>Prazo mínimo de resgate</th><th>Tipo</th></tr></thead>\n        <tbody><tr><td>{{ d.faixa }}</td><td class=\"t-rent\">{{ p.rentabilidade }}</td><td>{{ moeda(d.valor_total) }}</td>\n          <td>{{ d.prazo_meses }} meses</td><td>{{ p.tipo }}</td></tr></tbody>\n      </table>\n    </li>\n    <li>Tem consciência de que a Contratada tem amplos poderes para exercer a total administração do Condomínio;</li>\n    <li>Recebeu uma cópia, leu, compreendeu e está plenamente de acordo com os termos e condições do Regulamento e\n      reitera, assim, as declarações dispostas no referido documento;</li>\n    <li>Teve a oportunidade de questionar e de esclarecer dúvidas sobre o conteúdo dos termos e condições do\n      Regulamento;</li>\n    <li>Está ciente de que a remuneração mensal e o resgate da cota serão pagos apenas para contas bancárias de sua\n      própria titularidade;</li>\n    <li>Autoriza a Contratada a representar o Condomínio perante administradores, custodiantes, escrituradores e\n      gestores de fundos de investimentos, inclusive com poderes para dar e receber quitação, celebrar acordos e\n      transigir, solicitar informações, sempre nos limites necessários para a prestação dos serviços objeto do\n      Regulamento;</li>\n    <li>Está ciente de que o prazo mínimo para resgate começa a contar a partir do dia {{ p.dia }} ({{ p.dia_extenso }})\n      do mês subsequente à assinatura deste termo;</li>\n    <li>Sua concordância, por escrito, via e-mail ou WhatsApp, é válida também como assinatura deste termo;</li>\n    {% include \"contratos/doc/_item_corretoras.html\" %}\n  </ol>\n\n  <p class=\"t-just\">Este Termo de Renovação e seus anexos são parte integrante e indissociável do Regulamento. Na\n    hipótese de qualquer conflito entre as disposições, prevalecerão as disposições do Regulamento.</p>\n\n  <p class=\"t-data\">{{ d.local_data }}.</p>\n</section>\n",
  "contratos/doc/termo_retirada.html": "{# Termo de Retirada de Investimento — modelos Civil e Agronegócio (D4Sign 2026); Saúde segue o Agronegócio.\n   Assinado só pelo investidor. #}\n<section class=\"folha termo\">\n  <img class=\"cab-termo\" src=\"{{ cab }}\" alt=\"Capuzzo\">\n  <h1 class=\"t-titulo\">Termo de Retirada<br>de Investimento</h1>\n\n  <p class=\"t-abre\">Por meio deste instrumento,</p>\n\n  <p class=\"t-just\"><b>{{ d.investidor.nome }}</b>, {{ d.investidor.nacionalidade }}, portador(a) do\n    {{ d.investidor.documento_tipo }} nº {{ d.investidor.documento }}, residente e domiciliado(a) na\n    {{ d.investidor.endereco }}, CEP: {{ d.investidor.cep }}, (“<b>Investidor(a) Retirante</b>”), formaliza a retirada\n    de montante aplicado no <b>{{ p.condominio }}</b>, administrado por <b>{{ d.empresa.empresa_nome }}</b>, inscrita\n    no CNPJ: {{ d.empresa.empresa_cnpj }}, com sede na {{ d.empresa.empresa_endereco }}, e declara que:</p>\n\n  <ol class=\"t-lista\">\n    <li>Formaliza a retirada do montante de <b>{{ moeda(d.retirada.valor) }} ({{ d.retirada.valor_extenso }})</b>,\n      referente {{ 'à cota' if d.qtd == 1 else 'às cotas' }} nº {{ d.faixa }}, da carteira de títulos, ativos\n      financeiros, valores mobiliários e numerários do {{ p.condominio_curto }} administrado pela\n      {{ d.empresa.empresa_nome }}.</li>\n    <li>Reconhece que a contratada prestou os serviços de forma discricionária, observando as limitações impostas pela\n      regulamentação em vigor e os princípios da boa técnica de investimentos, visando a proteção do patrimônio do\n      Investidor e a obtenção de ganhos reais, em função das operações realizadas;</li>\n    <li>Afirma que a contratada colocou à disposição do Investidor toda a documentação das transações efetivas com a\n      carteira, forneceu todas as demais informações sobre a carteira que venham a ser solicitadas pelo Investidor;</li>\n    <li>A contratada utilizou na prestação dos serviços sistemas apropriados para o processamento, registro, controle,\n      segurança e comunicação das atividades prestadas, utilizando-se de política de confidencialidade. Geriu a\n      carteira em conformidade com a Política de Investimento constante do Termo de Adesão a este Contrato,\n      estabelecida entre as partes. Apresentou mensalmente e sempre que o Investidor solicitou, extrato com\n      informações sobre os investimentos realizados.</li>\n  </ol>\n\n  <p class=\"t-just\">Neste termo, o Investidor Retirante atesta ciência e concordância que receberá o valor de\n    <b>{{ moeda(d.retirada.valor) }} ({{ d.retirada.valor_extenso }})</b>, referente à retirada do montante investido e\n    supramencionado, o qual será creditado {{ p.prazo_credito }} a contar da assinatura deste instrumento.</p>\n\n  <p class=\"t-data\">{{ d.local_data }}.</p>\n</section>\n",
  "contratos/email/_base.html": "<!DOCTYPE html>\n<html lang=\"pt-BR\"><head><meta charset=\"UTF-8\"></head>\n<body style=\"margin:0;padding:0;background:#f3f1ec;font-family:Arial,Helvetica,sans-serif;color:#1a1a1a;\">\n<table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" style=\"background:#f3f1ec;padding:24px 0;\">\n<tr><td align=\"center\">\n<table role=\"presentation\" width=\"560\" cellpadding=\"0\" cellspacing=\"0\" style=\"max-width:560px;width:100%;background:#ffffff;border-radius:8px;overflow:hidden;border:1px solid #e4dfd2;\">\n  <tr><td style=\"background:#0d0d0d;padding:18px 28px;\">\n    <span style=\"font-family:Georgia,serif;font-size:22px;letter-spacing:3px;color:#f3ebd6;\">CAPUZZO</span>\n    <span style=\"display:block;font-size:10px;letter-spacing:3px;color:#c7a955;margin-top:2px;\">ASSESSORIA EMPRESARIAL</span>\n  </td></tr>\n  <tr><td style=\"height:4px;background:linear-gradient(90deg,#9e7c34,#f1d98a,#9e7c34);background-color:#c7a955;\"></td></tr>\n  <tr><td style=\"padding:28px 28px 8px;font-size:15px;line-height:1.55;\">\n{% block corpo %}{% endblock %}\n  </td></tr>\n  <tr><td style=\"padding:16px 28px 26px;font-size:12px;color:#777;line-height:1.5;border-top:1px solid #eee;\">\n    {{ cfg.empresa_nome }} · CNPJ {{ cfg.empresa_cnpj }}<br>\n    Atendimento ao cotista: {{ cfg.email_copia }} · (61) 4042-9355<br>\n    <span style=\"color:#999;\">Nunca pedimos senhas por e-mail. Em caso de dúvida sobre este e-mail, fale com a Capuzzo pelos canais acima.</span>\n  </td></tr>\n</table>\n</td></tr></table>\n</body></html>\n",
  "contratos/email/assinado.html": "{% extends \"contratos/email/_base.html\" %}\n{% block corpo %}\n<p style=\"margin:0 0 14px;\">Olá, <b>{{ d.investidor.nome }}</b>.</p>\n<p style=\"margin:0 0 14px;\">✅ Seu <b>{{ TIPOS[c.tipo] }}</b>{% if d.anexo_nome %} e o Regulamento foram assinados{% else %} foi assinado{% endif %} por todas as partes.</p>\n<p style=\"margin:0 0 14px;\">{{ d.produto.nome }} · {{ d.qtd }} cota(s) · {{ moeda((d.retirada or {}).valor or d.valor_total) }}.\n  {% if c.tipo == 'aquisicao' %}As cotas serão ativadas assim que o depósito (TED/PIX) for identificado pela Capuzzo.\n  {% elif c.tipo == 'retirada' %}O valor será creditado {{ d.produto_doc.prazo_credito }} a contar da assinatura, na conta informada no seu cadastro.\n  {% else %}A renovação das suas cotas está confirmada.{% endif %}</p>\n{% if c.tipo == 'aquisicao' and cfg.instrucoes_deposito %}\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"width:100%;background:#faf8f2;border:1px solid #ece5cf;border-radius:6px;margin:0 0 18px;font-size:14px;\">\n  <tr><td style=\"padding:12px 16px;white-space:pre-line;\"><b>Dados para depósito</b><br>{{ cfg.instrucoes_deposito }}</td></tr>\n</table>\n{% endif %}\n<p style=\"text-align:center;margin:0 0 20px;\">\n  <a href=\"{{ link }}\" style=\"display:inline-block;background:#141210;color:#f3ebd6;text-decoration:none;font-weight:bold;padding:12px 26px;border-radius:6px;font-size:14px;\">Ver e baixar o documento assinado</a>\n</p>\n{% endblock %}\n",
  "contratos/email/cancelado.html": "{% extends \"contratos/email/_base.html\" %}\n{% block corpo %}\n<p style=\"margin:0 0 14px;\">Olá, <b>{{ d.investidor.nome }}</b>.</p>\n<p style=\"margin:0 0 14px;\">O <b>{{ TIPOS[c.tipo] }}</b> enviado anteriormente ({{ d.produto.nome }} · {{ d.qtd }} cota(s) · {{ moeda((d.retirada or {}).valor or d.valor_total) }})\n  foi <b style=\"color:#b42318;\">cancelado</b> pela {{ cfg.empresa_assinante }} e <b>não tem mais validade</b>{% if substituido %} —\n  em seguida você receberá uma nova versão corrigida para assinar{% endif %}.</p>\n{% if motivo %}<p style=\"margin:0 0 14px;color:#555;\">Motivo: {{ motivo }}</p>{% endif %}\n<p style=\"margin:0 0 10px;font-size:13px;color:#555;\">Se você já assinou a versão cancelada, essa assinatura foi invalidada. Não é preciso fazer nada com ela.</p>\n{% endblock %}\n",
  "contratos/email/codigo.html": "{% extends \"contratos/email/_base.html\" %}\n{% block corpo %}\n<p style=\"margin:0 0 14px;\">Olá, <b>{{ nome }}</b>.</p>\n<p style=\"margin:0 0 14px;\">Use o código abaixo para confirmar sua assinatura eletrônica:</p>\n<p style=\"text-align:center;margin:0 0 18px;\"><span style=\"display:inline-block;font:bold 32px/1 'Courier New',monospace;letter-spacing:8px;background:#faf8f2;border:1px solid #ece5cf;border-radius:6px;padding:14px 22px;\">{{ codigo }}</span></p>\n<p style=\"margin:0 0 10px;font-size:13px;color:#555;\">O código vale por {{ validade }} minutos. Se você não pediu este código, ignore este e-mail.</p>\n{% endblock %}\n",
  "contratos/email/convite.html": "{% extends \"contratos/email/_base.html\" %}\n{% block corpo %}\n<p style=\"margin:0 0 14px;\">Olá, <b>{{ d.investidor.nome }}</b>.</p>\n<p style=\"margin:0 0 14px;\">A {{ cfg.empresa_assinante }} enviou para sua assinatura eletrônica os documentos abaixo.{% if c.tipo != 'retirada' %} A empresa já assinou — falta apenas você.{% endif %}</p>\n<table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" style=\"width:100%;background:#faf8f2;border:1px solid #ece5cf;border-radius:6px;margin:0 0 18px;font-size:14px;\">\n  <tr><td style=\"padding:12px 16px;\">\n    📄 <b>{{ TIPOS[c.tipo] }}</b><br>\n    {% if d.anexo_nome %}📎 {{ d.anexo_nome }}<br>{% endif %}\n    <span style=\"color:#666;font-size:13px;\">{{ d.produto.nome }} · {{ d.qtd }} cota(s) nº {{ d.cotas | map(attribute='numero') | join(', ') }} · {{ moeda((d.retirada or {}).valor or d.valor_total) }}</span>\n  </td></tr>\n</table>\n<p style=\"text-align:center;margin:0 0 20px;\">\n  <a href=\"{{ link }}\" style=\"display:inline-block;background:#c7a955;color:#141210;text-decoration:none;font-weight:bold;padding:14px 30px;border-radius:6px;font-size:15px;\">Ler e assinar o documento</a>\n</p>\n<p style=\"margin:0 0 6px;font-size:13px;color:#555;\">Para sua segurança, ao assinar pediremos a confirmação do seu CPF e um código enviado para este e-mail.</p>\n<p style=\"margin:0 0 10px;font-size:12px;color:#888;word-break:break-all;\">Se o botão não funcionar, copie e cole no navegador: {{ link }}</p>\n{% endblock %}\n",
  "contratos/novo.html": "{% extends \"base.html\" %}\n{% block title %}Gerar contrato — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n{% include \"contratos/_estilo.html\" %}\n<a href=\"{{ url_for('contratos.painel') }}\" class=\"back-link\">← Voltar para Contratos</a>\n\n<div class=\"page-header\">\n  <div class=\"page-header-icon\">📄</div>\n  <div class=\"page-header-title\">Gerar contrato para cotas pendentes</div>\n  <div class=\"page-header-sub\">Para cotas que já estão cadastradas como pendentes e ainda não têm contrato.\n    Para uma compra nova, use <a class=\"text-gold\" href=\"{{ url_for('cotas_nova', produto='civil') }}\">Nova cota com contrato</a>.</div>\n</div>\n\n<div class=\"card-gold\">\n  <form method=\"get\" class=\"form-row\" style=\"align-items:flex-end;\">\n    <div class=\"form-group\">\n      <label>Cliente com cotas pendentes</label>\n      <select name=\"client_id\" class=\"form-control\" onchange=\"this.form.submit()\">\n        <option value=\"\">Selecione…</option>\n        {% for cid, nome in clientes %}<option value=\"{{ cid }}\" {{ 'selected' if cliente and cliente.id == cid }}>{{ nome }}</option>{% endfor %}\n        {% if cliente and cliente.id not in (clientes | map(attribute=0) | list) %}<option value=\"{{ cliente.id }}\" selected>{{ cliente.full_name }}</option>{% endif %}\n      </select>\n    </div>\n  </form>\n\n  {% if cliente %}\n    {% if falta %}\n    <div class=\"alert alert-warning\" style=\"margin-top:12px;\"><span>\n      Para gerar o contrato, complete o cadastro de <b>{{ cliente.full_name }}</b>. Falta: {{ falta | join(', ') }}.\n      <a class=\"text-gold\" href=\"{{ url_for('clientes_editar', cid=cliente.id) }}#secao-contrato\">Completar cadastro →</a></span>\n    </div>\n    {% endif %}\n\n    {% if cotas %}\n    <form method=\"post\" style=\"margin-top:14px;\">\n      <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n      <input type=\"hidden\" name=\"client_id\" value=\"{{ cliente.id }}\">\n      {% set produtos = cotas | groupby('condominium_id') %}\n      <div class=\"form-group\">\n        <label>Produto</label>\n        <select name=\"condominium_id\" class=\"form-control\" id=\"sel-prod\" style=\"max-width:320px\">\n          {% for cond_id, lista in produtos %}\n          <option value=\"{{ cond_id }}\" {{ 'disabled' if lista[0].produto_code not in modelos }}>{{ lista[0].produto_nome }}{{ ' (modelo em breve)' if lista[0].produto_code not in modelos }}</option>\n          {% endfor %}\n        </select>\n      </div>\n      <div class=\"table-wrap\" style=\"margin-top:8px\">\n        <table>\n          <thead><tr><th style=\"width:40px\"></th><th>Cota</th><th>Produto</th><th style=\"text-align:right\">Valor</th><th>Cadastrada em</th></tr></thead>\n          <tbody>\n          {% for ct in cotas %}\n            <tr data-prod=\"{{ ct.condominium_id }}\">\n              <td><input type=\"checkbox\" name=\"share_ids\" value=\"{{ ct.id }}\" checked style=\"accent-color:#d4af37;width:16px;height:16px\"></td>\n              <td class=\"text-mono\">{{ ct.share_number }}</td><td>{{ ct.produto_nome }}</td>\n              <td style=\"text-align:right\" class=\"text-mono\">{{ moeda(ct.share_value) }}</td>\n              <td class=\"text-dim\">{{ ct.created_at | ct_data }}</td>\n            </tr>\n          {% endfor %}\n          </tbody>\n        </table>\n      </div>\n      <div class=\"page-actions\">\n        <button class=\"btn btn-primary\" {{ 'disabled' if falta }}>✍️ Gerar contrato (já assinado pela empresa)</button>\n      </div>\n    </form>\n    <script>\n    (function(){\n      var s = document.getElementById('sel-prod');\n      function f(){ document.querySelectorAll('tr[data-prod]').forEach(function(tr){\n        var on = tr.dataset.prod === s.value; tr.style.display = on ? '' : 'none';\n        tr.querySelector('input').disabled = !on; }); }\n      if(s){ s.addEventListener('change', f); f(); }\n    })();\n    </script>\n    {% else %}\n      <p class=\"text-dim\" style=\"margin-top:14px;\">Este cliente não tem cotas pendentes sem contrato.\n        <a class=\"text-gold\" href=\"{{ url_for('cotas_nova', produto='civil') }}\">Cadastrar nova cota com contrato →</a></p>\n    {% endif %}\n  {% elif not clientes %}\n    <p class=\"text-dim\" style=\"margin-top:14px;\">Não há cotas pendentes sem contrato.</p>\n  {% endif %}\n</div>\n{% endblock %}\n",
  "contratos/painel.html": "{% extends \"base.html\" %}\n{% block title %}Contratos e Assinaturas — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n{% include \"contratos/_estilo.html\" %}\n\n<div class=\"page-header\" style=\"display:flex;justify-content:space-between;align-items:flex-start;gap:16px;flex-wrap:wrap;\">\n  <div>\n    <div class=\"page-header-title\">✍️ Contratos e Assinaturas</div>\n    <div class=\"page-header-sub\">Termos gerados a partir das cotas, enviados ao cliente e acompanhados até a ativação.</div>\n  </div>\n  <div style=\"display:flex;gap:8px;flex-wrap:wrap;\">\n    <a href=\"{{ url_for('contratos.configuracoes') }}\" class=\"btn btn-secondary\">⚙️ Configurações</a>\n    <a href=\"{{ url_for('contratos.novo') }}\" class=\"btn btn-secondary\">📄 Contrato p/ cota pendente</a>\n    <a href=\"{{ url_for('cotas_nova', produto='civil') }}\" class=\"btn btn-primary\">+ Nova cota com contrato</a>\n  </div>\n</div>\n\n{% if '127.0.0.1' in cfg.url_publica or 'localhost' in cfg.url_publica %}\n<div class=\"alert alert-warning\"><span>⚠️ O link de assinatura está apontando para este computador ({{ cfg.url_publica }}).\n  O cliente só conseguirá abrir de fora depois que o <b>link público</b> for configurado em\n  <a href=\"{{ url_for('contratos.configuracoes') }}\" class=\"text-gold\">Configurações</a>.</span></div>\n{% endif %}\n\n<div class=\"metrics-grid ct-kpis\">\n  {% for s, rot, cor in [('rascunho','Aguardando envio','#a3a3a3'),('aguardando','Aguardando assinatura','#fbbf24'),\n                         ('assinado','Assinados · aguardam depósito','#60a5fa'),('concluido','Concluídos','#4ade80')] %}\n  <a class=\"metric-card ct-kpi {{ 'on' if status_filtro == s }}\" href=\"?status={{ s }}\">\n    <div class=\"metric-value\" style=\"color:{{ cor }}\">{{ resumo[s] }}</div>\n    <div class=\"metric-label\">{{ rot }}{% if s == 'concluido' %} · {{ resumo.concluidos_mes }} no mês{% endif %}</div>\n  </a>\n  {% endfor %}\n  <a class=\"metric-card ct-kpi\" href=\"{{ url_for('contratos.novo') }}\">\n    <div class=\"metric-value\" style=\"color:#d4af37\">{{ pendentes }}</div>\n    <div class=\"metric-label\">Cotas pendentes sem contrato</div>\n  </a>\n</div>\n\n<form method=\"get\" class=\"toolbar\">\n  <div class=\"toolbar-left\">\n    <input type=\"text\" name=\"q\" value=\"{{ q }}\" placeholder=\"Buscar cliente, CPF ou código…\" class=\"form-control\" style=\"width:280px;\">\n    <select name=\"status\" class=\"form-control form-control-sm\" style=\"width:220px;\">\n      <option value=\"\">Todos os status</option>\n      {% for k, s in STATUS.items() %}<option value=\"{{ k }}\" {{ 'selected' if status_filtro == k }}>{{ s.nome }}</option>{% endfor %}\n    </select>\n    <button class=\"btn btn-secondary btn-sm\">Filtrar</button>\n    {% if q or status_filtro %}<a href=\"{{ url_for('contratos.painel') }}\" class=\"btn btn-secondary btn-sm\">Limpar</a>{% endif %}\n  </div>\n</form>\n\n{% if contratos %}\n<div class=\"table-wrap\">\n  <table>\n    <thead><tr><th>Cliente</th><th>Documento</th><th>Cotas</th><th style=\"text-align:right\">Valor</th>\n      <th>Assinaturas</th><th>Status</th><th>Última movimentação</th><th></th></tr></thead>\n    <tbody>\n    {% for c in contratos %}\n      {% set st = STATUS[c.status] %}\n      <tr onclick=\"location.href='{{ url_for('contratos.detalhe', cid=c.id) }}'\" style=\"cursor:pointer\">\n        <td><b>{{ c.cliente_nome }}</b><div class=\"text-dim text-mono\" style=\"font-size:11px\">{{ fmt_doc(c.cliente_cpf) }}</div></td>\n        <td>{{ TIPOS[c.tipo] }}<div class=\"text-dim\" style=\"font-size:11px\">{{ c.produto_nome }}</div></td>\n        <td class=\"text-mono\">{{ c.dados.cotas | map(attribute='numero') | join(', ') }}</td>\n        <td style=\"text-align:right;white-space:nowrap\" class=\"text-mono\">{{ moeda(c.dados.valor_total) }}</td>\n        <td>\n          <div class=\"ct-prog\"><i style=\"width:{{ (100 * c.assinaturas / (c.signatarios or 1)) | round }}%\"></i></div>\n          <span style=\"font-size:11px\" class=\"text-dim\">{{ c.assinaturas }}/{{ c.signatarios }}{% if c.visto_em and c.status == 'aguardando' %} · 👁 visto {{ c.visto_em | ct_data(True) }}{% endif %}</span>\n        </td>\n        <td><span class=\"ct-badge\" style=\"--c:{{ st.cor }}\">{{ st.nome }}</span></td>\n        <td class=\"text-dim\" style=\"font-size:12px\">\n          {{ (c.concluido_em or c.assinado_em or c.enviado_em or c.criado_em) | ct_data(True) }}</td>\n        <td style=\"text-align:right\"><a href=\"{{ url_for('contratos.detalhe', cid=c.id) }}\" class=\"btn btn-secondary btn-sm\">Abrir</a></td>\n      </tr>\n    {% endfor %}\n    </tbody>\n  </table>\n</div>\n{% else %}\n<div class=\"empty-state\">\n  <div class=\"empty-state-icon\">✍️</div>\n  <div class=\"empty-state-title\">Nenhum contrato {{ 'com esse filtro' if q or status_filtro else 'ainda' }}</div>\n  <div class=\"empty-state-sub\">Cadastre uma nova cota marcando “Gerar Termo de Aquisição” — o contrato aparece aqui pronto para envio.</div>\n</div>\n{% endif %}\n{% endblock %}\n",
  "contratos/publico/assinar.html": "<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta name=\"robots\" content=\"noindex, nofollow\">\n<title>Assinatura de documento · Capuzzo</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Great+Vibes&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{--ouro:#C7A955;--ouro-esc:#9E7C34;--tinta:#16140F;--muted:#6E6552;--linha:#E4DFD2;--fundo:#F5F2EA;--ok:#2d7d46;--erro:#b42318}\n  *{box-sizing:border-box}\n  body{margin:0;background:var(--fundo);color:var(--tinta);font:15px/1.5 \"Segoe UI\",Roboto,Arial,sans-serif}\n  header{background:#fff;border-bottom:1px solid var(--linha)}\n  header .in{max-width:1100px;margin:0 auto;padding:10px 16px;display:flex;align-items:center;justify-content:space-between;gap:12px}\n  header img{height:46px}\n  header .seg{font-size:12px;color:var(--muted);display:flex;align-items:center;gap:6px}\n  .faixa{height:4px;background:linear-gradient(90deg,var(--ouro-esc),#f1d98a,var(--ouro-esc))}\n  main{max-width:1100px;margin:0 auto;padding:20px 16px 60px;display:grid;grid-template-columns:minmax(0,1fr) 360px;gap:18px;align-items:start}\n  .card{background:#fff;border:1px solid var(--linha);border-radius:10px;padding:18px}\n  h1{font-size:21px;margin:0 0 4px;letter-spacing:-.2px}\n  .sub{color:var(--muted);font-size:13.5px}\n  .docs{display:flex;flex-direction:column;gap:6px;margin:14px 0 0}\n  .doc{display:flex;gap:10px;align-items:center;border:1px solid var(--linha);border-radius:8px;padding:9px 12px;font-size:14px}\n  .doc small{display:block;color:var(--muted);font-size:12px}\n  .viewer{margin-top:14px;border:1px solid var(--linha);border-radius:8px;overflow:hidden;background:#e9e6df}\n  .viewer iframe{display:block;width:100%;height:72vh;border:0}\n  .viewer .acoes{display:flex;justify-content:flex-end;gap:12px;padding:8px 12px;background:#fff;border-top:1px solid var(--linha);font-size:13px}\n  a{color:var(--ouro-esc)}\n  .pessoas{margin:0;padding:0;list-style:none}\n  .pessoas li{display:flex;gap:10px;padding:8px 0;border-top:1px solid #f0ece2}\n  .pessoas li:first-child{border-top:0}\n  .pessoas .b{width:20px;height:20px;border-radius:50%;border:2px solid #c9c2b0;flex:none;margin-top:2px;display:grid;place-items:center;color:#fff;font-size:11px}\n  .pessoas .b.ok{background:var(--ok);border-color:var(--ok)}\n  .pessoas small{display:block;color:var(--muted);font-size:12px}\n  .passo{margin-top:16px;padding-top:14px;border-top:1px solid var(--linha)}\n  .passo h3{font-size:13px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);margin:0 0 8px}\n  label.chk{display:flex;gap:10px;align-items:flex-start;font-size:14px;cursor:pointer}\n  label.chk input{width:18px;height:18px;margin-top:2px;accent-color:var(--ouro-esc)}\n  input.campo{width:100%;padding:11px 12px;border:1px solid #cfc8b6;border-radius:7px;font-size:16px;background:#fff}\n  input.campo:focus{outline:2px solid var(--ouro);border-color:var(--ouro)}\n  .linha2{display:flex;gap:8px}\n  .btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;border:0;border-radius:7px;padding:11px 16px;font-weight:700;font-size:14.5px;cursor:pointer}\n  .btn-ouro{background:var(--ouro);color:#141210}\n  .btn-ouro:hover{background:#b8962e}\n  .btn-sec{background:#fff;border:1px solid #cfc8b6;color:var(--tinta)}\n  .btn[disabled]{opacity:.5;cursor:not-allowed}\n  .btn-full{width:100%;padding:14px;font-size:16px}\n  .tabs{display:flex;gap:4px;background:#f1ede3;border-radius:7px;padding:3px;margin-bottom:8px}\n  .tabs button{flex:1;border:0;background:none;padding:7px;border-radius:5px;font-weight:600;color:var(--muted);cursor:pointer}\n  .tabs button.on{background:#fff;color:var(--tinta);box-shadow:0 1px 3px rgba(0,0,0,.1)}\n  .pad{position:relative;border:1.5px dashed #c9c2b0;border-radius:8px;background:#fff;touch-action:none}\n  .pad canvas{display:block;width:100%;height:150px;cursor:crosshair}\n  .pad .dica{position:absolute;left:12px;bottom:8px;font-size:12px;color:#aaa;pointer-events:none}\n  .pad .limpar{position:absolute;right:8px;top:6px;font-size:12px;background:none;border:0;color:var(--ouro-esc);cursor:pointer}\n  .previa{border:1.5px dashed #c9c2b0;border-radius:8px;background:#fff;min-height:80px;display:flex;align-items:center;padding:8px 14px;\n          font-family:\"Great Vibes\",\"Segoe Script\",cursive;font-size:38px;color:#1d2a5a;overflow:hidden;white-space:nowrap;margin-top:8px}\n  .msg{font-size:13.5px;margin-top:8px;min-height:1em}\n  .msg.erro{color:var(--erro)} .msg.ok{color:var(--ok)}\n  .status{border-radius:10px;padding:18px;text-align:center}\n  .status.ok{background:#eef8f1;border:1px solid #b9e2c6}\n  .status.aviso{background:#fff8e6;border:1px solid #f0dca0}\n  .status .ic{font-size:40px;line-height:1}\n  .legal{font-size:11.5px;color:var(--muted);margin-top:12px}\n  .oculto{display:none}\n  @media (max-width:900px){main{grid-template-columns:1fr}.viewer iframe{height:60vh}}\n</style>\n</head>\n<body>\n<header><div class=\"in\"><img src=\"{{ logo }}\" alt=\"Capuzzo Assessoria Empresarial\">\n  <span class=\"seg\">🔒 Ambiente seguro de assinatura eletrônica</span></div></header>\n<div class=\"faixa\"></div>\n\n<main>\n  <section class=\"card\">\n    <h1>{{ TIPOS[c.tipo] }}</h1>\n    <div class=\"sub\">{{ d.produto.nome }} · {{ d.qtd }} cota(s) nº {{ d.cotas | map(attribute='numero') | join(', ') }} · {{ moeda((d.retirada or {}).valor or d.valor_total) }}</div>\n    <div class=\"docs\">\n      <div class=\"doc\">📄<div>{{ TIPOS[c.tipo] }}<small>Documento principal · preenchido com seus dados</small></div></div>\n      {% if d.anexo_nome %}<div class=\"doc\">📎<div>{{ d.anexo_nome }}<small>Anexo · parte integrante do termo</small></div></div>{% endif %}\n    </div>\n    <div class=\"viewer\">\n      <iframe src=\"{{ url_for('contratos.assinar_documento', token=c.token) }}\" title=\"Documento\"></iframe>\n      <div class=\"acoes\"><a href=\"{{ url_for('contratos.assinar_documento', token=c.token) }}\" target=\"_blank\" rel=\"noopener\">Abrir em tela cheia</a>\n        <a href=\"{{ url_for('contratos.assinar_documento', token=c.token, imprimir=1) }}\" target=\"_blank\" rel=\"noopener\">Baixar PDF</a></div>\n    </div>\n  </section>\n\n  <aside class=\"card\">\n    <h3 style=\"margin:0 0 6px;font-size:13px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted)\">Signatários</h3>\n    <ul class=\"pessoas\">\n      {% for s in c.signatarios %}\n      <li><span class=\"b {{ 'ok' if s.status == 'assinado' }}\">{{ '✔' if s.status == 'assinado' }}</span>\n        <div><b>{{ s.nome }}</b><small>{{ 'Assinou em ' ~ (s.assinado_em | ct_data(True)) if s.status == 'assinado' else 'Aguardando assinatura' }}</small></div></li>\n      {% endfor %}\n    </ul>\n\n    {% if ok or c.status in ('assinado', 'concluido') %}\n      <div class=\"status ok\" style=\"margin-top:14px\">\n        <div class=\"ic\">✅</div>\n        <p style=\"margin:8px 0 4px;font-weight:700\">Documento assinado com sucesso</p>\n        <p style=\"margin:0;font-size:13.5px\">Enviamos uma cópia para o seu e-mail.{% if c.tipo == 'aquisicao' %} As cotas serão ativadas após a confirmação do depósito.{% elif c.tipo == 'retirada' %} O valor será creditado {{ d.produto_doc.prazo_credito }} a contar da assinatura.{% endif %}</p>\n        {% if c.tipo == 'aquisicao' and cfg.instrucoes_deposito %}<p style=\"margin:12px 0 0;text-align:left;font-size:13.5px;white-space:pre-line;background:#fff;border:1px solid #d9eedf;border-radius:8px;padding:10px\"><b>Dados para depósito</b>\n{{ cfg.instrucoes_deposito }}</p>{% endif %}\n        <p style=\"margin:12px 0 0\"><a class=\"btn btn-sec\" href=\"{{ url_for('contratos.assinar_documento', token=c.token, imprimir=1) }}\" target=\"_blank\" rel=\"noopener\">⬇ Baixar documento assinado</a></p>\n      </div>\n    {% elif c.status == 'cancelado' %}\n      <div class=\"status aviso\" style=\"margin-top:14px\"><div class=\"ic\">⚠️</div>\n        <p style=\"margin:8px 0 0\">Este documento foi cancelado pela Capuzzo e não pode mais ser assinado. Em caso de dúvida, fale com {{ cfg.email_copia }}.</p></div>\n    {% elif c.status != 'aguardando' %}\n      <div class=\"status aviso\" style=\"margin-top:14px\"><div class=\"ic\">⏳</div>\n        <p style=\"margin:8px 0 0\">Este documento ainda não foi liberado para assinatura.</p></div>\n    {% else %}\n    <form id=\"f\" autocomplete=\"off\" onsubmit=\"return false\">\n      <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n      <div class=\"passo\">\n        <h3>1 · Leitura</h3>\n        <label class=\"chk\"><input type=\"checkbox\" id=\"aceite\"> <span>Li e concordo com o <b>{{ TIPOS[c.tipo] }}</b>{% if d.anexo_nome %} e com o <b>Regulamento</b> anexo{% endif %}.</span></label>\n      </div>\n      <div class=\"passo\">\n        <h3>2 · Confirme sua identidade</h3>\n        <input class=\"campo\" id=\"cpf\" inputmode=\"numeric\" placeholder=\"Seu CPF{{ '/CNPJ' if d.investidor.documento_tipo == 'CNPJ' }}\" maxlength=\"18\">\n        <div style=\"margin-top:8px\" class=\"linha2\">\n          <input class=\"campo\" id=\"codigo\" inputmode=\"numeric\" placeholder=\"Código do e-mail\" maxlength=\"6\" style=\"flex:1\">\n          <button type=\"button\" class=\"btn btn-sec\" id=\"btn-codigo\">Enviar código</button>\n        </div>\n        <div class=\"msg\" id=\"msg-codigo\">O código será enviado para {{ email_mask }}.</div>\n      </div>\n      <div class=\"passo\">\n        <h3>3 · Sua assinatura</h3>\n        <div class=\"tabs\"><button type=\"button\" class=\"on\" data-t=\"desenho\">Desenhar</button><button type=\"button\" data-t=\"texto\">Digitar</button></div>\n        <div id=\"t-desenho\" class=\"pad\"><canvas id=\"cv\"></canvas><span class=\"dica\">Assine aqui com o dedo ou o mouse</span>\n          <button type=\"button\" class=\"limpar\" id=\"limpar\">Limpar</button></div>\n        <div id=\"t-texto\" class=\"oculto\">\n          <input class=\"campo\" id=\"texto\" placeholder=\"Digite seu nome completo\" value=\"{{ cli.nome }}\" maxlength=\"80\">\n          <div class=\"previa\" id=\"previa\">{{ cli.nome }}</div>\n        </div>\n      </div>\n      <div class=\"passo\">\n        <button type=\"button\" class=\"btn btn-ouro btn-full\" id=\"btn-assinar\">✍️ Assinar documento</button>\n        <div class=\"msg\" id=\"msg\"></div>\n        <p class=\"legal\">Ao assinar, você concorda que sua assinatura eletrônica tem validade jurídica (MP 2.200-2/2001, art. 10, §2º, e Lei 14.063/2020).\n          Registramos data, hora, IP e o código de verificação para comprovar a autoria.</p>\n      </div>\n    </form>\n    {% endif %}\n  </aside>\n</main>\n\n{% if c.status == 'aguardando' and not ok %}\n<script>\n(function(){\n  var f = document.getElementById('f'), csrf = f.querySelector('[name=_csrf]').value;\n  var tipo = 'desenho', desenhou = false;\n  function post(url, dados){\n    var fd = new FormData(); fd.append('_csrf', csrf);\n    for(var k in dados) fd.append(k, dados[k]);\n    return fetch(url, {method:'POST', body:fd, credentials:'same-origin'}).then(function(r){\n      return r.json().catch(function(){ return {ok:false, msg:'Sessão expirada. Recarregue a página.'}; });\n    });\n  }\n  function msg(el, t, cls){ el.textContent = t; el.className = 'msg ' + (cls||''); }\n\n  /* CPF/CNPJ */\n  var cpf = document.getElementById('cpf');\n  cpf.addEventListener('input', function(){\n    var d = cpf.value.replace(/\\D/g,'').slice(0,14), v = d;\n    if(d.length <= 11) v = d.replace(/(\\d{3})(\\d)/,'$1.$2').replace(/(\\d{3})(\\d)/,'$1.$2').replace(/(\\d{3})(\\d{1,2})$/,'$1-$2');\n    else v = d.replace(/^(\\d{2})(\\d)/,'$1.$2').replace(/^(\\d{2})\\.(\\d{3})(\\d)/,'$1.$2.$3').replace(/\\.(\\d{3})(\\d)/,'.$1/$2').replace(/(\\d{4})(\\d)/,'$1-$2');\n    cpf.value = v;\n  });\n\n  /* Código */\n  var bc = document.getElementById('btn-codigo'), mc = document.getElementById('msg-codigo');\n  bc.addEventListener('click', function(){\n    bc.disabled = true; msg(mc, 'Enviando…');\n    post('{{ url_for(\"contratos.assinar_codigo\", token=c.token) }}', {}).then(function(j){\n      msg(mc, j.msg, j.ok ? 'ok' : 'erro');\n      var s = j.ok ? 45 : 0;\n      (function tick(){ if(s <= 0){ bc.disabled = false; bc.textContent = j.ok ? 'Reenviar' : 'Enviar código'; return; }\n        bc.textContent = 'Reenviar (' + s-- + ')'; setTimeout(tick, 1000); })();\n      if(j.ok) document.getElementById('codigo').focus();\n    }).catch(function(){ bc.disabled = false; msg(mc, 'Falha de conexão. Tente de novo.', 'erro'); });\n  });\n\n  /* Abas */\n  document.querySelectorAll('.tabs button').forEach(function(b){\n    b.addEventListener('click', function(){\n      document.querySelectorAll('.tabs button').forEach(function(x){ x.classList.toggle('on', x === b); });\n      tipo = b.dataset.t;\n      document.getElementById('t-desenho').classList.toggle('oculto', tipo !== 'desenho');\n      document.getElementById('t-texto').classList.toggle('oculto', tipo !== 'texto');\n      if(tipo === 'desenho') ajustar();\n    });\n  });\n  var tx = document.getElementById('texto'), pv = document.getElementById('previa');\n  tx.addEventListener('input', function(){ pv.textContent = tx.value; });\n\n  /* Quadro de assinatura */\n  var cv = document.getElementById('cv'), ctx = cv.getContext('2d'), tracando = false, ult = null;\n  function ajustar(){\n    var r = cv.getBoundingClientRect(), dpr = window.devicePixelRatio || 1;\n    if(!r.width) return;\n    var img = desenhou ? cv.toDataURL() : null;\n    cv.width = r.width * dpr; cv.height = r.height * dpr;\n    ctx.setTransform(dpr,0,0,dpr,0,0); ctx.lineWidth = 2.4; ctx.lineCap = 'round'; ctx.lineJoin = 'round'; ctx.strokeStyle = '#1d2a5a';\n    if(img){ var i = new Image(); i.onload = function(){ ctx.drawImage(i, 0, 0, r.width, r.height); }; i.src = img; }\n  }\n  function pos(e){ var r = cv.getBoundingClientRect(); return {x:e.clientX - r.left, y:e.clientY - r.top}; }\n  cv.addEventListener('pointerdown', function(e){ tracando = true; ult = pos(e); cv.setPointerCapture(e.pointerId); });\n  cv.addEventListener('pointermove', function(e){\n    if(!tracando) return; var p = pos(e);\n    ctx.beginPath(); ctx.moveTo(ult.x, ult.y); ctx.lineTo(p.x, p.y); ctx.stroke(); ult = p; desenhou = true;\n  });\n  ['pointerup','pointercancel','pointerleave'].forEach(function(ev){ cv.addEventListener(ev, function(){ tracando = false; }); });\n  document.getElementById('limpar').addEventListener('click', function(){ desenhou = false; ctx.clearRect(0,0,cv.width,cv.height); });\n  window.addEventListener('resize', ajustar); ajustar();\n\n  function recortar(){\n    /* recorta a área desenhada e devolve PNG com fundo transparente */\n    var w = cv.width, h = cv.height, dados = ctx.getImageData(0,0,w,h).data, x0=w, y0=h, x1=0, y1=0;\n    for(var y=0;y<h;y++) for(var x=0;x<w;x++) if(dados[(y*w+x)*4+3] > 0){ if(x<x0)x0=x; if(y<y0)y0=y; if(x>x1)x1=x; if(y>y1)y1=y; }\n    if(x1 <= x0) return '';\n    var m = 8, o = document.createElement('canvas'); o.width = x1-x0+2*m; o.height = y1-y0+2*m;\n    o.getContext('2d').drawImage(cv, x0-m, y0-m, o.width, o.height, 0, 0, o.width, o.height);\n    return o.toDataURL('image/png');\n  }\n\n  /* Assinar */\n  var ba = document.getElementById('btn-assinar'), ma = document.getElementById('msg');\n  ba.addEventListener('click', function(){\n    if(!document.getElementById('aceite').checked) return msg(ma, 'Marque que leu e concorda com os documentos.', 'erro');\n    if(cpf.value.replace(/\\D/g,'').length < 11) return msg(ma, 'Informe seu CPF.', 'erro');\n    if(document.getElementById('codigo').value.replace(/\\D/g,'').length !== 6) return msg(ma, 'Informe o código de 6 dígitos enviado ao seu e-mail.', 'erro');\n    if(tipo === 'desenho' && !desenhou) return msg(ma, 'Desenhe sua assinatura no quadro (ou use “Digitar”).', 'erro');\n    ba.disabled = true; msg(ma, 'Registrando assinatura…');\n    post('{{ url_for(\"contratos.assinar_confirmar\", token=c.token) }}', {\n      aceite:'1', cpf:cpf.value, codigo:document.getElementById('codigo').value, tipo:tipo,\n      imagem: tipo === 'desenho' ? recortar() : '', texto: tx.value\n    }).then(function(j){\n      if(j.ok){ window.location = j.redirect; return; }\n      ba.disabled = false; msg(ma, j.msg, 'erro');\n    }).catch(function(){ ba.disabled = false; msg(ma, 'Falha de conexão. Tente de novo.', 'erro'); });\n  });\n})();\n</script>\n{% endif %}\n</body>\n</html>\n",
  "cotas_editar_lote.html": "{% extends \"base.html\" %}\n{% block title %}Edição em lote de cotas — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n\n<a href=\"{{ referrer or url_for('cotas_lista') }}\" class=\"back-link\">← Voltar sem salvar</a>\n\n<div class=\"page-header\">\n  <div class=\"page-header-icon\">✏️</div>\n  <div class=\"page-header-title\">Edição em lote de cotas</div>\n  <div class=\"page-header-sub\">\n    {{ cotas | length }} cota(s) selecionada(s) — edite linha por linha ou preencha um campo\n    igual para todas de uma vez\n  </div>\n</div>\n\n<!-- ══════════ Painel: aplicar o mesmo valor a todas ══════════ -->\n<div class=\"form-section\" style=\"margin-bottom:18px;\">\n  <div class=\"form-section-title\">⚡ Aplicar a todas as linhas</div>\n  <p class=\"text-dim\" style=\"font-size:12px;margin:-4px 0 14px;\">\n    Preencha só o que quiser padronizar e clique em <strong>Aplicar</strong>. Nada é salvo\n    neste momento — os valores apenas caem nas linhas abaixo, onde você ainda pode ajustar\n    caso a caso.\n  </p>\n\n  <div class=\"form-row\">\n    <div class=\"form-group\">\n      <label>Data de aquisição</label>\n      <div style=\"display:flex;gap:6px;\">\n        <input type=\"date\" id=\"fill-acquisition_date\" class=\"form-control form-control-sm\">\n        <button type=\"button\" class=\"btn btn-secondary btn-sm\"\n                data-fill-target=\"acquisition_date\">Aplicar</button>\n      </div>\n    </div>\n    <div class=\"form-group\">\n      <label>Última renovação</label>\n      <div style=\"display:flex;gap:6px;\">\n        <input type=\"date\" id=\"fill-last_renewal_date\" class=\"form-control form-control-sm\">\n        <button type=\"button\" class=\"btn btn-secondary btn-sm\"\n                data-fill-target=\"last_renewal_date\">Aplicar</button>\n      </div>\n    </div>\n    <div class=\"form-group\">\n      <label>Vencimento</label>\n      <div style=\"display:flex;gap:6px;\">\n        <input type=\"date\" id=\"fill-maturity_date\" class=\"form-control form-control-sm\">\n        <button type=\"button\" class=\"btn btn-secondary btn-sm\"\n                data-fill-target=\"maturity_date\">Aplicar</button>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"form-row\">\n    <div class=\"form-group\">\n      <label>Valor da cota (R$)</label>\n      <div style=\"display:flex;gap:6px;\">\n        <input type=\"text\" id=\"fill-share_value\" class=\"form-control form-control-sm\"\n               data-mask=\"currency\" placeholder=\"10.000,00\">\n        <button type=\"button\" class=\"btn btn-secondary btn-sm\"\n                data-fill-target=\"share_value\">Aplicar</button>\n      </div>\n    </div>\n    <div class=\"form-group\">\n      <label>Status</label>\n      <div style=\"display:flex;gap:6px;\">\n        <select id=\"fill-status\" class=\"form-control form-control-sm\">\n          <option value=\"\">—</option>\n          <option value=\"ativa\">Ativa</option>\n          <option value=\"pendente\">Pendente</option>\n          <option value=\"inativa\">Inativa</option>\n        </select>\n        <button type=\"button\" class=\"btn btn-secondary btn-sm\"\n                data-fill-target=\"status\">Aplicar</button>\n      </div>\n    </div>\n    <div class=\"form-group\">\n      <label>Data de retirada <span class=\"text-dim\">(cotas inativas)</span></label>\n      <div style=\"display:flex;gap:6px;\">\n        <input type=\"date\" id=\"fill-withdrawal_date\" class=\"form-control form-control-sm\">\n        <button type=\"button\" class=\"btn btn-secondary btn-sm\"\n                data-fill-target=\"withdrawal_date\">Aplicar</button>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"form-row\">\n    <div class=\"form-group\" style=\"flex:1;\">\n      <label>Observações</label>\n      <div style=\"display:flex;gap:6px;\">\n        <input type=\"text\" id=\"fill-notes\" class=\"form-control form-control-sm\"\n               maxlength=\"300\" placeholder=\"Texto igual para todas…\">\n        <button type=\"button\" class=\"btn btn-secondary btn-sm\"\n                data-fill-target=\"notes\">Aplicar</button>\n      </div>\n    </div>\n    <div class=\"form-group\" style=\"flex:1;\">\n      <label>Cliente (cotista)</label>\n      <div style=\"display:flex;gap:6px;\">\n        <select id=\"fill-client_id\" class=\"form-control form-control-sm\">\n          <option value=\"\">—</option>\n          {% for c in clientes %}\n          <option value=\"{{ c.id }}\">{{ c.display_name }}</option>\n          {% endfor %}\n        </select>\n        <button type=\"button\" class=\"btn btn-secondary btn-sm\"\n                data-fill-target=\"client_id\">Aplicar</button>\n      </div>\n    </div>\n  </div>\n\n  <div style=\"display:flex;align-items:center;gap:18px;flex-wrap:wrap;margin-top:6px;\">\n    <label class=\"bulk-toolbar-select-all\" style=\"cursor:pointer;\">\n      <input type=\"checkbox\" id=\"fill-only-empty\">\n      Preencher somente os campos vazios\n    </label>\n    <button type=\"button\" class=\"btn btn-secondary btn-sm\" id=\"btn-fill-all\">\n      ⚡ Aplicar tudo o que está preenchido acima\n    </button>\n  </div>\n</div>\n\n<!-- ══════════ Grid editável ══════════ -->\n<form method=\"post\" action=\"{{ url_for('cotas_editar_lote_salvar') }}\" id=\"form-lote\">\n  <input type=\"hidden\" name=\"referrer\" value=\"{{ referrer }}\">\n\n  <div class=\"text-dim\" style=\"font-size:11px;margin-bottom:6px;\">\n    ↔ A tabela rola na horizontal — o número da cota fica fixo à esquerda.\n  </div>\n\n  <div class=\"table-wrap\" id=\"lote-table-wrap\">\n    <table id=\"tabela-lote\">\n      <thead>\n        <tr>\n          <th style=\"min-width:90px;\">Nº da cota</th>\n          <th style=\"min-width:120px;\">Produto</th>\n          <th style=\"min-width:170px;\">Cotista</th>\n          <th style=\"min-width:105px;\">Valor (R$)</th>\n          <th style=\"min-width:135px;\">Aquisição</th>\n          <th style=\"min-width:135px;\">Últ. renovação</th>\n          <th style=\"min-width:135px;\">Vencimento</th>\n          <th style=\"min-width:100px;\">Status</th>\n          <th style=\"min-width:135px;\">Retirada</th>\n          <th style=\"min-width:170px;\">Observações</th>\n          <th style=\"text-align:center;min-width:44px;\">Tirar</th>\n        </tr>\n      </thead>\n      <tbody>\n        {% for cota in cotas %}\n        <tr class=\"lote-row\">\n          <td>\n            <input type=\"hidden\" name=\"row_id[]\" value=\"{{ cota.id }}\">\n            <input type=\"text\" name=\"row_share_number[]\" class=\"form-control form-control-sm\"\n                   data-field=\"share_number\"\n                   value=\"{{ cota.share_number or '' }}\" style=\"font-weight:700;color:#d4af37;\">\n          </td>\n          <td>\n            <select name=\"row_condominium_id[]\" class=\"form-control form-control-sm\"\n                    data-field=\"condominium_id\">\n              {% for c in conds %}\n              <option value=\"{{ c.id }}\"\n                {{ 'selected' if c.id == cota.condominium_id else '' }}>{{ c.name }}</option>\n              {% endfor %}\n            </select>\n          </td>\n          <td>\n            <select name=\"row_client_id[]\" class=\"form-control form-control-sm\"\n                    data-field=\"client_id\">\n              {% for c in clientes %}\n              <option value=\"{{ c.id }}\"\n                {{ 'selected' if c.id == cota.client_id else '' }}>{{ c.display_name }}</option>\n              {% endfor %}\n            </select>\n          </td>\n          <td>\n            <input type=\"text\" name=\"row_share_value[]\" class=\"form-control form-control-sm\"\n                   data-mask=\"currency\" data-field=\"share_value\"\n                   value=\"{{ '%.2f' | format(cota.share_value or 0) | replace('.', ',') }}\">\n          </td>\n          <td>\n            <input type=\"date\" name=\"row_acquisition_date[]\" class=\"form-control form-control-sm\"\n                   data-field=\"acquisition_date\" value=\"{{ cota.acquisition_date or '' }}\">\n          </td>\n          <td>\n            <input type=\"date\" name=\"row_last_renewal_date[]\" class=\"form-control form-control-sm\"\n                   data-field=\"last_renewal_date\" value=\"{{ cota.last_renewal_date or '' }}\">\n          </td>\n          <td>\n            <input type=\"date\" name=\"row_maturity_date[]\" class=\"form-control form-control-sm\"\n                   data-field=\"maturity_date\" value=\"{{ cota.maturity_date or '' }}\">\n          </td>\n          <td>\n            <select name=\"row_status[]\" class=\"form-control form-control-sm\" data-field=\"status\">\n              <option value=\"ativa\"    {{ 'selected' if cota.status == 'ativa'    else '' }}>Ativa</option>\n              <option value=\"pendente\" {{ 'selected' if cota.status == 'pendente' else '' }}>Pendente</option>\n              <option value=\"inativa\"  {{ 'selected' if cota.status == 'inativa'  else '' }}>Inativa</option>\n            </select>\n          </td>\n          <td>\n            <input type=\"date\" name=\"row_withdrawal_date[]\" class=\"form-control form-control-sm\"\n                   data-field=\"withdrawal_date\" value=\"{{ cota.withdrawal_date or '' }}\">\n            {% if cota.withdrawal_requested %}\n            <div class=\"text-dim\" style=\"font-size:10px;margin-top:2px;\">\n              📤 em retirada · efetiva {{ cota.withdrawal_effective_date or '—' }}\n            </div>\n            {% endif %}\n          </td>\n          <td>\n            <input type=\"text\" name=\"row_notes[]\" class=\"form-control form-control-sm\"\n                   data-field=\"notes\" maxlength=\"300\" value=\"{{ cota.notes or '' }}\">\n          </td>\n          <td style=\"text-align:center;\">\n            <button type=\"button\" class=\"btn btn-secondary btn-sm btn-remover-linha\"\n                    title=\"Remover esta cota da edição em lote (não altera nada no cadastro)\">✕</button>\n          </td>\n        </tr>\n        {% endfor %}\n      </tbody>\n    </table>\n  </div>\n\n  <div class=\"note-box\" style=\"margin-top:14px;\">\n    <label style=\"display:flex;align-items:center;gap:8px;cursor:pointer;font-size:13px;color:#ccc;\">\n      <input type=\"checkbox\" name=\"allow_duplicate_share_number\">\n      Lançamento histórico — permitir números de cota repetidos\n    </label>\n    <div class=\"text-dim\" style=\"font-size:11px;margin-top:6px;\">\n      Cada cota alterada gera um registro individual no log de auditoria. Um backup\n      automático do banco é criado antes de salvar.\n    </div>\n  </div>\n\n  <div class=\"page-actions\">\n    <a href=\"{{ referrer or url_for('cotas_lista') }}\" class=\"btn btn-secondary\">Cancelar</a>\n    <button type=\"submit\" class=\"btn btn-primary\" id=\"btn-salvar-lote\">\n      💾 Salvar <span id=\"lote-row-count\">{{ cotas | length }}</span> cota(s)\n    </button>\n  </div>\n</form>\n\n<style>\n  /* a .table-wrap padrão usa overflow:hidden — aqui o grid precisa rolar na horizontal */\n  #lote-table-wrap { overflow-x: auto; overflow-y: visible; }\n  #tabela-lote { min-width: 1280px; }\n  #tabela-lote td { padding: 6px 6px; vertical-align: top; }\n  #tabela-lote th { white-space: nowrap; }\n  #tabela-lote .form-control-sm {\n    width: 100%; box-sizing: border-box; font-size: 12px; padding: 5px 6px;\n  }\n  /* Nº da cota fica fixo ao rolar a tabela na horizontal */\n  #tabela-lote th:first-child,\n  #tabela-lote td:first-child {\n    position: sticky; left: 0; z-index: 2; background: #111113;\n    box-shadow: 1px 0 0 #1e1e1e;\n  }\n</style>\n\n{% endblock %}\n\n{% block scripts %}\n<script>\n(function () {\n  var FIELDS = ['share_number', 'condominium_id', 'client_id', 'share_value',\n                'acquisition_date', 'last_renewal_date', 'maturity_date',\n                'status', 'withdrawal_date', 'notes'];\n\n  function rows() {\n    return Array.prototype.slice.call(document.querySelectorAll('#tabela-lote tr.lote-row'));\n  }\n\n  function updateCount() {\n    var n = rows().length;\n    var el = document.getElementById('lote-row-count');\n    if (el) el.textContent = n;\n    var btn = document.getElementById('btn-salvar-lote');\n    if (btn) btn.disabled = n === 0;\n  }\n\n  function applyField(field) {\n    var src = document.getElementById('fill-' + field);\n    if (!src) return 0;\n    var val = (src.value || '').trim();\n    if (!val) return 0;\n\n    var onlyEmpty = document.getElementById('fill-only-empty');\n    onlyEmpty = onlyEmpty && onlyEmpty.checked;\n    var changed = 0;\n\n    rows().forEach(function (tr) {\n      var target = tr.querySelector('[data-field=\"' + field + '\"]');\n      if (!target) return;\n      if (onlyEmpty && (target.value || '').trim() !== '') return;\n      target.value = val;\n      target.dispatchEvent(new Event('change', { bubbles: true }));\n      /* feedback visual rápido */\n      target.style.borderColor = '#d4af37';\n      setTimeout(function () { target.style.borderColor = ''; }, 900);\n      changed++;\n    });\n    return changed;\n  }\n\n  document.querySelectorAll('[data-fill-target]').forEach(function (btn) {\n    btn.addEventListener('click', function () {\n      applyField(btn.dataset.fillTarget);\n    });\n  });\n\n  var fillAll = document.getElementById('btn-fill-all');\n  if (fillAll) {\n    fillAll.addEventListener('click', function () {\n      var total = 0;\n      FIELDS.forEach(function (f) { total += applyField(f); });\n      if (total === 0) {\n        alert('Preencha ao menos um campo no painel \"Aplicar a todas\" antes de aplicar.');\n      }\n    });\n  }\n\n  /* Remover linha do lote (não mexe no cadastro) */\n  document.addEventListener('click', function (e) {\n    var btn = e.target.closest ? e.target.closest('.btn-remover-linha') : null;\n    if (!btn) return;\n    var tr = btn.closest('tr');\n    if (tr) { tr.remove(); updateCount(); }\n  });\n\n  /* Data de retirada só é usada quando o status é inativa */\n  function syncWithdrawal(tr) {\n    var st = tr.querySelector('[data-field=\"status\"]');\n    var wd = tr.querySelector('[data-field=\"withdrawal_date\"]');\n    if (!st || !wd) return;\n    var inativa = st.value === 'inativa';\n    wd.disabled = false;                 /* nunca desabilita: precisa ser postado */\n    wd.style.opacity = inativa ? '1' : '0.4';\n    wd.title = inativa\n      ? 'Obrigatória para cota inativa'\n      : 'Ignorada enquanto o status não for \"inativa\"';\n  }\n\n  document.addEventListener('change', function (e) {\n    if (e.target.dataset && e.target.dataset.field === 'status') {\n      var tr = e.target.closest('tr');\n      if (tr) syncWithdrawal(tr);\n    }\n  });\n\n  /* Formata os valores iniciais em pt-BR (10000,00 → 10.000,00) */\n  document.querySelectorAll('#tabela-lote [data-mask=\"currency\"]').forEach(function (el) {\n    var raw = (el.value || '').replace(/\\./g, '').replace(',', '.');\n    var n = parseFloat(raw);\n    if (!isNaN(n)) el.value = n.toLocaleString('pt-BR', { minimumFractionDigits: 2 });\n  });\n\n  rows().forEach(syncWithdrawal);\n  updateCount();\n})();\n</script>\n{% endblock %}\n",
  "cotas_form.html": "{% extends \"base.html\" %}\n{% block title %}{{ 'Nova Cota' if modo == 'nova' else 'Editar Cota' }} — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n\n<a href=\"{{ url_for('cotas_lista') }}\" class=\"back-link\">← Voltar para Cotas</a>\n\n<div class=\"page-header\">\n  <div class=\"page-header-icon\">{{ '➕' if modo == 'nova' else '✏️' }}</div>\n  <div class=\"page-header-title\">{{ 'Nova Cota' if modo == 'nova' else 'Editar Cota' }}</div>\n  <div class=\"page-header-sub\">\n    {{ 'Cadastre uma ou mais cotas de investimento de uma só vez.' if modo == 'nova' else 'Atualize os dados da cota.' }}\n  </div>\n</div>\n\n{# ══ CSS do combobox de cliente ══════════════════════════════════════════════ #}\n<style>\n.client-combobox { position:relative; }\n.client-combobox .cb-input {\n  width:100%; padding:9px 12px; font-size:14px;\n  background:#1a1a1a; color:#F5F5F5;\n  border:1px solid #333; border-radius:6px;\n  outline:none; box-sizing:border-box;\n  transition:border-color .15s;\n}\n.client-combobox .cb-input:focus { border-color:#d4af37; }\n.client-combobox .cb-input::placeholder { color:#555; }\n.cb-dropdown {\n  display:none; position:absolute; z-index:999;\n  top:calc(100% + 4px); left:0; right:0;\n  background:#141414; border:1px solid #333;\n  border-radius:6px; max-height:272px; overflow-y:auto;\n  box-shadow:0 8px 24px rgba(0,0,0,.6);\n}\n.cb-dropdown.open { display:block; }\n.cb-option {\n  display:block; width:100%; text-align:left;\n  padding:9px 14px; background:none; border:none;\n  cursor:pointer; border-bottom:1px solid rgba(255,255,255,.05);\n  transition:background .1s;\n}\n.cb-option:last-child { border-bottom:none; }\n.cb-option:hover, .cb-option.focused {\n  background:rgba(212,175,55,.12);\n}\n.cb-option .cb-name { display:block; font-weight:600; color:#F5F5F5; font-size:14px; }\n.cb-option .cb-meta { display:block; font-size:11px; color:#666; margin-top:2px; }\n.cb-option .cb-inactive { display:inline-block; font-size:10px; color:#888;\n  border:1px solid #444; border-radius:3px; padding:0 4px; margin-left:6px;\n  vertical-align:middle; font-style:italic; }\n.cb-empty { padding:12px 14px; color:#555; font-size:13px; font-style:italic; }\n.cb-selected-display {\n  display:none; font-size:12px; color:#888; margin-top:5px;\n}\n.cb-selected-display.visible { display:block; }\n.pending-date-note {\n  display:none; margin-top:8px; padding:8px 12px;\n  background:rgba(212,175,55,.07); border-left:3px solid rgba(212,175,55,.4);\n  border-radius:0 4px 4px 0; font-size:12px; color:#aaa;\n}\n.pending-date-note.visible { display:block; }\n.hist-dup-box {\n  display:flex; align-items:flex-start; gap:10px;\n  padding:10px 14px; margin-top:0;\n  background:rgba(255,170,0,.05);\n  border:1px solid rgba(255,170,0,.18);\n  border-radius:6px;\n}\n.hist-dup-box input[type=checkbox] {\n  width:16px; height:16px; flex-shrink:0; margin-top:2px;\n  accent-color:#d4af37; cursor:pointer;\n}\n.hist-dup-box .hist-label { cursor:pointer; }\n.hist-dup-box .hist-label strong { color:#d4af37; font-size:13px; }\n.hist-dup-box .hist-label small { display:block; color:#666; font-size:11px; margin-top:2px; }\n</style>\n\n{% if modo == 'nova' %}\n{# ══════════════════════════════════════════════════════\n   MODO NOVA — formulário de múltiplas cotas\n   ══════════════════════════════════════════════════════ #}\n\n{# Dados dos clientes para o combobox (JSON embutido) #}\n<script id=\"clientes-json\" type=\"application/json\">\n{{ clientes | tojson }}\n</script>\n\n<div class=\"card-gold\">\n  <form method=\"post\" id=\"multi-share-form\" novalidate>\n\n    {# — Produto e Cotista ———————————————————— #}\n    <div class=\"form-section\">\n      <div class=\"form-section-title\">Produto e Cotista</div>\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label>Produto *</label>\n          <select name=\"condominium_id\" id=\"condominium_id\" class=\"form-control\" required>\n            <option value=\"\">Selecione o produto…</option>\n            {% for c in conds %}\n            <option value=\"{{ c.id }}\"\n              data-default-value=\"{{ cond_default_values.get(c.code, 0) }}\"\n              {{ 'selected' if cota.get('condominium_id')|string == c.id|string else '' }}>\n              {{ c.name }}\n            </option>\n            {% endfor %}\n          </select>\n        </div>\n\n        <div class=\"form-group\">\n          <label>Cliente *</label>\n          <div class=\"client-combobox\" id=\"cb-nova\">\n            <input type=\"text\" class=\"cb-input\" id=\"cb-nova-input\"\n                   autocomplete=\"off\" placeholder=\"🔍 Buscar por nome, CPF/CNPJ ou Pix…\">\n            <input type=\"hidden\" name=\"client_id\" id=\"cb-nova-value\"\n                   value=\"{{ cota.get('client_id', '') }}\">\n            <div class=\"cb-dropdown\" id=\"cb-nova-dropdown\"></div>\n            <div class=\"cb-selected-display\" id=\"cb-nova-selected\"></div>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    {# — Quantidade e Valor ——————————————————— #}\n    <div class=\"form-section\">\n      <div class=\"form-section-title\">Cotas</div>\n      <div class=\"form-row\">\n\n        <div class=\"form-group\" style=\"max-width:200px;\">\n          <label>Quantidade de cotas *</label>\n          <input type=\"number\" id=\"quantidade\" name=\"quantidade\"\n                 value=\"{{ (cota.get('share_numbers') or [''])|length }}\"\n                 min=\"1\" max=\"200\" class=\"form-control\" required>\n        </div>\n\n        <div class=\"form-group\">\n          <label>Valor unitário (R$) *</label>\n          <input type=\"text\" id=\"share_value\" name=\"share_value\"\n                 value=\"{{ '%.2f'|format(cota.get('share_value', 0)|float) }}\"\n                 class=\"form-control\" data-mask=\"currency\"\n                 placeholder=\"10.000,00\" readonly>\n          <label class=\"checkbox-label\" style=\"margin-top:10px;display:flex;align-items:center;gap:8px;cursor:pointer;\">\n            <input type=\"checkbox\" id=\"valor_diferente\"\n              style=\"width:16px;height:16px;accent-color:#d4af37;cursor:pointer;\">\n            <span style=\"color:#aaa;font-size:13px;\">Usar valor diferente do padrão</span>\n          </label>\n        </div>\n\n        <div class=\"form-group\">\n          <label>Status</label>\n          <select name=\"status\" id=\"status-nova\" class=\"form-control\">\n            <option value=\"ativa\"    {{ 'selected' if (cota.get('status','ativa') == 'ativa')    else '' }}>Ativa</option>\n            <option value=\"pendente\" {{ 'selected' if (cota.get('status') == 'pendente') else '' }}>Pendente</option>\n            <option value=\"inativa\"  {{ 'selected' if (cota.get('status') == 'inativa')  else '' }}>Inativa</option>\n          </select>\n        </div>\n\n      </div>\n    </div>\n\n    {# — Datas padrão ————————————————————————— #}\n    <div class=\"form-section\">\n      <div class=\"form-section-title\">Datas Padrão</div>\n      <div class=\"pending-date-note\" id=\"pending-note-nova\">\n        ⏳ Para cotas pendentes, as datas podem ser preenchidas depois da efetivação da compra.\n      </div>\n      <p style=\"color:#888;font-size:13px;margin:0 0 12px;\">\n        Preencha as datas padrão e clique em <strong style=\"color:#d4af37;\">Aplicar nas linhas</strong>\n        para copiar para todas as cotas. Você pode editar cada linha individualmente depois.\n      </p>\n      <div class=\"form-row\" style=\"align-items:flex-end;\">\n        <div class=\"form-group\">\n          <label id=\"lbl-acq-nova\">Aquisição padrão <span id=\"acq-req-nova\" style=\"color:#d4af37;\">*</span></label>\n          <input type=\"date\" id=\"default-acq\" class=\"form-control\"\n                 value=\"{{ cota.get('acquisition_date','') }}\">\n        </div>\n        <div class=\"form-group\">\n          <label>Última Renovação padrão</label>\n          <input type=\"date\" id=\"default-lrd\" class=\"form-control\"\n                 value=\"{{ cota.get('last_renewal_date','') }}\">\n        </div>\n        <div class=\"form-group\">\n          <label>Vencimento padrão</label>\n          <input type=\"date\" id=\"default-mat\" class=\"form-control\"\n                 value=\"{{ cota.get('maturity_date','') }}\">\n        </div>\n        <div class=\"form-group\" style=\"flex:0 0 auto;padding-top:4px;\">\n          <label style=\"visibility:hidden;\">&#8203;</label>\n          <button type=\"button\" id=\"btn-apply-dates\" class=\"btn btn-secondary btn-sm\"\n                  style=\"white-space:nowrap;\">\n            ↓ Aplicar nas linhas\n          </button>\n        </div>\n      </div>\n    </div>\n\n    {# — Grade de cotas ———————————————————————— #}\n    <div class=\"form-section\">\n      <div class=\"form-section-title\">Cotas — Número, Valor e Datas individuais</div>\n      <p style=\"color:#888;font-size:13px;margin:0 0 16px;\">\n        Cada linha representa uma cota. Edite número, valor e datas individualmente.\n      </p>\n\n      <div style=\"overflow-x:auto;\">\n        <!-- Cabeçalho fixo das colunas -->\n        <div style=\"display:flex;align-items:center;gap:8px;flex-wrap:nowrap;min-width:860px;\n                    padding:0 0 6px;border-bottom:1px solid #2a2a2a;margin-bottom:4px;\">\n          <span style=\"min-width:52px;flex-shrink:0;\"></span>\n          <span style=\"width:120px;flex-shrink:0;font-size:11px;color:#666;text-align:center;\">Número</span>\n          <span style=\"width:130px;flex-shrink:0;font-size:11px;color:#666;text-align:center;\">Valor R$</span>\n          <span style=\"width:148px;flex-shrink:0;font-size:11px;color:#d4af37;text-align:center;\">📅 Aquisição</span>\n          <span style=\"width:148px;flex-shrink:0;font-size:11px;color:#888;text-align:center;\">🔄 Última Renovação</span>\n          <span style=\"width:148px;flex-shrink:0;font-size:11px;color:#888;text-align:center;\">⏳ Vencimento</span>\n        </div>\n        <div id=\"share-numbers-list\" style=\"display:flex;flex-direction:column;gap:8px;min-width:860px;\">\n          <noscript>\n            {% for num in (cota.get('share_numbers') or ['']) %}\n            <div class=\"form-row\" style=\"align-items:center;gap:10px;\">\n              <span style=\"color:#aaa;min-width:58px;font-size:13px;\">Cota {{ loop.index }}</span>\n              <input type=\"text\" name=\"share_numbers\" value=\"{{ num }}\" class=\"form-control\"\n                     style=\"max-width:130px;\" placeholder=\"Número\">\n              <input type=\"text\" name=\"share_values\" value=\"\" class=\"form-control\"\n                     style=\"max-width:130px;\" placeholder=\"Valor\">\n              <input type=\"date\" name=\"acquisition_dates\" class=\"form-control\" style=\"max-width:145px;\">\n              <input type=\"date\" name=\"last_renewal_dates\" class=\"form-control\" style=\"max-width:145px;\">\n              <input type=\"date\" name=\"maturity_dates\" class=\"form-control\" style=\"max-width:145px;\">\n            </div>\n            {% endfor %}\n          </noscript>\n        </div>\n      </div>\n\n      <script id=\"multi-share-config\" type=\"application/json\">\n      {\n        \"initialNumbers\":      {{ (cota.get('share_numbers') or [''])|tojson }},\n        \"initialValue\":        {{ cota.get('share_value', 0)|float }},\n        \"condId\":              {{ cota.get('condominium_id', 0)|int }},\n        \"initialAcqDates\":     {{ (cota.get('acquisition_dates') or [])|tojson }},\n        \"initialMatDates\":     {{ (cota.get('maturity_dates') or [])|tojson }},\n        \"initialLrdDates\":     {{ (cota.get('last_renewal_dates') or [])|tojson }}\n      }\n      </script>\n\n      {# — Lançamento histórico ——————————————— #}\n      <div class=\"hist-dup-box\" style=\"margin-top:16px;\">\n        <input type=\"checkbox\" name=\"allow_duplicate_share_number\"\n               id=\"allow-dup-nova\" value=\"on\">\n        <label class=\"hist-label\" for=\"allow-dup-nova\">\n          <strong>Lançamento histórico: permitir número repetido</strong>\n          <small>Use apenas para importar histórico com inconsistência de numeração. Cadastros normais devem manter números únicos.</small>\n        </label>\n      </div>\n    </div>\n\n    {# — Contrato e assinatura (módulo contratos) ——————————— #}\n    <div class=\"form-section\" id=\"secao-gerar-contrato\">\n      <div class=\"form-section-title\">Contrato e Assinatura</div>\n      <div class=\"hist-dup-box\" style=\"background:rgba(212,175,55,.06);border-color:rgba(212,175,55,.25);\">\n        <input type=\"checkbox\" name=\"gerar_contrato\" id=\"gerar-contrato\" value=\"on\"\n               {{ 'checked' if cota.get('gerar_contrato', True) else '' }}>\n        <label class=\"hist-label\" for=\"gerar-contrato\">\n          <strong>Gerar Termo de Aquisição + Regulamento e preparar para assinatura</strong>\n          <small id=\"gerar-contrato-info\">O contrato é preenchido com os dados do cliente e já sai assinado pela empresa.\n            As cotas ficam <b>Pendentes</b> até o cliente assinar e o depósito ser confirmado.</small>\n        </label>\n      </div>\n    </div>\n    <script>\n    (function(){\n      var MODELOS = {{ {'civil': True} | tojson }};   /* produtos com modelo de contrato pronto */\n      var CODIGOS = { {% for c in conds %}\"{{ c.id }}\": \"{{ c.code }}\"{{ ',' if not loop.last }}{% endfor %} };\n      var chk = document.getElementById('gerar-contrato'), info = document.getElementById('gerar-contrato-info');\n      var cond = document.getElementById('condominium_id'), st = document.getElementById('status-nova');\n      if(!chk || !cond || !st) return;\n      var txt = info.innerHTML;\n      function sync(){\n        var temModelo = !!MODELOS[CODIGOS[cond.value]];\n        if(cond.value && !temModelo){\n          chk.checked = false; chk.disabled = true;\n          info.innerHTML = 'Modelo de contrato deste produto ainda não cadastrado (por enquanto: Construção Civil).';\n        } else { chk.disabled = false; info.innerHTML = txt; }\n        if(chk.checked && st.value !== 'pendente'){ st.value = 'pendente'; st.dispatchEvent(new Event('change')); }\n        st.style.pointerEvents = chk.checked ? 'none' : '';\n        st.style.opacity = chk.checked ? '.6' : '';\n      }\n      chk.addEventListener('change', sync); cond.addEventListener('change', sync);\n      document.addEventListener('DOMContentLoaded', sync); sync();\n    })();\n    </script>\n\n    {# — Observações ———————————————————————— #}\n    <div class=\"form-section\">\n      <div class=\"form-section-title\">Observações</div>\n      <div class=\"form-group\">\n        <textarea name=\"notes\" class=\"form-control\" rows=\"3\"\n                  placeholder=\"Anotações internas (opcional)\">{{ cota.get('notes','') }}</textarea>\n      </div>\n    </div>\n\n    <div class=\"page-actions\">\n      <a href=\"{{ url_for('cotas_lista') }}\" class=\"btn btn-secondary\">Cancelar</a>\n      <button type=\"submit\" class=\"btn btn-primary\" id=\"btn-cadastrar\">\n        ✓ Cadastrar Cotas\n      </button>\n    </div>\n\n  </form>\n</div>\n\n{% else %}\n{# ══════════════════════════════════════════════════════\n   MODO EDITAR — formulário simples\n   ══════════════════════════════════════════════════════ #}\n\n<script id=\"clientes-json\" type=\"application/json\">\n{{ clientes | tojson }}\n</script>\n\n<div class=\"card-gold\">\n  <form method=\"post\" id=\"edit-share-form\" novalidate>\n\n    <div class=\"form-section\">\n      <div class=\"form-section-title\">Produto e Cotista</div>\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label>Produto *</label>\n          <select name=\"condominium_id\" id=\"condominium_id\" class=\"form-control\" required>\n            <option value=\"\">Selecione o produto…</option>\n            {% for c in conds %}\n            <option value=\"{{ c.id }}\"\n              {{ 'selected' if cota.get('condominium_id')|string == c.id|string else '' }}>\n              {{ c.name }}\n            </option>\n            {% endfor %}\n          </select>\n        </div>\n\n        <div class=\"form-group\">\n          <label>Cliente *</label>\n          <div class=\"client-combobox\" id=\"cb-editar\">\n            <input type=\"text\" class=\"cb-input\" id=\"cb-editar-input\"\n                   autocomplete=\"off\" placeholder=\"🔍 Buscar por nome, CPF/CNPJ ou Pix…\">\n            <input type=\"hidden\" name=\"client_id\" id=\"cb-editar-value\"\n                   value=\"{{ cota.get('client_id', '') }}\">\n            <div class=\"cb-dropdown\" id=\"cb-editar-dropdown\"></div>\n            <div class=\"cb-selected-display\" id=\"cb-editar-selected\"></div>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"form-section\">\n      <div class=\"form-section-title\">Dados da Cota</div>\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label>Número da Cota *</label>\n          <input type=\"text\" name=\"share_number\" id=\"share_number\"\n                 value=\"{{ cota.get('share_number','') }}\"\n                 class=\"form-control\" required placeholder=\"Ex: 1, 1.12, A1\">\n        </div>\n        <div class=\"form-group\">\n          <label>Valor (R$) *</label>\n          <input type=\"text\" name=\"share_value\"\n                 value=\"{{ '%.2f'|format(cota.get('share_value', 0)|float) }}\"\n                 class=\"form-control\" data-mask=\"currency\"\n                 placeholder=\"0,00\">\n        </div>\n        <div class=\"form-group\">\n          <label>Status</label>\n          <select name=\"status\" id=\"status-editar\" class=\"form-control\">\n            <option value=\"ativa\"    {{ 'selected' if cota.get('status','ativa') == 'ativa'    else '' }}>Ativa</option>\n            <option value=\"pendente\" {{ 'selected' if cota.get('status') == 'pendente' else '' }}>Pendente</option>\n            <option value=\"inativa\"  {{ 'selected' if cota.get('status') == 'inativa'  else '' }}>Inativa</option>\n          </select>\n        </div>\n      </div>\n\n      {# — Lançamento histórico ——————————————— #}\n      <div class=\"hist-dup-box\" style=\"margin-bottom:16px;\">\n        <input type=\"checkbox\" name=\"allow_duplicate_share_number\"\n               id=\"allow-dup-editar\" value=\"on\">\n        <label class=\"hist-label\" for=\"allow-dup-editar\">\n          <strong>Lançamento histórico: permitir número repetido</strong>\n          <small>Use apenas para importar histórico com inconsistência de numeração. Cadastros normais devem manter números únicos.</small>\n        </label>\n      </div>\n\n      <div class=\"pending-date-note\" id=\"pending-note-editar\">\n        ⏳ Para cotas pendentes, as datas podem ser preenchidas depois da efetivação da compra.\n      </div>\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label>Data de Aquisição <span id=\"acq-req-editar\" style=\"color:#d4af37;\">*</span></label>\n          <input type=\"date\" name=\"acquisition_date\" id=\"acq-editar\"\n                 value=\"{{ cota.get('acquisition_date','') }}\"\n                 class=\"form-control\" required>\n        </div>\n        <div class=\"form-group\">\n          <label>Data de Vencimento</label>\n          <input type=\"date\" name=\"maturity_date\"\n                 value=\"{{ cota.get('maturity_date','') }}\"\n                 class=\"form-control\">\n        </div>\n      </div>\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label>Última Renovação</label>\n          <input type=\"date\" name=\"last_renewal_date\"\n                 value=\"{{ cota.get('last_renewal_date','') }}\"\n                 class=\"form-control\">\n        </div>\n        <div class=\"form-group\">\n          <label>Data de Retirada</label>\n          <input type=\"date\" name=\"withdrawal_date\"\n                 value=\"{{ cota.get('withdrawal_date','') }}\"\n                 class=\"form-control\">\n        </div>\n      </div>\n\n      {# — Exceção: proporcional até a retirada ——————————— #}\n      <div style=\"margin-top:6px;padding:12px 14px;border:1px solid #6b4f12;\n                  border-radius:6px;background:rgba(251,191,36,0.07);\">\n        <label style=\"display:flex;align-items:flex-start;gap:10px;cursor:pointer;margin:0;\">\n          <input type=\"checkbox\" name=\"accrual_until_withdrawal\"\n                 id=\"accrual-ate-retirada\" value=\"on\"\n                 {{ 'checked' if (cota.get('accrual_until_withdrawal') or 0)|int == 1 else '' }}>\n          <span style=\"font-size:13px;line-height:1.5;\">\n            <strong style=\"color:#fbbf24;\">Retirada fora do período — considerar proporcional até a retirada</strong><br>\n            <small style=\"color:#999;\">\n              Ligado: mesmo inativa, esta cota entra na apuração e rende até o\n              <em>dia anterior</em> à Data de Retirada acima (o dia da retirada não rende).\n              Exige Data de Retirada preenchida.<br>\n              <strong style=\"color:#888;\">Desligado = regra padrão do condomínio:</strong>\n              cota inativada não rende nada no período.\n            </small>\n          </span>\n        </label>\n      </div>\n    </div>\n\n    <div class=\"form-section\">\n      <div class=\"form-section-title\">Observações</div>\n      <div class=\"form-group\">\n        <textarea name=\"notes\" class=\"form-control\" rows=\"3\"\n                  placeholder=\"Anotações internas (opcional)\">{{ cota.get('notes','') }}</textarea>\n      </div>\n    </div>\n\n    <div class=\"page-actions\">\n      <a href=\"{{ url_for('cotas_lista') }}\" class=\"btn btn-secondary\">Cancelar</a>\n      <button type=\"submit\" class=\"btn btn-primary\">✓ Salvar Alterações</button>\n    </div>\n\n  </form>\n</div>\n\n{% endif %}\n\n{% endblock %}\n\n{% block scripts %}\n<script>\n(function() {\n  'use strict';\n\n  /* ── 1. Dados dos clientes ─────────────────────────────────────────── */\n  var clientesEl = document.getElementById('clientes-json');\n  var CLIENTES = clientesEl ? JSON.parse(clientesEl.textContent) : [];\n\n  /* ── 2. Combobox factory ───────────────────────────────────────────── */\n  function initCombobox(inputId, hiddenId, dropdownId, selectedId, preselectedId) {\n    var inp   = document.getElementById(inputId);\n    var hid   = document.getElementById(hiddenId);\n    var drop  = document.getElementById(dropdownId);\n    var selEl = document.getElementById(selectedId);\n    if (!inp || !hid || !drop) return;\n\n    var focusIdx = -1;\n\n    /* Pré-preencher se vier de edição */\n    if (preselectedId && hid.value) {\n      var pre = CLIENTES.find(function(c){ return String(c.id) === String(hid.value); });\n      if (pre) {\n        inp.value = pre.display_name || pre.full_name;\n        if (selEl) {\n          selEl.textContent = pre.full_name + (pre.status === 'inativo' ? ' (inativo)' : '');\n          selEl.className = 'cb-selected-display visible';\n        }\n      }\n    }\n\n    function buildItems(q) {\n      q = (q || '').toLowerCase().trim();\n      var results = CLIENTES.filter(function(c) {\n        if (!q) return true;\n        return (c.full_name || '').toLowerCase().includes(q)\n            || (c.cpf || '').toLowerCase().includes(q)\n            || (c.pix_key || '').toLowerCase().includes(q);\n      });\n      return results.slice(0, 40);  /* máx 40 resultados */\n    }\n\n    function renderDrop(q) {\n      var items = buildItems(q);\n      focusIdx = -1;\n      if (!items.length) {\n        drop.innerHTML = '<div class=\"cb-empty\">Nenhum cliente encontrado</div>';\n      } else {\n        drop.innerHTML = items.map(function(c, i) {\n          var meta = c.cpf;\n          if (c.pix_key) meta += ' · Pix: ' + c.pix_key;\n          var badge = c.status === 'inativo'\n            ? '<span class=\"cb-inactive\">inativo</span>' : '';\n          return '<button type=\"button\" class=\"cb-option\"'\n            + ' data-id=\"' + c.id + '\"'\n            + ' data-name=\"' + (c.display_name || c.full_name).replace(/\"/g, '&quot;') + '\">'\n            + '<span class=\"cb-name\">' + escHtml(c.full_name) + badge + '</span>'\n            + '<span class=\"cb-meta\">' + escHtml(meta) + '</span>'\n            + '</button>';\n        }).join('');\n        /* eventos de clique */\n        drop.querySelectorAll('.cb-option').forEach(function(btn) {\n          btn.addEventListener('mousedown', function(e) {\n            e.preventDefault();\n            selectClient(btn.dataset.id, btn.dataset.name);\n          });\n        });\n      }\n      drop.classList.add('open');\n    }\n\n    function selectClient(id, name) {\n      hid.value  = id;\n      inp.value  = name;\n      if (selEl) {\n        selEl.textContent = name;\n        selEl.className = 'cb-selected-display visible';\n      }\n      drop.classList.remove('open');\n      drop.innerHTML = '';\n    }\n\n    function closeDropdown() {\n      drop.classList.remove('open');\n    }\n\n    inp.addEventListener('input', function() {\n      var q = inp.value.trim();\n      if (!q) {\n        hid.value = '';\n        if (selEl) selEl.className = 'cb-selected-display';\n      }\n      if (q.length >= 1 || CLIENTES.length < 30) {\n        renderDrop(q);\n      } else {\n        closeDropdown();\n      }\n    });\n\n    inp.addEventListener('focus', function() {\n      if (!inp.value || CLIENTES.length < 30) renderDrop(inp.value);\n    });\n\n    inp.addEventListener('keydown', function(e) {\n      var btns = drop.querySelectorAll('.cb-option');\n      if (!btns.length) return;\n      if (e.key === 'ArrowDown') {\n        e.preventDefault();\n        focusIdx = Math.min(focusIdx + 1, btns.length - 1);\n        btns.forEach(function(b, i){ b.classList.toggle('focused', i === focusIdx); });\n        if (btns[focusIdx]) btns[focusIdx].scrollIntoView({block:'nearest'});\n      } else if (e.key === 'ArrowUp') {\n        e.preventDefault();\n        focusIdx = Math.max(focusIdx - 1, 0);\n        btns.forEach(function(b, i){ b.classList.toggle('focused', i === focusIdx); });\n      } else if (e.key === 'Enter') {\n        e.preventDefault();\n        if (focusIdx >= 0 && btns[focusIdx]) {\n          var btn = btns[focusIdx];\n          selectClient(btn.dataset.id, btn.dataset.name);\n        }\n      } else if (e.key === 'Escape') {\n        closeDropdown();\n      }\n    });\n\n    document.addEventListener('click', function(e) {\n      if (!inp.closest('.client-combobox').contains(e.target)) closeDropdown();\n    });\n  }\n\n  /* ── 3. Inicializar comboboxes ─────────────────────────────────────── */\n  initCombobox('cb-nova-input',   'cb-nova-value',   'cb-nova-dropdown',   'cb-nova-selected',   true);\n  initCombobox('cb-editar-input', 'cb-editar-value', 'cb-editar-dropdown', 'cb-editar-selected', true);\n\n  /* ── 4. Validação de client_id no submit ───────────────────────────── */\n  ['multi-share-form', 'edit-share-form'].forEach(function(fid) {\n    var form = document.getElementById(fid);\n    if (!form) return;\n    form.addEventListener('submit', function(e) {\n      var hid = form.querySelector('input[name=\"client_id\"]');\n      if (hid && !hid.value) {\n        e.preventDefault();\n        var inp = form.querySelector('.cb-input');\n        if (inp) {\n          inp.style.borderColor = '#ef4444';\n          inp.placeholder = '⚠ Selecione um cliente antes de salvar';\n          inp.focus();\n          setTimeout(function(){ inp.style.borderColor = ''; }, 3000);\n        }\n      }\n    });\n  });\n\n  /* ── 5. Toggle obrigatoriedade de datas por status ─────────────────── */\n  function setupStatusDateToggle(selectId, acqId, reqId, noteId) {\n    var sel  = document.getElementById(selectId);\n    var acq  = document.getElementById(acqId);\n    var req  = document.getElementById(reqId);\n    var note = document.getElementById(noteId);\n    if (!sel || !acq) return;\n\n    function update() {\n      var pendente = sel.value === 'pendente';\n      acq.required = !pendente;\n      if (req)  req.style.display = pendente ? 'none' : '';\n      if (note) note.classList.toggle('visible', pendente);\n    }\n    sel.addEventListener('change', update);\n    update(); /* estado inicial */\n  }\n\n  setupStatusDateToggle('status-nova',   'acq-nova',   'acq-req-nova',   'pending-note-nova');\n  setupStatusDateToggle('status-editar', 'acq-editar', 'acq-req-editar', 'pending-note-editar');\n\n  /* ── helpers ────────────────────────────────────────────────────────── */\n  function escHtml(s) {\n    return String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');\n  }\n\n})();\n</script>\n{% endblock %}\n",
  "cotas_lista.html": "{% extends \"base.html\" %}\n{% block title %}Cotas — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n\n<div class=\"page-header\">\n  <div class=\"page-header-icon\">📄</div>\n  <div class=\"page-header-title\">Todas as Cotas</div>\n  <div class=\"page-header-sub\">Gestão de cotas de investimento — todos os produtos</div>\n</div>\n\n<!-- KPIs -->\n<div class=\"metrics-grid\" style=\"grid-template-columns: repeat(5,1fr);\">\n  <div class=\"metric-card\">\n    <div class=\"metric-value\">{{ resumo.total }}</div>\n    <div class=\"metric-label\">Total de Cotas</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#4ade80;\">{{ resumo.ativas }}</div>\n    <div class=\"metric-label\">Ativas</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#fbbf24;\">{{ resumo.pendentes }}</div>\n    <div class=\"metric-label\">Pendentes</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#555;\">{{ resumo.inativas }}</div>\n    <div class=\"metric-label\">Inativas</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value text-gold\">{{ formatar_moeda(resumo.valor_total) }}</div>\n    <div class=\"metric-label\">Patrimônio Ativo</div>\n  </div>\n</div>\n\n<!-- KPIs por produto -->\n<div class=\"metrics-grid\" style=\"grid-template-columns: repeat(3,1fr);margin-top:-8px;\">\n  {% for pp in resumo.por_produto %}\n  <div class=\"metric-card\">\n    <div class=\"metric-value\">{{ pp.qty }}</div>\n    <div class=\"metric-label\">{{ pp.name }} · {{ formatar_moeda(pp.total_value) }}</div>\n  </div>\n  {% endfor %}\n</div>\n\n<!-- Toolbar -->\n<form method=\"get\" class=\"toolbar\">\n  <div class=\"toolbar-left\">\n    <div class=\"search-wrap\">\n      <input type=\"text\" name=\"q\" value=\"{{ q }}\"\n             placeholder=\"Buscar por nº cota, cliente, CPF…\"\n             class=\"form-control\" style=\"width:260px;\">\n    </div>\n    <select name=\"produto\" class=\"form-control form-control-sm\" style=\"width:160px;\">\n      <option value=\"\">Todos os produtos</option>\n      {% for c in conds %}\n      <option value=\"{{ c.code }}\" {{ 'selected' if produto_filtro == c.code else '' }}>{{ c.name }}</option>\n      {% endfor %}\n    </select>\n    <select name=\"status\" class=\"form-control form-control-sm\" style=\"width:140px;\">\n      <option value=\"\">Todos os status</option>\n      <option value=\"ativa\"    {{ 'selected' if status_filtro == 'ativa' else '' }}>Ativas</option>\n      <option value=\"pendente\" {{ 'selected' if status_filtro == 'pendente' else '' }}>Pendentes</option>\n      <option value=\"inativa\"  {{ 'selected' if status_filtro == 'inativa' else '' }}>Inativas</option>\n    </select>\n    <button type=\"submit\" class=\"btn btn-secondary btn-sm\">Filtrar</button>\n    {% if q or status_filtro or produto_filtro %}\n      <a href=\"{{ url_for('cotas_lista') }}\" class=\"btn btn-secondary btn-sm\">Limpar</a>\n    {% endif %}\n  </div>\n  <div class=\"toolbar-right\">\n    <a href=\"{{ url_for('cotas_nova') }}\" class=\"btn btn-primary\">+ Nova Cota</a>\n  </div>\n</form>\n\n<!-- Tabela -->\n{% if cotas %}\n<div class=\"table-wrap\">\n  <table>\n    <thead>\n      <tr>\n        <th>Nº</th>\n        <th>Produto</th>\n        <th>Cliente</th>\n        <th>Valor</th>\n        <th>Aquisição</th>\n        <th>Vencimento</th>\n        <th>Status</th>\n        <th style=\"text-align:right;\">Ações</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for cota in cotas %}\n      <tr>\n        <td style=\"font-size:18px;font-weight:700;color:#d4af37;\">{{ cota.share_number }}</td>\n        <td>\n          {% if cota.condominium_code == 'civil' %}\n            <span class=\"badge badge-civil\">🏗️ Civil</span>\n          {% elif cota.condominium_code == 'agro' %}\n            <span class=\"badge badge-agro\">🌾 Agro</span>\n          {% else %}\n            <span class=\"badge badge-saude\">🏥 Saúde</span>\n          {% endif %}\n        </td>\n        <td>\n          <a href=\"{{ url_for('clientes_detalhe', cid=cota.client_id) }}\"\n             style=\"color:#F5F5F5;\">{{ cota.client_name }}</a>\n          <div class=\"text-mono text-dim\" style=\"font-size:11px;\">{{ cota.client_cpf }}</div>\n        </td>\n        <td style=\"font-weight:600;\">{{ formatar_moeda(cota.share_value) }}</td>\n        <td class=\"text-dim\">{{ cota.acquisition_date or '—' }}</td>\n        <td class=\"text-dim\">{{ cota.maturity_date or '—' }}</td>\n        <td>\n          {% if cota.status == 'ativa' %}\n            <span class=\"badge badge-active\">● Ativa</span>\n            {% if cota.withdrawal_requested %}\n              <span class=\"badge badge-retirada\" title=\"Retirada efetiva em {{ cota.withdrawal_effective_date or '—' }}\">📤 Em retirada</span>\n            {% endif %}\n          {% elif cota.status == 'pendente' %}\n            <span class=\"badge badge-pending\">● Pendente</span>\n          {% else %}\n            <span class=\"badge badge-inactive\">● Inativa</span>\n          {% endif %}\n        </td>\n        <td style=\"text-align:right;white-space:nowrap;\">\n          <a href=\"{{ url_for('cotas_editar', sid=cota.id) }}\" class=\"btn btn-secondary btn-sm\">Editar</a>\n          {% if cota.status == 'ativa' or cota.status == 'pendente' %}\n            <button type=\"button\" class=\"btn btn-danger btn-sm\"\n                    onclick=\"openInativarModal(this)\"\n                    data-share-id=\"{{ cota.id }}\"\n                    data-share-num=\"{{ cota.share_number | e }}\"\n                    data-client-name=\"{{ cota.client_name | e }}\"\n                    data-share-value=\"{{ cota.share_value }}\"\n                    data-acquisition-date=\"{{ cota.acquisition_date or '' }}\">\n              Inativar\n            </button>\n          {% else %}\n            <form method=\"post\" action=\"{{ url_for('cotas_reativar', sid=cota.id) }}\" style=\"display:inline;\">\n              <input type=\"hidden\" name=\"referrer\" value=\"{{ request.url }}\">\n              <button type=\"submit\" class=\"btn btn-success btn-sm\">Reativar</button>\n            </form>\n          {% endif %}\n          <button type=\"button\" class=\"btn btn-delete btn-sm\"\n                  onclick=\"openDeleteModal({{ cota.id }}, '{{ cota.share_number }}')\">\n            Excluir\n          </button>\n        </td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n<div class=\"text-dim\" style=\"font-size:12px;margin-top:10px;text-align:right;\">\n  {{ cotas | length }} cota(s) encontrada(s)\n</div>\n{% else %}\n<div class=\"empty-state\">\n  <div class=\"empty-state-icon\">📄</div>\n  <div class=\"empty-state-title\">Nenhuma cota encontrada</div>\n  <div class=\"empty-state-sub\">\n    {% if q or status_filtro or produto_filtro %}\n      Tente ajustar os filtros de busca.\n    {% else %}\n      Cadastre a primeira cota para começar.\n    {% endif %}\n  </div>\n</div>\n{% endif %}\n\n<!-- Modal: Inativar Cota -->\n<div class=\"modal-overlay\" id=\"modal-inativar-cota\" style=\"display:none;\">\n  <div class=\"modal\">\n    <div class=\"modal-title\" style=\"color:#fbbf24;\">⏸️ Inativar Cota</div>\n    <div style=\"margin-bottom:16px;\">\n      <table style=\"width:100%;border-collapse:collapse;font-size:13px;line-height:1.8;\">\n        <tr>\n          <td style=\"color:#888;width:110px;\">Cota nº</td>\n          <td style=\"color:#d4af37;font-weight:700;font-size:16px;\" id=\"modal-inativar-share-num\"></td>\n        </tr>\n        <tr>\n          <td style=\"color:#888;\">Cliente</td>\n          <td style=\"color:#ccc;\" id=\"modal-inativar-client\"></td>\n        </tr>\n        <tr>\n          <td style=\"color:#888;\">Valor</td>\n          <td style=\"color:#ccc;\" id=\"modal-inativar-value\"></td>\n        </tr>\n        <tr>\n          <td style=\"color:#888;\">Aquisição</td>\n          <td style=\"color:#ccc;\" id=\"modal-inativar-acq\"></td>\n        </tr>\n      </table>\n    </div>\n    <form id=\"modal-inativar-form\" method=\"post\" action=\"\">\n      <input type=\"hidden\" name=\"referrer\" id=\"modal-inativar-referrer\" value=\"\">\n      <div class=\"form-group\" style=\"margin-bottom:14px;\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">\n          Data de retirada <span style=\"color:#f87171;\">*</span>\n        </label>\n        <input type=\"date\" name=\"withdrawal_date\" id=\"modal-inativar-withdrawal-date\"\n               class=\"form-control\" required>\n      </div>\n      <div class=\"form-group\" style=\"margin-bottom:20px;\">\n        <label style=\"color:#ccc;font-size:13px;font-weight:500;\">\n          Observação <span style=\"color:#666;\">(opcional)</span>\n        </label>\n        <input type=\"text\" name=\"user_note\" id=\"modal-inativar-user-note\"\n               class=\"form-control\" placeholder=\"Motivo da inativação…\" maxlength=\"200\">\n      </div>\n      <div style=\"margin-bottom:20px;padding:12px 14px;border:1px solid #6b4f12;\n                  border-radius:6px;background:rgba(251,191,36,0.07);\">\n        <label style=\"display:flex;align-items:flex-start;gap:10px;cursor:pointer;margin:0;\">\n          <input type=\"checkbox\" name=\"accrual_until_withdrawal\"\n                 id=\"modal-inativar-prop\" value=\"on\"\n                 style=\"margin-top:3px;flex:0 0 auto;\">\n          <span style=\"color:#ccc;font-size:13px;line-height:1.5;\">\n            <strong style=\"color:#fbbf24;\">Retirada fora do período — considerar proporcional até a retirada</strong><br>\n            <small style=\"color:#999;\">\n              Marque <u>somente</u> quando a retirada ocorreu dentro da janela de apuração.\n              A cota continua entrando na apuração e rende proporcionalmente de\n              <em>até o dia anterior</em> à data de retirada (o dia da retirada não rende).<br>\n              <strong style=\"color:#888;\">Desmarcado = regra padrão do condomínio:</strong>\n              cota inativada não rende nada no período.\n            </small>\n          </span>\n        </label>\n      </div>\n      <div class=\"page-actions\" style=\"margin-top:0;padding-top:0;\">\n        <button type=\"button\" onclick=\"closeModal('modal-inativar-cota')\"\n                class=\"btn btn-secondary\">Cancelar</button>\n        <button type=\"submit\" class=\"btn btn-danger\">⏸️ Confirmar inativação</button>\n      </div>\n    </form>\n  </div>\n</div>\n\n<!-- Modal: Confirmar Exclusão de Cota -->\n<div class=\"modal-overlay\" id=\"modal-excluir-cota\" style=\"display:none;\">\n  <div class=\"modal\">\n    <div class=\"modal-title\" style=\"color:#f87171;\">🗑️ Excluir Cota</div>\n    <p style=\"color:#ccc;margin-bottom:14px;\">\n      Você está prestes a excluir a cota\n      <strong id=\"modal-delete-share-num\" style=\"color:#d4af37;font-size:18px;\"></strong>.\n    </p>\n    <div class=\"note-box\" style=\"border-color:rgba(239,68,68,0.35);background:rgba(239,68,68,0.06);margin-bottom:20px;\">\n      <strong style=\"color:#f87171;\">⚠️ Atenção:</strong>\n      Tem certeza que deseja excluir esta cota?\n      Esta ação deve ser usada apenas para corrigir cadastros feitos por engano.\n      A cota será removida permanentemente e a exclusão ficará registrada no log de auditoria.\n    </div>\n    <form id=\"form-excluir-cota\" method=\"post\" action=\"\">\n      <input type=\"hidden\" name=\"referrer\" id=\"modal-delete-referrer\" value=\"\">\n      <div class=\"page-actions\" style=\"margin-top:0;padding-top:0;\">\n        <button type=\"button\" onclick=\"closeModal('modal-excluir-cota')\"\n                class=\"btn btn-secondary\">Cancelar</button>\n        <button type=\"submit\" class=\"btn btn-delete\">🗑️ Confirmar exclusão</button>\n      </div>\n    </form>\n  </div>\n</div>\n\n{% endblock %}\n",
  "dashboard.html": "{% extends \"base.html\" %}\n{% block title %}Dashboard — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n\n<!-- Hero -->\n<div class=\"hero\">\n  <div class=\"hero-title\">🏛️ &nbsp;Painel de Gestão — Condomínios de Investimento</div>\n  <div class=\"hero-sub\">Visão executiva de cotas, clientes e produtos · Grupo Capuzzo</div>\n</div>\n\n<!-- KPIs Linha 1 -->\n<div class=\"metrics-grid\">\n  <div class=\"metric-card\">\n    <div class=\"metric-icon\">💰</div>\n    <div class=\"metric-value\">{{ formatar_moeda(s_res.valor_total) }}</div>\n    <div class=\"metric-label\">Patrimônio em Cotas</div>\n    <div class=\"metric-sub\">total investido ativo</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-icon\">👤</div>\n    <div class=\"metric-value\">{{ resumo.total_clients }}</div>\n    <div class=\"metric-label\">Clientes Ativos</div>\n    <div class=\"metric-sub\">cotistas cadastrados</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-icon\">📄</div>\n    <div class=\"metric-value\">{{ s_res.ativas }}</div>\n    <div class=\"metric-label\">Cotas Ativas</div>\n    <div class=\"metric-sub\">{{ s_res.pendentes }} pendentes</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-icon\">🏛️</div>\n    <div class=\"metric-value\">{{ conds | selectattr('active') | list | length }}</div>\n    <div class=\"metric-label\">Produtos Ativos</div>\n    <div class=\"metric-sub\">condomínios em operação</div>\n  </div>\n</div>\n\n<!-- KPIs Linha 2 -->\n<div class=\"metrics-grid\" style=\"margin-top:-8px;\">\n  <div class=\"metric-card\">\n    <div class=\"metric-icon\">📊</div>\n    <div class=\"metric-value\">{{ s_res.total }}</div>\n    <div class=\"metric-label\">Total de Cotas</div>\n    <div class=\"metric-sub\">todas as situações</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-icon\">⏳</div>\n    <div class=\"metric-value\">{{ s_res.pendentes }}</div>\n    <div class=\"metric-label\">Pendentes</div>\n    <div class=\"metric-sub\">aguardando ativação</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-icon\">🔒</div>\n    <div class=\"metric-value\">{{ s_res.inativas }}</div>\n    <div class=\"metric-label\">Inativas</div>\n    <div class=\"metric-sub\">encerradas</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-icon\">📐</div>\n    <div class=\"metric-value\">{{ ultima_apuracao }}</div>\n    <div class=\"metric-label\">Última Apuração</div>\n    <div class=\"metric-sub\">mês calculado</div>\n  </div>\n</div>\n\n<hr class=\"divider-gold\">\n\n<!-- Produtos -->\n<div class=\"section-label\">🏛️ &nbsp;Produtos de Investimento</div>\n\n<div class=\"cards-grid\">\n  {% for cond in conds %}\n  {% set prod = por_prod.get(cond.code, {}) %}\n  {% set page_map = {'civil': 'produto_civil', 'agro': 'produto_agro', 'saude': 'produto_saude'} %}\n  <div class=\"product-card\">\n    <div class=\"product-card-header\">\n      <div>\n        <div class=\"product-card-name\">{{ cond.name }}</div>\n        <div class=\"product-card-code\">{{ cond.code.upper() }}</div>\n      </div>\n      {% if cond.active %}\n        <span class=\"product-badge-active\">● Ativo</span>\n      {% else %}\n        <span class=\"badge badge-inactive\">● Inativo</span>\n      {% endif %}\n    </div>\n\n    <div class=\"product-stat\">\n      <span class=\"product-stat-label\">Taxa mensal</span>\n      <span class=\"product-stat-value\">{{ formatar_percentual(cond.default_monthly_rate) }}</span>\n    </div>\n    <div class=\"product-stat\">\n      <span class=\"product-stat-label\">Dia de pagamento</span>\n      <span class=\"product-stat-value\">Dia {{ cond.payment_day }}</span>\n    </div>\n    <div class=\"product-stat\">\n      <span class=\"product-stat-label\">Cotas ativas</span>\n      <span class=\"product-stat-value\">{{ prod.get('qty', 0) }}</span>\n    </div>\n\n    {% if cond.code == 'agro' %}\n    <div class=\"note-box\" style=\"margin-top:10px;\">\n      <span style=\"color:#fbbf24;font-weight:600;\">Taxa especial vencimento: </span>\n      <span>3,5% a 4,5%</span>\n    </div>\n    {% endif %}\n\n    <div class=\"product-value\">\n      <div class=\"product-value-label\">Patrimônio ativo</div>\n      <div class=\"product-value-amount\">{{ formatar_moeda(prod.get('total_value', 0)) }}</div>\n    </div>\n\n    <a href=\"{{ url_for('condominio', code=cond.code) }}\" class=\"btn btn-primary btn-full\">\n      Abrir {{ cond.name }} →\n    </a>\n  </div>\n  {% endfor %}\n</div>\n\n<hr class=\"divider-gold\">\n\n<!-- Acesso Rápido -->\n<div class=\"section-label\">⚡ &nbsp;Acesso Rápido</div>\n<div class=\"quick-grid\">\n  <a href=\"{{ url_for('clientes_lista') }}\" class=\"quick-card\">👤 &nbsp;Gestão de Clientes</a>\n  <a href=\"{{ url_for('cotas_lista') }}\" class=\"quick-card\">📄 &nbsp;Todas as Cotas</a>\n  <a href=\"{{ url_for('apuracao') }}\" class=\"quick-card\">📐 &nbsp;Apuração Geral</a>\n  <a href=\"{{ url_for('backup_page') }}\" class=\"quick-card\">💾 &nbsp;Backup</a>\n</div>\n\n{% endblock %}\n",
  "exportacao_supabase.html": "{% extends \"base.html\" %}\n{% block title %}Exportação Supabase / Lovable — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n\n<div class=\"page-header\">\n  <div class=\"page-header-icon\">🛰️</div>\n  <div class=\"page-header-title\">Exportação Supabase / Lovable</div>\n  <div class=\"page-header-sub\">\n    Área temporária para sincronizar o Supabase mantendo o histórico até junho.\n  </div>\n</div>\n\n<div class=\"note-box\" style=\"border-left:4px solid #f59e0b;\">\n  <div style=\"font-weight:700;color:#f59e0b;margin-bottom:6px;\">⚠️ Leia antes de gerar</div>\n  <div style=\"font-size:13px;line-height:1.7;\">\n    Esta exportação <strong>não reconstrói o histórico anterior ao corte</strong>.\n    Ela apenas gera dados incrementais a partir da base atual do app.<br>\n    Tabelas <strong>mensais</strong> (Agro e Fluxo) recebem\n    <code>DELETE ... WHERE &lt;coluna de corte&gt; &gt;= data</code> + <code>INSERT</code> —\n    tudo que está no Supabase antes do corte permanece intacto.<br>\n    Tabelas <strong>cadastrais</strong> (Civil e Saúde) não têm coluna de mês: recebem\n    <code>UPSERT</code> pela chave lógica e <strong>nenhum DELETE</strong>.<br>\n    Nada é executado automaticamente: o app <em>não</em> se conecta ao Supabase.\n  </div>\n</div>\n\n<form method=\"POST\" action=\"{{ url_for('exportacao_supabase_gerar') }}\"\n      onsubmit=\"return confirmarGeracao();\">\n\n  <!-- 1 · Data de corte -->\n  <div class=\"card\" style=\"margin-top:18px;\">\n    <div class=\"form-section-title\">1 · Data de corte</div>\n    <div class=\"form-row\">\n      <div class=\"form-group\" style=\"max-width:260px;\">\n        <label for=\"cutoff\">Exportar competências a partir de</label>\n        <input type=\"date\" id=\"cutoff\" name=\"cutoff\" class=\"form-control\"\n               value=\"{{ cutoff_selecionado }}\" required>\n      </div>\n      <div class=\"form-group flex-1\">\n        <label>&nbsp;</label>\n        <div class=\"text-dim\" style=\"font-size:12px;line-height:1.6;padding-top:10px;\">\n          Padrão <strong>{{ cutoff_padrao }}</strong>. Vale só para as tabelas mensais —\n          as cadastrais exportam a posição atual.\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- 2 · Bases e estratégia -->\n  <div class=\"card\" style=\"margin-top:18px;\">\n    <div class=\"form-section-title\">2 · Bases, tabelas e estratégia</div>\n    <div class=\"text-dim\" style=\"font-size:12px;margin-bottom:14px;\">\n      Os nomes e a estratégia já vêm com o mapeamento real do Supabase.\n      Ajuste apenas se a estrutura mudar. Nomes aceitam letras, números e underscore.\n    </div>\n\n    {% for b in bases %}\n    {% set cfg = config_bases.get(b.chave) %}\n    <div class=\"form-section\" style=\"border:1px solid rgba(212,175,55,.18);border-radius:8px;\n                padding:14px;margin-bottom:12px;\">\n      <label style=\"display:flex;align-items:center;gap:10px;cursor:pointer;margin-bottom:10px;\">\n        <input type=\"checkbox\" name=\"bases\" value=\"{{ b.chave }}\"\n               {% if b.chave in bases_selecionadas %}checked{% endif %}>\n        <span style=\"font-weight:700;\">{{ b.label }}</span>\n        <span class=\"text-dim\" style=\"font-size:11px;\">{{ b.descricao }}</span>\n      </label>\n\n      <div class=\"form-row\" style=\"flex-wrap:wrap;gap:12px;\">\n        <div class=\"form-group\" style=\"min-width:230px;flex:1;\">\n          <label for=\"tabela_{{ b.chave }}\">Tabela no Supabase</label>\n          <input type=\"text\" id=\"tabela_{{ b.chave }}\" name=\"tabela_{{ b.chave }}\"\n                 class=\"form-control text-mono\" value=\"{{ cfg.tabela }}\"\n                 pattern=\"[A-Za-z_][A-Za-z0-9_]*\"\n                 title=\"Apenas letras, números e underscore\">\n        </div>\n\n        <div class=\"form-group\" style=\"min-width:250px;flex:1;\">\n          <label for=\"estrategia_{{ b.chave }}\">Estratégia</label>\n          <select id=\"estrategia_{{ b.chave }}\" name=\"estrategia_{{ b.chave }}\"\n                  class=\"form-control\" data-base=\"{{ b.chave }}\"\n                  onchange=\"alternarCorte(this);\">\n            <option value=\"delete_insert_por_data\"\n                    {% if cfg.estrategia == 'delete_insert_por_data' %}selected{% endif %}>\n              Mensal — DELETE + INSERT por data\n            </option>\n            <option value=\"upsert_cadastral\"\n                    {% if cfg.estrategia == 'upsert_cadastral' %}selected{% endif %}>\n              Cadastral — UPSERT, sem DELETE\n            </option>\n          </select>\n        </div>\n\n        <div class=\"form-group\" style=\"min-width:200px;flex:1;\">\n          <label for=\"corte_{{ b.chave }}\">Coluna de corte</label>\n          <input type=\"text\" id=\"corte_{{ b.chave }}\" name=\"corte_{{ b.chave }}\"\n                 class=\"form-control text-mono\" value=\"{{ cfg.coluna_corte }}\"\n                 placeholder=\"mes\"\n                 {% if cfg.estrategia == 'upsert_cadastral' %}disabled{% endif %}>\n        </div>\n\n        <div class=\"form-group\" style=\"min-width:200px;flex:1;\">\n          <label>Chave de conflito (UPSERT)</label>\n          <input type=\"text\" class=\"form-control text-mono\"\n                 value=\"{{ cfg.conflict_columns | join(', ') or '—' }}\" readonly\n                 title=\"Definida pelo esquema da tabela\">\n        </div>\n      </div>\n\n      <div class=\"text-dim\" style=\"font-size:11px;margin-top:8px;\">\n        Colunas exportadas:\n        <span class=\"text-mono\">{{ cfg.columns | join(', ') }}</span>\n      </div>\n    </div>\n    {% endfor %}\n  </div>\n\n  <!-- 3 · Opções -->\n  <div class=\"card\" style=\"margin-top:18px;\">\n    <div class=\"form-section-title\">3 · Opções de conversão</div>\n    <div class=\"form-row\" style=\"flex-wrap:wrap;gap:16px;\">\n      <div class=\"form-group\" style=\"min-width:320px;flex:1;\">\n        <label for=\"percentual_formato\">Agro — <span class=\"text-mono\">percentual_rendimento</span></label>\n        <select id=\"percentual_formato\" name=\"percentual_formato\" class=\"form-control\">\n          <option value=\"fracao\" {% if opcoes.percentual_como_fracao %}selected{% endif %}>\n            Fração — 1,7% grava 0,017\n          </option>\n          <option value=\"percentual\" {% if not opcoes.percentual_como_fracao %}selected{% endif %}>\n            Percentual — 1,7% grava 1,70\n          </option>\n        </select>\n        <div class=\"text-dim\" style=\"font-size:11px;margin-top:6px;\">\n          Confira como os meses anteriores estão gravados no Supabase e use o mesmo formato.\n        </div>\n      </div>\n\n      <div class=\"form-group\" style=\"min-width:320px;flex:1;\">\n        <label for=\"escopo_cadastral\">Civil / Saúde — escopo do UPSERT</label>\n        <select id=\"escopo_cadastral\" name=\"escopo_cadastral\" class=\"form-control\">\n          <option value=\"tudo\" {% if not opcoes.cadastro_somente_alteradas %}selected{% endif %}>\n            Posição atual completa (todas as cotas do app)\n          </option>\n          <option value=\"alteradas\" {% if opcoes.cadastro_somente_alteradas %}selected{% endif %}>\n            Somente cotas criadas/alteradas desde a data de corte\n          </option>\n        </select>\n        <div class=\"text-dim\" style=\"font-size:11px;margin-top:6px;\">\n          Em nenhum dos dois casos há DELETE — linhas que só existem no Supabase ficam intactas.\n        </div>\n      </div>\n\n      <div class=\"form-group\" style=\"min-width:240px;flex:1;\">\n        <label for=\"fluxo_tipo\">Fluxo — <span class=\"text-mono\">tipo</span></label>\n        <input type=\"text\" id=\"fluxo_tipo\" name=\"fluxo_tipo\" class=\"form-control\"\n               value=\"{{ opcoes.fluxo_tipo }}\" maxlength=\"120\">\n        <div class=\"text-dim\" style=\"font-size:11px;margin-top:6px;\">\n          Precisa bater com a nomenclatura já usada no fluxo antigo.\n        </div>\n      </div>\n\n      <div class=\"form-group\" style=\"min-width:240px;flex:1;\">\n        <label for=\"fluxo_grupo\">Fluxo — <span class=\"text-mono\">grupo</span></label>\n        <input type=\"text\" id=\"fluxo_grupo\" name=\"fluxo_grupo\" class=\"form-control\"\n               value=\"{{ opcoes.fluxo_grupo }}\" maxlength=\"120\">\n        <div class=\"text-dim\" style=\"font-size:11px;margin-top:6px;\">\n          <span class=\"text-mono\">detalhe</span> usa sempre o nome do condomínio.\n        </div>\n      </div>\n    </div>\n\n    <div class=\"form-section-title\" style=\"margin-top:18px;\">\n      Grafia do status no Supabase\n    </div>\n    <div class=\"text-dim\" style=\"font-size:12px;margin-bottom:10px;\">\n      Deixe em branco para gravar exatamente como está no app\n      (<span class=\"text-mono\">ativa</span> / <span class=\"text-mono\">inativa</span>).\n      Na Saúde o status faz parte da chave do UPSERT — se a grafia não bater com\n      a do Supabase, o <span class=\"text-mono\">ON CONFLICT</span> nunca casa e\n      cada execução insere tudo de novo.\n    </div>\n    <div class=\"form-row\" style=\"flex-wrap:wrap;gap:12px;\">\n      {% for campo, rotulo, exemplo in [\n            ('status_civil_ativa',   'Civil · cotas ativas',   'Ativa'),\n            ('status_civil_inativa', 'Civil · cotas inativas', 'Inativa'),\n            ('status_saude_ativa',   'Saúde · cotas ativas',   'Ativo'),\n            ('status_saude_inativa', 'Saúde · cotas inativas', 'Inativo')] %}\n      <div class=\"form-group\" style=\"min-width:190px;flex:1;\">\n        <label for=\"{{ campo }}\">{{ rotulo }}</label>\n        <input type=\"text\" id=\"{{ campo }}\" name=\"{{ campo }}\" class=\"form-control\"\n               value=\"{{ opcoes.get(campo, '') }}\" placeholder=\"ex.: {{ exemplo }}\"\n               maxlength=\"60\">\n      </div>\n      {% endfor %}\n    </div>\n\n    {% if pontos_confirmar %}\n    <div class=\"note-box\" style=\"margin-top:14px;border-left:4px solid #f59e0b;\">\n      <div style=\"font-weight:700;color:#f59e0b;margin-bottom:6px;\">\n        ⚠️ Pontos a confirmar no Supabase antes de rodar em produção\n      </div>\n      <ul style=\"margin:0;padding-left:18px;font-size:12px;line-height:1.8;\">\n        {% for titulo, texto in pontos_confirmar %}\n        <li><span class=\"text-mono\">{{ titulo }}</span> — {{ texto }}</li>\n        {% endfor %}\n      </ul>\n      <div class=\"text-dim\" style=\"font-size:11px;margin-top:8px;\">\n        Estes mesmos avisos saem no SQL, no README e na aba <span class=\"text-mono\">resumo</span> do Excel.\n      </div>\n    </div>\n    {% endif %}\n  </div>\n\n  <div style=\"display:flex;justify-content:flex-end;gap:10px;margin-top:20px;\">\n    <button type=\"submit\" class=\"btn btn-primary\">🛰️ Gerar Exportação</button>\n  </div>\n</form>\n\n<!-- ═══════════════ RESULTADO ═══════════════ -->\n{% if resultado %}\n<div class=\"divider-gold\" style=\"margin:28px 0 18px;\"></div>\n\n<div class=\"page-header\" style=\"margin-bottom:12px;\">\n  <div class=\"page-header-title\" style=\"font-size:20px;\">Exportação {{ resultado.export_id }}</div>\n  <div class=\"page-header-sub\">Gerada em {{ resultado.gerado_em_txt }}</div>\n</div>\n\n{% for a in resultado.alertas %}\n<div class=\"alert alert-warning\">⚠️ {{ a }}</div>\n{% endfor %}\n\n<div class=\"metrics-grid\">\n  <div class=\"metric-card card-gold\">\n    <div class=\"metric-icon\">📅</div>\n    <div class=\"metric-label\">Data de corte</div>\n    <div class=\"metric-value\">{{ resultado.cutoff_iso }}</div>\n    <div class=\"metric-sub\">competência {{ resultado.cutoff_label }}</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-icon\">📦</div>\n    <div class=\"metric-label\">Total de registros</div>\n    <div class=\"metric-value\">{{ resultado.resumo.total_registros }}</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-icon\">🌾</div>\n    <div class=\"metric-label\">Registros Agro</div>\n    <div class=\"metric-value\">{{ resultado.resumo.registros_agro }}</div>\n    <div class=\"metric-sub\">mensal</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-icon\">💠</div>\n    <div class=\"metric-label\">Registros Fluxo</div>\n    <div class=\"metric-value\">{{ resultado.resumo.registros_fluxo }}</div>\n    <div class=\"metric-sub\">mensal</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-icon\">🏗️</div>\n    <div class=\"metric-label\">Registros Civil</div>\n    <div class=\"metric-value\">{{ resultado.resumo.registros_civil }}</div>\n    <div class=\"metric-sub\">cadastral</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-icon\">🏥</div>\n    <div class=\"metric-label\">Registros Saúde</div>\n    <div class=\"metric-value\">{{ resultado.resumo.registros_saude }}</div>\n    <div class=\"metric-sub\">cadastral</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-icon\">⏮️</div>\n    <div class=\"metric-label\">Período inicial</div>\n    <div class=\"metric-value\">{{ resultado.resumo.periodo_inicial or '—' }}</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-icon\">⏭️</div>\n    <div class=\"metric-label\">Período final</div>\n    <div class=\"metric-value\">{{ resultado.resumo.periodo_final or '—' }}</div>\n  </div>\n</div>\n\n<div style=\"display:flex;gap:10px;flex-wrap:wrap;margin-top:18px;\">\n  <a class=\"btn btn-primary\"\n     href=\"{{ url_for('exportacao_supabase_download', export_id=resultado.export_id, file_type='excel') }}\">\n     📊 Baixar Excel de conferência</a>\n  <a class=\"btn btn-secondary\"\n     href=\"{{ url_for('exportacao_supabase_download', export_id=resultado.export_id, file_type='csv') }}\">\n     📄 Baixar CSV</a>\n  <a class=\"btn btn-secondary\"\n     href=\"{{ url_for('exportacao_supabase_download', export_id=resultado.export_id, file_type='sql') }}\">\n     🧾 Baixar SQL</a>\n  <a class=\"btn btn-secondary\"\n     href=\"{{ url_for('exportacao_supabase_download', export_id=resultado.export_id, file_type='readme') }}\">\n     📘 Baixar README</a>\n</div>\n\n<div class=\"table-wrap\" style=\"margin-top:20px;\">\n  <table>\n    <thead>\n      <tr>\n        <th>Base</th>\n        <th>Tabela no Supabase</th>\n        <th style=\"text-align:center;\">Registros</th>\n        <th>Estratégia</th>\n        <th>Coluna de corte</th>\n        <th>Chave de conflito</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for t in resultado.tabelas %}\n      <tr>\n        <td>{{ t.label }}</td>\n        <td class=\"text-mono text-gold\">{{ t.tabela }}</td>\n        <td style=\"text-align:center;font-weight:600;\">{{ t.registros }}</td>\n        <td class=\"text-dim\" style=\"font-size:12px;\">\n          {% if t.estrategia == 'delete_insert_por_data' %}\n            DELETE WHERE {{ t.coluna_corte }} &gt;= '{{ resultado.cutoff_iso }}' + INSERT\n          {% else %}\n            INSERT … ON CONFLICT DO UPDATE (sem DELETE)\n          {% endif %}\n        </td>\n        <td class=\"text-mono\">{{ t.coluna_corte or '—' }}</td>\n        <td class=\"text-mono\">{{ t.conflict_columns | join(', ') or '—' }}</td>\n      </tr>\n      {% else %}\n      <tr><td colspan=\"6\" class=\"text-dim\">Nenhuma tabela — não havia registros a exportar.</td></tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n\n{% if resultado.avisos %}\n<div class=\"note-box\" style=\"margin-top:18px;\">\n  <div style=\"font-weight:700;margin-bottom:6px;\">Observações da geração</div>\n  <ul style=\"margin:0;padding-left:18px;font-size:12px;line-height:1.8;\">\n    {% for a in resultado.avisos %}<li>{{ a }}</li>{% endfor %}\n  </ul>\n</div>\n{% endif %}\n\n<div class=\"text-dim\" style=\"font-size:11px;margin-top:14px;\">\n  Arquivos gravados em <span class=\"text-mono\">exports/supabase_lovable/{{ resultado.export_id }}/</span>\n</div>\n{% endif %}\n\n<!-- ═══════════════ EXPORTAÇÕES ANTERIORES ═══════════════ -->\n{% if exports_anteriores %}\n<div class=\"divider-gold\" style=\"margin:28px 0 14px;\"></div>\n<div class=\"section-label\">Exportações anteriores</div>\n<div class=\"table-wrap\">\n  <table>\n    <thead>\n      <tr>\n        <th>Pasta</th><th>Gerada em</th><th>Data de corte</th>\n        <th style=\"text-align:center;\">Registros</th><th>Bases</th>\n        <th style=\"text-align:center;\">Arquivos</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for e in exports_anteriores %}\n      <tr>\n        <td class=\"text-mono\">{{ e.export_id }}</td>\n        <td class=\"text-dim\">{{ e.gerado_em }}</td>\n        <td class=\"text-dim\">{{ e.cutoff }}</td>\n        <td style=\"text-align:center;\">{{ e.registros }}</td>\n        <td class=\"text-dim\" style=\"font-size:12px;\">{{ e.bases }}</td>\n        <td style=\"text-align:center;\">\n          <div style=\"display:flex;gap:6px;justify-content:center;flex-wrap:wrap;\">\n            <a class=\"btn btn-secondary btn-sm\"\n               href=\"{{ url_for('exportacao_supabase_download', export_id=e.export_id, file_type='excel') }}\">Excel</a>\n            <a class=\"btn btn-secondary btn-sm\"\n               href=\"{{ url_for('exportacao_supabase_download', export_id=e.export_id, file_type='csv') }}\">CSV</a>\n            <a class=\"btn btn-secondary btn-sm\"\n               href=\"{{ url_for('exportacao_supabase_download', export_id=e.export_id, file_type='sql') }}\">SQL</a>\n            <a class=\"btn btn-secondary btn-sm\"\n               href=\"{{ url_for('exportacao_supabase_download', export_id=e.export_id, file_type='readme') }}\">README</a>\n          </div>\n        </td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n{% endif %}\n\n{% endblock %}\n\n{% block scripts %}\n<script>\nfunction alternarCorte(sel) {\n  var campo = document.getElementById('corte_' + sel.dataset.base);\n  if (!campo) return;\n  if (sel.value === 'upsert_cadastral') {\n    campo.dataset.anterior = campo.value;\n    campo.value = '';\n    campo.disabled = true;\n  } else {\n    campo.disabled = false;\n    if (!campo.value) campo.value = campo.dataset.anterior || 'mes';\n  }\n}\n\nfunction confirmarGeracao() {\n  var campo = document.getElementById('cutoff');\n  var valor = (campo.value || '').trim();\n  if (!valor) {\n    alert('Informe a data de corte. Ela é obrigatória.');\n    campo.focus();\n    return false;\n  }\n  if (document.querySelectorAll('input[name=\"bases\"]:checked').length === 0) {\n    alert('Selecione pelo menos uma base para exportar.');\n    return false;\n  }\n  var faltando = [];\n  document.querySelectorAll('input[name=\"bases\"]:checked').forEach(function (cb) {\n    var est = document.getElementById('estrategia_' + cb.value);\n    var col = document.getElementById('corte_' + cb.value);\n    if (est && est.value === 'delete_insert_por_data' && col && !col.value.trim()) {\n      faltando.push(cb.value);\n    }\n  });\n  if (faltando.length) {\n    alert('A estratégia mensal exige a coluna de corte nas bases: ' + faltando.join(', '));\n    return false;\n  }\n  if (valor < '{{ cutoff_minimo }}') {\n    return confirm(\n      'ATENÇÃO\\n\\nA data de corte ' + valor + ' é anterior a {{ cutoff_minimo }}.\\n\\n' +\n      'Nas tabelas mensais o SQL passará a substituir meses que vieram das planilhas originais.\\n\\n' +\n      'Deseja gerar mesmo assim?'\n    );\n  }\n  return true;\n}\n</script>\n{% endblock %}\n",
  "financas/_dlg_baixa.html": "{# Diálogo de baixa (pagamento/recebimento). Botões com data-baixar preenchem os campos. #}\n<dialog id=\"dlg-baixa\" class=\"dlg fin-dlg\">\n  <form method=\"post\" id=\"form-baixa\" data-base=\"{{ url_for('financas.lancamento_baixar', slug=empresa.slug, lid=0) }}\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n    <input type=\"hidden\" name=\"voltar\" value=\"{{ request.full_path }}\">\n    <div class=\"dlg-head\"><h3 id=\"baixa-tit\">Registrar pagamento</h3><button type=\"button\" class=\"ico\" data-fechar>{{ ic('close') }}</button></div>\n    <p id=\"baixa-desc\" class=\"fin-sub\"></p>\n    <div class=\"fin-2col\">\n      <div><label class=\"lbl\">Data</label><input class=\"inp\" type=\"date\" name=\"data\" value=\"{{ hoje_iso }}\" required></div>\n      <div><label class=\"lbl\">Conta</label>\n        <select class=\"inp\" name=\"conta_id\" required><option value=\"\">Escolha…</option>\n          {% for c in contas_ativas %}<option value=\"{{ c.id }}\">{{ c.nome }}</option>{% endfor %}</select></div>\n    </div>\n    <div class=\"fin-3col\">\n      <div><label class=\"lbl\">Valor pago (R$)</label><input class=\"inp\" name=\"valor\" required inputmode=\"decimal\" data-moeda></div>\n      <div><label class=\"lbl\">Juros/multa (R$)</label><input class=\"inp\" name=\"juros\" inputmode=\"decimal\" data-moeda placeholder=\"R$ 0,00\"></div>\n      <div><label class=\"lbl\">Desconto (R$)</label><input class=\"inp\" name=\"desconto\" inputmode=\"decimal\" data-moeda placeholder=\"R$ 0,00\"></div>\n    </div>\n    <p class=\"fin-sub\">Valor menor que o saldo, sem desconto, fica como pagamento parcial.</p>\n    <button class=\"btn-pill\" type=\"submit\">Confirmar</button>\n  </form>\n</dialog>\n<script>\ndocument.querySelectorAll('[data-baixar]').forEach(function (b) {\n  b.addEventListener('click', function () {\n    var f = document.getElementById('form-baixa');\n    f.action = f.dataset.base.replace(/\\/0\\/baixar$/, '/' + b.dataset.baixar + '/baixar');\n    f.valor.value = b.dataset.saldo; f.juros.value = ''; f.desconto.value = '';\n    if (b.dataset.conta) f.conta_id.value = b.dataset.conta;\n    document.getElementById('baixa-desc').textContent = b.dataset.desc;\n    document.getElementById('dlg-baixa').showModal();\n  });\n});\n</script>\n",
  "financas/_dlg_lancamento.html": "{# Diálogo de novo lançamento. Espera: tipo ('receber'|'pagar'), contas, e categorias/pessoas/centros (opcionais) #}\n<dialog id=\"dlg-{{ tipo }}\" class=\"dlg fin-dlg\">\n  <form method=\"post\" action=\"{{ url_for('financas.lancamento_novo', slug=empresa.slug, tipo=tipo) }}\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n    <input type=\"hidden\" name=\"voltar\" value=\"{{ request.full_path }}\">\n    <div class=\"dlg-head\"><h3>{{ 'Nova conta a receber' if tipo == 'receber' else 'Nova conta a pagar' }}</h3>\n      <button type=\"button\" class=\"ico\" data-fechar>{{ ic('close') }}</button></div>\n    <label class=\"lbl\">Descrição</label>\n    <input class=\"inp\" name=\"descricao\" required maxlength=\"200\" placeholder=\"{{ 'Ex.: Mensalidade outubro' if tipo == 'receber' else 'Ex.: Aluguel do escritório' }}\">\n    <div class=\"fin-3col\">\n      <div><label class=\"lbl\">Valor (R$)</label><input class=\"inp\" name=\"valor\" required inputmode=\"decimal\" data-moeda placeholder=\"R$ 0,00\"></div>\n      <div><label class=\"lbl\">Vencimento</label><input class=\"inp\" type=\"date\" name=\"vencimento\" required value=\"{{ hoje_iso }}\"></div>\n      <div><label class=\"lbl\">Competência</label><input class=\"inp\" type=\"date\" name=\"competencia\" value=\"{{ hoje_iso }}\"></div>\n    </div>\n    <div class=\"fin-2col\">\n      <div><label class=\"lbl\">{{ 'Cliente' if tipo == 'receber' else 'Fornecedor' }}</label>\n        <select class=\"inp\" name=\"pessoa_id\"><option value=\"\">—</option>\n          {% for p in pessoas_todas %}\n            {% if (tipo == 'receber' and p.tipo in ('cliente','ambos')) or (tipo == 'pagar' and p.tipo in ('fornecedor','ambos')) %}<option value=\"{{ p.id }}\">{{ p.nome }}</option>{% endif %}\n          {% endfor %}\n        </select></div>\n      <div><label class=\"lbl\">Categoria</label>\n        <select class=\"inp\" name=\"categoria_id\"><option value=\"\">—</option>\n          {% for c in categorias_todas %}\n            {% if (tipo == 'receber' and c.tipo == 'receita') or (tipo == 'pagar' and c.tipo == 'despesa') %}<option value=\"{{ c.id }}\">{{ c.nome }}</option>{% endif %}\n          {% endfor %}\n        </select></div>\n    </div>\n    <div class=\"fin-2col\">\n      <div><label class=\"lbl\">Conta prevista</label>\n        <select class=\"inp\" name=\"conta_id\"><option value=\"\">—</option>\n          {% for c in contas_ativas %}{% if c.ativa %}<option value=\"{{ c.id }}\">{{ c.nome }}</option>{% endif %}{% endfor %}\n        </select></div>\n      <div><label class=\"lbl\">Forma de pagamento</label>\n        <select class=\"inp\" name=\"forma_pagamento\"><option value=\"\">—</option>{% for f in FORMAS %}<option>{{ f }}</option>{% endfor %}</select></div>\n    </div>\n    <details class=\"fin-mais\">\n      <summary>Repetir, parcelar e mais detalhes</summary>\n      <div class=\"fin-2col\">\n        <div><label class=\"lbl\">Repetição</label>\n          <select class=\"inp\" name=\"modo\" data-modo>\n            <option value=\"unico\">Não repete</option>\n            <option value=\"parcelado\">Parcelado (divide o valor)</option>\n            <option value=\"recorrente\">Recorrente mensal (mesmo valor)</option>\n          </select></div>\n        <div><label class=\"lbl\">Quantidade</label><input class=\"inp\" type=\"number\" name=\"parcelas\" min=\"1\" max=\"120\" value=\"1\"></div>\n      </div>\n      <div class=\"fin-2col\">\n        <div><label class=\"lbl\">Centro de custo</label>\n          <select class=\"inp\" name=\"centro_id\"><option value=\"\">—</option>\n            {% for c in centros_todos %}<option value=\"{{ c.id }}\">{{ c.nome }}</option>{% endfor %}</select></div>\n        <div><label class=\"lbl\">Nº documento / NF</label><input class=\"inp\" name=\"documento\" maxlength=\"60\"></div>\n      </div>\n      <label class=\"lbl\">Observações</label><textarea class=\"inp\" name=\"obs\" rows=\"2\"></textarea>\n      <label class=\"fin-check\"><input type=\"checkbox\" name=\"ja_pago\" value=\"1\"> Já foi {{ 'recebido' if tipo == 'receber' else 'pago' }} (registra na conta prevista)</label>\n      <input type=\"hidden\" name=\"data_pagamento\" value=\"{{ hoje_iso }}\">\n    </details>\n    <button class=\"btn-pill\" type=\"submit\">Salvar</button>\n  </form>\n</dialog>\n",
  "financas/_layout.html": "{% extends \"portal/base.html\" %}\n{% block title %}{% block fin_titulo %}Finanças{% endblock %} · {{ empresa.nome }}{% endblock %}\n{% block head %}<link rel=\"stylesheet\" href=\"{{ url_for('financas.static', filename='financas.css') }}?v=18\">{% endblock %}\n{% block body_class %}erp-com-trilho{% endblock %}\n{% block brand %}\n  <span class=\"logo-circle xs\"><img src=\"{{ url_for('static', filename='portal/logos/' ~ empresa.logo) }}\" alt=\"\"></span>\n  <span class=\"tb-name\"><b>{{ empresa.nome }}</b><small>Grupo Capuzzo</small></span>\n{% endblock %}\n{% block tb_links %}\n  <a class=\"tb-btn\" href=\"{{ url_for('portal_empresa', slug=empresa.slug) }}\">{{ ic('grid_view') }}<span class=\"lbl\">Módulos</span></a>\n  {% include \"operacao/_barra_empresa.html\" ignore missing %}\n{% endblock %}\n{% block content %}\n\n{# ── Menu lateral: barra fina só com ícones; abre ao passar o mouse ── #}\n<nav class=\"erp-trilho\" id=\"erp-trilho\" aria-label=\"Menu do ERP\">\n  <button type=\"button\" class=\"erp-t erp-fixar\" id=\"erp-fixar\" title=\"Fixar menu aberto (M)\">\n    {{ fic('menu') }}<span class=\"rot\">Fixar menu</span></button>\n  {% set ns = namespace(prod=false) %}\n  {% for t in menu %}\n    {% if t == '-' %}<span class=\"erp-t-sep\"></span>\n    {% else %}\n      {% if t.produto and not ns.prod %}<span class=\"erp-rot-sec\">Produtos</span>{% set ns.prod = true %}{% endif %}\n      <div class=\"erp-item {{ 'grupo' if t.itens }} {{ 'on' if topico == t.id }}\">\n        {% if t.url %}\n          <a class=\"erp-t {{ 'on' if topico == t.id }}\" href=\"{{ t.url }}\" title=\"{{ t.rotulo }}\">{{ fic(t.icone) }}<span class=\"rot\">{{ t.rotulo }}</span></a>\n        {% else %}\n          <button type=\"button\" class=\"erp-t {{ 'on' if topico == t.id }}\" title=\"{{ t.rotulo }}\">{{ fic(t.icone) }}<span class=\"rot\">{{ t.rotulo }}</span>\n            <span class=\"seta\">{{ ic('expand_more') }}</span></button>\n          <div class=\"erp-sub\">\n            {% for i in t.itens %}<a class=\"{{ 'on' if fin_ativo == i.chave }}\" href=\"{{ i.url }}\">{{ i.rotulo }}</a>{% endfor %}\n          </div>\n        {% endif %}\n      </div>\n    {% endif %}\n  {% endfor %}\n  <div class=\"erp-item erp-fim\">\n    <a class=\"erp-t\" href=\"{{ url_for('portal_empresa', slug=empresa.slug) }}\" title=\"Voltar à empresa\">{{ ic('arrow_back') }}<span class=\"rot\">Voltar à empresa</span></a>\n  </div>\n</nav>\n<div class=\"erp-fundo\" id=\"erp-fundo\"></div>\n<button type=\"button\" class=\"erp-movel\" id=\"erp-movel\" aria-label=\"Abrir menu\">{{ fic('menu') }}</button>\n\n<section class=\"fin-main erp-main\">\n  {% block fin_conteudo %}{% endblock %}\n</section>\n\n<script>\n(function () {\n  var b = document.body, r = document.getElementById('erp-trilho'), t;\n  try { if (localStorage.getItem('erp_menu_fixo') === '1' && window.innerWidth > 1200) b.classList.add('erp-fixo'); } catch (e) {}\n  function fixar(v) { b.classList.toggle('erp-fixo', v); try { localStorage.setItem('erp_menu_fixo', v ? '1' : '0'); } catch (e) {} }\n  // abre ao passar o mouse (com pequeno atraso para não abrir sem querer)\n  r.addEventListener('mouseenter', function () { clearTimeout(t); t = setTimeout(function () { b.classList.add('erp-hover'); }, 120); });\n  r.addEventListener('mouseleave', function () { clearTimeout(t); t = setTimeout(function () { b.classList.remove('erp-hover'); }, 180); });\n  document.getElementById('erp-fixar').addEventListener('click', function () { fixar(!b.classList.contains('erp-fixo')); });\n  document.getElementById('erp-movel').addEventListener('click', function () { b.classList.add('erp-movel-on'); });\n  document.getElementById('erp-fundo').addEventListener('click', function () { b.classList.remove('erp-movel-on'); });\n  // grupos: no toque/clique abre e fecha as opções\n  r.querySelectorAll('.erp-item.grupo > .erp-t').forEach(function (x) {\n    x.addEventListener('click', function () { x.parentNode.classList.toggle('aberto'); b.classList.add('erp-hover'); });\n  });\n  document.addEventListener('keydown', function (e) {\n    if (e.key === 'Escape') { b.classList.remove('erp-movel-on', 'erp-hover'); }\n    if ((e.key === 'm' || e.key === 'M') && !/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName) && !e.ctrlKey && !e.metaKey && !e.altKey) {\n      fixar(!b.classList.contains('erp-fixo'));\n    }\n  });\n  var tb = document.querySelector('.topbar');\n  function topo() { document.documentElement.style.setProperty('--erp-topo', (tb ? tb.getBoundingClientRect().bottom : 0) + 'px'); }\n  topo(); window.addEventListener('resize', topo); window.addEventListener('scroll', topo, {passive: true});\n})();\n\n// Campos de valor: aceita 1.234,56 e mostra com separador de milhar ao sair do campo.\ndocument.querySelectorAll('input[data-moeda]').forEach(function (i) {\n  i.addEventListener('blur', function () {\n    var s = i.value.replace(/[^\\d,.-]/g, ''); if (!s) { i.value = ''; return; }\n    if (s.indexOf(',') >= 0) s = s.replace(/\\./g, '').replace(',', '.');\n    var n = parseFloat(s); if (isNaN(n)) return;\n    i.value = (n < 0 ? '-' : '') + 'R$ ' + Math.abs(n).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n  });\n});\ndocument.querySelectorAll('[data-abrir]').forEach(function (b) {\n  b.addEventListener('click', function () { var d = document.getElementById(b.dataset.abrir); if (d) d.showModal(); });\n});\ndocument.querySelectorAll('dialog [data-fechar]').forEach(function (b) {\n  b.addEventListener('click', function () { b.closest('dialog').close(); });\n});\n</script>\n{% block fin_scripts %}{% endblock %}\n{% endblock %}\n",
  "financas/_periodo.html": "{# Seletor de período: mês com setas + datas livres. Espera: de, ate, nav, ep (endpoint), extra (dict de parâmetros) #}\n<form class=\"fin-periodo\" method=\"get\">\n  {% for k, v in extra.items() %}{% if v not in (none, '') %}<input type=\"hidden\" name=\"{{ k }}\" value=\"{{ v }}\">{% endif %}{% endfor %}\n  {% if nav %}\n    <a class=\"fin-seta-mes\" href=\"{{ url_for(ep, slug=empresa.slug, de=nav.ant[0], ate=nav.ant[1], **extra) }}\" aria-label=\"Mês anterior\">‹</a>\n    <b class=\"fin-mes-rot\">{{ nav.rotulo }}</b>\n    <a class=\"fin-seta-mes\" href=\"{{ url_for(ep, slug=empresa.slug, de=nav.prox[0], ate=nav.prox[1], **extra) }}\" aria-label=\"Próximo mês\">›</a>\n  {% endif %}\n  <input class=\"inp\" type=\"date\" name=\"de\" value=\"{{ de }}\" aria-label=\"De\">\n  <span>até</span>\n  <input class=\"inp\" type=\"date\" name=\"ate\" value=\"{{ ate }}\" aria-label=\"Até\">\n  <button class=\"btn-pill outline fin-btn\" type=\"submit\">Aplicar</button>\n</form>\n",
  "financas/cad_categorias.html": "{% extends \"financas/_layout.html\" %}\n{% block fin_titulo %}Categorias{% endblock %}\n{% block fin_conteudo %}\n{% set c = editar or {} %}\n{% set nat_atual = (GRUPOS_DRE | selectattr(0, 'equalto', c.grupo_dre) | map(attribute=2) | first) if editar else 'despesa' %}\n<div class=\"fin-head\"><div><div class=\"eyebrow-line\">Cadastros</div><h1>Plano de categorias</h1>\n  <p>Receitas e despesas organizadas pelos grupos da DRE. Ao digitar uma nova categoria, o sistema sugere o grupo certo.</p></div>\n  <div class=\"fin-acoes\"><label class=\"search\">{{ ic('search') }}<input type=\"search\" id=\"cat-busca\" placeholder=\"Filtrar categorias\"></label></div>\n</div>\n\n<div class=\"cat-grid\">\n  {% for natureza, titulo in [('receita', 'Receitas'), ('despesa', 'Despesas')] %}\n  <section class=\"cat-col {{ natureza }}\">\n    {% set grupos = por_grupo | selectattr(2, 'equalto', natureza) | list %}\n    <header class=\"cat-col-topo\"><h2>{{ titulo }}</h2>\n      <span>{{ grupos | map(attribute=3) | map('length') | sum }} categorias · {{ grupos | length }} grupos</span></header>\n    {% for chave, nome, nat, cats in grupos %}\n    <div class=\"cat-grupo\" data-grupo=\"{{ chave }}\">\n      <div class=\"cat-g-topo\"><b>{{ nome }}</b><small>{{ cats | length }}</small></div>\n      <ul>\n        {% for x in cats %}\n          <li class=\"{{ 'inativa' if not x.ativo }} {{ 'sel' if editar and editar.id == x.id }}\" data-nome=\"{{ x.nome | lower }}\">\n            <a href=\"{{ url_for('financas.cad_categorias', slug=empresa.slug, editar=x.id) }}\" title=\"{{ x.nome }}\">{{ x.nome }}</a>\n            <span class=\"uso {{ 'zero' if not uso.get(x.id) }}\">{{ uso.get(x.id, 0) }}</span>\n          </li>\n        {% else %}<li class=\"vazio\">Nenhuma categoria.</li>{% endfor %}\n      </ul>\n    </div>\n    {% endfor %}\n  </section>\n  {% endfor %}\n\n  <section class=\"fin-box cat-form\">\n    <header><h3>{{ 'Editar categoria' if editar else 'Nova categoria' }}</h3>{% if editar %}<a class=\"fin-link\" href=\"{{ url_for('financas.cad_categorias', slug=empresa.slug) }}\">+ nova</a>{% endif %}</header>\n    <form method=\"post\" class=\"fin-form\" id=\"f-cat\" autocomplete=\"off\">\n      <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><input type=\"hidden\" name=\"id\" value=\"{{ c.id or '' }}\">\n      <label class=\"lbl\">Natureza</label>\n      <div class=\"cat-nat\">\n        <label><input type=\"radio\" name=\"natureza\" value=\"receita\" {{ 'checked' if nat_atual == 'receita' }}><span>{{ fic('receber') }} Receita</span></label>\n        <label><input type=\"radio\" name=\"natureza\" value=\"despesa\" {{ 'checked' if nat_atual == 'despesa' }}><span>{{ fic('pagar') }} Despesa</span></label>\n      </div>\n      <label class=\"lbl\">Nome</label><input class=\"inp\" name=\"nome\" id=\"cat-nome\" required maxlength=\"80\" value=\"{{ c.nome or '' }}\" placeholder=\"Ex.: Tarifa PIX, Google Ads, Pró-labore\">\n      <div class=\"cat-sug\" id=\"cat-sug\" hidden></div>\n      <label class=\"lbl\">Grupo da DRE</label>\n      <select class=\"inp\" name=\"grupo_dre\" id=\"cat-grupo\" required>\n        {% for k, n, nat in GRUPOS_DRE %}<option value=\"{{ k }}\" data-nat=\"{{ nat }}\" {{ 'selected' if c.grupo_dre == k }}>{{ n }}</option>{% endfor %}\n      </select>\n      {% if editar %}\n        <p class=\"fin-sub\">{{ uso.get(c.id, 0) }} lançamento(s) usam esta categoria. Mudar o grupo altera a DRE desses lançamentos.</p>\n        <label class=\"fin-check\"><input type=\"hidden\" name=\"ativo\" value=\"0\"><input type=\"checkbox\" name=\"ativo\" value=\"1\" {{ 'checked' if c.ativo }}> Categoria ativa</label>\n      {% endif %}\n      <button class=\"btn-pill fin-btn\" type=\"submit\" style=\"margin-top:.7rem\">Salvar</button>\n    </form>\n  </section>\n</div>\n{% endblock %}\n\n{% block fin_scripts %}\n<script>\n(function () {\n  var f = document.getElementById('f-cat'), nome = document.getElementById('cat-nome'), grupo = document.getElementById('cat-grupo'),\n      sug = document.getElementById('cat-sug'), editando = !!f.querySelector('[name=id]').value, manual = editando, t;\n  function nat() { return (f.querySelector('[name=natureza]:checked') || {}).value; }\n  function filtrarGrupos() {\n    var n = nat();\n    [].forEach.call(grupo.options, function (o) { o.hidden = o.dataset.nat !== n; });\n    if (grupo.selectedOptions[0] && grupo.selectedOptions[0].hidden) {\n      var p = [].find.call(grupo.options, function (o) { return !o.hidden; }); if (p) grupo.value = p.value;\n    }\n  }\n  function marcar(nt) { var r = f.querySelector('[name=natureza][value=' + nt + ']'); if (r && !r.checked) { r.checked = true; filtrarGrupos(); } }\n  function sugerir(semNatureza) {\n    var v = nome.value.trim(); if (v.length < 3) { sug.hidden = true; return; }\n    var url = '{{ url_for(\"financas.cad_categorias_sugerir\", slug=empresa.slug) }}?nome=' + encodeURIComponent(v) + (semNatureza ? '' : '&natureza=' + nat());\n    fetch(url, {credentials: 'same-origin'}).then(function (r) { return r.json(); }).then(function (j) {\n      if (!j.grupo) { sug.hidden = true; return; }\n      // sem pista na natureza escolhida? tenta sem natureza (ex.: \"Rendimento CDB\" digitado com Despesa marcada)\n      if (j.confianca === 'baixa' && !semNatureza) { return sugerir(true); }\n      sug.hidden = false; sug.className = 'cat-sug ' + j.confianca;\n      var aplicar = !manual;\n      sug.innerHTML = '✨ Sugestão: <b>' + j.grupo_nome + '</b> <span>' + j.motivo + '</span>' +\n        (aplicar || grupo.value === j.grupo ? '' : ' <button type=\"button\" class=\"fin-link\" id=\"cat-usar\">usar</button>');\n      if (aplicar) { marcar(j.natureza); grupo.value = j.grupo; }\n      var u = document.getElementById('cat-usar');\n      if (u) u.onclick = function () { marcar(j.natureza); grupo.value = j.grupo; manual = false; sug.querySelector('button').remove(); };\n    }).catch(function () {});\n  }\n  nome.addEventListener('input', function () { clearTimeout(t); t = setTimeout(function () { sugerir(false); }, 250); });\n  grupo.addEventListener('change', function () { manual = true; });\n  f.querySelectorAll('[name=natureza]').forEach(function (r) { r.addEventListener('change', function () { filtrarGrupos(); sugerir(false); }); });\n  filtrarGrupos();\n  if (editando) sugerir(false);\n\n  // filtro da lista\n  var busca = document.getElementById('cat-busca');\n  busca.addEventListener('input', function () {\n    var q = busca.value.trim().toLowerCase();\n    document.querySelectorAll('.cat-grupo').forEach(function (g) {\n      var vis = 0;\n      g.querySelectorAll('li[data-nome]').forEach(function (li) { var ok = !q || li.dataset.nome.indexOf(q) >= 0; li.hidden = !ok; if (ok) vis++; });\n      g.hidden = q && !vis;\n    });\n  });\n})();\n</script>\n{% endblock %}\n",
  "financas/cad_centros.html": "{% extends \"financas/_layout.html\" %}\n{% block fin_titulo %}Centros de custo{% endblock %}\n{% block fin_conteudo %}\n<div class=\"fin-head\"><div><div class=\"eyebrow-line\">Cadastros</div><h1>Centros de custo</h1>\n  <p>Separe receitas e despesas por área, projeto ou unidade (ex.: Matriz, Filial, Projeto X).</p></div></div>\n<div class=\"fin-cols\">\n  <section class=\"fin-box\">\n    <ul class=\"fin-cats\">\n      {% for c in centros %}<li class=\"{{ 'inativa' if not c.ativo }}\"><a href=\"{{ url_for('financas.cad_centros', slug=empresa.slug, editar=c.id) }}\">{{ c.nome }}</a>{% if not c.ativo %}<small>inativo</small>{% endif %}</li>\n      {% else %}<li class=\"vazio\">Nenhum centro de custo.</li>{% endfor %}\n    </ul>\n  </section>\n  <section class=\"fin-box\">\n    <header><h3>{{ 'Editar' if editar else 'Novo centro de custo' }}</h3>{% if editar %}<a class=\"fin-link\" href=\"{{ url_for('financas.cad_centros', slug=empresa.slug) }}\">+ novo</a>{% endif %}</header>\n    {% set c = editar or {} %}\n    <form method=\"post\" class=\"fin-form\">\n      <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><input type=\"hidden\" name=\"id\" value=\"{{ c.id or '' }}\">\n      <label class=\"lbl\">Nome</label><input class=\"inp\" name=\"nome\" required maxlength=\"80\" value=\"{{ c.nome or '' }}\">\n      {% if editar %}<label class=\"fin-check\"><input type=\"hidden\" name=\"ativo\" value=\"0\"><input type=\"checkbox\" name=\"ativo\" value=\"1\" {{ 'checked' if c.ativo }}> Ativo</label>{% endif %}\n      <button class=\"btn-pill fin-btn\" type=\"submit\">Salvar</button>\n    </form>\n  </section>\n</div>\n{% endblock %}\n",
  "financas/cad_contas.html": "{% extends \"financas/_layout.html\" %}\n{% block fin_titulo %}Contas bancárias{% endblock %}\n{% block fin_conteudo %}\n<div class=\"fin-head\"><div><div class=\"eyebrow-line\">Cadastros</div><h1>Contas bancárias</h1>\n  <p>Bancos, caixa, aplicações e cartões. O saldo inicial é o ponto de partida do extrato.</p></div></div>\n{% if contas %}\n{% set n_cons = contas|selectattr('considerada')|list|length %}\n<form method=\"post\" class=\"fin-box cc-sel\" id=\"cc-sel\">\n  <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><input type=\"hidden\" name=\"acao\" value=\"considerar\">\n  <header><h3>Contas consideradas no sistema</h3><span id=\"cc-n\">{{ n_cons }} de {{ contas|length }}</span></header>\n  <p class=\"co-dica\">Só as contas marcadas aparecem nos saldos, no extrato, nas contas a pagar e a receber, no fluxo de caixa e na DRE.\n    As desmarcadas continuam guardadas (nada é apagado) e voltam a aparecer quando você marcar de novo.</p>\n  <div class=\"cc-acoes\">\n    <button type=\"button\" class=\"fin-link\" data-cc=\"todas\">Marcar todas</button>\n    <button type=\"button\" class=\"fin-link\" data-cc=\"nenhuma\">Desmarcar todas</button>\n  </div>\n  <div class=\"cc-lista\">\n    {% for c in contas|sort(attribute='nome') %}\n      <label class=\"cc-item {{ 'off' if not c.considerada }}\">\n        <input type=\"checkbox\" name=\"considerada\" value=\"{{ c.id }}\" {{ 'checked' if c.considerada }}>\n        <span class=\"txt\"><b>{{ c.nome }}</b><small>{{ TIPOS_CONTA.get(c.tipo) }}{% if not c.ativa %} · inativa{% endif %}</small></span>\n        <b class=\"num {{ 'neg' if c.saldo < 0 }}\">{{ moeda(c.saldo) }}</b>\n      </label>\n    {% endfor %}\n  </div>\n  <div class=\"cc-rodape\"><span>Total das marcadas: <b id=\"cc-tot\">{{ moeda(contas|selectattr('considerada')|sum(attribute='saldo')) }}</b></span>\n    <button class=\"btn-pill fin-btn\" type=\"submit\">{{ ic('check') }} Salvar seleção</button></div>\n</form>\n<script>\n(function () {\n  var f = document.getElementById('cc-sel'); if (!f) return;\n  var saldos = { {% for c in contas %}\"{{ c.id }}\": {{ c.saldo }}{{ ',' if not loop.last }}{% endfor %} };\n  function brl(v) { return (v / 100).toLocaleString('pt-BR', {style: 'currency', currency: 'BRL'}); }\n  function atualiza() {\n    var cx = f.querySelectorAll('input[name=considerada]'), n = 0, t = 0;\n    cx.forEach(function (c) { c.closest('.cc-item').classList.toggle('off', !c.checked); if (c.checked) { n++; t += saldos[c.value] || 0; } });\n    document.getElementById('cc-n').textContent = n + ' de ' + cx.length; document.getElementById('cc-tot').textContent = brl(t);\n  }\n  f.addEventListener('change', atualiza);\n  f.querySelectorAll('[data-cc]').forEach(function (b) { b.addEventListener('click', function () {\n    f.querySelectorAll('input[name=considerada]').forEach(function (c) { c.checked = b.dataset.cc === 'todas'; }); atualiza(); }); });\n})();\n</script>\n{% endif %}\n\n<div class=\"fin-cols\">\n  <div class=\"fin-contas-grade\">\n    {% for c in contas %}\n      <a class=\"fin-conta {{ 'inativa' if not c.ativa or not c.considerada }}\" href=\"{{ url_for('financas.cad_contas', slug=empresa.slug, editar=c.id) }}\">\n        <span class=\"fin-conta-ic\">{{ fic('banco') }}</span>\n        <span class=\"txt\"><b>{{ c.nome }}</b><small>{{ TIPOS_CONTA.get(c.tipo) }}{% if c.banco %} · {{ c.banco }}{% endif %}{% if c.agencia %} · Ag. {{ c.agencia }}{% endif %}{% if c.numero %} · C/C {{ c.numero }}{% endif %}{% if not c.ativa %} · inativa{% endif %}{% if not c.considerada %} · fora do sistema{% endif %}</small></span>\n        <b class=\"{{ 'neg' if c.saldo < 0 }}\">{{ moeda(c.saldo) }}</b>\n      </a>\n    {% else %}\n      <p class=\"fin-vazio\">Nenhuma conta ainda. Cadastre ao lado.</p>\n    {% endfor %}\n  </div>\n  <section class=\"fin-box\">\n    <header><h3>{{ 'Editar conta' if editar else 'Nova conta' }}</h3>{% if editar %}<a class=\"fin-link\" href=\"{{ url_for('financas.cad_contas', slug=empresa.slug) }}\">+ nova</a>{% endif %}</header>\n    {% set c = editar or {} %}\n    <form method=\"post\" class=\"fin-form\">\n      <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><input type=\"hidden\" name=\"id\" value=\"{{ c.id or '' }}\">\n      <label class=\"lbl\">Nome da conta</label><input class=\"inp\" name=\"nome\" required maxlength=\"80\" value=\"{{ c.nome or '' }}\" placeholder=\"Ex.: Itaú PJ\">\n      <div class=\"fin-2col\">\n        <div><label class=\"lbl\">Tipo</label><select class=\"inp\" name=\"tipo\">{% for k, v in TIPOS_CONTA.items() %}<option value=\"{{ k }}\" {{ 'selected' if c.tipo == k }}>{{ v }}</option>{% endfor %}</select></div>\n        <div><label class=\"lbl\">Banco</label><input class=\"inp\" name=\"banco\" maxlength=\"60\" value=\"{{ c.banco or '' }}\" placeholder=\"Ex.: Itaú (341)\"></div>\n      </div>\n      <div class=\"fin-2col\">\n        <div><label class=\"lbl\">Agência</label><input class=\"inp\" name=\"agencia\" maxlength=\"20\" value=\"{{ c.agencia or '' }}\"></div>\n        <div><label class=\"lbl\">Conta</label><input class=\"inp\" name=\"numero\" maxlength=\"30\" value=\"{{ c.numero or '' }}\"></div>\n      </div>\n      <div class=\"fin-2col\">\n        <div><label class=\"lbl\">Saldo inicial (R$)</label><input class=\"inp\" name=\"saldo_inicial\" data-moeda value=\"{{ valor_campo(c.saldo_inicial) if c else '' }}\" placeholder=\"R$ 0,00\"></div>\n        <div><label class=\"lbl\">Data do saldo inicial</label><input class=\"inp\" type=\"date\" name=\"data_saldo_inicial\" value=\"{{ c.data_saldo_inicial or hoje_iso }}\"></div>\n      </div>\n      {% if editar %}<label class=\"fin-check\"><input type=\"hidden\" name=\"ativa\" value=\"0\"><input type=\"checkbox\" name=\"ativa\" value=\"1\" {{ 'checked' if c.ativa }}> Conta ativa</label>\n      <label class=\"fin-check\"><input type=\"hidden\" name=\"considerada\" value=\"0\"><input type=\"checkbox\" name=\"considerada\" value=\"1\" {{ 'checked' if c.considerada }}> Considerar no sistema</label>{% endif %}\n      <button class=\"btn-pill fin-btn\" type=\"submit\">Salvar</button>\n    </form>\n  </section>\n</div>\n{% endblock %}\n",
  "financas/cad_integracoes.html": "{% extends \"financas/_layout.html\" %}\n{% block fin_titulo %}Integrações (API){% endblock %}\n{% block fin_conteudo %}\n<div class=\"fin-head\"><div><div class=\"eyebrow-line\">Cadastros · somente administradores</div><h1>Integrações (API)</h1>\n  <p>Conecte o ERP a outros sistemas para que as informações entrem sozinhas, sem digitação.</p></div></div>\n\n<form method=\"post\" class=\"api-card fin-box\" id=\"f-api\" autocomplete=\"off\">\n  <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n  <header class=\"api-head\">\n    <div class=\"api-logo\">Omie</div>\n    <div><h3>Omie ERP</h3><small>Traz o que está <b>conciliado</b> no Omie: recebimentos, pagamentos e transferências de cada conta, com categorias e clientes/fornecedores.</small></div>\n    <div class=\"api-st\" id=\"api-st\">\n      {% if rodando %}<span class=\"pr-st aviso\">sincronizando…</span>\n      {% elif cfg.status == 'ok' %}<span class=\"pr-st ok\">conectado</span>\n      {% elif cfg.status == 'erro' %}<span class=\"pr-st risco\">erro</span>\n      {% else %}<span class=\"pr-st neutro\">não configurado</span>{% endif %}\n      <small>{% if cfg.ultima_sync %}última: {{ data_br(cfg.ultima_sync[:10]) }} {{ cfg.ultima_sync[11:16] }}{% endif %}\n        {% if cfg.ativo and cfg.proxima_sync %} · próxima: {{ data_br(cfg.proxima_sync[:10]) }} {{ cfg.proxima_sync[11:16] }}{% endif %}</small>\n    </div>\n  </header>\n  {% if cfg.mensagem and cfg.mensagem.startswith('ADDON:') %}\n  <div class=\"api-addon\" id=\"api-msg\">\n    <b>A API do Omie ainda não está liberada nesta conta.</b>\n    <p>O Omie só permite que outros sistemas leiam os dados depois que o administrador da conta contrata o add-on\n      <b>“APIs Omie”</b> na Omie.Store (hoje R$ 49,90/mês por aplicativo, cobrado na mensalidade do Omie). Sem ele, qualquer integração recebe essa mesma recusa —\n      não é um problema da chave nem do nosso sistema.</p>\n    <p>Para conferir se já está contratado: no Omie, <i>Meus Aplicativos</i> → engrenagem do app → <i>Resumo do App</i> →\n      “Adicionais contratados na Omie.Store” deve mostrar <b>APIs Omie – Plano Padrão</b>.</p>\n    <a class=\"fin-link\" href=\"https://store.omie.com.br/apps/apis-omie\" target=\"_blank\" rel=\"noopener\">Abrir a página do add-on na Omie.Store ↗</a>\n  </div>\n  {% elif cfg.mensagem %}<p class=\"api-msg {{ 'erro' if cfg.status == 'erro' }}\" id=\"api-msg\">{{ cfg.mensagem }}</p>{% endif %}\n\n  <div class=\"api-grid\">\n    <section>\n      <div class=\"pe-sec\">Acesso <small>Omie → Configurações → Aplicativos (Desenvolvedor) → chave de integração</small></div>\n      <label class=\"lbl\">App Key</label>\n      <input class=\"inp mono\" name=\"app_key\" placeholder=\"{{ mascarar(cfg.app_key) if cfg.app_key else 'cole a App Key' }}\">\n      <label class=\"lbl\">App Secret</label>\n      <input class=\"inp mono\" name=\"app_secret\" type=\"password\" placeholder=\"{{ mascarar(cfg.app_secret) if cfg.app_secret else 'cole o App Secret' }}\">\n      <p class=\"co-dica\">Por segurança a chave não é mostrada depois de salva. Deixe em branco para manter a atual.</p>\n\n      <div class=\"pe-sec\">O que trazer</div>\n      <div class=\"fin-2col\">\n        <div><label class=\"lbl\">Histórico a partir de</label><input class=\"inp\" type=\"date\" name=\"data_inicial\" value=\"{{ cfg.data_inicial }}\"></div>\n        <div><label class=\"lbl\">Reprocessar nas atualizações</label>\n          <select class=\"inp\" name=\"janela_dias\" id=\"api-janela\">\n            <option value=\"0\" {{ 'selected' if not cfg.janela_dias }}>Manualmente (pelo botão)</option>\n            {% for n in [30, 60, 90, 180] %}<option value=\"{{ n }}\" {{ 'selected' if cfg.janela_dias == n }}>últimos {{ n }} dias</option>{% endfor %}</select></div>\n      </div>\n      <div class=\"api-rep\">\n        <div><label class=\"lbl\">Reprocessar de</label><input class=\"inp\" type=\"date\" name=\"rep_de\" value=\"{{ rep_de }}\"></div>\n        <div><label class=\"lbl\">até</label><input class=\"inp\" type=\"date\" name=\"rep_ate\" value=\"{{ hoje_iso }}\"></div>\n        <button class=\"btn-pill outline fin-btn\" name=\"acao\" value=\"reprocessar\" {{ 'disabled' if rodando or not cfg.app_key }}>{{ ic('autorenew') }} Reprocessar período</button>\n      </div>\n      <p class=\"co-dica\" id=\"api-janela-dica\">Em <b>Manualmente</b>, a atualização automática só traz a última semana; períodos antigos (alterações e\n        desconciliações feitas no Omie) entram quando você clicar em <b>Reprocessar período</b>.</p>\n      <label class=\"co-chk\"><input type=\"checkbox\" name=\"importar_clientes\" value=\"1\" {{ 'checked' if cfg.importar_clientes }}>\n        <span><b>Cadastro completo de clientes e fornecedores</b><small>Além dos que aparecem no extrato, traz e-mail, telefone e cidade.</small></span></label>\n      <label class=\"co-chk\"><input type=\"checkbox\" name=\"criar_contas\" value=\"1\" {{ 'checked' if cfg.criar_contas }}>\n        <span><b>Criar aqui as contas que ainda não existem</b><small>Contas do Omie sem ligação viram contas novas no ERP, com o saldo do Omie.</small></span></label>\n    </section>\n\n    <section>\n      <div class=\"pe-sec\">Atualização automática</div>\n      <label class=\"api-toggle\"><input type=\"checkbox\" name=\"ativo\" value=\"1\" {{ 'checked' if cfg.ativo }}>\n        <span class=\"api-sw\"></span><span><b>Atualizar sozinho</b><small>enquanto o app estiver aberto neste computador</small></span></label>\n      <label class=\"lbl\">A cada</label>\n      <select class=\"inp\" name=\"intervalo_horas\" style=\"max-width:220px\">{% for h in INTERVALOS %}<option value=\"{{ h }}\" {{ 'selected' if cfg.intervalo_horas == h }}>{{ h }} hora{{ 's' if h > 1 }}</option>{% endfor %}</select>\n\n      <div class=\"pe-sec\">Importado até agora</div>\n      <div class=\"vg-linhas\">\n        <div><span>Lançamentos conciliados</span><b>{{ (totais.n or 0) - (totais.transf or 0) }}</b></div>\n        <div><span>Transferências entre contas</span><b>{{ totais.transf or 0 }}</b></div>\n        <div><span>Histórico completo</span><b>{{ 'sim, desde ' ~ data_br(cfg.data_inicial) if cfg.carga_completa else 'ainda não' }}</b></div>\n      </div>\n    </section>\n  </div>\n\n  {% if contas_omie %}\n  <div class=\"pe-sec\">Ligação das contas <small>cada conta do Omie com a conta do ERP onde os movimentos vão entrar</small></div>\n  <table class=\"pr-tabela api-contas\">\n    <thead><tr><th>Conta no Omie</th><th>Banco · agência · conta</th><th>Conta no ERP</th></tr></thead>\n    <tbody>\n    {% for c in contas_omie %}\n      <tr class=\"{{ 'gt-inativo' if c.inativa }}\"><td><b>{{ c.nome }}</b>{% if c.inativa %} <small>(inativa no Omie)</small>{% endif %}</td>\n        <td class=\"mono\">{{ c.banco }} · {{ c.agencia }} · {{ c.numero }}</td>\n        <td><select class=\"inp\" name=\"conta_{{ c.id }}\">\n          <option value=\"\">{{ 'Criar conta nova automaticamente' if cfg.criar_contas else '— não ligar —' }}</option>\n          <option value=\"0\" {{ 'selected' if c.local_id == 0 }}>Não importar esta conta</option>\n          {% for x in contas %}<option value=\"{{ x.id }}\" {{ 'selected' if c.local_id == x.id }}>{{ x.nome }}</option>{% endfor %}\n        </select></td></tr>\n    {% endfor %}\n    </tbody>\n  </table>\n  <p class=\"co-dica\">Ao ligar a uma conta que já existe, o saldo inicial dela passa a ser o saldo do Omie no dia anterior ao início do histórico,\n    para o saldo final bater com o do Omie. Movimentos digitados à mão nessa conta continuam e podem duplicar.</p>\n  {% endif %}\n\n  <div class=\"api-acoes\">\n    <button class=\"btn-pill outline fin-btn\" name=\"acao\" value=\"testar\">{{ fic('conciliar') }} Testar conexão</button>\n    <button class=\"btn-pill outline fin-btn\" name=\"acao\" value=\"sincronizar\" {{ 'disabled' if rodando or not cfg.app_key }}>{{ ic('autorenew') }} Sincronizar agora</button>\n    <button class=\"btn-pill outline fin-btn\" name=\"acao\" value=\"completa\" {{ 'disabled' if rodando or not cfg.app_key }}\n      onclick=\"return confirm('Reprocessar todo o histórico desde {{ data_br(cfg.data_inicial) }}? Pode levar alguns minutos.')\">Reprocessar tudo</button>\n    <button class=\"btn-pill fin-btn\" name=\"acao\" value=\"salvar\">{{ ic('check') }} Salvar</button>\n  </div>\n</form>\n\n<section class=\"api-card fin-box api-web\" style=\"margin-top:1rem\">\n  <header class=\"api-head\">\n    <div class=\"api-logo\">Omie</div>\n    <div><h3>Omie pelo navegador <span class=\"pr-st ok\">sem custo</span></h3>\n      <small>Não precisa do add-on pago: um favorito lê a tela do Omie com o <b>seu</b> login e traz o que está conciliado para cá, com as mesmas regras da API (sem duplicar, atualiza o que mudou e remove o que foi desconciliado).</small></div>\n  </header>\n  <div class=\"api-grid\">\n    <section>\n      <div class=\"pe-sec\">1 · Instalar o favorito (uma vez só)</div>\n      <p class=\"co-dica\">Mostre a barra de favoritos do Chrome (<b>Ctrl+Shift+B</b>) e <b>arraste</b> o botão abaixo para ela.</p>\n      <a class=\"btn-pill fin-btn api-fav\" href=\"{{ favorito }}\" onclick=\"alert('Arraste este botão para a barra de favoritos e use-o dentro do Omie.'); return false;\">{{ ic('autorenew') }} Enviar ao ERP</a>\n    </section>\n    <section>\n      <div class=\"pe-sec\">2 · Sempre que quiser atualizar</div>\n      <ol class=\"api-passos\">\n        <li>No Omie (app <b>CAPUZZO NEGOCIOS</b>), abra <b>Finanças → Movimentação da Conta Corrente</b>.</li>\n        <li>Em Conta Corrente escolha <b>Todas as Contas Correntes</b>, informe o período e clique em <b>Atualizar</b>.</li>\n        <li>Clique no favorito <b>Enviar ao ERP</b>. Ele lê todas as páginas (aparece o andamento no canto da tela) e, no fim, clique em <b>Clique aqui para enviar ao ERP</b>.</li>\n      </ol>\n      <p class=\"co-dica\">Só o período lido é conferido: o que sumiu ou foi desconciliado nele é removido daqui; o resto não muda.\n        Você precisa estar logado no ERP neste mesmo navegador.</p>\n    </section>\n  </div>\n</section>\n\n<section class=\"vg-box\" style=\"margin-top:1rem\">\n  <header><h3>Histórico de sincronizações</h3><span>{{ logs|length }} mais recentes</span></header>\n  <table class=\"pr-tabela api-log\">\n    <thead><tr><th>Início</th><th>Origem</th><th>Situação</th><th>Resultado</th><th class=\"num\">Novos</th><th class=\"num\">Atualiz.</th><th class=\"num\">Removidos</th><th></th></tr></thead>\n    <tbody>\n    {% for l in logs %}{% set c = l.det.contagem or {} %}\n      <tr><td>{{ data_br(l.inicio[:10]) }} {{ l.inicio[11:16] }}</td><td>{{ l.origem }}</td>\n        <td>{% if l.status == 'ok' %}<span class=\"pr-st ok\">ok</span>{% elif l.status == 'erro' %}<span class=\"pr-st risco\">erro</span>{% else %}<span class=\"pr-st aviso\">{{ l.status }}</span>{% endif %}</td>\n        <td class=\"api-res\">{{ l.resumo }}</td><td class=\"num\">{{ c.novos or 0 }}</td><td class=\"num\">{{ c.atualizados or 0 }}</td><td class=\"num\">{{ c.removidos or 0 }}</td>\n        <td><details class=\"api-det\"><summary>detalhes</summary>\n          <div><b>Contagem:</b> {{ c.recebimentos or 0 }} recebimento(s), {{ c.pagamentos or 0 }} pagamento(s), {{ c.transferencias or 0 }} transferência(s),\n            {{ c.nao_conciliadas or 0 }} linha(s) não conciliada(s) ignorada(s), {{ c.categorias or 0 }} categoria(s), {{ c.clientes or 0 }} cadastro(s), {{ c.chamadas or 0 }} chamada(s) à API.</div>\n          {% for a in l.det.chamadas or [] %}<pre>{{ a.call or 'erro' }} {{ (a.param|tojson) if a.param }}\n{{ a.amostra or a.erro }}</pre>{% endfor %}\n        </details></td></tr>\n    {% else %}<tr><td colspan=\"8\" class=\"fin-vazio\">Nenhuma sincronização ainda.</td></tr>{% endfor %}\n    </tbody>\n  </table>\n</section>\n\n{% if rodando %}\n<script>\n(function () {\n  var t = setInterval(function () {\n    fetch('{{ url_for(\"financas.cad_integracoes_status\", slug=empresa.slug) }}', {credentials: 'same-origin'}).then(function (r) { return r.json(); }).then(function (j) {\n      var m = document.getElementById('api-msg'); if (m) m.textContent = j.mensagem || '';\n      if (!j.rodando && j.status !== 'rodando') { clearInterval(t); location.reload(); }\n    }).catch(function () {});\n  }, 4000);\n})();\n</script>\n{% endif %}\n{% endblock %}\n",
  "financas/cad_integracoes_web.html": "{% extends \"financas/_layout.html\" %}\n{% block fin_titulo %}Omie pelo navegador{% endblock %}\n{% block fin_conteudo %}\n<div class=\"fin-head\"><div><div class=\"eyebrow-line\">Cadastros · Integrações</div><h1>Dados recebidos do Omie</h1>\n  <p>O favorito leu a tela do Omie e trouxe os lançamentos conciliados para cá. A importação roda sozinha.</p></div>\n  <div><a class=\"btn-pill outline fin-btn\" href=\"{{ url_for('financas.cad_integracoes', slug=empresa.slug) }}\">{{ ic('arrow_back') }} Integrações</a></div></div>\n\n<section class=\"api-card fin-box\" id=\"ow\">\n  <div class=\"ow-passo\" id=\"ow-msg\"><span class=\"ow-spin\"></span> Lendo o pacote…</div>\n  <div class=\"vg-linhas\" id=\"ow-res\" hidden></div>\n  <p class=\"co-dica\" id=\"ow-dica\" hidden>Pode fechar esta aba: a importação continua. O resultado fica no histórico de sincronizações.</p>\n</section>\n\n<script>\n(function () {\n  var msg = document.getElementById('ow-msg'), res = document.getElementById('ow-res'), dica = document.getElementById('ow-dica');\n  var pacote = location.hash.slice(1);\n  function linha(r, v) { var d = document.createElement('div'); var s = document.createElement('span'); s.textContent = r; var b = document.createElement('b'); b.textContent = v; d.append(s, b); res.append(d); }\n  function texto(t, fim) { msg.innerHTML = fim ? '' : '<span class=\"ow-spin\"></span> '; msg.append(t); }\n  if (!pacote) { texto('Nenhum dado chegou. No Omie, abra Finanças → Movimentação da Conta Corrente e use o favorito “Enviar ao ERP”.', true); return; }\n  history.replaceState(null, '', location.pathname);          // tira o pacote do endereço (e do histórico)\n  var fd = new FormData(); fd.append('_csrf', '{{ csrf_token() }}'); fd.append('pacote', pacote);\n  fetch(location.pathname, {method: 'POST', body: fd, credentials: 'same-origin'}).then(function (r) { return r.json(); }).then(function (j) {\n    if (!j.ok) { texto(j.erro || 'Não foi possível importar.', true); return; }\n    res.hidden = false; dica.hidden = false;\n    linha('Empresa no Omie', j.empresa || '—'); linha('Período lido', (j.de || '?') + ' a ' + (j.ate || '?'));\n    linha('Contas', j.filtro || '—'); linha('Linhas conciliadas recebidas', j.linhas + ' de ' + (j.total || '?') + ' registros da tela');\n    if (j.saldo) linha('Saldo atual no Omie', 'R$ ' + j.saldo);\n    texto('Importando…');\n    var t = setInterval(function () {\n      fetch('{{ url_for(\"financas.cad_integracoes_status\", slug=empresa.slug) }}', {credentials: 'same-origin'}).then(function (r) { return r.json(); }).then(function (s) {\n        if (s.status === 'rodando' || s.rodando) { texto(s.mensagem || 'Importando…'); return; }\n        clearInterval(t); texto(s.mensagem || 'Concluído.', true);\n        var a = document.createElement('a'); a.className = 'btn-pill fin-btn'; a.style.marginTop = '.8rem'; a.textContent = 'Ver o resultado';\n        a.href = '{{ url_for(\"financas.cad_integracoes\", slug=empresa.slug) }}'; msg.after(a);\n      }).catch(function () {});\n    }, 2500);\n  }).catch(function (e) { texto('Falha ao enviar: ' + e, true); });\n})();\n</script>\n{% endblock %}\n",
  "financas/cad_pessoas.html": "{% extends \"financas/_layout.html\" %}\n{% block fin_titulo %}Clientes e fornecedores{% endblock %}\n{% block fin_conteudo %}\n<div class=\"fin-head\"><div><div class=\"eyebrow-line\">Cadastros</div><h1>Clientes e fornecedores</h1>\n  <p>Digite o CPF ou CNPJ e o sistema busca os dados. Os dados bancários serão usados nos arquivos de remessa (pagar e receber).</p></div>\n  <div class=\"fin-acoes\">\n    {% if pode_importar %}\n    <form method=\"post\" action=\"{{ url_for('financas.cad_pessoas_importar', slug=empresa.slug) }}\">\n      <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n      <button class=\"btn-pill outline fin-btn\" type=\"submit\" title=\"Copia nome, CPF, contato, endereço e dados bancários dos clientes do módulo Condomínios\">Trazer clientes dos Condomínios</button></form>\n    {% endif %}\n    <a class=\"btn-pill fin-btn\" href=\"{{ url_for('financas.cad_pessoas', slug=empresa.slug, tipo=tipo or None) }}#form-pessoa\">{{ fic('add') }} Novo cadastro</a>\n  </div>\n</div>\n\n<div class=\"pe-grid\">\n  <div>\n    <form class=\"fin-filtros\" method=\"get\">\n      <div class=\"chips\">\n        {% for k, rot in [('', 'Todos'), ('cliente', 'Clientes'), ('fornecedor', 'Fornecedores')] %}\n          <a class=\"chip {{ 'on' if tipo == k }}\" href=\"{{ url_for('financas.cad_pessoas', slug=empresa.slug, tipo=k or None, q=busca or None) }}\">{{ rot }}</a>{% endfor %}\n      </div>\n      <input type=\"hidden\" name=\"tipo\" value=\"{{ tipo }}\">\n      <label class=\"search\">{{ ic('search') }}<input type=\"search\" name=\"q\" value=\"{{ busca }}\" placeholder=\"Nome, CPF/CNPJ ou e-mail\"></label>\n    </form>\n    <div class=\"fin-tabela-wrap\">\n      <table class=\"fin-tabela\">\n        <thead><tr><th>Nome</th><th>Tipo</th><th>CPF/CNPJ</th><th>Contato</th><th>Banco</th></tr></thead>\n        <tbody>\n        {% for p in lista %}\n          <tr class=\"{{ 'inativa' if not p.ativo }} {{ 'pe-sel' if editar and editar.id == p.id }}\">\n            <td data-rot=\"Nome\" class=\"desc\"><a href=\"{{ url_for('financas.cad_pessoas', slug=empresa.slug, editar=p.id, tipo=tipo or None, q=busca or None) }}\"><b>{{ p.nome }}</b></a>\n              {% set extra = [p.nome_fantasia, (p.cidade ~ ('/' ~ p.uf if p.uf else '')) if p.cidade else '', {'condominios': 'Condomínios', 'supabase': 'Supabase'}.get(p.origem, '') if p.origem != 'local' else ''] | select | list %}\n              {% if extra %}<small>{{ extra | join(' · ') }}</small>{% endif %}</td>\n            <td data-rot=\"Tipo\">{{ TIPOS_PESSOA.get(p.tipo) }}</td>\n            <td data-rot=\"CPF/CNPJ\" class=\"dt\">{{ p.documento|doc_fmt if p.documento else '—' }}</td>\n            <td data-rot=\"Contato\" title=\"{{ p.email }} {{ p.telefone }}\">{{ p.email or p.telefone or '—' }}</td>\n            <td data-rot=\"Banco\">{% if p.banco_codigo or p.pix_chave %}<span class=\"fin-chip\" title=\"{{ p.banco_nome }} ag. {{ p.agencia }} cc {{ p.conta }}{{ '-' ~ p.conta_dv if p.conta_dv }}\">{{ p.banco_codigo or 'PIX' }}</span>{% else %}<span style=\"color:var(--muted)\">—</span>{% endif %}</td>\n          </tr>\n        {% else %}\n          <tr class=\"vazio\"><td colspan=\"5\">Nenhum cadastro encontrado.</td></tr>\n        {% endfor %}\n        </tbody>\n      </table>\n    </div>\n  </div>\n\n  {% set p = editar or {} %}\n  <section class=\"fin-box pe-form\" id=\"form-pessoa\">\n    <header><h3>{{ 'Editar: ' ~ p.nome if editar else 'Novo cadastro' }}</h3>{% if editar %}<a class=\"fin-link\" href=\"{{ url_for('financas.cad_pessoas', slug=empresa.slug, tipo=tipo or None) }}\">+ novo</a>{% endif %}</header>\n    <form method=\"post\" class=\"fin-form\" id=\"f-pessoa\" action=\"{{ url_for('financas.cad_pessoas', slug=empresa.slug, tipo=tipo or None) }}\" autocomplete=\"off\">\n      <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><input type=\"hidden\" name=\"id\" id=\"pe-id\" value=\"{{ p.id or '' }}\">\n\n      <div class=\"pe-sec\">Identificação</div>\n      <div class=\"pe-doc\">\n        <div><label class=\"lbl\">CPF / CNPJ</label>\n          <input class=\"inp\" name=\"documento\" id=\"pe-doc\" maxlength=\"18\" value=\"{{ p.documento|doc_fmt if p.documento else '' }}\" placeholder=\"Digite e o sistema busca os dados\" inputmode=\"numeric\"></div>\n        <button type=\"button\" class=\"btn-pill fin-btn mini\" id=\"pe-buscar\">{{ ic('search') }} Buscar</button>\n      </div>\n      <div class=\"pe-msg\" id=\"pe-msg\" hidden></div>\n      <div class=\"fin-2col\">\n        <div><label class=\"lbl\">Tipo</label>\n          <select class=\"inp\" name=\"tipo\">{% for k, v in TIPOS_PESSOA.items() %}<option value=\"{{ k }}\" {{ 'selected' if (p.tipo or tipo or 'cliente') == k }}>{{ v }}</option>{% endfor %}</select></div>\n        <div><label class=\"lbl\">Situação na Receita</label><input class=\"inp\" name=\"situacao_receita\" data-campo=\"situacao\" value=\"{{ p.situacao_receita or '' }}\" readonly placeholder=\"preenchido pela consulta do CNPJ\"></div>\n      </div>\n      <label class=\"lbl\">Nome / razão social *</label><input class=\"inp\" name=\"nome\" data-campo=\"nome\" required maxlength=\"160\" value=\"{{ p.nome or request.args.get('nome', '') }}\">\n      <label class=\"lbl\">Nome fantasia</label><input class=\"inp\" name=\"nome_fantasia\" data-campo=\"nome_fantasia\" maxlength=\"160\" value=\"{{ p.nome_fantasia or '' }}\">\n      <input type=\"hidden\" name=\"atividade\" data-campo=\"atividade\" value=\"{{ p.atividade or '' }}\">\n      <div class=\"pe-ativ\" id=\"pe-ativ\" {{ 'hidden' if not p.atividade }}>{{ p.atividade }}</div>\n\n      <div class=\"pe-sec\">Contato</div>\n      <div class=\"fin-2col\">\n        <div><label class=\"lbl\">E-mail</label><input class=\"inp\" type=\"email\" name=\"email\" data-campo=\"email\" maxlength=\"160\" value=\"{{ p.email or '' }}\"></div>\n        <div><label class=\"lbl\">Telefone</label><input class=\"inp\" name=\"telefone\" data-campo=\"telefone\" maxlength=\"40\" value=\"{{ p.telefone or '' }}\"></div>\n      </div>\n\n      <div class=\"pe-sec\">Endereço</div>\n      <div class=\"pe-3col\">\n        <div><label class=\"lbl\">CEP</label><input class=\"inp\" name=\"cep\" id=\"pe-cep\" data-campo=\"cep\" maxlength=\"9\" inputmode=\"numeric\" value=\"{{ p.cep or '' }}\"></div>\n        <div style=\"grid-column:span 2\"><label class=\"lbl\">Logradouro</label><input class=\"inp\" name=\"logradouro\" data-campo=\"logradouro\" maxlength=\"160\" value=\"{{ p.logradouro or '' }}\"></div>\n      </div>\n      <div class=\"pe-3col\">\n        <div><label class=\"lbl\">Número</label><input class=\"inp\" name=\"numero\" data-campo=\"numero\" maxlength=\"20\" value=\"{{ p.numero or '' }}\"></div>\n        <div style=\"grid-column:span 2\"><label class=\"lbl\">Complemento</label><input class=\"inp\" name=\"complemento\" data-campo=\"complemento\" maxlength=\"80\" value=\"{{ p.complemento or '' }}\"></div>\n      </div>\n      <div class=\"pe-3col\">\n        <div><label class=\"lbl\">Bairro</label><input class=\"inp\" name=\"bairro\" data-campo=\"bairro\" maxlength=\"80\" value=\"{{ p.bairro or '' }}\"></div>\n        <div><label class=\"lbl\">Cidade</label><input class=\"inp\" name=\"cidade\" data-campo=\"cidade\" maxlength=\"80\" value=\"{{ p.cidade or '' }}\"></div>\n        <div><label class=\"lbl\">UF</label><input class=\"inp\" name=\"uf\" data-campo=\"uf\" maxlength=\"2\" style=\"text-transform:uppercase\" value=\"{{ p.uf or '' }}\"></div>\n      </div>\n\n      <div class=\"pe-sec\">Dados bancários <small>para remessas de pagamento e cobrança</small></div>\n      <label class=\"lbl\">Banco</label>\n      <input class=\"inp\" name=\"banco_codigo\" id=\"pe-banco\" data-campo=\"banco_codigo\" list=\"pe-bancos\" maxlength=\"60\"\n             value=\"{{ (p.banco_codigo ~ ' - ' ~ p.banco_nome) if p.banco_codigo else '' }}\" placeholder=\"Código ou nome — ex.: 341 - Itaú Unibanco\">\n      <datalist id=\"pe-bancos\">{% for c, n in BANCOS %}<option value=\"{{ c }} - {{ n }}\">{% endfor %}</datalist>\n      <input type=\"hidden\" name=\"banco_nome\" data-campo=\"banco_nome\" value=\"{{ p.banco_nome or '' }}\">\n      <div class=\"pe-banco\">\n        <div><label class=\"lbl\">Agência</label><input class=\"inp\" name=\"agencia\" data-campo=\"agencia\" maxlength=\"6\" inputmode=\"numeric\" value=\"{{ p.agencia or '' }}\"></div>\n        <div><label class=\"lbl\">Dígito</label><input class=\"inp\" name=\"agencia_dv\" data-campo=\"agencia_dv\" maxlength=\"2\" value=\"{{ p.agencia_dv or '' }}\"></div>\n        <div><label class=\"lbl\">Conta</label><input class=\"inp\" name=\"conta\" data-campo=\"conta\" maxlength=\"15\" inputmode=\"numeric\" value=\"{{ p.conta or '' }}\"></div>\n        <div><label class=\"lbl\">Dígito</label><input class=\"inp\" name=\"conta_dv\" data-campo=\"conta_dv\" maxlength=\"2\" value=\"{{ p.conta_dv or '' }}\"></div>\n      </div>\n      <div class=\"fin-2col\">\n        <div><label class=\"lbl\">Tipo de conta</label>\n          <select class=\"inp\" name=\"conta_tipo\" data-campo=\"conta_tipo\"><option value=\"\">—</option>{% for k, v in CONTA_TIPOS.items() %}<option value=\"{{ k }}\" {{ 'selected' if p.conta_tipo == k }}>{{ v }}</option>{% endfor %}</select></div>\n        <div><label class=\"lbl\">CPF/CNPJ do titular</label><input class=\"inp\" name=\"titular_documento\" data-campo=\"titular_documento\" maxlength=\"18\" value=\"{{ p.titular_documento|doc_fmt if p.titular_documento else '' }}\" placeholder=\"vazio = o próprio cadastro\"></div>\n      </div>\n      <label class=\"lbl\">Titular da conta</label><input class=\"inp\" name=\"titular_nome\" data-campo=\"titular_nome\" maxlength=\"160\" value=\"{{ p.titular_nome or '' }}\" placeholder=\"vazio = o próprio cadastro\">\n      <div class=\"fin-2col\">\n        <div><label class=\"lbl\">Tipo da chave PIX</label>\n          <select class=\"inp\" name=\"pix_tipo\" id=\"pe-pixtipo\" data-campo=\"pix_tipo\"><option value=\"\">—</option>{% for k, v in PIX_TIPOS.items() %}<option value=\"{{ k }}\" {{ 'selected' if p.pix_tipo == k }}>{{ v }}</option>{% endfor %}</select></div>\n        <div><label class=\"lbl\">Chave PIX</label><input class=\"inp\" name=\"pix_chave\" id=\"pe-pix\" data-campo=\"pix_chave\" maxlength=\"120\" value=\"{{ p.pix_chave or '' }}\"></div>\n      </div>\n\n      <div class=\"pe-sec\">Outros</div>\n      <label class=\"lbl\">Observações</label><textarea class=\"inp\" name=\"obs\" rows=\"2\">{{ p.obs or '' }}</textarea>\n      {% if editar %}<label class=\"fin-check\"><input type=\"hidden\" name=\"ativo\" value=\"0\"><input type=\"checkbox\" name=\"ativo\" value=\"1\" {{ 'checked' if p.ativo }}> Cadastro ativo</label>{% endif %}\n      <button class=\"btn-pill fin-btn\" type=\"submit\" style=\"margin-top:.6rem\">Salvar</button>\n    </form>\n  </section>\n</div>\n{% endblock %}\n\n{% block fin_scripts %}\n<script>\n(function () {\n  var f = document.getElementById('f-pessoa'), doc = document.getElementById('pe-doc'), msg = document.getElementById('pe-msg');\n  var novo = !document.getElementById('pe-id').value, ultimo = '';\n  function dig(s) { return (s || '').replace(/\\D/g, ''); }\n  function mascaraDoc(el) {\n    var d = dig(el.value).slice(0, 14);\n    el.value = d.length <= 11\n      ? d.replace(/(\\d{3})(\\d)/, '$1.$2').replace(/(\\d{3})(\\d)/, '$1.$2').replace(/(\\d{3})(\\d{1,2})$/, '$1-$2')\n      : d.replace(/^(\\d{2})(\\d)/, '$1.$2').replace(/^(\\d{2})\\.(\\d{3})(\\d)/, '$1.$2.$3').replace(/\\.(\\d{3})(\\d)/, '.$1/$2').replace(/(\\d{4})(\\d)/, '$1-$2');\n  }\n  function aviso(t, tipo, html) { msg.hidden = false; msg.className = 'pe-msg ' + (tipo || ''); msg[html ? 'innerHTML' : 'textContent'] = t; }\n  function preencher(dados, sobrescrever) {\n    var n = 0;\n    Object.keys(dados).forEach(function (k) {\n      var v = dados[k]; if (!v) return;\n      var el = f.querySelector('[data-campo=\"' + k + '\"]'); if (!el) return;\n      if (k === 'banco_codigo') { v = v + (dados.banco_nome ? ' - ' + dados.banco_nome : ''); }\n      if (sobrescrever || !el.value) { el.value = v; el.classList.add('pe-auto'); n++; }\n    });\n    var at = document.getElementById('pe-ativ'); if (dados.atividade) { at.hidden = false; at.textContent = dados.atividade; }\n    return n;\n  }\n  function buscar() {\n    var d = dig(doc.value);\n    if (d.length !== 11 && d.length !== 14) return;\n    if (d === ultimo) return; ultimo = d;\n    aviso(d.length === 14 ? 'Consultando a Receita Federal…' : 'Verificando CPF…', 'carregando');\n    fetch('{{ url_for(\"financas.cad_pessoas_consulta\", slug=empresa.slug) }}?doc=' + d + '&id=' + (document.getElementById('pe-id').value || 0),\n          {credentials: 'same-origin'}).then(function (r) { return r.json(); }).then(function (j) {\n      if (j.ja_cadastrado) {\n        aviso('Este documento já está cadastrado: <a href=\"' + j.ja_cadastrado.url + '\">' + j.ja_cadastrado.nome + ' — abrir</a>', 'erro', true);\n        return;\n      }\n      if (!j.ok) { aviso(j.msg, 'erro'); return; }\n      if (j.cpf_sem_dados) { aviso(j.msg, ''); return; }\n      var n = preencher(j.dados || {}, novo);\n      var sit = (j.dados || {}).situacao;\n      aviso('✓ ' + n + ' campo(s) preenchido(s) com dados de ' + j.fonte + '.' + (sit && sit !== 'ATIVA' ? ' Atenção: situação ' + sit + '.' : '')\n            + (j.aviso ? ' (' + j.aviso + ')' : '') + (!novo ? ' Campos já preenchidos foram mantidos.' : ''), sit && sit !== 'ATIVA' ? 'erro' : 'ok');\n    }).catch(function () { ultimo = ''; aviso('Falha na consulta. Verifique a internet e tente de novo.', 'erro'); });\n  }\n  doc.addEventListener('input', function () { mascaraDoc(doc); var d = dig(doc.value); if (d.length === 14 || (d.length === 11 && novo)) buscar(); });\n  doc.addEventListener('blur', buscar);\n  document.getElementById('pe-buscar').addEventListener('click', function () { ultimo = ''; buscar(); });\n\n  // CEP → endereço (ViaCEP)\n  var cep = document.getElementById('pe-cep');\n  cep.addEventListener('input', function () { var d = dig(cep.value).slice(0, 8); cep.value = d.length > 5 ? d.slice(0, 5) + '-' + d.slice(5) : d; });\n  cep.addEventListener('blur', function () {\n    var d = dig(cep.value); if (d.length !== 8) return;\n    fetch('https://viacep.com.br/ws/' + d + '/json/').then(function (r) { return r.json(); }).then(function (j) {\n      if (j.erro) return;\n      preencher({logradouro: j.logradouro, bairro: j.bairro, cidade: j.localidade, uf: j.uf}, false);\n    }).catch(function () {});\n  });\n\n  // Banco: guarda só o código; mostra \"341 - Itaú\"\n  var banco = document.getElementById('pe-banco');\n  banco.addEventListener('change', function () { var m = banco.value.match(/^\\s*(\\d{1,3})\\s*(?:-\\s*(.*))?$/);\n    if (m) f.querySelector('[name=banco_nome]').value = m[2] || ''; });\n  f.addEventListener('submit', function () { var m = banco.value.match(/^\\s*(\\d{1,3})/); banco.value = m ? m[1] : ''; });\n\n  // Tipo da chave PIX pelo formato\n  var pix = document.getElementById('pe-pix'), pt = document.getElementById('pe-pixtipo');\n  pix.addEventListener('blur', function () {\n    if (pt.value || !pix.value) return; var v = pix.value.trim(), d = dig(v);\n    pt.value = v.indexOf('@') > 0 ? 'email' : (/^[0-9a-f-]{32,36}$/i.test(v) ? 'aleatoria' : (d.length === 14 || (d.length === 11 && !/^\\(?\\d{2}\\)?\\s?9/.test(v)) ? 'cpf_cnpj' : (d.length >= 10 ? 'telefone' : '')));\n  });\n  {% if editar %}document.getElementById('form-pessoa').scrollIntoView({block: 'nearest'});{% endif %}\n})();\n</script>\n{% endblock %}\n",
  "financas/cap/_apur_cliente.html": "{# Tabela \"consolidado por cliente\" com detalhe das cotas — usada na apuração nova e no detalhe #}\n<div style=\"overflow-x:auto\">\n<table class=\"pr-tabela ap-tab\">\n  <thead><tr>{% if conferir %}<th title=\"Marque conforme confere no banco\">✓</th>{% endif %}<th>#</th><th>Cotista</th><th>CPF/CNPJ</th><th>Pix</th><th>Produto</th>\n    <th class=\"num\">Cotas</th><th class=\"num\">Capital</th><th class=\"num\">Rendimento</th><th></th></tr></thead>\n  <tbody>\n  {% for cli in clientes %}\n    <tr class=\"ap-cli\" id=\"ap-l{{ loop.index0 }}\">\n      {% if conferir %}<td><input type=\"checkbox\" class=\"ap-conf\" data-k=\"{{ cli.client_id }}-{{ cli.condominium_code }}\"></td>{% endif %}\n      <td class=\"ap-i\">{{ loop.index }}</td>\n      <td><a href=\"{{ url_for('financas.cond_cotista', slug=empresa.slug, cid=cli.client_id) }}\"><b>{{ cli.client_name }}</b></a></td>\n      <td class=\"mono\">{{ cli.client_cpf }}</td>\n      <td class=\"ap-pix\">{{ cli.client_pix or '—' }}</td>\n      <td><span class=\"ap-prod\" style=\"--c:{{ COND_CORES.get(cli.condominium_code) }}\">{{ COND_NOMES.get(cli.condominium_code, cli.condominium_code) }}</span></td>\n      <td class=\"num\">{{ cli.active_shares_count if cli.active_shares_count is defined else cli.shares_count }}{% if cli.withdrawn_count %}<small class=\"ap-ret\">+{{ cli.withdrawn_count }} retirada(s)</small>{% endif %}</td>\n      <td class=\"num\">{{ reais(cli.total_share_value) }}{% if cli.withdrawn_count %}<small class=\"ap-ret\">− {{ reais(cli.total_withdrawn_value) }} retirado</small>{% endif %}</td>\n      <td class=\"num\"><b>{{ reais(cli.total_income) }}</b></td>\n      <td class=\"num\"><button type=\"button\" class=\"ap-ver\" data-i=\"{{ loop.index0 }}\">cotas ▾</button></td>\n    </tr>\n    <tr class=\"ap-det\" id=\"ap-d{{ loop.index0 }}\" hidden><td colspan=\"{{ 10 if conferir else 9 }}\">\n      <table class=\"ap-sub\">\n        <thead><tr><th>Cota</th><th class=\"num\">Valor</th><th>Aquisição</th><th>Vencimento</th><th>Últ. renovação</th><th>Período</th><th class=\"num\">Dias</th><th class=\"num\">Taxa</th><th class=\"num\">Rendimento</th><th>Tipo</th></tr></thead>\n        <tbody>\n        {% for it in cli.shares_detail %}\n          {% set ct = it.calc_type or it.calculation_details or '' %}\n          <tr><td class=\"mono\">{{ it.share_number or '—' }}</td><td class=\"num\">{{ reais(it.share_value) }}</td>\n            <td>{{ data_br(it.acquisition_date) if it.acquisition_date else '—' }}</td><td>{{ data_br(it.maturity_date) if it.maturity_date else '—' }}</td>\n            <td>{{ data_br(it.last_renewal_date) if it.last_renewal_date else '—' }}</td>\n            <td class=\"ap-per\">{{ data_br(it.period_start) }} → {{ data_br(it.period_end) }}</td>\n            <td class=\"num\">{{ it.active_days }}/{{ it.total_period_days }}</td><td class=\"num\">{{ '%.2f'|format(it.applied_rate * 100) }}%</td>\n            <td class=\"num\"><b>{{ reais(it.income_value) }}</b></td>\n            <td>{% if 'RETIRADA em' in ct or 'até retirada' in ct %}<span class=\"ap-t ret\" title=\"{{ it.calculation_details }}\">Proporc. até retirada</span>\n              {% elif 'Especial' in ct %}<span class=\"ap-t esp\">Especial Agro</span>\n              {% elif it.active_days == it.total_period_days %}<span class=\"ap-t int\">Integral</span>\n              {% else %}<span class=\"ap-t prop\" title=\"{{ it.calculation_details }}\">Proporcional</span>{% endif %}</td></tr>\n        {% endfor %}\n        </tbody>\n      </table>\n    </td></tr>\n  {% endfor %}\n  </tbody>\n  <tfoot><tr>{% if conferir %}<td></td>{% endif %}<td colspan=\"6\"><b>Total geral</b> · {{ clientes|length }} cotista(s)</td>\n    <td class=\"num\"><b>{{ reais(clientes|sum(attribute='total_share_value')) }}</b></td>\n    <td class=\"num\"><b>{{ reais(clientes|sum(attribute='total_income')) }}</b></td><td></td></tr></tfoot>\n</table>\n</div>\n<script>\ndocument.querySelectorAll('.ap-ver').forEach(function (b) {\n  b.addEventListener('click', function () { var r = document.getElementById('ap-d' + b.dataset.i); r.hidden = !r.hidden; b.textContent = r.hidden ? 'cotas ▾' : 'ocultar ▴'; });\n});\n</script>\n",
  "financas/cap/_macros.html": "{% macro cabecalho(titulo, sub, eyebrow='Condomínios de Investimento') %}\n<div class=\"fin-head\">\n  <div>\n    <div class=\"eyebrow-line\">{{ eyebrow }}</div>\n    <h1>{{ titulo }}</h1>\n    {% if sub %}<p>{{ sub }}</p>{% endif %}\n  </div>\n  <div class=\"fin-acoes\">{{ caller() if caller }}</div>\n</div>\n{% endmacro %}\n\n{% macro aviso_modulo() %}{% endmacro %}\n\n{% macro status_cota(s) %}<span class=\"pr-st {{ s }}\">{{ {'ativa':'Ativa','pendente':'Pendente','inativa':'Inativa'}.get(s, s) }}</span>{% endmacro %}\n\n{% macro financeiro(fin, produto, empresa) %}\n<section class=\"vg-box\">\n  <header><h3>{{ fic('centro') }} Financeiro do produto</h3>\n    <a href=\"{{ url_for('financas.lancamentos', slug=empresa.slug, tipo='receber') }}\">Lançamentos</a></header>\n  <div class=\"vg-linhas\">\n    <div><span>Receitas recebidas no mês</span><b style=\"color:var(--fin-pos)\">{{ moeda(fin.receitas_mes) }}</b></div>\n    <div><span>Despesas pagas no mês</span><b style=\"color:var(--fin-neg)\">{{ moeda(fin.despesas_mes) }}</b></div>\n    <div><span>A receber em aberto</span><b>{{ moeda(fin.a_receber) }}</b></div>\n    <div><span>A pagar em aberto</span><b>{{ moeda(fin.a_pagar) }}</b></div>\n  </div>\n  <p class=\"fin-sub\">Lance receitas e despesas com o centro de custo <b>{{ produto }}</b> para que apareçam aqui.</p>\n</section>\n{% endmacro %}\n",
  "financas/cap/cond_apuracao.html": "{% extends \"financas/_layout.html\" %}\n{% import \"financas/cap/_macros.html\" as m with context %}\n{% block fin_titulo %}Apurações{% endblock %}\n{% block fin_conteudo %}\n{% call m.cabecalho('Apurações de rendimentos', 'Histórico mensal dos rendimentos calculados para os cotistas.') %}\n  <a class=\"btn-pill fin-btn\" href=\"{{ url_for('financas.cond_apuracao_nova', slug=empresa.slug) }}\">{{ fic('calculo') }} Nova apuração</a>\n{% endcall %}\n{% set mx = (meses|map(attribute='total')|max) if meses else 1 %}\n<section class=\"vg-box\" style=\"margin-bottom:1rem\">\n  <header><h3>Rendimentos por mês</h3></header>\n  {% for mm in meses[:12]|reverse %}\n    <div style=\"display:grid;grid-template-columns:70px 1fr 130px;gap:.7rem;align-items:center;margin:.35rem 0;font-size:.85rem\">\n      <span>{{ '%02d/%d'|format(mm.mes, mm.ano) }}</span>\n      <span class=\"pr-barra-h\" style=\"margin:0\">{% for a in mm.itens %}<i title=\"{{ COND_NOMES.get(a.code, '') }} {{ reais(a.total) }}\" style=\"width:{{ 100 * a.total / (mx or 1) }}%;background:{{ COND_CORES.get(a.code, '#888') }}\"></i>{% endfor %}</span>\n      <b style=\"text-align:right\">{{ reais(mm.total) }}</b>\n    </div>\n  {% else %}<p class=\"fin-vazio\">Nenhuma apuração registrada.</p>{% endfor %}\n  <div class=\"pr-leg\" style=\"margin-top:.6rem\">{% for k, n in COND_NOMES.items() %}<span style=\"--c:{{ COND_CORES[k] }}\">{{ n }}</span>{% endfor %}</div>\n</section>\n<section class=\"vg-box\">\n  <header><h3>Apurações registradas</h3></header>\n  <table class=\"pr-tabela\">\n    <thead><tr><th>Mês</th><th>Produto</th><th class=\"num\">Cotas</th><th class=\"num\">Cotistas</th><th class=\"num\">Rendimentos</th><th>Calculada em</th><th></th></tr></thead>\n    <tbody>\n    {% for mm in meses %}{% for a in mm.itens %}\n      <tr class=\"clic\" onclick=\"location.href='{{ url_for('financas.cond_apuracao_detalhe', slug=empresa.slug, calc_id=a.id) }}'\"><td>{{ '%02d/%d'|format(a.calculation_month, a.calculation_year) }}</td><td>{{ COND_NOMES.get(a.code, 'Todos') }}</td>\n        <td class=\"num\">{{ a.itens }}</td><td class=\"num\">{{ a.clientes }}</td><td class=\"num\"><b>{{ reais(a.total) }}</b></td>\n        <td>{{ data_br(a.calculated_at[:10]) }} {{ a.calculated_at[11:16] }}</td><td class=\"num\"><a class=\"fin-link\" href=\"{{ url_for('financas.cond_apuracao_detalhe', slug=empresa.slug, calc_id=a.id) }}\">detalhe</a></td></tr>\n    {% endfor %}{% endfor %}\n    </tbody>\n  </table>\n</section>\n{% endblock %}\n",
  "financas/cap/cond_apuracao_detalhe.html": "{% extends \"financas/_layout.html\" %}\n{% import \"financas/cap/_macros.html\" as m with context %}\n{% block fin_titulo %}Apuração {{ '%02d'|format(meta.calculation_month) }}/{{ meta.calculation_year }}{% endblock %}\n{% block fin_conteudo %}\n{% call m.cabecalho('Apuração ' ~ MESES[meta.calculation_month] ~ '/' ~ meta.calculation_year ~ ' · ' ~ (meta.condominium_name or 'Todos os produtos'),\n                    'Salva em ' ~ data_br(meta.calculated_at[:10]) ~ ' ' ~ meta.calculated_at[11:16] ~ ((' · ' ~ meta.notes) if meta.notes else '')) %}\n  <a class=\"btn-pill outline fin-btn\" href=\"{{ url_for('financas.cond_apuracao', slug=empresa.slug) }}\">{{ ic('arrow_back') }} Histórico</a>\n  <a class=\"btn-pill fin-btn\" href=\"{{ url_for('financas.cond_apuracao_exportar', slug=empresa.slug, calc_id=calc_id) }}\" title=\"Excel no padrão da planilha de controle\">{{ ic('table_view') }} Exportar Excel</a>\n  <a class=\"btn-pill outline fin-btn\" href=\"{{ url_for('financas.cond_apuracao_editar', slug=empresa.slug, calc_id=calc_id) }}\">{{ fic('edit') }} Editar</a>\n  <form method=\"post\" action=\"{{ url_for('financas.cond_apuracao_excluir', slug=empresa.slug, calc_id=calc_id) }}\" onsubmit=\"return confirm('Excluir esta apuração? Cotas e cotistas não são alterados.')\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><button class=\"btn-pill outline fin-btn co-perigo-t\">{{ ic('delete') }} Excluir</button></form>\n{% endcall %}\n\n<div class=\"vg-kpis\">\n  <div class=\"vg-kpi escuro\"><small>Total apurado</small><b>{{ reais(total_geral) }}</b><em>{{ meta.condominium_name or 'Todos os produtos' }}</em></div>\n  <div class=\"vg-kpi\"><small>Cotistas</small><b>{{ clients|length }}</b></div>\n  <div class=\"vg-kpi\"><small>Cotas</small><b>{{ total_cotas }}</b></div>\n  <div class=\"vg-kpi\"><small>Capital</small><b>{{ reais(clients|sum(attribute='total_share_value')) }}</b></div>\n</div>\n\n<section class=\"vg-box\" style=\"margin-bottom:1rem\">\n  <header><h3>{{ ic('account_balance') }} Arquivo bancário</h3><span>{{ bank.bank_name or 'Banco não definido' }} · {{ {'pix': 'Pix — CNAB240', 'dados_bancarios': 'Dados bancários — CNAB240'}.get(bank.method, 'layout pendente') }}</span></header>\n  {% if bank.method in ('pix', 'dados_bancarios') %}\n  <div class=\"ap-banco\">\n    <div><label class=\"lbl\">Data de pagamento</label><input class=\"inp\" type=\"date\" id=\"bk-data\" value=\"{{ data_sug or '' }}\"></div>\n    <button type=\"button\" class=\"btn-pill outline fin-btn\" id=\"bk-validar\">{{ ic('fact_check') }} Validar pagamentos</button>\n    <button type=\"button\" class=\"btn-pill fin-btn\" id=\"bk-gerar\">{{ ic('account_balance') }} Gerar arquivo do banco</button>\n  </div>\n  <div class=\"ap-valid\" id=\"bk-res\" hidden></div>\n  <form id=\"bk-form\" method=\"post\" action=\"{{ url_for('financas.cond_apuracao_banco_gerar', slug=empresa.slug, calc_id=calc_id) }}\" hidden>\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><input type=\"hidden\" name=\"payment_date\" id=\"bk-data-h\"></form>\n  {% else %}\n  <p class=\"fin-sub\">Banco pagador não configurado para este condomínio (apuração com todos os produtos não gera arquivo — faça uma por produto).</p>\n  {% endif %}\n  {% if remessas %}\n  <table class=\"pr-tabela\" style=\"margin-top:.8rem\">\n    <thead><tr><th>Arquivo</th><th>Gerado em</th><th class=\"num\">Valor</th><th class=\"num\">Pagamentos</th><th>Situação</th><th></th></tr></thead>\n    <tbody>{% for rf in remessas %}\n      <tr><td class=\"mono\">{{ rf.file_name }}</td><td>{{ rf.created_at }}</td><td class=\"num\">{{ reais(rf.total_amount) }}</td><td class=\"num\">{{ rf.total_payments }}</td>\n        <td>{{ {'generated': 'Gerado', 'imported_to_bank': 'Importado no banco', 'cancelled': 'Cancelado'}.get(rf.status, 'Erro') }}</td>\n        <td class=\"num\"><a class=\"fin-link\" href=\"{{ url_for('financas.cond_apuracao_banco_baixar', slug=empresa.slug, calc_id=calc_id, rid=rf.id, tipo='rem') }}\">.REM</a> ·\n          <a class=\"fin-link\" href=\"{{ url_for('financas.cond_apuracao_banco_baixar', slug=empresa.slug, calc_id=calc_id, rid=rf.id, tipo='csv') }}\">conferência</a></td></tr>\n    {% endfor %}</tbody>\n  </table>\n  {% endif %}\n</section>\n\n<section class=\"vg-box\">\n  <header><h3>Consolidado por cotista</h3><span>Marque ✓ conforme confere no banco (fica salvo neste navegador)</span></header>\n  {% with clientes = clients, conferir = true %}{% include \"financas/cap/_apur_cliente.html\" %}{% endwith %}\n</section>\n\n<script>\n(function () {\n  // conferência por pessoa (só no navegador)\n  var K = 'confer_apuracao_{{ calc_id }}', mapa = {};\n  try { mapa = JSON.parse(localStorage.getItem(K) || '{}'); } catch (e) {}\n  document.querySelectorAll('.ap-conf').forEach(function (c) {\n    var tr = c.closest('tr'); c.checked = !!mapa[c.dataset.k]; tr.classList.toggle('ok', c.checked);\n    c.addEventListener('change', function () { if (c.checked) mapa[c.dataset.k] = true; else delete mapa[c.dataset.k]; tr.classList.toggle('ok', c.checked); try { localStorage.setItem(K, JSON.stringify(mapa)); } catch (e) {} });\n  });\n  var res = document.getElementById('bk-res'); if (!res) return;\n  var ult = null;\n  function lista(t, a) { return a && a.length ? '<li><b>' + t + ' (' + a.length + '):</b> ' + a.join(', ') + '</li>' : ''; }\n  document.getElementById('bk-validar').addEventListener('click', function () {\n    res.hidden = false; res.className = 'ap-valid'; res.textContent = 'Validando…';\n    var fd = new FormData(); fd.append('_csrf', '{{ csrf_token() }}');\n    fetch('{{ url_for(\"financas.cond_apuracao_banco_validar\", slug=empresa.slug, calc_id=calc_id) }}', {method: 'POST', body: fd, credentials: 'same-origin'})\n      .then(function (r) { return r.json(); }).then(function (j) {\n        if (!j.success) { res.className = 'ap-valid erro'; res.textContent = j.message || 'Não foi possível validar.'; return; }\n        ult = j;\n        res.className = 'ap-valid ' + (j.can_generate ? 'ok' : 'erro');\n        res.innerHTML = '<p><b>' + j.total_client_count + '</b> cotista(s) na apuração · <b class=\"pos\">' + j.valid_count + ' no arquivo</b> (' + j.total_amount + ') · <b class=\"neg\">' + j.pending_count + ' fora por pendência</b> (' + j.pending_total_amount + ')</p><ul>' +\n          lista('Sem nome', j.pending_no_name) + lista('Sem CPF/CNPJ', j.pending_no_document) + lista('CPF/CNPJ inválido', j.pending_invalid_document) +\n          lista('Sem chave Pix', j.pending_no_pix) + lista('Pix e-mail inválido', j.pending_invalid_pix_email) + lista('Dados bancários incompletos', j.pending_no_bank_data) +\n          lista('Valor zerado/negativo', j.pending_zero_amount) + '</ul>' +\n          (j.config_missing && j.config_missing.length ? '<p class=\"neg\">Configuração do banco incompleta: ' + j.config_missing.join(', ') + '.</p>' : '') +\n          (!j.can_generate ? '<p class=\"neg\"><b>Geração bloqueada.</b></p>' : (j.pending_count ? '<p>As pendências não bloqueiam: esses cotistas ficam fora do .REM e aparecem na conferência.</p>' : ''));\n      }).catch(function () { res.className = 'ap-valid erro'; res.textContent = 'Falha ao conectar para validar.'; });\n  });\n  document.getElementById('bk-gerar').addEventListener('click', function () {\n    var dt = document.getElementById('bk-data').value;\n    if (!dt) { alert('Informe a data de pagamento.'); return; }\n    if (!ult) { alert('Clique em \"Validar pagamentos\" antes de gerar o arquivo.'); return; }\n    if (!ult.can_generate) { alert('Geração bloqueada — veja o resultado da validação.'); return; }\n    if (!confirm('Gerar arquivo com ' + ult.valid_count + ' pagamento(s), total ' + ult.total_amount + '? ' + ult.pending_count + ' cotista(s) ficam fora por pendência.')) return;\n    document.getElementById('bk-data-h').value = dt; document.getElementById('bk-form').submit();\n  });\n})();\n</script>\n{% endblock %}\n",
  "financas/cap/cond_apuracao_editar.html": "{% extends \"financas/_layout.html\" %}\n{% import \"financas/cap/_macros.html\" as m with context %}\n{% set h = det.header %}\n{% block fin_titulo %}Editar apuração{% endblock %}\n{% block fin_conteudo %}\n{% call m.cabecalho('Editar apuração ' ~ MESES[h.calculation_month] ~ '/' ~ h.calculation_year, 'Ajuste valores linha a linha. O total é recalculado ao salvar e a alteração fica no log de auditoria.') %}\n  <a class=\"btn-pill outline fin-btn\" href=\"{{ url_for('financas.cond_apuracao_detalhe', slug=empresa.slug, calc_id=calc_id) }}\">{{ ic('arrow_back') }} Voltar</a>\n{% endcall %}\n{% if erro %}<div class=\"flash flash-error\" style=\"margin-bottom:.8rem\">{{ erro }}</div>{% endif %}\n<form method=\"post\" class=\"fin-form\" id=\"f-ed\">\n  <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n  <section class=\"vg-box\">\n    <label class=\"lbl\">Observação da apuração</label><input class=\"inp\" name=\"notes\" value=\"{{ h.notes or '' }}\">\n    <div style=\"overflow-x:auto;margin-top:.8rem\">\n    <table class=\"pr-tabela ap-ed\">\n      <thead><tr><th>Cotista</th><th>Produto</th><th>Cota</th><th class=\"num\">Valor cota</th><th class=\"num\">Dias ativos</th><th class=\"num\">Dias período</th><th class=\"num\">Taxa</th><th class=\"num\">Rendimento</th><th>Detalhe do cálculo</th></tr></thead>\n      <tbody>\n      {% for it in det['items'] %}\n        <tr><td>{{ it.client_name }}</td><td>{{ COND_NOMES.get(it.condominium_code, '') }}</td><td class=\"mono\">{{ it.share_number }}</td>\n          <td><input class=\"inp num\" type=\"number\" step=\"0.01\" min=\"0\" name=\"sv_{{ it.id }}\" value=\"{{ '%.2f'|format(it.share_value) }}\"></td>\n          <td><input class=\"inp num\" type=\"number\" min=\"0\" name=\"ad_{{ it.id }}\" value=\"{{ it.active_days }}\"></td>\n          <td><input class=\"inp num\" type=\"number\" min=\"1\" name=\"tpd_{{ it.id }}\" value=\"{{ it.total_period_days }}\"></td>\n          <td><input class=\"inp num\" type=\"number\" step=\"0.00001\" min=\"0\" name=\"ar_{{ it.id }}\" value=\"{{ '%.5f'|format(it.applied_rate) }}\"></td>\n          <td><input class=\"inp num ap-iv\" type=\"number\" step=\"0.01\" min=\"0\" name=\"iv_{{ it.id }}\" value=\"{{ '%.2f'|format(it.income_value) }}\"></td>\n          <td><input class=\"inp\" name=\"cd_{{ it.id }}\" value=\"{{ it.calculation_details or '' }}\"></td></tr>\n      {% endfor %}\n      </tbody>\n      <tfoot><tr><td colspan=\"7\"><b>Total</b></td><td class=\"num\"><b id=\"ap-tot\"></b></td><td></td></tr></tfoot>\n    </table>\n    </div>\n  </section>\n  <div class=\"lf-barra co-barra\"><span class=\"co-barra-info\">{{ det['items']|length }} linha(s)</span>\n    <a class=\"btn-pill outline fin-btn\" href=\"{{ url_for('financas.cond_apuracao_detalhe', slug=empresa.slug, calc_id=calc_id) }}\">Cancelar</a>\n    <button class=\"btn-pill fin-btn\" type=\"submit\">{{ ic('check') }} Salvar</button></div>\n</form>\n<script>\n(function () { function t() { var s = 0; document.querySelectorAll('.ap-iv').forEach(function (i) { s += parseFloat(i.value) || 0; });\n  document.getElementById('ap-tot').textContent = 'R$ ' + s.toLocaleString('pt-BR', {minimumFractionDigits: 2, maximumFractionDigits: 2}); }\n  document.getElementById('f-ed').addEventListener('input', t); t(); })();\n</script>\n{% endblock %}\n",
  "financas/cap/cond_apuracao_nova.html": "{% extends \"financas/_layout.html\" %}\n{% import \"financas/cap/_macros.html\" as m with context %}\n{% block fin_titulo %}Nova apuração{% endblock %}\n{% block fin_conteudo %}\n{% call m.cabecalho('Apuração mensal', 'Calcule os rendimentos do mês, confira por cotista e salve no histórico.') %}\n  <a class=\"btn-pill outline fin-btn\" href=\"{{ url_for('financas.cond_apuracao', slug=empresa.slug) }}\">{{ ic('history') }} Histórico</a>\n{% endcall %}\n\n<form method=\"post\" class=\"fin-box fin-form ap-form\" id=\"f-apur\">\n  <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n  <div><label class=\"lbl\">Mês</label><select class=\"inp\" name=\"mes\">{% for i in range(1, 13) %}<option value=\"{{ i }}\" {{ 'selected' if mes == i }}>{{ MESES[i] }}</option>{% endfor %}</select></div>\n  <div><label class=\"lbl\">Ano</label><input class=\"inp\" type=\"number\" name=\"ano\" min=\"2020\" max=\"2099\" value=\"{{ ano }}\"></div>\n  <div><label class=\"lbl\">Produto</label><select class=\"inp\" name=\"produto\" id=\"ap-prod\">\n    <option value=\"\">Todos os produtos</option>{% for c in conds %}<option value=\"{{ c.code }}\" {{ 'selected' if prod == c.code }}>{{ c.name }}</option>{% endfor %}</select></div>\n  <div id=\"ap-agro\"><label class=\"lbl\">Taxa especial Agro (%) <small class=\"co-dica\">3,5 a 4,5 — só se houver cota vencendo</small></label>\n    <input class=\"inp\" name=\"agro_special_rate\" value=\"{{ agro_txt }}\" placeholder=\"Ex.: 4,0\"></div>\n  <div class=\"ap-btn\"><button class=\"btn-pill fin-btn\" type=\"submit\">{{ fic('calculo') }} Calcular</button></div>\n</form>\n\n{% if erro %}<div class=\"flash flash-error\" style=\"margin:.8rem 0\">{{ erro }}</div>{% endif %}\n\n{% if r %}\n<div class=\"vg-kpis\" style=\"margin-top:1rem\">\n  <div class=\"vg-kpi escuro\"><small>Total a pagar · {{ MESES[r.mes] }}/{{ r.ano }}</small><b>{{ reais(r.total_geral) }}</b><em>{{ COND_NOMES.get(r.produto, 'Todos os produtos') }}</em></div>\n  <div class=\"vg-kpi\"><small>Cotistas</small><b>{{ r.consolidado|length }}</b></div>\n  <div class=\"vg-kpi\"><small>Cotas</small><b>{{ r.qty_cotas }}</b></div>\n  <div class=\"vg-kpi\"><small>Capital</small><b>{{ reais(r.capital) }}</b></div>\n  {% for c, v in r.por_produto.items() %}<div class=\"vg-kpi\"><small>{{ COND_NOMES[c] }}</small><b>{{ reais(v) }}</b>{% if c == 'agro' and r.agro_rate %}<em>taxa especial {{ '%.2f'|format(r.agro_rate|float * 100) }}%</em>{% endif %}</div>{% endfor %}\n</div>\n\n{% if r.duplicata %}\n  <div class=\"flash flash-warning\" style=\"margin:.8rem 0\">Já existe apuração salva para {{ MESES[r.mes] }}/{{ r.ano }} — {{ COND_NOMES.get(r.produto, 'todos os produtos') }}.\n    <a href=\"{{ url_for('financas.cond_apuracao', slug=empresa.slug) }}\">Abrir o histórico</a> (para refazer, exclua a anterior).</div>\n{% else %}\n  <form method=\"post\" action=\"{{ url_for('financas.cond_apuracao_salvar', slug=empresa.slug) }}\" class=\"ap-salvar\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n    <input type=\"hidden\" name=\"mes\" value=\"{{ r.mes }}\"><input type=\"hidden\" name=\"ano\" value=\"{{ r.ano }}\"><input type=\"hidden\" name=\"produto\" value=\"{{ r.produto }}\">\n    <input type=\"hidden\" name=\"agro_rate\" value=\"{{ r.agro_rate|float if r.agro_rate else '' }}\">\n    <input type=\"hidden\" name=\"items_json\" id=\"ap-items\">\n    <button class=\"btn-pill fin-btn\" type=\"submit\">{{ ic('save') }} Salvar no histórico</button>\n    <span>Um backup do banco é feito antes de salvar. Depois de salva, a apuração gera o Excel e o arquivo do banco.</span>\n  </form>\n  <script>document.getElementById('ap-items').value = JSON.stringify({{ r['items']|tojson }});</script>\n{% endif %}\n\n<section class=\"vg-box\" style=\"margin-top:1rem\">\n  <header><h3>Consolidado por cotista</h3><span>{{ r.consolidado|length }} cotista(s) · {{ r.qty_cotas }} cota(s)</span></header>\n  {% with clientes = r.consolidado, conferir = false %}{% include \"financas/cap/_apur_cliente.html\" %}{% endwith %}\n</section>\n{% endif %}\n\n<script>\n(function () { var s = document.getElementById('ap-prod'), a = document.getElementById('ap-agro');\n  function t() { a.style.display = (!s.value || s.value === 'agro') ? '' : 'none'; } s.addEventListener('change', t); t(); })();\n</script>\n{% endblock %}\n",
  "financas/cap/cond_contrato.html": "{% extends \"financas/_layout.html\" %}\n{% import \"financas/cap/_macros.html\" as m with context %}\n{% block fin_titulo %}Contrato · {{ c.cliente_nome }}{% endblock %}\n{% block fin_conteudo %}\n{% set st = STATUS[c.status] %}{% set st_nome = STATUS_CONCLUIDO.get(c.tipo, st.nome) if c.status == 'concluido' else st.nome %}\n{% call m.cabecalho(TIPOS[c.tipo] ~ ' · ' ~ c.cliente_nome, c.produto_nome ~ ' · ' ~ c.dados.qtd ~ ' cota(s) · ' ~ reais((c.dados.retirada or {}).valor or c.dados.valor_total) ~ ' · ' ~ c.codigo, 'Contratos e assinaturas') %}\n  <a class=\"btn-pill outline fin-btn\" href=\"{{ url_for('financas.cond_contratos', slug=empresa.slug) }}\">{{ ic('arrow_back') }} Contratos</a>\n  <a class=\"btn-pill outline fin-btn\" href=\"{{ url_for('contratos.documento', cid=c.id) }}\" target=\"_blank\">{{ ic('open_in_new') }} Documento</a>\n  <a class=\"btn-pill outline fin-btn\" href=\"{{ url_for('contratos.documento', cid=c.id, imprimir=1) }}\" target=\"_blank\">{{ ic('download') }} PDF</a>\n  <a class=\"btn-pill outline fin-btn\" href=\"{{ url_for('financas.cond_cotista', slug=empresa.slug, cid=c.client_id) }}\">{{ fic('pessoas') }} Cotista</a>\n  {% if c.status in ('rascunho', 'aguardando', 'assinado') %}<button type=\"button\" class=\"btn-pill outline fin-btn co-perigo-t\" data-abrir=\"dlg-cancelar\">{{ ic('block') }} Cancelar envio</button>{% endif %}\n  {% if c.status != 'concluido' %}<button type=\"button\" class=\"btn-pill outline fin-btn\" data-abrir=\"dlg-excluir\" title=\"Contrato de teste ou gerado por engano\">{{ ic('delete') }} Apagar</button>{% endif %}\n{% endcall %}\n\n{% if c.dados.sem_regulamento %}<p class=\"co-aviso\">Este Termo de Aquisição foi gerado <b>sem o regulamento anexo</b> — o regulamento de {{ c.produto_nome }} ainda não foi cadastrado no sistema.</p>{% endif %}\n<div class=\"ctf-grid\">\n  <div class=\"ctf-doc\"><div class=\"ctf-st\"><span class=\"ctf-badge\" style=\"--c:{{ st.cor }}\">{{ st_nome }}</span></div>\n    <iframe src=\"{{ url_for('contratos.documento', cid=c.id) }}\" title=\"Documento\"></iframe></div>\n\n  <div class=\"ctf-lado\">\n    <section class=\"fin-box\">\n      {% if c.status in ('rascunho', 'aguardando') %}\n        <h3>{{ '1. Enviar para assinatura' if c.status == 'rascunho' else 'Aguardando assinatura do cliente' }}</h3>\n        {% if link_local %}<p class=\"co-aviso\">O link ainda aponta para este computador — o cliente não abre de fora.\n          Configure o <a href=\"{{ url_for('financas.cond_contratos_config', slug=empresa.slug) }}\">link público</a>.</p>{% endif %}\n        <form method=\"post\" action=\"{{ url_for('financas.cond_contrato_acao', slug=empresa.slug, cid=c.id, acao='enviar') }}\">\n          <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n          <button class=\"btn-pill fin-btn ctf-full\" {{ 'disabled' if not cli.email }}>{{ ic('mail') }} {{ 'Enviar para assinatura' if c.status == 'rascunho' else 'Reenviar e-mail' }}</button>\n          <p class=\"co-dica\" style=\"text-align:center\">para {{ cli.email or 'cliente sem e-mail' }}</p>\n        </form>\n        {% if fone_wpp %}<a class=\"btn-pill outline fin-btn ctf-full js-manual\" data-canal=\"WhatsApp\" target=\"_blank\" rel=\"noopener\" href=\"https://wa.me/{{ fone_wpp }}?text={{ msg_wpp|urlencode }}\">Enviar link pelo WhatsApp</a>{% endif %}\n        <div class=\"ctf-link\"><input class=\"inp\" id=\"ct-link\" value=\"{{ link }}\" readonly><button type=\"button\" class=\"btn-pill outline fin-btn mini\" id=\"ct-copiar\">Copiar</button></div>\n      {% elif c.status == 'assinado' %}\n        <h3>2. Confirmar depósito e ativar cotas</h3>\n        <p class=\"co-dica\">O cliente assinou. As cotas seguem <b>pendentes</b> até você confirmar o depósito.</p>\n        <form method=\"post\" action=\"{{ url_for('financas.cond_contrato_acao', slug=empresa.slug, cid=c.id, acao='ativar') }}\" class=\"fin-form\" onsubmit=\"return confirm('Confirmar o depósito e ativar {{ c.cotas|length }} cota(s)?')\">\n          <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n          <label class=\"lbl\">Data do depósito</label><input class=\"inp\" type=\"date\" name=\"data_deposito\" id=\"dt-dep\" value=\"{{ hoje }}\">\n          <table class=\"pr-tabela\" style=\"margin:.5rem 0\">\n            <thead><tr><th>Cota</th><th>Aquisição</th><th>Vencimento</th></tr></thead>\n            <tbody>{% for x in c.cotas %}<tr><td class=\"mono\">{{ x.share_number }}</td>\n              <td><input class=\"inp js-aq\" type=\"date\" name=\"aq_{{ x.id }}\" value=\"{{ aq_sugerida }}\"></td>\n              <td><input class=\"inp js-venc\" type=\"date\" name=\"venc_{{ x.id }}\" value=\"{{ venc_sugerido }}\"></td></tr>{% endfor %}</tbody>\n          </table>\n          <p class=\"co-dica\">Vencimento sugerido = aquisição + {{ c.dados.prazo_meses }} meses.</p>\n          <button class=\"btn-pill fin-btn ctf-full\">{{ ic('check') }} Confirmar depósito e ativar cotas</button>\n        </form>\n      {% elif c.status == 'concluido' %}\n        <h3>Concluído</h3><p class=\"co-dica\">{% if c.tipo == 'aquisicao' %}Depósito confirmado e cotas ativadas{% elif c.tipo == 'renovacao' %}Renovação assinada pelo cliente{% else %}Retirada assinada pelo cliente{% endif %} em {{ c.concluido_em|ct_data(True) }}.</p>\n        {% if c.tipo == 'renovacao' and c.dados.renovacao %}<p class=\"co-dica\">Renovação registrada nas cotas: {{ c.dados.renovacao.data|ct_data }} · novo vencimento {{ c.dados.renovacao.vencimento|ct_data }}.</p>{% endif %}\n        {% if c.tipo == 'retirada' and c.dados.retirada %}<p class=\"co-dica\">Retirada efetiva em {{ c.dados.retirada.data_efetiva|ct_data }} — finalize a cota em <a href=\"{{ url_for('financas.cond_vencimentos', slug=empresa.slug, aba='retiradas') }}\">Retiradas solicitadas</a> nessa data.</p>{% endif %}\n      {% else %}\n        <h3>Contrato cancelado</h3><p class=\"co-dica\">{{ c.cancelado_em|ct_data(True) }}{% if c.motivo_cancelamento %} — {{ c.motivo_cancelamento }}{% endif %}</p>\n        <a class=\"btn-pill outline fin-btn mini\" href=\"{{ url_for('financas.cond_contrato_novo', slug=empresa.slug, client_id=c.client_id) }}\">Gerar novo contrato</a>\n      {% endif %}\n    </section>\n\n    <section class=\"fin-box\">\n      <h3>Signatários</h3>\n      {% for s in c.signatarios %}\n      <div class=\"ctf-sig\"><span class=\"ctf-dot {{ 'ok' if s.status == 'assinado' }}\">{{ '✓' if s.status == 'assinado' }}</span>\n        <div><b>{{ s.nome }}</b> <small>· {{ 'Empresa' if s.papel == 'empresa' else 'Investidor(a)' }}</small>\n          <small class=\"ctf-l\">{{ s.email or '—' }}</small>\n          <small class=\"ctf-l {{ 'pos' if s.status == 'assinado' else 'aviso' }}\">{{ 'Assinou em ' ~ (s.assinado_em|ct_data(True)) ~ (' · IP ' ~ s.ip if s.ip else '') if s.status == 'assinado' else 'Aguardando assinatura' }}</small></div></div>\n      {% endfor %}\n    </section>\n\n    <section class=\"fin-box\">\n      <h3>Cotas deste contrato</h3>\n      <div class=\"vg-linhas\">{% for x in c.cotas %}<a href=\"{{ url_for('financas.cond_cota_editar', slug=empresa.slug, sid=x.id) }}\"><span class=\"mono\">nº {{ x.share_number }} · {{ reais(x.share_value) }}</span><b>{{ m.status_cota(x.status) }}</b></a>{% endfor %}</div>\n    </section>\n\n    <section class=\"fin-box\">\n      <h3>Histórico</h3>\n      <ul class=\"co-hist-lista\">{% for ev in c.eventos|reverse %}\n        <li class=\"{{ 'erro' if ev.tipo in ('email_erro', 'codigo_invalido', 'cancelado') }}\"><b>{{ EVENTOS.get(ev.tipo, ev.tipo) }}</b><span>{{ ev.criado_em|ct_data(True) }}{% if ev.ip %} · IP {{ ev.ip }}{% endif %}</span>{% if ev.descricao %}<small>{{ ev.descricao }}</small>{% endif %}</li>\n      {% endfor %}</ul>\n    </section>\n  </div>\n</div>\n\n<dialog class=\"dlg fin-dlg\" id=\"dlg-cancelar\">\n  <form method=\"post\" class=\"fin-form\" action=\"{{ url_for('financas.cond_contrato_acao', slug=empresa.slug, cid=c.id, acao='cancelar') }}\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n    <div class=\"dlg-head\"><h3>Cancelar envio do contrato</h3><button type=\"button\" class=\"ico\" data-fechar>{{ ic('close') }}</button></div>\n    <p class=\"co-dica\">O link de assinatura deixa de funcionar e o documento passa a mostrar <b>CANCELADO</b>.\n      {% if c.status == 'assinado' %}<b class=\"neg\">A assinatura já feita pelo cliente perde a validade.</b>{% endif %} As cotas continuam pendentes.</p>\n    <label class=\"lbl\">Motivo</label><input class=\"inp\" name=\"motivo\" maxlength=\"300\" placeholder=\"Ex.: CPF digitado errado, valor incorreto…\">\n    {% if c.status in ('aguardando', 'assinado') and cli.email %}\n    <label class=\"co-chk\"><input type=\"checkbox\" name=\"avisar\" value=\"1\" checked> Avisar o cliente por e-mail ({{ cli.email }})</label>{% endif %}\n    <p class=\"co-aviso\">Se o erro é no cadastro, primeiro <a href=\"{{ url_for('financas.cond_cotista_editar', slug=empresa.slug, cid=c.client_id) }}\">corrija o cotista</a> e depois use <b>Cancelar e gerar novo</b> — sai com as mesmas cotas e os dados atualizados.</p>\n    <div class=\"dlg-acoes\"><button type=\"button\" class=\"btn-pill outline fin-btn\" data-fechar>Voltar</button>\n      <button name=\"acao\" value=\"cancelar\" class=\"btn-pill outline fin-btn co-perigo-t\">Só cancelar</button>\n      <button name=\"acao\" value=\"regerar\" class=\"btn-pill fin-btn\">Cancelar e gerar novo</button></div>\n  </form>\n</dialog>\n\n<dialog class=\"dlg fin-dlg\" id=\"dlg-excluir\">\n  <form method=\"post\" class=\"fin-form\" action=\"{{ url_for('financas.cond_contrato_acao', slug=empresa.slug, cid=c.id, acao='excluir') }}\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n    <div class=\"dlg-head\"><h3>Apagar contrato</h3><button type=\"button\" class=\"ico\" data-fechar>{{ ic('close') }}</button></div>\n    <p class=\"co-dica\">Para contratos de <b>teste</b> ou gerados por engano. O contrato e o histórico de assinatura são apagados (fica o registro na auditoria) e o link enviado deixa de existir.</p>\n    {% set pend = c.cotas|selectattr('status', 'equalto', 'pendente')|list %}\n    {% if pend %}<label class=\"co-chk\"><input type=\"checkbox\" name=\"excluir_cotas\" value=\"1\"> Apagar também as cotas pendentes ({{ pend|map(attribute='share_number')|join(', ') }})</label>{% endif %}\n    <label class=\"lbl\">Digite <b>APAGAR</b> para confirmar</label><input class=\"inp\" id=\"conf-apagar\" autocomplete=\"off\">\n    <div class=\"dlg-acoes\"><button type=\"button\" class=\"btn-pill outline fin-btn\" data-fechar>Voltar</button>\n      <button class=\"btn-pill fin-btn co-perigo\" id=\"bt-apagar\" disabled>Apagar definitivamente</button></div>\n  </form>\n</dialog>\n\n<script>\n(function () {\n  var ca = document.getElementById('conf-apagar'), ba = document.getElementById('bt-apagar');\n  if (ca) ca.addEventListener('input', function () { ba.disabled = ca.value.trim().toUpperCase() !== 'APAGAR'; });\n  function manual(canal) { var fd = new FormData(); fd.append('_csrf', '{{ csrf_token() }}'); fd.append('canal', canal);\n    fetch('{{ url_for(\"financas.cond_contrato_acao\", slug=empresa.slug, cid=c.id, acao=\"enviado-manual\") }}', {method: 'POST', body: fd, credentials: 'same-origin'}); }\n  var cp = document.getElementById('ct-copiar');\n  if (cp) cp.addEventListener('click', function () { var i = document.getElementById('ct-link'); i.select();\n    (navigator.clipboard ? navigator.clipboard.writeText(i.value) : Promise.resolve(document.execCommand('copy'))).then(function () { cp.textContent = 'Copiado ✓'; manual('link copiado'); }); });\n  document.querySelectorAll('.js-manual').forEach(function (a) { a.addEventListener('click', function () { manual(a.dataset.canal); }); });\n  var dep = document.getElementById('dt-dep'), prazo = {{ c.dados.prazo_meses|int }};\n  function somaMeses(iso, n) { var p = iso.split('-').map(Number), x = new Date(p[0], p[1] - 1 + n, 1), ult = new Date(x.getFullYear(), x.getMonth() + 1, 0).getDate();\n    x.setDate(Math.min(p[2], ult)); return x.getFullYear() + '-' + String(x.getMonth() + 1).padStart(2, '0') + '-' + String(x.getDate()).padStart(2, '0'); }\n  if (dep) dep.addEventListener('change', function () { if (!dep.value) return;\n    document.querySelectorAll('.js-aq').forEach(function (i) { i.value = dep.value; }); document.querySelectorAll('.js-venc').forEach(function (i) { i.value = somaMeses(dep.value, prazo); }); });\n  document.querySelectorAll('.js-aq').forEach(function (i) { i.addEventListener('change', function () { if (i.value) i.closest('tr').querySelector('.js-venc').value = somaMeses(i.value, prazo); }); });\n})();\n</script>\n{% endblock %}\n",
  "financas/cap/cond_contrato_novo.html": "{% extends \"financas/_layout.html\" %}\n{% import \"financas/cap/_macros.html\" as m with context %}\n{% block fin_titulo %}Gerar contrato{% endblock %}\n{% block fin_conteudo %}\n{% call m.cabecalho('Gerar contrato para cotas pendentes', 'Para cotas já cadastradas como pendentes e ainda sem contrato. Para uma compra nova, use “Nova cota com contrato”.', 'Contratos e assinaturas') %}\n  <a class=\"btn-pill outline fin-btn\" href=\"{{ url_for('financas.cond_contratos', slug=empresa.slug) }}\">{{ ic('arrow_back') }} Contratos</a>\n{% endcall %}\n<section class=\"fin-box\">\n  <form method=\"get\" class=\"fin-form\" style=\"max-width:420px\">\n    <label class=\"lbl\">Cotista com cotas pendentes</label>\n    <select class=\"inp\" name=\"client_id\" onchange=\"this.form.submit()\"><option value=\"\">Selecione…</option>\n      {% for cid, nome in clientes %}<option value=\"{{ cid }}\" {{ 'selected' if cliente and cliente.id == cid }}>{{ nome }}</option>{% endfor %}\n      {% if cliente and cliente.id not in (clientes|map(attribute=0)|list) %}<option value=\"{{ cliente.id }}\" selected>{{ cliente.full_name }}</option>{% endif %}\n    </select>\n  </form>\n  {% if cliente %}\n    {% if falta %}<p class=\"co-aviso\">Para gerar o contrato, complete o cadastro de <b>{{ cliente.full_name }}</b>. Falta: {{ falta|join(', ') }}.\n      <a href=\"{{ url_for('financas.cond_cotista_editar', slug=empresa.slug, cid=cliente.id) }}\">Completar cadastro →</a></p>{% endif %}\n    {% if cotas %}\n    <form method=\"post\" class=\"fin-form\" style=\"margin-top:.8rem\">\n      <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><input type=\"hidden\" name=\"client_id\" value=\"{{ cliente.id }}\">\n      <label class=\"lbl\">Produto</label>\n      <select class=\"inp\" name=\"condominium_id\" id=\"sel-prod\" style=\"max-width:320px\">\n        {% for cond_id, lista in cotas|groupby('condominium_id') %}<option value=\"{{ cond_id }}\" {{ 'disabled' if lista[0].produto_code not in modelos }}>{{ lista[0].produto_nome }}{{ ' (modelo em breve)' if lista[0].produto_code not in modelos }}</option>{% endfor %}\n      </select>\n      <table class=\"pr-tabela\" style=\"margin-top:.6rem\">\n        <thead><tr><th></th><th>Cota</th><th>Produto</th><th class=\"num\">Valor</th><th>Cadastrada em</th></tr></thead>\n        <tbody>{% for x in cotas %}<tr data-prod=\"{{ x.condominium_id }}\"><td><input type=\"checkbox\" name=\"share_ids\" value=\"{{ x.id }}\" checked></td>\n          <td class=\"mono\">{{ x.share_number }}</td><td>{{ x.produto_nome }}</td><td class=\"num\">{{ reais(x.share_value) }}</td><td>{{ x.created_at|ct_data }}</td></tr>{% endfor %}</tbody>\n      </table>\n      <button class=\"btn-pill fin-btn\" style=\"margin-top:.8rem\" {{ 'disabled' if falta }}>{{ fic('contrato') }} Gerar contrato (já assinado pela empresa)</button>\n    </form>\n    <script>(function () { var s = document.getElementById('sel-prod'); function f() { document.querySelectorAll('tr[data-prod]').forEach(function (tr) {\n      var on = tr.dataset.prod === s.value; tr.style.display = on ? '' : 'none'; tr.querySelector('input').disabled = !on; }); } if (s) { s.addEventListener('change', f); f(); } })();</script>\n    {% else %}\n      <p class=\"fin-sub\" style=\"margin-top:.8rem\">Este cotista não tem cotas pendentes sem contrato.\n        <a href=\"{{ url_for('financas.cond_cota_nova', slug=empresa.slug, produto='civil', client_id=cliente.id) }}\">Cadastrar nova cota com contrato →</a></p>\n    {% endif %}\n  {% elif not clientes %}<p class=\"fin-sub\" style=\"margin-top:.8rem\">Não há cotas pendentes sem contrato.</p>{% endif %}\n</section>\n{% endblock %}\n",
  "financas/cap/cond_contratos.html": "{% extends \"financas/_layout.html\" %}\n{% import \"financas/cap/_macros.html\" as m with context %}\n{% block fin_titulo %}Contratos{% endblock %}\n{% block fin_conteudo %}\n{% call m.cabecalho('Contratos e assinaturas', 'Termos de aquisição, renovação e retirada: emissão, assinatura do cliente e acompanhamento.') %}\n  <a class=\"btn-pill fin-btn\" href=\"{{ url_for('financas.cond_cota_nova', slug=empresa.slug, produto='civil', voltar=request.path) }}\">{{ fic('add') }} Nova cota com contrato</a>\n  <a class=\"btn-pill outline fin-btn\" href=\"{{ url_for('financas.cond_contrato_novo', slug=empresa.slug) }}\">{{ fic('contrato') }} Contrato p/ cotas pendentes</a>\n  <a class=\"btn-pill outline fin-btn\" href=\"{{ url_for('financas.cond_contratos_config', slug=empresa.slug) }}\">{{ ic('settings') }} Configurações</a>\n{% endcall %}\n<div class=\"pr-abas\"><a class=\"{{ 'on' if not tipo }}\" href=\"?\">Todos</a>{% for k, v in TIPOS_CT.items() %}<a class=\"{{ 'on' if tipo == k }}\" href=\"?tipo={{ k }}\">{{ v }}</a>{% endfor %}</div>\n<section class=\"vg-box\">\n  <table class=\"pr-tabela\">\n    <thead><tr><th>Nº</th><th>Termo</th><th>Cotista</th><th>Produto</th><th>Cotas</th><th class=\"num\">Valor</th><th>Status</th><th>Criado</th><th>Assinado</th></tr></thead>\n    <tbody>\n    {% for c in lista %}\n      <tr class=\"clic\" onclick=\"location.href='{{ url_for('financas.cond_contrato', slug=empresa.slug, cid=c.id) }}'\">\n        <td class=\"mono\">{{ c.id }}</td><td>{{ TIPOS_CT.get(c.tipo, c.tipo) }}</td><td><b>{{ c.cliente }}</b></td><td>{{ COND_NOMES.get(c.code, c.code) }}</td>\n        <td class=\"mono\">{{ c.dados.cotas|map(attribute='numero')|join(', ') }}</td>\n        <td class=\"num\">{{ reais((c.dados.retirada or {}).valor or c.dados.valor_total) }}</td>\n        <td><span class=\"pr-st {{ ST[c.status][1] }}\">{{ ST[c.status][0] }}</span></td>\n        <td>{{ data_br(c.criado_em[:10]) }}</td><td>{{ data_br(c.assinado_em[:10]) if c.assinado_em else '—' }}</td>\n      </tr>\n    {% else %}<tr><td colspan=\"9\" class=\"fin-vazio\">Nenhum contrato emitido.</td></tr>{% endfor %}\n    </tbody>\n  </table>\n</section>\n{% endblock %}\n",
  "financas/cap/cond_contratos_config.html": "{% extends \"financas/_layout.html\" %}\n{% import \"financas/cap/_macros.html\" as m with context %}\n{% block fin_titulo %}Configurações dos contratos{% endblock %}\n{% block fin_conteudo %}\n{% call m.cabecalho('Configurações dos contratos', 'Valem para os próximos contratos. Os já gerados não mudam (ficam protegidos pelo hash).', 'Contratos e assinaturas') %}\n  <a class=\"btn-pill outline fin-btn\" href=\"{{ url_for('financas.cond_contratos', slug=empresa.slug) }}\">{{ ic('arrow_back') }} Contratos</a>\n{% endcall %}\n<form method=\"post\" class=\"fin-form co-form\">\n  <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n  <div class=\"co-grid\">\n    <section class=\"fin-box\">\n      <div class=\"pe-sec\">Link de assinatura</div>\n      <label class=\"lbl\">Endereço público do app</label><input class=\"inp\" type=\"url\" name=\"url_publica\" value=\"{{ cfg.url_publica }}\" placeholder=\"https://assinar.capuzzo.com.br\">\n      <p class=\"co-dica\">Começo do link que vai no e-mail do cliente ({{ cfg.url_publica }}/contratos/assinar/…). Enquanto for 127.0.0.1 o link só abre neste computador.</p>\n      <div class=\"pe-sec\">Empresa (contratada)</div>\n      <div class=\"fin-2col\"><div><label class=\"lbl\">Razão social</label><input class=\"inp\" name=\"empresa_nome\" value=\"{{ cfg.empresa_nome }}\"></div>\n        <div><label class=\"lbl\">CNPJ</label><input class=\"inp\" name=\"empresa_cnpj\" value=\"{{ cfg.empresa_cnpj }}\"></div></div>\n      <label class=\"lbl\">Sede</label><input class=\"inp\" name=\"empresa_endereco\" value=\"{{ cfg.empresa_endereco }}\">\n      <div class=\"pe-3col\"><div><label class=\"lbl\">Assina pela empresa</label><input class=\"inp\" name=\"empresa_assinante\" value=\"{{ cfg.empresa_assinante }}\"></div>\n        <div><label class=\"lbl\">E-mail do signatário</label><input class=\"inp\" name=\"empresa_email\" value=\"{{ cfg.empresa_email }}\"></div>\n        <div><label class=\"lbl\">Local da assinatura</label><input class=\"inp\" name=\"cidade_assinatura\" value=\"{{ cfg.cidade_assinatura }}\"></div></div>\n    </section>\n    <section class=\"fin-box\">\n      <div class=\"pe-sec\">Testemunhas</div>\n      {% for i in (1, 2) %}<div class=\"fin-2col\"><div><label class=\"lbl\">Testemunha {{ i }} — nome</label><input class=\"inp\" name=\"testemunha{{ i }}_nome\" value=\"{{ cfg['testemunha%d_nome' % i] }}\"></div>\n        <div><label class=\"lbl\">CPF</label><input class=\"inp\" name=\"testemunha{{ i }}_cpf\" value=\"{{ cfg['testemunha%d_cpf' % i] }}\"></div></div>{% endfor %}\n      <div class=\"pe-sec\">Comunicação com o cliente</div>\n      <label class=\"lbl\">E-mail de atendimento / cópia dos comprovantes</label><input class=\"inp\" name=\"email_copia\" value=\"{{ cfg.email_copia }}\">\n      <label class=\"lbl\">Dados para depósito (aparecem para o cliente depois que ele assina)</label>\n      <textarea class=\"inp\" name=\"instrucoes_deposito\" rows=\"4\">{{ cfg.instrucoes_deposito }}</textarea>\n      <label class=\"lbl\">Termos de renovação e retirada</label>\n      <select class=\"inp\" name=\"envio_automatico\">\n        <option value=\"0\" {{ 'selected' if cfg.envio_automatico != '1' }}>Gerar e esperar eu conferir e clicar em Enviar (fase de testes)</option>\n        <option value=\"1\" {{ 'selected' if cfg.envio_automatico == '1' }}>Enviar automaticamente ao cliente assim que for gerado</option>\n      </select>\n    </section>\n  </div>\n  <div class=\"lf-barra co-barra\"><span class=\"co-barra-info\"></span><button class=\"btn-pill fin-btn\">{{ ic('check') }} Salvar</button></div>\n</form>\n{% endblock %}\n",
  "financas/cap/cond_cota_editar.html": "{% extends \"financas/_layout.html\" %}\n{% import \"financas/cap/_macros.html\" as m with context %}\n{% block fin_titulo %}Cota {{ cota.share_number }}{% endblock %}\n{% block fin_conteudo %}\n{% set aqui = request.path %}\n{% call m.cabecalho('Cota ' ~ cota.share_number, (cota.condominium_name or COND_NOMES.get(cota.condominium_code, '')) ~ ' · ' ~ (cota.client_name or '')) %}\n  <a class=\"btn-pill outline fin-btn\" href=\"{{ voltar if voltar and voltar != request.url else url_for('financas.cond_produto', slug=empresa.slug, code=cota.condominium_code) }}\">{{ ic('arrow_back') }} Voltar</a>\n{% endcall %}\n\n<div class=\"co-grid co-grid-ed\">\n<form method=\"post\" class=\"fin-form co-form\" id=\"f-cota\" autocomplete=\"off\" novalidate>\n  <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><input type=\"hidden\" name=\"voltar\" value=\"{{ voltar if voltar and '/editar' not in voltar else '' }}\">\n  <section class=\"fin-box\">\n    <div class=\"pe-sec\">Produto e cotista</div>\n    <div class=\"co-l2\">\n      <div><label class=\"lbl\">Produto *</label>\n        <select class=\"inp\" name=\"condominium_id\">{% for c in conds %}<option value=\"{{ c.id }}\" {{ 'selected' if cota.condominium_id|string == c.id|string }}>{{ c.name }}</option>{% endfor %}</select></div>\n      <div><label class=\"lbl\">Cotista *</label>\n        <div class=\"co-cb\"><input class=\"inp\" id=\"co-cli-txt\"><input type=\"hidden\" name=\"client_id\" id=\"co-cli\" value=\"{{ cota.client_id }}\">\n          <div class=\"co-cb-lista\" id=\"co-cli-lista\" hidden></div></div></div>\n    </div>\n    <div class=\"pe-sec\">Dados da cota</div>\n    <div class=\"co-l4\">\n      <div><label class=\"lbl\">Número *</label><input class=\"inp mono\" name=\"share_number\" required value=\"{{ cota.share_number }}\"></div>\n      <div><label class=\"lbl\">Valor *</label><input class=\"inp num\" name=\"share_value\" id=\"co-valor\" value=\"{{ '%.2f'|format(cota.share_value|float) }}\"></div>\n      <div><label class=\"lbl\">Status</label>\n        <select class=\"inp\" name=\"status\">{% for k, v in [('ativa', 'Ativa'), ('pendente', 'Pendente'), ('inativa', 'Inativa')] %}<option value=\"{{ k }}\" {{ 'selected' if cota.status == k }}>{{ v }}</option>{% endfor %}</select></div>\n      <div></div>\n    </div>\n    <div class=\"co-l4\">\n      <div><label class=\"lbl\">Aquisição</label><input class=\"inp\" type=\"date\" name=\"acquisition_date\" value=\"{{ cota.acquisition_date or '' }}\"></div>\n      <div><label class=\"lbl\">Última renovação</label><input class=\"inp\" type=\"date\" name=\"last_renewal_date\" value=\"{{ cota.last_renewal_date or '' }}\"></div>\n      <div><label class=\"lbl\">Vencimento</label><input class=\"inp\" type=\"date\" name=\"maturity_date\" value=\"{{ cota.maturity_date or '' }}\"></div>\n      <div><label class=\"lbl\">Data de retirada</label><input class=\"inp\" type=\"date\" name=\"withdrawal_date\" value=\"{{ cota.withdrawal_date or '' }}\"></div>\n    </div>\n    <label class=\"co-chk co-hist\"><input type=\"checkbox\" name=\"accrual_until_withdrawal\" value=\"on\" {{ 'checked' if (cota.accrual_until_withdrawal or 0)|int == 1 }}>\n      <span><b>Retirada fora do período — render proporcional até a retirada</b>\n        <small>Ligado: mesmo inativa, a cota entra na apuração e rende até o dia anterior à data de retirada. Desligado = regra padrão (cota inativada não rende no período).</small></span></label>\n    <label class=\"co-chk co-hist\"><input type=\"checkbox\" name=\"allow_duplicate_share_number\" value=\"on\">\n      <span><b>Lançamento histórico: permitir número repetido</b><small>Só para histórico com numeração inconsistente.</small></span></label>\n    <div class=\"pe-sec\">Observações</div>\n    <textarea class=\"inp\" name=\"notes\" rows=\"2\">{{ cota.notes or '' }}</textarea>\n    <div class=\"co-acoes-form\"><button class=\"btn-pill fin-btn\" type=\"submit\">{{ ic('check') }} Salvar alterações</button></div>\n  </section>\n</form>\n\n<aside>\n  <section class=\"fin-box co-lado\">\n    <h3>Situação</h3>\n    <div class=\"vg-linhas\">\n      <div><span>Status</span><b>{{ m.status_cota(cota.status) }}</b></div>\n      {% if cota.withdrawal_requested %}<div><span>Retirada pedida</span><b>efetiva {{ data_br(cota.withdrawal_effective_date) }}</b></div>{% endif %}\n      <div><span>Vencimento</span><b>{{ data_br(cota.maturity_date) if cota.maturity_date else '—' }}</b></div>\n      <div><span>Valor</span><b>{{ reais(cota.share_value) }}</b></div>\n    </div>\n    {% if cota.status == 'ativa' %}\n      <div class=\"co-acao-linha\" style=\"display:flex;gap:.5rem;flex-wrap:wrap\">\n        <a class=\"btn-pill fin-btn mini\" href=\"{{ url_for('financas.cond_termo', slug=empresa.slug, tipo='renovacao', ids=cota.id, referrer=aqui) }}\">{{ ic('autorenew') }} Renovar (gera termo)</a>\n      {% if not cota.withdrawal_requested %}\n        <a class=\"btn-pill outline fin-btn mini\" href=\"{{ url_for('financas.cond_termo', slug=empresa.slug, tipo='retirada', ids=cota.id, referrer=aqui) }}\">{{ ic('event') }} Marcar retirada (gera termo)</a>\n      </div>\n      {% else %}\n      </div>\n      <form method=\"post\" action=\"{{ url_for('financas.cond_cota_acao', slug=empresa.slug, sid=cota.id, acao='cancelar-retirada') }}\" class=\"co-acao-linha\">\n        <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><input type=\"hidden\" name=\"voltar\" value=\"{{ aqui }}\">\n        <button class=\"btn-pill outline fin-btn mini\">Cancelar pedido de retirada</button></form>\n      {% endif %}\n      <details class=\"co-acao\"><summary>{{ ic('logout') }} Retirar agora (inativar)</summary>\n        <form method=\"post\" action=\"{{ url_for('financas.cond_cota_acao', slug=empresa.slug, sid=cota.id, acao='inativar') }}\" onsubmit=\"return confirm('Inativar a cota {{ cota.share_number }}?')\">\n          <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><input type=\"hidden\" name=\"referrer\" value=\"{{ aqui }}\">\n          <label class=\"lbl\">Data de retirada *</label><input class=\"inp\" type=\"date\" name=\"withdrawal_date\" value=\"{{ hoje }}\" required>\n          <label class=\"co-chk\"><input type=\"checkbox\" name=\"accrual_until_withdrawal\" value=\"on\"> render proporcional até a retirada</label>\n          <label class=\"lbl\">Observação</label><input class=\"inp\" name=\"user_note\">\n          <button class=\"btn-pill fin-btn mini co-perigo\">Inativar cota</button></form></details>\n    {% elif cota.status == 'inativa' %}\n      <form method=\"post\" action=\"{{ url_for('financas.cond_cota_acao', slug=empresa.slug, sid=cota.id, acao='reativar') }}\" class=\"co-acao-linha\" onsubmit=\"return confirm('Reativar a cota? A data de retirada será removida.')\">\n        <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><input type=\"hidden\" name=\"referrer\" value=\"{{ aqui }}\">\n        <button class=\"btn-pill outline fin-btn mini\">{{ ic('undo') }} Reativar cota</button></form>\n    {% endif %}\n    <details class=\"co-acao\"><summary class=\"co-perigo-t\">{{ ic('delete') }} Excluir cota</summary>\n      <form method=\"post\" action=\"{{ url_for('financas.cond_cota_acao', slug=empresa.slug, sid=cota.id, acao='excluir') }}\" onsubmit=\"return confirm('Excluir DEFINITIVAMENTE a cota {{ cota.share_number }}? Um backup é feito antes.')\">\n        <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><input type=\"hidden\" name=\"voltar\" value=\"{{ url_for('financas.cond_produto', slug=empresa.slug, code=cota.condominium_code) }}\">\n        <p class=\"co-dica\">Use só para lançamentos errados. Para saída do cotista, use “Retirar”. Um backup do banco é feito antes.</p>\n        <button class=\"btn-pill fin-btn mini co-perigo\">Excluir definitivamente</button></form></details>\n  </section>\n  {% if hist %}\n  <section class=\"fin-box co-lado\">\n    <h3>Histórico</h3>\n    <ul class=\"co-hist-lista\">\n      {% for h in hist %}<li><b>{{ {'INSERT':'Cadastro','UPDATE':'Alteração','RENEW':'Renovação','DEACTIVATE':'Inativação','REACTIVATE':'Reativação','WITHDRAWAL_REQUEST':'Retirada pedida','WITHDRAWAL_CANCEL':'Retirada cancelada','WITHDRAWAL_UPDATE':'Data de retirada alterada','WITHDRAWAL_FINALIZE':'Retirada finalizada'}.get(h.action, h.action) }}</b>\n        <span>{{ data_br(h.created_at[:10]) }} {{ h.created_at[11:16] }}</span>{% if h.user_note %}<small>{{ h.user_note }}</small>{% endif %}</li>{% endfor %}\n    </ul>\n  </section>\n  {% endif %}\n</aside>\n</div>\n\n<script>\n(function () {\n  var CLIENTES = {{ clientes|tojson }}, txt = document.getElementById('co-cli-txt'), hid = document.getElementById('co-cli'), lista = document.getElementById('co-cli-lista');\n  function esc(s) { return String(s || '').replace(/[&<>\"]/g, function (c) { return {'&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;'}[c]; }); }\n  var pre = CLIENTES.find(function (c) { return String(c.id) === String(hid.value); }); if (pre) txt.value = pre.nome;\n  txt.addEventListener('input', function () {\n    var q = txt.value.toLowerCase().trim(), qd = q.replace(/\\D/g, '');\n    var r = CLIENTES.filter(function (c) { return c.nome.toLowerCase().indexOf(q) >= 0 || (qd && c.cpf.replace(/\\D/g, '').indexOf(qd) >= 0); }).slice(0, 30);\n    lista.innerHTML = r.map(function (c) { return '<button type=\"button\" data-id=\"' + c.id + '\"><b>' + esc(c.nome) + '</b><small>' + esc(c.cpf) + '</small></button>'; }).join('') || '<div class=\"co-cb-vazio\">Nenhum cotista</div>';\n    lista.hidden = false;\n  });\n  lista.addEventListener('mousedown', function (e) { var b = e.target.closest('button'); if (!b) return; e.preventDefault(); hid.value = b.dataset.id; txt.value = b.querySelector('b').textContent; lista.hidden = true; });\n  txt.addEventListener('blur', function () { setTimeout(function () { lista.hidden = true; if (pre && !txt.value) { txt.value = pre.nome; hid.value = pre.id; } }, 150); });\n  var v = document.getElementById('co-valor'); v.value = Number(v.value).toLocaleString('pt-BR', {minimumFractionDigits: 2});\n})();\n</script>\n{% endblock %}\n",
  "financas/cap/cond_cota_nova.html": "{% extends \"financas/_layout.html\" %}\n{% import \"financas/cap/_macros.html\" as m with context %}\n{% block fin_titulo %}Nova cota{% endblock %}\n{% block fin_conteudo %}\n{% call m.cabecalho('Nova cota', 'Cadastre uma ou mais cotas de um cotista de uma só vez.') %}\n  <a class=\"btn-pill outline fin-btn\" href=\"{{ voltar or url_for('financas.cond_painel', slug=empresa.slug) }}\">{{ ic('arrow_back') }} Voltar</a>\n{% endcall %}\n\n<form method=\"post\" class=\"fin-form co-form\" id=\"f-cota\" autocomplete=\"off\" novalidate>\n  <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><input type=\"hidden\" name=\"voltar\" value=\"{{ voltar }}\">\n  <section class=\"fin-box\">\n    <div class=\"pe-sec\">Produto e cotista</div>\n    <div class=\"co-l2\">\n      <div><label class=\"lbl\">Produto *</label>\n        <select class=\"inp\" name=\"condominium_id\" id=\"co-cond\" required>\n          <option value=\"\">Selecione…</option>\n          {% for c in conds %}<option value=\"{{ c.id }}\" data-code=\"{{ c.code }}\" data-padrao=\"{{ padroes.get(c.code, 0) }}\" {{ 'selected' if cota.condominium_id|string == c.id|string }}>{{ c.name }}</option>{% endfor %}\n        </select></div>\n      <div><label class=\"lbl\">Cotista *</label>\n        <div class=\"co-cb\">\n          <input class=\"inp\" id=\"co-cli-txt\" placeholder=\"Digite nome, CPF/CNPJ ou Pix…\">\n          <input type=\"hidden\" name=\"client_id\" id=\"co-cli\" value=\"{{ cota.client_id or '' }}\">\n          <a class=\"btn-pill outline fin-btn mini\" id=\"co-cli-novo\" href=\"{{ url_for('financas.cond_cotista_novo', slug=empresa.slug) }}\">{{ ic('add') }} Novo</a>\n          <div class=\"co-cb-lista\" id=\"co-cli-lista\" hidden></div>\n        </div>\n        <small class=\"co-dica\" id=\"co-cli-info\"></small></div>\n    </div>\n\n    <div class=\"pe-sec\">Cotas</div>\n    <div class=\"co-l4\">\n      <div><label class=\"lbl\">Quantidade *</label><input class=\"inp\" type=\"number\" min=\"1\" max=\"200\" id=\"co-qtd\" value=\"{{ cota.linhas|length or 1 }}\"></div>\n      <div><label class=\"lbl\">Valor unitário</label>\n        <input class=\"inp\" name=\"share_value\" id=\"co-valor\" value=\"{{ cota.share_value or 0 }}\" readonly>\n        <label class=\"co-chk\"><input type=\"checkbox\" id=\"co-valor-dif\"> usar valor diferente do padrão</label></div>\n      <div><label class=\"lbl\">Status</label>\n        <select class=\"inp\" name=\"status\" id=\"co-status\">\n          {% for k, v in [('ativa', 'Ativa'), ('pendente', 'Pendente'), ('inativa', 'Inativa')] %}<option value=\"{{ k }}\" {{ 'selected' if cota.status == k }}>{{ v }}</option>{% endfor %}\n        </select></div>\n      <div><label class=\"lbl\">Total</label><div class=\"co-total\" id=\"co-total\">R$ 0,00</div></div>\n    </div>\n\n    <div class=\"pe-sec\">Datas <small>preenchem todas as linhas — depois dá para ajustar cada uma</small></div>\n    <div class=\"co-l4\">\n      <div><label class=\"lbl\">Aquisição <span id=\"co-acq-req\">*</span></label><input class=\"inp\" type=\"date\" id=\"co-acq\"></div>\n      <div><label class=\"lbl\">Última renovação</label><input class=\"inp\" type=\"date\" id=\"co-lrd\"></div>\n      <div><label class=\"lbl\">Vencimento <small class=\"co-dica\">sugerido: aquisição + 1 ano</small></label><input class=\"inp\" type=\"date\" id=\"co-mat\"></div>\n      <div><label class=\"lbl\">&nbsp;</label><button type=\"button\" class=\"btn-pill outline fin-btn\" id=\"co-aplicar\">{{ ic('south') }} Aplicar em todas</button></div>\n    </div>\n    <p class=\"co-aviso\" id=\"co-pend\" hidden>Cota pendente: as datas podem ser preenchidas depois, quando o depósito for confirmado.</p>\n\n    <div style=\"overflow-x:auto;margin-top:.6rem\">\n      <table class=\"pr-tabela co-linhas\">\n        <thead><tr><th>#</th><th>Número</th><th class=\"num\">Valor</th><th>Aquisição</th><th>Última renovação</th><th>Vencimento</th></tr></thead>\n        <tbody id=\"co-corpo\"></tbody>\n      </table>\n    </div>\n    <label class=\"co-chk co-hist\"><input type=\"checkbox\" name=\"allow_duplicate_share_number\" value=\"on\" {{ 'checked' if cota.allow_dup }}>\n      <span><b>Lançamento histórico: permitir número repetido</b><small>Só para importar histórico com numeração inconsistente.</small></span></label>\n  </section>\n\n  <section class=\"fin-box\" id=\"co-sec-contrato\">\n    <label class=\"co-chk co-contrato\"><input type=\"checkbox\" name=\"gerar_contrato\" id=\"co-contrato\" value=\"on\" {{ 'checked' if cota.gerar_contrato }}>\n      <span><b>Gerar Termo de Aquisição + Regulamento e preparar para assinatura</b>\n        <small id=\"co-contrato-info\">O contrato sai preenchido e já assinado pela empresa. As cotas ficam <b>pendentes</b> até o cliente assinar e o depósito ser confirmado.</small></span></label>\n    <div class=\"pe-sec\">Observações</div>\n    <textarea class=\"inp\" name=\"notes\" rows=\"2\" placeholder=\"Anotações internas (opcional)\">{{ cota.notes or '' }}</textarea>\n  </section>\n\n  <div class=\"lf-barra co-barra\">\n    <span class=\"co-barra-info\" id=\"co-resumo\"></span>\n    <a class=\"btn-pill outline fin-btn\" href=\"{{ voltar or url_for('financas.cond_painel', slug=empresa.slug) }}\">Cancelar</a>\n    <button class=\"btn-pill fin-btn\" type=\"submit\">{{ ic('check') }} Cadastrar cotas</button>\n  </div>\n</form>\n\n<script>\n(function () {\n  var CLIENTES = {{ clientes|tojson }}, LINHAS = {{ cota.linhas|tojson }};\n  var URL_SUG = '{{ url_for(\"financas.cond_cotas_sugerir\", slug=empresa.slug, cond_id=0, qty=0) }}'.replace(/0\\/0$/, '');\n  var MODELOS = {{ modelos_aq|tojson }};   // produto → tem regulamento anexo (true) / termo sem regulamento ainda (false)\n  var $ = function (id) { return document.getElementById(id); };\n  var cond = $('co-cond'), qtd = $('co-qtd'), valor = $('co-valor'), dif = $('co-valor-dif'), st = $('co-status'), corpo = $('co-corpo');\n  function num(s) { s = String(s || '').replace(/[^\\d,.-]/g, ''); if (s.indexOf(',') >= 0 || /^\\d{1,3}(\\.\\d{3})+$/.test(s)) s = s.replace(/\\./g, '').replace(',', '.'); return parseFloat(s) || 0; }\n  function br(v) { return 'R$ ' + Number(v || 0).toLocaleString('pt-BR', {minimumFractionDigits: 2, maximumFractionDigits: 2}); }\n  function esc(s) { return String(s == null ? '' : s).replace(/[&<>\"]/g, function (c) { return {'&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;'}[c]; }); }\n  function maisUmAno(s) { if (!s) return ''; var p = s.split('-'); var a = +p[0] + 1, m = p[1], dd = p[2]; if (m === '02' && dd === '29') dd = '28'; return a + '-' + m + '-' + dd; }\n\n  // ── cotista (busca) ──\n  var txt = $('co-cli-txt'), hid = $('co-cli'), lista = $('co-cli-lista'), info = $('co-cli-info'), foco = -1;\n  function escolher(c) { hid.value = c.id; txt.value = c.nome; info.textContent = (c.cpf ? 'CPF/CNPJ ' + c.cpf : '') + (c.pix ? ' · Pix ' + c.pix : '') + (c.inativo ? ' · cadastro inativo' : ''); lista.hidden = true; }\n  function filtrar() {\n    var q = txt.value.toLowerCase().trim(), qd = q.replace(/\\D/g, '');\n    var r = CLIENTES.filter(function (c) { return !q || c.nome.toLowerCase().indexOf(q) >= 0 || (qd && c.cpf.replace(/\\D/g, '').indexOf(qd) >= 0) || c.pix.toLowerCase().indexOf(q) >= 0; }).slice(0, 30);\n    foco = -1;\n    lista.innerHTML = r.length ? r.map(function (c) { return '<button type=\"button\" data-id=\"' + c.id + '\"><b>' + esc(c.nome) + (c.inativo ? ' <i>inativo</i>' : '') + '</b><small>' + esc(c.cpf) + (c.pix ? ' · Pix ' + esc(c.pix) : '') + '</small></button>'; }).join('')\n      : '<div class=\"co-cb-vazio\">Nenhum cotista encontrado. Use “+ Novo”.</div>';\n    lista.hidden = false;\n  }\n  txt.addEventListener('input', function () { hid.value = ''; info.textContent = ''; filtrar(); });\n  txt.addEventListener('focus', filtrar);\n  txt.addEventListener('keydown', function (e) {\n    var b = lista.querySelectorAll('button'); if (!b.length) return;\n    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') { e.preventDefault(); foco = Math.max(0, Math.min(b.length - 1, foco + (e.key === 'ArrowDown' ? 1 : -1))); b.forEach(function (x, i) { x.classList.toggle('on', i === foco); }); }\n    else if (e.key === 'Enter') { e.preventDefault(); (b[foco] || b[0]).dispatchEvent(new MouseEvent('mousedown')); }\n    else if (e.key === 'Escape') lista.hidden = true;\n  });\n  lista.addEventListener('mousedown', function (e) { var b = e.target.closest('button'); if (!b) return; e.preventDefault(); escolher(CLIENTES.find(function (c) { return String(c.id) === b.dataset.id; })); });\n  document.addEventListener('click', function (e) { if (!e.target.closest('.co-cb')) lista.hidden = true; });\n  if (hid.value) { var pre = CLIENTES.find(function (c) { return String(c.id) === String(hid.value); }); if (pre) escolher(pre); }\n  $('co-cli-novo').addEventListener('click', function () {\n    var u = new URL(location.href); if (cond.value) u.searchParams.set('produto', cond.selectedOptions[0].dataset.code);\n    this.href += '?voltar=' + encodeURIComponent(u.pathname + u.search);\n  });\n\n  // ── linhas ──\n  function linha(i, x) {\n    return '<tr><td class=\"co-i\">' + (i + 1) + '</td>' +\n      '<td><input class=\"inp mono\" name=\"share_numbers\" value=\"' + esc(x.n) + '\" required></td>' +\n      '<td><input class=\"inp num co-v\" name=\"share_values\" value=\"' + (x.v ? Number(x.v).toLocaleString('pt-BR', {minimumFractionDigits: 2}) : '') + '\"></td>' +\n      '<td><input class=\"inp co-acq\" type=\"date\" name=\"acquisition_dates\" value=\"' + esc(x.acq) + '\"></td>' +\n      '<td><input class=\"inp co-lrd\" type=\"date\" name=\"last_renewal_dates\" value=\"' + esc(x.lrd) + '\"></td>' +\n      '<td><input class=\"inp co-mat\" type=\"date\" name=\"maturity_dates\" value=\"' + esc(x.mat) + '\"></td></tr>';\n  }\n  function linhasAtuais() {\n    return Array.prototype.map.call(corpo.rows, function (r) { var i = r.querySelectorAll('input'); return {n: i[0].value, v: num(i[1].value), acq: i[2].value, lrd: i[3].value, mat: i[4].value}; });\n  }\n  function desenhar(arr) { corpo.innerHTML = arr.map(function (x, i) { return linha(i, x); }).join(''); total(); }\n  function padrao() { return {n: '', v: num(valor.value), acq: $('co-acq').value, lrd: $('co-lrd').value, mat: $('co-mat').value}; }\n  function total() {\n    var t = 0; corpo.querySelectorAll('.co-v').forEach(function (i) { t += num(i.value); });\n    $('co-total').textContent = br(t);\n    $('co-resumo').textContent = corpo.rows.length + ' cota(s) · ' + br(t);\n  }\n  function sugerir(manter) {\n    var n = Math.max(1, Math.min(200, parseInt(qtd.value) || 1)), atuais = linhasAtuais();\n    if (!cond.value) { while (atuais.length < n) atuais.push(padrao()); desenhar(atuais.slice(0, n)); return; }\n    fetch(URL_SUG + cond.value + '/' + n, {credentials: 'same-origin'}).then(function (r) { return r.json(); }).then(function (j) {\n      if (!dif.checked && j.valor_padrao) valor.value = Number(j.valor_padrao).toLocaleString('pt-BR', {minimumFractionDigits: 2});\n      var arr = [];\n      for (var i = 0; i < n; i++) {\n        var x = (manter && atuais[i]) ? atuais[i] : padrao();\n        if (!manter || !atuais[i] || !atuais[i].n) x.n = j.numeros[i] || '';\n        if (!dif.checked && !manter) x.v = num(valor.value);\n        if (!x.v) x.v = num(valor.value);\n        arr.push(x);\n      }\n      desenhar(arr);\n    });\n  }\n  cond.addEventListener('change', function () { sugerir(false); contrato(); });\n  qtd.addEventListener('change', function () { sugerir(true); });\n  dif.addEventListener('change', function () {\n    valor.readOnly = !dif.checked;\n    if (dif.checked) { valor.focus(); valor.select(); } else { var o = cond.selectedOptions[0]; if (o && o.dataset.padrao) { valor.value = Number(o.dataset.padrao).toLocaleString('pt-BR', {minimumFractionDigits: 2}); aplicarValor(); } }\n  });\n  function aplicarValor() { var v = num(valor.value); corpo.querySelectorAll('.co-v').forEach(function (i) { i.value = v.toLocaleString('pt-BR', {minimumFractionDigits: 2}); }); total(); }\n  valor.addEventListener('input', function () { if (dif.checked) aplicarValor(); });\n  corpo.addEventListener('input', function (e) { if (e.target.classList.contains('co-v')) total(); });\n  $('co-acq').addEventListener('change', function () { var m = $('co-mat'); if (!m.value || m.dataset.auto) { m.value = maisUmAno(this.value); m.dataset.auto = '1'; } aplicarDatas(false); });\n  $('co-mat').addEventListener('input', function () { this.dataset.auto = ''; });\n  function aplicarDatas(tudo) {\n    [['co-acq', '.co-acq'], ['co-lrd', '.co-lrd'], ['co-mat', '.co-mat']].forEach(function (p) {\n      var v = $(p[0]).value; corpo.querySelectorAll(p[1]).forEach(function (i) { if (tudo || !i.value || i.dataset.auto) { i.value = v; i.dataset.auto = '1'; } });\n    });\n  }\n  $('co-aplicar').addEventListener('click', function () { aplicarDatas(true); });\n  corpo.addEventListener('change', function (e) {\n    var t = e.target; t.dataset.auto = '';\n    if (t.classList.contains('co-acq')) { var m = t.closest('tr').querySelector('.co-mat'); if (!m.value || m.dataset.auto) { m.value = maisUmAno(t.value); m.dataset.auto = '1'; } }\n  });\n\n  // ── status / contrato ──\n  var chk = $('co-contrato'), cinfo = $('co-contrato-info'), ctxt = cinfo.innerHTML;\n  function contrato() {\n    var o = cond.selectedOptions[0], code = o ? o.dataset.code : '';\n    if (cond.value && !(code in MODELOS)) { chk.checked = false; chk.disabled = true; cinfo.textContent = 'Modelo de contrato deste produto ainda não cadastrado.'; }\n    else if (cond.value && MODELOS[code] === false) { chk.disabled = false; cinfo.innerHTML = ctxt + ' <b>O regulamento deste produto ainda não foi cadastrado</b> — o termo sai sem o anexo.'; }\n    else { chk.disabled = false; cinfo.innerHTML = ctxt; }\n    if (chk.checked) st.value = 'pendente';\n    st.disabled = chk.checked; status();\n  }\n  function status() { var p = st.value === 'pendente'; $('co-pend').hidden = !p; $('co-acq-req').hidden = p; }\n  chk.addEventListener('change', contrato); st.addEventListener('change', status);\n  $('f-cota').addEventListener('submit', function (e) {\n    st.disabled = false;\n    if (!hid.value) { e.preventDefault(); txt.focus(); txt.classList.add('erro'); info.textContent = 'Selecione o cotista (ou cadastre com “+ Novo”).'; st.disabled = chk.checked; return; }\n    if (!cond.value) { e.preventDefault(); cond.focus(); st.disabled = chk.checked; }\n  });\n\n  valor.value = num(valor.value).toLocaleString('pt-BR', {minimumFractionDigits: 2});\n  if (LINHAS.length) { desenhar(LINHAS); } else { sugerir(false); }\n  contrato();\n})();\n</script>\n{% endblock %}\n",
  "financas/cap/cond_cotista.html": "{% extends \"financas/_layout.html\" %}\n{% import \"financas/cap/_macros.html\" as m with context %}\n{% block fin_titulo %}{{ cli.full_name }}{% endblock %}\n{% block fin_conteudo %}\n{% call m.cabecalho(cli.full_name, cli.cpf ~ (' · ' ~ cli.email if cli.email else '') ~ (' · ' ~ cli.phone if cli.phone else ''), 'Cotista') %}\n  <a class=\"btn-pill fin-btn\" href=\"{{ url_for('financas.cond_cotista_editar', slug=empresa.slug, cid=cli.id) }}\">{{ fic('edit') }} Editar cadastro</a>\n  <a class=\"btn-pill fin-btn\" href=\"{{ url_for('financas.cond_cota_nova', slug=empresa.slug, client_id=cli.id, voltar=request.path) }}\">{{ fic('add') }} Nova cota</a>\n  <form method=\"post\" action=\"{{ url_for('financas.cond_cotista_acao', slug=empresa.slug, cid=cli.id, acao='reativar' if cli.status == 'inativo' else 'inativar') }}\" onsubmit=\"return confirm('{{ 'Reativar' if cli.status == 'inativo' else 'Inativar' }} o cadastro de {{ cli.full_name }}?')\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><input type=\"hidden\" name=\"voltar\" value=\"{{ request.path }}\">\n    <button class=\"btn-pill outline fin-btn\">{{ 'Reativar cadastro' if cli.status == 'inativo' else 'Inativar cadastro' }}</button></form>\n{% endcall %}\n<div class=\"vg-kpis\" style=\"grid-template-columns:repeat(4,minmax(0,1fr))\">\n  <div class=\"vg-kpi escuro\"><small>Patrimônio ativo</small><b>{{ reais(total_ativo) }}</b><em>{{ n_ativas }} cota(s) ativa(s)</em></div>\n  <div class=\"vg-kpi\"><small>Último rendimento</small><b>{{ reais(rend[0].v) if rend else '—' }}</b><em>{{ ('%02d/%d'|format(rend[0].m, rend[0].a)) if rend else 'sem apuração' }}</em></div>\n  <div class=\"vg-kpi\"><small>Recebido (12 apurações)</small><b>{{ reais(rend|sum(attribute='v')) }}</b><em>rendimentos apurados</em></div>\n  <div class=\"vg-kpi\"><small>Pagamento</small><b style=\"font-size:1rem\">{{ cli.pix_key or (cli.bank_name ~ ' ' ~ (cli.bank_account or '')) or '—' }}</b><em>{{ 'chave PIX' if cli.pix_key else 'conta bancária' }}</em></div>\n</div>\n<div class=\"vg-cols\">\n  <section class=\"vg-box\">\n    <header><h3>Cotas</h3><a href=\"{{ url_for('financas.cond_cota_nova', slug=empresa.slug, client_id=cli.id, voltar=request.path) }}\">Nova cota</a></header>\n    <table class=\"pr-tabela\">\n      <thead><tr><th>Produto</th><th>Cota</th><th class=\"num\">Valor</th><th>Aquisição</th><th>Vencimento</th><th>Status</th></tr></thead>\n      <tbody>\n      {% for s in cotas %}\n        <tr class=\"clic\" onclick=\"location.href='{{ url_for('financas.cond_cota_editar', slug=empresa.slug, sid=s.id) }}'\"><td>{{ COND_NOMES[s.code] }}</td><td class=\"mono\">{{ s.share_number }}</td><td class=\"num\">{{ reais(s.share_value) }}</td>\n          <td>{{ data_br(s.acquisition_date) if s.acquisition_date else '—' }}</td><td>{{ data_br(s.maturity_date) if s.maturity_date else '—' }}</td>\n          <td>{{ m.status_cota(s.status) }}</td></tr>\n      {% else %}<tr><td colspan=\"6\" class=\"fin-vazio\">Sem cotas.</td></tr>{% endfor %}\n      </tbody>\n    </table>\n  </section>\n  <div>\n    <section class=\"vg-box\" style=\"margin-bottom:1rem\">\n      <header><h3>Dados para contrato</h3></header>\n      <div class=\"vg-linhas\">\n        <div><span>Estado civil · profissão</span><b>{{ cli.marital_status or '—' }} · {{ cli.profession or '—' }}</b></div>\n        <div><span>Endereço</span><b style=\"white-space:normal;text-align:right\">{{ [cli.address_street, cli.address_district, cli.address_city]|select|join(', ') or '—' }}{{ '-' ~ cli.address_state if cli.address_state }}</b></div>\n        <div><span>CEP</span><b>{{ cli.address_zip or '—' }}</b></div>\n      </div>\n    </section>\n    <section class=\"vg-box\" style=\"margin-bottom:1rem\">\n      <header><h3>Contratos</h3></header>\n      <div class=\"vg-linhas\">\n        {% for c in contratos %}\n          <a href=\"{{ url_for('financas.cond_contrato', slug=empresa.slug, cid=c.id) }}\"><span>Termo de Aquisição · {{ c.dados.qtd }} cota(s) · {{ data_br(c.criado_em[:10]) }}</span><b>{{ c.status }}</b></a>\n        {% else %}<div><span>Nenhum contrato emitido.</span></div>{% endfor %}\n      </div>\n    </section>\n    <section class=\"vg-box\">\n      <header><h3>Rendimentos apurados</h3></header>\n      <div class=\"vg-linhas\">\n        {% for r in rend %}<div><span>{{ '%02d/%d'|format(r.m, r.a) }}</span><b>{{ reais(r.v) }}</b></div>\n        {% else %}<div><span>Sem apurações.</span></div>{% endfor %}\n      </div>\n    </section>\n  </div>\n</div>\n{% endblock %}\n",
  "financas/cap/cond_cotista_form.html": "{% extends \"financas/_layout.html\" %}\n{% import \"financas/cap/_macros.html\" as m with context %}\n{% block fin_titulo %}{{ 'Novo cotista' if modo == 'novo' else 'Editar cotista' }}{% endblock %}\n{% block fin_conteudo %}\n{% call m.cabecalho('Novo cotista' if modo == 'novo' else cli.full_name, 'Dados usados nas cotas, nos contratos e nos pagamentos (Pix / remessa bancária).') %}\n  <a class=\"btn-pill outline fin-btn\" href=\"{{ voltar or (url_for('financas.cond_cotista', slug=empresa.slug, cid=cli.id) if cli.id else url_for('financas.cond_cotistas', slug=empresa.slug)) }}\">{{ ic('arrow_back') }} Voltar</a>\n{% endcall %}\n\n<form method=\"post\" class=\"fin-form co-form\" id=\"f-cli\" autocomplete=\"off\">\n  <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><input type=\"hidden\" name=\"voltar\" value=\"{{ voltar }}\">\n  <div class=\"co-grid\">\n    <section class=\"fin-box\">\n      <div class=\"pe-sec\">Identificação</div>\n      <div class=\"pe-doc\">\n        <div><label class=\"lbl\">CPF / CNPJ *</label>\n          <input class=\"inp\" name=\"cpf\" id=\"co-doc\" maxlength=\"18\" required value=\"{{ cli.cpf or '' }}\" placeholder=\"Digite e o sistema busca os dados\" inputmode=\"numeric\"></div>\n        <button type=\"button\" class=\"btn-pill fin-btn mini\" id=\"co-buscar\">{{ ic('search') }} Buscar</button>\n      </div>\n      <div class=\"pe-msg\" id=\"co-msg\" hidden></div>\n      <label class=\"lbl\">Nome completo *</label>\n      <input class=\"inp\" name=\"full_name\" data-campo=\"nome\" required maxlength=\"160\" value=\"{{ cli.full_name or '' }}\">\n      <div class=\"fin-2col\">\n        <div><label class=\"lbl\">E-mail</label><input class=\"inp\" type=\"email\" name=\"email\" data-campo=\"email\" value=\"{{ cli.email or '' }}\"></div>\n        <div><label class=\"lbl\">Telefone</label><input class=\"inp\" name=\"phone\" data-campo=\"telefone\" value=\"{{ cli.phone or '' }}\" placeholder=\"(00) 00000-0000\"></div>\n      </div>\n      <div class=\"pe-3col\">\n        <div><label class=\"lbl\">Nacionalidade</label><input class=\"inp\" name=\"nationality\" value=\"{{ cli.nationality or '' }}\" placeholder=\"brasileira\"></div>\n        <div><label class=\"lbl\">Estado civil</label>\n          <select class=\"inp\" name=\"marital_status\"><option value=\"\">—</option>\n            {% for x in ['Solteiro(a)', 'Casado(a)', 'União estável', 'Divorciado(a)', 'Separado(a)', 'Viúvo(a)'] %}<option {{ 'selected' if cli.marital_status == x }}>{{ x }}</option>{% endfor %}</select></div>\n        <div><label class=\"lbl\">Profissão</label><input class=\"inp\" name=\"profession\" value=\"{{ cli.profession or '' }}\"></div>\n      </div>\n      <label class=\"lbl\">Situação</label>\n      <select class=\"inp\" name=\"status\" style=\"max-width:200px\"><option value=\"ativo\" {{ 'selected' if cli.status != 'inativo' }}>Ativo</option><option value=\"inativo\" {{ 'selected' if cli.status == 'inativo' }}>Inativo</option></select>\n\n      <div class=\"pe-sec\">Endereço <small>usado no contrato</small></div>\n      <div class=\"pe-3col\">\n        <div><label class=\"lbl\">CEP</label><input class=\"inp\" name=\"address_zip\" id=\"co-cep\" data-campo=\"cep\" maxlength=\"9\" inputmode=\"numeric\" value=\"{{ cli.address_zip or '' }}\"></div>\n        <div style=\"grid-column:span 2\"><label class=\"lbl\">Logradouro, número e complemento</label><input class=\"inp\" name=\"address_street\" data-campo=\"logradouro\" value=\"{{ cli.address_street or '' }}\"></div>\n      </div>\n      <div class=\"pe-3col\">\n        <div><label class=\"lbl\">Bairro</label><input class=\"inp\" name=\"address_district\" data-campo=\"bairro\" value=\"{{ cli.address_district or '' }}\"></div>\n        <div><label class=\"lbl\">Cidade</label><input class=\"inp\" name=\"address_city\" data-campo=\"cidade\" value=\"{{ cli.address_city or '' }}\"></div>\n        <div><label class=\"lbl\">UF</label><input class=\"inp\" name=\"address_state\" data-campo=\"uf\" maxlength=\"2\" style=\"text-transform:uppercase\" value=\"{{ cli.address_state or '' }}\"></div>\n      </div>\n    </section>\n\n    <section class=\"fin-box\">\n      <div class=\"pe-sec\">Pagamento dos rendimentos</div>\n      <label class=\"lbl\">Chave Pix <small class=\"co-dica\">Construção Civil e Saúde pagam por Pix</small></label>\n      <input class=\"inp\" name=\"pix_key\" data-campo=\"pix_chave\" value=\"{{ cli.pix_key or '' }}\" placeholder=\"CPF, e-mail, telefone ou chave aleatória\">\n      <div class=\"pe-sec\">Dados bancários <small>Agronegócio paga por TED (Itaú)</small></div>\n      <label class=\"lbl\">Banco</label><input class=\"inp\" name=\"bank_name\" data-campo=\"banco_nome\" value=\"{{ cli.bank_name or '' }}\" placeholder=\"Ex.: 341 - Itaú\">\n      <div class=\"pe-3col\">\n        <div><label class=\"lbl\">Agência</label><input class=\"inp\" name=\"bank_agency\" data-campo=\"agencia\" value=\"{{ cli.bank_agency or '' }}\"></div>\n        <div><label class=\"lbl\">Conta</label><input class=\"inp\" name=\"bank_account\" data-campo=\"conta\" value=\"{{ cli.bank_account or '' }}\"></div>\n        <div><label class=\"lbl\">Dígito</label><input class=\"inp\" name=\"bank_account_digit\" data-campo=\"conta_dv\" maxlength=\"2\" value=\"{{ cli.bank_account_digit or '' }}\"></div>\n      </div>\n      <label class=\"lbl\">Tipo de conta</label>\n      <select class=\"inp\" name=\"bank_account_type\"><option value=\"\">—</option>{% for x in ['Corrente', 'Poupança'] %}<option {{ 'selected' if cli.bank_account_type == x }}>{{ x }}</option>{% endfor %}</select>\n      <div class=\"fin-2col\">\n        <div><label class=\"lbl\">Titular (se diferente)</label><input class=\"inp\" name=\"bank_holder_name\" value=\"{{ cli.bank_holder_name or '' }}\"></div>\n        <div><label class=\"lbl\">CPF/CNPJ do titular</label><input class=\"inp\" name=\"bank_holder_document\" value=\"{{ cli.bank_holder_document or '' }}\"></div>\n      </div>\n      <label class=\"lbl\">Observações bancárias</label><input class=\"inp\" name=\"bank_notes\" value=\"{{ cli.bank_notes or '' }}\">\n      <div class=\"pe-sec\">Observações</div>\n      <textarea class=\"inp\" name=\"notes\" rows=\"3\" placeholder=\"Anotações internas (opcional)\">{{ cli.notes or '' }}</textarea>\n    </section>\n  </div>\n  <div class=\"lf-barra co-barra\">\n    <span class=\"co-barra-info\">{{ 'Cadastro novo' if modo == 'novo' else 'Alterações ficam registradas no log de auditoria.' }}</span>\n    <a class=\"btn-pill outline fin-btn\" href=\"{{ voltar or url_for('financas.cond_cotistas', slug=empresa.slug) }}\">Cancelar</a>\n    <button class=\"btn-pill fin-btn\" type=\"submit\">{{ ic('check') }} {{ 'Cadastrar cotista' if modo == 'novo' else 'Salvar alterações' }}</button>\n  </div>\n</form>\n\n<script>\n(function () {\n  var f = document.getElementById('f-cli'), doc = document.getElementById('co-doc'), msg = document.getElementById('co-msg'), ultimo = '';\n  var novo = {{ 'true' if modo == 'novo' else 'false' }};\n  function dig(s) { return String(s || '').replace(/\\D/g, ''); }\n  function aviso(t, tipo) { msg.hidden = false; msg.className = 'pe-msg ' + (tipo || ''); msg.innerHTML = t; }\n  function mascara() {\n    var d = dig(doc.value).slice(0, 14);\n    doc.value = d.length <= 11 ? d.replace(/(\\d{3})(\\d)/, '$1.$2').replace(/(\\d{3})(\\d)/, '$1.$2').replace(/(\\d{3})(\\d{1,2})$/, '$1-$2')\n      : d.replace(/^(\\d{2})(\\d)/, '$1.$2').replace(/^(\\d{2})\\.(\\d{3})(\\d)/, '$1.$2.$3').replace(/\\.(\\d{3})(\\d)/, '.$1/$2').replace(/(\\d{4})(\\d)/, '$1-$2');\n  }\n  function preencher(dados, sobrescrever) {\n    var n = 0;\n    Object.keys(dados).forEach(function (k) {\n      var v = dados[k]; if (!v) return;\n      var el = f.querySelector('[data-campo=\"' + k + '\"]'); if (!el) return;\n      if (k === 'banco_nome' && dados.banco_codigo) v = dados.banco_codigo + ' - ' + v;\n      if (sobrescrever || !el.value) { el.value = v; el.classList.add('pe-auto'); n++; }\n    });\n    return n;\n  }\n  function buscar() {\n    var d = dig(doc.value);\n    if ((d.length !== 11 && d.length !== 14) || d === ultimo) return; ultimo = d;\n    aviso(d.length === 14 ? 'Consultando a Receita Federal…' : 'Verificando CPF…', 'carregando');\n    fetch('{{ url_for(\"financas.cad_pessoas_consulta\", slug=empresa.slug) }}?doc=' + d, {credentials: 'same-origin'})\n      .then(function (r) { return r.json(); }).then(function (j) {\n        if (!j.ok) { aviso(j.msg, 'erro'); return; }\n        if (j.cpf_sem_dados) { aviso(j.msg, ''); return; }\n        var n = preencher(j.dados || {}, novo);\n        aviso('✓ ' + n + ' campo(s) preenchido(s) com dados de ' + j.fonte + '.', 'ok');\n      }).catch(function () { ultimo = ''; aviso('Falha na consulta. Verifique a internet e tente de novo.', 'erro'); });\n  }\n  doc.addEventListener('input', function () { mascara(); var d = dig(doc.value); if (d.length === 14 || (d.length === 11 && novo)) buscar(); });\n  doc.addEventListener('blur', buscar);\n  document.getElementById('co-buscar').addEventListener('click', function () { ultimo = ''; buscar(); });\n  var cep = document.getElementById('co-cep');\n  cep.addEventListener('input', function () { var d = dig(cep.value).slice(0, 8); cep.value = d.length > 5 ? d.slice(0, 5) + '-' + d.slice(5) : d; });\n  cep.addEventListener('blur', function () {\n    var d = dig(cep.value); if (d.length !== 8) return;\n    fetch('https://viacep.com.br/ws/' + d + '/json/').then(function (r) { return r.json(); }).then(function (j) {\n      if (!j.erro) preencher({logradouro: j.logradouro, bairro: j.bairro, cidade: j.localidade, uf: j.uf}, false);\n    }).catch(function () {});\n  });\n})();\n</script>\n{% endblock %}\n",
  "financas/cap/cond_cotistas.html": "{% extends \"financas/_layout.html\" %}\n{% import \"financas/cap/_macros.html\" as m with context %}\n{% block fin_titulo %}Cotistas{% endblock %}\n{% block fin_conteudo %}\n{% call m.cabecalho('Cotistas', 'Todos os clientes dos condomínios, com patrimônio e próximos vencimentos.') %}\n  <a class=\"btn-pill fin-btn\" href=\"{{ url_for('financas.cond_cotista_novo', slug=empresa.slug) }}\">{{ fic('add') }} Novo cliente</a>\n{% endcall %}\n<form class=\"pr-filtros\" method=\"get\"><input class=\"inp\" name=\"q\" value=\"{{ busca }}\" placeholder=\"Buscar nome, CPF ou e-mail\"><button class=\"btn-pill fin-btn mini\">Buscar</button></form>\n<section class=\"vg-box\">\n  <header><h3>{{ lista|length }} cliente(s)</h3><span>Patrimônio ativo {{ reais(lista|sum(attribute='valor')) }}</span></header>\n  <div style=\"overflow-x:auto\">\n  <table class=\"pr-tabela\">\n    <thead><tr><th>Cotista</th><th>CPF/CNPJ</th><th>Contato</th><th class=\"num\">Cotas ativas</th><th class=\"num\">Patrimônio</th><th>Próx. vencimento</th><th>Situação</th></tr></thead>\n    <tbody>\n    {% for c in lista %}\n      <tr class=\"clic\" onclick=\"location.href='{{ url_for('financas.cond_cotista', slug=empresa.slug, cid=c.id) }}'\">\n        <td><b>{{ c.full_name }}</b></td><td class=\"mono\">{{ c.cpf }}</td>\n        <td style=\"font-size:.8rem\">{{ c.email or '' }}<br><span style=\"color:var(--muted)\">{{ c.phone or '' }}</span></td>\n        <td class=\"num\">{{ c.cotas_ativas }}{% if c.pendentes %} <span class=\"pr-st pendente\">+{{ c.pendentes }} pend.</span>{% endif %}</td>\n        <td class=\"num\"><b>{{ reais(c.valor) }}</b></td>\n        <td>{{ data_br(c.prox_venc) if c.prox_venc else '—' }}</td>\n        <td><span class=\"pr-st {{ 'ok' if c.status == 'ativo' else 'neutro' }}\">{{ c.status|capitalize }}</span></td>\n      </tr>\n    {% else %}<tr><td colspan=\"7\" class=\"fin-vazio\">Nenhum cliente encontrado.</td></tr>{% endfor %}\n    </tbody>\n  </table>\n  </div>\n</section>\n{% endblock %}\n",
  "financas/cap/cond_painel.html": "{% extends \"financas/_layout.html\" %}\n{% import \"financas/cap/_macros.html\" as m with context %}\n{% block fin_titulo %}Condomínios{% endblock %}\n{% block fin_conteudo %}\n{% call m.cabecalho('Painel dos condomínios', 'Patrimônio, cotistas, vencimentos e apurações dos três condomínios.') %}\n  <a class=\"btn-pill fin-btn\" href=\"{{ url_for('financas.cond_cota_nova', slug=empresa.slug) }}\">{{ fic('add') }} Nova cota</a>\n  <a class=\"btn-pill fin-btn\" href=\"{{ url_for('financas.cond_apuracao_nova', slug=empresa.slug) }}\">{{ fic('calculo') }} Apurar mês</a>\n{% endcall %}\n\n<div class=\"vg-kpis\">\n  <div class=\"vg-kpi escuro\"><small>{{ fic('predio') }} Patrimônio ativo</small><b>{{ res.patrimonio_fmt }}</b><em>{{ res.cotas_ativas }} cotas ativas</em></div>\n  <a class=\"vg-kpi\" href=\"{{ url_for('financas.cond_cotistas', slug=empresa.slug) }}\"><small>{{ fic('pessoas') }} Cotistas</small><b>{{ res.cotistas }}</b><em>com cota ativa</em></a>\n  <div class=\"vg-kpi\"><small>{{ fic('receber') }} Rendimento mensal</small><b>{{ res.rendimento_fmt }}</b><em>estimado pela taxa de cada produto</em></div>\n  <a class=\"vg-kpi\" href=\"{{ url_for('financas.cond_contratos', slug=empresa.slug) }}\"><small>{{ fic('contrato') }} Pendentes</small><b>{{ res.pendentes }}</b><em>{{ res.valor_pendente_fmt }} aguardando ativação</em></a>\n  <a class=\"vg-kpi\" href=\"{{ url_for('financas.cond_vencimentos', slug=empresa.slug, dias=30) }}\"><small>{{ fic('calendario') }} Vencem em 30 dias</small><b>{{ res.vencem_30 }}</b><em>{{ res.vencidas }} já vencida(s) sem renovação</em></a>\n  <a class=\"vg-kpi {{ 'alerta' if res.retiradas }}\" href=\"{{ url_for('financas.cond_vencimentos', slug=empresa.slug, aba='retiradas') }}\"><small>{{ fic('pagar') }} Retiradas</small><b>{{ res.retiradas }}</b><em>solicitadas</em></a>\n</div>\n\n<div class=\"vg-prods\">\n  {% for p in res.por_produto %}\n  <a class=\"vg-box vg-prod\" href=\"{{ url_for('financas.cond_produto', slug=empresa.slug, code=p.code) }}\" style=\"text-decoration:none;color:inherit;border-top:4px solid {{ p.cor }}\">\n    <header><h3>{{ fic('predio') }} {{ p.nome }}</h3><span>{{ '%.2f'|format(p.default_monthly_rate * 100) }}% a.m.</span></header>\n    <div class=\"vg-big\"><small>Patrimônio</small>{{ reais(p.valor) }}</div>\n    <div class=\"vg-linhas\">\n      <div><span>Cotas ativas · cotistas</span><b>{{ p.ativas }} · {{ p.cotistas }}</b></div>\n      <div><span>Rendimento mensal estimado</span><b>{{ reais(p.rendimento) }}</b></div>\n      <div><span>Pendentes</span><b>{{ p.pendentes }}</b></div>\n      <div class=\"{{ 'risco' if p.vencidas }}\"><span>Vencem em 30 dias · vencidas</span><b>{{ p.venc30 }} · {{ p.vencidas }}</b></div>\n    </div>\n  </a>\n  {% endfor %}\n</div>\n\n{% set tot = res.patrimonio or 1 %}\n<section class=\"vg-box\" style=\"margin-bottom:1rem\">\n  <header><h3>Distribuição do patrimônio</h3></header>\n  <div class=\"pr-barra-h\">{% for p in res.por_produto %}<i style=\"width:{{ 100 * p.valor / tot }}%;background:{{ p.cor }}\"></i>{% endfor %}</div>\n  <div class=\"pr-leg\">{% for p in res.por_produto %}<span style=\"--c:{{ p.cor }}\">{{ p.nome }} {{ '%.1f'|format(100 * p.valor / tot) }}%</span>{% endfor %}</div>\n</section>\n\n{# ── Aquisições x retiradas, mês a mês ── #}\n<section class=\"vg-box\" style=\"margin-bottom:1rem\">\n  <header><h3>Aquisições × retiradas por mês</h3>\n    <form method=\"get\" class=\"mv-per\"><select class=\"inp\" name=\"periodo\" onchange=\"this.form.submit()\">\n      <option value=\"12m\" {{ 'selected' if periodo == '12m' }}>Últimos 12 meses</option>\n      {% for a in anos %}<option value=\"{{ a }}\" {{ 'selected' if periodo == a }}>{{ a }}</option>{% endfor %}\n    </select><input type=\"hidden\" name=\"dias\" value=\"{{ dias }}\"></form></header>\n  <p class=\"fin-sub\" style=\"margin:-.3rem 0 .6rem\">Resultado de cada mês (entradas − retiradas). Clique no condomínio para abrir entradas e retiradas; clique num valor para ver os clientes.\n    Entrada = data de aquisição da cota · retirada = data em que a cota foi retirada (inativada).</p>\n  {% macro cel(v, n, k, tipo) %}{% if n %}<button type=\"button\" class=\"mv-v {{ tipo }}\" data-k=\"{{ k }}|{{ tipo }}\">{{ reais(v) }}<small>{{ n }} cota{{ 's' if n > 1 }}</small></button>{% else %}<span class=\"mv-0\">—</span>{% endif %}{% endmacro %}\n  {% macro liq(v, n) %}{% if n %}<b class=\"{{ 'neg' if v < 0 else ('pos' if v > 0) }}\">{{ reais(v) }}</b>{% else %}<span class=\"mv-0\">—</span>{% endif %}{% endmacro %}\n  <div class=\"mv-wrap\">\n  <table class=\"mv-tab mv-t2\">\n    <thead><tr><th class=\"mv-cab\">Condomínio</th>{% for l in mov.linhas %}<th class=\"num\">{{ l.rotulo }}</th>{% endfor %}<th class=\"num tot\">Total</th></tr></thead>\n    <tbody>\n    {% for c in mov.conds %}{% set t = mov.tot[c.code] %}\n      <tr class=\"mv-cond\" data-g=\"{{ c.code }}\">\n        <td class=\"mv-nome\"><button type=\"button\" class=\"mv-abre\" style=\"--c:{{ COND_CORES.get(c.code) }}\"><i></i>{{ COND_NOMES.get(c.code, c.name) }}<span class=\"mv-seta\">▸</span></button></td>\n        {% for l in mov.linhas %}{% set x = l.c[c.code] %}<td class=\"num\">{{ liq(x.aq_v - x.rt_v, x.aq_n + x.rt_n) }}</td>{% endfor %}\n        <td class=\"num tot\">{{ liq(t.aq_v - t.rt_v, t.aq_n + t.rt_n) }}</td>\n      </tr>\n      <tr class=\"mv-sub\" data-g=\"{{ c.code }}\" hidden><td class=\"mv-rot\">↳ Entradas</td>\n        {% for l in mov.linhas %}{% set x = l.c[c.code] %}<td class=\"num\">{{ cel(x.aq_v, x.aq_n, l.mes ~ '|' ~ c.code, 'aq') }}</td>{% endfor %}\n        <td class=\"num tot\">{{ cel(t.aq_v, t.aq_n, '*|' ~ c.code, 'aq') }}</td></tr>\n      <tr class=\"mv-sub\" data-g=\"{{ c.code }}\" hidden><td class=\"mv-rot\">↳ Retiradas</td>\n        {% for l in mov.linhas %}{% set x = l.c[c.code] %}<td class=\"num\">{{ cel(x.rt_v, x.rt_n, l.mes ~ '|' ~ c.code, 'rt') }}</td>{% endfor %}\n        <td class=\"num tot\">{{ cel(t.rt_v, t.rt_n, '*|' ~ c.code, 'rt') }}</td></tr>\n    {% endfor %}\n    </tbody>\n    <tbody class=\"mv-res\">\n      <tr class=\"mv-cond\" data-g=\"tot\">\n        <td class=\"mv-nome\"><button type=\"button\" class=\"mv-abre\"><i style=\"background:#111827\"></i>Resultado do mês<span class=\"mv-seta\">▸</span></button></td>\n        {% for l in mov.linhas %}<td class=\"num\">{{ liq(l.aq_v - l.rt_v, l.aq_n + l.rt_n) }}</td>{% endfor %}\n        <td class=\"num tot\">{{ liq(mov.geral.aq_v - mov.geral.rt_v, mov.geral.aq_n + mov.geral.rt_n) }}</td>\n      </tr>\n      <tr class=\"mv-sub\" data-g=\"tot\" hidden><td class=\"mv-rot\">↳ Entradas</td>\n        {% for l in mov.linhas %}<td class=\"num\">{{ cel(l.aq_v, l.aq_n, l.mes ~ '|*', 'aq') }}</td>{% endfor %}\n        <td class=\"num tot\">{{ cel(mov.geral.aq_v, mov.geral.aq_n, '*|*', 'aq') }}</td></tr>\n      <tr class=\"mv-sub\" data-g=\"tot\" hidden><td class=\"mv-rot\">↳ Retiradas</td>\n        {% for l in mov.linhas %}<td class=\"num\">{{ cel(l.rt_v, l.rt_n, l.mes ~ '|*', 'rt') }}</td>{% endfor %}\n        <td class=\"num tot\">{{ cel(mov.geral.rt_v, mov.geral.rt_n, '*|*', 'rt') }}</td></tr>\n    </tbody>\n  </table>\n  </div>\n</section>\n\n<div class=\"vg-cols\">\n  <section class=\"vg-box\">\n    <header><h3>Vencimentos — próximos {{ dias }} dias</h3>\n      <span class=\"mv-dias\">{% for n in [15, 30, 60, 90] %}<a class=\"{{ 'on' if dias == n }}\" href=\"?dias={{ n }}&periodo={{ periodo }}\">{{ n }}d</a>{% endfor %}</span></header>\n    <p class=\"fin-sub\" style=\"margin:-.3rem 0 .5rem\">{{ n_cli_venc }} cliente(s) · {{ n_cotas_venc }} cota(s) · <b>{{ reais(venc_total) }}</b>. Clique no dia para ver os clientes e no cliente para ver as cotas.</p>\n    <div class=\"vc-lista\">\n      {% for dia in venc_dias %}\n      <details class=\"vc-dia\">\n        <summary>\n          <span class=\"vc-data\"><b>{{ data_br(dia.data) }}</b><small>{{ dia.sem }}</small></span>\n          <span class=\"vc-nome\"><small>{{ dia.clientes|length }} cliente{{ 's' if dia.clientes|length > 1 }} · {{ dia.n }} cota{{ 's' if dia.n > 1 }}</small></span>\n          <span class=\"vc-tot\">{{ reais(dia.total) }}</span>\n        </summary>\n        <div class=\"vc-clis\">\n        {% for c in dia.clientes %}\n          <details class=\"vc-cli\">\n            <summary><span class=\"vc-nome\"><b>{{ c.nome }}</b><small>{{ c.cotas|length }} cota{{ 's' if c.cotas|length > 1 }}</small></span><span class=\"vc-tot\">{{ reais(c.total) }}</span></summary>\n            <table class=\"pr-tabela\">\n              <thead><tr><th>Produto</th><th>Cota</th><th class=\"num\">Valor</th><th></th></tr></thead>\n              <tbody>{% for s in c.cotas %}<tr><td>{{ COND_NOMES[s.code] }}</td><td class=\"mono\">{{ s.share_number }}</td><td class=\"num\">{{ reais(s.share_value) }}</td>\n                <td class=\"num\"><a class=\"fin-link\" href=\"{{ url_for('financas.cond_cota_editar', slug=empresa.slug, sid=s.id) }}\">abrir</a></td></tr>{% endfor %}</tbody>\n            </table>\n            <div class=\"vc-links\"><a class=\"fin-link\" href=\"{{ url_for('financas.cond_cotista', slug=empresa.slug, cid=c.client_id) }}\">Abrir cotista →</a>\n              <a class=\"fin-link\" href=\"{{ url_for('financas.cond_vencimentos', slug=empresa.slug, dias=dias) }}\">Renovar / retirar →</a></div>\n          </details>\n        {% endfor %}\n        </div>\n      </details>\n      {% else %}<p class=\"fin-vazio\">Nenhuma cota vence nos próximos {{ dias }} dias.</p>{% endfor %}\n    </div>\n  </section>\n  <section class=\"vg-box\">\n    <header><h3>Últimas apurações</h3><a href=\"{{ url_for('financas.cond_apuracao', slug=empresa.slug) }}\">Histórico</a></header>\n    <div class=\"vg-linhas\">\n      {% for a in ultimas %}\n        <a href=\"{{ url_for('financas.cond_apuracao_detalhe', slug=empresa.slug, calc_id=a.id) }}\"><span>{{ '%02d'|format(a.calculation_month) }}/{{ a.calculation_year }} · {{ COND_NOMES.get(a.code, 'Todos') }}</span><b>{{ reais(a.total) }}</b></a>\n      {% else %}<div><span>Nenhuma apuração registrada.</span></div>{% endfor %}\n    </div>\n  </section>\n</div>\n\n{# detalhe ao clicar num valor da tabela #}\n<dialog class=\"dlg fin-dlg mv-dlg\" id=\"dlg-mov\">\n  <div class=\"dlg-head\"><h3 id=\"mv-tit\"></h3><button type=\"button\" class=\"ico\" data-fechar>{{ ic('close') }}</button></div>\n  <p class=\"fin-sub\" id=\"mv-sub\"></p>\n  <table class=\"pr-tabela\"><thead><tr><th>Data</th><th></th><th>Produto</th><th>Cota</th><th class=\"num\">Valor</th></tr></thead><tbody id=\"mv-corpo\"></tbody>\n    <tfoot><tr><td colspan=\"4\"><b>Total</b></td><td class=\"num\"><b id=\"mv-total\"></b></td></tr></tfoot></table>\n</dialog>\n{% set det = {} %}\n{% for l in mov.linhas %}{% for code, x in l.c.items() %}{% if x.aq or x.rt %}{% set _ = pyset(det, l.mes ~ '|' ~ code, {'aq': x.aq, 'rt': x.rt}) %}{% endif %}{% endfor %}{% endfor %}\n<script>\n(function () {\n  var DET = {{ det | tojson }}, NOMES = {{ COND_NOMES | tojson }}, ROT = {}, dlg = document.getElementById('dlg-mov');\n  {% for l in mov.linhas %}ROT['{{ l.mes }}'] = '{{ l.rotulo }}';{% endfor %} ROT['*'] = 'Período todo';\n  function br(v) { return 'R$ ' + Number(v).toLocaleString('pt-BR', {minimumFractionDigits: 2, maximumFractionDigits: 2}); }\n  function dt(s) { return s ? s.slice(8, 10) + '/' + s.slice(5, 7) + '/' + s.slice(0, 4) : ''; }\n  function esc(s) { return String(s || '').replace(/[&<>]/g, function (c) { return {'&': '&amp;', '<': '&lt;', '>': '&gt;'}[c]; }); }\n  var URL_CLI = '{{ url_for(\"financas.cond_cotista\", slug=empresa.slug, cid=0) }}'.replace(/0$/, '');\n  document.querySelectorAll('.mv-cond').forEach(function (tr) {\n    tr.addEventListener('click', function (e) {\n      if (e.target.closest('.mv-v')) return;\n      var g = tr.dataset.g, abre = !tr.classList.contains('aberto');\n      tr.classList.toggle('aberto', abre);\n      document.querySelectorAll('.mv-sub[data-g=\"' + g + '\"]').forEach(function (x) { x.hidden = !abre; });\n    });\n  });\n  document.querySelectorAll('.mv-v').forEach(function (b) {\n    b.addEventListener('click', function () {\n      var k = b.dataset.k.split('|'), mes = k[0], code = k[1], tp = k[2], itens = [];\n      Object.keys(DET).forEach(function (chave) {\n        var p = chave.split('|'); if ((mes !== '*' && p[0] !== mes) || (code !== '*' && p[1] !== code)) return;\n        DET[chave][tp].forEach(function (x) { itens.push(Object.assign({code: p[1]}, x)); });\n      });\n      itens.sort(function (a, b) { return a.dt < b.dt ? -1 : a.dt > b.dt ? 1 : a.cli.localeCompare(b.cli); });\n      document.getElementById('mv-tit').textContent = (tp === 'aq' ? 'Aquisições' : 'Retiradas') + ' · ' + ROT[mes] + (code !== '*' ? ' · ' + NOMES[code] : '');\n      // agrupa por cliente no subtítulo\n      var porCli = {}; itens.forEach(function (x) { porCli[x.cli] = (porCli[x.cli] || 0) + x.v; });\n      document.getElementById('mv-sub').textContent = Object.keys(porCli).length + ' cliente(s) · ' + itens.length + ' cota(s)';\n      var grupos = {}, ordem = [];\n      itens.forEach(function (x) { if (!grupos[x.cid]) { grupos[x.cid] = {cli: x.cli, cid: x.cid, v: 0, l: []}; ordem.push(x.cid); } grupos[x.cid].v += x.v; grupos[x.cid].l.push(x); });\n      ordem.sort(function (a, b) { return grupos[b].v - grupos[a].v; });\n      document.getElementById('mv-corpo').innerHTML = ordem.map(function (id) {\n        var g = grupos[id];\n        return '<tr class=\"mv-gcli\"><td colspan=\"4\"><a href=\"' + URL_CLI + g.cid + '\">' + esc(g.cli) + '</a> <small>' + g.l.length + ' cota' + (g.l.length > 1 ? 's' : '') + '</small></td><td class=\"num\"><b>' + br(g.v) + '</b></td></tr>' +\n          g.l.map(function (x) { return '<tr class=\"mv-gcota\"><td>' + dt(x.dt) + '</td><td></td><td>' + esc(NOMES[x.code]) + '</td><td class=\"mono\">' + esc(x.cota) + '</td><td class=\"num\">' + br(x.v) + '</td></tr>'; }).join('');\n      }).join('');\n      document.getElementById('mv-total').textContent = br(itens.reduce(function (a, x) { return a + x.v; }, 0));\n      dlg.showModal();\n    });\n  });\n})();\n</script>\n{% endblock %}\n",
  "financas/cap/cond_produto.html": "{% extends \"financas/_layout.html\" %}\n{% import \"financas/cap/_macros.html\" as m with context %}\n{% block fin_titulo %}{{ COND_NOMES[code] }}{% endblock %}\n{% block fin_conteudo %}\n{% call m.cabecalho(COND_NOMES[code], ('%.2f'|format(cond.default_monthly_rate * 100)) ~ '% a.m. · pagamento no dia ' ~ cond.payment_day) %}\n  <a class=\"btn-pill fin-btn\" href=\"{{ url_for('financas.cond_cota_nova', slug=empresa.slug, produto=code) }}\">{{ fic('add') }} Nova cota</a>\n  <a class=\"btn-pill outline fin-btn\" href=\"{{ url_for('financas.cond_apuracao_nova', slug=empresa.slug, produto=code) }}\">{{ fic('calculo') }} Apurar mês</a>\n{% endcall %}\n\n<div class=\"vg-kpis\">\n  <div class=\"vg-kpi escuro\"><small>Patrimônio ativo</small><b>{{ reais(prod.valor) }}</b><em>{{ prod.ativas }} cotas</em></div>\n  <div class=\"vg-kpi\"><small>Cotistas</small><b>{{ prod.cotistas }}</b><em>com cota ativa</em></div>\n  <div class=\"vg-kpi\"><small>Rendimento mensal</small><b>{{ reais(prod.rendimento) }}</b><em>estimado</em></div>\n  <div class=\"vg-kpi\"><small>Pendentes</small><b>{{ prod.pendentes }}</b><em>{{ reais(prod.valor_pend) }}</em></div>\n  <div class=\"vg-kpi\"><small>Vencem em 30 dias</small><b>{{ prod.venc30 }}</b><em>cotas</em></div>\n  <div class=\"vg-kpi {{ 'alerta' if prod.vencidas }}\"><small>Vencidas</small><b>{{ prod.vencidas }}</b><em>sem renovação registrada</em></div>\n</div>\n\n<form class=\"pr-filtros\" method=\"get\">\n  <input class=\"inp\" name=\"q\" value=\"{{ busca }}\" placeholder=\"Buscar cotista, CPF ou nº da cota\">\n  <div class=\"pr-abas\" style=\"margin:0\">\n    {% for k, rot in [('ativa','Ativas'),('pendente','Pendentes'),('inativa','Inativas'),('todas','Todas')] %}\n      <a class=\"{{ 'on' if status == k }}\" href=\"?status={{ k }}{{ '&q=' ~ busca if busca }}\">{{ rot }}</a>\n    {% endfor %}\n  </div>\n  <input type=\"hidden\" name=\"status\" value=\"{{ status }}\">\n</form>\n\n<section class=\"vg-box\">\n  <header><h3>{{ cotas|length }} cota(s)</h3><span>Total {{ reais(cotas|sum(attribute='share_value')) }}</span></header>\n  <div style=\"overflow-x:auto\">\n  <table class=\"pr-tabela\">\n    <thead><tr><th>Cota</th><th>Cotista</th><th class=\"num\">Valor</th><th>Aquisição</th><th>Últ. renovação</th><th>Vencimento</th><th>Status</th><th></th></tr></thead>\n    <tbody>\n    {% for s in cotas %}\n      <tr>\n        <td class=\"mono\"><a href=\"{{ url_for('financas.cond_cota_editar', slug=empresa.slug, sid=s.id) }}\">{{ s.share_number }}</a></td>\n        <td><a href=\"{{ url_for('financas.cond_cotista', slug=empresa.slug, cid=s.client_id) }}\">{{ s.cliente }}</a></td>\n        <td class=\"num\">{{ reais(s.share_value) }}</td>\n        <td>{{ data_br(s.acquisition_date) if s.acquisition_date else '—' }}</td>\n        <td>{{ data_br(s.last_renewal_date) if s.last_renewal_date else '—' }}</td>\n        <td style=\"{{ 'color:var(--fin-neg);font-weight:600' if s.status == 'ativa' and s.maturity_date and s.maturity_date < hoje }}\">{{ data_br(s.maturity_date) if s.maturity_date else '—' }}</td>\n        <td>{{ m.status_cota(s.status) }}{% if s.withdrawal_requested %} <span class=\"pr-st risco\">Retirada</span>{% endif %}</td>\n        <td class=\"num\"><a class=\"fin-link\" href=\"{{ url_for('financas.cond_cota_editar', slug=empresa.slug, sid=s.id) }}\">editar</a></td>\n      </tr>\n    {% else %}<tr><td colspan=\"8\" class=\"fin-vazio\">Nenhuma cota encontrada.</td></tr>{% endfor %}\n    </tbody>\n  </table>\n  </div>\n</section>\n{% endblock %}\n",
  "financas/cap/cond_termo.html": "{% extends \"financas/_layout.html\" %}\n{% import \"financas/cap/_macros.html\" as m with context %}\n{% set ren = tipo == 'renovacao' %}\n{% block fin_titulo %}{{ 'Renovar cotas' if ren else 'Retirada de cotas' }}{% endblock %}\n{% block fin_conteudo %}\n{% call m.cabecalho('Renovar cotas' if ren else 'Retirada de cotas',\n   'Confira as cotas de cada cliente antes de confirmar. Ao confirmar, as cotas são ' ~ ('renovadas' if ren else 'marcadas em retirada')\n   ~ ' e o ' ~ TIPOS[tipo] ~ ' é gerado para o cliente assinar.', 'Condomínios') %}\n  <a class=\"btn-pill outline fin-btn\" href=\"{{ voltar }}\">{{ ic('arrow_back') }} Voltar</a>\n{% endcall %}\n\n{% if not grupos %}\n<section class=\"vg-box\"><p class=\"fin-vazio\">Nenhuma cota selecionada.</p></section>\n{% else %}\n<form method=\"post\" class=\"tm-form\" id=\"tm-form\">\n  <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><input type=\"hidden\" name=\"voltar\" value=\"{{ voltar }}\">\n  <input type=\"hidden\" name=\"grupos\" value=\"{{ grupos|length }}\">\n  {% for g in grupos %}{% set gi = loop.index0 %}{% set pd = PRODUTOS_DOC.get(g.cond.code, {}) %}\n  <section class=\"vg-box tm-grupo\" data-g=\"{{ gi }}\">\n    <input type=\"hidden\" name=\"g{{ gi }}_cliente\" value=\"{{ g.cliente.id }}\"><input type=\"hidden\" name=\"g{{ gi }}_produto\" value=\"{{ g.cond.id }}\">\n    <header><h3>{{ g.cliente.full_name }}</h3><span>{{ COND_NOMES.get(g.cond.code, g.cond.name) }} · {{ g.cotas|length }} cota(s) ativa(s)</span></header>\n    {% if g.falta %}<p class=\"co-aviso\">Cadastro incompleto — falta {{ g.falta|join(', ') }}. Sem isso o termo não é gerado e nada é alterado.\n      <a href=\"{{ url_for('financas.cond_cotista_editar', slug=empresa.slug, cid=g.cliente.id, voltar=request.full_path) }}\">Completar cadastro</a></p>{% endif %}\n\n    <div class=\"tm-sel\">\n      <span><b class=\"js-n\">0</b> de {{ g.cotas|length }} selecionada(s) · <b class=\"js-tot\">R$ 0,00</b></span>\n      <button type=\"button\" class=\"fin-link js-todas\">Marcar todas</button><button type=\"button\" class=\"fin-link js-nenhuma\">Desmarcar</button>\n    </div>\n    <div class=\"tm-cotas\">\n      {% for c in g.cotas %}\n        <label class=\"tm-cota {{ 'off' if c.bloqueio }}\" title=\"{{ c.bloqueio }}\">\n          <input type=\"checkbox\" name=\"g{{ gi }}_ids\" value=\"{{ c.id }}\" data-v=\"{{ c.share_value }}\" {{ 'checked' if c.id in g.marcadas and not c.bloqueio }} {{ 'disabled' if c.bloqueio }}>\n          <span class=\"mono\"><b>{{ c.share_number }}</b></span><span>{{ reais(c.share_value) }}</span>\n          <small>{{ c.bloqueio or ('vence ' ~ data_br(c.maturity_date) if c.maturity_date else 'sem vencimento') }}</small>\n        </label>\n      {% endfor %}\n    </div>\n\n    <div class=\"pe-3col\">\n      <div><label class=\"lbl\">{{ 'Data da renovação' if ren else 'Pedido em' }}</label><input class=\"inp\" type=\"date\" name=\"g{{ gi }}_data\" value=\"{{ g.data }}\" required></div>\n      <div><label class=\"lbl\">{{ 'Novo vencimento' if ren else 'Efetiva em' }}</label><input class=\"inp\" type=\"date\" name=\"g{{ gi }}_venc\" value=\"{{ g.venc }}\" required></div>\n      {% if not ren %}<div><label class=\"lbl\">Valor da retirada (R$)</label><input class=\"inp num js-valor\" name=\"g{{ gi }}_valor\" placeholder=\"soma das cotas\"></div>{% endif %}\n    </div>\n    {% if not ren %}<p class=\"co-dica\">A cota continua ativa e rende até a data efetiva. No termo: crédito {{ pd.prazo_credito }} a contar da assinatura.\n      Deixe o valor em branco para usar a soma das cotas selecionadas.</p>{% endif %}\n    <label class=\"lbl\">Observação (vai para o histórico da cota)</label><input class=\"inp\" name=\"g{{ gi }}_obs\">\n    <label class=\"co-chk\"><input type=\"checkbox\" name=\"g{{ gi }}_termo\" value=\"1\" {{ 'checked' if g.modelo and not g.falta }} {{ 'disabled' if not g.modelo }}>\n      <span><b>Gerar o {{ TIPOS[tipo] }} para o cliente assinar</b>\n        <small>{% if auto %}Vai direto para o e-mail do cliente.{% else %}Fica pronto na tela do contrato; você confere e clica em “Enviar para assinatura”.{% endif %}</small></span></label>\n  </section>\n  {% endfor %}\n  <div class=\"tm-acoes\">\n    <a class=\"btn-pill outline fin-btn\" href=\"{{ voltar }}\">Cancelar</a>\n    <button class=\"btn-pill fin-btn\" id=\"tm-ok\">{{ ic('check') }} {{ 'Renovar e gerar termo' if ren else 'Marcar retirada e gerar termo' }}</button>\n  </div>\n</form>\n<script>\n(function () {\n  function brl(v) { return v.toLocaleString('pt-BR', {style: 'currency', currency: 'BRL'}); }\n  document.querySelectorAll('.tm-grupo').forEach(function (g) {\n    var cx = g.querySelectorAll('input[type=checkbox][data-v]:not([disabled])');\n    function at() {\n      var n = 0, t = 0;\n      cx.forEach(function (c) { if (c.checked) { n++; t += parseFloat(c.dataset.v) || 0; } c.closest('.tm-cota').classList.toggle('on', c.checked); });\n      g.querySelector('.js-n').textContent = n; g.querySelector('.js-tot').textContent = brl(t);\n      var v = g.querySelector('.js-valor'); if (v) v.placeholder = 'soma: ' + brl(t);\n    }\n    cx.forEach(function (c) { c.addEventListener('change', at); });\n    g.querySelector('.js-todas').addEventListener('click', function () { cx.forEach(function (c) { c.checked = true; }); at(); });\n    g.querySelector('.js-nenhuma').addEventListener('click', function () { cx.forEach(function (c) { c.checked = false; }); at(); });\n    at();\n  });\n  document.getElementById('tm-form').addEventListener('submit', function (e) {\n    var n = document.querySelectorAll('.tm-grupo input[type=checkbox][data-v]:checked').length;\n    if (!n) { e.preventDefault(); alert('Selecione ao menos uma cota.'); return; }\n    if (!confirm('Confirmar {{ \"a renovação\" if ren else \"a retirada\" }} de ' + n + ' cota(s)?')) e.preventDefault();\n  });\n})();\n</script>\n{% endif %}\n{% endblock %}\n",
  "financas/cap/cond_vencimentos.html": "{% extends \"financas/_layout.html\" %}\n{% import \"financas/cap/_macros.html\" as m with context %}\n{% block fin_titulo %}Vencimentos e retiradas{% endblock %}\n{% block fin_conteudo %}\n{% set aqui = request.full_path.rstrip('?') %}\n{% call m.cabecalho('Vencimentos e retiradas', 'Renove, marque retiradas e finalize as saídas — individualmente ou em lote.') %}{% endcall %}\n<div class=\"pr-abas\">\n  <a class=\"{{ 'on' if aba == 'vencimentos' }}\" href=\"?aba=vencimentos&dias={{ dias }}\">Próximos vencimentos</a>\n  <a class=\"{{ 'on' if aba == 'vencidas' }}\" href=\"?aba=vencidas\">Vencidas sem renovação</a>\n  <a class=\"{{ 'on' if aba == 'retiradas' }}\" href=\"?aba=retiradas\">Retiradas solicitadas</a>\n</div>\n{% if aba == 'vencimentos' %}\n<div class=\"pr-abas\">{% for n in [15, 30, 60, 90] %}<a class=\"{{ 'on' if dias == n }}\" href=\"?aba=vencimentos&dias={{ n }}\">{{ n }} dias</a>{% endfor %}</div>\n{% endif %}\n\n<section class=\"vg-box\">\n  <header><h3>{{ lista|length }} cota(s)</h3><span>Total {{ reais(total) }}</span></header>\n  {% if aba != 'retiradas' and lista %}\n  <div class=\"vc-lote\" id=\"vc-lote\" hidden>\n    <b id=\"vc-n\">0</b> selecionada(s)\n    <button type=\"button\" class=\"btn-pill fin-btn mini\" data-lote=\"renovar\">{{ ic('autorenew') }} Renovar selecionadas</button>\n    <button type=\"button\" class=\"btn-pill outline fin-btn mini\" data-lote=\"retirar\">{{ ic('event') }} Marcar retirada</button>\n  </div>\n  {% endif %}\n  <div style=\"overflow-x:auto\">\n  <table class=\"pr-tabela vc-tab\">\n    <thead><tr>\n      {% if aba != 'retiradas' %}<th><input type=\"checkbox\" id=\"vc-todas\" title=\"Selecionar todas\"></th>{% endif %}\n      <th>{{ 'Efetiva em' if aba == 'retiradas' else 'Vencimento' }}</th><th>Cotista</th><th>Produto</th><th>Cota</th><th class=\"num\">Valor</th><th class=\"num\">Ações</th></tr></thead>\n    <tbody>\n    {% for s in lista %}\n      {% set dt = (s.withdrawal_effective_date or s.maturity_date) if aba == 'retiradas' else s.maturity_date %}\n      <tr>\n        {% if aba != 'retiradas' %}<td>{% if not s.withdrawal_requested %}<input type=\"checkbox\" class=\"vc-sel\" value=\"{{ s.id }}\">{% endif %}</td>{% endif %}\n        <td style=\"{{ 'color:var(--fin-neg);font-weight:600' if dt and dt < hoje }}\">{{ data_br(dt) if dt else '—' }}</td>\n        <td><a href=\"{{ url_for('financas.cond_cotista', slug=empresa.slug, cid=s.client_id) }}\"><b>{{ s.cliente }}</b></a>\n          <small class=\"vc-cont\">{{ s.email or '' }}{{ ' · ' if s.email and s.phone }}{{ s.phone or '' }}</small></td>\n        <td>{{ COND_NOMES[s.code] }}</td>\n        <td class=\"mono\"><a href=\"{{ url_for('financas.cond_cota_editar', slug=empresa.slug, sid=s.id) }}\">{{ s.share_number }}</a></td>\n        <td class=\"num\">{{ reais(s.share_value) }}</td>\n        <td class=\"num vc-acoes\">\n        {% if aba == 'retiradas' %}\n          <form method=\"post\" class=\"vc-f\" action=\"{{ url_for('financas.cond_cota_acao', slug=empresa.slug, sid=s.id, acao='retirada-data') }}\">\n            <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><input type=\"hidden\" name=\"referrer\" value=\"{{ aqui }}\">\n            <input class=\"inp vc-dt\" type=\"date\" name=\"withdrawal_effective_date\" value=\"{{ s.withdrawal_effective_date or '' }}\" onchange=\"this.form.submit()\" title=\"Alterar a data efetiva\"></form>\n          <form method=\"post\" class=\"vc-f\" action=\"{{ url_for('financas.cond_cota_acao', slug=empresa.slug, sid=s.id, acao='cancelar-retirada') }}\" onsubmit=\"return confirm('Cancelar o pedido de retirada da cota {{ s.share_number }}?')\">\n            <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><input type=\"hidden\" name=\"referrer\" value=\"{{ aqui }}\">\n            <button class=\"btn-pill outline fin-btn mini\">Cancelar</button></form>\n          <form method=\"post\" class=\"vc-f\" action=\"{{ url_for('financas.cond_cota_acao', slug=empresa.slug, sid=s.id, acao='inativar-retirada') }}\" onsubmit=\"return confirm('Finalizar a retirada e inativar a cota {{ s.share_number }}?')\">\n            <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><input type=\"hidden\" name=\"referrer\" value=\"{{ aqui }}\">\n            <button class=\"btn-pill fin-btn mini\" {{ 'disabled title=\"Disponível a partir da data efetiva\"' if (s.withdrawal_effective_date or '9') > hoje }}>Finalizar</button></form>\n        {% elif s.withdrawal_requested %}\n          <span class=\"pr-st pendente\">retirada em {{ data_br(s.withdrawal_effective_date) }}</span>\n        {% else %}\n          <a class=\"btn-pill fin-btn mini\" href=\"{{ url_for('financas.cond_termo', slug=empresa.slug, tipo='renovacao', ids=s.id, referrer=aqui) }}\" title=\"Confere as cotas do cliente e gera o Termo de Renovação\">Vai renovar</a>\n          <a class=\"btn-pill outline fin-btn mini\" href=\"{{ url_for('financas.cond_termo', slug=empresa.slug, tipo='retirada', ids=s.id, referrer=aqui) }}\" title=\"Confere as cotas do cliente e gera o Termo de Retirada\">Vai retirar</a>\n        {% endif %}\n        </td>\n      </tr>\n    {% else %}<tr><td colspan=\"7\" class=\"fin-vazio\">Nada por aqui.</td></tr>{% endfor %}\n    </tbody>\n  </table>\n  </div>\n</section>\n\n{# ── diálogo: renovar / retirar com datas escolhidas (individual ou lote) ── #}\n<dialog class=\"dlg fin-dlg\" id=\"dlg-vc\">\n  <div class=\"dlg-head\"><h3 id=\"vc-tit\"></h3><button type=\"button\" class=\"ico\" data-fechar>{{ ic('close') }}</button></div>\n  <div class=\"pr-abas\" id=\"vc-abas\"><a href=\"#\" data-m=\"ren\" class=\"on\">Renovar</a><a href=\"#\" data-m=\"ret\">Marcar retirada</a></div>\n  <form method=\"post\" class=\"fin-form\" id=\"vc-form\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><input type=\"hidden\" name=\"referrer\" value=\"{{ aqui }}\"><input type=\"hidden\" name=\"voltar\" value=\"{{ aqui }}\">\n    <div id=\"vc-ids\"></div>\n    <div data-m=\"ren\"><div class=\"fin-2col\">\n      <div><label class=\"lbl\">Data da renovação</label><input class=\"inp\" type=\"date\" name=\"renewal_date\" id=\"vc-ren\"></div>\n      <div><label class=\"lbl\">Novo vencimento</label><input class=\"inp\" type=\"date\" name=\"new_maturity_date\" id=\"vc-venc\"></div></div></div>\n    <div data-m=\"ret\" hidden><div class=\"fin-2col\">\n      <div><label class=\"lbl\">Pedido em</label><input class=\"inp\" type=\"date\" id=\"vc-ped\"></div>\n      <div><label class=\"lbl\">Efetiva em</label><input class=\"inp\" type=\"date\" id=\"vc-eff\"></div></div>\n      <p class=\"co-dica\">A cota continua ativa e rende até a data efetiva.</p></div>\n    <label class=\"lbl\">Observação</label><input class=\"inp\" id=\"vc-obs\">\n    <div class=\"dlg-acoes\"><button type=\"button\" class=\"btn-pill outline fin-btn\" data-fechar>Cancelar</button><button class=\"btn-pill fin-btn\" id=\"vc-ok\">Confirmar</button></div>\n  </form>\n</dialog>\n\n<script>\n(function () {\n  var dlg = document.getElementById('dlg-vc'), form = document.getElementById('vc-form'), ids = document.getElementById('vc-ids'), modo = 'ren', alvo = null;\n  var U = {\n    um: function (id, a) { return '{{ url_for(\"financas.cond_cota_acao\", slug=empresa.slug, sid=999999, acao=\"X\") }}'.replace('999999', id).replace('/X', '/' + a); },\n    lote: { ren: '{{ url_for(\"financas.cond_cotas_lote\", slug=empresa.slug, acao=\"renovar\") }}', ret: '{{ url_for(\"financas.cond_cotas_lote\", slug=empresa.slug, acao=\"retirar\") }}' }\n  };\n  function maisUmAno(s) { if (!s) return ''; var p = s.split('-'); return (+p[0] + 1) + '-' + p[1] + '-' + (p[1] === '02' && p[2] === '29' ? '28' : p[2]); }\n  function setModo(m) {\n    modo = m;\n    document.querySelectorAll('#vc-abas a').forEach(function (a) { a.classList.toggle('on', a.dataset.m === m); });\n    form.querySelectorAll('div[data-m]').forEach(function (x) { x.hidden = x.dataset.m !== m; });\n  }\n  document.querySelectorAll('#vc-abas a').forEach(function (a) { a.addEventListener('click', function (e) { e.preventDefault(); setModo(a.dataset.m); }); });\n  function abrir(m, dados, lote) {\n    alvo = lote; ids.innerHTML = '';\n    document.getElementById('vc-tit').textContent = lote ? lote.length + ' cota(s) selecionada(s)' : 'Cota ' + dados.n;\n    document.getElementById('vc-ren').value = dados.ren || '{{ hoje }}'; document.getElementById('vc-venc').value = dados.venc || '';\n    document.getElementById('vc-ped').value = dados.ped || '{{ hoje }}'; document.getElementById('vc-eff').value = dados.eff || '';\n    document.getElementById('vc-obs').value = '';\n    form.dataset.id = dados.id || '';\n    if (lote) lote.forEach(function (i) { ids.insertAdjacentHTML('beforeend', '<input type=\"hidden\" name=\"share_ids[]\" value=\"' + i + '\">'); });\n    setModo(m); dlg.showModal();\n  }\n  document.getElementById('vc-ren').addEventListener('change', function () { var v = document.getElementById('vc-venc'); if (!v.value) v.value = maisUmAno(this.value); });\n  form.addEventListener('submit', function () {\n    var obs = document.getElementById('vc-obs').value, ped = document.getElementById('vc-ped').value, eff = document.getElementById('vc-eff').value;\n    function h(n, v) { ids.insertAdjacentHTML('beforeend', '<input type=\"hidden\" name=\"' + n + '\" value=\"' + String(v).replace(/\"/g, '&quot;') + '\">'); }\n    if (alvo) {\n      form.action = U.lote[modo];\n      if (modo === 'ren') h('notes', obs); else { h('request_date', ped); h('effective_date', eff); h('notes', obs); }\n    } else if (modo === 'ren') { form.action = U.um(form.dataset.id, 'renovar'); h('user_note', obs); }\n    else { form.action = U.um(form.dataset.id, 'marcar-retirada'); h('withdrawal_request_date', ped); h('withdrawal_effective_date', eff); h('withdrawal_notes', obs); }\n  });\n  document.querySelectorAll('.vc-mais').forEach(function (b) { b.addEventListener('click', function () { abrir('ren', b.dataset, null); }); });\n\n  // seleção em lote\n  var sel = document.querySelectorAll('.vc-sel'), barra = document.getElementById('vc-lote'), todas = document.getElementById('vc-todas');\n  function marcadas() { return Array.prototype.filter.call(sel, function (c) { return c.checked; }).map(function (c) { return c.value; }); }\n  function atualiza() { if (!barra) return; var n = marcadas().length; barra.hidden = !n; document.getElementById('vc-n').textContent = n; }\n  sel.forEach(function (c) { c.addEventListener('change', atualiza); });\n  if (todas) todas.addEventListener('change', function () { sel.forEach(function (c) { c.checked = todas.checked; }); atualiza(); });\n  var URL_TERMO = { renovar: '{{ url_for(\"financas.cond_termo\", slug=empresa.slug, tipo=\"renovacao\") }}', retirar: '{{ url_for(\"financas.cond_termo\", slug=empresa.slug, tipo=\"retirada\") }}' };\n  document.querySelectorAll('[data-lote]').forEach(function (b) {\n    b.addEventListener('click', function () {\n      location.href = URL_TERMO[b.dataset.lote] + '?ids=' + marcadas().join(',') + '&referrer=' + encodeURIComponent('{{ aqui }}');\n    });\n  });\n})();\n</script>\n{% endblock %}\n",
  "financas/cap/gt_cliente.html": "{% extends \"financas/_layout.html\" %}\n{% import \"financas/cap/_macros.html\" as m with context %}\n{% block fin_titulo %}GT · {{ c.nome if c else 'Novo cliente' }}{% endblock %}\n{% block fin_conteudo %}\n{% call m.cabecalho(c.nome if c else 'Novo cliente', ('Cliente desde ' ~ rotulo(hist[-1].competencia) if hist else 'Cadastro do cliente da Gestão Tática'), 'Gestão Tática') %}\n  <a class=\"btn-pill outline fin-btn\" href=\"{{ url_for('financas.gt_clientes', slug=empresa.slug) }}\">{{ ic('arrow_back') }} Clientes</a>\n{% endcall %}\n\n{% if c %}\n<div class=\"vg-kpis\">\n  <div class=\"vg-kpi escuro\"><small>Saldo atual</small><b>{{ reais(ult.saldo_final if ult and ult.competencia == uc else 0) }}</b><em>{{ rotulo(ult.competencia) if ult else '—' }}</em></div>\n  <div class=\"vg-kpi\"><small>Aportado</small><b>{{ reais(tot.aporte) }}</b><em>total</em></div>\n  <div class=\"vg-kpi\"><small>Saques recebidos</small><b>{{ reais(tot.saque) }}</b><em>rendimentos pagos</em></div>\n  <div class=\"vg-kpi\"><small>Rendimento líquido</small><b>{{ reais(tot.resultado_liquido) }}</b><em>bruto {{ reais(tot.resultado_bruto) }}</em></div>\n  <div class=\"vg-kpi\"><small>Taxa de gestão</small><b>{{ reais(tot.taxa_gestao) }}</b><em>+ {{ reais(tot.tarifa) }} de tarifas</em></div>\n  <div class=\"vg-kpi\"><small>Rentabilidade média</small><b>{{ pct(rent12) }}</b><em>bruta, últimos 12 meses</em></div>\n</div>\n{% endif %}\n\n<div class=\"co-grid co-grid-ed\">\n  <section class=\"vg-box\">\n    {% if cong %}\n      <div class=\"gt-cong-cli\">{{ fic('relogio') }}<div><b>Congelado aguardando saque</b>\n        {% for p in cong %}<span>{{ reais(p.valor) }} · congelado em {{ data_br(p.congelado_em.isoformat()) }} · saque em {{ data_br(p.libera_em.isoformat()) }}\n          ({{ 'faltam ' ~ p.dias ~ ' dias' if p.dias > 0 else 'liberado' }})</span>{% endfor %}</div></div>\n    {% endif %}\n    {% if serie|length > 1 %}\n      {% set mx = serie|map(attribute=1)|max %}{% set mn = serie|map(attribute=1)|min %}\n      <header><h3>Saldo da banca</h3><span>últimos {{ serie|length }} meses</span></header>\n      <svg class=\"gt-graf\" viewBox=\"0 0 600 160\" preserveAspectRatio=\"none\">\n        {% set n = serie|length %}\n        <polyline fill=\"none\" stroke=\"var(--accent, #C7A955)\" stroke-width=\"2.5\" vector-effect=\"non-scaling-stroke\"\n          points=\"{% for s in serie %}{{ 600 * loop.index0 / (n - 1) }},{{ 150 - 140 * ((s[1] - mn) / ((mx - mn) or 1)) }} {% endfor %}\"/>\n      </svg>\n      <div class=\"gt-graf-x\"><span>{{ rotulo(serie[0][0], True) }}</span><span>{{ reais(mn) }} – {{ reais(mx) }}</span><span>{{ rotulo(serie[-1][0], True) }}</span></div>\n    {% endif %}\n    <header style=\"margin-top:.6rem\"><h3>Histórico mensal</h3><span>igual à aba do cliente na planilha</span></header>\n    <div class=\"mv-wrap\">\n    <table class=\"pr-tabela gt-hist\">\n      <thead><tr><th>Mês</th><th class=\"num\">Banca inicial</th><th class=\"num\">Aporte</th><th class=\"num\">Saque</th><th class=\"num\">Congelado</th><th class=\"num\">Retirada</th>\n        <th class=\"num\">Peso</th><th class=\"num\">Montante × peso</th><th class=\"num\">% banca</th><th class=\"num\">Bruto</th><th class=\"num\">Rentab.</th><th class=\"num\">Taxa</th><th class=\"num\">Tarifa</th><th class=\"num\">Líquido</th><th class=\"num\">Saldo final</th></tr></thead>\n      <tbody>\n      {% for h in hist %}\n        <tr class=\"clic {{ '' if h.calculado else 'gt-pend' }}\" onclick=\"location.href='{{ url_for('financas.gt_mes', slug=empresa.slug, comp=h.competencia) }}'\">\n          <td><b>{{ rotulo(h.competencia, True) }}</b></td><td class=\"num\">{{ reais(h.banca_inicial) }}</td>\n          <td class=\"num\">{{ (reais(h.aporte) ~ (' (d' ~ h.dia_aporte ~ ')' if h.dia_aporte else '')) if h.aporte else '—' }}</td>\n          <td class=\"num\">{{ (reais(h.saque) ~ (' (d' ~ h.dia_saque ~ ')' if h.dia_saque else '')) if h.saque else '—' }}</td>\n          <td class=\"num\">{{ (reais(h.congelado) ~ (' (d' ~ h.dia_congel ~ ')' if h.dia_congel else '')) if h.congelado else '—' }}</td>\n          <td class=\"num\">{{ (reais(h.retirada) ~ (' (d' ~ h.dia_retirada ~ ')' if h.dia_retirada else '')) if h.retirada else '—' }}</td><td class=\"num\">{{ '%g'|format(h.peso or 0) }}</td>\n          <td class=\"num\">{{ reais(h.base_calculo) if h.base_calculo is not none else '—' }}</td>\n          <td class=\"num\">{{ pct(h.percentual) if h.percentual is not none else '—' }}</td><td class=\"num\">{{ reais(h.resultado_bruto) if h.resultado_bruto is not none else '—' }}</td>\n          <td class=\"num\">{{ pct(h.rentab) if h.rentab is not none else '—' }}</td><td class=\"num\">{{ reais(h.taxa_gestao) if h.taxa_gestao is not none else '—' }}</td>\n          <td class=\"num\">{{ reais(h.tarifa) if h.tarifa is not none else '—' }}</td><td class=\"num\">{{ reais(h.resultado_liquido) if h.resultado_liquido is not none else '—' }}</td>\n          <td class=\"num\"><b>{{ reais(h.saldo_final) if h.saldo_final is not none else '—' }}</b></td></tr>\n      {% else %}<tr><td colspan=\"15\" class=\"fin-vazio\">Sem movimentos.</td></tr>{% endfor %}\n      </tbody>\n    </table>\n    </div>\n  </section>\n\n  <form method=\"post\" class=\"fin-box fin-form co-lado\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n    <h3>{{ 'Parâmetros' if c else 'Cadastro' }}</h3>\n    <label class=\"lbl\">Nome *</label><input class=\"inp\" name=\"nome\" required value=\"{{ c.nome if c else '' }}\">\n    <div class=\"pe-3col\">\n      <div><label class=\"lbl\">Peso</label><input class=\"inp num\" name=\"peso\" value=\"{{ ('%g'|format(c.peso if c else 1)).replace('.', ',') }}\"></div>\n      <div><label class=\"lbl\">Taxa gestão %</label><input class=\"inp num\" name=\"taxa\" value=\"{{ ('%g'|format((c.taxa_pct if c else 0.25) * 100)).replace('.', ',') }}\"></div>\n      <div><label class=\"lbl\">Tarifa R$</label><input class=\"inp num\" name=\"tarifa\" value=\"{{ ('%g'|format(c.tarifa if c else 67)).replace('.', ',') }}\"></div>\n    </div>\n    <div class=\"fin-2col\">\n      <div><label class=\"lbl\">Dia do saque</label><input class=\"inp\" name=\"dia_saque\" value=\"{{ c.dia_saque if c else 10 }}\"></div>\n      <div><label class=\"lbl\">Situação</label><select class=\"inp\" name=\"ativo\"><option value=\"1\" {{ 'selected' if not c or c.ativo }}>Ativo</option><option value=\"0\" {{ 'selected' if c and not c.ativo }}>Inativo</option></select></div>\n    </div>\n    <label class=\"lbl\">É cotista dos Condomínios?</label>\n    <select class=\"inp\" name=\"client_id\"><option value=\"\">— não —</option>{% for x in cotistas %}<option value=\"{{ x.id }}\" {{ 'selected' if c and c.client_id == x.id }}>{{ x.full_name }}</option>{% endfor %}</select>\n    {% if not c %}\n      <div class=\"pe-sec\">Entrada</div>\n      <div class=\"pe-3col\">\n        <div><label class=\"lbl\">Mês</label><input class=\"inp\" type=\"month\" name=\"comp\" value=\"{{ request.args.get('comp') or trabalho }}\"></div>\n        <div><label class=\"lbl\">Dia do aporte</label><input class=\"inp\" name=\"dia_aporte\"></div>\n        <div><label class=\"lbl\">Aporte R$</label><input class=\"inp num\" name=\"aporte\"></div>\n      </div>\n    {% endif %}\n    <label class=\"lbl\">Observações</label><textarea class=\"inp\" name=\"obs\" rows=\"2\">{{ c.obs if c and c.obs else '' }}</textarea>\n    <p class=\"co-dica\">Peso: 1 = participa com a banca inteira; 0,9 = 90%. Os parâmetros novos valem nos próximos cálculos — os meses já calculados não mudam.</p>\n    <button class=\"btn-pill fin-btn\" style=\"margin-top:.6rem\">{{ ic('check') }} {{ 'Salvar' if c else 'Cadastrar' }}</button>\n  </form>\n</div>\n{% endblock %}\n",
  "financas/cap/gt_clientes.html": "{% extends \"financas/_layout.html\" %}\n{% import \"financas/cap/_macros.html\" as m with context %}\n{% block fin_titulo %}GT · Clientes{% endblock %}\n{% block fin_conteudo %}\n{% call m.cabecalho('Clientes da Gestão Tática', 'Banca atual, aportes, rendimentos pagos e parâmetros de cada cliente.', 'Gestão Tática') %}\n  <a class=\"btn-pill fin-btn\" href=\"{{ url_for('financas.gt_cliente', slug=empresa.slug) }}\">{{ fic('add') }} Novo cliente</a>\n{% endcall %}\n<section class=\"vg-box\">\n  <header><h3>{{ lista|selectattr('ativo')|list|length }} ativo(s) · {{ lista|length }} no total</h3><span>Patrimônio {{ reais(total) }}{{ ' em ' ~ rotulo(uc) if uc }}</span></header>\n  <div class=\"mv-wrap\">\n  <table class=\"pr-tabela\">\n    <thead><tr><th>Cliente</th><th>Situação</th><th>Desde</th><th class=\"num\">Saldo atual</th><th class=\"num\">% da banca</th><th class=\"num\">Aportes</th>\n      <th class=\"num\">Saques</th><th class=\"num\">Rendimento líquido</th><th class=\"num\">Taxa paga</th><th class=\"num\">Congelado a pagar</th><th class=\"num\">Peso · taxa · tarifa</th></tr></thead>\n    <tbody>\n    {% for c in lista %}\n      <tr class=\"clic {{ '' if c.ativo else 'gt-inativo' }}\" onclick=\"location.href='{{ url_for('financas.gt_cliente', slug=empresa.slug, cid=c.id) }}'\">\n        <td><b>{{ c.nome }}</b></td>\n        <td>{% if c.ativo %}<span class=\"pr-st ok\">Ativo</span>{% else %}<span class=\"pr-st neutro\">Inativo</span>{% endif %}</td>\n        <td>{{ rotulo(c.primeiro, True) if c.primeiro else '—' }}</td>\n        <td class=\"num\"><b>{{ reais(c.saldo) if c.saldo else '—' }}</b></td>\n        <td class=\"num\">{{ pct(c.ult.percentual) if c.saldo and c.ult else '—' }}</td>\n        <td class=\"num\">{{ reais(c.aportes) }}</td><td class=\"num\">{{ reais(c.saques) }}</td><td class=\"num\">{{ reais(c.liquido) }}</td>\n        <td class=\"num\">{{ reais(c.taxa_total) }}</td>\n        <td class=\"num\">{{ reais(c.congelado_pagar) if (c.congelado_pagar or 0) > 0.5 else '—' }}</td>\n        <td class=\"num\">{{ '%g'|format(c.peso) }} · {{ pct(c.taxa_pct, 0) }} · {{ reais(c.tarifa) }}</td>\n      </tr>\n    {% else %}<tr><td colspan=\"11\" class=\"fin-vazio\">Nenhum cliente. <a href=\"{{ url_for('financas.gt_importar', slug=empresa.slug) }}\">Importe a planilha</a>.</td></tr>{% endfor %}\n    </tbody>\n  </table>\n  </div>\n</section>\n{% endblock %}\n",
  "financas/cap/gt_importar.html": "{% extends \"financas/_layout.html\" %}\n{% import \"financas/cap/_macros.html\" as m with context %}\n{% block fin_titulo %}GT · Importar planilha{% endblock %}\n{% block fin_conteudo %}\n{% call m.cabecalho('Importar planilha da GT', 'Traz clientes, meses e resultados da planilha “NOVO MODELO GT.xlsx”.', 'Gestão Tática') %}\n  <a class=\"btn-pill outline fin-btn\" href=\"{{ url_for('financas.tatica_painel', slug=empresa.slug) }}\">{{ ic('arrow_back') }} Painel</a>\n{% endcall %}\n{% if encerrada %}\n<section class=\"vg-box gt-vazio\">\n  <h3>{{ ic('lock') }} Planilha encerrada</h3>\n  <p class=\"fin-sub\">A Gestão Tática agora é feita só no sistema. A importação está bloqueada para não sobrescrever os meses apurados aqui.</p>\n  <form method=\"post\" action=\"{{ url_for('financas.gt_planilha', slug=empresa.slug, acao='reativar') }}\" onsubmit=\"return confirm('Liberar a importação da planilha de novo?')\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><button class=\"btn-pill outline fin-btn\">Liberar importação</button></form>\n</section>\n{% else %}\n{% if ja_tem %}\n<section class=\"vg-box gt-encerrar\">\n  <div><b>Já importou e conferiu?</b> Encerre a planilha: daqui em diante a apuração é feita só no sistema e a importação fica bloqueada.</div>\n  <form method=\"post\" action=\"{{ url_for('financas.gt_planilha', slug=empresa.slug, acao='encerrar') }}\" onsubmit=\"return confirm('Encerrar a planilha? A importação fica bloqueada (dá para liberar depois).')\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><button class=\"btn-pill fin-btn\">{{ ic('lock') }} Encerrar planilha</button></form>\n</section>\n{% endif %}\n<div class=\"co-grid\">\n  <form method=\"post\" enctype=\"multipart/form-data\" class=\"fin-box fin-form\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n    <h3 style=\"margin-top:0\">Escolha o arquivo</h3>\n    <input class=\"inp\" type=\"file\" name=\"arquivo\" accept=\".xlsx,.xlsm\" required>\n    {% if ja_tem %}<p class=\"co-aviso\">Já existem {{ ja_tem }} registros mensais. Importar de novo <b>atualiza</b> os meses que estão na planilha\n      (mesmo cliente e mês) e mantém os meses criados aqui no app que não existem na planilha.</p>{% endif %}\n    <button class=\"btn-pill fin-btn\" style=\"margin-top:.8rem\">{{ fic('abrir') }} Importar</button>\n  </form>\n  <section class=\"fin-box\">\n    <h3 style=\"margin-top:0\">O que é importado</h3>\n    <ul class=\"gt-lista\">\n      <li><b>Cada aba de cliente</b> (FLAVIA, LUCIANA…) vira um cliente, com o nome completo que está na aba RESUMO / PERCENTUAL DA BANCA.</li>\n      <li><b>Cada linha (competência)</b> vira um mês do cliente: banca inicial, aporte, saque, retirada, congelamento (com os dias), peso, base,\n        % da banca, resultado bruto, tarifa, taxa de gestão, líquido e saldo final — <b>com os valores exatamente como o Excel calculou</b>.</li>\n      <li><b>Aba ADM</b>: resultado de cada origem (XP, XM, títulos privados, complemento…) e o valor repassado.</li>\n      <li>Abas <b>vermelhas</b> = investidores inativos; as demais entram como ativos.</li>\n      <li>Meses totalmente calculados ficam <b>fechados</b>. Linhas só com lançamentos (ex.: retirada já marcada para o mês seguinte) ficam abertas.</li>\n      <li>Abas RESUMO e PERCENTUAL DA BANCA não precisam ser importadas: o app monta esses totais sozinho.</li>\n    </ul>\n  </section>\n</div>\n{% endif %}\n{% endblock %}\n",
  "financas/cap/gt_mes.html": "{% extends \"financas/_layout.html\" %}\n{% import \"financas/cap/_macros.html\" as m with context %}\n{% block fin_titulo %}GT · Apuração {{ rotulo(comp) }}{% endblock %}\n{% block fin_conteudo %}\n{% set ed = not fechado %}\n{% macro v(x) %}{{ '' if x is none else ('%.2f'|format(x)).replace('.', ',') }}{% endmacro %}\n{% macro dd(x) %}{{ '' if x is none else x }}{% endmacro %}\n{% call m.cabecalho('Apuração · ' ~ rotulo(comp), 'Informe o valor a distribuir: o sistema faz o rateio entre os investidores pela fórmula da planilha.', 'Gestão Tática') %}\n  <a class=\"btn-pill outline fin-btn mini\" href=\"{{ url_for('financas.gt_mes', slug=empresa.slug, comp=anterior) }}\">{{ ic('chevron_left') }} {{ rotulo(anterior, True) }}</a>\n  <a class=\"btn-pill outline fin-btn mini\" href=\"{{ url_for('financas.gt_mes', slug=empresa.slug, comp=proximo) }}\">{{ rotulo(proximo, True) }} {{ ic('chevron_right') }}</a>\n  {% if fechado %}\n    <span class=\"pr-st neutro gt-st\">Fechado</span>\n    <form method=\"post\" action=\"{{ url_for('financas.gt_mes_acao', slug=empresa.slug, comp=comp, acao='reabrir') }}\" onsubmit=\"return confirm('Reabrir {{ rotulo(comp) }} para edição?')\">\n      <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><button class=\"btn-pill outline fin-btn\">{{ ic('lock_open') }} Reabrir</button></form>\n  {% elif movs %}\n    <span class=\"pr-st {{ 'ok' if calculado else 'aviso' }} gt-st\">{{ 'Calculado' if calculado else 'Aberto' }}</span>\n    <form method=\"post\" action=\"{{ url_for('financas.gt_mes_acao', slug=empresa.slug, comp=comp, acao='gerar') }}\" title=\"Inclui os investidores ativos que ainda não estão no mês\">\n      <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><button class=\"btn-pill outline fin-btn\">{{ fic('pessoas') }} Trazer investidores</button></form>\n    {% if calculado %}\n    <form method=\"post\" action=\"{{ url_for('financas.gt_mes_acao', slug=empresa.slug, comp=comp, acao='fechar') }}\" onsubmit=\"return confirm('Fechar {{ rotulo(comp) }}? Os valores ficam travados e o próximo mês parte deles.')\">\n      <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><button class=\"btn-pill fin-btn\">{{ ic('lock') }} Fechar mês</button></form>\n    {% endif %}\n  {% endif %}\n{% endcall %}\n\n{% if not movs %}\n<section class=\"vg-box gt-vazio\">\n  <h3>{{ rotulo(comp) }} ainda não foi aberto</h3>\n  <p class=\"fin-sub\">Entram todos os investidores ativos com a banca de {{ rotulo(anterior) }}, o saque já preenchido com o rendimento líquido do mês anterior\n    e as retiradas dos congelados que completam 60 dias neste mês. Tudo pode ser ajustado antes de calcular.</p>\n  <form method=\"post\" action=\"{{ url_for('financas.gt_mes_acao', slug=empresa.slug, comp=comp, acao='gerar') }}\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><button class=\"btn-pill fin-btn\">{{ fic('add') }} Abrir {{ rotulo(comp) }}</button></form>\n</section>\n{% else %}\n\n<form method=\"post\" id=\"gt-form\" action=\"{{ url_for('financas.gt_mes_salvar', slug=empresa.slug, comp=comp) }}\" autocomplete=\"off\">\n  <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n\n  <div class=\"gt-topo\">\n    <section class=\"vg-box gt-dist\">\n      <header><h3>Valor a distribuir — {{ rotulo(comp) }}</h3><span>divulgação em {{ data_br(divulgacao.isoformat()) }}</span></header>\n      {% if ed %}\n        <div class=\"gt-dist-in\"><span>R$</span><input class=\"inp\" name=\"valor_distribuir\" id=\"gt-valor\" inputmode=\"decimal\" value=\"{{ v(valor) if valor else '' }}\" placeholder=\"0,00\"></div>\n      {% else %}\n        <div class=\"gt-dist-in ro\"><b>{{ reais(valor) }}</b></div>\n      {% endif %}\n      <div class=\"gt-prev\">\n        <div><small>Rentabilidade bruta</small><b id=\"pv-bruta\">{{ (pct(faixa.bruta_min) ~ ' a ' ~ pct(faixa.bruta_max)) if faixa else '—' }}</b></div>\n        <div><small>Rentabilidade líquida</small><b id=\"pv-liq\">{{ (pct(faixa.liq_min) ~ ' a ' ~ pct(faixa.liq_max)) if faixa else '—' }}</b></div>\n        <div><small>Taxa de gestão + tarifas</small><b id=\"pv-taxa\">{{ reais(tot.taxa_gestao + tot.tarifa) }}</b></div>\n        <div><small>Líquido aos investidores</small><b id=\"pv-liqv\">{{ reais(tot.resultado_liquido) }}</b></div>\n      </div>\n      {% if res %}<details class=\"gt-adm\"><summary>Detalhe vindo da planilha (aba ADM)</summary>\n        <div class=\"vg-linhas\">{% for r in res %}<div><span>{{ r.origem }}</span><b>{{ reais(r.valor) }} → {{ reais(r.valor_repassado) }}</b></div>{% endfor %}</div></details>{% endif %}\n    </section>\n    <section class=\"vg-box gt-hist3\">\n      <header><h3>Rentabilidade dos últimos 3 meses</h3><span>menor e maior entre os investidores</span></header>\n      <table class=\"pr-tabela\">\n        <thead><tr><th>Mês</th><th class=\"num\">Distribuído</th><th class=\"num\">Bruta</th><th class=\"num\">Líquida</th></tr></thead>\n        <tbody>\n        {% for f in faixas %}\n          <tr class=\"clic\" onclick=\"location.href='{{ url_for('financas.gt_mes', slug=empresa.slug, comp=f.comp) }}'\"><td><b>{{ rotulo(f.comp, True) }}</b></td><td class=\"num\">{{ reais(f.valor) }}</td>\n            <td class=\"num\">{{ pct(f.bruta_min) }} – {{ pct(f.bruta_max) }}</td><td class=\"num\">{{ pct(f.liq_min) }} – {{ pct(f.liq_max) }}</td></tr>\n        {% else %}<tr><td colspan=\"4\" class=\"fin-vazio\">Sem meses anteriores apurados.</td></tr>{% endfor %}\n        <tr class=\"gt-este\"><td><b>{{ rotulo(comp, True) }}</b> <small>{{ 'prévia' if ed else '' }}</small></td><td class=\"num\" id=\"pv-valor\">{{ reais(valor) }}</td>\n          <td class=\"num\" id=\"pv-bruta2\">{{ (pct(faixa.bruta_min) ~ ' – ' ~ pct(faixa.bruta_max)) if faixa else '—' }}</td>\n          <td class=\"num\" id=\"pv-liq2\">{{ (pct(faixa.liq_min) ~ ' – ' ~ pct(faixa.liq_max)) if faixa else '—' }}</td></tr>\n        </tbody>\n      </table>\n      <p class=\"co-dica\">A rentabilidade varia pelo peso (0,9 rende 90%) e pela taxa de gestão de cada um. A faixa considera só quem ficou com a banca cheia o mês todo (sem aporte nem congelamento no mês).</p>\n    </section>\n  </div>\n\n  <section class=\"vg-box\">\n    <header><h3>Investidores</h3><span>dias = dia do mês (1 a 30) · os resultados se atualizam enquanto você digita</span></header>\n    <div class=\"mv-wrap\">\n    <table class=\"pr-tabela gt-mov\" id=\"gt-mov\">\n      <thead>\n        <tr><th rowspan=\"2\">Investidor</th><th rowspan=\"2\" class=\"num\">Banca inicial</th>\n          <th colspan=\"2\">Aporte</th><th colspan=\"2\">Saque</th><th colspan=\"2\">Congelado</th><th colspan=\"2\">Retirada</th>\n          <th rowspan=\"2\" class=\"num\">Peso</th><th rowspan=\"2\" class=\"num\">Taxa %</th><th rowspan=\"2\" class=\"num\">Tarifa</th>\n          <th rowspan=\"2\" class=\"num gt-c\">Montante × peso</th><th rowspan=\"2\" class=\"num gt-c\">% banca</th><th rowspan=\"2\" class=\"num gt-c\">Bruto</th>\n          <th rowspan=\"2\" class=\"num gt-c\">Rentab.</th><th rowspan=\"2\" class=\"num gt-c\">Taxa gestão</th><th rowspan=\"2\" class=\"num gt-c\">Líquido</th><th rowspan=\"2\" class=\"num gt-c\">Saldo final</th></tr>\n        <tr class=\"gt-g2\"><th>dia</th><th class=\"num\">valor</th><th>dia</th><th class=\"num\">valor</th><th>dia</th><th class=\"num\">valor</th><th>dia</th><th class=\"num\">valor</th></tr>\n      </thead>\n      <tbody>\n      {% for x in movs %}{% set p = 'm' ~ x.id ~ '_' %}\n        <tr class=\"gt-l {{ '' if x.calculado else 'gt-pend' }}\" data-p=\"{{ p }}\" data-ant=\"{{ x.saldo_ant if x.tem_ant else '' }}\"\n            data-taxacli=\"{{ x.taxa_cli }}\" data-tarifacli=\"{{ x.tarifa_cli }}\">\n          <td class=\"gt-nome\"><a href=\"{{ url_for('financas.gt_cliente', slug=empresa.slug, cid=x.gt_cliente_id) }}\"><b>{{ x.nome }}</b></a>\n            {% if ed %}<label class=\"gt-rm\" title=\"Tirar este investidor do mês\"><input type=\"checkbox\" name=\"{{ p }}remover\" value=\"1\"> tirar</label>{% endif %}</td>\n          {% if ed %}\n            <td class=\"num\">{% if x.tem_ant %}<span class=\"gt-ro c-banca\" title=\"Saldo de {{ rotulo(anterior, True) }} − saque − congelado\">{{ reais(x.banca_inicial) }}</span><input type=\"hidden\" name=\"{{ p }}banca\" value=\"{{ v(x.banca_inicial) }}\">\n              {% else %}<input class=\"inp num gt-w\" name=\"{{ p }}banca\" value=\"{{ v(x.banca_inicial) if x.banca_inicial else '' }}\" title=\"Primeiro mês do investidor\">{% endif %}</td>\n            <td><input class=\"inp gt-d\" name=\"{{ p }}dia_aporte\" value=\"{{ dd(x.dia_aporte) }}\"></td><td><input class=\"inp num gt-w\" name=\"{{ p }}aporte\" value=\"{{ v(x.aporte) if x.aporte else '' }}\"></td>\n            <td><input class=\"inp gt-d\" name=\"{{ p }}dia_saque\" value=\"{{ dd(x.dia_saque) }}\"></td><td><input class=\"inp num gt-w\" name=\"{{ p }}saque\" value=\"{{ v(x.saque) if x.saque else '' }}\"></td>\n            <td><input class=\"inp gt-d\" name=\"{{ p }}dia_congel\" value=\"{{ dd(x.dia_congel) }}\"></td><td><input class=\"inp num gt-w\" name=\"{{ p }}congelado\" value=\"{{ v(x.congelado) if x.congelado else '' }}\"></td>\n            <td><input class=\"inp gt-d\" name=\"{{ p }}dia_retirada\" value=\"{{ dd(x.dia_retirada) }}\"></td><td><input class=\"inp num gt-w\" name=\"{{ p }}retirada\" value=\"{{ v(x.retirada) if x.retirada else '' }}\"></td>\n            <td><input class=\"inp num gt-d\" name=\"{{ p }}peso\" value=\"{{ ('%g'|format(x.peso if x.peso is not none else 1)).replace('.', ',') }}\"></td>\n            <td><input class=\"inp num gt-d\" name=\"{{ p }}taxa\" value=\"{{ ('%g'|format((x.taxa_pct if x.taxa_pct is not none else (x.taxa_cli or 0.25)) * 100)).replace('.', ',') }}\"></td>\n            <td><input class=\"inp num gt-d2\" name=\"{{ p }}tarifa\" value=\"{{ v(x.tarifa) if x.tarifa is not none else '' }}\" placeholder=\"{{ v(x.tarifa_cli) }}\"><input type=\"hidden\" name=\"{{ p }}obs\" value=\"{{ x.obs or '' }}\"></td>\n          {% else %}\n            <td class=\"num\">{{ reais(x.banca_inicial) }}</td>\n            <td>{{ dd(x.dia_aporte) }}</td><td class=\"num\">{{ reais(x.aporte) if x.aporte else '—' }}</td>\n            <td>{{ dd(x.dia_saque) }}</td><td class=\"num\">{{ reais(x.saque) if x.saque else '—' }}</td>\n            <td>{{ dd(x.dia_congel) }}</td><td class=\"num\">{{ reais(x.congelado) if x.congelado else '—' }}</td>\n            <td>{{ dd(x.dia_retirada) }}</td><td class=\"num\">{{ reais(x.retirada) if x.retirada else '—' }}</td>\n            <td class=\"num\">{{ '%g'|format(x.peso or 0) }}</td><td class=\"num\">{{ pct(x.taxa_pct, 0) }}</td><td class=\"num\">{{ reais(x.tarifa) }}</td>\n          {% endif %}\n          <td class=\"num gt-c c-base\">{{ reais(x.base_calculo) if x.base_calculo is not none else '—' }}</td>\n          <td class=\"num gt-c c-pct\">{{ pct(x.percentual) if x.percentual is not none else '—' }}</td>\n          <td class=\"num gt-c c-bruto\"><b>{{ reais(x.resultado_bruto) if x.resultado_bruto is not none else '—' }}</b></td>\n          <td class=\"num gt-c c-rent\">{{ pct(x.rentab) if x.rentab is not none else '—' }}</td>\n          <td class=\"num gt-c c-taxa\">{{ reais(x.taxa_gestao) if x.taxa_gestao is not none else '—' }}</td>\n          <td class=\"num gt-c c-liq\">{{ reais(x.resultado_liquido) if x.resultado_liquido is not none else '—' }}</td>\n          <td class=\"num gt-c c-saldo\"><b>{{ reais(x.saldo_final) if x.saldo_final is not none else '—' }}</b></td>\n        </tr>\n      {% endfor %}\n      </tbody>\n      <tfoot><tr><td><b>Total · {{ movs|length }}</b></td><td class=\"num\"><b id=\"t-banca\">{{ reais(tot.banca_inicial) }}</b></td>\n        <td></td><td class=\"num\" id=\"t-aporte\">{{ reais(tot.aporte) }}</td><td></td><td class=\"num\" id=\"t-saque\">{{ reais(tot.saque) }}</td>\n        <td></td><td class=\"num\" id=\"t-cong\">{{ reais(tot.congelado) }}</td><td></td><td class=\"num\" id=\"t-ret\">{{ reais(tot.retirada) }}</td>\n        <td></td><td></td><td class=\"num\" id=\"t-tarifa\">{{ reais(tot.tarifa) }}</td>\n        <td class=\"num gt-c\" id=\"t-base\">{{ reais(tot.base_calculo) }}</td><td class=\"num gt-c\">100%</td><td class=\"num gt-c\"><b id=\"t-bruto\">{{ reais(tot.resultado_bruto) }}</b></td>\n        <td class=\"num gt-c\"></td><td class=\"num gt-c\" id=\"t-taxa\">{{ reais(tot.taxa_gestao) }}</td><td class=\"num gt-c\" id=\"t-liq\">{{ reais(tot.resultado_liquido) }}</td>\n        <td class=\"num gt-c\"><b id=\"t-saldo\">{{ reais(tot.saldo_final) }}</b></td></tr></tfoot>\n    </table>\n    </div>\n    <details class=\"gt-regras\"><summary>Como o rateio é calculado (mesma fórmula da planilha)</summary>\n      <ul class=\"gt-lista\">\n        <li><b>Banca inicial</b> = saldo final do mês anterior − saque − congelado do mês.</li>\n        <li><b>Montante × peso</b> = banca × peso + aporte × peso ÷ 30 × (30 − dia do aporte) + congelado × peso ÷ 30 × dia do congelamento + saque × peso ÷ 30 × dia do saque.\n          Ou seja: o aporte rende a partir do dia em que entra; o saque e o congelado rendem até o dia em que saem.</li>\n        <li><b>% da banca</b> = montante × peso do investidor ÷ soma de todos. <b>Bruto</b> = % × valor a distribuir.</li>\n        <li><b>Taxa de gestão</b> = bruto × taxa %. <b>Líquido</b> = bruto − taxa − tarifa. <b>Saldo final</b> = banca inicial + aporte + líquido.</li>\n        <li><b>Congelado</b>: sai da banca no dia informado e fica 60 dias sem render até o saque. <b>Retirada</b> = o pagamento desse congelado (não altera o saldo).</li>\n      </ul>\n    </details>\n  </section>\n\n  {% if ed %}\n  <div class=\"lf-barra co-barra\">\n    <span class=\"co-barra-info\">Distribuindo <b id=\"pv-barra\">{{ reais(valor) }}</b> entre {{ movs|length }} investidor(es)</span>\n    <button class=\"btn-pill fin-btn\" type=\"submit\">{{ fic('calculo') }} Calcular e salvar</button>\n  </div>\n  {% endif %}\n</form>\n\n{% if ed and fora %}\n<form method=\"post\" class=\"gt-incluir\" action=\"{{ url_for('financas.gt_mes_acao', slug=empresa.slug, comp=comp, acao='incluir') }}\">\n  <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n  <span>Incluir investidor neste mês:</span>\n  <select class=\"inp\" name=\"gt_cliente_id\">{% for c in fora %}<option value=\"{{ c.id }}\">{{ c.nome }}{{ '' if c.ativo else ' (inativo)' }}</option>{% endfor %}</select>\n  <button class=\"btn-pill outline fin-btn mini\">Incluir</button>\n  <a class=\"fin-link\" href=\"{{ url_for('financas.gt_cliente', slug=empresa.slug) }}?comp={{ comp }}\">ou cadastrar investidor novo</a>\n</form>\n{% endif %}\n{% endif %}\n\n{% if ed and movs %}\n<script>\n(function () {\n  function num(s) { s = String(s || '').replace(/[^\\d,.-]/g, ''); if (s.indexOf(',') >= 0 || /^-?\\d{1,3}(\\.\\d{3})+$/.test(s)) s = s.replace(/\\./g, '').replace(',', '.'); return parseFloat(s) || 0; }\n  function br(v) { return 'R$ ' + (v || 0).toLocaleString('pt-BR', {minimumFractionDigits: 2, maximumFractionDigits: 2}); }\n  function pc(v) { return (v * 100).toLocaleString('pt-BR', {minimumFractionDigits: 2, maximumFractionDigits: 2}) + '%'; }\n  var form = document.getElementById('gt-form'), valor = document.getElementById('gt-valor'), linhas = form.querySelectorAll('tr.gt-l');\n  function campo(tr, n) { var i = form.querySelector('[name=\"' + tr.dataset.p + n + '\"]'); return i ? i.value : ''; }\n  function dia(s) { var n = parseInt(s, 10); return isNaN(n) ? 0 : Math.max(0, Math.min(30, n)); }\n  function set(tr, cls, txt) { var c = tr.querySelector('.' + cls); if (c) c.innerHTML = txt; }\n  function calc() {\n    var V = num(valor.value), rows = [], soma = 0;\n    linhas.forEach(function (tr) {\n      if (form.querySelector('[name=\"' + tr.dataset.p + 'remover\"]:checked')) { tr.classList.add('gt-off'); return; }\n      tr.classList.remove('gt-off');\n      var G = num(campo(tr, 'saque')), K = num(campo(tr, 'congelado')), E = num(campo(tr, 'aporte')), I = num(campo(tr, 'retirada'));\n      var L = campo(tr, 'peso').trim() === '' ? 1 : num(campo(tr, 'peso'));\n      var C = tr.dataset.ant !== '' ? parseFloat(tr.dataset.ant) - G - K : num(campo(tr, 'banca'));\n      var M = C * L + E * L / 30 * (30 - dia(campo(tr, 'dia_aporte'))) + K * L / 30 * dia(campo(tr, 'dia_congel')) + G * L / 30 * dia(campo(tr, 'dia_saque'));\n      var taxa = campo(tr, 'taxa').trim() === '' ? parseFloat(tr.dataset.taxacli || 0.25) : num(campo(tr, 'taxa')) / 100;\n      var tar = campo(tr, 'tarifa').trim() === '' ? parseFloat(tr.dataset.tarifacli || 0) : num(campo(tr, 'tarifa'));\n      rows.push({tr: tr, C: C, E: E, G: G, K: K, I: I, M: M, taxa: taxa, tar: tar}); soma += Math.max(M, 0);\n    });\n    var t = {C: 0, E: 0, G: 0, K: 0, I: 0, M: 0, O: 0, tar: 0, S: 0, T: 0, U: 0}, br_ = [], lq_ = [];\n    rows.forEach(function (r) {\n      var M = Math.max(r.M, 0), N = soma ? M / soma : 0, O = N * V, tar = M > 0 ? r.tar : 0, S = O * r.taxa, T = O - S - tar, U = r.C + r.E + T;\n      var Q = r.C > 0 ? O / r.C : (r.E > 0 ? O / r.E : 0);\n      if (r.tr.dataset.ant !== '') set(r.tr, 'c-banca', br(r.C));\n      set(r.tr, 'c-base', br(r.M)); set(r.tr, 'c-pct', pc(N)); set(r.tr, 'c-bruto', '<b>' + br(O) + '</b>'); set(r.tr, 'c-rent', pc(Q));\n      set(r.tr, 'c-taxa', br(S)); set(r.tr, 'c-liq', br(T)); set(r.tr, 'c-saldo', '<b>' + br(U) + '</b>');\n      t.C += r.C; t.E += r.E; t.G += r.G; t.K += r.K; t.I += r.I; t.M += r.M; t.O += O; t.tar += tar; t.S += S; t.T += T; t.U += U;\n      if (r.C > 1 && !r.E && !r.K) { br_.push(O / r.C); lq_.push(T / r.C); }\n    });\n    if (!br_.length) rows.forEach(function (r) { if (r.C > 1) { var O = soma ? Math.max(r.M, 0) / soma * V : 0, tar = r.M > 0 ? r.tar : 0; br_.push(O / r.C); lq_.push((O - O * r.taxa - tar) / r.C); } });\n    var faixa = function (a) { return (a.length && V) ? pc(Math.min.apply(null, a)) + ' a ' + pc(Math.max.apply(null, a)) : '—'; };\n    document.getElementById('pv-bruta').textContent = faixa(br_); document.getElementById('pv-liq').textContent = faixa(lq_);\n    document.getElementById('pv-bruta2').textContent = faixa(br_).replace(' a ', ' – '); document.getElementById('pv-liq2').textContent = faixa(lq_).replace(' a ', ' – ');\n    document.getElementById('pv-taxa').textContent = V ? br(t.S + t.tar) : '—'; document.getElementById('pv-liqv').textContent = V ? br(t.T) : '—';\n    document.getElementById('pv-valor').textContent = br(V); document.getElementById('pv-barra').textContent = br(V);\n    [['t-banca', t.C], ['t-aporte', t.E], ['t-saque', t.G], ['t-cong', t.K], ['t-ret', t.I], ['t-tarifa', t.tar], ['t-base', t.M], ['t-bruto', t.O], ['t-taxa', t.S], ['t-liq', t.T], ['t-saldo', t.U]]\n      .forEach(function (x) { document.getElementById(x[0]).textContent = br(x[1]); });\n  }\n  form.addEventListener('input', calc); form.addEventListener('change', calc);\n  valor.addEventListener('blur', function () { if (valor.value) valor.value = num(valor.value).toLocaleString('pt-BR', {minimumFractionDigits: 2}); });\n  calc();\n  valor.focus();\n})();\n</script>\n{% endif %}\n{% endblock %}\n",
  "financas/cap/gt_painel.html": "{% extends \"financas/_layout.html\" %}\n{% import \"financas/cap/_macros.html\" as m with context %}\n{% block fin_titulo %}Gestão Tática{% endblock %}\n{% block fin_conteudo %}\n{% call m.cabecalho('Painel gerencial', ('Posição de ' ~ rotulo(uc) ~ ' — o último mês apurado.' if uc else 'Importe a planilha ou cadastre os clientes para começar.') , 'Gestão Tática') %}\n  <a class=\"btn-pill fin-btn\" href=\"{{ url_for('financas.gt_mes', slug=empresa.slug, comp=trabalho) }}\">{{ fic('calculo') }} Apurar {{ rotulo(trabalho, True) }}</a>\n{% endcall %}\n\n{% if vazio %}\n<section class=\"vg-box gt-vazio\">\n  <h3>Nenhum dado da Gestão Tática ainda</h3>\n  <p class=\"fin-sub\">Importe a planilha uma única vez para trazer o histórico; depois a apuração é feita só aqui.</p>\n  <a class=\"btn-pill fin-btn\" href=\"{{ url_for('financas.gt_importar', slug=empresa.slug) }}\">{{ fic('abrir') }} Importar planilha</a>\n</section>\n{% else %}\n<p class=\"gt-aviso-div\">{{ fic('calendario') }} Próxima divulgação: <b>{{ data_br(divulgacao.isoformat()) }}</b> — resultado de {{ rotulo(trabalho) }}.</p>\n\n<div class=\"vg-kpis gt-kpis\">\n  <div class=\"vg-kpi escuro\"><small>{{ fic('tatica') }} Total da banca</small><b>{{ reais(total_banca) }}</b><em>saldo final de {{ rotulo(uc, True) }}</em></div>\n  <div class=\"vg-kpi\"><small>{{ fic('receber') }} Rendimento líquido</small><b>{{ reais(atual.liquido if atual else 0) }}</b>\n    <em>bruto {{ reais(atual.bruto if atual else 0) }} · taxa {{ reais(atual.taxa if atual else 0) }}</em></div>\n  <a class=\"vg-kpi\" href=\"{{ url_for('financas.gt_clientes', slug=empresa.slug) }}\"><small>{{ fic('pessoas') }} Investidores</small><b>{{ ativos|length }}</b>\n    <em>{{ ranking|length }} com banca{% if ativos|length > ranking|length %} · {{ ativos|length - ranking|length }} só com congelado{% endif %}</em></a>\n  <div class=\"vg-kpi\"><small>{{ fic('pagar') }} Saques</small><b>{{ reais(atual.saque if atual else 0) }}</b>\n    <em>rendimentos pagos em {{ rotulo(uc, True) }}{% if ret_mes %} · + {{ reais(ret_mes) }} de retiradas{% endif %}</em></div>\n  <div class=\"vg-kpi {{ 'alerta' if total_cong }}\"><small>{{ fic('relogio') }} Congelados</small><b>{{ reais(total_cong) }}</b>\n    <em>{{ cong|length }} aguardando saque (60 dias)</em></div>\n</div>\n\n<div class=\"vg-cols gt-cols\">\n  <section class=\"vg-box\">\n    <header><h3>Ranking dos investidores</h3><span>banca em {{ rotulo(uc, True) }}</span></header>\n    {% set mx = (ranking|map(attribute='saldo')|max) if ranking else 1 %}\n    <ol class=\"gt-rank\">\n      {% for c in ranking %}\n      <li><a href=\"{{ url_for('financas.gt_cliente', slug=empresa.slug, cid=c.id) }}\">\n        <span class=\"gt-pos\">{{ loop.index }}</span>\n        <span class=\"gt-rank-n\"><b>{{ c.nome }}</b><small>{{ pct(c.saldo / (total_banca or 1), 1) }} da banca · peso {{ '%g'|format(c.peso) }} · taxa {{ pct(c.taxa_pct, 0) }}</small>\n          <span class=\"gt-rank-b\"><i style=\"width:{{ 100 * c.saldo / (mx or 1) }}%\"></i></span></span>\n        <b class=\"gt-rank-v\">{{ reais(c.saldo) }}</b></a></li>\n      {% else %}<li class=\"fin-vazio\">Nenhum investidor com banca.</li>{% endfor %}\n    </ol>\n  </section>\n  <section class=\"vg-box\">\n    <header><h3>Valores congelados</h3><span>sem rendimento até o saque</span></header>\n    {% if cong %}\n    <table class=\"pr-tabela gt-cong\">\n      <thead><tr><th>Investidor</th><th class=\"num\">Valor</th><th>Congelado em</th><th>Saque em</th></tr></thead>\n      <tbody>{% for p in cong %}\n        <tr class=\"clic\" onclick=\"location.href='{{ url_for('financas.gt_cliente', slug=empresa.slug, cid=p.gt_cliente_id) }}'\">\n          <td><b>{{ p.cliente }}</b></td><td class=\"num\"><b>{{ reais(p.valor) }}</b></td>\n          <td>{{ data_br(p.congelado_em.isoformat()) }}</td>\n          <td>{{ data_br(p.libera_em.isoformat()) }}<br>{% if p.dias > 0 %}<span class=\"pr-st aviso\">faltam {{ p.dias }} dias</span>{% else %}<span class=\"pr-st risco\">liberado para saque</span>{% endif %}</td></tr>\n      {% endfor %}</tbody>\n      <tfoot><tr><td><b>Total</b></td><td class=\"num\"><b>{{ reais(total_cong) }}</b></td><td colspan=\"2\"></td></tr></tfoot>\n    </table>\n    {% else %}<p class=\"fin-vazio\">Nenhum valor congelado aguardando saque.</p>{% endif %}\n    <p class=\"co-dica\" style=\"margin-top:.6rem\">O congelado rende até o dia do congelamento; depois fica parado {{ 60 }} dias até virar saque (retirada).\n      Ao abrir o mês em que vence, a retirada já entra sugerida na apuração.</p>\n  </section>\n</div>\n\n<section class=\"vg-box\" style=\"margin-top:1rem\">\n  <header><h3>Evolução mês a mês</h3><span>clique no mês para abrir a apuração</span></header>\n  <div class=\"mv-wrap\">\n  <table class=\"pr-tabela gt-tab\">\n    <thead><tr><th>Mês</th><th class=\"num\">Investidores</th><th class=\"num\">Banca inicial</th><th class=\"num\">Aportes</th><th class=\"num\">Distribuído</th>\n      <th class=\"num\">Rentab.</th><th class=\"num\">Taxa gestão</th><th class=\"num\">Líquido</th><th class=\"num\">Saques</th><th class=\"num\">Saldo final</th></tr></thead>\n    <tbody>\n    {% for mm in ult12|reverse %}\n      <tr class=\"clic\" onclick=\"location.href='{{ url_for('financas.gt_mes', slug=empresa.slug, comp=mm.c) }}'\">\n        <td><b>{{ rotulo(mm.c, True) }}</b></td><td class=\"num\">{{ mm.n }}</td><td class=\"num\">{{ reais(mm.banca) }}</td>\n        <td class=\"num\">{{ reais(mm.aporte) if mm.aporte else '—' }}</td><td class=\"num\">{{ reais(mm.distribuido) }}</td>\n        <td class=\"num\">{{ pct(mm.rentab) }}</td><td class=\"num\">{{ reais(mm.taxa) }}</td><td class=\"num\">{{ reais(mm.liquido) }}</td>\n        <td class=\"num\">{{ reais(mm.saque) if mm.saque else '—' }}</td><td class=\"num\"><b>{{ reais(mm.saldo) }}</b></td></tr>\n    {% endfor %}\n    </tbody>\n  </table>\n  </div>\n</section>\n{% endif %}\n{% endblock %}\n",
  "financas/cap/tatica.html": "{% extends \"financas/_layout.html\" %}\n{% import \"financas/cap/_macros.html\" as m with context %}\n{% block fin_titulo %}Gestão Tática{% endblock %}\n{% block fin_conteudo %}\n{% call m.cabecalho('Gestão Tática', 'Esboço do produto — estrutura inicial para validarmos juntos antes de desenvolver.', 'Produto · Gestão Tática') %}\n  <span class=\"vg-tag\">Em construção</span>\n{% endcall %}\n<div class=\"pr-abas\">\n  {% for k, rot in [('painel','Painel'),('clientes','Clientes atendidos'),('entregas','Entregas do mês'),('honorarios','Honorários')] %}\n    <a class=\"{{ 'on' if aba == k }}\" href=\"?aba={{ k }}\">{{ rot }}</a>\n  {% endfor %}\n</div>\n\n<div class=\"vg-kpis\" style=\"grid-template-columns:repeat(4,minmax(0,1fr))\">\n  <div class=\"vg-kpi escuro\"><small>Receitas do mês</small><b>{{ moeda(fin.receitas_mes) }}</b><em>centro de custo “Gestão Tática”</em></div>\n  <div class=\"vg-kpi\"><small>Honorários a receber</small><b>{{ moeda(fin.a_receber) }}</b><em>em aberto</em></div>\n  <div class=\"vg-kpi pr-esboco\"><small>Clientes ativos</small><b>—</b><em>cadastro a criar</em></div>\n  <div class=\"vg-kpi pr-esboco\"><small>Entregas no prazo</small><b>—</b><em>rotina mensal a definir</em></div>\n</div>\n\n{% if aba == 'honorarios' %}\n<section class=\"vg-box\">\n  <header><h3>Honorários em aberto</h3><a href=\"{{ url_for('financas.lancamentos', slug=empresa.slug, tipo='receber') }}\">Contas a receber</a></header>\n  <table class=\"pr-tabela\">\n    <thead><tr><th>Vencimento</th><th>Descrição</th><th>Cliente</th><th class=\"num\">Saldo</th><th>Situação</th></tr></thead>\n    <tbody>\n    {% for l in fin.abertos if l.tipo == 'receber' %}\n      <tr class=\"clic\" onclick=\"location.href='{{ url_for('financas.lancamento', slug=empresa.slug, lid=l.id) }}'\"><td>{{ data_br(l.vencimento) }}</td><td>{{ l.descricao }}</td>\n        <td>{{ l.pessoa_nome or '—' }}</td><td class=\"num\">{{ moeda(l.saldo) }}</td>\n        <td><span class=\"pr-st {{ 'risco' if l.situacao == 'vencido' else 'aviso' }}\">{{ SITUACOES[l.situacao] }}</span></td></tr>\n    {% else %}<tr><td colspan=\"5\" class=\"fin-vazio\">Nenhum honorário em aberto no centro de custo “Gestão Tática”.</td></tr>{% endfor %}\n    </tbody>\n  </table>\n</section>\n{% else %}\n<div class=\"vg-prods\">\n  <section class=\"vg-box pr-esboco\">\n    <header><h3>{{ fic('pessoas') }} Clientes atendidos</h3><span class=\"vg-tag\">Esboço</span></header>\n    <ul>\n      <li>Cadastro das empresas atendidas (ligado a Clientes e fornecedores do ERP)</li>\n      <li>Plano contratado, valor da mensalidade e dia de vencimento</li>\n      <li>Responsável interno e início do contrato</li>\n      <li>Situação: ativo, em implantação, pausado, encerrado</li>\n    </ul>\n  </section>\n  <section class=\"vg-box pr-esboco\">\n    <header><h3>{{ fic('calendario') }} Entregas do mês</h3><span class=\"vg-tag\">Esboço</span></header>\n    <ul>\n      <li>Checklist mensal por cliente (ex.: fechamento, DRE, fluxo de caixa, reunião tática)</li>\n      <li>Prazo, responsável e status de cada entrega</li>\n      <li>Integração com Demandas e cronômetro do módulo Operação (horas por cliente)</li>\n    </ul>\n  </section>\n  <section class=\"vg-box pr-esboco\">\n    <header><h3>{{ fic('receber') }} Honorários e indicadores</h3><span class=\"vg-tag\">Esboço</span></header>\n    <ul>\n      <li>Geração automática das mensalidades em Contas a receber (centro “Gestão Tática”)</li>\n      <li>Receita recorrente (MRR), inadimplência e rentabilidade por cliente (receita ÷ horas)</li>\n      <li>Já funcionando: receitas e honorários lançados no centro de custo aparecem aqui</li>\n    </ul>\n  </section>\n</div>\n<div class=\"pr-aviso\">{{ fic('tatica') }}<div>Me explique como a Gestão Tática funciona hoje (o que é vendido, como cobra e o que é entregue) e eu transformo este esboço nas telas reais.</div></div>\n{% endif %}\n{% endblock %}\n",
  "financas/cap/titulos.html": "{% extends \"financas/_layout.html\" %}\n{% import \"financas/cap/_macros.html\" as m with context %}\n{% block fin_titulo %}Títulos Privados{% endblock %}\n{% block fin_conteudo %}\n{% call m.cabecalho('Títulos Privados', 'Empréstimos privados: carteira, parcelas a receber e atrasos.', 'Produto · Títulos Privados') %}\n  <a class=\"btn-pill fin-btn\" href=\"{{ url_for('titulos_privados_emprestimos') }}\">{{ fic('abrir') }} Abrir no módulo</a>\n{% endcall %}\n<div class=\"vg-kpis\" style=\"grid-template-columns:repeat(4,minmax(0,1fr))\">\n  <div class=\"vg-kpi escuro\"><small>Carteira a receber</small><b>{{ res.a_receber_fmt }}</b><em>{{ res.ativos }} empréstimo(s) ativo(s)</em></div>\n  <div class=\"vg-kpi {{ 'alerta' if res.vencidas }}\"><small>Parcelas vencidas</small><b class=\"{{ 'neg' if res.vencidas }}\">{{ res.vencido_fmt }}</b><em>{{ res.vencidas }} parcela(s)</em></div>\n  <div class=\"vg-kpi\"><small>Próxima parcela</small><b style=\"font-size:1rem\">{{ res.proxima or '—' }}</b><em>em aberto</em></div>\n  <div class=\"vg-kpi\"><small>Recebido no mês (ERP)</small><b>{{ moeda(fin.receitas_mes) }}</b><em>centro de custo do produto</em></div>\n</div>\n<div class=\"pr-abas\">\n  <a class=\"{{ 'on' if aba != 'parcelas' }}\" href=\"?aba=carteira\">Carteira</a>\n  <a class=\"{{ 'on' if aba == 'parcelas' }}\" href=\"?aba=parcelas\">Parcelas a receber</a>\n</div>\n<section class=\"vg-box\">\n{% if aba == 'parcelas' %}\n  <table class=\"pr-tabela\">\n    <thead><tr><th>Vencimento</th><th>Cliente</th><th>Empréstimo</th><th>Parcela</th><th class=\"num\">Principal</th><th class=\"num\">Juros</th><th class=\"num\">Parcela</th><th>Situação</th></tr></thead>\n    <tbody>\n    {% for p in parcelas %}\n      <tr class=\"clic\" onclick=\"location.href='{{ url_for('titulos_privados_emprestimo_detalhe', loan_id=p.loan_id) }}'\">\n        <td>{{ data_br(p.due_date) }}</td><td>{{ p.cliente or '—' }}</td><td class=\"mono\">{{ p.loan_number or ('#' ~ p.loan_id) }}</td>\n        <td>{{ p.installment_number }}</td><td class=\"num\">{{ reais(p.principal_amount) }}</td><td class=\"num\">{{ reais(p.interest_amount) }}</td>\n        <td class=\"num\"><b>{{ reais(p.installment_amount - (p.paid_amount or 0)) }}</b></td>\n        <td>{% if p.due_date < hoje %}<span class=\"pr-st risco\">Vencida</span>{% else %}<span class=\"pr-st aviso\">A vencer</span>{% endif %}</td></tr>\n    {% else %}<tr><td colspan=\"8\" class=\"fin-vazio\">Nenhuma parcela em aberto.</td></tr>{% endfor %}\n    </tbody>\n  </table>\n{% else %}\n  <table class=\"pr-tabela\">\n    <thead><tr><th>Cliente</th><th>Empréstimo</th><th class=\"num\">Contratado</th><th class=\"num\">Taxa</th><th>Parcelas</th><th class=\"num\">Saldo a receber</th><th>Próx. vencimento</th><th>Status</th></tr></thead>\n    <tbody>\n    {% for l in emprestimos %}\n      <tr class=\"clic\" onclick=\"location.href='{{ url_for('titulos_privados_emprestimo_detalhe', loan_id=l.id) }}'\">\n        <td><b>{{ l.cliente or '—' }}</b></td><td class=\"mono\">{{ l.loan_number or ('#' ~ l.id) }}</td>\n        <td class=\"num\">{{ reais(l.contracted_amount) }}</td><td class=\"num\">{{ '%.2f'|format((l.interest_rate_monthly or 0) * 100) }}% a.m.</td>\n        <td>{{ l.pagas }}/{{ l.installments_count }}</td><td class=\"num\"><b>{{ reais(l.saldo) }}</b></td>\n        <td style=\"{{ 'color:var(--fin-neg);font-weight:600' if l.prox and l.prox < hoje }}\">{{ data_br(l.prox) if l.prox else '—' }}</td>\n        <td><span class=\"pr-st {{ 'ok' if l.status == 'active' else 'neutro' }}\">{{ {'active':'Ativo','paid':'Quitado','closed':'Encerrado'}.get(l.status, l.status) }}</span></td></tr>\n    {% else %}<tr><td colspan=\"8\" class=\"fin-vazio\">Nenhum empréstimo cadastrado.</td></tr>{% endfor %}\n    </tbody>\n  </table>\n{% endif %}\n</section>\n<div class=\"pr-aviso\" style=\"margin-top:1rem\">{{ fic('tatica') }}<div><b>Próximos passos (a definir com você):</b> lançar cada parcela automaticamente em\n  Contas a receber (centro de custo “Títulos Privados”), baixa da parcela ao conciliar o extrato e relatório de rentabilidade da carteira.</div></div>\n{% endblock %}\n",
  "financas/conciliacao.html": "{% extends \"financas/_layout.html\" %}\n{% block fin_titulo %}Conciliação bancária{% endblock %}\n{% block fin_conteudo %}\n<div class=\"fin-head\">\n  <div>\n    <div class=\"eyebrow-line\">Finanças</div>\n    <h1>Conciliação bancária</h1>\n    <p>Importe o extrato do banco (OFX) e confirme cada linha com um lançamento. O que não existir, você cria na hora.</p>\n  </div>\n</div>\n{% if not contas %}\n  <div class=\"fin-onboarding\"><h3>Nenhuma conta cadastrada</h3><p><a href=\"{{ url_for('financas.cad_contas', slug=empresa.slug) }}\">Cadastre a conta bancária</a> antes de importar o extrato.</p></div>\n{% else %}\n<div class=\"fin-contas-abas\">\n  {% for c in contas %}\n    <a class=\"{{ 'on' if conta and c.id == conta.id }}\" href=\"{{ url_for('financas.conciliacao', slug=empresa.slug, conta=c.id) }}\"><small>{{ TIPOS_CONTA.get(c.tipo, '') }}</small><b>{{ c.nome }}</b><span>{{ moeda(c.saldo) }}</span></a>\n  {% endfor %}\n</div>\n\n<form class=\"fin-box fin-import\" method=\"post\" enctype=\"multipart/form-data\" action=\"{{ url_for('financas.conciliacao_importar', slug=empresa.slug) }}\">\n  <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><input type=\"hidden\" name=\"conta_id\" value=\"{{ conta.id }}\">\n  <div><b>{{ fic('upload') }} Importar extrato OFX — {{ conta.nome }}</b>\n    <small>No internet banking: Extrato → Exportar → formato OFX (Money/Quicken). Linhas repetidas são ignoradas.</small></div>\n  <input class=\"inp\" type=\"file\" name=\"arquivo\" accept=\".ofx,.OFX\" required>\n  <button class=\"btn-pill fin-btn\" type=\"submit\">Importar</button>\n</form>\n\n<section class=\"fin-box\">\n  <header><h3>Para conciliar ({{ pend|length }})</h3><span>sugestões por valor e data próximos</span></header>\n  {% for x in pend %}\n  <article class=\"fin-conc\">\n    <div class=\"fin-conc-linha\">\n      <span class=\"dt\">{{ data_br(x.data) }}</span>\n      <span class=\"txt\"><b>{{ x.descricao }}</b><small>Extrato do banco</small></span>\n      <b class=\"num {{ 'pos' if x.valor > 0 else 'risco' }}\">{{ moeda(x.valor, true) }}</b>\n    </div>\n    <div class=\"fin-conc-opcoes\">\n      {% for s in x.sugestoes %}\n        <form method=\"post\" action=\"{{ url_for('financas.conciliacao_acao', slug=empresa.slug, xid=x.id, acao='vincular') }}\" class=\"fin-sug\">\n          <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><input type=\"hidden\" name=\"lancamento_id\" value=\"{{ s.id }}\">\n          <span><b>{{ s.descricao }}</b><small>{{ s.pessoa_nome or s.categoria_nome or '—' }} · vence {{ data_br(s.vencimento) }} · saldo {{ moeda(s.saldo) }}</small></span>\n          {% if s.saldo > (x.valor|abs) %}<label class=\"fin-check\"><input type=\"checkbox\" name=\"quitar\" value=\"1\"> quitar com desconto</label>{% endif %}\n          <button class=\"btn-pill fin-btn mini\" type=\"submit\">{{ fic('check') }} Conciliar</button>\n        </form>\n      {% endfor %}\n      <details class=\"fin-conc-novo\" {{ 'open' if not x.sugestoes }}>\n        <summary>{{ 'Nenhum lançamento parecido — ' if not x.sugestoes }}Criar {{ 'receita' if x.valor > 0 else 'despesa' }} com esta linha</summary>\n        <form method=\"post\" action=\"{{ url_for('financas.conciliacao_acao', slug=empresa.slug, xid=x.id, acao='criar') }}\" class=\"fin-conc-form\">\n          <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n          <input class=\"inp\" name=\"descricao\" value=\"{{ x.descricao }}\" aria-label=\"Descrição\">\n          <select class=\"inp\" name=\"categoria_id\" aria-label=\"Categoria\"><option value=\"\">Categoria…</option>\n            {% for c in categorias %}{% if (x.valor > 0) == (c.tipo == 'receita') %}<option value=\"{{ c.id }}\">{{ c.nome }}</option>{% endif %}{% endfor %}</select>\n          <select class=\"inp\" name=\"pessoa_id\" aria-label=\"Cliente/fornecedor\"><option value=\"\">{{ 'Cliente' if x.valor > 0 else 'Fornecedor' }}…</option>\n            {% for p in pessoas %}<option value=\"{{ p.id }}\">{{ p.nome }}</option>{% endfor %}</select>\n          <button class=\"btn-pill fin-btn mini\" type=\"submit\">Criar e conciliar</button>\n        </form>\n      </details>\n      <form method=\"post\" action=\"{{ url_for('financas.conciliacao_acao', slug=empresa.slug, xid=x.id, acao='ignorar') }}\">\n        <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><button class=\"fin-link\" type=\"submit\">Ignorar esta linha</button></form>\n    </div>\n  </article>\n  {% else %}\n    <p class=\"fin-vazio\">Nada pendente. Importe um extrato OFX para começar.</p>\n  {% endfor %}\n</section>\n\n{% if feitas %}\n<section class=\"fin-box\">\n  <header><h3>Últimas conciliadas / ignoradas</h3></header>\n  <ul class=\"fin-lista\">\n    {% for x in feitas %}\n      <li><span>{{ data_br(x.data) }} · {{ x.descricao }} <b class=\"{{ 'pos' if x.valor > 0 else 'risco' }}\">{{ moeda(x.valor, true) }}</b></span>\n        <span class=\"dir\">{{ '✓ Conciliada' if x.status == 'conciliado' else 'Ignorada' }}\n          {% if x.status == 'ignorado' %}<form method=\"post\" action=\"{{ url_for('financas.conciliacao_acao', slug=empresa.slug, xid=x.id, acao='desfazer') }}\">\n            <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><button class=\"fin-link\" type=\"submit\">voltar para pendentes</button></form>{% endif %}</span></li>\n    {% endfor %}\n  </ul>\n</section>\n{% endif %}\n{% endif %}\n{% endblock %}\n",
  "financas/extrato.html": "{% extends \"financas/_layout.html\" %}\n{% block fin_titulo %}Extrato bancário{% endblock %}\n{% block fin_conteudo %}\n<div class=\"fin-head\">\n  <div>\n    <div class=\"eyebrow-line\">Finanças</div>\n    <h1>Extrato bancário</h1>\n    <p>Tudo o que entrou e saiu de cada conta, com o saldo dia a dia.</p>\n  </div>\n  {% if conta %}\n  <div class=\"fin-acoes\">\n    <button class=\"btn-pill outline fin-btn\" type=\"button\" data-abrir=\"dlg-transf\">{{ fic('transferir') }} Transferência</button>\n    <button class=\"btn-pill fin-btn\" type=\"button\" data-abrir=\"dlg-mov\">{{ fic('add') }} Movimento avulso</button>\n  </div>\n  {% endif %}\n</div>\n\n{% if not contas %}\n  <div class=\"fin-onboarding\"><h3>Nenhuma conta cadastrada</h3><p><a href=\"{{ url_for('financas.cad_contas', slug=empresa.slug) }}\">Cadastre a primeira conta bancária</a> para ver o extrato.</p></div>\n{% else %}\n<div class=\"fin-contas-abas\">\n  {% for c in contas %}\n    <a class=\"{{ 'on' if conta and c.id == conta.id }} {{ 'inativa' if not c.ativa }}\" href=\"{{ url_for('financas.extrato', slug=empresa.slug, conta=c.id, de=de, ate=ate) }}\">\n      <small>{{ TIPOS_CONTA.get(c.tipo, '') }}</small><b>{{ c.nome }}</b><span class=\"{{ 'neg' if c.saldo < 0 }}\">{{ moeda(c.saldo) }}</span></a>\n  {% endfor %}\n</div>\n\n{% set ep = 'financas.extrato' %}{% set extra = {'conta': conta.id} %}\n{% include \"financas/_periodo.html\" %}\n\n<div class=\"fin-totais\">\n  <div><small>Saldo anterior</small><b class=\"{{ 'neg' if saldo_ini < 0 }}\">{{ moeda(saldo_ini) }}</b></div>\n  <div class=\"pos\"><small>Entradas</small><b>{{ moeda(entradas) }}</b></div>\n  <div class=\"risco\"><small>Saídas</small><b>{{ moeda(saidas) }}</b></div>\n  <div class=\"dark\"><small>Saldo no fim do período</small><b>{{ moeda(saldo_ini + entradas - saidas) }}</b></div>\n</div>\n\n<div class=\"fin-tabela-wrap\">\n  <table class=\"fin-tabela\">\n    <thead><tr><th>Data</th><th>Descrição</th><th class=\"num\">Entrada</th><th class=\"num\">Saída</th><th class=\"num\">Saldo</th><th></th></tr></thead>\n    <tbody>\n      <tr class=\"saldo-ant\"><td class=\"dt\">{{ data_br(de) }}</td><td colspan=\"3\">Saldo anterior</td><td class=\"num\">{{ moeda(saldo_ini) }}</td><td></td></tr>\n      {% for m in movs %}\n      <tr>\n        <td data-rot=\"Data\" class=\"dt\">{{ data_br(m.data) }}</td>\n        <td data-rot=\"Descrição\" class=\"desc\">\n          {% if m.lancamento_id %}<a href=\"{{ url_for('financas.lancamento', slug=empresa.slug, lid=m.lancamento_id) }}\"><b>{{ m.descricao }}</b></a>{% else %}<b>{{ m.descricao }}</b>{% endif %}\n          <small>{% if m.origem == 'transferencia' %}Transferência entre contas{% else %}{{ m.categoria_nome or 'Sem categoria' }}{% if m.pessoa_nome %} · {{ m.pessoa_nome }}{% endif %}{% endif %}\n            {% if m.conciliado %} · <span class=\"fin-ok\">✓ conciliado</span>{% endif %}</small></td>\n        <td data-rot=\"Entrada\" class=\"num pos\">{{ moeda(m.valor) if m.valor > 0 else '' }}</td>\n        <td data-rot=\"Saída\" class=\"num risco\">{{ moeda(-m.valor) if m.valor < 0 else '' }}</td>\n        <td data-rot=\"Saldo\" class=\"num {{ 'neg' if m.saldo < 0 }}\">{{ moeda(m.saldo) }}</td>\n        <td class=\"acoes\">{% if m.transferencia_id %}\n          <form method=\"post\" action=\"{{ url_for('financas.transferencia_excluir', slug=empresa.slug, tid=m.transferencia_id) }}\">\n            <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><input type=\"hidden\" name=\"voltar\" value=\"{{ request.full_path }}\">\n            <button class=\"fin-link-risco\" type=\"submit\" title=\"Excluir a transferência (das duas contas)\">Excluir</button></form>{% endif %}</td>\n      </tr>\n      {% else %}\n      <tr class=\"vazio\"><td colspan=\"6\">Nenhuma movimentação neste período.</td></tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n\n<dialog id=\"dlg-mov\" class=\"dlg fin-dlg\">\n  <form method=\"post\" action=\"{{ url_for('financas.movimento_novo', slug=empresa.slug) }}\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><input type=\"hidden\" name=\"voltar\" value=\"{{ request.full_path }}\">\n    <input type=\"hidden\" name=\"conta_id\" value=\"{{ conta.id }}\">\n    <div class=\"dlg-head\"><h3>Movimento avulso — {{ conta.nome }}</h3><button type=\"button\" class=\"ico\" data-fechar>{{ ic('close') }}</button></div>\n    <p class=\"fin-sub\">Para tarifas, rendimentos e outros valores que já aconteceram na conta.</p>\n    <div class=\"seg fin-seg\">\n      <input type=\"radio\" id=\"mv-e\" name=\"sentido\" value=\"entrada\"><label for=\"mv-e\">Entrada</label>\n      <input type=\"radio\" id=\"mv-s\" name=\"sentido\" value=\"saida\" checked><label for=\"mv-s\">Saída</label>\n    </div>\n    <label class=\"lbl\">Descrição</label><input class=\"inp\" name=\"descricao\" required maxlength=\"200\" placeholder=\"Ex.: Tarifa de manutenção\">\n    <div class=\"fin-2col\">\n      <div><label class=\"lbl\">Data</label><input class=\"inp\" type=\"date\" name=\"data\" value=\"{{ hoje_iso }}\"></div>\n      <div><label class=\"lbl\">Valor (R$)</label><input class=\"inp\" name=\"valor\" required data-moeda placeholder=\"R$ 0,00\"></div>\n    </div>\n    <div class=\"fin-2col\">\n      <div><label class=\"lbl\">Categoria</label><select class=\"inp\" name=\"categoria_id\"><option value=\"\">—</option>\n        {% for c in categorias %}<option value=\"{{ c.id }}\">{{ c.nome }} ({{ 'receita' if c.tipo == 'receita' else 'despesa' }})</option>{% endfor %}</select></div>\n      <div><label class=\"lbl\">Cliente/fornecedor</label><select class=\"inp\" name=\"pessoa_id\"><option value=\"\">—</option>\n        {% for p in pessoas %}<option value=\"{{ p.id }}\">{{ p.nome }}</option>{% endfor %}</select></div>\n    </div>\n    <button class=\"btn-pill\" type=\"submit\">Lançar no extrato</button>\n  </form>\n</dialog>\n<dialog id=\"dlg-transf\" class=\"dlg fin-dlg\">\n  <form method=\"post\" action=\"{{ url_for('financas.transferencia', slug=empresa.slug) }}\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><input type=\"hidden\" name=\"voltar\" value=\"{{ request.full_path }}\">\n    <div class=\"dlg-head\"><h3>Transferência entre contas</h3><button type=\"button\" class=\"ico\" data-fechar>{{ ic('close') }}</button></div>\n    <div class=\"fin-2col\">\n      <div><label class=\"lbl\">De</label><select class=\"inp\" name=\"origem_id\">{% for c in contas_ativas %}<option value=\"{{ c.id }}\" {{ 'selected' if c.id == conta.id }}>{{ c.nome }}</option>{% endfor %}</select></div>\n      <div><label class=\"lbl\">Para</label><select class=\"inp\" name=\"destino_id\">{% set ns = namespace(ok=false) %}{% for c in contas_ativas %}<option value=\"{{ c.id }}\" {% if c.id != conta.id and not ns.ok %}selected{% set ns.ok = true %}{% endif %}>{{ c.nome }}</option>{% endfor %}</select></div>\n    </div>\n    <div class=\"fin-2col\">\n      <div><label class=\"lbl\">Data</label><input class=\"inp\" type=\"date\" name=\"data\" value=\"{{ hoje_iso }}\"></div>\n      <div><label class=\"lbl\">Valor (R$)</label><input class=\"inp\" name=\"valor\" required data-moeda placeholder=\"R$ 0,00\"></div>\n    </div>\n    <label class=\"lbl\">Descrição <small>(opcional)</small></label><input class=\"inp\" name=\"descricao\" maxlength=\"200\">\n    <button class=\"btn-pill\" type=\"submit\">Transferir</button>\n  </form>\n</dialog>\n{% endif %}\n{% endblock %}\n",
  "financas/lancamento.html": "{% extends \"financas/_layout.html\" %}\n{% block fin_titulo %}{{ l.descricao }}{% endblock %}\n{% block fin_conteudo %}\n{% set receber = l.tipo == 'receber' %}\n<a class=\"fin-voltar\" href=\"{{ url_for('financas.lancamentos', slug=empresa.slug, tipo=l.tipo) }}\">{{ ic('arrow_back') }} {{ 'Contas a receber' if receber else 'Contas a pagar' }}</a>\n\n<section class=\"fin-detalhe sit-{{ l.situacao }}\">\n  <div class=\"fin-detalhe-topo\">\n    <div>\n      <div class=\"fin-meta\">\n        <span class=\"fin-tipo {{ l.tipo }}\">{{ fic(l.tipo) }} {{ 'A receber' if receber else 'A pagar' }}</span>\n        <span class=\"fin-sit {{ l.situacao }}\">{{ SITUACOES[l.situacao] }}</span>\n        {% if l.parcelas > 1 %}<span class=\"fin-chip\">Parcela {{ l.parcela }} de {{ l.parcelas }}</span>{% endif %}\n      </div>\n      <h1>{{ l.descricao }}</h1>\n      <p class=\"fin-sub\">{{ l.pessoa_nome or 'Sem ' ~ ('cliente' if receber else 'fornecedor') }} · {{ l.categoria_nome or 'Sem categoria' }}\n        · Vencimento {{ data_br(l.vencimento) }} · Competência {{ data_br(l.competencia) }}</p>\n    </div>\n    <div class=\"fin-valores\">\n      <div><small>Valor</small><b>{{ moeda(l.valor) }}</b></div>\n      <div><small>{{ 'Recebido' if receber else 'Pago' }}</small><b class=\"pos\">{{ moeda(l.pago) }}</b></div>\n      <div><small>Saldo</small><b class=\"{{ 'neg' if l.saldo and l.situacao == 'vencido' }}\">{{ moeda(l.saldo) }}</b></div>\n    </div>\n  </div>\n  <div class=\"fin-acoes linha\">\n    {% if l.situacao in ('aberto','vencido','parcial') %}\n      <button type=\"button\" class=\"btn-pill fin-btn {{ 'entrada' if receber else 'saida' }}\" data-baixar=\"{{ l.id }}\" data-desc=\"{{ l.descricao }}\" data-saldo=\"{{ valor_campo(l.saldo) }}\" data-conta=\"{{ l.conta_id or '' }}\">{{ fic('check') }} {{ 'Registrar recebimento' if receber else 'Registrar pagamento' }}</button>\n    {% endif %}\n    <form method=\"post\" action=\"{{ url_for('financas.lancamento_acao', slug=empresa.slug, lid=l.id, acao='reativar' if l.cancelado else 'cancelar') }}\">\n      <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n      <button class=\"btn-pill outline fin-btn\" type=\"submit\">{{ 'Reativar' if l.cancelado else 'Cancelar lançamento' }}</button>\n    </form>\n    {% if not baixas %}<button type=\"button\" class=\"fin-link-risco\" data-abrir=\"dlg-excluir\">Excluir</button>{% endif %}\n  </div>\n</section>\n\n<div class=\"fin-cols\">\n  <section class=\"fin-box\">\n    <header><h3>Dados do lançamento</h3></header>\n    <form method=\"post\" class=\"fin-form\">\n      <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n      <label class=\"lbl\">Descrição</label><input class=\"inp\" name=\"descricao\" required maxlength=\"200\" value=\"{{ l.descricao }}\">\n      <div class=\"fin-3col\">\n        <div><label class=\"lbl\">Valor (R$)</label><input class=\"inp\" name=\"valor\" required data-moeda value=\"{{ valor_campo(l.valor) }}\"></div>\n        <div><label class=\"lbl\">Vencimento</label><input class=\"inp\" type=\"date\" name=\"vencimento\" required value=\"{{ l.vencimento }}\"></div>\n        <div><label class=\"lbl\">Competência</label><input class=\"inp\" type=\"date\" name=\"competencia\" value=\"{{ l.competencia }}\"></div>\n      </div>\n      <div class=\"fin-2col\">\n        <div><label class=\"lbl\">{{ 'Cliente' if receber else 'Fornecedor' }}</label>\n          <select class=\"inp\" name=\"pessoa_id\"><option value=\"\">—</option>{% for p in pessoas %}<option value=\"{{ p.id }}\" {{ 'selected' if p.id == l.pessoa_id }}>{{ p.nome }}</option>{% endfor %}</select></div>\n        <div><label class=\"lbl\">Categoria</label>\n          <select class=\"inp\" name=\"categoria_id\"><option value=\"\">—</option>{% for c in categorias %}<option value=\"{{ c.id }}\" {{ 'selected' if c.id == l.categoria_id }}>{{ c.nome }}</option>{% endfor %}</select></div>\n      </div>\n      <div class=\"fin-3col\">\n        <div><label class=\"lbl\">Conta prevista</label>\n          <select class=\"inp\" name=\"conta_id\"><option value=\"\">—</option>{% for c in contas %}<option value=\"{{ c.id }}\" {{ 'selected' if c.id == l.conta_id }}>{{ c.nome }}</option>{% endfor %}</select></div>\n        <div><label class=\"lbl\">Forma de pagamento</label>\n          <select class=\"inp\" name=\"forma_pagamento\"><option value=\"\">—</option>{% for f in FORMAS %}<option {{ 'selected' if f == l.forma_pagamento }}>{{ f }}</option>{% endfor %}</select></div>\n        <div><label class=\"lbl\">Centro de custo</label>\n          <select class=\"inp\" name=\"centro_id\"><option value=\"\">—</option>{% for c in centros %}<option value=\"{{ c.id }}\" {{ 'selected' if c.id == l.centro_id }}>{{ c.nome }}</option>{% endfor %}</select></div>\n      </div>\n      <label class=\"lbl\">Nº documento / NF</label><input class=\"inp\" name=\"documento\" maxlength=\"60\" value=\"{{ l.documento }}\">\n      <label class=\"lbl\">Observações</label><textarea class=\"inp\" name=\"obs\" rows=\"3\">{{ l.obs }}</textarea>\n      <button class=\"btn-pill fin-btn\" type=\"submit\">Salvar alterações</button>\n    </form>\n  </section>\n  <div class=\"fin-coluna\">\n    <section class=\"fin-box\">\n      <header><h3>{{ 'Recebimentos' if receber else 'Pagamentos' }}</h3></header>\n      <ul class=\"fin-lista\">\n        {% for b in baixas %}\n          <li><span><b>{{ moeda(b.valor) }}</b> em {{ data_br(b.data) }}<small>{{ b.conta_nome }}{% if b.juros %} · juros {{ moeda(b.juros) }}{% endif %}{% if b.desconto %} · desconto {{ moeda(b.desconto) }}{% endif %}</small></span>\n            <form method=\"post\" action=\"{{ url_for('financas.baixa_estornar', slug=empresa.slug, bid=b.id) }}\">\n              <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><button class=\"fin-link-risco\" type=\"submit\">Estornar</button></form></li>\n        {% else %}<li class=\"vazio\">Nenhum {{ 'recebimento' if receber else 'pagamento' }} registrado.</li>{% endfor %}\n      </ul>\n    </section>\n    {% if irmaos|length > 1 %}\n    <section class=\"fin-box\">\n      <header><h3>Parcelas / repetições</h3></header>\n      <ul class=\"fin-lista\">\n        {% for x in irmaos %}\n          <li class=\"{{ 'atual' if x.id == l.id }}\"><a href=\"{{ url_for('financas.lancamento', slug=empresa.slug, lid=x.id) }}\">{{ x.parcela }}/{{ x.parcelas }} · {{ data_br(x.vencimento) }}</a>\n            <span class=\"dir\">{{ moeda(x.valor) }} <span class=\"fin-sit {{ x.situacao }}\">{{ SITUACOES[x.situacao] }}</span></span></li>\n        {% endfor %}\n      </ul>\n    </section>\n    {% endif %}\n  </div>\n</div>\n\n<dialog id=\"dlg-excluir\" class=\"dlg fin-dlg\">\n  <form method=\"post\" action=\"{{ url_for('financas.lancamento_acao', slug=empresa.slug, lid=l.id, acao='excluir') }}\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n    <div class=\"dlg-head\"><h3>Excluir lançamento?</h3><button type=\"button\" class=\"ico\" data-fechar>{{ ic('close') }}</button></div>\n    <p class=\"fin-sub\">“{{ l.descricao }}” será apagado. Para manter no histórico, use “Cancelar lançamento”.</p>\n    <div class=\"row-btns\"><button type=\"button\" class=\"btn-pill outline\" data-fechar>Voltar</button><button class=\"btn-pill fin-risco\" type=\"submit\">Excluir</button></div>\n  </form>\n</dialog>\n{% include \"financas/_dlg_baixa.html\" %}\n{% endblock %}\n",
  "financas/lancamento_form.html": "{% extends \"financas/_layout.html\" %}\n{% set receber = tipo == 'receber' %}\n{% set novo = not l %}\n{% block fin_titulo %}{{ ('Nova conta a receber' if receber else 'Nova conta a pagar') if novo else l.descricao }}{% endblock %}\n{% block fin_conteudo %}\n{% set rot_pessoa = 'Cliente' if receber else 'Fornecedor' %}\n{% set rot_prev = 'Previsão de recebimento' if receber else 'Previsão de pagamento' %}\n{% set pessoa_atual = (pessoas | selectattr('id', 'equalto', l.pessoa_id) | first) if l else none %}\n\n<form method=\"post\" id=\"f-lanc\" enctype=\"multipart/form-data\" autocomplete=\"off\"\n      action=\"{{ url_for('financas.lancamento_novo', slug=empresa.slug, tipo=tipo) if novo else url_for('financas.lancamento', slug=empresa.slug, lid=l.id) }}\">\n<input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n\n<div class=\"lf-cab {{ tipo }}\">\n  <a class=\"fin-voltar\" href=\"{{ voltar }}\">{{ ic('arrow_back') }} {{ 'Contas a receber' if receber else 'Contas a pagar' }}</a>\n  <div class=\"lf-cab-linha\">\n    <div>\n      <h1>{% if novo %}{{ 'Nova conta a receber' if receber else 'Nova conta a pagar' }}{% else %}{{ l.descricao }}{% endif %}</h1>\n      {% if not novo %}\n      <div class=\"fin-meta\">\n        <span class=\"fin-sit {{ l.situacao }}\">{{ SITUACOES[l.situacao] }}</span>\n        {% if l.parcelas > 1 %}<span class=\"fin-chip\">{{ 'Parcela' if l.repeticao != 'recorrente' else 'Repetição' }} {{ l.parcela }} de {{ l.parcelas }}</span>{% endif %}\n        {% if l.natureza_custo %}<span class=\"fin-chip\">{{ NATUREZAS_CUSTO[l.natureza_custo] }}</span>{% endif %}\n        {% if l.n_anexos %}<span class=\"fin-chip\">📎 {{ l.n_anexos }}</span>{% endif %}\n      </div>\n      {% endif %}\n    </div>\n    {% if not novo %}\n    <div class=\"lf-stats\">\n      <div><small>Valor</small><b>{{ moeda(l.valor) }}</b></div>\n      <div><small>{{ 'Recebido' if receber else 'Pago' }}</small><b class=\"pos\">{{ moeda(l.pago) }}</b></div>\n      <div><small>Saldo</small><b class=\"{{ 'neg' if l.situacao == 'vencido' }}\">{{ moeda(l.saldo) }}</b></div>\n    </div>\n    {% endif %}\n  </div>\n</div>\n\n{# ── 1. Informações ── #}\n<section class=\"lf-sec\">\n  <h2><span>1</span> Informações</h2>\n  <div class=\"lf-row\">\n    <div class=\"lf-f lf-w2\">\n      <div class=\"lf-lbl-linha\"><label class=\"lbl\" for=\"lf-pessoa-txt\">{{ rot_pessoa }}</label></div>\n      <div class=\"lf-pessoa\">\n        <div class=\"lf-combo\" id=\"lf-combo\">\n          <input class=\"inp\" id=\"lf-pessoa-txt\" placeholder=\"Digite parte do nome, fantasia ou CPF/CNPJ e tecle Enter\" value=\"{{ pessoa_atual.nome if pessoa_atual else '' }}\"\n                 role=\"combobox\" aria-autocomplete=\"list\" aria-expanded=\"false\" aria-controls=\"lf-sugs\">\n          <span class=\"lf-ok\" id=\"lf-pessoa-ok\" {{ 'hidden' if not pessoa_atual }}>✓</span>\n          <ul class=\"lf-sugs\" id=\"lf-sugs\" role=\"listbox\" hidden></ul>\n        </div>\n        <a class=\"btn-pill outline fin-btn lf-novo\" id=\"lf-novo\" target=\"_blank\" title=\"Cadastrar novo {{ rot_pessoa|lower }} (abre em outra aba)\"\n           href=\"{{ url_for('financas.cad_pessoas', slug=empresa.slug, tipo='cliente' if receber else 'fornecedor') }}\">{{ fic('add') }} Novo</a>\n      </div>\n      <input type=\"hidden\" name=\"pessoa_id\" id=\"lf-pessoa-id\" value=\"{{ l.pessoa_id if l and l.pessoa_id else '' }}\">\n      <div class=\"lf-pessoa-info\" id=\"lf-pessoa-info\">{% if pessoa_atual and pessoa_atual.documento %}{{ pessoa_atual.documento|doc_fmt }}{% endif %}</div>\n    </div>\n    <div class=\"lf-f\"><label class=\"lbl\">Nº documento / NF</label><input class=\"inp\" name=\"documento\" maxlength=\"60\" value=\"{{ l.documento if l else '' }}\"></div>\n  </div>\n  <div class=\"lf-row\">\n    <div class=\"lf-f lf-w2\"><label class=\"lbl\">Descrição *</label>\n      <input class=\"inp\" name=\"descricao\" required maxlength=\"200\" value=\"{{ l.descricao if l else '' }}\"\n             placeholder=\"{{ 'Ex.: Honorários de consultoria — outubro' if receber else 'Ex.: Aluguel do escritório' }}\"></div>\n    <div class=\"lf-f\"><label class=\"lbl\">Classificação</label>\n      <div class=\"lf-seg\">\n        {% for k, v in NATUREZAS_CUSTO.items() %}\n          <label><input type=\"radio\" name=\"natureza_custo\" value=\"{{ k }}\" {{ 'checked' if (l and l.natureza_custo == k) or (not l and k == 'variavel') }}><span>{{ v }}</span></label>\n        {% endfor %}\n      </div></div>\n  </div>\n  <div class=\"lf-row\">\n    <div class=\"lf-f\"><label class=\"lbl\">Competência</label>\n      <div class=\"lf-mes\"><input class=\"inp\" type=\"month\" name=\"competencia\" id=\"lf-comp\" value=\"{{ (l.competencia if l else hoje)[:7] }}\">\n        <span id=\"lf-comp-txt\"></span></div></div>\n    <div class=\"lf-f\"><label class=\"lbl\">Conta {{ 'de recebimento' if receber else 'de pagamento' }}</label>\n      <select class=\"inp\" name=\"conta_id\" id=\"lf-conta\"><option value=\"\">—</option>\n        {% for c in contas %}<option value=\"{{ c.id }}\" {{ 'selected' if l and c.id == l.conta_id }}>{{ c.nome }}</option>{% endfor %}</select></div>\n    <div class=\"lf-f\"><label class=\"lbl\">Forma de pagamento</label>\n      <select class=\"inp\" name=\"forma_pagamento\"><option value=\"\">—</option>\n        {% for f in FORMAS %}<option {{ 'selected' if l and f == l.forma_pagamento }}>{{ f }}</option>{% endfor %}</select></div>\n  </div>\n</section>\n\n{# ── 2. Valor e categorias ── #}\n<section class=\"lf-sec\">\n  <h2><span>2</span> Valor e categorias</h2>\n  <div class=\"lf-row\">\n    <div class=\"lf-f\"><label class=\"lbl\">{{ 'Valor total' if novo else 'Valor desta ' ~ ('parcela' if l.parcelas > 1 else 'conta') }} *</label>\n      <input class=\"inp lf-valor\" id=\"lf-total\" inputmode=\"decimal\" placeholder=\"R$ 0,00\" value=\"{{ valor_campo(l.valor) if l else '' }}\" required></div>\n    <div class=\"lf-f lf-w2 lf-dica\">Para dividir em mais de uma categoria use “+ Adicionar categoria” — ex.: R$ 1.000,00 = R$ 500,00 Consultoria + R$ 500,00 Honorários.\n      Nas parcelas e repetições a divisão é aplicada proporcionalmente.</div>\n  </div>\n  <table class=\"lf-rateio\" id=\"lf-rateio\">\n    <thead><tr><th>Categoria *</th><th>Centro de custo</th><th class=\"num\">Valor</th><th class=\"num\">%</th><th></th></tr></thead>\n    <tbody>\n    {% for r in (rateio if rateio else [{}]) %}\n      <tr>\n        <td><select class=\"inp\" name=\"rat_categoria\"><option value=\"\">Selecione…</option>\n          {% for c in categorias %}<option value=\"{{ c.id }}\" {{ 'selected' if r.categoria_id == c.id }}>{{ c.nome }} · {{ NOME_GRUPO.get(c.grupo_dre, '') }}</option>{% endfor %}</select></td>\n        <td><select class=\"inp\" name=\"rat_centro\"><option value=\"\">—</option>\n          {% for c in centros %}<option value=\"{{ c.id }}\" {{ 'selected' if r.centro_id == c.id }}>{{ c.nome }}</option>{% endfor %}</select></td>\n        <td><input class=\"inp num\" name=\"rat_valor\" inputmode=\"decimal\" placeholder=\"R$ 0,00\" value=\"{{ valor_campo(r.valor) if r.valor else '' }}\"></td>\n        <td><input class=\"inp num lf-pct\" inputmode=\"decimal\" tabindex=\"-1\"></td>\n        <td><button type=\"button\" class=\"lf-x\" title=\"Remover\">{{ fic('fechar') }}</button></td>\n      </tr>\n    {% endfor %}\n    </tbody>\n    <tfoot><tr>\n      <td colspan=\"2\"><button type=\"button\" class=\"fin-link\" id=\"lf-add-rat\">+ Adicionar categoria</button></td>\n      <td class=\"num\"><b id=\"lf-rat-soma\">R$ 0,00</b></td><td class=\"num\" id=\"lf-rat-pct\"></td><td></td>\n    </tr></tfoot>\n  </table>\n  <div class=\"lf-alerta\" id=\"lf-rat-aviso\" hidden></div>\n</section>\n\n{# ── 3. Datas e condição ── #}\n<section class=\"lf-sec\">\n  <h2><span>3</span> {{ 'Datas e condição' if novo else 'Datas' }}</h2>\n  {% if novo %}\n    <div class=\"lf-seg lf-cond\">\n      <label><input type=\"radio\" name=\"condicao\" value=\"unico\" checked><span>À vista / única</span></label>\n      <label><input type=\"radio\" name=\"condicao\" value=\"parcelado\"><span>Parcelado</span></label>\n      <label><input type=\"radio\" name=\"condicao\" value=\"recorrente\"><span>Recorrente (repetir)</span></label>\n    </div>\n    <div class=\"lf-row lf-row4\" style=\"margin-top:.6rem\">\n      <div class=\"lf-f\"><label class=\"lbl\"><span class=\"lf-1a\" hidden>1ª </span>{{ rot_prev }} *</label><input class=\"inp\" type=\"date\" id=\"lf-prev1\" value=\"{{ hoje }}\"></div>\n      <div class=\"lf-f\"><label class=\"lbl\"><span class=\"lf-1a\" hidden>1º </span>Vencimento *</label><input class=\"inp\" type=\"date\" id=\"lf-venc1\" value=\"{{ hoje }}\">\n        <small class=\"lf-sub\" id=\"lf-venc-dica\">igual à previsão — altere se for diferente</small></div>\n      <div class=\"lf-f lf-so-rep\" hidden><label class=\"lbl\" id=\"lf-lbl-qtd\">Nº de parcelas</label><input class=\"inp\" type=\"number\" id=\"lf-qtd\" min=\"2\" max=\"360\" value=\"2\"></div>\n      <div class=\"lf-f lf-so-rep\" hidden><label class=\"lbl\">Frequência</label>\n        <select class=\"inp\" id=\"lf-freq\">{% for k, v in FREQUENCIAS.items() %}<option value=\"{{ k }}\">{{ v[0] }}</option>{% endfor %}</select></div>\n    </div>\n    <p class=\"fin-sub lf-so-rep\" hidden id=\"lf-cond-dica\"></p>\n    <div class=\"lf-parcelas\" id=\"lf-parcelas\" hidden>\n      <table class=\"lf-tab-parc\">\n        <thead><tr><th>#</th><th>{{ rot_prev }}</th><th>Vencimento</th><th class=\"num\">Valor</th></tr></thead>\n        <tbody></tbody>\n        <tfoot><tr><td></td><td colspan=\"2\"><button type=\"button\" class=\"fin-link\" id=\"lf-recalc\">↻ Recalcular parcelas</button></td><td class=\"num\"><b id=\"lf-parc-soma\"></b></td></tr></tfoot>\n      </table>\n      <div class=\"lf-alerta\" id=\"lf-parc-aviso\" hidden></div>\n    </div>\n    <div id=\"lf-hidden-parc\"></div>\n    <div class=\"lf-japago\" id=\"lf-japago\">\n      <label class=\"fin-check\"><input type=\"checkbox\" name=\"ja_pago\" value=\"1\" id=\"lf-ja\"> Já foi {{ 'recebido' if receber else 'pago' }}</label>\n      <div class=\"lf-row\" id=\"lf-ja-campos\" hidden>\n        <div class=\"lf-f\"><label class=\"lbl\">Data do {{ 'recebimento' if receber else 'pagamento' }}</label><input class=\"inp\" type=\"date\" name=\"pago_data\" value=\"{{ hoje }}\"></div>\n        <div class=\"lf-f\"><label class=\"lbl\">Conta</label><select class=\"inp\" name=\"pago_conta_id\"><option value=\"\">Mesma conta acima</option>\n          {% for c in contas %}<option value=\"{{ c.id }}\">{{ c.nome }}</option>{% endfor %}</select></div>\n      </div>\n    </div>\n  {% else %}\n    <div class=\"lf-row\">\n      <div class=\"lf-f\"><label class=\"lbl\">{{ rot_prev }} *</label><input class=\"inp\" type=\"date\" name=\"par_prev\" id=\"lf-prev1\" value=\"{{ l.previsao or l.vencimento }}\" required></div>\n      <div class=\"lf-f\"><label class=\"lbl\">Vencimento *</label><input class=\"inp\" type=\"date\" name=\"par_venc\" id=\"lf-venc1\" value=\"{{ l.vencimento }}\" required></div>\n      <input type=\"hidden\" name=\"par_valor\" id=\"lf-par-valor-edit\" value=\"{{ valor_campo(l.valor) }}\">\n      {% if l.grupo %}\n      <div class=\"lf-f\"><label class=\"fin-check\" style=\"margin-top:1.7rem\"><input type=\"checkbox\" name=\"propagar\" value=\"1\">\n        Aplicar descrição, {{ rot_pessoa|lower }}, conta e categorias às próximas parcelas em aberto</label></div>\n      {% endif %}\n    </div>\n  {% endif %}\n</section>\n\n{# ── 4. Anexos e observações ── #}\n<section class=\"lf-sec\">\n  <h2><span>4</span> Anexos e observações</h2>\n  <div class=\"lf-row lf-row-anx\">\n    <div class=\"lf-f\">\n      <label class=\"lf-drop\" id=\"lf-drop\">\n        <input type=\"file\" name=\"anexos\" id=\"lf-arquivos\" multiple accept=\".pdf,.png,.jpg,.jpeg,.webp,.gif,.xml,.txt,.csv,.xls,.xlsx,.doc,.docx,.ofx,.rem,.ret,.zip,.eml,.msg\">\n        <span>{{ fic('upload') }} <b>Arraste boletos, notas e documentos</b> ou clique para escolher<small>PDF, imagens, XML, planilhas… até 20 MB cada</small></span>\n      </label>\n      <ul class=\"lf-arqs\" id=\"lf-arqs\"></ul>\n    </div>\n    <div class=\"lf-f lf-w2\"><label class=\"lbl\" style=\"margin-top:0\">Observações</label><textarea class=\"inp\" name=\"obs\" rows=\"5\">{{ l.obs if l else '' }}</textarea></div>\n  </div>\n</section>\n\n{# ── barra de ações fixa no rodapé ── #}\n<div class=\"lf-barra {{ tipo }}\">\n  <div class=\"lf-barra-res\">\n    <div><small>{{ 'Total a receber' if receber else 'Total a pagar' }}</small><b id=\"lf-res-total\">R$ 0,00</b></div>\n    <div><small>Categorias</small><b id=\"lf-res-cats\">1</b></div>\n    <div><small>{{ 'Parcelas' if novo else 'Vencimento' }}</small><b id=\"lf-res-parc\">{{ '1' if novo else data_br(l.vencimento) }}</b></div>\n  </div>\n  <div class=\"lf-botoes\">\n    <a class=\"btn-pill outline fin-btn\" href=\"{{ voltar }}\">Cancelar</a>\n    {% if novo %}<button class=\"btn-pill outline fin-btn\" name=\"acao\" value=\"novo\">Salvar e criar outro</button>{% endif %}\n    <button class=\"btn-pill fin-btn {{ 'entrada' if receber else 'saida' }}\" name=\"acao\" value=\"salvar\">{{ fic('check') }} Salvar</button>\n  </div>\n</div>\n</form>\n\n{# janela de busca quando há mais de um resultado #}\n<dialog class=\"dlg fin-dlg lf-busca\" id=\"dlg-busca\">\n  <div class=\"dlg-head\"><h3>Selecionar {{ rot_pessoa|lower }}</h3><button type=\"button\" class=\"ico\" data-fechar>{{ ic('close') }}</button></div>\n  <label class=\"search\">{{ ic('search') }}<input type=\"search\" id=\"lf-busca-txt\" placeholder=\"Nome, fantasia ou CPF/CNPJ\"></label>\n  <p class=\"fin-sub\" id=\"lf-busca-n\"></p>\n  <ul class=\"lf-busca-lista\" id=\"lf-busca-lista\"></ul>\n</dialog>\n\n{% if not novo %}\n<div class=\"lf-extra\">\n  {% if irmaos|length > 1 %}\n  <section class=\"lf-sec lf-sec-larga\" id=\"parcelas\">\n    <h2>{{ fic('calendario') }} {{ 'Parcelas' if l.repeticao != 'recorrente' else 'Repetições' }} ({{ irmaos|length }})</h2>\n    <form method=\"post\" action=\"{{ url_for('financas.lancamento_parcelas', slug=empresa.slug, lid=l.id) }}\">\n      <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n      <table class=\"lf-tab-parc\">\n        <thead><tr><th>#</th><th>{{ rot_prev }}</th><th>Vencimento</th><th class=\"num\">Valor</th><th>Situação</th><th></th></tr></thead>\n        <tbody>\n        {% for x in irmaos %}\n          {% set editavel = x.situacao in ('aberto', 'vencido') %}\n          <tr class=\"{{ 'atual' if x.id == l.id }}\">\n            <td>{{ x.parcela }}/{{ x.parcelas }}</td>\n            <td>{% if editavel %}<input class=\"inp\" type=\"date\" name=\"prev_{{ x.id }}\" value=\"{{ x.previsao or x.vencimento }}\">{% else %}{{ data_br(x.previsao or x.vencimento) }}{% endif %}</td>\n            <td>{% if editavel %}<input class=\"inp\" type=\"date\" name=\"venc_{{ x.id }}\" value=\"{{ x.vencimento }}\">{% else %}{{ data_br(x.vencimento) }}{% endif %}</td>\n            <td class=\"num\">{% if editavel %}<input class=\"inp num\" data-moeda name=\"valor_{{ x.id }}\" value=\"{{ valor_campo(x.valor) }}\" inputmode=\"decimal\">{% else %}{{ moeda(x.valor) }}{% endif %}</td>\n            <td><span class=\"fin-sit {{ x.situacao }}\">{{ SITUACOES[x.situacao] }}</span></td>\n            <td class=\"num\">{% if x.id != l.id %}<a class=\"fin-link\" href=\"{{ url_for('financas.lancamento', slug=empresa.slug, lid=x.id) }}\">abrir</a>{% else %}<b>atual</b>{% endif %}</td>\n          </tr>\n        {% endfor %}\n        </tbody>\n        <tfoot><tr><td></td><td></td><td>Total</td><td class=\"num\"><b>{{ moeda(irmaos|sum(attribute='valor')) }}</b></td><td colspan=\"2\"></td></tr></tfoot>\n      </table>\n      <button class=\"btn-pill outline fin-btn mini\" type=\"submit\" style=\"margin-top:.7rem\">Salvar ajustes das parcelas</button>\n      <span class=\"fin-sub\" style=\"margin-left:.6rem\">Só parcelas em aberto podem ser ajustadas.</span>\n    </form>\n  </section>\n  {% endif %}\n\n  <section class=\"lf-sec\">\n    <h2>{{ fic('check') }} {{ 'Recebimentos' if receber else 'Pagamentos' }}</h2>\n    {% if l.situacao in ('aberto','vencido','parcial') %}\n      <button type=\"button\" class=\"btn-pill fin-btn {{ 'entrada' if receber else 'saida' }}\" data-baixar=\"{{ l.id }}\" data-desc=\"{{ l.descricao }}\" data-saldo=\"{{ valor_campo(l.saldo) }}\" data-conta=\"{{ l.conta_id or '' }}\">{{ 'Registrar recebimento' if receber else 'Registrar pagamento' }}</button>\n    {% endif %}\n    <ul class=\"fin-lista\">\n      {% for b in baixas %}\n        <li><span><b>{{ moeda(b.valor) }}</b> em {{ data_br(b.data) }}<small>{{ b.conta_nome }}{% if b.juros %} · juros {{ moeda(b.juros) }}{% endif %}{% if b.desconto %} · desconto {{ moeda(b.desconto) }}{% endif %}</small></span>\n          <form method=\"post\" action=\"{{ url_for('financas.baixa_estornar', slug=empresa.slug, bid=b.id) }}\">\n            <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><button class=\"fin-link-risco\" type=\"submit\">Estornar</button></form></li>\n      {% else %}<li class=\"vazio\">Nenhum {{ 'recebimento' if receber else 'pagamento' }} registrado.</li>{% endfor %}\n    </ul>\n  </section>\n  <section class=\"lf-sec\">\n    <h2>{{ fic('upload') }} Anexos ({{ anexos|length }})</h2>\n    <ul class=\"lf-anexos\">\n      {% for a in anexos %}\n        <li><a href=\"{{ url_for('financas.anexo_baixar', slug=empresa.slug, aid=a.id) }}\" target=\"_blank\" title=\"Abrir\">{{ a.nome }}</a>\n          <small>{{ (a.tamanho / 1024)|round|int }} KB{% if a.grupo %} · todas as parcelas{% endif %}</small>\n          <a class=\"fin-link\" href=\"{{ url_for('financas.anexo_baixar', slug=empresa.slug, aid=a.id, baixar=1) }}\">baixar</a>\n          <form method=\"post\" action=\"{{ url_for('financas.anexo_excluir', slug=empresa.slug, aid=a.id) }}\" onsubmit=\"return confirm('Remover o anexo {{ a.nome }}?')\">\n            <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\"><input type=\"hidden\" name=\"voltar\" value=\"{{ request.path }}\">\n            <button class=\"fin-link-risco\" type=\"submit\">remover</button></form></li>\n      {% else %}<li class=\"vazio\">Nenhum anexo.</li>{% endfor %}\n    </ul>\n  </section>\n  <section class=\"lf-sec\">\n    <h2>Ações</h2>\n    <div class=\"lf-acoes\">\n      <form method=\"post\" action=\"{{ url_for('financas.lancamento_acao', slug=empresa.slug, lid=l.id, acao='reativar' if l.cancelado else 'cancelar') }}\">\n        <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n        <button class=\"btn-pill outline fin-btn mini\" type=\"submit\">{{ 'Reativar' if l.cancelado else 'Cancelar lançamento' }}</button></form>\n      {% if not baixas %}<button type=\"button\" class=\"fin-link-risco\" data-abrir=\"dlg-excluir\">Excluir</button>{% endif %}\n    </div>\n  </section>\n</div>\n\n<dialog id=\"dlg-excluir\" class=\"dlg fin-dlg\">\n  <form method=\"post\" action=\"{{ url_for('financas.lancamento_acao', slug=empresa.slug, lid=l.id, acao='excluir') }}\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n    <div class=\"dlg-head\"><h3>Excluir lançamento?</h3><button type=\"button\" class=\"ico\" data-fechar>{{ ic('close') }}</button></div>\n    <p class=\"fin-sub\">“{{ l.descricao }}” e seus anexos serão apagados. Para manter no histórico, use “Cancelar lançamento”.</p>\n    <div class=\"row-btns\"><button type=\"button\" class=\"btn-pill outline\" data-fechar>Voltar</button><button class=\"btn-pill fin-risco\" type=\"submit\">Excluir</button></div>\n  </form>\n</dialog>\n{% include \"financas/_dlg_baixa.html\" %}\n{% endif %}\n{% endblock %}\n\n{% block fin_scripts %}\n<script>\n(function () {\n  var NOVO = {{ 'true' if novo else 'false' }}, FREQ = {{ FREQUENCIAS | tojson }};\n  var MESES = ['janeiro','fevereiro','março','abril','maio','junho','julho','agosto','setembro','outubro','novembro','dezembro'];\n  var f = document.getElementById('f-lanc'), total = document.getElementById('lf-total');\n  function cent(s) { s = String(s || '').replace(/[^\\d,.-]/g, ''); if (!s) return 0; if (s.indexOf(',') >= 0) s = s.replace(/\\./g, '').replace(',', '.'); var n = parseFloat(s); return isNaN(n) ? 0 : Math.round(n * 100); }\n  function br(c) { return (c < 0 ? '-' : '') + 'R$ ' + (Math.abs(c) / 100).toLocaleString('pt-BR', {minimumFractionDigits: 2, maximumFractionDigits: 2}); }\n  function aviso(id, t) { var el = document.getElementById(id); el.hidden = !t; el.textContent = t || ''; }\n  function sem(s) { return (s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase(); }\n\n  // ══ busca de cliente/fornecedor ══\n  var LISTA = [], ptxt = document.getElementById('lf-pessoa-txt'), pid = document.getElementById('lf-pessoa-id'),\n      sugs = document.getElementById('lf-sugs'), ok = document.getElementById('lf-pessoa-ok'), info = document.getElementById('lf-pessoa-info'),\n      dlg = document.getElementById('dlg-busca'), btxt = document.getElementById('lf-busca-txt'), blista = document.getElementById('lf-busca-lista'),\n      foco = -1, escolhido = ptxt.value;\n  var URL_PESSOAS = '{{ url_for(\"financas.pessoas_json\", slug=empresa.slug, tipo=\"cliente\" if receber else \"fornecedor\") }}';\n  function carregar(depois) { fetch(URL_PESSOAS, {credentials: 'same-origin'}).then(function (r) { return r.json(); }).then(function (j) { LISTA = j; if (depois) depois(); }); }\n  function buscar(q) {\n    q = sem(q).trim(); if (!q) return [];\n    var dig = q.replace(/\\D/g, '');\n    var r = LISTA.filter(function (p) {\n      return sem(p.nome).indexOf(q) >= 0 || sem(p.fantasia).indexOf(q) >= 0 || (dig.length >= 3 && p.doc.indexOf(dig) >= 0);\n    });\n    r.sort(function (a, b) {  // quem começa com o texto vem primeiro\n      var pa = sem(a.nome).indexOf(q) === 0 || sem(a.fantasia).indexOf(q) === 0 ? 0 : 1, pb = sem(b.nome).indexOf(q) === 0 || sem(b.fantasia).indexOf(q) === 0 ? 0 : 1;\n      return pa - pb || a.nome.localeCompare(b.nome);\n    });\n    return r;\n  }\n  function fmtDoc(d) { return d.length === 14 ? d.replace(/^(\\d{2})(\\d{3})(\\d{3})(\\d{4})(\\d{2})$/, '$1.$2.$3/$4-$5') : d.length === 11 ? d.replace(/^(\\d{3})(\\d{3})(\\d{3})(\\d{2})$/, '$1.$2.$3-$4') : d; }\n  function detalhe(p) { return [p.fantasia && p.fantasia !== p.nome ? p.fantasia : '', p.doc ? fmtDoc(p.doc) : '', p.cidade ? p.cidade + (p.uf ? '/' + p.uf : '') : ''].filter(Boolean).join(' · '); }\n  function escolher(p) {\n    pid.value = p.id; ptxt.value = p.nome; escolhido = p.nome; ok.hidden = false; info.textContent = detalhe(p); info.classList.remove('erro');\n    fechaSugs(); if (dlg.open) dlg.close();\n  }\n  function limpa() { pid.value = ''; ok.hidden = true; info.textContent = ''; info.classList.remove('erro'); }\n  function itemHTML(p, i) { return '<li role=\"option\" data-i=\"' + i + '\"><b>' + esc(p.nome) + '</b><small>' + esc(detalhe(p)) + '</small></li>'; }\n  function esc(s) { return String(s || '').replace(/[&<>\"]/g, function (c) { return {'&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;'}[c]; }); }\n  var atuais = [];\n  function abreSugs() {\n    atuais = buscar(ptxt.value).slice(0, 8); foco = -1;\n    if (!atuais.length) { fechaSugs(); return; }\n    sugs.innerHTML = atuais.map(itemHTML).join(''); sugs.hidden = false; ptxt.setAttribute('aria-expanded', 'true');\n  }\n  function fechaSugs() { sugs.hidden = true; ptxt.setAttribute('aria-expanded', 'false'); }\n  function marcaFoco() { [].forEach.call(sugs.children, function (li, i) { li.classList.toggle('on', i === foco); }); }\n  function confirmar() {\n    var t = ptxt.value.trim();\n    if (!t) { limpa(); info.textContent = ''; return true; }\n    if (pid.value && t === escolhido) return true;\n    var r = buscar(t);\n    var exato = r.filter(function (p) { return sem(p.nome) === sem(t) || sem(p.fantasia) === sem(t); });\n    if (r.length === 1 || exato.length === 1) { escolher(exato.length === 1 ? exato[0] : r[0]); return true; }\n    limpa();\n    if (!r.length) { info.innerHTML = 'Nenhum {{ rot_pessoa|lower }} encontrado com “' + esc(t) + '”. <a href=\"#\" id=\"lf-cad-rapido\">Cadastrar agora</a>'; info.classList.add('erro');\n      document.getElementById('lf-cad-rapido').onclick = function (e) { e.preventDefault(); abrirNovo(t); }; return true; }\n    abrirBusca(t); return false;\n  }\n  function abrirBusca(t) {\n    fechaSugs(); btxt.value = t; listaBusca(); dlg.showModal(); btxt.focus(); btxt.select();\n  }\n  function listaBusca() {\n    var r = btxt.value.trim() ? buscar(btxt.value) : LISTA.slice().sort(function (a, b) { return a.nome.localeCompare(b.nome); });\n    document.getElementById('lf-busca-n').textContent = r.length + ' resultado(s) — clique para escolher';\n    blista.innerHTML = r.slice(0, 200).map(itemHTML).join('') || '<li class=\"vazio\">Nada encontrado.</li>';\n    blista._r = r;\n  }\n  ptxt.addEventListener('input', function () { if (ptxt.value !== escolhido) limpa(); abreSugs(); });\n  ptxt.addEventListener('focus', function () { if (!LISTA.length) carregar(); });\n  ptxt.addEventListener('keydown', function (e) {\n    if (e.key === 'ArrowDown' && !sugs.hidden) { e.preventDefault(); foco = Math.min(foco + 1, atuais.length - 1); marcaFoco(); }\n    else if (e.key === 'ArrowUp' && !sugs.hidden) { e.preventDefault(); foco = Math.max(foco - 1, 0); marcaFoco(); }\n    else if (e.key === 'Enter') { e.preventDefault(); if (foco >= 0 && atuais[foco]) escolher(atuais[foco]); else confirmar(); }\n    else if (e.key === 'Tab') { if (foco >= 0 && atuais[foco]) { escolher(atuais[foco]); } else if (!confirmar()) e.preventDefault(); }\n    else if (e.key === 'Escape') fechaSugs();\n  });\n  ptxt.addEventListener('blur', function () { setTimeout(function () { if (!dlg.open && document.activeElement !== ptxt) { fechaSugs(); confirmar(); } }, 150); });\n  sugs.addEventListener('mousedown', function (e) { var li = e.target.closest('li[data-i]'); if (li) { e.preventDefault(); escolher(atuais[+li.dataset.i]); } });\n  btxt.addEventListener('input', listaBusca);\n  btxt.addEventListener('keydown', function (e) { if (e.key === 'Enter') { e.preventDefault(); if (blista._r && blista._r.length === 1) escolher(blista._r[0]); } });\n  blista.addEventListener('click', function (e) { var li = e.target.closest('li[data-i]'); if (li) escolher(blista._r[+li.dataset.i]); });\n  dlg.querySelector('[data-fechar]').addEventListener('click', function () { dlg.close(); });\n  function abrirNovo(nome) {\n    var a = document.getElementById('lf-novo'); window.open(a.href + (nome ? '&nome=' + encodeURIComponent(nome) : ''), '_blank');\n  }\n  document.getElementById('lf-novo').addEventListener('click', function (e) { e.preventDefault(); abrirNovo(pid.value ? '' : ptxt.value.trim()); });\n  // ao voltar da aba de cadastro, atualiza a lista e tenta achar o que foi digitado\n  window.addEventListener('focus', function () { carregar(function () { if (!pid.value && ptxt.value.trim()) { var r = buscar(ptxt.value); if (r.length === 1) escolher(r[0]); } }); });\n  carregar();\n\n  // ══ competência por extenso ══\n  var comp = document.getElementById('lf-comp'), compTxt = document.getElementById('lf-comp-txt');\n  function compExt() { var v = comp.value; var m = v ? MESES[+v.slice(5, 7) - 1] : ''; compTxt.textContent = v ? m.charAt(0).toUpperCase() + m.slice(1) + ' de ' + v.slice(0, 4) : ''; }\n  comp.addEventListener('change', compExt); compExt();\n\n  // ══ previsão → vencimento ══\n  var prev1 = document.getElementById('lf-prev1'), venc1 = document.getElementById('lf-venc1'), vencManual = !NOVO && prev1.value !== venc1.value;\n  prev1.addEventListener('change', function () { if (!vencManual) venc1.value = prev1.value; if (NOVO) gerar(); });\n  venc1.addEventListener('change', function () { vencManual = venc1.value !== prev1.value; var d = document.getElementById('lf-venc-dica'); if (d) d.textContent = vencManual ? 'diferente da previsão' : 'igual à previsão — altere se for diferente'; if (NOVO) gerar(); });\n\n  // ══ rateio ══\n  var tb = document.querySelector('#lf-rateio tbody'), modelo = tb.rows[0].cloneNode(true);\n  function linhas() { return [].slice.call(tb.rows); }\n  function sync(origem) {\n    var t = cent(total.value), ls = linhas();\n    if (ls.length === 1) { ls[0].querySelector('[name=rat_valor]').value = t ? br(t) : ''; }\n    var soma = 0;\n    ls.forEach(function (tr) {\n      var v = cent(tr.querySelector('[name=rat_valor]').value); soma += v;\n      if (origem !== tr) tr.querySelector('.lf-pct').value = t ? (100 * v / t).toFixed(1).replace('.', ',') + '%' : '';\n      tr.querySelector('.lf-x').style.visibility = ls.length > 1 ? 'visible' : 'hidden';\n    });\n    document.getElementById('lf-rat-soma').textContent = br(soma);\n    document.getElementById('lf-rat-pct').textContent = t ? Math.round(100 * soma / t) + '%' : '';\n    aviso('lf-rat-aviso', t && soma !== t ? 'A soma das categorias (' + br(soma) + ') está diferente do valor total (' + br(t) + '). Diferença: ' + br(t - soma) + '.' : '');\n    document.getElementById('lf-res-cats').textContent = ls.length;\n    resumo();\n  }\n  tb.addEventListener('input', function (e) {\n    var tr = e.target.closest('tr');\n    if (e.target.classList.contains('lf-pct')) { var p = parseFloat(e.target.value.replace('%', '').replace(',', '.')) || 0;\n      tr.querySelector('[name=rat_valor]').value = br(Math.round(cent(total.value) * p / 100)); sync(tr); return; }\n    sync();\n  });\n  tb.addEventListener('blur', function (e) { if (e.target.name === 'rat_valor' && e.target.value) e.target.value = br(cent(e.target.value)); }, true);\n  tb.addEventListener('click', function (e) { var x = e.target.closest('.lf-x'); if (x && linhas().length > 1) { x.closest('tr').remove(); sync(); } });\n  document.getElementById('lf-add-rat').addEventListener('click', function () {\n    var n = modelo.cloneNode(true); n.querySelectorAll('input').forEach(function (i) { i.value = ''; }); n.querySelectorAll('select').forEach(function (s) { s.selectedIndex = 0; });\n    var falta = cent(total.value) - linhas().reduce(function (a, tr) { return a + cent(tr.querySelector('[name=rat_valor]').value); }, 0);\n    if (falta > 0) n.querySelector('[name=rat_valor]').value = br(falta);\n    tb.appendChild(n); sync(); n.querySelector('select').focus();\n  });\n  total.addEventListener('input', function () { sync(); if (NOVO) gerar(); else document.getElementById('lf-par-valor-edit').value = total.value; });\n  total.addEventListener('blur', function () { if (total.value) total.value = br(cent(total.value)); });\n\n  // ══ condição / parcelas (novo) ══\n  var tbp, hidden = document.getElementById('lf-hidden-parc');\n  function cond() { var r = f.querySelector('[name=condicao]:checked'); return r ? r.value : 'unico'; }\n  function addData(iso, i, freq) {\n    if (!iso) return '';\n    var p = iso.split('-').map(Number), m = FREQ[freq][1], dd = FREQ[freq][2], d;\n    if (m) { d = new Date(p[0], p[1] - 1 + m * i, 1); var ult = new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate(); d.setDate(Math.min(p[2], ult)); }\n    else { d = new Date(p[0], p[1] - 1, p[2] + dd * i); }\n    return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');\n  }\n  function gerar() {\n    if (!NOVO) return;\n    var c = cond(), t = cent(total.value);\n    document.querySelectorAll('.lf-so-rep').forEach(function (x) { x.hidden = c === 'unico'; });\n    document.querySelectorAll('.lf-1a').forEach(function (x) { x.hidden = c === 'unico'; });\n    document.getElementById('lf-parcelas').hidden = c === 'unico';\n    document.getElementById('lf-japago').hidden = c !== 'unico';\n    document.getElementById('lf-lbl-qtd').textContent = c === 'parcelado' ? 'Nº de parcelas' : 'Quantas vezes repetir';\n    var n = c === 'unico' ? 1 : Math.max(2, Math.min(360, parseInt(document.getElementById('lf-qtd').value) || 2)), fq = document.getElementById('lf-freq').value;\n    document.getElementById('lf-cond-dica').textContent = c === 'parcelado'\n      ? 'O valor total é dividido em ' + n + ' parcelas. Ajuste datas e valores na tabela se precisar.'\n      : 'O valor é repetido ' + n + ' vezes (' + FREQ[fq][0].toLowerCase() + '). Ajuste datas e valores na tabela se precisar.';\n    tbp = document.querySelector('#lf-parcelas tbody'); tbp.innerHTML = '';\n    var base = c === 'parcelado' ? Math.floor(t / n) : t;\n    for (var i = 0; i < n; i++) {\n      var val = c === 'parcelado' ? base + (i === 0 ? t - base * n : 0) : t;\n      var tr = document.createElement('tr');\n      tr.innerHTML = '<td>' + (i + 1) + '/' + n + '</td><td><input class=\"inp\" type=\"date\" data-p value=\"' + addData(prev1.value, i, fq) + '\"></td>' +\n        '<td><input class=\"inp\" type=\"date\" data-v value=\"' + addData(venc1.value, i, fq) + '\"></td>' +\n        '<td class=\"num\"><input class=\"inp num\" data-x inputmode=\"decimal\" placeholder=\"R$ 0,00\" value=\"' + (t ? br(val) : '') + '\"></td>';\n      tbp.appendChild(tr);\n    }\n    somaParc();\n  }\n  function somaParc() {\n    if (!tbp) return; var s = 0, n = tbp.rows.length;\n    [].forEach.call(tbp.rows, function (tr) { s += cent(tr.querySelector('[data-x]').value); });\n    document.getElementById('lf-parc-soma').textContent = br(s);\n    var t = cent(total.value);\n    aviso('lf-parc-aviso', cond() === 'parcelado' && t && s !== t ? 'A soma das parcelas (' + br(s) + ') difere do total (' + br(t) + ').' : '');\n    document.getElementById('lf-res-parc').textContent = cond() === 'unico' ? '1' : n + 'x';\n    resumo();\n  }\n  function resumo() {\n    var t = cent(total.value), tot = t;\n    if (NOVO && cond() !== 'unico' && tbp) tot = [].reduce.call(tbp.rows, function (a, tr) { return a + cent(tr.querySelector('[data-x]').value); }, 0);\n    document.getElementById('lf-res-total').textContent = br(tot);\n  }\n  if (NOVO) {\n    f.querySelectorAll('[name=condicao]').forEach(function (r) { r.addEventListener('change', gerar); });\n    ['lf-qtd', 'lf-freq'].forEach(function (id) { document.getElementById(id).addEventListener('change', gerar); });\n    document.getElementById('lf-qtd').addEventListener('input', gerar);\n    document.getElementById('lf-recalc').addEventListener('click', gerar);\n    var tabp = document.getElementById('lf-parcelas');\n    tabp.addEventListener('input', somaParc);\n    tabp.addEventListener('change', function (e) {  // previsão da parcela → vencimento igual, se ainda não foi mexido\n      if (e.target.dataset.p !== undefined) { var v = e.target.closest('tr').querySelector('[data-v]'); if (!v.dataset.manual) v.value = e.target.value; }\n      if (e.target.dataset.v !== undefined) e.target.dataset.manual = '1';\n    });\n    tabp.addEventListener('blur', function (e) { if (e.target.dataset.x !== undefined && e.target.value) e.target.value = br(cent(e.target.value)); }, true);\n    document.getElementById('lf-ja').addEventListener('change', function (e) { document.getElementById('lf-ja-campos').hidden = !e.target.checked; });\n  }\n\n  // ══ anexos ══\n  var drop = document.getElementById('lf-drop'), inp = document.getElementById('lf-arquivos'), ul = document.getElementById('lf-arqs');\n  function listar() { ul.innerHTML = ''; [].forEach.call(inp.files, function (fl) { var li = document.createElement('li'); li.textContent = fl.name + ' · ' + Math.ceil(fl.size / 1024) + ' KB'; ul.appendChild(li); }); }\n  inp.addEventListener('change', listar);\n  ['dragenter', 'dragover'].forEach(function (ev) { drop.addEventListener(ev, function (e) { e.preventDefault(); drop.classList.add('on'); }); });\n  ['dragleave', 'drop'].forEach(function (ev) { drop.addEventListener(ev, function (e) { e.preventDefault(); drop.classList.remove('on'); }); });\n  drop.addEventListener('drop', function (e) {\n    var dt = new DataTransfer(); [].forEach.call(inp.files, function (x) { dt.items.add(x); }); [].forEach.call(e.dataTransfer.files, function (x) { dt.items.add(x); });\n    inp.files = dt.files; listar();\n  });\n\n  // ══ envio ══\n  f.addEventListener('submit', function (e) {\n    if (ptxt.value.trim() && !pid.value) { e.preventDefault(); confirmar(); return; }\n    var t = cent(total.value);\n    if (!t) { e.preventDefault(); alert('Informe o valor.'); total.focus(); return; }\n    if (!linhas().some(function (tr) { return tr.querySelector('[name=rat_categoria]').value; })) { e.preventDefault(); alert('Escolha ao menos uma categoria.'); return; }\n    var soma = linhas().reduce(function (a, tr) { return a + cent(tr.querySelector('[name=rat_valor]').value); }, 0);\n    if (soma !== t && !confirm('A soma das categorias (' + br(soma) + ') é diferente do total (' + br(t) + '). O sistema vai ajustar proporcionalmente. Continuar?')) { e.preventDefault(); return; }\n    if (NOVO) {\n      hidden.innerHTML = '';\n      var rows = cond() === 'unico' ? [[prev1.value, venc1.value, br(t)]]\n        : [].map.call(tbp.rows, function (tr) { return [tr.querySelector('[data-p]').value, tr.querySelector('[data-v]').value, tr.querySelector('[data-x]').value]; });\n      if (rows.some(function (r) { return !r[1]; })) { e.preventDefault(); alert('Preencha os vencimentos.'); return; }\n      rows.forEach(function (r) {\n        hidden.insertAdjacentHTML('beforeend', '<input type=\"hidden\" name=\"par_prev\" value=\"' + (r[0] || r[1]) + '\"><input type=\"hidden\" name=\"par_venc\" value=\"' + r[1] + '\"><input type=\"hidden\" name=\"par_valor\" value=\"' + r[2] + '\">');\n      });\n    }\n  });\n  sync(); gerar();\n  if (NOVO) ptxt.focus();\n})();\n</script>\n{% endblock %}\n",
  "financas/lancamentos.html": "{% extends \"financas/_layout.html\" %}\n{% block fin_titulo %}{{ 'Contas a receber' if tipo == 'receber' else 'Contas a pagar' }}{% endblock %}\n{% block fin_conteudo %}\n{% set receber = tipo == 'receber' %}\n<div class=\"fin-head\">\n  <div>\n    <div class=\"eyebrow-line\">Finanças</div>\n    <h1>{{ 'Contas a receber' if receber else 'Contas a pagar' }}</h1>\n    <p>{{ 'Vendas, mensalidades e tudo o que a empresa tem a receber.' if receber else 'Fornecedores, impostos, folha e tudo o que a empresa tem a pagar.' }}</p>\n  </div>\n  <div class=\"fin-acoes\">\n    <a class=\"btn-pill fin-btn {{ 'entrada' if receber else 'saida' }}\" href=\"{{ url_for('financas.lancamento_novo', slug=empresa.slug, tipo=tipo, voltar=request.full_path) }}\">{{ fic('add') }} {{ 'Nova receita' if receber else 'Nova despesa' }}</a>\n  </div>\n</div>\n\n{% set ep = 'financas.lancamentos' %}{% set extra = {'tipo': tipo, 'situacao': situacao, 'q': busca, 'categoria': cat} %}\n{% include \"financas/_periodo.html\" %}\n\n<div class=\"fin-totais\">\n  <a class=\"risco {{ 'on' if situacao == 'vencido' }}\" href=\"{{ url_for(ep, slug=empresa.slug, tipo=tipo, de=de, ate=ate, situacao='vencido') }}\"><small>Vencidos</small><b>{{ moeda(tot.vencido) }}</b></a>\n  <a class=\"{{ 'on' if situacao == 'abertos' }}\" href=\"{{ url_for(ep, slug=empresa.slug, tipo=tipo, de=de, ate=ate, situacao='abertos') }}\"><small>Em aberto</small><b>{{ moeda(tot.aberto) }}</b></a>\n  <a class=\"pos {{ 'on' if situacao == 'pago' }}\" href=\"{{ url_for(ep, slug=empresa.slug, tipo=tipo, de=de, ate=ate, situacao='pago') }}\"><small>{{ 'Recebidos' if receber else 'Pagos' }}</small><b>{{ moeda(tot.pago) }}</b></a>\n  <a class=\"dark {{ 'on' if not situacao }}\" href=\"{{ url_for(ep, slug=empresa.slug, tipo=tipo, de=de, ate=ate) }}\"><small>Total do período</small><b>{{ moeda(tot.total) }}</b></a>\n</div>\n\n<form class=\"fin-filtros\" method=\"get\">\n  <input type=\"hidden\" name=\"de\" value=\"{{ de }}\"><input type=\"hidden\" name=\"ate\" value=\"{{ ate }}\">\n  <select class=\"inp\" name=\"situacao\" aria-label=\"Situação\">\n    <option value=\"\">Todas as situações</option>\n    <option value=\"abertos\" {{ 'selected' if situacao == 'abertos' }}>Em aberto (inclui vencidos)</option>\n    {% for k, v in SITUACOES.items() %}<option value=\"{{ k }}\" {{ 'selected' if situacao == k }}>{{ v }}</option>{% endfor %}\n  </select>\n  <select class=\"inp\" name=\"categoria\" aria-label=\"Categoria\">\n    <option value=\"\">Todas as categorias</option>\n    {% for c in categorias %}<option value=\"{{ c.id }}\" {{ 'selected' if cat == c.id }}>{{ c.nome }}</option>{% endfor %}\n  </select>\n  <label class=\"search\">{{ ic('search') }}<input type=\"search\" name=\"q\" value=\"{{ busca }}\" placeholder=\"Descrição, {{ 'cliente' if receber else 'fornecedor' }} ou documento\"></label>\n  <button class=\"btn-pill outline fin-btn\" type=\"submit\">Filtrar</button>\n</form>\n\n<form method=\"post\" action=\"{{ url_for('financas.lote_baixar', slug=empresa.slug) }}\" id=\"form-lote\">\n  <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n  <input type=\"hidden\" name=\"voltar\" value=\"{{ request.full_path }}\">\n  <div class=\"fin-lote\" id=\"barra-lote\" hidden>\n    <span><b id=\"lote-n\">0</b> selecionado(s) · <b id=\"lote-total\">R$ 0,00</b></span>\n    <select class=\"inp\" name=\"conta_id\" required aria-label=\"Conta\"><option value=\"\">Conta…</option>\n      {% for c in contas_ativas %}<option value=\"{{ c.id }}\" {{ 'selected' if loop.first }}>{{ c.nome }}</option>{% endfor %}</select>\n    <input class=\"inp\" type=\"date\" name=\"data\" value=\"{{ hoje_iso }}\" aria-label=\"Data\">\n    <button class=\"btn-pill fin-btn\" type=\"submit\">{{ 'Receber' if receber else 'Pagar' }} selecionados</button>\n  </div>\n  <div class=\"fin-tabela-wrap\">\n    <table class=\"fin-tabela\">\n      <thead><tr>\n        <th class=\"ck\"><input type=\"checkbox\" id=\"ck-todos\" aria-label=\"Selecionar todos\"></th>\n        <th>Vencimento</th><th>Descrição</th><th>Categoria</th><th class=\"num\">Valor</th><th class=\"num\">{{ 'Recebido' if receber else 'Pago' }}</th><th>Situação</th><th></th>\n      </tr></thead>\n      <tbody>\n      {% for l in lista %}\n        <tr class=\"sit-{{ l.situacao }}\">\n          <td class=\"ck\">{% if l.situacao in ('aberto','vencido','parcial') %}<input type=\"checkbox\" name=\"ids\" value=\"{{ l.id }}\" data-saldo=\"{{ l.saldo }}\" aria-label=\"Selecionar\">{% endif %}</td>\n          <td data-rot=\"Vencimento\" class=\"dt\">{{ data_br(l.vencimento) }}</td>\n          <td data-rot=\"Descrição\" class=\"desc\"><a href=\"{{ url_for('financas.lancamento', slug=empresa.slug, lid=l.id) }}\"><b>{{ l.descricao }}</b></a>{% if l.n_anexos %} <span class=\"fin-chip\" title=\"{{ l.n_anexos }} anexo(s)\">📎 {{ l.n_anexos }}</span>{% endif %}\n            <small>{{ l.pessoa_nome or '—' }}{% if l.documento %} · Doc. {{ l.documento }}{% endif %}{% if l.parcelas > 1 %} · parcela {{ l.parcela }}/{{ l.parcelas }}{% endif %}</small></td>\n          <td data-rot=\"Categoria\">{{ l.categoria_nome or '—' }}</td>\n          <td data-rot=\"Valor\" class=\"num\">{{ moeda(l.valor) }}</td>\n          <td data-rot=\"{{ 'Recebido' if receber else 'Pago' }}\" class=\"num\">{{ moeda(l.pago) if l.pago else '—' }}</td>\n          <td data-rot=\"Situação\"><span class=\"fin-sit {{ l.situacao }}\">{{ SITUACOES[l.situacao] }}</span></td>\n          <td class=\"acoes\">\n            {% if l.situacao in ('aberto','vencido','parcial') %}\n              <button type=\"button\" class=\"btn-pill fin-btn mini\" data-baixar=\"{{ l.id }}\" data-desc=\"{{ l.descricao }}\" data-saldo=\"{{ valor_campo(l.saldo) }}\" data-conta=\"{{ l.conta_id or '' }}\">{{ 'Receber' if receber else 'Pagar' }}</button>\n            {% endif %}\n            <a class=\"ico\" href=\"{{ url_for('financas.lancamento', slug=empresa.slug, lid=l.id) }}\" title=\"Abrir\">{{ fic('edit') }}</a>\n          </td>\n        </tr>\n      {% else %}\n        <tr class=\"vazio\"><td colspan=\"8\">Nenhum lançamento neste período. Use “{{ 'Nova receita' if receber else 'Nova despesa' }}”.</td></tr>\n      {% endfor %}\n      </tbody>\n    </table>\n  </div>\n</form>\n\n{% include \"financas/_dlg_lancamento.html\" %}\n{% include \"financas/_dlg_baixa.html\" %}\n{% endblock %}\n{% block fin_scripts %}\n<script>\n(function () {\n  var cks = Array.from(document.querySelectorAll('input[name=ids]')), barra = document.getElementById('barra-lote');\n  function fmt(c) { return (c / 100).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' }); }\n  function atualizar() {\n    var sel = cks.filter(function (c) { return c.checked; });\n    barra.hidden = !sel.length;\n    document.getElementById('lote-n').textContent = sel.length;\n    document.getElementById('lote-total').textContent = fmt(sel.reduce(function (a, c) { return a + Number(c.dataset.saldo); }, 0));\n  }\n  cks.forEach(function (c) { c.addEventListener('change', atualizar); });\n  var todos = document.getElementById('ck-todos');\n  if (todos) todos.addEventListener('change', function () { cks.forEach(function (c) { c.checked = todos.checked; }); atualizar(); });\n})();\n</script>\n{% endblock %}\n",
  "financas/painel.html": "{% extends \"financas/_layout.html\" %}\n{% block fin_titulo %}Visão geral{% endblock %}\n{% block fin_conteudo %}\n{% set CORES = ['#C7A955', '#2F6B1A', '#3B6EA8', '#8E4FA0', '#B3261E', '#5F7A86', '#C77B2B'] %}\n<div class=\"fin-head\">\n  <div>\n    <div class=\"eyebrow-line\">Finanças · {{ data_br(hoje_iso) }}</div>\n    <h1>Visão geral</h1>\n    <p>Resumo da empresa: saldos, o que entra, o que sai, atrasos{% if produtos %} e os produtos{% endif %}.</p>\n  </div>\n</div>\n\n{% if sem_contas %}\n<div class=\"fin-onboarding\">\n  <h3>Primeiros passos</h3>\n  <ol>\n    <li><a href=\"{{ url_for('financas.cad_contas', slug=empresa.slug) }}\">Cadastre as contas bancárias</a> com o saldo inicial.</li>\n    <li>Revise o <a href=\"{{ url_for('financas.cad_categorias', slug=empresa.slug) }}\">plano de categorias</a> (já vem um modelo pronto).</li>\n    <li>Cadastre <a href=\"{{ url_for('financas.cad_pessoas', slug=empresa.slug) }}\">clientes e fornecedores</a>.</li>\n    <li>Lance contas a receber e a pagar, ou importe o extrato OFX na <a href=\"{{ url_for('financas.conciliacao', slug=empresa.slug) }}\">conciliação</a>.</li>\n  </ol>\n</div>\n{% endif %}\n\n{# ── Indicadores principais ── #}\n<div class=\"vg-kpis\">\n  <a class=\"vg-kpi escuro\" href=\"{{ url_for('financas.extrato', slug=empresa.slug) }}\">\n    <small>{{ fic('banco') }} Saldo em contas</small>\n    <b class=\"{{ 'neg' if saldo_atual < 0 }}\">{{ moeda(saldo_atual) }}</b>\n    <em>{{ contas|length }} conta(s) corrente(s) e aplicação(ões)</em>\n  </a>\n  <a class=\"vg-kpi\" href=\"{{ url_for('financas.lancamentos', slug=empresa.slug, tipo='receber', situacao='abertos', de='2000-01-01', ate='2100-12-31') }}\">\n    <small>{{ fic('receber') }} A receber</small>\n    <b class=\"pos\">{{ moeda(ind.receber.valor) }}</b>\n    <em>{{ ind.receber.n }} título(s) em aberto</em>\n  </a>\n  <a class=\"vg-kpi\" href=\"{{ url_for('financas.lancamentos', slug=empresa.slug, tipo='pagar', situacao='abertos', de='2000-01-01', ate='2100-12-31') }}\">\n    <small>{{ fic('pagar') }} A pagar</small>\n    <b class=\"neg\">{{ moeda(ind.pagar.valor) }}</b>\n    <em>{{ ind.pagar.n }} título(s) em aberto</em>\n  </a>\n  <div class=\"vg-kpi {{ 'alerta' if ind.atraso }}\">\n    <small>{{ fic('relogio') }} Em atraso</small>\n    <b class=\"{{ 'neg' if ind.atraso }}\">{{ moeda(ind.atraso) }}</b>\n    <em>Receber {{ moeda(ind.receber_venc.valor) }} · Pagar {{ moeda(ind.pagar_venc.valor) }}</em>\n  </div>\n  <a class=\"vg-kpi\" href=\"{{ url_for('financas.rel_fluxo', slug=empresa.slug) }}\">\n    <small>{{ fic('fluxo') }} Resultado do mês</small>\n    <b class=\"{{ 'neg' if mes.entradas - mes.saidas < 0 else 'pos' }}\">{{ moeda(mes.entradas - mes.saidas) }}</b>\n    <em>Entrou {{ moeda(mes.entradas) }} · saiu {{ moeda(mes.saidas) }}</em>\n  </a>\n  <div class=\"vg-kpi\">\n    <small>{{ fic('calendario') }} Saldo em 30 dias</small>\n    <b class=\"{{ 'neg' if proj[-1].saldo < 0 }}\">{{ moeda(proj[-1].saldo) }}</b>\n    <em>Menor saldo previsto {{ moeda(proj|map(attribute='saldo')|min) }}</em>\n  </div>\n</div>\n\n{# ── Contas, receber e pagar ── #}\n<div class=\"vg-grade\">\n  <section class=\"vg-box\">\n    <header><h3>Saldo por conta</h3><a href=\"{{ url_for('financas.cad_contas', slug=empresa.slug) }}\">Contas bancárias</a></header>\n    <div class=\"vg-contas-rol\"><ul class=\"vg-contas\">\n      {% for c in contas|sort(attribute='saldo', reverse=True) %}\n        {% set cor = CORES[loop.index0 % CORES|length] if (not c.cor or c.cor|upper == '#C9A45C') else c.cor %}\n        <li>\n          <span class=\"cor\" style=\"background:{{ cor }}\"></span>\n          <span class=\"nm\"><b>{{ c.nome }}</b><small>{{ c.banco or TIPOS_CONTA.get(c.tipo, '') }}</small></span>\n          <span class=\"vl {{ 'neg' if c.saldo < 0 }}\" style=\"{{ 'color:var(--fin-neg)' if c.saldo < 0 }}\">{{ moeda(c.saldo) }}</span>\n          <span class=\"barra\"><i style=\"width:{{ (100 * (c.saldo|abs) / maior)|round(1) }}%;background:{{ 'var(--fin-neg)' if c.saldo < 0 else cor }}\"></i></span>\n        </li>\n      {% else %}\n        <li><span></span><span class=\"nm\"><b>Nenhuma conta cadastrada</b></span><span></span></li>\n      {% endfor %}\n    </ul></div>\n    <ul class=\"vg-contas\">\n      <li class=\"total\"><span></span><span class=\"nm\"><b>Total</b></span>\n        <span class=\"vl\" style=\"{{ 'color:var(--fin-neg)' if saldo_atual < 0 }}\">{{ moeda(saldo_atual) }}</span></li>\n    </ul>\n    <div class=\"vg-ind\">\n      <div title=\"Quanto do total a receber já está vencido\"><small>Inadimplência</small><b style=\"{{ 'color:var(--fin-neg)' if ind.inadimplencia > 10 }}\">{{ '%.1f'|format(ind.inadimplencia) }}%</b></div>\n      <div title=\"Saldo atual dividido pelo que vence a pagar nos próximos 30 dias\"><small>Cobertura de caixa</small><b>{{ ('%.1fx'|format(ind.cobertura)) if ind.cobertura is not none else '—' }}</b></div>\n      <div title=\"Saldo + a receber − a pagar (vencidos e próximos 30 dias)\"><small>Líquido 30 dias</small><b style=\"{{ 'color:var(--fin-neg)' if ind.liquido_30 < 0 }}\">{{ moeda(ind.liquido_30) }}</b></div>\n    </div>\n  </section>\n\n  {% for tp, rot, chave in [('receber', 'Contas a receber', 'receber'), ('pagar', 'Contas a pagar', 'pagar')] %}\n  <section class=\"vg-box\">\n    <header><h3>{{ fic(tp) }} {{ rot }}</h3><a href=\"{{ url_for('financas.lancamentos', slug=empresa.slug, tipo=tp) }}\">Abrir</a></header>\n    <div class=\"vg-linhas\">\n      <a class=\"risco\" href=\"{{ url_for('financas.lancamentos', slug=empresa.slug, tipo=tp, situacao='vencido', de='2000-01-01', ate=hoje_iso) }}\">\n        <span>Vencido ({{ ind[chave ~ '_venc'].n }})</span><b>{{ moeda(ind[chave ~ '_venc'].valor) }}</b></a>\n      <a href=\"{{ url_for('financas.lancamentos', slug=empresa.slug, tipo=tp, situacao='abertos', de=hoje_iso, ate=hoje_iso) }}\">\n        <span>Vence hoje</span><b>{{ moeda(cards[chave ~ '_hoje']) }}</b></a>\n      <a href=\"{{ url_for('financas.lancamentos', slug=empresa.slug, tipo=tp, situacao='abertos') }}\">\n        <span>Próximos 7 dias</span><b>{{ moeda(cards[chave ~ '_7']) }}</b></a>\n      <a href=\"{{ url_for('financas.lancamentos', slug=empresa.slug, tipo=tp, situacao='abertos', de=hoje_iso) }}\">\n        <span>Próximos 30 dias ({{ ind[chave ~ '_30'].n }})</span><b>{{ moeda(ind[chave ~ '_30'].valor) }}</b></a>\n      <div class=\"total\"><span>Total em aberto</span><b>{{ moeda(ind[chave].valor) }}</b></div>\n    </div>\n  </section>\n  {% endfor %}\n</div>\n\n{# ── Projeção e agenda ── #}\n<div class=\"vg-cols\">\n  <section class=\"vg-box\">\n    <header><h3>Saldo projetado — próximos 30 dias</h3><span>saldo atual + a receber − a pagar</span></header>\n    {% set vals = proj|map(attribute='saldo')|list %}\n    {% set mx = [vals|max, 0]|max %}{% set mn = [vals|min, 0]|min %}{% set amp = (mx - mn) or 1 %}\n    <svg class=\"fin-graf\" viewBox=\"0 0 620 190\" preserveAspectRatio=\"none\" role=\"img\" aria-label=\"Saldo projetado\">\n      {% set y0 = 10 + (mx - 0) * 150 / amp %}\n      <line x1=\"10\" x2=\"610\" y1=\"{{ y0 }}\" y2=\"{{ y0 }}\" class=\"zero\"/>\n      <polyline class=\"linha\" fill=\"none\" points=\"{% for p in proj %}{{ 10 + loop.index0 * 20 }},{{ 10 + (mx - p.saldo) * 150 / amp }} {% endfor %}\"/>\n      {% for p in proj %}{% if loop.index0 % 5 == 0 %}\n        <text x=\"{{ 10 + loop.index0 * 20 }}\" y=\"185\" text-anchor=\"middle\">{{ data_br(p.dia)[:5] }}</text>{% endif %}{% endfor %}\n    </svg>\n    <div class=\"fin-graf-leg\"><span>Hoje: <b>{{ moeda(proj[0].saldo) }}</b></span><span>Em 30 dias: <b class=\"{{ 'neg' if proj[-1].saldo < 0 }}\">{{ moeda(proj[-1].saldo) }}</b></span>\n      <span>Menor saldo: <b class=\"{{ 'neg' if vals|min < 0 }}\">{{ moeda(vals|min) }}</b></span></div>\n  </section>\n  <section class=\"vg-box\">\n    <header><h3>Vencidos e próximos 7 dias</h3></header>\n    <ul class=\"fin-prox\">\n      {% for l in proximos %}\n        <li><a href=\"{{ url_for('financas.lancamento', slug=empresa.slug, lid=l.id) }}\">\n          <span class=\"fin-seta {{ l.tipo }}\">{{ fic(l.tipo) }}</span>\n          <span class=\"txt\"><b>{{ l.descricao }}</b><small>{{ l.pessoa_nome or l.categoria_nome or '—' }}</small></span>\n          <span class=\"dir\"><b class=\"{{ 'neg' if l.tipo == 'pagar' }}\">{{ moeda(l.saldo) }}</b>\n            <small class=\"{{ 'risco' if l.situacao == 'vencido' }}\">{{ 'Venceu ' if l.situacao == 'vencido' }}{{ data_br(l.vencimento) }}</small></span>\n        </a></li>\n      {% else %}\n        <li class=\"vazio\">Nada vencido nem vencendo nos próximos 7 dias.</li>\n      {% endfor %}\n    </ul>\n  </section>\n</div>\n\n{# ── Produtos (Capuzzo Assessoria) ── #}\n{% if produtos %}\n{% set pc = produtos.condominios %}{% set pt = produtos.titulos %}{% set pg = produtos.tatica %}\n<div class=\"vg-secao\"><h2>Produtos</h2></div>\n<div class=\"vg-prods\">\n  <section class=\"vg-box vg-prod\">\n    <header><h3>{{ fic('predio') }} Condomínios</h3><a href=\"{{ url_for('financas.cond_painel', slug=empresa.slug) }}\">Abrir</a></header>\n    <div class=\"vg-big\"><small>Patrimônio ativo</small>{{ pc.patrimonio_fmt }}</div>\n    <div class=\"vg-linhas\">\n      <div><span>Cotas ativas · cotistas</span><b>{{ pc.cotas_ativas }} · {{ pc.cotistas }}</b></div>\n      <div><span>Rendimento mensal estimado</span><b>{{ pc.rendimento_fmt }}</b></div>\n      <a href=\"{{ url_for('financas.cond_vencimentos', slug=empresa.slug) }}\"><span>Vencem em 30 dias</span><b>{{ pc.vencem_30 }} cota(s)</b></a>\n      <a href=\"{{ url_for('financas.cond_vencimentos', slug=empresa.slug, aba='retiradas') }}\"><span>Retiradas solicitadas</span><b>{{ pc.retiradas }}</b></a>\n      <a href=\"{{ url_for('financas.cond_contratos', slug=empresa.slug) }}\"><span>Contratos a assinar / aguardando depósito</span><b>{{ pc.contratos_aguardando }} / {{ pc.contratos_deposito }}</b></a>\n    </div>\n  </section>\n  <section class=\"vg-box vg-prod\">\n    <header><h3>{{ fic('titulo') }} Títulos Privados</h3><a href=\"{{ url_for('financas.titulos_painel', slug=empresa.slug) }}\">Abrir</a></header>\n    <div class=\"vg-big\"><small>Carteira a receber</small>{{ pt.a_receber_fmt }}</div>\n    <div class=\"vg-linhas\">\n      <div><span>Empréstimos ativos</span><b>{{ pt.ativos }}</b></div>\n      <div class=\"{{ 'risco' if pt.vencidas }}\"><span>Parcelas vencidas</span><b>{{ pt.vencidas }} · {{ pt.vencido_fmt }}</b></div>\n      <div><span>Próxima parcela</span><b>{{ pt.proxima or '—' }}</b></div>\n    </div>\n  </section>\n  <a class=\"vg-box vg-prod\" href=\"{{ url_for('financas.tatica_painel', slug=empresa.slug) }}\" style=\"text-decoration:none;color:inherit\">\n    <header><h3>{{ fic('tatica') }} Gestão Tática</h3><span>{{ pg.rotulo or '' }}</span></header>\n    {% if pg.uc %}\n    <div class=\"vg-big\"><small>Patrimônio sob gestão</small>{{ pg.saldo_fmt }}</div>\n    <div class=\"vg-linhas\">\n      <div><span>Clientes com banca</span><b>{{ pg.n }}</b></div>\n      <div><span>Resultado bruto · rentabilidade</span><b>{{ pg.bruto_fmt }} · {{ '%.2f'|format((pg.rentab or 0) * 100) }}%</b></div>\n      <div><span>Taxa de gestão + tarifas</span><b>{{ pg.receita_fmt }}</b></div>\n    </div>\n    {% else %}\n    <div class=\"vg-big\"><small>Importe a planilha da GT</small>—</div>\n    {% endif %}\n  </a>\n</div>\n{% endif %}\n\n{% endblock %}\n",
  "financas/rel_dre.html": "{% extends \"financas/_layout.html\" %}\n{% block fin_titulo %}DRE {{ ano }}{% endblock %}\n{% block fin_conteudo %}\n<div class=\"fin-head\">\n  <div>\n    <div class=\"eyebrow-line\">Relatórios</div>\n    <h1>DRE gerencial</h1>\n    <p>Resultado por grupo e categoria. Competência: pela data de competência dos lançamentos. Caixa: pela data em que foi pago/recebido.</p>\n  </div>\n  <div class=\"fin-ano\">\n    <div class=\"chips\">\n      <a class=\"chip {{ 'on' if regime == 'competencia' }}\" href=\"{{ url_for('financas.rel_dre', slug=empresa.slug, ano=ano, regime='competencia') }}\">Competência</a>\n      <a class=\"chip {{ 'on' if regime == 'caixa' }}\" href=\"{{ url_for('financas.rel_dre', slug=empresa.slug, ano=ano, regime='caixa') }}\">Caixa</a>\n    </div>\n    <a class=\"fin-seta-mes\" href=\"{{ url_for('financas.rel_dre', slug=empresa.slug, ano=ano - 1, regime=regime) }}\">‹</a><b>{{ ano }}</b>\n    <a class=\"fin-seta-mes\" href=\"{{ url_for('financas.rel_dre', slug=empresa.slug, ano=ano + 1, regime=regime) }}\">›</a>\n  </div>\n</div>\n{% macro linha_total(rot, t, classe='') %}\n  <tr class=\"fin-dre-total {{ classe }}\"><td>{{ rot }}</td>{% for v in t.meses %}<td class=\"num {{ 'neg' if v < 0 }}\">{{ moeda(v) if v else '—' }}</td>{% endfor %}\n    <td class=\"num {{ 'neg' if t.total < 0 }}\"><b>{{ moeda(t.total) }}</b></td></tr>\n{% endmacro %}\n{% set ordem_chaves = r.ordem|map(attribute='chave')|list %}\n<div class=\"fin-tabela-wrap fin-dre-wrap\">\n  <table class=\"fin-tabela fin-dre\">\n    <thead><tr><th>Conta</th>{% for m in MESES[1:] %}<th class=\"num\">{{ m }}</th>{% endfor %}<th class=\"num\">Total</th></tr></thead>\n    <tbody>\n    {% if not r.ordem %}\n      <tr class=\"vazio\"><td colspan=\"14\">Nenhum lançamento em {{ ano }} ({{ regime }}).</td></tr>\n    {% endif %}\n    {% for chave in ['receita_bruta','deducoes','custos','despesas_operacionais','pessoal','receitas_financeiras','despesas_financeiras','outras_receitas','outras_despesas','sem_categoria','impostos_lucro','investimentos'] %}\n      {% if chave in ordem_chaves %}{% set gr = r.grupos[chave] %}\n      <tr class=\"fin-dre-grupo\"><td>{{ gr.nome }}</td>{% for v in gr.meses %}<td class=\"num {{ 'neg' if v < 0 }}\">{{ moeda(v) if v else '—' }}</td>{% endfor %}<td class=\"num\"><b>{{ moeda(gr.total) }}</b></td></tr>\n      {% for c in gr.cats %}\n        <tr class=\"fin-dre-cat\"><td>{{ c.nome }}</td>{% for v in c.meses %}<td class=\"num\">{{ moeda(v) if v else '' }}</td>{% endfor %}<td class=\"num\">{{ moeda(c.total) }}</td></tr>\n      {% endfor %}\n      {% endif %}\n      {% if chave == 'deducoes' %}{{ linha_total('= Receita líquida', r.totais.receita_liquida) }}{% endif %}\n      {% if chave == 'custos' %}{{ linha_total('= Lucro bruto', r.totais.lucro_bruto) }}{% endif %}\n      {% if chave == 'pessoal' %}{{ linha_total('= Resultado operacional (EBITDA)', r.totais.resultado_operacional) }}{% endif %}\n      {% if chave == 'sem_categoria' %}{{ linha_total('= Resultado antes do IR', r.totais.resultado_antes_ir) }}{% endif %}\n      {% if chave == 'impostos_lucro' %}{{ linha_total('= Resultado líquido', r.totais.resultado_liquido, 'final') }}{% endif %}\n    {% endfor %}\n    </tbody>\n  </table>\n</div>\n<p class=\"fin-sub\">Investimentos aparecem na DRE para conferência, mas não entram no resultado (como no Conta Azul).</p>\n{% endblock %}\n",
  "financas/rel_fluxo.html": "{% extends \"financas/_layout.html\" %}\n{% block fin_titulo %}Fluxo de caixa {{ ano }}{% endblock %}\n{% block fin_conteudo %}\n<div class=\"fin-head\">\n  <div>\n    <div class=\"eyebrow-line\">Relatórios</div>\n    <h1>Fluxo de caixa</h1>\n    <p>Realizado (pagamentos e recebimentos efetivos) e previsto (em aberto, pelo vencimento), mês a mês.</p>\n  </div>\n  <div class=\"fin-ano\">\n    <a class=\"fin-seta-mes\" href=\"{{ url_for('financas.rel_fluxo', slug=empresa.slug, ano=ano - 1) }}\">‹</a><b>{{ ano }}</b>\n    <a class=\"fin-seta-mes\" href=\"{{ url_for('financas.rel_fluxo', slug=empresa.slug, ano=ano + 1) }}\">›</a>\n  </div>\n</div>\n<section class=\"fin-box\">\n  <div class=\"fin-leg\"><span><i class=\"ent\"></i>Entradas realizadas</span><span><i class=\"ent prev\"></i>Entradas previstas</span>\n    <span><i class=\"sai\"></i>Saídas realizadas</span><span><i class=\"sai prev\"></i>Saídas previstas</span></div>\n  <svg class=\"fin-barras\" viewBox=\"0 0 1200 260\" role=\"img\" aria-label=\"Fluxo de caixa mensal\">\n    {% for m in meses %}\n      {% set x = 20 + loop.index0 * 98 %}\n      {% set he = (m.entradas * 210 / maior) %}{% set hpe = (m.prev_entradas * 210 / maior) %}\n      {% set hs = (m.saidas * 210 / maior) %}{% set hps = (m.prev_saidas * 210 / maior) %}\n      <rect class=\"ent\" x=\"{{ x }}\" y=\"{{ 225 - he }}\" width=\"36\" height=\"{{ he }}\"><title>{{ m.nome }}: entradas {{ moeda(m.entradas) }}</title></rect>\n      <rect class=\"ent prev\" x=\"{{ x }}\" y=\"{{ 225 - he - hpe }}\" width=\"36\" height=\"{{ hpe }}\"><title>{{ m.nome }}: a receber {{ moeda(m.prev_entradas) }}</title></rect>\n      <rect class=\"sai\" x=\"{{ x + 40 }}\" y=\"{{ 225 - hs }}\" width=\"36\" height=\"{{ hs }}\"><title>{{ m.nome }}: saídas {{ moeda(m.saidas) }}</title></rect>\n      <rect class=\"sai prev\" x=\"{{ x + 40 }}\" y=\"{{ 225 - hs - hps }}\" width=\"36\" height=\"{{ hps }}\"><title>{{ m.nome }}: a pagar {{ moeda(m.prev_saidas) }}</title></rect>\n      <text x=\"{{ x + 38 }}\" y=\"248\" text-anchor=\"middle\">{{ m.nome }}</text>\n    {% endfor %}\n    <line x1=\"10\" x2=\"1190\" y1=\"225\" y2=\"225\" class=\"base\"/>\n  </svg>\n</section>\n<div class=\"fin-tabela-wrap\">\n  <table class=\"fin-tabela fin-rel\">\n    <thead><tr><th>Mês</th><th class=\"num\">Entradas</th><th class=\"num\">A receber</th><th class=\"num\">Saídas</th><th class=\"num\">A pagar</th><th class=\"num\">Resultado do mês</th><th class=\"num\">Acumulado</th></tr></thead>\n    <tbody>\n      {% for m in meses %}{% set r = m.entradas + m.prev_entradas - m.saidas - m.prev_saidas %}\n      <tr><td><b>{{ m.nome }}/{{ ano }}</b></td>\n        <td class=\"num pos\">{{ moeda(m.entradas) if m.entradas else '—' }}</td><td class=\"num\">{{ moeda(m.prev_entradas) if m.prev_entradas else '—' }}</td>\n        <td class=\"num risco\">{{ moeda(m.saidas) if m.saidas else '—' }}</td><td class=\"num\">{{ moeda(m.prev_saidas) if m.prev_saidas else '—' }}</td>\n        <td class=\"num {{ 'neg' if r < 0 }}\"><b>{{ moeda(r) if r else '—' }}</b></td><td class=\"num {{ 'neg' if acum[loop.index0] < 0 }}\">{{ moeda(acum[loop.index0]) }}</td></tr>\n      {% endfor %}\n    </tbody>\n    <tfoot><tr><td>Total</td>\n      <td class=\"num\">{{ moeda(meses|sum(attribute='entradas')) }}</td><td class=\"num\">{{ moeda(meses|sum(attribute='prev_entradas')) }}</td>\n      <td class=\"num\">{{ moeda(meses|sum(attribute='saidas')) }}</td><td class=\"num\">{{ moeda(meses|sum(attribute='prev_saidas')) }}</td>\n      <td class=\"num\">{{ moeda(acum[-1]) }}</td><td></td></tr></tfoot>\n  </table>\n</div>\n{% endblock %}\n",
  "historico.html": "{% extends \"base.html\" %}\n{% block title %}Histórico de Apurações — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n\n<div class=\"page-header\">\n  <div class=\"page-header-icon\">📈</div>\n  <div class=\"page-header-title\">Histórico de Apurações</div>\n  <div class=\"page-header-sub\">Apurações mensais salvas — consulte, edite ou exclua registros anteriores.</div>\n</div>\n\n<div style=\"display:flex;justify-content:flex-end;margin-bottom:16px;\">\n  <a href=\"{{ url_for('apuracao') }}\" class=\"btn btn-primary\">+ Nova Apuração</a>\n</div>\n\n{% if calcs %}\n<div class=\"table-wrap\">\n  <table>\n    <thead>\n      <tr>\n        <th>Mês/Ano</th>\n        <th>Produto</th>\n        <th style=\"text-align:center;\">Clientes</th>\n        <th style=\"text-align:center;\">Cotas</th>\n        <th style=\"text-align:right;\">Taxa Agro</th>\n        <th>Salvo em</th>\n        <th style=\"text-align:right;color:#d4af37;\">Total Apurado</th>\n        <th style=\"text-align:center;\">Ações</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for c in calcs %}\n      <tr>\n        <td style=\"font-weight:700;color:#d4af37;font-size:16px;\">\n          {{ '%02d'|format(c.calculation_month) }}/{{ c.calculation_year }}\n        </td>\n        <td>\n          {% if c.condominium_name %}\n            {% if 'Civil' in c.condominium_name %}<span class=\"badge badge-civil\">🏗️ Civil</span>\n            {% elif 'gro' in c.condominium_name %}<span class=\"badge badge-agro\">🌾 Agro</span>\n            {% else %}<span class=\"badge badge-saude\">🏥 Saúde</span>{% endif %}\n          {% else %}\n            <span style=\"color:#888;font-size:12px;\">Todos os produtos</span>\n          {% endif %}\n        </td>\n        <td style=\"text-align:center;color:#4ade80;font-weight:600;\">{{ c.qty_clients }}</td>\n        <td style=\"text-align:center;color:#888;\">{{ c.qty_shares }}</td>\n        <td style=\"text-align:right;color:#888;font-size:12px;\">\n          {% if c.agro_special_rate %}{{ \"%.2f\"|format(c.agro_special_rate * 100) }}%{% else %}—{% endif %}\n        </td>\n        <td class=\"text-dim\" style=\"font-size:12px;\">{{ c.calculated_at }}</td>\n        <td style=\"text-align:right;font-weight:700;color:#d4af37;\">{{ formatar_moeda(c.total_income) }}</td>\n        <td style=\"text-align:center;\">\n          <div style=\"display:flex;gap:6px;justify-content:center;align-items:center;flex-wrap:wrap;\">\n            <a href=\"{{ url_for('historico_detalhe', calc_id=c.id) }}\"\n               class=\"btn btn-secondary btn-sm\">Ver Detalhes</a>\n            <a href=\"{{ url_for('historico_editar', calculation_id=c.id) }}\"\n               class=\"btn btn-secondary btn-sm\">✏️ Editar</a>\n            <form method=\"POST\"\n                  action=\"{{ url_for('historico_excluir', calculation_id=c.id) }}\"\n                  onsubmit=\"return confirm('Excluir esta apuração do histórico?\\n\\nAs cotas e clientes não serão alterados.');\"\n                  style=\"display:inline;\">\n              <button type=\"submit\" class=\"btn btn-danger btn-sm\">Excluir</button>\n            </form>\n          </div>\n        </td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n<div style=\"font-size:11px;color:#555;margin-top:8px;text-align:right;\">\n  {{ calcs|length }} apuração(ões) salva(s)\n</div>\n{% else %}\n<div class=\"empty-state\">\n  <div class=\"empty-state-icon\">📈</div>\n  <div class=\"empty-state-title\">Nenhuma apuração salva</div>\n  <div class=\"empty-state-text\">Realize e salve uma apuração para ela aparecer aqui.</div>\n  <a href=\"{{ url_for('apuracao') }}\" class=\"btn btn-primary\">Ir para Apuração</a>\n</div>\n{% endif %}\n\n{% endblock %}\n",
  "historico_detalhe.html": "{% extends \"base.html\" %}\n{% block title %}Detalhes da Apuração #{{ calc_id }} — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n\n<div style=\"display:flex;align-items:center;gap:12px;margin-bottom:8px;\">\n  <a href=\"{{ url_for('historico') }}\" class=\"back-link\">← Histórico</a>\n  <div style=\"flex:1;\"></div>\n  <a href=\"{{ url_for('historico_exportar_planilha', calc_id=calc_id) }}\"\n     class=\"btn btn-primary\"\n     title=\"Gera o Excel no padrão da planilha de controle: uma aba consolidada por cliente e outra de vencimentos, separadas por produto\">\n    📊 Exportar Excel (padrão planilha)\n  </a>\n  <a href=\"{{ url_for('historico_editar', calculation_id=calc_id) }}\" class=\"btn btn-secondary\">✏️ Editar Apuração</a>\n  <form method=\"POST\" action=\"{{ url_for('historico_excluir', calculation_id=calc_id) }}\"\n        onsubmit=\"return confirm('Excluir esta apuração? As cotas e clientes não serão alterados.');\"\n        style=\"display:inline;\">\n    <button type=\"submit\" class=\"btn btn-danger\">Excluir</button>\n  </form>\n</div>\n\n<div class=\"page-header\">\n  <div class=\"page-header-icon\">📐</div>\n  <div class=\"page-header-title\">\n    Apuração #{{ calc_id }}\n    {% if calc_meta %}\n    · {{ '%02d'|format(calc_meta.calculation_month) }}/{{ calc_meta.calculation_year }}\n    {% if calc_meta.condominium_name %}— {{ calc_meta.condominium_name }}{% else %}— Todos os Produtos{% endif %}\n    {% endif %}\n  </div>\n  <div class=\"page-header-sub\">\n    Salvo em {{ calc_meta.calculated_at if calc_meta else '—' }}\n    {% if calc_meta and calc_meta.notes %} · <em>{{ calc_meta.notes }}</em>{% endif %}\n  </div>\n</div>\n\n<!-- KPIs -->\n<div class=\"metrics-grid\" style=\"grid-template-columns:repeat(4,1fr);margin-bottom:24px;\">\n  <div class=\"metric-card\">\n    <div class=\"metric-value text-gold\">{{ formatar_moeda(total_geral) }}</div>\n    <div class=\"metric-label\">Total Apurado</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#4ade80;\">{{ clients|length }}</div>\n    <div class=\"metric-label\">Clientes</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\">{{ total_shares }}</div>\n    <div class=\"metric-label\">Cotas</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#888;font-size:13px;\">\n      {{ calc_meta.condominium_name if calc_meta and calc_meta.condominium_name else 'Todos' }}\n    </div>\n    <div class=\"metric-label\">Produto</div>\n  </div>\n</div>\n\n<!-- Consolidado por cliente -->\n<div class=\"section-label\" style=\"margin-bottom:12px;\">● Consolidado por Cliente</div>\n<div class=\"table-wrap\" style=\"margin-bottom:8px;\">\n  <table>\n    <thead>\n      <tr>\n        <th style=\"width:34px;text-align:center;color:#4ade80;\"\n            title=\"Marque conforme confere cada pessoa no banco\">✓</th>\n        <th style=\"width:32px;\"></th>\n        <th>Cliente</th>\n        <th>CPF</th>\n        <th>Pix</th>\n        <th>Produto</th>\n        <th style=\"text-align:center;\">Cotas</th>\n        <th style=\"text-align:right;\">Capital Investido</th>\n        <th style=\"text-align:right;color:#d4af37;\">Total Apurado</th>\n        <th style=\"text-align:center;\">Detalhes</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for cli in clients %}\n      {% set row_id = loop.index0 %}\n      <tr id=\"linha-{{ row_id }}\">\n        <td style=\"text-align:center;\">\n          <input type=\"checkbox\" class=\"confer-check\"\n                 id=\"confer-{{ row_id }}\"\n                 data-row=\"{{ row_id }}\"\n                 data-key=\"{{ cli.client_id }}-{{ cli.condominium_code }}\"\n                 title=\"Marcar {{ cli.client_name }} como conferido\">\n        </td>\n        <td style=\"text-align:center;color:#888;font-size:12px;\">{{ loop.index }}</td>\n        <td style=\"font-weight:600;color:#F5F5F5;\">{{ cli.client_name }}</td>\n        <td class=\"text-mono text-dim\">{{ cli.client_cpf }}</td>\n        <td class=\"text-dim\" style=\"font-size:12px;\">{{ cli.client_pix or '—' }}</td>\n        <td>\n          {% if cli.condominium_code == 'civil' %}<span class=\"badge badge-civil\">🏗️ Civil</span>\n          {% elif cli.condominium_code == 'agro' %}<span class=\"badge badge-agro\">🌾 Agro</span>\n          {% else %}<span class=\"badge badge-saude\">🏥 Saúde</span>{% endif %}\n        </td>\n        <td style=\"text-align:center;color:#888;\">{{ cli.shares_count }}</td>\n        <td style=\"text-align:right;color:#aaa;\">\n          {{ formatar_moeda(cli.total_share_value) }}\n          {% if cli.withdrawn_count %}<br><small style=\"color:#38bdf8;\">− {{ formatar_moeda(cli.total_withdrawn_value) }} retirado</small>{% endif %}\n        </td>\n        <td style=\"text-align:right;font-weight:700;color:#d4af37;font-size:16px;\">{{ formatar_moeda(cli.total_income) }}</td>\n        <td style=\"text-align:center;\">\n          <button type=\"button\" class=\"btn btn-secondary btn-sm\"\n                  onclick=\"toggleCotas({{ row_id }})\" id=\"btn-{{ row_id }}\">▶ Ver cotas</button>\n        </td>\n      </tr>\n      <tr id=\"detalhe-{{ row_id }}\" style=\"display:none;background:rgba(0,0,0,0.25);\">\n        <td colspan=\"10\" style=\"padding:0;\">\n          <div style=\"padding:12px 16px 16px;\">\n            <div style=\"font-size:11px;color:#888;text-transform:uppercase;letter-spacing:1px;margin-bottom:10px;\">\n              Cotas de {{ cli.client_name }} · {{ cli.condominium_name }}\n            </div>\n            <table style=\"width:100%;border-collapse:collapse;font-size:13px;\">\n              <thead>\n                <tr style=\"border-bottom:1px solid rgba(255,255,255,0.08);\">\n                  <th style=\"padding:6px 8px;text-align:left;color:#888;font-weight:500;\">Nº Cota</th>\n                  <th style=\"padding:6px 8px;text-align:right;color:#888;font-weight:500;\">Valor</th>\n                  <th style=\"padding:6px 8px;color:#888;font-weight:500;\">Aquisição</th>\n                  <th style=\"padding:6px 8px;color:#888;font-weight:500;\">Vencimento</th>\n                  <th style=\"padding:6px 8px;color:#888;font-weight:500;\">Ú. Renovação</th>\n                  <th style=\"padding:6px 8px;color:#888;font-weight:500;\">Período Apurado</th>\n                  <th style=\"padding:6px 8px;text-align:center;color:#888;font-weight:500;\">Dias</th>\n                  <th style=\"padding:6px 8px;text-align:right;color:#888;font-weight:500;\">Taxa</th>\n                  <th style=\"padding:6px 8px;text-align:right;color:#d4af37;font-weight:500;\">Rendimento</th>\n                  <th style=\"padding:6px 8px;color:#888;font-weight:500;\">Tipo</th>\n                </tr>\n              </thead>\n              <tbody>\n                {% for it in cli[\"shares_detail\"] %}\n                <tr style=\"border-bottom:1px solid rgba(255,255,255,0.04);\">\n                  <td style=\"padding:6px 8px;font-weight:700;color:#d4af37;\">{{ it.share_number or '—' }}</td>\n                  <td style=\"padding:6px 8px;text-align:right;color:#ccc;\">{{ formatar_moeda(it.share_value) }}</td>\n                  <td style=\"padding:6px 8px;color:#888;\">{{ it.acquisition_date or '—' }}</td>\n                  <td style=\"padding:6px 8px;color:#888;\">{{ it.maturity_date or '—' }}</td>\n                  <td style=\"padding:6px 8px;color:#888;\">{{ it.last_renewal_date or '—' }}</td>\n                  <td style=\"padding:6px 8px;color:#888;font-size:11px;\">{{ it.period_start }} → {{ it.period_end }}</td>\n                  <td style=\"padding:6px 8px;text-align:center;color:#888;\">{{ it.active_days }}/{{ it.total_period_days }}</td>\n                  <td style=\"padding:6px 8px;text-align:right;color:#888;\">{{ \"%.2f\"|format(it.applied_rate * 100) }}%</td>\n                  <td style=\"padding:6px 8px;text-align:right;font-weight:700;color:#d4af37;\">{{ formatar_moeda(it.income_value) }}</td>\n                  <td style=\"padding:6px 8px;font-size:11px;\">\n                    {% set ct = it.calculation_details or '' %}\n                    {% if 'RETIRADA em' in ct %}\n                      <span style=\"color:#38bdf8;\" title=\"{{ ct }}\">↩ Proporc. até retirada</span>\n                    {% elif it.active_days == it.total_period_days %}\n                      <span style=\"color:#4ade80;\">✓ Integral</span>\n                    {% elif 'Especial' in ct %}\n                      <span style=\"color:#f97316;\">★ Especial Agro</span>\n                    {% else %}\n                      <span style=\"color:#fbbf24;\">⊘ Proporcional</span>\n                    {% endif %}\n                  </td>\n                </tr>\n                {% endfor %}\n              </tbody>\n              <tfoot>\n                <tr style=\"border-top:1px solid rgba(212,175,55,0.3);\">\n                  <td colspan=\"8\" style=\"padding:8px;text-align:right;color:#888;font-weight:600;\">Total {{ cli.client_name }}</td>\n                  <td style=\"padding:8px;text-align:right;font-weight:700;color:#d4af37;\">{{ formatar_moeda(cli.total_income) }}</td>\n                  <td></td>\n                </tr>\n              </tfoot>\n            </table>\n          </div>\n        </td>\n      </tr>\n      {% endfor %}\n    </tbody>\n    <tfoot>\n      <tr style=\"border-top:2px solid rgba(212,175,55,0.3);\">\n        <td colspan=\"7\" style=\"font-weight:600;color:#d4af37;padding:10px 12px;\">TOTAL GERAL</td>\n        <td style=\"text-align:right;font-weight:600;color:#aaa;padding:10px 12px;\">\n          {{ formatar_moeda(clients | sum(attribute='total_share_value')) }}\n        </td>\n        <td style=\"text-align:right;font-weight:700;color:#d4af37;font-size:18px;padding:10px 12px;\">\n          {{ formatar_moeda(total_geral) }}\n        </td>\n        <td></td>\n      </tr>\n    </tfoot>\n  </table>\n</div>\n<div style=\"font-size:11px;color:#555;margin-bottom:28px;text-align:right;\">\n  {{ clients|length }} cliente(s) · {{ total_shares }} cota(s)\n</div>\n\n<!-- ═══ Arquivo bancário (remessa de pagamento) ═══ -->\n<div class=\"section-label\" style=\"color:#d4af37;\">🏦 Arquivo bancário</div>\n<div class=\"card\" style=\"margin-bottom:24px;\">\n  <div class=\"detail-grid\" style=\"margin-bottom:18px;\">\n    <div>\n      <div class=\"detail-item-label\">Banco definido</div>\n      <div class=\"detail-item-value\">{{ bank_info.bank_name or '—' }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Método</div>\n      <div class=\"detail-item-value\">\n        {% if bank_info.method == 'pix' %}\n          <span class=\"badge badge-active\">Pix — CNAB240</span>\n        {% elif bank_info.method == 'dados_bancarios' %}\n          <span class=\"badge badge-active\">Dados Bancários — CNAB240</span>\n        {% else %}\n          <span class=\"badge badge-inactive\">Layout pendente</span>\n        {% endif %}\n      </div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Total da apuração</div>\n      <div class=\"detail-item-value\" style=\"color:#d4af37;font-weight:700;\">{{ formatar_moeda(total_geral) }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Quantidade de clientes</div>\n      <div class=\"detail-item-value\">{{ clients|length }}</div>\n    </div>\n  </div>\n\n  {% if bank_info.method in ('pix', 'dados_bancarios') %}\n    <div class=\"form-group\" style=\"margin-bottom:14px;max-width:260px;\">\n      <label style=\"color:#ccc;font-size:13px;font-weight:500;\">Data de pagamento</label>\n      <input type=\"date\" id=\"banco-payment-date\" class=\"form-control\"\n             value=\"{{ data_sugerida or '' }}\">\n    </div>\n\n    <div class=\"page-actions\" style=\"margin-bottom:14px;\">\n      <button type=\"button\" class=\"btn btn-secondary\" onclick=\"validarPagamentosBanco({{ calc_id }})\">\n        🔎 Validar pagamentos\n      </button>\n      <button type=\"button\" class=\"btn btn-primary\" onclick=\"confirmarGerarArquivoBanco({{ calc_id }})\">\n        🏦 Gerar arquivo banco\n      </button>\n    </div>\n\n    <div id=\"banco-validacao-resultado\" style=\"display:none;margin-bottom:14px;\"></div>\n\n    <form id=\"form-gerar-banco\" method=\"post\"\n          action=\"{{ url_for('historico_banco_gerar', calc_id=calc_id) }}\" style=\"display:none;\">\n      <input type=\"hidden\" name=\"payment_date\" id=\"banco-payment-date-hidden\">\n    </form>\n  {% else %}\n    <div class=\"note-box\" style=\"margin-bottom:14px;color:#f87171;border-color:rgba(239,68,68,0.25);\">\n      ⚠️ Banco pagador não configurado para este condomínio.\n    </div>\n    <button type=\"button\" class=\"btn btn-secondary\" disabled>Gerar arquivo banco</button>\n  {% endif %}\n\n  {% if remittance_files %}\n  <div style=\"margin-top:20px;\">\n    <div class=\"section-label\" style=\"font-size:12px;margin-bottom:8px;\">Arquivos já gerados</div>\n    <div class=\"table-wrap\">\n      <table>\n        <thead>\n          <tr>\n            <th>Arquivo</th><th>Gerado em</th><th style=\"text-align:right;\">Total</th>\n            <th style=\"text-align:center;\">Pagamentos</th><th>Status</th><th style=\"text-align:right;\">Ações</th>\n          </tr>\n        </thead>\n        <tbody>\n          {% for rf in remittance_files %}\n          <tr>\n            <td class=\"text-mono\">{{ rf.file_name }}</td>\n            <td class=\"text-dim\">{{ rf.created_at }}</td>\n            <td style=\"text-align:right;\">{{ formatar_moeda(rf.total_amount) }}</td>\n            <td style=\"text-align:center;\">{{ rf.total_payments }}</td>\n            <td>\n              {% if rf.status == 'generated' %}<span class=\"badge badge-active\">Gerado</span>\n              {% elif rf.status == 'imported_to_bank' %}<span class=\"badge badge-active\">Importado no banco</span>\n              {% elif rf.status == 'cancelled' %}<span class=\"badge badge-inactive\">Cancelado</span>\n              {% else %}<span class=\"badge badge-inactive\">Erro</span>{% endif %}\n            </td>\n            <td style=\"text-align:right;white-space:nowrap;\">\n              <a class=\"btn btn-secondary btn-sm\" href=\"{{ url_for('historico_banco_baixar', calc_id=calc_id, remittance_id=rf.id, tipo='rem') }}\">.REM</a>\n              <a class=\"btn btn-secondary btn-sm\" href=\"{{ url_for('historico_banco_baixar', calc_id=calc_id, remittance_id=rf.id, tipo='csv') }}\">Conferência</a>\n            </td>\n          </tr>\n          {% endfor %}\n        </tbody>\n      </table>\n    </div>\n  </div>\n  {% endif %}\n</div>\n\n{% endblock %}\n\n{% block scripts %}\n<script>\nfunction toggleCotas(idx) {\n  var row = document.getElementById('detalhe-' + idx);\n  var btn = document.getElementById('btn-' + idx);\n  if (!row) return;\n  var open = row.style.display === 'none' || row.style.display === '';\n  row.style.display = open ? 'table-row' : 'none';\n  btn.textContent = open ? '▼ Ocultar' : '▶ Ver cotas';\n}\n\n/* ── Conferência por pessoa (caixinhas do Consolidado por Cliente) ──\n   As marcações ficam guardadas no próprio navegador, separadas por\n   apuração, para você poder recarregar a página sem perder o que\n   já conferiu no banco. Nada é gravado no banco de dados do app. */\nvar CONFER_KEY = 'confer_apuracao_{{ calc_id }}';\n\nfunction conferLer() {\n  try {\n    var raw = window.localStorage.getItem(CONFER_KEY);\n    return raw ? JSON.parse(raw) : {};\n  } catch (e) { return {}; }\n}\n\nfunction conferGravar(mapa) {\n  try { window.localStorage.setItem(CONFER_KEY, JSON.stringify(mapa)); } catch (e) {}\n}\n\nfunction conferAplicarLinha(chk) {\n  var linha = document.getElementById('linha-' + chk.dataset.row);\n  if (!linha) return;\n  if (chk.checked) { linha.classList.add('row-conferida'); }\n  else { linha.classList.remove('row-conferida'); }\n}\n\nfunction conferInit() {\n  var checks = Array.prototype.slice.call(document.querySelectorAll('.confer-check'));\n  if (!checks.length) return;\n  var marcados = conferLer();\n\n  checks.forEach(function (chk) {\n    chk.checked = marcados[chk.dataset.key] === true;\n    conferAplicarLinha(chk);\n\n    chk.addEventListener('change', function () {\n      var mapa = conferLer();\n      if (chk.checked) { mapa[chk.dataset.key] = true; }\n      else { delete mapa[chk.dataset.key]; }\n      conferGravar(mapa);\n      conferAplicarLinha(chk);\n    });\n  });\n}\n\nif (document.readyState === 'loading') {\n  document.addEventListener('DOMContentLoaded', conferInit);\n} else {\n  conferInit();\n}\n\nvar HOUVE_ARQUIVO_BANCO_GERADO = {{ 'true' if remittance_files else 'false' }};\nvar ULTIMA_VALIDACAO_BANCO = null;\n\nfunction validarPagamentosBanco(calcId) {\n  var resultEl = document.getElementById('banco-validacao-resultado');\n  if (!resultEl) return;\n  resultEl.style.display = 'block';\n  resultEl.className = 'note-box';\n  resultEl.innerHTML = 'Validando...';\n\n  fetch('/erp/historico/' + calcId + '/banco/validar', { method: 'POST' })\n    .then(function (r) { return r.json(); })\n    .then(function (data) {\n      if (!data.success) {\n        resultEl.innerHTML = '✗ ' + (data.message || 'Não foi possível validar.');\n        return;\n      }\n      ULTIMA_VALIDACAO_BANCO = data;\n      var html = ''\n        + '<div style=\"margin-bottom:10px;\">'\n        + '<strong>Total de clientes da apuração:</strong> ' + data.total_client_count + '<br>'\n        + '<strong style=\"color:#4ade80;\">Incluídos no arquivo:</strong> ' + data.valid_count\n        + ' · Total incluído: <strong>' + data.total_amount + '</strong><br>'\n        + '<strong style=\"color:#f0ad4e;\">Fora do arquivo por pendência:</strong> ' + data.pending_count\n        + ' · Total pendente: <strong>' + data.pending_total_amount + '</strong>'\n        + '</div>';\n      function listar(titulo, arr) {\n        if (arr && arr.length) {\n          html += '<br><strong>' + titulo + ' (' + arr.length + '):</strong> ' + arr.join(', ');\n        }\n      }\n      listar('Sem nome cadastrado', data.pending_no_name);\n      listar('Sem CPF/CNPJ', data.pending_no_document);\n      listar('CPF/CNPJ inválido', data.pending_invalid_document);\n      listar('Sem chave Pix', data.pending_no_pix);\n      listar('Chave Pix e-mail inválida', data.pending_invalid_pix_email);\n      listar('Dados bancários incompletos', data.pending_no_bank_data);\n      listar('Valor inválido (zerado/negativo)', data.pending_zero_amount);\n      if (data.config_missing && data.config_missing.length) {\n        html += '<br><strong style=\"color:#f87171;\">Configuração do banco incompleta:</strong> ' +\n                data.config_missing.join(', ') + ' — preencha em Configurações.';\n      }\n      if (!data.can_generate) {\n        html += '<br><br><strong style=\"color:#f87171;\">Geração bloqueada: ' +\n                (data.valid_count === 0 ? 'nenhum pagamento válido nesta apuração.' : 'configuração do banco incompleta.') +\n                '</strong>';\n      } else if (data.pending_count > 0) {\n        html += '<br><br><span style=\"color:#999;\">As pendências acima NÃO bloqueiam a geração — ' +\n                'esses clientes só ficarão fora do .REM e aparecerão na conferência CSV.</span>';\n      }\n      resultEl.innerHTML = html;\n    })\n    .catch(function () {\n      resultEl.innerHTML = '✗ Não foi possível conectar ao servidor para validar.';\n    });\n}\n\nfunction confirmarGerarArquivoBanco(calcId) {\n  var dateEl = document.getElementById('banco-payment-date');\n  var paymentDate = dateEl ? dateEl.value : '';\n  if (!paymentDate) {\n    alert('Informe a data de pagamento antes de gerar o arquivo.');\n    return;\n  }\n\n  if (!ULTIMA_VALIDACAO_BANCO) {\n    alert('Clique em \"Validar pagamentos\" antes de gerar o arquivo.');\n    return;\n  }\n  if (!ULTIMA_VALIDACAO_BANCO.can_generate) {\n    var motivoBloqueio = ULTIMA_VALIDACAO_BANCO.valid_count === 0\n      ? 'Nenhum pagamento válido nesta apuração.'\n      : 'Cadastro do banco pagador incompleto em Configurações.';\n    alert('Geração bloqueada: ' + motivoBloqueio);\n    return;\n  }\n\n  var msg = 'Serão incluídos ' + ULTIMA_VALIDACAO_BANCO.valid_count + ' pagamentos no arquivo, totalizando ' +\n            ULTIMA_VALIDACAO_BANCO.total_amount + '. ' +\n            ULTIMA_VALIDACAO_BANCO.pending_count + ' clientes ficarão fora por pendências cadastrais ' +\n            'e aparecerão na conferência. Deseja continuar?';\n  if (!window.confirm(msg)) return;\n\n  if (HOUVE_ARQUIVO_BANCO_GERADO) {\n    if (!window.confirm('Já existe arquivo gerado. Deseja gerar nova versão (novo sequencial de remessa)?')) return;\n  }\n\n  document.getElementById('banco-payment-date-hidden').value = paymentDate;\n  document.getElementById('form-gerar-banco').submit();\n}\n</script>\n{% endblock %}\n",
  "historico_editar.html": "{% extends \"base.html\" %}\n{% block title %}Editar Apuração #{{ calculation_id }} — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n\n<div style=\"display:flex;align-items:center;gap:12px;margin-bottom:8px;\">\n  <a href=\"{{ url_for('historico_detalhe', calc_id=calculation_id) }}\" class=\"back-link\">← Ver Detalhes</a>\n  <div style=\"flex:1;\"></div>\n  <a href=\"{{ url_for('historico') }}\" class=\"btn btn-secondary btn-sm\">← Histórico</a>\n</div>\n\n<div class=\"page-header\">\n  <div class=\"page-header-icon\">✏️</div>\n  <div class=\"page-header-title\">\n    Editar Apuração #{{ calculation_id }}\n    {% if detail %}\n    {% set h = detail[\"header\"] %}\n    · {{ '%02d'|format(h.calculation_month) }}/{{ h.calculation_year }}\n    {% if h.condominium_name %}— {{ h.condominium_name }}{% else %}— Todos os Produtos{% endif %}\n    {% endif %}\n  </div>\n  <div class=\"page-header-sub\">\n    Editando registro salvo — as cotas e clientes originais não serão alterados.\n  </div>\n</div>\n\n{% if erro %}\n<div class=\"alert alert-error\" style=\"margin-bottom:20px;\">⚠️ {{ erro }}</div>\n{% endif %}\n\n{% if detail %}\n{% set h = detail[\"header\"] %}\n{% set calc_items = detail[\"items\"] %}\n\n<form method=\"POST\">\n\n  <!-- Observações do cabeçalho -->\n  <div class=\"card-gold\" style=\"margin-bottom:24px;\">\n    <div class=\"form-section\">\n      <div class=\"form-section-title\">Observações da Apuração</div>\n      <div style=\"font-size:12px;color:#888;margin-bottom:12px;\">\n        Salvo em {{ h.calculated_at }}\n        {% if h.agro_special_rate %} · Taxa especial Agro: {{ \"%.2f\"|format(h.agro_special_rate * 100) }}%{% endif %}\n      </div>\n      <div class=\"form-group\">\n        <label>Notas / Observações</label>\n        <input type=\"text\" name=\"notes\" class=\"form-control\"\n               value=\"{{ h.notes or '' }}\"\n               placeholder=\"Observação opcional sobre esta apuração\">\n      </div>\n    </div>\n  </div>\n\n  <!-- Itens por cota -->\n  <div class=\"section-label\" style=\"margin-bottom:12px;\">● Itens da Apuração — edite os valores e clique em Salvar</div>\n  <div class=\"note-box\" style=\"margin-bottom:16px;font-size:12px;\">\n    ℹ️ <strong>Taxa aplicada:</strong> use decimal — ex: <code>0.017</code> para 1,7% · <code>0.04</code> para 4%.\n    Alterar o rendimento de uma cota atualiza o total ao salvar.\n  </div>\n\n  {% if calc_items %}\n  <div class=\"table-wrap\" style=\"margin-bottom:24px;overflow-x:auto;\">\n    <table style=\"min-width:1100px;\">\n      <thead>\n        <tr>\n          <th>Cliente</th>\n          <th>Produto</th>\n          <th>Nº Cota</th>\n          <th style=\"text-align:right;\">Valor Cota (R$)</th>\n          <th style=\"text-align:center;\">Dias Ativos</th>\n          <th style=\"text-align:center;\">Total Dias</th>\n          <th style=\"text-align:right;\">Taxa (decimal)</th>\n          <th style=\"text-align:right;color:#d4af37;\">Rendimento (R$)</th>\n          <th>Obs. Cota</th>\n        </tr>\n      </thead>\n      <tbody>\n        {% for it in calc_items %}\n        <tr>\n          <td style=\"font-weight:600;color:#F5F5F5;white-space:nowrap;\">{{ it.client_name }}</td>\n          <td>\n            {% if it.condominium_code == 'civil' %}<span class=\"badge badge-civil\">🏗️ Civil</span>\n            {% elif it.condominium_code == 'agro' %}<span class=\"badge badge-agro\">🌾 Agro</span>\n            {% else %}<span class=\"badge badge-saude\">🏥 Saúde</span>{% endif %}\n          </td>\n          <td style=\"font-weight:700;color:#d4af37;\">{{ it.share_number }}</td>\n          <td>\n            <input type=\"number\" name=\"sv_{{ it.id }}\" step=\"0.01\" min=\"0\"\n                   value=\"{{ '%.2f'|format(it.share_value) }}\"\n                   class=\"form-control\" style=\"min-width:110px;text-align:right;\">\n          </td>\n          <td>\n            <input type=\"number\" name=\"ad_{{ it.id }}\" min=\"0\"\n                   value=\"{{ it.active_days }}\"\n                   class=\"form-control\" style=\"min-width:70px;text-align:center;\">\n          </td>\n          <td>\n            <input type=\"number\" name=\"tpd_{{ it.id }}\" min=\"1\"\n                   value=\"{{ it.total_period_days }}\"\n                   class=\"form-control\" style=\"min-width:70px;text-align:center;\">\n          </td>\n          <td>\n            <input type=\"number\" name=\"ar_{{ it.id }}\" step=\"0.00001\" min=\"0\"\n                   value=\"{{ '%.5f'|format(it.applied_rate) }}\"\n                   class=\"form-control\" style=\"min-width:100px;text-align:right;\">\n          </td>\n          <td>\n            <input type=\"number\" name=\"iv_{{ it.id }}\" step=\"0.01\" min=\"0\"\n                   value=\"{{ '%.2f'|format(it.income_value) }}\"\n                   class=\"form-control\" style=\"min-width:110px;text-align:right;\">\n          </td>\n          <td>\n            <input type=\"text\" name=\"cd_{{ it.id }}\"\n                   value=\"{{ it.calculation_details or '' }}\"\n                   class=\"form-control\" style=\"min-width:140px;\"\n                   placeholder=\"Obs.\">\n          </td>\n        </tr>\n        {% endfor %}\n      </tbody>\n    </table>\n  </div>\n  {% else %}\n  <div class=\"empty-state\">\n    <div class=\"empty-state-title\">Nenhum item encontrado</div>\n  </div>\n  {% endif %}\n\n  <div class=\"page-actions\">\n    <a href=\"{{ url_for('historico_detalhe', calc_id=calculation_id) }}\" class=\"btn btn-secondary\">Cancelar</a>\n    <button type=\"submit\" class=\"btn btn-primary\">💾 Salvar Alterações</button>\n  </div>\n\n</form>\n{% endif %}\n\n{% endblock %}\n",
  "operacao/_barra_empresa.html": "{# Barra da empresa: cronômetro de jornada + atalhos de Demandas e Chamados.\n   Incluída na barra superior das páginas da empresa (portal e módulo Operação). #}\n{% if empresa and portal_user %}\n<link rel=\"stylesheet\" href=\"{{ url_for('operacao.static', filename='operacao.css') }}\">\n<div class=\"op-crono\" id=\"op-crono\" data-url=\"{{ url_for('operacao.cronometro', slug=empresa.slug) }}\"\n     data-csrf=\"{{ csrf_token() }}\" title=\"Tempo nesta empresa hoje\">\n  <span class=\"op-crono-ic\">{{ oic('timer') }}</span>\n  <span class=\"op-crono-txt\"><b id=\"op-crono-tempo\">00:00:00</b><small id=\"op-crono-rot\">hoje nesta empresa</small></span>\n  <button type=\"button\" class=\"op-crono-btn\" id=\"op-crono-btn\" aria-label=\"Iniciar\" disabled>\n    <span class=\"quando-parado\">{{ oic('play') }}<span>Iniciar</span></span>\n    <span class=\"quando-rodando\">{{ oic('pause') }}<span>Pausar</span></span>\n  </button>\n</div>\n<a class=\"tb-btn op-tb {{ 'op-on' if op_ativo == 'demandas' }}\" href=\"{{ url_for('operacao.demandas', slug=empresa.slug) }}\">{{ oic('tarefas') }}<span class=\"lbl\">Demandas</span></a>\n<a class=\"tb-btn op-tb {{ 'op-on' if op_ativo == 'chamados' }}\" href=\"{{ url_for('operacao.chamados', slug=empresa.slug) }}\">{{ oic('chamados') }}<span class=\"lbl\">Chamados</span></a>\n<script>\n(function () {\n  var box = document.getElementById('op-crono');\n  if (!box || box.dataset.ok) return; box.dataset.ok = '1';\n  // Botões só com ícone continuam com o nome ao passar o mouse.\n  document.querySelectorAll('.topbar .tb-btn').forEach(function (a) {\n    var l = a.querySelector('.lbl'); if (l && !a.title) a.title = l.textContent.trim();\n  });\n  var tempo = document.getElementById('op-crono-tempo'), rot = document.getElementById('op-crono-rot'),\n      btn = document.getElementById('op-crono-btn');\n  var est = null, base = 0, t0 = 0;\n  function fmt(s) { s = Math.max(0, Math.floor(s)); var h = Math.floor(s / 3600), m = Math.floor(s % 3600 / 60), x = s % 60;\n    return String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0') + ':' + String(x).padStart(2, '0'); }\n  function pintar() {\n    var s = base + (est && est.rodando ? (Date.now() - t0) / 1000 : 0);\n    tempo.textContent = fmt(s);\n    var tarefa = document.querySelector('[data-op-tarefa-tempo]');\n    if (tarefa && est && est.tarefa && String(est.tarefa.id) === tarefa.dataset.opTarefaTempo) {\n      tarefa.textContent = fmt(est.tarefa_segundos + (Date.now() - t0) / 1000);\n    }\n  }\n  function aplicar(d) {\n    est = d; base = d.segundos_hoje; t0 = Date.now(); btn.disabled = false;\n    box.classList.toggle('rodando', !!d.rodando);\n    btn.setAttribute('aria-label', d.rodando ? 'Pausar' : 'Iniciar');\n    rot.textContent = d.rodando ? (d.tarefa ? 'em: ' + d.tarefa.titulo : 'em andamento') :\n      (d.outra_empresa ? 'rodando em ' + d.outra_empresa : 'pausado · hoje');\n    rot.title = rot.textContent;\n    pintar();\n  }\n  function chamar(acao) {\n    var op = { credentials: 'same-origin' };\n    if (acao) { var f = new FormData(); f.append('_csrf', box.dataset.csrf); f.append('acao', acao); op.method = 'POST'; op.body = f; }\n    return fetch(box.dataset.url, op).then(function (r) { if (!r.ok) throw r; return r.json(); }).then(aplicar)\n      .catch(function () { rot.textContent = 'sem conexão com o sistema'; btn.disabled = !est; });\n  }\n  btn.addEventListener('click', function () {\n    if (!est) return;\n    btn.disabled = true;\n    var ia = est && est.rodando ? 'pausar' : 'iniciar';\n    chamar(ia).then(function () { if (document.body.dataset.opRecarregar) location.reload(); });\n  });\n  chamar();\n  setInterval(pintar, 1000);\n  setInterval(function () { chamar(); }, 60000);   // sinal de uso + sincroniza\n})();\n</script>\n{% endif %}\n",
  "operacao/_form_demanda.html": "{# Campos da demanda (nova ou edição). Espera: d (dict ou none), usuarios, portal_user #}\n{% set d = d or {} %}\n<label class=\"lbl\" for=\"f-titulo\">Título</label>\n<input class=\"inp\" id=\"f-titulo\" name=\"titulo\" maxlength=\"200\" required value=\"{{ d.titulo or '' }}\" placeholder=\"O que precisa ser feito\">\n<label class=\"lbl\" for=\"f-desc\">Descrição <small>(opcional)</small></label>\n<textarea class=\"inp\" id=\"f-desc\" name=\"descricao\" rows=\"3\" placeholder=\"Detalhes, passo a passo, onde encontrar\">{{ d.descricao or '' }}</textarea>\n<div class=\"op-2col\">\n  <div>\n    <label class=\"lbl\">Tipo</label>\n    <div class=\"seg op-seg\">\n      <input type=\"radio\" id=\"f-tipo-p-{{ d.id or 'n' }}\" name=\"tipo\" value=\"pontual\" {{ 'checked' if d.tipo != 'recorrente' }} data-op-tipo>\n      <label for=\"f-tipo-p-{{ d.id or 'n' }}\">Pontual</label>\n      <input type=\"radio\" id=\"f-tipo-r-{{ d.id or 'n' }}\" name=\"tipo\" value=\"recorrente\" {{ 'checked' if d.tipo == 'recorrente' }} data-op-tipo>\n      <label for=\"f-tipo-r-{{ d.id or 'n' }}\">Recorrente</label>\n    </div>\n  </div>\n  <div data-op-rec {{ 'hidden' if d.tipo != 'recorrente' }}>\n    <label class=\"lbl\" for=\"f-rec\">Repete</label>\n    <select class=\"inp\" id=\"f-rec\" name=\"recorrencia\">\n      {% for k, v in RECORRENCIAS.items() %}<option value=\"{{ k }}\" {{ 'selected' if (d.recorrencia or 'mensal') == k }}>{{ v }}</option>{% endfor %}\n    </select>\n  </div>\n</div>\n<div class=\"op-2col\">\n  <div>\n    <label class=\"lbl\" for=\"f-venc\">Vencimento</label>\n    <input class=\"inp\" id=\"f-venc\" type=\"date\" name=\"vencimento\" value=\"{{ d.vencimento or (hoje_iso if hoje_iso is defined else '') }}\">\n  </div>\n  <div>\n    <label class=\"lbl\" for=\"f-prio\">Prioridade</label>\n    <select class=\"inp\" id=\"f-prio\" name=\"prioridade\">\n      {% for k, v in PRIORIDADES.items() %}<option value=\"{{ k }}\" {{ 'selected' if (d.prioridade or 'normal') == k }}>{{ v }}</option>{% endfor %}\n    </select>\n  </div>\n</div>\n{% if portal_user.admin %}\n<label class=\"lbl\" for=\"f-resp\">Responsável</label>\n<select class=\"inp\" id=\"f-resp\" name=\"responsavel_id\">\n  {% for x in usuarios %}<option value=\"{{ x.id }}\" {{ 'selected' if (d.responsavel_id or portal_user.id) == x.id }}>{{ x.nome }}</option>{% endfor %}\n</select>\n{% endif %}\n",
  "operacao/_js_form.html": "<script>\ndocument.querySelectorAll('form').forEach(function (f) {\n  var rec = f.querySelector('[data-op-rec]');\n  if (!rec) return;\n  f.querySelectorAll('[data-op-tipo]').forEach(function (r) {\n    r.addEventListener('change', function () { rec.hidden = f.querySelector('[data-op-tipo]:checked').value !== 'recorrente'; });\n  });\n});\n</script>\n",
  "operacao/_layout.html": "{% extends \"portal/base.html\" %}\n{% block brand %}\n  <span class=\"logo-circle xs\"><img src=\"{{ url_for('static', filename='portal/logos/' ~ empresa.logo) }}\" alt=\"\"></span>\n  <span class=\"tb-name\"><b>{{ empresa.nome }}</b><small>Grupo Capuzzo</small></span>\n{% endblock %}\n{% block tb_links %}\n  <a class=\"tb-btn\" href=\"{{ url_for('portal_empresa', slug=empresa.slug) }}\">{{ ic('grid_view') }}<span class=\"lbl\">Módulos</span></a>\n  {% include \"operacao/_barra_empresa.html\" %}\n{% endblock %}\n{% block content %}\n<div class=\"mod-layout op-layout\">\n  <aside class=\"side\">\n    <div class=\"side-title\">Meu dia</div>\n    <a class=\"side-link {{ 'on' if op_ativo == 'demandas' }}\" href=\"{{ url_for('operacao.demandas', slug=empresa.slug) }}\">\n      {{ oic('tarefas') }}Demandas\n      {% if cont.atrasadas %}<span class=\"op-badge op-badge-risco\" title=\"Atrasadas\">{{ cont.atrasadas }}</span>\n      {% elif cont.abertas %}<span class=\"op-badge\">{{ cont.abertas }}</span>{% endif %}</a>\n    <a class=\"side-link {{ 'on' if op_ativo == 'chamados' }}\" href=\"{{ url_for('operacao.chamados', slug=empresa.slug) }}\">\n      {{ oic('chamados') }}Chamados\n      {% if cont.chamados %}<span class=\"op-badge\">{{ cont.chamados }}</span>{% endif %}</a>\n    <div class=\"side-sep\"></div>\n    <div class=\"side-title\">Módulos</div>\n    {% for m in modulos %}\n      <a class=\"side-link\" href=\"{{ url_for('portal_modulo', slug=empresa.slug, modulo_id=m.id) }}\">{{ ic(m.icone) }}{{ m.nome }}</a>\n    {% else %}\n      <span class=\"side-vazio\">Nenhum módulo publicado ainda.</span>\n    {% endfor %}\n    <div class=\"side-sep\"></div>\n    <a class=\"side-link\" href=\"{{ url_for('portal_empresa', slug=empresa.slug) }}\">{{ ic('arrow_back') }}Voltar à empresa</a>\n  </aside>\n  <section class=\"mod-main op-main\">\n    {% block op_content %}{% endblock %}\n  </section>\n</div>\n{% endblock %}\n",
  "operacao/chamado.html": "{% extends \"operacao/_layout.html\" %}\n{% block title %}Chamado nº {{ numero_chamado(c.id) }} · {{ empresa.nome }}{% endblock %}\n{% block op_content %}\n<a class=\"op-voltar\" href=\"{{ url_for('operacao.chamados', slug=empresa.slug) }}\">{{ ic('arrow_back') }} Chamados</a>\n\n<section class=\"op-detalhe\">\n  <header class=\"op-detalhe-head\">\n    <div>\n      <div class=\"op-meta\">\n        <span class=\"op-num-grande\">Nº {{ numero_chamado(c.id) }}</span>\n        <span class=\"op-status st-{{ c.status }}\">{{ STATUS_CHAMADO[c.status] }}</span>\n        <span class=\"op-tag\">{{ c.setor }}</span>\n      </div>\n      <h1>{{ c.assunto }}</h1>\n      <p class=\"op-info\">Solicitante: <b>{{ c.solicitante or '—' }}</b> · Aberto em {{ data_hora_br(c.aberto_em) }} por {{ aberto_por }}\n        · Última movimentação: {{ data_hora_br(c.ultima_mov_em) }}{% if resp_nome %} · Responsável: <b>{{ resp_nome }}</b>{% endif %}</p>\n    </div>\n  </header>\n  {% if c.descricao %}<div class=\"op-desc\">{{ c.descricao }}</div>{% endif %}\n</section>\n\n<div class=\"op-cols\">\n  <section class=\"op-card\">\n    <h3>Movimentações</h3>\n    <ol class=\"op-timeline cronologica\">\n      {% for m in movs %}\n        <li class=\"{{ 'evento' if m.status and not m.texto.strip() }}\">\n          <span class=\"op-quando\">{{ data_hora_br(m.criado_em) }} · {{ m.autor }}{% if m.status %} · <span class=\"op-status st-{{ m.status }}\">{{ STATUS_CHAMADO[m.status] }}</span>{% endif %}</span>\n          <span class=\"op-texto\">{{ m.texto }}</span>\n        </li>\n      {% endfor %}\n    </ol>\n    <form class=\"op-nota-form\" method=\"post\" action=\"{{ url_for('operacao.chamado_mov', slug=empresa.slug, cid=c.id) }}\">\n      <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n      <label class=\"lbl\" for=\"m-texto\">Nova movimentação</label>\n      <textarea class=\"inp\" id=\"m-texto\" name=\"texto\" rows=\"3\" placeholder=\"Resposta, andamento, pedido de informação…\"></textarea>\n      <div class=\"op-2col\">\n        <div>\n          <label class=\"lbl\" for=\"m-status\">Status</label>\n          <select class=\"inp\" id=\"m-status\" name=\"status\">\n            {% for k, v in STATUS_CHAMADO.items() %}<option value=\"{{ k }}\" {{ 'selected' if c.status == k }}>{{ v }}</option>{% endfor %}\n          </select>\n        </div>\n        <div>\n          <label class=\"lbl\" for=\"m-resp\">Responsável</label>\n          <select class=\"inp\" id=\"m-resp\" name=\"responsavel_id\">\n            <option value=\"\">Ninguém ainda</option>\n            {% for x in usuarios %}<option value=\"{{ x.id }}\" {{ 'selected' if c.responsavel_id == x.id }}>{{ x.nome }}</option>{% endfor %}\n          </select>\n        </div>\n      </div>\n      <button class=\"btn-pill op-btn\" type=\"submit\">Registrar movimentação</button>\n    </form>\n  </section>\n  <aside class=\"op-resumo\">\n    <section class=\"op-card\">\n      <h3>Demandas deste chamado</h3>\n      <p class=\"op-sub\">Transforme o chamado em tarefa para medir o tempo de atendimento.</p>\n      <ul class=\"op-sessoes\">\n        {% for t in tarefas %}\n          <li>{% if t.posso_abrir %}<a href=\"{{ url_for('operacao.demanda', slug=empresa.slug, tid=t.id) }}\">{{ t.titulo }}</a>{% else %}<span>{{ t.titulo }}</span>{% endif %}\n            <b class=\"{{ 'ok' if t.status == 'concluida' }}\">{{ t.resp_nome }} · {{ STATUS_TAREFA[t.status] }}</b></li>\n        {% else %}\n          <li><span>Nenhuma demanda criada.</span></li>\n        {% endfor %}\n      </ul>\n      <button class=\"btn-pill outline op-btn\" type=\"button\" onclick=\"document.getElementById('dlg-tarefa').showModal()\">{{ oic('tarefas') }} Criar demanda</button>\n    </section>\n  </aside>\n</div>\n\n<dialog id=\"dlg-tarefa\" class=\"dlg op-dlg\">\n  <form method=\"post\" action=\"{{ url_for('operacao.demanda_nova', slug=empresa.slug) }}\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n    <input type=\"hidden\" name=\"chamado_id\" value=\"{{ c.id }}\">\n    <input type=\"hidden\" name=\"voltar\" value=\"{{ url_for('operacao.chamado', slug=empresa.slug, cid=c.id) }}\">\n    <div class=\"dlg-head\"><h3>Demanda do chamado nº {{ numero_chamado(c.id) }}</h3>\n      <button type=\"button\" class=\"ico\" onclick=\"this.closest('dialog').close()\">{{ ic('close') }}</button></div>\n    {% with d={'titulo': 'Chamado ' ~ numero_chamado(c.id) ~ ' — ' ~ c.assunto, 'descricao': c.descricao, 'prioridade': 'normal'} %}{% include \"operacao/_form_demanda.html\" %}{% endwith %}\n    <button class=\"btn-pill\" type=\"submit\">Criar demanda</button>\n  </form>\n</dialog>\n{% include \"operacao/_js_form.html\" %}\n{% endblock %}\n",
  "operacao/chamados.html": "{% extends \"operacao/_layout.html\" %}\n{% block title %}Chamados · {{ empresa.nome }}{% endblock %}\n{% block op_content %}\n<div class=\"op-head\">\n  <div>\n    <div class=\"eyebrow-line\">Central de chamados</div>\n    <h1>Chamados</h1>\n    <p>Solicitações feitas à {{ empresa.nome }}, por número, setor e situação.</p>\n  </div>\n  <button class=\"btn-pill\" type=\"button\" onclick=\"document.getElementById('dlg-chamado').showModal()\">{{ oic('add') }} Novo chamado</button>\n</div>\n\n<div class=\"op-kpis\">\n  <div class=\"op-kpi {{ 'risco' if totais.get('aberto') }}\"><b>{{ totais.get('aberto', 0) }}</b><span>Em aberto</span></div>\n  <div class=\"op-kpi\"><b>{{ totais.get('atendimento', 0) }}</b><span>Em atendimento</span></div>\n  <div class=\"op-kpi\"><b>{{ totais.get('concluido', 0) }}</b><span>Concluídos</span></div>\n  <div class=\"op-kpi dark\"><b>{{ totais.values()|sum }}</b><span>Total</span></div>\n</div>\n\n<form class=\"op-toolbar\" method=\"get\">\n  <input type=\"hidden\" name=\"status\" value=\"{{ st }}\">\n  <div class=\"chips\">\n    {% for k, rot in [('abertos','Pendentes'),('aberto','Em aberto'),('atendimento','Em atendimento'),('concluido','Concluídos'),('todos','Todos')] %}\n      <a class=\"chip {{ 'on' if st == k }}\" href=\"{{ url_for('operacao.chamados', slug=empresa.slug, status=k, setor=setor or None, q=busca or None) }}\">{{ rot }}</a>\n    {% endfor %}\n  </div>\n  <div class=\"op-filtros\">\n    <select class=\"inp\" name=\"setor\" onchange=\"this.form.submit()\" aria-label=\"Setor\">\n      <option value=\"\">Todos os setores</option>\n      {% for s in SETORES %}<option {{ 'selected' if setor == s }}>{{ s }}</option>{% endfor %}\n    </select>\n    <label class=\"search\">{{ ic('search') }}<input type=\"search\" name=\"q\" value=\"{{ busca }}\" placeholder=\"Nº, assunto ou solicitante…\"></label>\n  </div>\n</form>\n\n<div class=\"op-tabela-wrap\">\n  <table class=\"op-tabela\">\n    <thead><tr>\n      <th>Nº</th><th>Abertura</th><th>Setor</th><th>Assunto</th><th>Status</th><th>Última movimentação</th>\n    </tr></thead>\n    <tbody>\n    {% for c in lista %}\n      <tr onclick=\"location.href='{{ url_for('operacao.chamado', slug=empresa.slug, cid=c.id) }}'\">\n        <td class=\"op-num\"><a href=\"{{ url_for('operacao.chamado', slug=empresa.slug, cid=c.id) }}\">{{ numero_chamado(c.id) }}</a></td>\n        <td data-rot=\"Abertura\">{{ data_hora_br(c.aberto_em) }}</td>\n        <td data-rot=\"Setor\">{{ c.setor }}</td>\n        <td data-rot=\"Assunto\" class=\"op-assunto\"><b>{{ c.assunto }}</b><small>{{ c.solicitante }}{% if c.resp_nome %} · com {{ c.resp_nome }}{% endif %}</small></td>\n        <td data-rot=\"Status\"><span class=\"op-status st-{{ c.status }}\">{{ STATUS_CHAMADO[c.status] }}</span></td>\n        <td data-rot=\"Últ. movimentação\">{{ data_hora_br(c.ultima_mov_em) }}</td>\n      </tr>\n    {% else %}\n      <tr class=\"op-sem\"><td colspan=\"6\">Nenhum chamado {{ 'pendente' if st == 'abertos' else 'encontrado' }}.</td></tr>\n    {% endfor %}\n    </tbody>\n  </table>\n</div>\n\n<dialog id=\"dlg-chamado\" class=\"dlg op-dlg\">\n  <form method=\"post\" action=\"{{ url_for('operacao.chamado_novo', slug=empresa.slug) }}\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n    <div class=\"dlg-head\"><h3>Novo chamado</h3>\n      <button type=\"button\" class=\"ico\" onclick=\"this.closest('dialog').close()\">{{ ic('close') }}</button></div>\n    <div class=\"op-2col\">\n      <div>\n        <label class=\"lbl\" for=\"c-setor\">Setor responsável</label>\n        <select class=\"inp\" id=\"c-setor\" name=\"setor\" required>\n          <option value=\"\">Escolha…</option>\n          {% for s in SETORES %}<option>{{ s }}</option>{% endfor %}\n        </select>\n      </div>\n      <div>\n        <label class=\"lbl\" for=\"c-sol\">Solicitante</label>\n        <input class=\"inp\" id=\"c-sol\" name=\"solicitante\" maxlength=\"160\" placeholder=\"{{ portal_user.nome }}\">\n      </div>\n    </div>\n    <label class=\"lbl\" for=\"c-assunto\">Assunto</label>\n    <input class=\"inp\" id=\"c-assunto\" name=\"assunto\" maxlength=\"200\" required placeholder=\"Resumo da solicitação\">\n    <label class=\"lbl\" for=\"c-desc\">Descrição</label>\n    <textarea class=\"inp\" id=\"c-desc\" name=\"descricao\" rows=\"4\" placeholder=\"Explique o que precisa\"></textarea>\n    <button class=\"btn-pill\" type=\"submit\">Abrir chamado</button>\n  </form>\n</dialog>\n{% endblock %}\n",
  "operacao/demanda.html": "{% extends \"operacao/_layout.html\" %}\n{% block title %}{{ tarefa.titulo }} · Demandas{% endblock %}\n{% block op_content %}\n<a class=\"op-voltar\" href=\"{{ url_for('operacao.demandas', slug=empresa.slug) }}\">{{ ic('arrow_back') }} Demandas</a>\n\n<section class=\"op-detalhe sit-{{ tarefa.situacao }}\">\n  <header class=\"op-detalhe-head\">\n    <div>\n      <div class=\"op-meta\">\n        <span class=\"op-tag {{ 'ok' if tarefa.status == 'concluida' else ('andamento' if tarefa.status == 'andamento') }}\">{{ STATUS_TAREFA[tarefa.status] }}</span>\n        {% if tarefa.tipo == 'recorrente' %}<span class=\"op-tag\">{{ oic('repeat') }}Recorrente · {{ RECORRENCIAS.get(tarefa.recorrencia, '') }}</span>{% else %}<span class=\"op-tag\">Pontual</span>{% endif %}\n        {% if tarefa.prioridade != 'normal' %}<span class=\"op-tag {{ 'risco' if tarefa.prioridade == 'alta' }}\">Prioridade {{ PRIORIDADES[tarefa.prioridade]|lower }}</span>{% endif %}\n        {% if chamado %}<a class=\"op-tag\" href=\"{{ url_for('operacao.chamado', slug=empresa.slug, cid=chamado.id) }}\">Chamado nº {{ numero_chamado(chamado.id) }}</a>{% endif %}\n      </div>\n      <h1>{{ tarefa.titulo }}</h1>\n      <p class=\"op-info\">\n        Responsável: <b>{{ resp_nome }}</b> ·\n        {% if tarefa.status == 'concluida' %}Concluída em <b>{{ data_hora_br(tarefa.concluida_em) }}</b>\n        {% elif tarefa.vencimento %}Vencimento: <b class=\"{{ 'risco' if tarefa.situacao == 'atrasada' }}\">{{ data_br(tarefa.vencimento) }}</b>{% if tarefa.situacao == 'atrasada' %} (atrasada){% elif tarefa.situacao == 'hoje' %} (hoje){% endif %}\n        {% else %}Sem vencimento{% endif %}\n        · Lançada por {{ criador }} em {{ data_br(tarefa.criado_em) }}\n      </p>\n    </div>\n    <div class=\"op-relogio {{ 'rodando' if rodando }}\">\n      <small>Tempo nesta demanda</small>\n      <b {% if rodando %}data-op-tarefa-tempo=\"{{ tarefa.id }}\"{% endif %}>{{ hhmmss(total) }}</b>\n      {% if tarefa.status != 'concluida' and tarefa.responsavel_id == portal_user.id %}\n      <form method=\"post\" action=\"{{ url_for('operacao.demanda_acao', slug=empresa.slug, tid=tarefa.id) }}\">\n        <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n        {% if rodando %}\n          <button class=\"btn-pill outline op-btn\" name=\"acao\" value=\"parar\">{{ oic('pause') }} Pausar</button>\n        {% else %}\n          <button class=\"btn-pill op-btn\" name=\"acao\" value=\"iniciar\">{{ oic('play') }} Iniciar</button>\n        {% endif %}\n      </form>\n      {% endif %}\n    </div>\n  </header>\n\n  {% if tarefa.descricao %}<div class=\"op-desc\">{{ tarefa.descricao }}</div>{% endif %}\n\n  <div class=\"op-acoes\">\n    <form method=\"post\" action=\"{{ url_for('operacao.demanda_acao', slug=empresa.slug, tid=tarefa.id) }}\">\n      <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n      {% if tarefa.status == 'concluida' %}\n        <button class=\"btn-pill outline op-btn\" name=\"acao\" value=\"reabrir\">{{ oic('reabrir') }} Reabrir</button>\n      {% else %}\n        <button class=\"btn-pill op-btn\" name=\"acao\" value=\"concluir\">{{ oic('check') }} Marcar como concluída</button>\n      {% endif %}\n    </form>\n    <button class=\"btn-pill outline op-btn\" type=\"button\" onclick=\"document.getElementById('dlg-editar').showModal()\">{{ oic('edit') }} Editar</button>\n    {% if portal_user.admin or tarefa.criado_por == portal_user.id %}\n    <button class=\"op-link-risco\" type=\"button\" onclick=\"document.getElementById('dlg-excluir').showModal()\">{{ oic('delete') }} Excluir</button>\n    {% endif %}\n  </div>\n</section>\n\n<div class=\"op-cols\">\n  <section class=\"op-card\">\n    <h3>Acompanhamento</h3>\n    <p class=\"op-sub\">Anotações e histórico do que foi feito</p>\n    <form class=\"op-nota-form\" method=\"post\" action=\"{{ url_for('operacao.demanda_acao', slug=empresa.slug, tid=tarefa.id) }}\">\n      <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n      <input type=\"hidden\" name=\"acao\" value=\"nota\">\n      <textarea class=\"inp\" name=\"texto\" rows=\"3\" required placeholder=\"Escreva o que foi feito, uma pendência, um contato…\"></textarea>\n      <button class=\"btn-pill op-btn\" type=\"submit\">{{ oic('nota') }} Adicionar anotação</button>\n    </form>\n    <ol class=\"op-timeline\">\n      {% for n in notas %}\n        <li class=\"{{ 'evento' if n.tipo == 'evento' }}\">\n          <span class=\"op-quando\">{{ data_hora_br(n.criado_em) }} · {{ n.autor }}</span>\n          <span class=\"op-texto\">{{ n.texto }}</span>\n        </li>\n      {% else %}\n        <li class=\"evento\"><span class=\"op-texto\">Nenhuma anotação ainda.</span></li>\n      {% endfor %}\n    </ol>\n  </section>\n  <aside class=\"op-resumo\">\n    <section class=\"op-card\">\n      <h3>Tempo registrado</h3>\n      <p class=\"op-sub\">Total: <b>{{ hhmm(total) }}</b></p>\n      <ul class=\"op-sessoes\">\n        {% for x in tempos %}\n          <li><span>{{ data_br(x.inicio) }} · {{ x.inicio[11:16] }}–{{ x.fim[11:16] if x.fim else 'agora' }}{% if portal_user.admin %} · {{ x.autor }}{% endif %}</span><b>{{ hhmm(x.segundos) }}</b></li>\n        {% else %}\n          <li><span>Nenhum tempo registrado. Use “Iniciar”.</span></li>\n        {% endfor %}\n      </ul>\n    </section>\n    {% if serie|length > 1 %}\n    <section class=\"op-card\">\n      <h3>Ocorrências desta rotina</h3>\n      <ul class=\"op-sessoes\">\n        {% for s in serie %}\n          <li><a href=\"{{ url_for('operacao.demanda', slug=empresa.slug, tid=s.id) }}\">{{ data_br(s.vencimento) or 'sem data' }}{% if s.id == tarefa.id %} (esta){% endif %}</a>\n            <b class=\"{{ 'ok' if s.status == 'concluida' }}\">{{ STATUS_TAREFA[s.status] }}</b></li>\n        {% endfor %}\n      </ul>\n    </section>\n    {% endif %}\n  </aside>\n</div>\n\n<dialog id=\"dlg-editar\" class=\"dlg op-dlg\">\n  <form method=\"post\" action=\"{{ url_for('operacao.demanda_acao', slug=empresa.slug, tid=tarefa.id) }}\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n    <input type=\"hidden\" name=\"acao\" value=\"editar\">\n    <div class=\"dlg-head\"><h3>Editar demanda</h3>\n      <button type=\"button\" class=\"ico\" onclick=\"this.closest('dialog').close()\">{{ ic('close') }}</button></div>\n    {% with d=tarefa %}{% include \"operacao/_form_demanda.html\" %}{% endwith %}\n    <button class=\"btn-pill\" type=\"submit\">Salvar alterações</button>\n  </form>\n</dialog>\n<dialog id=\"dlg-excluir\" class=\"dlg op-dlg\">\n  <form method=\"post\" action=\"{{ url_for('operacao.demanda_acao', slug=empresa.slug, tid=tarefa.id) }}\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n    <input type=\"hidden\" name=\"acao\" value=\"excluir\">\n    <div class=\"dlg-head\"><h3>Excluir demanda?</h3>\n      <button type=\"button\" class=\"ico\" onclick=\"this.closest('dialog').close()\">{{ ic('close') }}</button></div>\n    <p>“{{ tarefa.titulo }}” será apagada junto com as anotações e o tempo registrado nela. Isso não pode ser desfeito.</p>\n    <div class=\"row-btns\">\n      <button class=\"btn-pill outline\" type=\"button\" onclick=\"this.closest('dialog').close()\">Cancelar</button>\n      <button class=\"btn-pill op-risco\" type=\"submit\">Excluir</button>\n    </div>\n  </form>\n</dialog>\n{% include \"operacao/_js_form.html\" %}\n{% endblock %}\n",
  "operacao/demandas.html": "{% extends \"operacao/_layout.html\" %}\n{% block title %}Demandas · {{ empresa.nome }}{% endblock %}\n{% block op_content %}\n<div class=\"op-head\">\n  <div>\n    <div class=\"eyebrow-line\">Demandas e rotinas</div>\n    <h1>{{ 'Demandas da equipe' if portal_user.admin else 'Minhas demandas' }}</h1>\n    <p>Tudo o que precisa ser feito na {{ empresa.nome }}: lance, acompanhe, anote e conclua.</p>\n  </div>\n  <button class=\"btn-pill\" type=\"button\" onclick=\"document.getElementById('dlg-nova').showModal()\">{{ oic('add') }} Nova demanda</button>\n</div>\n\n<div class=\"op-kpis\">\n  <div class=\"op-kpi {{ 'risco' if cont.atrasadas }}\"><b>{{ cont.atrasadas }}</b><span>Atrasadas</span></div>\n  <div class=\"op-kpi\"><b>{{ cont.hoje }}</b><span>Vencem hoje</span></div>\n  <div class=\"op-kpi\"><b>{{ cont.abertas }}</b><span>Em aberto</span></div>\n  <div class=\"op-kpi dark\"><b>{{ hhmm(semana[-1].s) }}</b><span>Na empresa hoje</span></div>\n</div>\n\n<form class=\"op-toolbar\" method=\"get\">\n  <input type=\"hidden\" name=\"aba\" value=\"{{ aba }}\">\n  <div class=\"chips\">\n    {% for k, rot in [('hoje','Hoje e atrasadas'),('proximas','Próximas'),('recorrentes','Recorrentes'),('todas','Todas abertas'),('concluidas','Concluídas')] %}\n      <a class=\"chip {{ 'on' if aba == k }}\" href=\"{{ url_for('operacao.demandas', slug=empresa.slug, aba=k, resp=resp, q=busca or None) }}\">{{ rot }} <small>{{ abas[k] }}</small></a>\n    {% endfor %}\n  </div>\n  <div class=\"op-filtros\">\n    {% if portal_user.admin %}\n    <select class=\"inp\" name=\"resp\" onchange=\"this.form.submit()\" aria-label=\"Responsável\">\n      <option value=\"\">Toda a equipe</option>\n      {% for x in usuarios %}<option value=\"{{ x.id }}\" {{ 'selected' if resp == x.id }}>{{ x.nome }}</option>{% endfor %}\n    </select>\n    {% endif %}\n    <label class=\"search\">{{ ic('search') }}<input type=\"search\" name=\"q\" value=\"{{ busca }}\" placeholder=\"Buscar demanda…\"></label>\n  </div>\n</form>\n\n<div class=\"op-cols\">\n  <div class=\"op-lista\">\n    {% for t in lista %}\n    <article class=\"op-tarefa sit-{{ t.situacao }} {{ 'rodando' if t.rodando }}\">\n      <form method=\"post\" action=\"{{ url_for('operacao.demanda_acao', slug=empresa.slug, tid=t.id) }}\">\n        <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n        <input type=\"hidden\" name=\"voltar\" value=\"{{ request.full_path }}\">\n        {% if t.status == 'concluida' %}\n          <button class=\"op-check feito\" name=\"acao\" value=\"reabrir\" title=\"Reabrir\">{{ oic('check') }}</button>\n        {% else %}\n          <button class=\"op-check\" name=\"acao\" value=\"concluir\" title=\"Marcar como concluída\">{{ oic('check') }}</button>\n        {% endif %}\n      </form>\n      <a class=\"op-tarefa-corpo\" href=\"{{ url_for('operacao.demanda', slug=empresa.slug, tid=t.id) }}\">\n        <b>{{ t.titulo }}</b>\n        <span class=\"op-meta\">\n          {% if t.status == 'concluida' %}<span class=\"op-venc ok\">Concluída em {{ data_hora_br(t.concluida_em) }}</span>\n          {% elif t.situacao == 'atrasada' %}<span class=\"op-venc risco\">Venceu {{ data_br(t.vencimento) }}</span>\n          {% elif t.situacao == 'hoje' %}<span class=\"op-venc aviso\">Vence hoje</span>\n          {% elif t.vencimento %}<span class=\"op-venc\">Vence {{ data_br(t.vencimento) }}</span>\n          {% else %}<span class=\"op-venc\">Sem data</span>{% endif %}\n          {% if t.tipo == 'recorrente' %}<span class=\"op-tag\">{{ oic('repeat') }}{{ RECORRENCIAS.get(t.recorrencia, '') }}</span>{% endif %}\n          {% if t.prioridade == 'alta' %}<span class=\"op-tag risco\">Prioridade alta</span>{% endif %}\n          {% if t.chamado_id %}<span class=\"op-tag\">Chamado nº {{ numero_chamado(t.chamado_id) }}</span>{% endif %}\n          {% if t.status == 'andamento' %}<span class=\"op-tag andamento\">Em andamento</span>{% endif %}\n          {% if portal_user.admin %}<span class=\"op-resp\">{{ t.resp_nome }}</span>{% endif %}\n        </span>\n      </a>\n      <div class=\"op-tempo\">\n        <span class=\"op-tempo-n\" {% if t.rodando %}data-op-tarefa-tempo=\"{{ t.id }}\"{% endif %}>{{ hhmmss(t.segundos) }}</span>\n        {% if t.status != 'concluida' and t.responsavel_id == portal_user.id %}\n        <form method=\"post\" action=\"{{ url_for('operacao.demanda_acao', slug=empresa.slug, tid=t.id) }}\">\n          <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n          <input type=\"hidden\" name=\"voltar\" value=\"{{ request.full_path }}\">\n          {% if t.rodando %}\n            <button class=\"op-play on\" name=\"acao\" value=\"parar\" title=\"Pausar o tempo desta demanda\">{{ oic('pause') }}</button>\n          {% else %}\n            <button class=\"op-play\" name=\"acao\" value=\"iniciar\" title=\"Começar a contar o tempo nesta demanda\">{{ oic('play') }}</button>\n          {% endif %}\n        </form>\n        {% endif %}\n      </div>\n    </article>\n    {% else %}\n    <div class=\"op-vazio\">\n      {% if aba == 'hoje' %}Nada vencendo hoje nem atrasado. {% if abas.proximas %}Veja as <a href=\"{{ url_for('operacao.demandas', slug=empresa.slug, aba='proximas', resp=resp) }}\">próximas</a>.{% endif %}\n      {% elif aba == 'concluidas' %}Nenhuma demanda concluída ainda.\n      {% else %}Nenhuma demanda aqui. Use “Nova demanda” para lançar.{% endif %}\n    </div>\n    {% endfor %}\n  </div>\n\n  <aside class=\"op-resumo\">\n    <section class=\"op-card\">\n      <h3>Onde o tempo foi gasto</h3>\n      <p class=\"op-sub\">Demandas com mais tempo nos últimos 7 dias</p>\n      {% for r in gasto %}\n        <a class=\"op-barra\" href=\"{{ url_for('operacao.demanda', slug=empresa.slug, tid=r.id) }}\">\n          <span class=\"op-barra-rot\"><span>{{ r.titulo }}</span><b>{{ hhmm(r.s) }}</b></span>\n          <span class=\"op-barra-trilha\"><i style=\"width: {{ ((r.s or 0) * 100 / maior)|round|int }}%\"></i></span>\n        </a>\n      {% else %}\n        <p class=\"op-sub\">Use o ▶ de uma demanda para começar a medir.</p>\n      {% endfor %}\n    </section>\n    <section class=\"op-card\">\n      <h3>Tempo na empresa</h3>\n      <p class=\"op-sub\">Cronômetro da barra superior, por dia</p>\n      {% set maxd = (semana|map(attribute='s')|max) or 1 %}\n      <div class=\"op-semana\">\n        {% for d in semana %}\n          <div class=\"op-dia\" title=\"{{ d.dia.strftime('%d/%m') }}: {{ hhmm(d.s) }}\">\n            <span class=\"op-dia-col\"><i style=\"height: {{ (d.s * 100 / maxd)|round|int }}%\"></i></span>\n            <small>{{ ['seg','ter','qua','qui','sex','sáb','dom'][d.dia.weekday()] }}</small>\n          </div>\n        {% endfor %}\n      </div>\n      <p class=\"op-sub\">Semana: <b>{{ hhmm(semana|sum(attribute='s')) }}</b></p>\n    </section>\n  </aside>\n</div>\n\n<dialog id=\"dlg-nova\" class=\"dlg op-dlg\">\n  <form method=\"post\" action=\"{{ url_for('operacao.demanda_nova', slug=empresa.slug) }}\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n    <div class=\"dlg-head\"><h3>Nova demanda</h3>\n      <button type=\"button\" class=\"ico\" onclick=\"this.closest('dialog').close()\">{{ ic('close') }}</button></div>\n    {% with d=none %}{% include \"operacao/_form_demanda.html\" %}{% endwith %}\n    <button class=\"btn-pill\" type=\"submit\">Lançar demanda</button>\n  </form>\n</dialog>\n{% include \"operacao/_js_form.html\" %}\n{% endblock %}\n",
  "placeholder.html": "{% extends \"base.html\" %}\n{% block title %}{{ titulo }} — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n\n<div class=\"page-header\">\n  <div class=\"page-header-icon\">{{ icon }}</div>\n  <div class=\"page-header-title\">{{ titulo }}</div>\n</div>\n\n<div class=\"placeholder-box\">\n  <div class=\"placeholder-icon\">🚧</div>\n  <div class=\"placeholder-title\">Módulo em desenvolvimento</div>\n  <div class=\"placeholder-sub\">{{ subtitulo }}</div>\n</div>\n\n{% endblock %}\n",
  "portal/admin.html": "{% extends \"portal/base.html\" %}\n{% block title %}Administração · Portal Grupo Capuzzo{% endblock %}\n{% block tb_links %}\n  <a class=\"tb-btn\" href=\"{{ url_for('portal_grupo') }}\">{{ ic('apps') }}<span class=\"lbl\">Empresas</span></a>\n{% endblock %}\n{% block content %}\n<section class=\"page-title\"><div class=\"eyebrow-line\">Grupo Capuzzo</div><h1>Administração</h1></section>\n<nav class=\"tabs\">\n  <a class=\"{{ 'on' if aba != 'empresas' }}\" href=\"{{ url_for('portal_admin') }}\">Usuários</a>\n  <a class=\"{{ 'on' if aba == 'empresas' }}\" href=\"{{ url_for('portal_admin', aba='empresas') }}\">Empresas</a>\n</nav>\n\n{% if aba != 'empresas' %}\n<div class=\"box\">\n  <table class=\"tbl\">\n    <thead><tr><th>Nome</th><th>E-mail</th><th>Perfil</th><th>Situação</th><th>Empresas</th><th>Último acesso</th><th></th></tr></thead>\n    <tbody>\n    {% for u in usuarios %}\n      <tr class=\"{{ 'sel' if editar and editar.id == u.id }}\">\n        <td><b>{{ u.nome }}</b></td><td>{{ u.email }}</td>\n        <td>{{ 'Administrador' if u.perfil == 'admin' else 'Usuário' }}</td>\n        <td>{% if u.ativo %}<span class=\"tag tag-on\">Ativo</span>{% else %}<span class=\"tag tag-off\">Bloqueado</span>{% endif %}</td>\n        <td>{% if u.perfil == 'admin' %}Todas{% else %}{% for e in empresas if e.slug in u.empresas %}{{ e.nome }}{% if u.modulos.get(e.slug) %} <small>({{ e.modulos|selectattr('id', 'in', u.modulos.get(e.slug))|map(attribute='nome')|join(', ') }})</small>{% endif %}{{ ', ' if not loop.last }}{% else %}—{% endfor %}{% endif %}</td>\n        <td>{{ (u.ultimo_login or '—')|replace('T', ' ') }}</td>\n        <td><a class=\"lnk\" href=\"{{ url_for('portal_admin', u=u.id) }}\">Editar</a></td>\n      </tr>\n    {% endfor %}\n    </tbody>\n  </table>\n</div>\n\n<div class=\"cols\">\n  {% for modo in ['novo', 'editar'] %}\n  {% set u = editar if modo == 'editar' else none %}\n  {% if modo == 'novo' or u %}\n  <form class=\"box\" method=\"post\" action=\"{{ url_for('portal_admin_usuario') }}\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n    {% if u %}<input type=\"hidden\" name=\"id\" value=\"{{ u.id }}\">{% endif %}\n    <div class=\"box-title\">{{ 'Editar ' ~ u.nome if u else 'Novo usuário' }}</div>\n    <label class=\"lbl\">Nome</label><input class=\"inp\" name=\"nome\" value=\"{{ u.nome if u else '' }}\" required>\n    <label class=\"lbl\">E-mail</label>\n    <input class=\"inp\" name=\"email\" type=\"email\" value=\"{{ u.email if u else '' }}\" {% if u %}disabled{% else %}required{% endif %}>\n    {% set eu = u and u.id == portal_user.id %}\n    <label class=\"lbl\">Perfil</label>\n    <div class=\"radios\">\n      <label><input type=\"radio\" name=\"perfil\" value=\"usuario\" {% if not u or u.perfil != 'admin' %}checked{% endif %} {% if eu %}disabled{% endif %}> Usuário</label>\n      <label><input type=\"radio\" name=\"perfil\" value=\"admin\" {% if u and u.perfil == 'admin' %}checked{% endif %} {% if eu %}disabled{% endif %}> Administrador</label>\n    </div>\n    <label class=\"lbl\">Empresas liberadas <small>(para perfil Usuário)</small></label>\n    <div class=\"checks\">\n      {% for e in empresas %}\n        <label><input type=\"checkbox\" name=\"empresas\" value=\"{{ e.slug }}\" {% if u and e.slug in u.empresas %}checked{% endif %}>\n          <span class=\"logo-circle xxs\"><img src=\"{{ url_for('static', filename='portal/logos/' ~ e.logo) }}\" alt=\"\"></span>{{ e.nome }}</label>\n        {% if e.modulos %}<div class=\"hint\" style=\"margin:-.15rem 0 .45rem 1.7rem\">Módulos:\n          {% for m in e.modulos %}<label style=\"display:inline-flex;align-items:center;gap:.25rem;margin-right:.7rem;font-weight:400\"><input type=\"checkbox\" name=\"mod_{{ e.slug }}\" value=\"{{ m.id }}\" {% if u and m.id in (u.modulos.get(e.slug) or []) %}checked{% endif %}>{{ m.nome }}</label>{% endfor %}\n          <span style=\"opacity:.75\">(nenhum marcado = todos)</span></div>{% endif %}\n      {% endfor %}\n    </div>\n    <label class=\"lbl\">{{ 'Redefinir senha (opcional)' if u else 'Senha provisória' }}</label>\n    <input class=\"inp\" name=\"senha\" type=\"password\" {% if not u %}required{% endif %} minlength=\"8\" autocomplete=\"new-password\">\n    <p class=\"hint\">Mínimo de 8 caracteres, com letras e números.</p>\n    {% if u %}\n    <label class=\"check-line\"><input type=\"checkbox\" name=\"ativo\" value=\"1\" {% if u.ativo %}checked{% endif %} {% if eu %}disabled{% endif %}> Acesso ativo</label>\n    {% if eu %}<p class=\"hint\">Você não pode remover o seu próprio acesso de administrador.</p>{% endif %}\n    {% else %}<input type=\"hidden\" name=\"ativo\" value=\"1\">{% endif %}\n    <div class=\"row-btns\">\n      {% if u %}<a class=\"btn-pill outline\" href=\"{{ url_for('portal_admin') }}\">Fechar</a>{% endif %}\n      <button class=\"btn-pill\" type=\"submit\">{{ 'Salvar alterações' if u else 'Criar usuário' }}</button>\n    </div>\n  </form>\n  {% endif %}\n  {% endfor %}\n</div>\n\n{% else %}\n<div class=\"emp-admin\">\n  {% for e in empresas %}\n  <form class=\"box emp-row\" method=\"post\" action=\"{{ url_for('portal_admin_empresa', slug=e.slug) }}\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n    <input type=\"hidden\" name=\"voltar\" value=\"{{ url_for('portal_admin', aba='empresas') }}\">\n    <span class=\"logo-circle\"><img src=\"{{ url_for('static', filename='portal/logos/' ~ e.logo) }}\" alt=\"\"></span>\n    <div class=\"emp-row-name\"><b>{{ e.nome }}</b>\n      <span class=\"swatches\">{% for k in ['primary','secondary','accent','bg'] %}<i style=\"background:{{ e.tema_full[k] }}\"></i>{% endfor %}</span></div>\n    <select class=\"inp\" name=\"status\">{% for k, v in STATUS.items() %}<option value=\"{{ k }}\" {% if e.status == k %}selected{% endif %}>{{ v }}</option>{% endfor %}</select>\n    <input class=\"inp\" name=\"obs\" value=\"{{ e.obs }}\" placeholder=\"Observação (ex.: Pendência financeira)\" maxlength=\"120\">\n    <button class=\"btn-pill\" type=\"submit\">Salvar</button>\n  </form>\n  {% endfor %}\n  <p class=\"hint\">Cores, logos e módulos de cada empresa ficam no arquivo <code>app/portal_grupo.py</code>.</p>\n</div>\n{% endif %}\n{% endblock %}\n",
  "portal/base.html": "<!DOCTYPE html>\n<html lang=\"pt-BR\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>{% block title %}Portal Grupo Capuzzo{% endblock %}</title>\n  <link rel=\"icon\" href=\"{{ url_for('static', filename='portal/logos/grupo_capuzzo.png') }}\">\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600;700&family={{ t.font_head|replace(' ', '+') }}:wght@300;400;600;700;800&display=swap\">\n  <style>\n    :root {\n      --primary:{{ t.primary }}; --secondary:{{ t.secondary }}; --accent:{{ t.accent }};\n      --accent-dark:{{ t.accent_dark }}; --on-primary:{{ t.on_primary }}; --on-accent:{{ t.on_accent }};\n      --bg:{{ t.bg }}; --surface:{{ t.surface }}; --text:{{ t.text }}; --muted:{{ t.muted }};\n      --font-head:'{{ t.font_head }}', 'Poppins', 'Segoe UI', sans-serif;\n    }\n  </style>\n  <link rel=\"stylesheet\" href=\"{{ url_for('static', filename='portal/portal.css') }}\">\n  <link rel=\"stylesheet\" href=\"{{ url_for('static', filename='portal/tema.css') }}?v=1\">\n  <script>try { if (localStorage.getItem('tema') === 'escuro') document.documentElement.setAttribute('data-tema', 'escuro'); } catch (e) {}</script>\n  {% block head %}{% endblock %}\n</head>\n<body class=\"{% block body_class %}{% endblock %}\">\n{% block topbar %}{% if portal_user %}\n<header class=\"topbar\">\n  <div class=\"topbar-in\">\n    <a class=\"tb-brand\" href=\"{{ url_for('portal_grupo') }}\">{% block brand %}\n      <img class=\"brand\" src=\"{{ url_for('static', filename='portal/logos/grupo_word_light.png') }}\" alt=\"Grupo Capuzzo\">\n    {% endblock %}</a>\n    <nav class=\"tb-nav\">\n      {% block tb_links %}{% endblock %}\n      {% if portal_user.admin %}\n        <a class=\"tb-btn\" href=\"/erp/central/plano\">{{ ic('checklist') }}<span class=\"lbl\">Plano de ação</span></a>\n        <a class=\"tb-btn\" href=\"{{ url_for('portal_admin') }}\">{{ ic('admin_panel_settings') }}<span class=\"lbl\">Administração</span></a>\n      {% endif %}\n      <button type=\"button\" class=\"tb-btn tb-tema\" id=\"tb-tema\" title=\"Alternar tema claro / escuro\" aria-label=\"Alternar tema claro / escuro\">\n        <svg class=\"ms lua\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path fill=\"currentColor\" d=\"M12 21q-3.75 0-6.375-2.625T3 12q0-3.75 2.625-6.375T12 3q.35 0 .688.025t.662.075q-1.025.725-1.638 1.888T11.1 7.5q0 2.25 1.575 3.825T16.5 12.9q1.375 0 2.525-.613T20.9 10.65q.05.325.075.662T21 12q0 3.75-2.625 6.375T12 21\"/></svg>\n        <svg class=\"ms sol\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path fill=\"currentColor\" d=\"M12 17q-2.075 0-3.537-1.463T7 12t1.463-3.537T12 7t3.538 1.463T17 12t-1.463 3.538T12 17M2 13q-.425 0-.712-.288T1 12t.288-.712T2 11h2q.425 0 .713.288T5 12t-.288.713T4 13zm18 0q-.425 0-.712-.288T19 12t.288-.712T20 11h2q.425 0 .713.288T23 12t-.288.713T22 13zm-8-8q-.425 0-.712-.288T11 4V2q0-.425.288-.712T12 1t.713.288T13 2v2q0 .425-.288.713T12 5m0 18q-.425 0-.712-.288T11 22v-2q0-.425.288-.712T12 19t.713.288T13 20v2q0 .425-.288.713T12 23M5.65 7.05L4.575 6q-.3-.275-.288-.7t.288-.725q.3-.3.725-.3t.7.3L7.05 5.65q.275.3.275.7t-.275.7t-.687.288t-.713-.288M18 19.425l-1.05-1.075q-.275-.3-.275-.712t.275-.688q.275-.3.688-.287t.712.287L19.425 18q.3.275.288.7t-.288.725q-.3.3-.725.3t-.7-.3M16.95 7.05q-.3-.275-.288-.687t.288-.713L18 4.575q.275-.3.7-.288t.725.288q.3.3.3.725t-.3.7L18.35 7.05q-.3.275-.7.275t-.7-.275M4.575 19.425q-.3-.3-.3-.725t.3-.7l1.075-1.05q.3-.275.712-.275t.688.275q.3.275.288.688t-.288.712L6 19.425q-.275.3-.7.288t-.725-.288\"/></svg>\n        <span class=\"lbl\">Tema</span></button>\n      <details class=\"tb-user\">\n        <summary>\n          <span class=\"who\"><b>{{ portal_user.nome }}</b><small>{{ 'Administrador' if portal_user.admin else 'Usuário' }}</small></span>\n          <span class=\"avatar\">{{ portal_user.nome[:1]|upper }}</span>\n          {{ ic('expand_more') }}\n        </summary>\n        <div class=\"menu\">\n          <div class=\"menu-mail\">{{ portal_user.email }}</div>\n          <a href=\"{{ url_for('portal_minha_senha') }}\">{{ ic('key') }} Alterar senha</a>\n          <a href=\"{{ url_for('portal_logout') }}\">{{ ic('logout') }} Sair</a>\n        </div>\n      </details>\n    </nav>\n  </div>\n</header>\n{% endif %}{% endblock %}\n\n<main class=\"wrap\">\n  {% with msgs = get_flashed_messages(with_categories=true) %}\n    {% if msgs %}<div class=\"flashes\">{% for cat, m in msgs %}<div class=\"flash flash-{{ cat }}\">{{ m }}</div>{% endfor %}</div>{% endif %}\n  {% endwith %}\n  {% block content %}{% endblock %}\n</main>\n<script>\n(function () {\n  var b = document.getElementById('tb-tema'); if (!b) return;\n  b.addEventListener('click', function () {\n    var h = document.documentElement, escuro = h.getAttribute('data-tema') !== 'escuro';\n    h.classList.add('tema-trocando');\n    if (escuro) h.setAttribute('data-tema', 'escuro'); else h.removeAttribute('data-tema');\n    try { localStorage.setItem('tema', escuro ? 'escuro' : 'claro'); } catch (e) {}\n    setTimeout(function () { h.classList.remove('tema-trocando'); }, 300);\n  });\n})();\n</script>\n{% block scripts %}{% endblock %}\n</body>\n</html>\n",
  "portal/empresa.html": "{% extends \"portal/base.html\" %}\n{% block title %}{{ empresa.nome }} · Portal Grupo Capuzzo{% endblock %}\n{% block brand %}\n  <span class=\"logo-circle xs\"><img src=\"{{ url_for('static', filename='portal/logos/' ~ empresa.logo) }}\" alt=\"\"></span>\n  <span class=\"tb-name\"><b>{{ empresa.nome }}</b><small>Grupo Capuzzo</small></span>\n{% endblock %}\n{% block tb_links %}\n  <a class=\"tb-btn\" href=\"{{ url_for('portal_grupo') }}\">{{ ic('apps') }}<span class=\"lbl\">Empresas</span></a>\n  {% include \"operacao/_barra_empresa.html\" ignore missing %}\n{% endblock %}\n{% block content %}\n<section class=\"emp-head\">\n  <span class=\"logo-square\"><img src=\"{{ url_for('static', filename='portal/logos/' ~ empresa.logo) }}\" alt=\"{{ empresa.nome }}\"></span>\n  <div>\n    <div class=\"eyebrow-line\">Módulos</div>\n    <h1>{{ empresa.nome }}</h1>\n    <p>{{ 'Selecione o módulo que deseja acessar.' if modulos else 'Os módulos desta empresa aparecerão aqui conforme forem liberados.' }}</p>\n  </div>\n</section>\n\n{% if not modulos %}\n<div class=\"empty\">\n  <div class=\"empty-ic\">{{ ic('grid_view') }}</div>\n  <h3>Nenhum módulo disponível ainda</h3>\n  <p>Assim que o primeiro módulo da {{ empresa.nome }} for publicado, ele aparecerá aqui com o botão de acesso.</p>\n</div>\n{% else %}\n<div class=\"mods\">\n  {% for m in modulos %}\n  <article class=\"mod {{ 'mod-on' if m.status == 'ativo' }}\">\n    <div class=\"mod-ic\">{{ ic(m.icone) }}</div>\n    <h3>{{ m.nome }}</h3>\n    <p>{{ m.desc }}</p>\n    <div class=\"mod-foot\">\n      {% if m.status == 'ativo' %}<span class=\"tag tag-on\">Disponível</span>{% else %}<span class=\"tag\">Em construção</span>{% endif %}\n      <a class=\"btn-pill\" href=\"{{ url_for('portal_modulo', slug=empresa.slug, modulo_id=m.id) }}\">Acessar</a>\n    </div>\n  </article>\n  {% endfor %}\n</div>\n{% endif %}\n{% endblock %}\n",
  "portal/erro.html": "{% extends \"portal/base.html\" %}\n{% block title %}Acesso negado · Portal Grupo Capuzzo{% endblock %}\n{% block content %}\n<div class=\"empty\" style=\"margin-top:3rem\">\n  <div class=\"empty-ic\">{{ ic('block') }}</div>\n  <h3>{{ msg }}</h3>\n  <p>Se precisar de acesso, fale com o administrador do portal.</p>\n  <p style=\"margin-top:1.2rem\"><a class=\"btn-pill\" href=\"{{ url_for('portal_grupo') }}\">Voltar às empresas</a></p>\n</div>\n{% endblock %}\n",
  "portal/grupo.html": "{% extends \"portal/base.html\" %}\n{% block title %}Empresas · Portal Grupo Capuzzo{% endblock %}\n{% block content %}\n<section class=\"hero\">\n  <div>\n    <div class=\"eyebrow-line\">Portal do Grupo Capuzzo</div>\n    <h1>Olá, <b>{{ portal_user.nome.split()[0] }}</b>.</h1>\n    <p>Escolha a empresa que deseja acessar.</p>\n  </div>\n  <div class=\"stats\">\n    <div class=\"stat dark\"><b>{{ empresas|length }}</b><span>Empresas</span></div>\n    <div class=\"stat\"><b>{{ ativas }}</b><span>Ativas</span></div>\n    <div class=\"stat\"><b>{{ pendentes }}</b><span>Pendentes</span></div>\n  </div>\n</section>\n\n{% if not empresas %}\n  <div class=\"vazio\">Nenhuma empresa liberada para o seu usuário. Fale com o administrador.</div>\n{% else %}\n<div class=\"toolbar\">\n  <label class=\"search\">{{ ic('search') }}\n    <input id=\"busca\" type=\"search\" placeholder=\"Buscar empresa…\" autocomplete=\"off\"></label>\n  <div class=\"chips\" id=\"filtros\">\n    <button class=\"chip on\" data-f=\"todas\">Todas</button>\n    <button class=\"chip\" data-f=\"fav\">Favoritas</button>\n    <button class=\"chip\" data-f=\"ativo\">Ativas</button>\n    <button class=\"chip\" data-f=\"pendente\">Pendentes</button>\n  </div>\n</div>\n\n<div class=\"grid\" id=\"grid\">\n  {% for e in empresas %}\n    {% if loop.index0 == 1 %}\n    <article class=\"promo\" id=\"promo\">\n      <div class=\"slide\"><small>Grupo Capuzzo</small><h4>Bem-vindo, <b>{{ portal_user.nome.split()[0] }}</b>.</h4>\n        <p>Selecione uma empresa para ver os módulos dela, com a identidade visual da própria marca.</p></div>\n      <div class=\"slide\"><small>Visão do grupo</small><h4><b>{{ ativas }}</b> empresas ativas</h4>\n        <p>{{ pendentes }} com pendência no momento. Acompanhe a situação de cada uma pelos cartões.</p></div>\n      <div class=\"slide\"><small>Dica</small><h4>Seus <b>favoritos</b> primeiro</h4>\n        <p>Toque no coração de um cartão para fixar a empresa no topo da lista.</p></div>\n      <img class=\"mark\" src=\"{{ url_for('static', filename='portal/logos/grupo_word_light.png') }}\" alt=\"\">\n      <div class=\"dots\"><i></i><i></i><i></i></div>\n    </article>\n    {% endif %}\n    {% set fav = e.slug in favs %}\n    <article class=\"card st-{{ e.status }}\" id=\"emp-{{ e.slug }}\" data-nome=\"{{ e.nome|lower }}\"\n             data-status=\"{{ e.status }}\" data-fav=\"{{ 1 if fav else 0 }}\">\n      <header class=\"card-head\">\n        <div class=\"status\"><span class=\"bar\"></span>\n          <div><b>{{ STATUS[e.status] }}{% if e.status != 'ativo' %} *{% endif %}</b>\n            {% if e.status != 'ativo' %}<small>* {{ e.obs or ('Pendência' if e.status == 'pendente' else 'Acesso suspenso') }}</small>{% endif %}</div>\n        </div>\n        <div class=\"head-actions\">\n          <form method=\"post\" action=\"{{ url_for('portal_favorito', slug=e.slug) }}\">\n            <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n            <button class=\"ico {{ 'fav-on' if fav }}\" title=\"{{ 'Remover dos favoritos' if fav else 'Favoritar' }}\">\n              {{ ic('favorite' if fav else 'favorite_border') }}</button>\n          </form>\n          {% if portal_user.admin %}\n          <button class=\"ico\" type=\"button\" title=\"Configurar\" onclick=\"abrirConfig('{{ e.slug }}')\">{{ ic('settings') }}</button>\n          {% endif %}\n        </div>\n      </header>\n      <div class=\"card-body\">\n        <span class=\"logo-circle\"><img src=\"{{ url_for('static', filename='portal/logos/' ~ e.logo) }}\" alt=\"{{ e.nome }}\"></span>\n        <div><h3>{{ e.nome }}</h3>{% if e.descricao %}<p>{{ e.descricao }}</p>{% endif %}</div>\n      </div>\n      <footer class=\"card-foot\">\n        {% if e.status == 'inativo' and not portal_user.admin %}\n          <span class=\"btn-pill disabled\">Acessar</span>\n        {% else %}\n          <a class=\"btn-pill {{ 'outline' if e.status != 'ativo' }}\" href=\"{{ url_for('portal_empresa', slug=e.slug) }}\">Acessar</a>\n        {% endif %}\n      </footer>\n    </article>\n  {% endfor %}\n</div>\n<div class=\"vazio\" id=\"semres\" hidden>Nenhuma empresa encontrada com esse filtro.</div>\n\n{% if portal_user.admin %}\n<dialog id=\"dlg-config\" class=\"dlg\">\n  <form method=\"post\" id=\"form-config\">\n    <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n    <input type=\"hidden\" name=\"voltar\" value=\"{{ url_for('portal_grupo') }}\">\n    <div class=\"dlg-head\"><h3>Configurar empresa</h3>\n      <button type=\"button\" class=\"ico\" onclick=\"this.closest('dialog').close()\">{{ ic('close') }}</button></div>\n    <div class=\"dlg-emp\"><span class=\"logo-circle\"><img id=\"cfg-logo\" src=\"\" alt=\"\"></span><b id=\"cfg-nome\"></b></div>\n    <label class=\"lbl\">Situação</label>\n    <select class=\"inp\" name=\"status\" id=\"cfg-status\">\n      {% for k, v in STATUS.items() %}<option value=\"{{ k }}\">{{ v }}</option>{% endfor %}\n    </select>\n    <label class=\"lbl\">Observação da situação</label>\n    <input class=\"inp\" name=\"obs\" id=\"cfg-obs\" maxlength=\"120\" placeholder=\"Ex.: Pendência financeira\">\n    <p class=\"hint\">Usuários com acesso a cada empresa são definidos em Administração.</p>\n    <button class=\"btn-pill\" type=\"submit\">Salvar</button>\n  </form>\n</dialog>\n<script>\n  const DADOS = {\n    {% for e in empresas %}\"{{ e.slug }}\": {nome: {{ e.nome|tojson }}, status: \"{{ e.status }}\", obs: {{ e.obs|tojson }},\n      logo: \"{{ url_for('static', filename='portal/logos/' ~ e.logo) }}\",\n      url: \"{{ url_for('portal_admin_empresa', slug=e.slug) }}\"},{% endfor %}\n  };\n  function abrirConfig(slug) {\n    const d = DADOS[slug];\n    document.getElementById('form-config').action = d.url;\n    document.getElementById('cfg-nome').textContent = d.nome;\n    document.getElementById('cfg-logo').src = d.logo;\n    document.getElementById('cfg-status').value = d.status;\n    document.getElementById('cfg-obs').value = d.obs;\n    document.getElementById('dlg-config').showModal();\n  }\n</script>\n{% endif %}\n{% endif %}\n{% endblock %}\n\n{% block scripts %}\n<script>\n(function () {\n  const busca = document.getElementById('busca');\n  if (!busca) return;\n  const cards = [...document.querySelectorAll('#grid .card')];\n  const promo = document.getElementById('promo');\n  let filtro = 'todas';\n  function aplicar() {\n    const q = busca.value.trim().toLowerCase();\n    let vis = 0;\n    cards.forEach(c => {\n      const ok = (!q || c.dataset.nome.includes(q)) &&\n        (filtro === 'todas' || (filtro === 'fav' ? c.dataset.fav === '1' : c.dataset.status === filtro));\n      c.hidden = !ok; if (ok) vis++;\n    });\n    if (promo) promo.hidden = !(filtro === 'todas' && !q);\n    document.getElementById('semres').hidden = vis > 0;\n  }\n  busca.addEventListener('input', aplicar);\n  document.querySelectorAll('#filtros .chip').forEach(b => b.addEventListener('click', () => {\n    document.querySelectorAll('#filtros .chip').forEach(x => x.classList.remove('on'));\n    b.classList.add('on'); filtro = b.dataset.f; aplicar();\n  }));\n})();\n</script>\n{% endblock %}\n",
  "portal/login.html": "{% extends \"portal/base.html\" %}\n{% block title %}Entrar · Portal Grupo Capuzzo{% endblock %}\n{% block body_class %}page-login{% endblock %}\n{% block topbar %}{% endblock %}\n{% block content %}\n<div class=\"login\">\n  <section class=\"cover\">\n    <div class=\"grain\"></div>\n    <div class=\"cover-top\">\n      <img src=\"{{ url_for('static', filename='portal/logos/grupo_ring_light.png') }}\" alt=\"Grupo Capuzzo\">\n    </div>\n    <div class=\"cover-mid\">\n      <div class=\"eyebrow-line\">Portal corporativo</div>\n      <h1>Gestão integrada de <strong>todas as empresas</strong> do grupo.</h1>\n      <p class=\"lead\">Finanças, indicadores e rotinas de cada empresa do Grupo Capuzzo reunidos em um só lugar,\n        com a identidade de cada marca.</p>\n      <div class=\"cover-brands\">\n        {% for e in marcas %}\n          <span class=\"logo-circle sm\"><img src=\"{{ url_for('static', filename='portal/logos/' ~ e.logo) }}\" alt=\"{{ e.nome }}\"></span>\n        {% endfor %}\n        <span class=\"cb-txt\">{{ marcas|length }} empresas conectadas</span>\n      </div>\n    </div>\n    <div class=\"cover-foot\"><span>© {{ ano }} Grupo Capuzzo · Grupo Empresarial</span><span>Acesso restrito</span></div>\n  </section>\n\n  <section class=\"login-side\">\n    <form class=\"login-box\" method=\"post\" autocomplete=\"on\">\n      <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n      <div class=\"eyebrow\">Bem-vindo</div>\n      <h2>Acesse sua conta</h2>\n      <p class=\"sub\">Entre com o e-mail e a senha cadastrados.</p>\n\n      <label class=\"lbl\">Tipo de acesso</label>\n      <div class=\"seg\">\n        <input type=\"radio\" id=\"ac-admin\" name=\"acesso\" value=\"admin\" {% if acesso == 'admin' %}checked{% endif %}>\n        <label for=\"ac-admin\">Administrador</label>\n        <input type=\"radio\" id=\"ac-user\" name=\"acesso\" value=\"usuario\" {% if acesso != 'admin' %}checked{% endif %}>\n        <label for=\"ac-user\">Usuário</label>\n      </div>\n\n      <label class=\"lbl\" for=\"email\">E-mail</label>\n      <input class=\"inp\" id=\"email\" name=\"email\" type=\"email\" value=\"{{ email }}\" placeholder=\"nome@grupocapuzzo.com\" required autofocus>\n\n      <label class=\"lbl\" for=\"senha\">Senha</label>\n      <div class=\"pw\">\n        <input class=\"inp\" id=\"senha\" name=\"senha\" type=\"password\" placeholder=\"Sua senha\" required>\n        <button type=\"button\" class=\"pw-eye\" aria-label=\"Mostrar senha\"\n          onclick=\"const i=document.getElementById('senha');i.type=i.type==='password'?'text':'password'\">{{ ic('visibility') }}</button>\n      </div>\n\n      {% if senha_alterada %}<p role=\"status\">Senha alterada com sucesso.</p>{% endif %}\n      {% if erro %}<div class=\"alert\">{{ ic('error') }}{{ erro }}</div>{% endif %}\n\n      <button class=\"btn-gold\" type=\"submit\">Entrar</button>\n      <div class=\"login-help\"><a href=\"/forgot-password\">Esqueci minha senha</a></div>\n      <div class=\"login-secure\">{{ ic('lock') }} Conexão protegida · senhas armazenadas com criptografia</div>\n    </form>\n  </section>\n</div>\n{% endblock %}\n",
  "portal/minha_senha.html": "{% extends \"portal/base.html\" %}\n{% block title %}Alterar senha · Portal Grupo Capuzzo{% endblock %}\n{% block content %}\n<section class=\"page-title\"><div class=\"eyebrow-line\">Minha conta</div><h1>Alterar senha</h1></section>\n<form class=\"box narrow\" method=\"post\">\n  <input type=\"hidden\" name=\"_csrf\" value=\"{{ csrf_token() }}\">\n  <label class=\"lbl\">Senha atual</label><input class=\"inp\" type=\"password\" name=\"atual\" required>\n  <label class=\"lbl\">Nova senha</label><input class=\"inp\" type=\"password\" name=\"nova\" required minlength=\"8\">\n  <p class=\"hint\">Mínimo de 8 caracteres, com letras e números.</p>\n  <label class=\"lbl\">Confirmar nova senha</label><input class=\"inp\" type=\"password\" name=\"conf\" required>\n  <div class=\"row-btns\"><a class=\"btn-pill outline\" href=\"{{ url_for('portal_grupo') }}\">Cancelar</a>\n    <button class=\"btn-pill\" type=\"submit\">Salvar nova senha</button></div>\n</form>\n{% endblock %}\n",
  "portal/modulo.html": "{% extends \"portal/base.html\" %}\n{% block title %}{{ modulo.nome }} · {{ empresa.nome }}{% endblock %}\n{% block brand %}\n  <span class=\"logo-circle xs\"><img src=\"{{ url_for('static', filename='portal/logos/' ~ empresa.logo) }}\" alt=\"\"></span>\n  <span class=\"tb-name\"><b>{{ empresa.nome }}</b><small>Grupo Capuzzo</small></span>\n{% endblock %}\n{% block tb_links %}\n  <a class=\"tb-btn\" href=\"{{ url_for('portal_empresa', slug=empresa.slug) }}\">{{ ic('grid_view') }}<span class=\"lbl\">Módulos</span></a>\n  <a class=\"tb-btn\" href=\"{{ url_for('portal_grupo') }}\">{{ ic('apps') }}<span class=\"lbl\">Empresas</span></a>\n  {% include \"operacao/_barra_empresa.html\" ignore missing %}\n{% endblock %}\n{% block content %}\n<div class=\"mod-layout\">\n  <aside class=\"side\">\n    <div class=\"side-title\">Módulos</div>\n    {% for m in modulos %}\n      <a class=\"side-link {{ 'on' if m.id == modulo.id }}\" href=\"{{ url_for('portal_modulo', slug=empresa.slug, modulo_id=m.id) }}\">\n        {{ ic(m.icone) }}{{ m.nome }}</a>\n    {% endfor %}\n    <div class=\"side-sep\"></div>\n    <a class=\"side-link\" href=\"{{ url_for('portal_empresa', slug=empresa.slug) }}\">{{ ic('arrow_back') }}Voltar aos módulos</a>\n  </aside>\n  <section class=\"mod-main\">\n    <div class=\"banner\">\n      <div class=\"txt\"><small>{{ empresa.nome }}</small><h1>{{ modulo.nome }}</h1><p>{{ modulo.desc }}</p></div>\n    </div>\n    <div class=\"empty\">\n      <div class=\"empty-ic\">{{ ic(modulo.icone) }}</div>\n      <h3>Módulo em construção</h3>\n      <p>As informações de {{ modulo.nome|lower }} da {{ empresa.nome }} aparecerão aqui assim que o módulo for publicado.</p>\n    </div>\n  </section>\n</div>\n{% endblock %}\n",
  "titulos_privados.html": "{% extends \"base.html\" %}\n{% block title %}Títulos Privados — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n\n<div class=\"page-header\">\n  <div class=\"page-header-icon\">📜</div>\n  <div class=\"page-header-title\">Títulos Privados</div>\n  <div class=\"page-header-sub\">Controle de empréstimos privados a clientes — módulo isolado dos condomínios.</div>\n</div>\n\n<!-- KPIs -->\n<div class=\"metrics-grid\" style=\"grid-template-columns: repeat(4,1fr);margin-bottom:16px;\">\n  <div class=\"metric-card\">\n    <div class=\"metric-value\">{{ formatar_moeda(cards.total_original) }}</div>\n    <div class=\"metric-label\">Total Emprestado (Original)</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#d4af37;\">{{ formatar_moeda(cards.saldo_atualizado) }}</div>\n    <div class=\"metric-label\">Saldo Atualizado em Aberto</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#f87171;\">{{ formatar_moeda(cards.total_atraso) }}</div>\n    <div class=\"metric-label\">Total em Atraso</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#f0ad4e;\">{{ formatar_moeda(cards.juros_acumulados) }}</div>\n    <div class=\"metric-label\">Juros Acumulados</div>\n  </div>\n</div>\n\n<div class=\"metrics-grid\" style=\"grid-template-columns: repeat(4,1fr);margin-bottom:28px;\">\n  <div class=\"metric-card\">\n    <div class=\"metric-value\">{{ cards.clientes_ativos }}</div>\n    <div class=\"metric-label\">Clientes Ativos</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#4ade80;\">{{ cards.emprestimos_ativos }}</div>\n    <div class=\"metric-label\">Empréstimos Ativos</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#f87171;\">{{ cards.emprestimos_atraso }}</div>\n    <div class=\"metric-label\">Empréstimos em Atraso</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\">{{ cards.proximos_vencimentos }}</div>\n    <div class=\"metric-label\">Próximos Vencimentos</div>\n  </div>\n</div>\n\n<div class=\"page-actions\" style=\"margin-bottom:24px;justify-content:flex-start;\">\n  <a href=\"{{ url_for('titulos_privados_clientes_novo') }}\" class=\"btn btn-secondary\">+ Novo Cliente de Títulos</a>\n  <a href=\"{{ url_for('titulos_privados_emprestimos_novo') }}\" class=\"btn btn-primary\">+ Novo Empréstimo</a>\n  <a href=\"{{ url_for('titulos_privados_calculadora_price') }}\" class=\"btn btn-secondary\">🧮 Calculadora Price</a>\n</div>\n\n<!-- Empréstimos em atraso -->\n<div class=\"section-label\">⏰ &nbsp;Empréstimos em Atraso</div>\n{% if emprestimos_em_atraso %}\n<div class=\"table-wrap\" style=\"margin-bottom:28px;\">\n  <table>\n    <thead>\n      <tr>\n        <th>Cliente</th><th>Empréstimo</th><th>Dias em Atraso</th>\n        <th style=\"text-align:right;\">Saldo Atualizado</th><th style=\"text-align:right;\">Ações</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for l in emprestimos_em_atraso %}\n      <tr>\n        <td>{{ l.client_name }}</td>\n        <td class=\"text-mono\">{{ l.loan_number or ('#' ~ l.id) }}</td>\n        <td><span class=\"badge badge-inactive\">{{ l.calc.days_overdue }} dia(s)</span></td>\n        <td style=\"text-align:right;font-weight:600;color:#f87171;\">{{ formatar_moeda(l.calc.updated_amount) }}</td>\n        <td style=\"text-align:right;\">\n          <a href=\"{{ url_for('titulos_privados_emprestimo_detalhe', loan_id=l.id) }}\" class=\"btn btn-secondary btn-sm\">Ver</a>\n        </td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n{% else %}\n<div class=\"empty-state\" style=\"margin-bottom:28px;\">\n  <div class=\"empty-state-icon\">✅</div>\n  <div class=\"empty-state-title\">Nenhum empréstimo em atraso</div>\n  <div class=\"empty-state-sub\">Todos os empréstimos ativos estão dentro do prazo.</div>\n</div>\n{% endif %}\n\n<!-- Próximos vencimentos -->\n<div class=\"section-label\">📅 &nbsp;Próximos Vencimentos</div>\n{% if proximos_vencimentos %}\n<div class=\"table-wrap\" style=\"margin-bottom:28px;\">\n  <table>\n    <thead>\n      <tr>\n        <th>Cliente</th><th>Empréstimo</th><th>Data Base</th>\n        <th style=\"text-align:right;\">Saldo Atual</th><th style=\"text-align:right;\">Ações</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for l in proximos_vencimentos %}\n      <tr>\n        <td>{{ l.client_name }}</td>\n        <td class=\"text-mono\">{{ l.loan_number or ('#' ~ l.id) }}</td>\n        <td class=\"text-dim\">{{ formatar_data(l.calc.base_date) }}</td>\n        <td style=\"text-align:right;font-weight:600;\">{{ formatar_moeda(l.calc.updated_amount) }}</td>\n        <td style=\"text-align:right;\">\n          <a href=\"{{ url_for('titulos_privados_emprestimo_detalhe', loan_id=l.id) }}\" class=\"btn btn-secondary btn-sm\">Ver</a>\n        </td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n{% else %}\n<div class=\"empty-state\" style=\"margin-bottom:28px;\">\n  <div class=\"empty-state-icon\">📅</div>\n  <div class=\"empty-state-title\">Nenhum vencimento futuro cadastrado</div>\n</div>\n{% endif %}\n\n<!-- Maiores saldos devedores -->\n<div class=\"section-label\">📈 &nbsp;Maiores Saldos Devedores</div>\n{% if maiores_saldos %}\n<div class=\"table-wrap\" style=\"margin-bottom:28px;\">\n  <table>\n    <thead>\n      <tr>\n        <th>Cliente</th><th>Empréstimo</th><th style=\"text-align:right;\">Saldo Atualizado</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for l in maiores_saldos %}\n      <tr>\n        <td>{{ l.client_name }}</td>\n        <td class=\"text-mono\">{{ l.loan_number or ('#' ~ l.id) }}</td>\n        <td style=\"text-align:right;font-weight:600;color:#d4af37;\">{{ formatar_moeda(l.calc.updated_amount) }}</td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n{% else %}\n<div class=\"empty-state\" style=\"margin-bottom:28px;\">\n  <div class=\"empty-state-icon\">📈</div>\n  <div class=\"empty-state-title\">Nenhum empréstimo ativo</div>\n</div>\n{% endif %}\n\n<!-- Clientes com prorrogação ativa -->\n<div class=\"section-label\">⏳ &nbsp;Clientes com Prorrogação Ativa</div>\n{% if clientes_prorrogacao_ativa %}\n<div class=\"table-wrap\">\n  <table>\n    <thead>\n      <tr><th>Cliente</th><th>Empréstimo</th><th>Coberto até</th></tr>\n    </thead>\n    <tbody>\n      {% for l in clientes_prorrogacao_ativa %}\n      <tr>\n        <td>{{ l.client_name }}</td>\n        <td class=\"text-mono\">{{ l.loan_number or ('#' ~ l.id) }}</td>\n        <td class=\"text-dim\">{{ formatar_data(l.covered_until) }}</td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n{% else %}\n<div class=\"empty-state\">\n  <div class=\"empty-state-icon\">⏳</div>\n  <div class=\"empty-state-title\">Nenhuma prorrogação ativa no momento</div>\n</div>\n{% endif %}\n\n{% endblock %}\n",
  "titulos_privados_amortizacao_form.html": "{% extends \"base.html\" %}\n{% block title %}Registrar Amortização — Títulos Privados{% endblock %}\n\n{% block content %}\n\n<a href=\"{{ url_for('titulos_privados_emprestimo_detalhe', loan_id=loan.id) }}\" class=\"back-link\">← Voltar para o Empréstimo</a>\n\n<div class=\"page-header\">\n  <div class=\"page-header-icon\">📉</div>\n  <div class=\"page-header-title\">Registrar Amortização</div>\n  <div class=\"page-header-sub\">{{ loan.client_name }} — Empréstimo {{ loan.loan_number or ('#' ~ loan.id) }}</div>\n</div>\n\n{% if is_price_like %}\n{# ══════════════════════════════════════════════════════════════════\n   OPÇÃO 1 — Quitar Parcela Antecipada (calculadora \"quanto fica hoje\")\n   ══════════════════════════════════════════════════════════════════ #}\n<div class=\"card-gold\" style=\"margin-bottom:16px;\">\n  <div class=\"form-section-title\" style=\"margin-bottom:6px;\">💰 Quitar Parcela Antecipada</div>\n  <div class=\"note-box\" style=\"margin-bottom:14px;\">\n    ℹ️ Use aqui quando o cliente perguntar \"quanto fica para quitar a parcela do mês que vem, se eu pagar hoje?\".\n    O sistema desconta os juros que ainda não venceram (valor presente). Parcelas já vencidas usam o valor\n    atualizado por atraso, sem desconto.\n  </div>\n\n  {% if not parcelas_abertas %}\n  <div class=\"note-box\" style=\"color:#f87171;border-color:rgba(239,68,68,0.25);\">\n    ⚠️ Não há parcelas em aberto neste empréstimo.\n  </div>\n  {% else %}\n  <form method=\"post\" id=\"form-quitacao-antecipada\">\n    <input type=\"hidden\" name=\"ui_tipo\" value=\"quitar_parcela_antecipada\">\n    <div class=\"form-row\">\n      <div class=\"form-group\">\n        <label>Data de Pagamento *</label>\n        <input type=\"date\" name=\"payment_date\" id=\"early-payment-date\" class=\"form-control\" required\n               value=\"{{ hoje_iso }}\">\n      </div>\n      <div class=\"form-group\">\n        <label>Parcela que Deseja Quitar *</label>\n        <select name=\"installment_id\" id=\"early-installment-id\" class=\"form-control\" required>\n          <option value=\"\">Selecione…</option>\n          {% for p in parcelas_abertas %}\n          <option value=\"{{ p.id }}\">\n            Parcela {{ p.installment_number }} — venc. {{ formatar_data(p.due_date) }} —\n            valor original {{ formatar_moeda(p.original_amount) }}\n          </option>\n          {% endfor %}\n        </select>\n      </div>\n    </div>\n\n    <div id=\"qa-resultado\" style=\"display:none;\">\n      <div class=\"detail-grid\" style=\"margin-top:6px;\">\n        <div>\n          <div class=\"detail-item-label\">Vencimento da Parcela</div>\n          <div class=\"detail-item-value\" id=\"qa-vencimento\">—</div>\n        </div>\n        <div>\n          <div class=\"detail-item-label\">Dias de Antecipação</div>\n          <div class=\"detail-item-value\" id=\"qa-dias\">—</div>\n        </div>\n        <div>\n          <div class=\"detail-item-label\">Desconto por Antecipação</div>\n          <div class=\"detail-item-value\" id=\"qa-desconto\" style=\"color:#4ade80;font-weight:700;\">—</div>\n        </div>\n      </div>\n      <div class=\"note-box\" style=\"margin-top:12px;text-align:center;\">\n        <div style=\"font-size:12px;color:#888;margin-bottom:4px;\">Valor para quitar esta parcela hoje</div>\n        <div style=\"font-size:22px;font-weight:700;color:#d4af37;\" id=\"qa-valor-final\">—</div>\n      </div>\n    </div>\n    <div id=\"qa-erro\" class=\"note-box\" style=\"display:none;color:#f87171;border-color:rgba(239,68,68,0.25);margin-top:12px;\"></div>\n    <div id=\"qa-carregando\" class=\"text-dim\" style=\"display:none;margin-top:8px;font-size:12px;\">Calculando…</div>\n\n    <div class=\"page-actions\">\n      <button type=\"submit\" class=\"btn btn-primary\" id=\"btn-quitar-antecipada\" disabled>\n        ✓ Registrar Quitação Antecipada\n      </button>\n    </div>\n  </form>\n  {% endif %}\n</div>\n{% endif %}\n\n{# ══════════════════════════════════════════════════════════════════\n   OPÇÃO 2 — Amortização Avulsa (valor livre)\n   ══════════════════════════════════════════════════════════════════ #}\n<div class=\"card-gold\">\n  <div class=\"form-section-title\" style=\"margin-bottom:6px;\">📉 Amortização Avulsa</div>\n  {% if is_price_like %}\n  <div class=\"note-box\" style=\"margin-bottom:14px;\">\n    ℹ️ Use quando o cliente quiser pagar um valor qualquer (não necessariamente o valor exato de antecipação de\n    uma parcela) — o sistema aplica esse valor na parcela escolhida, nas próximas parcelas em sequência, ou\n    liquida o empréstimo inteiro.\n  </div>\n  {% endif %}\n\n  {% if calc_atual %}\n  <div class=\"detail-grid\" style=\"margin-bottom:14px;\">\n    <div>\n      <div class=\"detail-item-label\">Saldo Atualizado Antes</div>\n      <div class=\"detail-item-value\" id=\"saldo-antes\" style=\"font-weight:700;\">{{ formatar_moeda(calc_atual.updated_amount) }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Valor Aplicado (digite ao lado)</div>\n      <div class=\"detail-item-value\" id=\"valor-preview\">R$ 0,00</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Saldo Estimado Depois</div>\n      <div class=\"detail-item-value\" id=\"saldo-depois\" style=\"color:#d4af37;font-weight:700;\">{{ formatar_moeda(calc_atual.updated_amount) }}</div>\n    </div>\n  </div>\n  <div class=\"note-box\" id=\"preview-parcelas\" style=\"margin-bottom:14px;display:none;\"></div>\n  {% endif %}\n\n  <form method=\"post\" id=\"form-amortizacao\">\n\n    {% if is_price_like %}\n    <div class=\"form-section\">\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label>Tipo *</label>\n          <select name=\"ui_tipo\" id=\"ui_tipo\" class=\"form-control\" required onchange=\"atualizarTipoPrice()\">\n            <option value=\"parcela_especifica\">Antecipar Parcela Específica (valor livre)</option>\n            <option value=\"proximas_parcelas\">Aplicar nas Próximas Parcelas (em sequência)</option>\n            <option value=\"liquidacao_total\">Liquidação Total do Empréstimo</option>\n            <option value=\"reduzir_prazo\" disabled>Amortizar Principal — Reduzir Prazo (em breve)</option>\n            <option value=\"reduzir_parcela\" disabled>Amortizar Principal — Reduzir Parcela (em breve)</option>\n          </select>\n        </div>\n        <div class=\"form-group\" id=\"grupo-parcela-alvo\">\n          <label>Parcela Alvo *</label>\n          <select name=\"installment_id\" id=\"installment_id\" class=\"form-control\">\n            <option value=\"\">Selecione…</option>\n            {% for p in parcelas_abertas %}\n            <option value=\"{{ p.id }}\" data-saldo=\"{{ p.updated_amount }}\">\n              Parcela {{ p.installment_number }} — venc. {{ formatar_data(p.due_date) }} —\n              valor {{ formatar_moeda(p.original_amount) }} — saldo atualizado {{ formatar_moeda(p.updated_amount) }} —\n              status {% if p.visual_status == 'overdue' %}Atrasada{% elif p.visual_status == 'partial' %}Parcial{% elif p.visual_status == 'extended' %}Prorrogada{% else %}Aberta{% endif %}\n            </option>\n            {% endfor %}\n          </select>\n        </div>\n      </div>\n      <div class=\"note-box\" id=\"aviso-proximas\" style=\"display:none;\">\n        ℹ️ O valor será aplicado à primeira parcela em aberto (por vencimento); se sobrar, passa para a\n        próxima, e assim por diante, até acabar o valor ou as parcelas em aberto.\n      </div>\n      <div class=\"note-box\" id=\"aviso-liquidacao\" style=\"display:none;\">\n        ℹ️ A liquidação total exige valor igual ou maior que o saldo atualizado total do empréstimo\n        ({{ formatar_moeda(calc_atual.updated_amount) if calc_atual else '—' }}). Todas as parcelas em\n        aberto serão marcadas como pagas e o empréstimo passa para \"Quitado\".\n      </div>\n      <div class=\"note-box\" id=\"aviso-fase2\" style=\"display:none;color:#f0ad4e;border-color:rgba(240,173,78,0.25);\">\n        ⚠️ Esta opção recalcula o cronograma futuro e ainda não está disponível nesta versão —\n        selecione outro tipo para continuar.\n      </div>\n      {% if not parcelas_abertas %}\n      <div class=\"note-box\" style=\"color:#f87171;border-color:rgba(239,68,68,0.25);\">\n        ⚠️ Não há parcelas em aberto neste empréstimo.\n      </div>\n      {% endif %}\n    </div>\n    {% else %}\n    <div class=\"form-section\">\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label>Tipo de Amortização *</label>\n          <select name=\"amortization_type\" class=\"form-control\" required>\n            <option value=\"antecipacao_parcela\">Antecipação de Parcela</option>\n            <option value=\"reducao_saldo\" selected>Redução de Saldo</option>\n            <option value=\"liquidacao_parcial\">Liquidação Parcial</option>\n            <option value=\"liquidacao_total\">Liquidação Total</option>\n          </select>\n        </div>\n        <div class=\"form-group\">\n          <label>Aplicar Em *</label>\n          <select name=\"applied_to\" class=\"form-control\" required>\n            <option value=\"principal\" selected>Principal</option>\n            <option value=\"interest\">Juros</option>\n            <option value=\"mixed\">Misto</option>\n          </select>\n        </div>\n      </div>\n    </div>\n    {% endif %}\n\n    <div class=\"form-section\">\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label>Valor Amortizado (R$) *</label>\n          <input type=\"text\" name=\"amount\" id=\"input-amount\" class=\"form-control\" required\n                 placeholder=\"5.000,00\" data-mask=\"currency\" oninput=\"atualizarPreview()\">\n        </div>\n        <div class=\"form-group\">\n          <label>Data do Pagamento *</label>\n          <input type=\"date\" name=\"payment_date\" class=\"form-control\" required value=\"{{ hoje_iso }}\">\n        </div>\n      </div>\n      <div class=\"form-group\">\n        <label>Observações</label>\n        <textarea name=\"notes\" class=\"form-control\" rows=\"2\" placeholder=\"Opcional\"></textarea>\n      </div>\n    </div>\n\n    <div class=\"page-actions\">\n      <a href=\"{{ url_for('titulos_privados_emprestimo_detalhe', loan_id=loan.id) }}\" class=\"btn btn-secondary\">Cancelar</a>\n      <button type=\"submit\" class=\"btn btn-primary\" id=\"btn-salvar-amortizacao\">✓ Registrar Amortização Avulsa</button>\n    </div>\n  </form>\n</div>\n\n{% endblock %}\n\n{% block scripts %}\n<script>\nvar SALDO_ATUAL = {{ (calc_atual.updated_amount if calc_atual else 0) | tojson }};\nvar IS_PRICE_LIKE = {{ (is_price_like | default(false)) | tojson }};\nvar PARCELAS_ABERTAS = {{ (parcelas_abertas | default([])) | tojson }};\nvar PREVIEW_URL = {{ (url_for('titulos_privados_amortizacao_preview_parcela', loan_id=loan.id) if is_price_like else '') | tojson }};\n\nfunction parseValorBR(texto) {\n  if (!texto) return 0;\n  var limpo = texto.replace(/[^0-9,.-]/g, '').replace(/\\./g, '').replace(',', '.');\n  var v = parseFloat(limpo);\n  return isNaN(v) ? 0 : v;\n}\n\nfunction formatarMoedaJS(v) {\n  return 'R$ ' + v.toLocaleString('pt-BR', {minimumFractionDigits: 2, maximumFractionDigits: 2});\n}\n\nfunction formatarDataJS(iso) {\n  if (!iso) return '—';\n  var partes = iso.split('-');\n  return partes.length === 3 ? (partes[2] + '/' + partes[1] + '/' + partes[0]) : iso;\n}\n\n/* ── Card 1: Quitar Parcela Antecipada — preview via AJAX ── */\nfunction atualizarQuitacaoAntecipada() {\n  var instEl = document.getElementById('early-installment-id');\n  var dataEl = document.getElementById('early-payment-date');\n  if (!instEl || !dataEl) return;\n  var instId = instEl.value;\n  var dataPag = dataEl.value;\n  var resultadoEl = document.getElementById('qa-resultado');\n  var erroEl = document.getElementById('qa-erro');\n  var carregandoEl = document.getElementById('qa-carregando');\n  var btn = document.getElementById('btn-quitar-antecipada');\n\n  resultadoEl.style.display = 'none';\n  erroEl.style.display = 'none';\n  btn.disabled = true;\n\n  if (!instId || !dataPag) return;\n\n  carregandoEl.style.display = 'block';\n  fetch(PREVIEW_URL + '?installment_id=' + encodeURIComponent(instId) + '&payment_date=' + encodeURIComponent(dataPag))\n    .then(function (resp) { return resp.json(); })\n    .then(function (data) {\n      carregandoEl.style.display = 'none';\n      if (!data.success) {\n        erroEl.textContent = data.error || 'Não foi possível calcular.';\n        erroEl.style.display = 'block';\n        return;\n      }\n      if (data.status === 'paid') {\n        erroEl.textContent = 'Esta parcela já está paga.';\n        erroEl.style.display = 'block';\n        return;\n      }\n      document.getElementById('qa-vencimento').textContent = formatarDataJS(data.due_date);\n      document.getElementById('qa-dias').textContent =\n        data.days_until_due > 0 ? (data.days_until_due + ' dia(s) antes do vencimento')\n        : (data.days_until_due === 0 ? 'Vence hoje' : 'Já vencida (' + Math.abs(data.days_until_due) + ' dia(s) de atraso)');\n      document.getElementById('qa-desconto').textContent = formatarMoedaJS(data.discount_amount);\n      document.getElementById('qa-valor-final').textContent = formatarMoedaJS(data.early_settlement_amount);\n      resultadoEl.style.display = 'block';\n      btn.disabled = false;\n    })\n    .catch(function () {\n      carregandoEl.style.display = 'none';\n      erroEl.textContent = 'Erro ao calcular a quitação antecipada.';\n      erroEl.style.display = 'block';\n    });\n}\n\nif (document.getElementById('early-installment-id')) {\n  document.getElementById('early-installment-id').addEventListener('change', atualizarQuitacaoAntecipada);\n  document.getElementById('early-payment-date').addEventListener('change', atualizarQuitacaoAntecipada);\n}\n\n/* ── Card 2: Amortização Avulsa ── */\nfunction atualizarTipoPrice() {\n  if (!IS_PRICE_LIKE) return;\n  var tipo = document.getElementById('ui_tipo').value;\n  var grupoParcelaAlvo = document.getElementById('grupo-parcela-alvo');\n  var inputParcela = document.getElementById('installment_id');\n  var avisoProximas = document.getElementById('aviso-proximas');\n  var avisoLiquidacao = document.getElementById('aviso-liquidacao');\n  var avisoFase2 = document.getElementById('aviso-fase2');\n  var btnSalvar = document.getElementById('btn-salvar-amortizacao');\n\n  grupoParcelaAlvo.style.display = 'none';\n  inputParcela.required = false;\n  avisoProximas.style.display = 'none';\n  avisoLiquidacao.style.display = 'none';\n  avisoFase2.style.display = 'none';\n  btnSalvar.disabled = false;\n\n  if (tipo === 'parcela_especifica') {\n    grupoParcelaAlvo.style.display = 'block';\n    inputParcela.required = true;\n  } else if (tipo === 'proximas_parcelas') {\n    avisoProximas.style.display = 'block';\n  } else if (tipo === 'liquidacao_total') {\n    avisoLiquidacao.style.display = 'block';\n  } else if (tipo === 'reduzir_prazo' || tipo === 'reduzir_parcela') {\n    avisoFase2.style.display = 'block';\n    btnSalvar.disabled = true;\n  }\n  atualizarPreview();\n}\n\nfunction atualizarPreview() {\n  var valor = parseValorBR(document.getElementById('input-amount').value);\n  var previewEl = document.getElementById('valor-preview');\n  var depoisEl = document.getElementById('saldo-depois');\n  var previewParcelasEl = document.getElementById('preview-parcelas');\n  if (!previewEl || !depoisEl) return;\n  previewEl.textContent = formatarMoedaJS(valor);\n\n  if (IS_PRICE_LIKE) {\n    var tipo = document.getElementById('ui_tipo') ? document.getElementById('ui_tipo').value : 'parcela_especifica';\n\n    if (tipo === 'parcela_especifica') {\n      var sel = document.getElementById('installment_id');\n      var opt = sel.options[sel.selectedIndex];\n      var saldoParcela = opt ? parseFloat(opt.getAttribute('data-saldo') || '0') : 0;\n      var restante = Math.max(saldoParcela - valor, 0);\n      if (previewParcelasEl) {\n        previewParcelasEl.style.display = opt && opt.value ? 'block' : 'none';\n        previewParcelasEl.textContent = opt && opt.value\n          ? 'Parcela selecionada: saldo atualizado ' + formatarMoedaJS(saldoParcela) +\n            ' → depois do pagamento: ' + formatarMoedaJS(restante) +\n            (valor >= saldoParcela ? ' (fica PAGA)' : ' (fica PARCIAL)')\n          : '';\n      }\n      var depoisTotal = SALDO_ATUAL - Math.min(valor, saldoParcela || valor);\n      depoisEl.textContent = formatarMoedaJS(depoisTotal < 0 ? 0 : depoisTotal);\n      depoisEl.style.color = depoisTotal < 0 ? '#f87171' : '#d4af37';\n      return;\n    }\n\n    if (tipo === 'proximas_parcelas') {\n      var restanteValor = valor;\n      var linhas = [];\n      for (var idx = 0; idx < PARCELAS_ABERTAS.length && restanteValor > 0; idx++) {\n        var p = PARCELAS_ABERTAS[idx];\n        var saldoP = p.updated_amount;\n        var consumido = Math.min(restanteValor, saldoP);\n        var ficaPago = consumido >= saldoP;\n        linhas.push('Parcela ' + p.installment_number + ': ' + formatarMoedaJS(consumido) +\n                     (ficaPago ? ' (fica PAGA)' : ' (fica PARCIAL)'));\n        restanteValor -= consumido;\n      }\n      if (previewParcelasEl) {\n        previewParcelasEl.style.display = linhas.length ? 'block' : 'none';\n        previewParcelasEl.textContent = linhas.length\n          ? 'Parcelas afetadas em sequência: ' + linhas.join(' | ') +\n            (restanteValor > 0 ? ' | Sobra não aplicada: ' + formatarMoedaJS(restanteValor) : '')\n          : '';\n      }\n      var depois2 = SALDO_ATUAL - (valor - restanteValor);\n      depoisEl.textContent = formatarMoedaJS(depois2 < 0 ? 0 : depois2);\n      depoisEl.style.color = depois2 < 0 ? '#f87171' : '#d4af37';\n      return;\n    }\n\n    if (tipo === 'liquidacao_total') {\n      if (previewParcelasEl) {\n        previewParcelasEl.style.display = 'block';\n        previewParcelasEl.textContent = valor >= SALDO_ATUAL\n          ? 'Cobre o saldo total — empréstimo ficará QUITADO.'\n          : 'Valor insuficiente para liquidação total (faltam ' + formatarMoedaJS(SALDO_ATUAL - valor) + ').';\n      }\n      depoisEl.textContent = formatarMoedaJS(valor >= SALDO_ATUAL ? 0 : SALDO_ATUAL);\n      depoisEl.style.color = valor >= SALDO_ATUAL ? '#d4af37' : '#f87171';\n      return;\n    }\n\n    if (previewParcelasEl) { previewParcelasEl.style.display = 'none'; }\n    depoisEl.textContent = formatarMoedaJS(SALDO_ATUAL);\n    return;\n  }\n\n  // Empréstimo bullet — projeção simples de sempre.\n  var depois = SALDO_ATUAL - valor;\n  depoisEl.textContent = formatarMoedaJS(depois < 0 ? 0 : depois);\n  depoisEl.style.color = depois < 0 ? '#f87171' : '#d4af37';\n}\n\nif (document.getElementById('ui_tipo')) {\n  document.getElementById('installment_id').addEventListener('change', atualizarPreview);\n  atualizarTipoPrice();\n}\n\ndocument.getElementById('form-amortizacao').addEventListener('submit', function (e) {\n  var valor = parseValorBR(document.getElementById('input-amount').value);\n  if (!IS_PRICE_LIKE && SALDO_ATUAL > 0 && valor > SALDO_ATUAL) {\n    if (!confirm('O valor amortizado (' + formatarMoedaJS(valor) + ') é MAIOR que o saldo total ' +\n                 'atualizado (' + formatarMoedaJS(SALDO_ATUAL) + '). Confirma mesmo assim?')) {\n      e.preventDefault();\n    }\n  }\n});\n</script>\n{% endblock %}\n",
  "titulos_privados_amortizacoes.html": "{% extends \"base.html\" %}\n{% block title %}Amortizações — Títulos Privados{% endblock %}\n\n{% block content %}\n\n<div class=\"page-header\">\n  <div class=\"page-header-icon\">📉</div>\n  <div class=\"page-header-title\">Amortizações</div>\n  <div class=\"page-header-sub\">Todas as amortizações/antecipações registradas nos empréstimos privados.</div>\n</div>\n\n{% if amortizacoes %}\n<div class=\"table-wrap\">\n  <table>\n    <thead>\n      <tr>\n        <th>Cliente</th><th>Empréstimo</th><th>Parcela</th><th>Data</th>\n        <th style=\"text-align:right;\">Valor</th><th>Tipo</th>\n        <th style=\"text-align:right;\">Desconto</th><th>Aplicado em</th><th style=\"text-align:right;\">Ações</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for a in amortizacoes %}\n      <tr>\n        <td>{{ a.client_name }}</td>\n        <td class=\"text-mono\">{{ a.loan_number or ('#' ~ a.loan_id) }}</td>\n        <td class=\"text-dim\">\n          {% if a.target_installment_number %}Parcela {{ a.target_installment_number }}\n          {% elif a.target_mode == 'proximas_parcelas' %}Próximas parcelas\n          {% elif a.target_mode == 'saldo_devedor' %}Saldo devedor\n          {% else %}—{% endif %}\n        </td>\n        <td class=\"text-dim\">{{ formatar_data(a.payment_date) }}</td>\n        <td style=\"text-align:right;font-weight:600;\">{{ formatar_moeda(a.amount) }}</td>\n        <td>\n          {% if a.price_action == 'quitar_parcela_antecipada' %}⚡ Quitação Antecipada de Parcela\n          {% else %}{{ {'antecipacao_parcela':'Antecipação de Parcela','reducao_saldo':'Redução de Saldo','liquidacao_parcial':'Liquidação Parcial','liquidacao_total':'Liquidação Total'}.get(a.amortization_type, a.amortization_type) }}\n          {% endif %}\n        </td>\n        <td style=\"text-align:right;\" class=\"text-dim\">\n          {% if a.price_action == 'quitar_parcela_antecipada' and a.amount_before is not none %}\n            {{ formatar_moeda(a.amount_before - a.amount) }}\n          {% else %}—{% endif %}\n        </td>\n        <td>{{ {'principal':'Principal','interest':'Juros','mixed':'Misto'}.get(a.applied_to, a.applied_to) }}</td>\n        <td style=\"text-align:right;\">\n          <a href=\"{{ url_for('titulos_privados_emprestimo_detalhe', loan_id=a.loan_id) }}\" class=\"btn btn-secondary btn-sm\">Ver Empréstimo</a>\n        </td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n<div class=\"text-dim\" style=\"font-size:12px;margin-top:10px;text-align:right;\">\n  {{ amortizacoes | length }} amortização(ões) encontrada(s)\n</div>\n{% else %}\n<div class=\"empty-state\">\n  <div class=\"empty-state-icon\">📉</div>\n  <div class=\"empty-state-title\">Nenhuma amortização registrada ainda</div>\n</div>\n{% endif %}\n\n{% endblock %}\n",
  "titulos_privados_calculadora_price.html": "{% extends \"base.html\" %}\n{% block title %}Calculadora Price — Títulos Privados{% endblock %}\n\n{% block content %}\n\n<div class=\"page-header\">\n  <div class=\"page-header-icon\">🧮</div>\n  <div class=\"page-header-title\">Calculadora Price</div>\n  <div class=\"page-header-sub\">Simulação de empréstimo pelo Sistema Price (parcelas fixas) — independente de qualquer empréstimo cadastrado.</div>\n</div>\n\n<div class=\"card-gold\" style=\"margin-bottom:24px;\">\n  <form method=\"post\">\n    <div class=\"form-row\">\n      <div class=\"form-group\">\n        <label>Valor Financiado (R$) *</label>\n        <input type=\"text\" name=\"principal\" value=\"{{ entrada.get('principal','') }}\"\n               class=\"form-control\" required placeholder=\"30.000,00\" data-mask=\"currency\">\n      </div>\n      <div class=\"form-group\">\n        <label>Taxa Mensal (%) *</label>\n        <input type=\"text\" name=\"monthly_rate\" value=\"{{ entrada.get('monthly_rate','') }}\"\n               class=\"form-control\" required placeholder=\"Ex: 3,5 ou 3,5%\">\n      </div>\n      <div class=\"form-group\">\n        <label>Quantidade de Parcelas *</label>\n        <input type=\"number\" name=\"installments\" min=\"1\" value=\"{{ entrada.get('installments','') }}\"\n               class=\"form-control\" required placeholder=\"12\">\n      </div>\n      <div class=\"form-group\">\n        <label>Data da Primeira Parcela *</label>\n        <input type=\"date\" name=\"first_due_date\" value=\"{{ entrada.get('first_due_date','') }}\"\n               class=\"form-control\" required>\n      </div>\n    </div>\n    <div class=\"page-actions\" style=\"justify-content:flex-start;\">\n      <button type=\"submit\" class=\"btn btn-primary\">🧮 Calcular</button>\n    </div>\n  </form>\n</div>\n\n{% if resultado %}\n<div class=\"metrics-grid\" style=\"grid-template-columns:repeat(3,1fr);margin-bottom:24px;\">\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#d4af37;\">{{ formatar_moeda(resultado.installment_amount) }}</div>\n    <div class=\"metric-label\">Valor da Parcela</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\">{{ formatar_moeda(resultado.total_paid) }}</div>\n    <div class=\"metric-label\">Total Pago</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#f0ad4e;\">{{ formatar_moeda(resultado.total_interest) }}</div>\n    <div class=\"metric-label\">Total de Juros</div>\n  </div>\n</div>\n\n<div class=\"page-actions\" style=\"justify-content:flex-start;margin-bottom:16px;\">\n  <button type=\"button\" class=\"btn btn-secondary\" onclick=\"copiarResultado()\">📋 Copiar Resultado</button>\n  <a class=\"btn btn-primary\"\n     href=\"{{ url_for('titulos_privados_emprestimos_novo',\n                       calculation_method='price',\n                       original_amount=resultado.principal,\n                       contracted_amount=resultado.total_paid,\n                       interest_rate_monthly=entrada.get('monthly_rate',''),\n                       installments_count=resultado.installments_count,\n                       first_due_date=resultado.first_due_date) }}\">\n    ➕ Gerar Empréstimo a partir desta Simulação\n  </a>\n</div>\n\n<div class=\"section-label\">📋 &nbsp;Tabela Price Completa</div>\n<div class=\"table-wrap\" id=\"tabela-price\">\n  <table>\n    <thead>\n      <tr>\n        <th>Parcela</th><th>Vencimento</th>\n        <th style=\"text-align:right;\">Saldo Inicial</th><th style=\"text-align:right;\">Juros</th>\n        <th style=\"text-align:right;\">Amortização</th><th style=\"text-align:right;\">Parcela</th>\n        <th style=\"text-align:right;\">Saldo Final</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for row in resultado.schedule %}\n      <tr>\n        <td>{{ row.installment_number }}</td>\n        <td class=\"text-dim\">{{ formatar_data(row.due_date) }}</td>\n        <td style=\"text-align:right;\">{{ formatar_moeda(row.opening_balance) }}</td>\n        <td style=\"text-align:right;\">{{ formatar_moeda(row.interest) }}</td>\n        <td style=\"text-align:right;\">{{ formatar_moeda(row.principal) }}</td>\n        <td style=\"text-align:right;font-weight:600;\">{{ formatar_moeda(row.installment_amount) }}</td>\n        <td style=\"text-align:right;\">{{ formatar_moeda(row.closing_balance) }}</td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n{% endif %}\n\n{% endblock %}\n\n{% block scripts %}\n<script>\nfunction copiarResultado() {\n  var tabela = document.getElementById('tabela-price');\n  if (!tabela) return;\n  var linhas = [['Parcela','Vencimento','Saldo Inicial','Juros','Amortização','Parcela','Saldo Final']];\n  tabela.querySelectorAll('tbody tr').forEach(function (tr) {\n    var cols = [];\n    tr.querySelectorAll('td').forEach(function (td) { cols.push(td.textContent.trim()); });\n    linhas.push(cols);\n  });\n  var texto = linhas.map(function (l) { return l.join('\\t'); }).join('\\n');\n  navigator.clipboard.writeText(texto).then(function () {\n    alert('Tabela Price copiada para a área de transferência.');\n  }).catch(function () {\n    alert('Não foi possível copiar automaticamente. Selecione a tabela manualmente.');\n  });\n}\n</script>\n{% endblock %}\n",
  "titulos_privados_cliente_detalhe.html": "{% extends \"base.html\" %}\n{% block title %}{{ cliente.name }} — Títulos Privados — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n\n<a href=\"{{ url_for('titulos_privados_clientes') }}\" class=\"back-link\">← Voltar para Clientes de Títulos</a>\n\n<div class=\"page-header\" style=\"display:flex;justify-content:space-between;align-items:flex-start;\">\n  <div>\n    <div class=\"page-header-title\">{{ cliente.name }}</div>\n    <div class=\"page-header-sub\" style=\"margin-top:6px;\">\n      {% if cliente.status == 'ativo' %}\n        <span class=\"badge badge-active\">● Ativo</span>\n      {% else %}\n        <span class=\"badge badge-inactive\">● Inativo</span>\n      {% endif %}\n      &nbsp;\n      {% if cliente.document %}<span class=\"text-mono text-dim\">{{ formatar_documento(cliente.document) }}</span>{% endif %}\n    </div>\n  </div>\n  <div style=\"display:flex;gap:8px;flex-shrink:0;flex-wrap:wrap;justify-content:flex-end;\">\n    <a href=\"{{ url_for('titulos_privados_cliente_editar', pcid=cliente.id) }}\" class=\"btn btn-secondary\">✏️ Editar</a>\n    {% if cliente.status == 'ativo' %}\n      <form method=\"post\" action=\"{{ url_for('titulos_privados_cliente_inativar', pcid=cliente.id) }}\" style=\"display:inline;\">\n        <button type=\"submit\" class=\"btn btn-danger\" data-confirm=\"Inativar o cliente {{ cliente.name }}?\">🔒 Inativar</button>\n      </form>\n    {% else %}\n      <form method=\"post\" action=\"{{ url_for('titulos_privados_cliente_reativar', pcid=cliente.id) }}\" style=\"display:inline;\">\n        <button type=\"submit\" class=\"btn btn-success\">🔓 Reativar</button>\n      </form>\n    {% endif %}\n  </div>\n</div>\n\n<!-- Dados do cliente -->\n<div class=\"card-gold\" style=\"margin-bottom:20px;\">\n  <div class=\"form-section-title\" style=\"margin-bottom:12px;\">Dados do Cliente</div>\n  <div class=\"detail-grid\">\n    <div>\n      <div class=\"detail-item-label\">Nome</div>\n      <div class=\"detail-item-value\">{{ cliente.name }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">CPF/CNPJ</div>\n      <div class=\"detail-item-value text-mono\">{{ formatar_documento(cliente.document) if cliente.document else '—' }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Telefone</div>\n      <div class=\"detail-item-value\">{{ cliente.phone or '—' }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">E-mail</div>\n      <div class=\"detail-item-value\">{{ cliente.email or '—' }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Chave PIX</div>\n      <div class=\"detail-item-value text-mono\">{{ cliente.pix_key or '—' }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Vinculado ao cadastro geral</div>\n      <div class=\"detail-item-value\">\n        {% if cliente.linked_client_id %}\n          <span class=\"badge badge-active\">🔗 Sim (cliente #{{ cliente.linked_client_id }})</span>\n        {% else %}\n          <span class=\"text-dim\">Não</span>\n        {% endif %}\n      </div>\n    </div>\n  </div>\n  {% if cliente.notes %}\n  <div style=\"margin-top:14px;\">\n    <div class=\"detail-item-label\">Observações</div>\n    <div class=\"detail-item-value text-dim\" style=\"margin-top:4px;\">{{ cliente.notes }}</div>\n  </div>\n  {% endif %}\n</div>\n\n<!-- Saldo total -->\n<div class=\"metrics-grid\" style=\"grid-template-columns:repeat(3,1fr);margin-bottom:24px;\">\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#d4af37;\">{{ formatar_moeda(saldo_total) }}</div>\n    <div class=\"metric-label\">Saldo Total Atualizado</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\">{{ loans_ativos | length }}</div>\n    <div class=\"metric-label\">Empréstimos Ativos</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#555;\">{{ loans_quitados | length }}</div>\n    <div class=\"metric-label\">Empréstimos Quitados</div>\n  </div>\n</div>\n\n<div style=\"margin-bottom:20px;\">\n  <a href=\"{{ url_for('titulos_privados_emprestimos_novo', private_client_id=cliente.id) }}\" class=\"btn btn-primary\">\n    + Novo Empréstimo para este Cliente\n  </a>\n</div>\n\n<!-- Empréstimos ativos -->\n<div class=\"section-label\">💰 &nbsp;Empréstimos Ativos ({{ loans_ativos | length }})</div>\n{% if loans_ativos %}\n<div class=\"table-wrap\" style=\"margin-bottom:24px;\">\n  <table>\n    <thead>\n      <tr>\n        <th>Empréstimo</th><th>Método</th><th>Dias em Atraso</th>\n        <th style=\"text-align:right;\">Saldo Atualizado</th><th>Status</th><th style=\"text-align:right;\">Ações</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for l in loans_ativos %}\n      <tr>\n        <td class=\"text-mono\">{{ l.loan_number or ('#' ~ l.id) }}</td>\n        <td>{{ {'bullet':'Pagamento Único','price':'Price','manual':'Manual'}.get(l.calculation_method, l.calculation_method) }}</td>\n        <td>\n          {% if l.calc and l.calc.days_overdue > 0 %}\n            <span class=\"badge badge-inactive\">{{ l.calc.days_overdue }} dia(s)</span>\n          {% else %}\n            <span class=\"badge badge-active\">Em dia</span>\n          {% endif %}\n        </td>\n        <td style=\"text-align:right;font-weight:600;\">{{ formatar_moeda(l.calc.updated_amount) if l.calc else '—' }}</td>\n        <td>\n          {% if l.status == 'active' %}<span class=\"badge badge-active\">Ativo</span>\n          {% elif l.status == 'overdue' %}<span class=\"badge badge-inactive\">Em Atraso</span>\n          {% else %}<span class=\"badge badge-pending\">{{ l.status }}</span>{% endif %}\n        </td>\n        <td style=\"text-align:right;\">\n          <a href=\"{{ url_for('titulos_privados_emprestimo_detalhe', loan_id=l.id) }}\" class=\"btn btn-secondary btn-sm\">Ver</a>\n        </td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n{% else %}\n<div class=\"empty-state\" style=\"margin-bottom:24px;\">\n  <div class=\"empty-state-icon\">💰</div>\n  <div class=\"empty-state-title\">Nenhum empréstimo ativo</div>\n</div>\n{% endif %}\n\n<!-- Empréstimos quitados -->\n<div class=\"section-label\">✅ &nbsp;Empréstimos Quitados ({{ loans_quitados | length }})</div>\n{% if loans_quitados %}\n<div class=\"table-wrap\">\n  <table>\n    <thead>\n      <tr><th>Empréstimo</th><th>Valor Contratado</th><th>Status</th><th style=\"text-align:right;\">Ações</th></tr>\n    </thead>\n    <tbody>\n      {% for l in loans_quitados %}\n      <tr>\n        <td class=\"text-mono\">{{ l.loan_number or ('#' ~ l.id) }}</td>\n        <td>{{ formatar_moeda(l.contracted_amount) }}</td>\n        <td><span class=\"badge badge-inactive\">{{ l.status }}</span></td>\n        <td style=\"text-align:right;\">\n          <a href=\"{{ url_for('titulos_privados_emprestimo_detalhe', loan_id=l.id) }}\" class=\"btn btn-secondary btn-sm\">Ver</a>\n        </td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n{% else %}\n<div class=\"empty-state\">\n  <div class=\"empty-state-icon\">✅</div>\n  <div class=\"empty-state-title\">Nenhum empréstimo quitado ainda</div>\n</div>\n{% endif %}\n\n{% endblock %}\n",
  "titulos_privados_cliente_form.html": "{% extends \"base.html\" %}\n{% block title %}{{ 'Novo Cliente de Títulos' if modo == 'novo' else 'Editar Cliente de Títulos' }} — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n\n<a href=\"{{ url_for('titulos_privados_clientes') }}\" class=\"back-link\">← Voltar para Clientes de Títulos</a>\n\n<div class=\"page-header\">\n  <div class=\"page-header-icon\">{{ '➕' if modo == 'novo' else '✏️' }}</div>\n  <div class=\"page-header-title\">{{ 'Novo Cliente de Títulos' if modo == 'novo' else 'Editar Cliente de Títulos' }}</div>\n  <div class=\"page-header-sub\">\n    Cadastro próprio do módulo — não altera o cadastro geral de clientes dos condomínios.\n  </div>\n</div>\n\n<div class=\"card-gold\">\n  <form method=\"post\">\n\n    <!-- Vincular cliente já existente -->\n    <div class=\"form-section\">\n      <div class=\"form-section-title\">Vincular Cliente Já Existente (opcional)</div>\n      <div class=\"note-box\" style=\"margin-bottom:12px;\">\n        ℹ️ Se este tomador já é cliente cadastrado nos condomínios, busque por nome, CPF/CNPJ,\n        telefone ou e-mail e vincule — sem duplicar o cadastro. Se não encontrar, cadastre os\n        dados abaixo normalmente (fica só neste módulo por enquanto).\n      </div>\n      <div class=\"form-row\">\n        <div class=\"form-group\" style=\"position:relative;\">\n          <label>Buscar cliente existente</label>\n          <input type=\"text\" id=\"busca-cliente-vinculo\" class=\"form-control\"\n                 placeholder=\"Digite nome, CPF/CNPJ, telefone ou e-mail…\" autocomplete=\"off\">\n          <div id=\"resultado-busca-vinculo\"\n               style=\"display:none;position:absolute;z-index:20;top:100%;left:0;right:0;\n                      background:#1a1a1a;border:1px solid rgba(212,175,55,.3);border-radius:8px;\n                      max-height:220px;overflow-y:auto;margin-top:4px;\"></div>\n        </div>\n      </div>\n      <div id=\"cliente-vinculado-info\" style=\"{{ 'display:none;' if not cliente.get('linked_client_id') }}margin-top:6px;\">\n        <span class=\"badge badge-active\">🔗 Vinculado a: <span id=\"cliente-vinculado-nome\"></span></span>\n        <button type=\"button\" class=\"btn btn-secondary btn-sm\" onclick=\"limparVinculo()\" style=\"margin-left:6px;\">Remover vínculo</button>\n      </div>\n      <input type=\"hidden\" name=\"linked_client_id\" id=\"linked_client_id\"\n             value=\"{{ cliente.get('linked_client_id','') or '' }}\">\n    </div>\n\n    <!-- Dados do cliente de títulos -->\n    <div class=\"form-section\">\n      <div class=\"form-section-title\">Dados do Cliente</div>\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label>Nome Completo *</label>\n          <input type=\"text\" name=\"name\" value=\"{{ cliente.get('name','') }}\"\n                 class=\"form-control\" required placeholder=\"Nome do tomador do empréstimo\">\n        </div>\n        <div class=\"form-group\">\n          <label>CPF/CNPJ</label>\n          <input type=\"text\" name=\"document\" value=\"{{ formatar_documento(cliente.get('document','')) if cliente.get('document') else '' }}\"\n                 class=\"form-control\" data-mask=\"cpfcnpj\"\n                 placeholder=\"000.000.000-00 ou 00.000.000/0000-00\">\n        </div>\n      </div>\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label>E-mail</label>\n          <input type=\"email\" name=\"email\" value=\"{{ cliente.get('email','') }}\"\n                 class=\"form-control\" placeholder=\"email@exemplo.com\">\n        </div>\n        <div class=\"form-group\">\n          <label>Telefone</label>\n          <input type=\"text\" name=\"phone\" value=\"{{ cliente.get('phone','') }}\"\n                 class=\"form-control\" data-mask=\"phone\" placeholder=\"(00) 00000-0000\">\n        </div>\n      </div>\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label>Chave PIX</label>\n          <input type=\"text\" name=\"pix_key\" value=\"{{ cliente.get('pix_key','') }}\"\n                 class=\"form-control\" placeholder=\"CPF, e-mail ou chave aleatória\">\n        </div>\n        <div class=\"form-group\">\n          <label>Status</label>\n          <select name=\"status\" class=\"form-control\" style=\"max-width:200px;\">\n            <option value=\"ativo\"   {{ 'selected' if cliente.get('status','ativo') == 'ativo' else '' }}>Ativo</option>\n            <option value=\"inativo\" {{ 'selected' if cliente.get('status') == 'inativo' else '' }}>Inativo</option>\n          </select>\n        </div>\n      </div>\n      <div class=\"form-group\">\n        <label>Observações</label>\n        <textarea name=\"notes\" class=\"form-control\" rows=\"3\"\n                  placeholder=\"Anotações internas (opcional)\">{{ cliente.get('notes','') }}</textarea>\n      </div>\n    </div>\n\n    <div class=\"page-actions\">\n      <a href=\"{{ url_for('titulos_privados_clientes') }}\" class=\"btn btn-secondary\">Cancelar</a>\n      <button type=\"submit\" class=\"btn btn-primary\">\n        {{ '✓ Cadastrar Cliente' if modo == 'novo' else '✓ Salvar Alterações' }}\n      </button>\n    </div>\n\n  </form>\n</div>\n\n{% endblock %}\n\n{% block scripts %}\n<script>\nvar buscaInput = document.getElementById('busca-cliente-vinculo');\nvar resultadoDiv = document.getElementById('resultado-busca-vinculo');\nvar linkedInput = document.getElementById('linked_client_id');\nvar infoDiv = document.getElementById('cliente-vinculado-info');\nvar nomeSpan = document.getElementById('cliente-vinculado-nome');\nvar buscaTimeout = null;\n\nif (buscaInput) {\n  buscaInput.addEventListener('input', function () {\n    var termo = this.value.trim();\n    clearTimeout(buscaTimeout);\n    if (termo.length < 2) {\n      resultadoDiv.style.display = 'none';\n      return;\n    }\n    buscaTimeout = setTimeout(function () {\n      fetch('{{ url_for(\"titulos_privados_clientes_buscar_vinculo\") }}?q=' + encodeURIComponent(termo))\n        .then(function (r) { return r.json(); })\n        .then(function (data) {\n          resultadoDiv.innerHTML = '';\n          if (!data.results || !data.results.length) {\n            resultadoDiv.innerHTML = '<div style=\"padding:10px;color:#888;font-size:13px;\">Nenhum cliente encontrado no cadastro geral.</div>';\n          } else {\n            data.results.forEach(function (c) {\n              var item = document.createElement('div');\n              item.style.cssText = 'padding:10px 14px;cursor:pointer;border-bottom:1px solid rgba(255,255,255,.05);font-size:13px;';\n              item.innerHTML = '<strong style=\"color:#F5F5F5;\">' + c.full_name + '</strong><br>' +\n                                '<span style=\"color:#888;font-size:11px;\">' + (c.cpf || '') +\n                                (c.phone ? ' · ' + c.phone : '') + (c.email ? ' · ' + c.email : '') + '</span>';\n              item.onclick = function () {\n                linkedInput.value = c.id;\n                nomeSpan.textContent = c.full_name;\n                infoDiv.style.display = 'block';\n                resultadoDiv.style.display = 'none';\n                buscaInput.value = '';\n                if (!document.querySelector('input[name=\"name\"]').value) {\n                  document.querySelector('input[name=\"name\"]').value = c.full_name;\n                }\n                if (c.cpf && !document.querySelector('input[name=\"document\"]').value) {\n                  document.querySelector('input[name=\"document\"]').value = c.cpf;\n                }\n                if (c.email && !document.querySelector('input[name=\"email\"]').value) {\n                  document.querySelector('input[name=\"email\"]').value = c.email;\n                }\n                if (c.phone && !document.querySelector('input[name=\"phone\"]').value) {\n                  document.querySelector('input[name=\"phone\"]').value = c.phone;\n                }\n                if (c.pix_key && !document.querySelector('input[name=\"pix_key\"]').value) {\n                  document.querySelector('input[name=\"pix_key\"]').value = c.pix_key;\n                }\n              };\n              resultadoDiv.appendChild(item);\n            });\n          }\n          resultadoDiv.style.display = 'block';\n        })\n        .catch(function () {\n          resultadoDiv.style.display = 'none';\n        });\n    }, 300);\n  });\n}\n\nfunction limparVinculo() {\n  linkedInput.value = '';\n  infoDiv.style.display = 'none';\n}\n</script>\n{% endblock %}\n",
  "titulos_privados_clientes.html": "{% extends \"base.html\" %}\n{% block title %}Clientes de Títulos — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n\n<div class=\"page-header\">\n  <div class=\"page-header-icon\">👤</div>\n  <div class=\"page-header-title\">Clientes de Títulos</div>\n  <div class=\"page-header-sub\">Cadastro próprio do módulo de Títulos Privados.</div>\n</div>\n\n<!-- KPIs -->\n<div class=\"metrics-grid\" style=\"grid-template-columns: repeat(3,1fr);\">\n  <div class=\"metric-card\">\n    <div class=\"metric-value\">{{ resumo.total }}</div>\n    <div class=\"metric-label\">Total de Clientes</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#4ade80;\">{{ resumo.ativos }}</div>\n    <div class=\"metric-label\">Ativos</div>\n  </div>\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#555;\">{{ resumo.inativos }}</div>\n    <div class=\"metric-label\">Inativos</div>\n  </div>\n</div>\n\n<!-- Toolbar -->\n<form method=\"get\" class=\"toolbar\">\n  <div class=\"toolbar-left\">\n    <div class=\"search-wrap\">\n      <input type=\"text\" name=\"q\" value=\"{{ q }}\"\n             placeholder=\"Buscar por nome, CPF/CNPJ, telefone ou e-mail…\"\n             class=\"form-control\" style=\"width:300px;\">\n    </div>\n    <select name=\"status\" class=\"form-control form-control-sm\" style=\"width:160px;\">\n      <option value=\"\">Todos os status</option>\n      <option value=\"ativo\"   {% if status_filtro == 'ativo' %}selected{% endif %}>Ativos</option>\n      <option value=\"inativo\" {% if status_filtro == 'inativo' %}selected{% endif %}>Inativos</option>\n    </select>\n    <button type=\"submit\" class=\"btn btn-secondary btn-sm\">Filtrar</button>\n    {% if q or status_filtro %}\n      <a href=\"{{ url_for('titulos_privados_clientes') }}\" class=\"btn btn-secondary btn-sm\">Limpar</a>\n    {% endif %}\n  </div>\n  <div class=\"toolbar-right\" style=\"gap:8px;\">\n    <a href=\"{{ url_for('titulos_privados_clientes_novo') }}\" class=\"btn btn-primary\">\n      + Novo Cliente de Títulos\n    </a>\n  </div>\n</form>\n\n{% if clientes %}\n<div class=\"table-wrap\">\n  <table>\n    <thead>\n      <tr>\n        <th>Nome</th>\n        <th>CPF/CNPJ</th>\n        <th>Telefone</th>\n        <th>E-mail</th>\n        <th style=\"text-align:center;\">Empréstimos</th>\n        <th style=\"text-align:right;\">Saldo em Aberto</th>\n        <th>Status</th>\n        <th style=\"text-align:right;\">Ações</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for c in clientes %}\n      <tr>\n        <td>\n          <a href=\"{{ url_for('titulos_privados_cliente_detalhe', pcid=c.id) }}\"\n             style=\"color:#F5F5F5;font-weight:500;\">{{ c.name }}</a>\n        </td>\n        <td class=\"text-mono text-dim\">{{ formatar_documento(c.document) }}</td>\n        <td class=\"text-dim\">{{ c.phone or '—' }}</td>\n        <td class=\"text-dim\">{{ c.email or '—' }}</td>\n        <td style=\"text-align:center;\">{{ c.loan_count }}</td>\n        <td style=\"text-align:right;font-weight:600;\">{{ formatar_moeda(c.saldo_aberto) }}</td>\n        <td>\n          {% if c.status == 'ativo' %}\n            <span class=\"badge badge-active\">● Ativo</span>\n          {% else %}\n            <span class=\"badge badge-inactive\">● Inativo</span>\n          {% endif %}\n        </td>\n        <td style=\"text-align:right;white-space:nowrap;\">\n          <a href=\"{{ url_for('titulos_privados_cliente_detalhe', pcid=c.id) }}\"\n             class=\"btn btn-secondary btn-sm\">Ver</a>\n          <a href=\"{{ url_for('titulos_privados_emprestimos_novo', private_client_id=c.id) }}\"\n             class=\"btn btn-secondary btn-sm\">Novo Empréstimo</a>\n          <a href=\"{{ url_for('titulos_privados_cliente_editar', pcid=c.id) }}\"\n             class=\"btn btn-secondary btn-sm\">Editar</a>\n        </td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n<div class=\"text-dim\" style=\"font-size:12px;margin-top:10px;text-align:right;\">\n  {{ clientes | length }} cliente(s) encontrado(s)\n</div>\n{% else %}\n<div class=\"empty-state\">\n  <div class=\"empty-state-icon\">👤</div>\n  <div class=\"empty-state-title\">Nenhum cliente de títulos encontrado</div>\n  <div class=\"empty-state-sub\">\n    {% if q or status_filtro %}\n      Tente ajustar os filtros de busca.\n    {% else %}\n      Cadastre o primeiro cliente de títulos para começar.\n    {% endif %}\n  </div>\n</div>\n{% endif %}\n\n{% endblock %}\n",
  "titulos_privados_emprestimo_detalhe.html": "{% extends \"base.html\" %}\n{% block title %}Empréstimo {{ loan.loan_number or ('#' ~ loan.id) }} — Títulos Privados{% endblock %}\n\n{% block content %}\n\n<a href=\"{{ url_for('titulos_privados_emprestimos') }}\" class=\"back-link\">← Voltar para Empréstimos</a>\n\n<div class=\"page-header\" style=\"display:flex;justify-content:space-between;align-items:flex-start;\">\n  <div>\n    <div class=\"page-header-title\">Empréstimo {{ loan.loan_number or ('#' ~ loan.id) }}</div>\n    <div class=\"page-header-sub\" style=\"margin-top:6px;\">\n      <a href=\"{{ url_for('titulos_privados_cliente_detalhe', pcid=loan.private_client_id) }}\" style=\"color:#d4af37;\">{{ loan.client_name }}</a>\n      &nbsp;\n      {% if loan_visual_status == 'active' %}<span class=\"badge badge-active\">Ativo</span>\n      {% elif loan_visual_status == 'overdue' %}<span class=\"badge badge-danger\">Em Atraso</span>\n      {% elif loan_visual_status == 'extended' %}<span class=\"badge badge-extended\">Prorrogado</span>\n      {% elif loan_visual_status == 'settled' %}<span class=\"badge badge-active\">Quitado</span>\n      {% elif loan_visual_status == 'renegotiated' %}<span class=\"badge badge-pending\">Renegociado</span>\n      {% else %}<span class=\"badge badge-inactive\">Cancelado</span>{% endif %}\n    </div>\n  </div>\n  <div style=\"display:flex;gap:8px;flex-shrink:0;flex-wrap:wrap;justify-content:flex-end;\">\n    {% if loan.status in ('active','overdue') %}\n      <form method=\"post\" action=\"{{ url_for('titulos_privados_emprestimo_recalcular', loan_id=loan.id) }}\" style=\"display:inline;\">\n        <button type=\"submit\" class=\"btn btn-secondary\">🔄 Recalcular para Hoje</button>\n      </form>\n      <a href=\"{{ url_for('titulos_privados_emprestimo_prorrogacao', loan_id=loan.id) }}\" class=\"btn btn-secondary\">⏳ Registrar Prorrogação</a>\n      <a href=\"{{ url_for('titulos_privados_emprestimo_amortizacao', loan_id=loan.id) }}\" class=\"btn btn-secondary\">📉 Registrar Amortização</a>\n      <form method=\"post\" action=\"{{ url_for('titulos_privados_emprestimo_quitar', loan_id=loan.id) }}\" style=\"display:inline;\">\n        <button type=\"submit\" class=\"btn btn-danger\"\n                data-confirm=\"Marcar o empréstimo {{ loan.loan_number or ('#' ~ loan.id) }} como quitado? Isso não apaga o histórico de parcelas/pagamentos.\">\n          ✅ Quitar Empréstimo\n        </button>\n      </form>\n    {% endif %}\n  </div>\n</div>\n\n<!-- Dados do empréstimo -->\n<div class=\"card-gold\" style=\"margin-bottom:20px;\">\n  <div class=\"form-section-title\" style=\"margin-bottom:12px;\">Dados do Empréstimo</div>\n  <div class=\"detail-grid\">\n    <div>\n      <div class=\"detail-item-label\">Cliente</div>\n      <div class=\"detail-item-value\">{{ loan.client_name }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">CPF/CNPJ</div>\n      <div class=\"detail-item-value text-mono\">{{ formatar_documento(loan.client_document) if loan.client_document else '—' }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Valor Original</div>\n      <div class=\"detail-item-value\">{{ formatar_moeda(loan.original_amount) }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Valor Contratado</div>\n      <div class=\"detail-item-value\" style=\"color:#d4af37;font-weight:700;\">{{ formatar_moeda(loan.contracted_amount) }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Taxa Mensal</div>\n      <div class=\"detail-item-value\">{{ formatar_percentual(loan.interest_rate_monthly) }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Método</div>\n      <div class=\"detail-item-value\">{{ {'bullet':'Pagamento Único','price':'Price','manual':'Manual'}.get(loan.calculation_method, loan.calculation_method) }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Data de Contratação</div>\n      <div class=\"detail-item-value text-dim\">{{ formatar_data(loan.start_date) }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Vencimento Final</div>\n      <div class=\"detail-item-value text-dim\">{{ formatar_data(loan.final_due_date) if loan.final_due_date else '—' }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Parcelas</div>\n      <div class=\"detail-item-value\">{{ loan.installments_count }}</div>\n    </div>\n  </div>\n\n  <div style=\"margin-top:16px;\">\n    <div class=\"detail-item-label\">Observações</div>\n    <form method=\"post\" action=\"{{ url_for('titulos_privados_emprestimo_observacoes', loan_id=loan.id) }}\" style=\"margin-top:6px;display:flex;gap:8px;align-items:flex-start;\">\n      <textarea name=\"notes\" class=\"form-control\" rows=\"2\" style=\"flex:1;\">{{ loan.notes or '' }}</textarea>\n      <button type=\"submit\" class=\"btn btn-secondary btn-sm\">Salvar</button>\n    </form>\n  </div>\n</div>\n\n<!-- Saldo atualizado -->\n{% if calc %}\n<div class=\"card-gold\" style=\"margin-bottom:20px;\">\n  <div class=\"form-section-title\" style=\"margin-bottom:12px;\">Saldo Atualizado (calculado para {{ formatar_data(calc.as_of_date) }})</div>\n  <div class=\"detail-grid\">\n    <div>\n      <div class=\"detail-item-label\">Saldo Base</div>\n      <div class=\"detail-item-value\">{{ formatar_moeda(calc.base_amount) }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Data Base do Cálculo</div>\n      <div class=\"detail-item-value text-dim\">{{ formatar_data(calc.base_date) }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Dias em Atraso</div>\n      <div class=\"detail-item-value\">\n        {% if calc.days_overdue > 0 %}\n          <span class=\"badge badge-inactive\">{{ calc.days_overdue }} dia(s)</span>\n        {% else %}\n          <span class=\"badge badge-active\">Em dia</span>\n        {% endif %}\n      </div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Taxa Diária Equivalente</div>\n      <div class=\"detail-item-value text-mono\">{{ '%.6f'|format(calc.daily_rate * 100) }}%</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Juros Acumulados</div>\n      <div class=\"detail-item-value\" style=\"color:#f0ad4e;\">{{ formatar_moeda(calc.accrued_interest) }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Total Amortizado Considerado</div>\n      <div class=\"detail-item-value text-dim\">{{ formatar_moeda(calc.total_amortized) }}</div>\n    </div>\n    <div>\n      <div class=\"detail-item-label\">Valor Atualizado</div>\n      <div class=\"detail-item-value\" style=\"color:#d4af37;font-weight:700;font-size:18px;\">{{ formatar_moeda(calc.updated_amount) }}</div>\n    </div>\n  </div>\n  <form method=\"post\" action=\"{{ url_for('titulos_privados_emprestimo_registrar_calculo', loan_id=loan.id) }}\" style=\"margin-top:14px;\">\n    <button type=\"submit\" class=\"btn btn-secondary btn-sm\">📝 Registrar Cálculo no Histórico</button>\n  </form>\n</div>\n{% endif %}\n\n<!-- Parcelas -->\n<div class=\"section-label\">🧾 &nbsp;Parcelas ({{ installments | length }})</div>\n{% if installments %}\n<div class=\"table-wrap\" style=\"margin-bottom:24px;\">\n  <table>\n    <thead>\n      <tr>\n        <th>#</th><th>Vencimento</th>\n        <th style=\"text-align:right;\">Valor Original</th>\n        <th style=\"text-align:right;\">Valor Pago</th>\n        <th style=\"text-align:right;\">Saldo em Aberto</th>\n        <th style=\"text-align:center;\">Dias em Atraso</th>\n        <th style=\"text-align:right;\">Valor Atualizado Hoje</th>\n        <th>Status</th><th style=\"text-align:right;\">Ações</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for p in installments %}\n      <tr>\n        <td>{{ p.installment_number }}</td>\n        <td class=\"text-dim\">{{ formatar_data(p.due_date) }}</td>\n        <td style=\"text-align:right;\">{{ formatar_moeda(p.original_amount) }}</td>\n        <td style=\"text-align:right;\">{{ formatar_moeda(p.paid_amount) }}</td>\n        <td style=\"text-align:right;\">{{ formatar_moeda(p.open_amount) }}</td>\n        <td style=\"text-align:center;\">\n          {% if p.days_overdue > 0 %}{{ p.days_overdue }}{% else %}—{% endif %}\n        </td>\n        <td style=\"text-align:right;font-weight:600;{% if p.visual_status == 'overdue' %}color:#f87171;{% endif %}\">\n          {% if p.visual_status == 'paid' %}Pago\n          {% else %}{{ formatar_moeda(p.updated_amount) }}{% endif %}\n        </td>\n        <td>\n          {% if p.visual_status == 'paid' %}<span class=\"badge badge-active\" {% if p.early_settled %}title=\"Quitada antecipadamente com desconto de juros futuro\"{% endif %}>Paga{% if p.early_settled %} ⚡{% endif %}</span>\n          {% elif p.visual_status == 'partial' %}<span class=\"badge badge-warning\">Parcial</span>\n          {% elif p.visual_status == 'overdue' %}<span class=\"badge badge-danger\">Atrasada</span>\n          {% elif p.visual_status == 'extended' %}<span class=\"badge badge-extended\">Prorrogada</span>\n          {% else %}<span class=\"badge badge-pending\">Aberta</span>{% endif %}\n        </td>\n        <td style=\"text-align:right;white-space:nowrap;\">\n          {% if p.visual_status != 'paid' %}\n          <form method=\"post\" action=\"{{ url_for('titulos_privados_parcela_pagar', loan_id=loan.id, installment_id=p.id) }}\"\n                style=\"display:inline-flex;gap:4px;align-items:center;\"\n                onsubmit=\"return confirm('Confirma o registro deste pagamento? Isso não pode ser desfeito automaticamente.');\">\n            <input type=\"number\" step=\"0.01\" name=\"paid_amount\" class=\"form-control form-control-sm\"\n                   style=\"width:110px;\" placeholder=\"Valor pago\" required>\n            <input type=\"date\" name=\"paid_date\" class=\"form-control form-control-sm\" style=\"width:140px;\"\n                   value=\"{{ '' }}\">\n            <button type=\"submit\" class=\"btn btn-secondary btn-sm\">Registrar Pagamento</button>\n          </form>\n          {% else %}\n            <span class=\"text-dim\">{{ formatar_data(p.paid_date) if p.paid_date else '—' }}</span>\n          {% endif %}\n        </td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n{% else %}\n<div class=\"empty-state\" style=\"margin-bottom:24px;\">\n  <div class=\"empty-state-icon\">🧾</div>\n  <div class=\"empty-state-title\">Nenhuma parcela gerada</div>\n  <div class=\"empty-state-sub\">Empréstimo do tipo manual — parcelas ainda não são geradas automaticamente.</div>\n</div>\n{% endif %}\n\n<!-- Prorrogações -->\n<div class=\"section-label\">⏳ &nbsp;Prorrogações ({{ extensions | length }})</div>\n{% if extensions %}\n<div class=\"table-wrap\" style=\"margin-bottom:24px;\">\n  <table>\n    <thead>\n      <tr><th>Data do Pagamento</th><th style=\"text-align:right;\">Valor Pago</th><th>Coberto Até</th><th>Observações</th></tr>\n    </thead>\n    <tbody>\n      {% for e in extensions %}\n      <tr>\n        <td class=\"text-dim\">{{ formatar_data(e.paid_date) }}</td>\n        <td style=\"text-align:right;\">{{ formatar_moeda(e.extension_amount) }}</td>\n        <td style=\"font-weight:600;color:#d4af37;\">{{ formatar_data(e.covered_until_date) }}</td>\n        <td class=\"text-dim\">{{ e.notes or '—' }}</td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n{% else %}\n<div class=\"empty-state\" style=\"margin-bottom:24px;\">\n  <div class=\"empty-state-icon\">⏳</div>\n  <div class=\"empty-state-title\">Nenhuma prorrogação registrada</div>\n</div>\n{% endif %}\n\n<!-- Amortizações -->\n<div class=\"section-label\">📉 &nbsp;Amortizações ({{ amortizations | length }})</div>\n{% if amortizations %}\n<div class=\"table-wrap\" style=\"margin-bottom:24px;\">\n  <table>\n    <thead>\n      <tr><th>Data</th><th style=\"text-align:right;\">Valor</th><th>Tipo</th><th>Parcela</th>\n          <th style=\"text-align:right;\">Desconto</th><th>Aplicado em</th><th>Observações</th></tr>\n    </thead>\n    <tbody>\n      {% for a in amortizations %}\n      <tr>\n        <td class=\"text-dim\">{{ formatar_data(a.payment_date) }}</td>\n        <td style=\"text-align:right;font-weight:600;\">{{ formatar_moeda(a.amount) }}</td>\n        <td>\n          {% if a.price_action == 'quitar_parcela_antecipada' %}⚡ Quitação Antecipada de Parcela\n          {% else %}{{ {'antecipacao_parcela':'Antecipação de Parcela','reducao_saldo':'Redução de Saldo','liquidacao_parcial':'Liquidação Parcial','liquidacao_total':'Liquidação Total'}.get(a.amortization_type, a.amortization_type) }}\n          {% endif %}\n        </td>\n        <td class=\"text-dim\">\n          {% if a.target_installment_number %}Parcela {{ a.target_installment_number }}\n          {% elif a.target_mode == 'proximas_parcelas' %}Próximas parcelas\n          {% elif a.target_mode == 'saldo_devedor' %}Saldo devedor\n          {% else %}—{% endif %}\n        </td>\n        <td style=\"text-align:right;\" class=\"text-dim\">\n          {% if a.price_action == 'quitar_parcela_antecipada' and a.amount_before is not none %}\n            {{ formatar_moeda(a.amount_before - a.amount) }}\n          {% else %}—{% endif %}\n        </td>\n        <td>{{ {'principal':'Principal','interest':'Juros','mixed':'Misto'}.get(a.applied_to, a.applied_to) }}</td>\n        <td class=\"text-dim\">{{ a.notes or '—' }}</td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n{% else %}\n<div class=\"empty-state\" style=\"margin-bottom:24px;\">\n  <div class=\"empty-state-icon\">📉</div>\n  <div class=\"empty-state-title\">Nenhuma amortização registrada</div>\n</div>\n{% endif %}\n\n<!-- Pagamentos -->\n<div class=\"section-label\">💳 &nbsp;Pagamentos Registrados ({{ payments | length }})</div>\n{% if payments %}\n<div class=\"table-wrap\" style=\"margin-bottom:24px;\">\n  <table>\n    <thead>\n      <tr><th>Data</th><th style=\"text-align:right;\">Valor</th><th>Tipo</th><th>Observações</th></tr>\n    </thead>\n    <tbody>\n      {% for pg in payments %}\n      <tr>\n        <td class=\"text-dim\">{{ formatar_data(pg.payment_date) }}</td>\n        <td style=\"text-align:right;\">{{ formatar_moeda(pg.amount) }}</td>\n        <td>{{ {'installment':'Parcela','extension':'Prorrogação','amortization':'Amortização','settlement':'Quitação','other':'Outro'}.get(pg.payment_type, pg.payment_type) }}</td>\n        <td class=\"text-dim\">{{ pg.notes or '—' }}</td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n{% else %}\n<div class=\"empty-state\" style=\"margin-bottom:24px;\">\n  <div class=\"empty-state-icon\">💳</div>\n  <div class=\"empty-state-title\">Nenhum pagamento registrado ainda</div>\n</div>\n{% endif %}\n\n<!-- Histórico de cálculos -->\n<div class=\"section-label\">📊 &nbsp;Histórico de Cálculos Registrados ({{ calculations_log | length }})</div>\n{% if calculations_log %}\n<div class=\"table-wrap\">\n  <table>\n    <thead>\n      <tr><th>Registrado em</th><th>Data Base</th><th>Dias Atraso</th>\n          <th style=\"text-align:right;\">Saldo Base</th><th style=\"text-align:right;\">Valor Calculado</th></tr>\n    </thead>\n    <tbody>\n      {% for log in calculations_log %}\n      <tr>\n        <td class=\"text-dim\">{{ log.calculation_date }}</td>\n        <td class=\"text-dim\">{{ formatar_data(log.base_date) }}</td>\n        <td>{{ log.days_overdue }}</td>\n        <td style=\"text-align:right;\">{{ formatar_moeda(log.base_amount) }}</td>\n        <td style=\"text-align:right;font-weight:600;color:#d4af37;\">{{ formatar_moeda(log.calculated_amount) }}</td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n{% else %}\n<div class=\"empty-state\">\n  <div class=\"empty-state-icon\">📊</div>\n  <div class=\"empty-state-title\">Nenhum cálculo registrado no histórico ainda</div>\n  <div class=\"empty-state-sub\">Use \"Recalcular para Hoje\" e depois \"Registrar Cálculo no Histórico\".</div>\n</div>\n{% endif %}\n\n{% endblock %}\n",
  "titulos_privados_emprestimo_form.html": "{% extends \"base.html\" %}\n{% block title %}Novo Empréstimo — Títulos Privados — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n\n<a href=\"{{ url_for('titulos_privados_emprestimos') }}\" class=\"back-link\">← Voltar para Empréstimos</a>\n\n<div class=\"page-header\">\n  <div class=\"page-header-icon\">➕</div>\n  <div class=\"page-header-title\">Novo Empréstimo</div>\n  <div class=\"page-header-sub\">Empréstimo privado da empresa para um cliente de títulos.</div>\n</div>\n\n{% if not clientes %}\n<div class=\"note-box\" style=\"color:#f87171;border-color:rgba(239,68,68,0.25);margin-bottom:16px;\">\n  ⚠️ Nenhum cliente de títulos ativo cadastrado ainda.\n  <a href=\"{{ url_for('titulos_privados_clientes_novo') }}\" style=\"color:#d4af37;\">Cadastre um cliente primeiro</a>.\n</div>\n{% endif %}\n\n<div class=\"card-gold\">\n  <form method=\"post\" id=\"form-emprestimo\">\n\n    <div class=\"form-section\">\n      <div class=\"form-section-title\">Cliente</div>\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label>Cliente de Títulos *</label>\n          <select name=\"private_client_id\" class=\"form-control\" required>\n            <option value=\"\">Selecione…</option>\n            {% for c in clientes %}\n            <option value=\"{{ c.id }}\" {{ 'selected' if emprestimo.get('private_client_id')|string == c.id|string else '' }}>\n              {{ c.name }}{% if c.document %} — {{ formatar_documento(c.document) }}{% endif %}\n            </option>\n            {% endfor %}\n          </select>\n        </div>\n        <div class=\"form-group\">\n          <label>Número/Identificação do Empréstimo</label>\n          <input type=\"text\" name=\"loan_number\" value=\"{{ emprestimo.get('loan_number','') }}\"\n                 class=\"form-control\" placeholder=\"Opcional — ex: EMP-001\">\n        </div>\n      </div>\n    </div>\n\n    <div class=\"form-section\">\n      <div class=\"form-section-title\">Tipo de Empréstimo</div>\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label>Método de Cálculo *</label>\n          <select name=\"calculation_method\" id=\"calculation_method\" class=\"form-control\" onchange=\"atualizarCamposMetodo()\">\n            <option value=\"bullet\" {{ 'selected' if emprestimo.get('calculation_method','bullet') == 'bullet' else '' }}>Pagamento Único</option>\n            <option value=\"price\"  {{ 'selected' if emprestimo.get('calculation_method') == 'price' else '' }}>Parcelado — Sistema Price</option>\n            <option value=\"manual\" {{ 'selected' if emprestimo.get('calculation_method') == 'manual' else '' }}>Manual</option>\n          </select>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"form-section\">\n      <div class=\"form-section-title\">Valores e Taxa</div>\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label>Valor Originalmente Emprestado (R$) *</label>\n          <input type=\"text\" name=\"original_amount\" value=\"{{ emprestimo.get('original_amount','') }}\"\n                 class=\"form-control\" required placeholder=\"30.000,00\" data-mask=\"currency\">\n        </div>\n        <div class=\"form-group\" id=\"grupo-contracted-amount\">\n          <label>Valor Total Contratado a Pagar (R$) *\n            <span style=\"color:#666;font-size:11px;\">(automático no Price)</span>\n          </label>\n          <input type=\"text\" name=\"contracted_amount\" value=\"{{ emprestimo.get('contracted_amount','') }}\"\n                 class=\"form-control\" required placeholder=\"32.000,00\" data-mask=\"currency\">\n        </div>\n        <div class=\"form-group\">\n          <label>Taxa de Juros Mensal (%) *</label>\n          <input type=\"text\" name=\"interest_rate_monthly\" value=\"{{ emprestimo.get('interest_rate_monthly','') }}\"\n                 class=\"form-control\" required placeholder=\"Ex: 3,5 ou 3,5%\">\n          <div style=\"font-size:11px;color:#666;margin-top:4px;\">Aceita 3,5 / 3,5% / 0,035 / 0.035 — todos equivalem a 3,5% ao mês.</div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"form-section\">\n      <div class=\"form-section-title\">Datas</div>\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label>Data de Contratação *</label>\n          <input type=\"date\" name=\"start_date\" value=\"{{ emprestimo.get('start_date','') }}\"\n                 class=\"form-control\" required>\n        </div>\n        <div class=\"form-group\" id=\"grupo-final-due-date\">\n          <label>Data de Vencimento *</label>\n          <input type=\"date\" name=\"final_due_date\" value=\"{{ emprestimo.get('final_due_date','') }}\"\n                 class=\"form-control\">\n        </div>\n        <div class=\"form-group\" id=\"grupo-first-due-date\" style=\"display:none;\">\n          <label>Data da Primeira Parcela *</label>\n          <input type=\"date\" name=\"first_due_date\" value=\"{{ emprestimo.get('first_due_date','') }}\"\n                 class=\"form-control\">\n        </div>\n        <div class=\"form-group\" id=\"grupo-installments\" style=\"display:none;\">\n          <label>Quantidade de Parcelas *</label>\n          <input type=\"number\" name=\"installments_count\" min=\"1\" value=\"{{ emprestimo.get('installments_count','') }}\"\n                 class=\"form-control\">\n        </div>\n      </div>\n      <div class=\"note-box\" id=\"aviso-price\" style=\"display:none;\">\n        ℹ️ No método Price, o valor da parcela e o valor total contratado são calculados\n        automaticamente a partir do valor original, da taxa mensal e da quantidade de parcelas.\n      </div>\n      <div class=\"note-box\" id=\"aviso-manual\" style=\"display:none;\">\n        ℹ️ No método manual, o empréstimo é criado sem parcelas — o preenchimento manual das\n        parcelas será suportado em uma próxima etapa deste módulo.\n      </div>\n    </div>\n\n    <div class=\"form-section\">\n      <div class=\"form-section-title\">Observações</div>\n      <div class=\"form-group\">\n        <textarea name=\"notes\" class=\"form-control\" rows=\"3\"\n                  placeholder=\"Anotações internas (opcional)\">{{ emprestimo.get('notes','') }}</textarea>\n      </div>\n    </div>\n\n    <div class=\"page-actions\">\n      <a href=\"{{ url_for('titulos_privados_emprestimos') }}\" class=\"btn btn-secondary\">Cancelar</a>\n      <button type=\"submit\" class=\"btn btn-primary\">✓ Cadastrar Empréstimo</button>\n    </div>\n\n  </form>\n</div>\n\n{% endblock %}\n\n{% block scripts %}\n<script>\nfunction atualizarCamposMetodo() {\n  var metodo = document.getElementById('calculation_method').value;\n  var grupoContratado = document.getElementById('grupo-contracted-amount');\n  var grupoFinalDue = document.getElementById('grupo-final-due-date');\n  var grupoFirstDue = document.getElementById('grupo-first-due-date');\n  var grupoInstallments = document.getElementById('grupo-installments');\n  var avisoPrice = document.getElementById('aviso-price');\n  var avisoManual = document.getElementById('aviso-manual');\n  var inputContratado = grupoContratado.querySelector('input');\n  var inputFinalDue = grupoFinalDue.querySelector('input');\n  var inputFirstDue = grupoFirstDue.querySelector('input');\n  var inputInstallments = grupoInstallments.querySelector('input');\n\n  if (metodo === 'price') {\n    grupoContratado.style.display = 'none';\n    inputContratado.required = false;\n    grupoFinalDue.style.display = 'none';\n    inputFinalDue.required = false;\n    grupoFirstDue.style.display = 'block';\n    inputFirstDue.required = true;\n    grupoInstallments.style.display = 'block';\n    inputInstallments.required = true;\n    avisoPrice.style.display = 'block';\n    avisoManual.style.display = 'none';\n  } else if (metodo === 'manual') {\n    grupoContratado.style.display = 'block';\n    inputContratado.required = true;\n    grupoFinalDue.style.display = 'block';\n    inputFinalDue.required = false;\n    grupoFirstDue.style.display = 'none';\n    inputFirstDue.required = false;\n    grupoInstallments.style.display = 'none';\n    inputInstallments.required = false;\n    avisoPrice.style.display = 'none';\n    avisoManual.style.display = 'block';\n  } else { // bullet\n    grupoContratado.style.display = 'block';\n    inputContratado.required = true;\n    grupoFinalDue.style.display = 'block';\n    inputFinalDue.required = true;\n    grupoFirstDue.style.display = 'none';\n    inputFirstDue.required = false;\n    grupoInstallments.style.display = 'none';\n    inputInstallments.required = false;\n    avisoPrice.style.display = 'none';\n    avisoManual.style.display = 'none';\n  }\n}\natualizarCamposMetodo();\n</script>\n{% endblock %}\n",
  "titulos_privados_emprestimos.html": "{% extends \"base.html\" %}\n{% block title %}Empréstimos — Títulos Privados — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n\n<div class=\"page-header\">\n  <div class=\"page-header-icon\">💰</div>\n  <div class=\"page-header-title\">Empréstimos</div>\n  <div class=\"page-header-sub\">Todos os empréstimos privados cadastrados.</div>\n</div>\n\n<form method=\"get\" class=\"toolbar\">\n  <div class=\"toolbar-left\">\n    <select name=\"status\" class=\"form-control form-control-sm\" style=\"width:200px;\" onchange=\"this.form.submit()\">\n      <option value=\"\">Todos os status</option>\n      <option value=\"active\"       {% if status_filtro == 'active' %}selected{% endif %}>Ativo</option>\n      <option value=\"overdue\"      {% if status_filtro == 'overdue' %}selected{% endif %}>Em Atraso</option>\n      <option value=\"settled\"      {% if status_filtro == 'settled' %}selected{% endif %}>Quitado</option>\n      <option value=\"renegotiated\" {% if status_filtro == 'renegotiated' %}selected{% endif %}>Renegociado</option>\n      <option value=\"cancelled\"    {% if status_filtro == 'cancelled' %}selected{% endif %}>Cancelado</option>\n    </select>\n    {% if status_filtro %}\n      <a href=\"{{ url_for('titulos_privados_emprestimos') }}\" class=\"btn btn-secondary btn-sm\">Limpar</a>\n    {% endif %}\n  </div>\n  <div class=\"toolbar-right\">\n    <a href=\"{{ url_for('titulos_privados_emprestimos_novo') }}\" class=\"btn btn-primary\">+ Novo Empréstimo</a>\n  </div>\n</form>\n\n{% if loans %}\n<div class=\"table-wrap\">\n  <table>\n    <thead>\n      <tr>\n        <th>Empréstimo</th><th>Cliente</th><th>Método</th>\n        <th style=\"text-align:right;\">Original</th><th style=\"text-align:right;\">Contratado</th>\n        <th style=\"text-align:right;\">Saldo Atualizado</th><th>Status</th><th style=\"text-align:right;\">Ações</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for l in loans %}\n      <tr>\n        <td class=\"text-mono\">{{ l.loan_number or ('#' ~ l.id) }}</td>\n        <td>\n          <a href=\"{{ url_for('titulos_privados_cliente_detalhe', pcid=l.private_client_id) }}\"\n             style=\"color:#F5F5F5;\">{{ l.client_name }}</a>\n        </td>\n        <td>{{ {'bullet':'Pagamento Único','price':'Price','manual':'Manual'}.get(l.calculation_method, l.calculation_method) }}</td>\n        <td style=\"text-align:right;\">{{ formatar_moeda(l.original_amount) }}</td>\n        <td style=\"text-align:right;\">{{ formatar_moeda(l.contracted_amount) }}</td>\n        <td style=\"text-align:right;font-weight:600;{% if l.calc and l.calc.days_overdue > 0 %}color:#f87171;{% endif %}\">\n          {{ formatar_moeda(l.calc.updated_amount) if l.calc else '—' }}\n        </td>\n        <td>\n          {% if l.status == 'active' %}<span class=\"badge badge-active\">Ativo</span>\n          {% elif l.status == 'overdue' %}<span class=\"badge badge-inactive\">Em Atraso</span>\n          {% elif l.status == 'settled' %}<span class=\"badge badge-active\">Quitado</span>\n          {% elif l.status == 'renegotiated' %}<span class=\"badge badge-pending\">Renegociado</span>\n          {% else %}<span class=\"badge badge-inactive\">Cancelado</span>{% endif %}\n        </td>\n        <td style=\"text-align:right;\">\n          <a href=\"{{ url_for('titulos_privados_emprestimo_detalhe', loan_id=l.id) }}\" class=\"btn btn-secondary btn-sm\">Ver</a>\n        </td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n<div class=\"text-dim\" style=\"font-size:12px;margin-top:10px;text-align:right;\">\n  {{ loans | length }} empréstimo(s) encontrado(s)\n</div>\n{% else %}\n<div class=\"empty-state\">\n  <div class=\"empty-state-icon\">💰</div>\n  <div class=\"empty-state-title\">Nenhum empréstimo cadastrado</div>\n  <div class=\"empty-state-sub\">Cadastre o primeiro empréstimo privado para começar.</div>\n</div>\n{% endif %}\n\n{% endblock %}\n",
  "titulos_privados_parcelas.html": "{% extends \"base.html\" %}\n{% block title %}Parcelas / Recebimentos — Títulos Privados{% endblock %}\n\n{% block content %}\n\n<div class=\"page-header\">\n  <div class=\"page-header-icon\">🧾</div>\n  <div class=\"page-header-title\">Parcelas / Recebimentos</div>\n  <div class=\"page-header-sub\">Visão consolidada das parcelas de todos os empréstimos privados.</div>\n</div>\n\n<form method=\"get\" class=\"toolbar\">\n  <div class=\"toolbar-left\">\n    <select name=\"status\" class=\"form-control form-control-sm\" style=\"width:200px;\" onchange=\"this.form.submit()\">\n      <option value=\"\">Todos os status</option>\n      <option value=\"open\"         {% if status_filtro == 'open' %}selected{% endif %}>Aberta</option>\n      <option value=\"paid\"         {% if status_filtro == 'paid' %}selected{% endif %}>Paga</option>\n      <option value=\"partial\"      {% if status_filtro == 'partial' %}selected{% endif %}>Parcial</option>\n      <option value=\"overdue\"      {% if status_filtro == 'overdue' %}selected{% endif %}>Vencida</option>\n      <option value=\"renegotiated\" {% if status_filtro == 'renegotiated' %}selected{% endif %}>Renegociada</option>\n      <option value=\"cancelled\"    {% if status_filtro == 'cancelled' %}selected{% endif %}>Cancelada</option>\n    </select>\n    {% if status_filtro %}\n      <a href=\"{{ url_for('titulos_privados_parcelas') }}\" class=\"btn btn-secondary btn-sm\">Limpar</a>\n    {% endif %}\n  </div>\n</form>\n\n{% if parcelas %}\n<div class=\"table-wrap\">\n  <table>\n    <thead>\n      <tr>\n        <th>Cliente</th><th>Empréstimo</th><th>#</th><th>Vencimento</th>\n        <th style=\"text-align:right;\">Parcela</th><th style=\"text-align:right;\">Pago</th><th>Status</th><th style=\"text-align:right;\">Ações</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for p in parcelas %}\n      <tr>\n        <td>{{ p.client_name }}</td>\n        <td class=\"text-mono\">{{ p.loan_number or ('#' ~ p.loan_id) }}</td>\n        <td>{{ p.installment_number }}</td>\n        <td class=\"text-dim\">{{ formatar_data(p.due_date) }}</td>\n        <td style=\"text-align:right;font-weight:600;\">{{ formatar_moeda(p.installment_amount) }}</td>\n        <td style=\"text-align:right;\">{{ formatar_moeda(p.paid_amount) }}</td>\n        <td>\n          {% if p.status == 'paid' %}<span class=\"badge badge-active\">Pago</span>\n          {% elif p.status == 'partial' %}<span class=\"badge badge-pending\">Parcial</span>\n          {% elif p.status == 'overdue' %}<span class=\"badge badge-inactive\">Vencida</span>\n          {% elif p.status == 'renegotiated' %}<span class=\"badge badge-pending\">Renegociada</span>\n          {% elif p.status == 'cancelled' %}<span class=\"badge badge-inactive\">Cancelada</span>\n          {% else %}<span class=\"badge badge-pending\">Aberta</span>{% endif %}\n        </td>\n        <td style=\"text-align:right;\">\n          <a href=\"{{ url_for('titulos_privados_emprestimo_detalhe', loan_id=p.loan_id) }}\" class=\"btn btn-secondary btn-sm\">Ver Empréstimo</a>\n        </td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n<div class=\"text-dim\" style=\"font-size:12px;margin-top:10px;text-align:right;\">\n  {{ parcelas | length }} parcela(s) encontrada(s)\n</div>\n{% else %}\n<div class=\"empty-state\">\n  <div class=\"empty-state-icon\">🧾</div>\n  <div class=\"empty-state-title\">Nenhuma parcela cadastrada</div>\n</div>\n{% endif %}\n\n{% endblock %}\n",
  "titulos_privados_prorrogacao_form.html": "{% extends \"base.html\" %}\n{% block title %}Registrar Prorrogação — Títulos Privados{% endblock %}\n\n{% block content %}\n\n<a href=\"{{ url_for('titulos_privados_emprestimo_detalhe', loan_id=loan.id) }}\" class=\"back-link\">← Voltar para o Empréstimo</a>\n\n<div class=\"page-header\">\n  <div class=\"page-header-icon\">⏳</div>\n  <div class=\"page-header-title\">Registrar Prorrogação</div>\n  <div class=\"page-header-sub\">{{ loan.client_name }} — Empréstimo {{ loan.loan_number or ('#' ~ loan.id) }}</div>\n</div>\n\n<div class=\"note-box\" style=\"margin-bottom:16px;\">\n  ℹ️ A prorrogação NÃO reduz o valor principal do empréstimo — ela só adia a data a partir da\n  qual os juros de atraso passam a contar. Se parte do valor pago deve ser considerada\n  amortização (reduzindo o saldo), preencha o campo opcional abaixo.\n</div>\n\n<div class=\"card-gold\">\n  <form method=\"post\">\n    <div class=\"form-section\">\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label>Valor Pago da Prorrogação (R$) *</label>\n          <input type=\"text\" name=\"extension_amount\" class=\"form-control\" required\n                 placeholder=\"2.000,00\" data-mask=\"currency\">\n        </div>\n        <div class=\"form-group\">\n          <label>Data do Pagamento *</label>\n          <input type=\"date\" name=\"paid_date\" class=\"form-control\" required>\n        </div>\n        <div class=\"form-group\">\n          <label>Prorrogar Até Qual Data *</label>\n          <input type=\"date\" name=\"covered_until_date\" class=\"form-control\" required>\n        </div>\n      </div>\n      <div class=\"form-row\">\n        <div class=\"form-group\">\n          <label>Valor Considerado Amortização (opcional)</label>\n          <input type=\"text\" name=\"principal_amortization_amount\" class=\"form-control\"\n                 placeholder=\"0,00 — só preencha se parte do valor reduzir o principal\" data-mask=\"currency\">\n        </div>\n      </div>\n      <div class=\"form-group\">\n        <label>Observações</label>\n        <textarea name=\"notes\" class=\"form-control\" rows=\"2\" placeholder=\"Opcional\"></textarea>\n      </div>\n    </div>\n\n    <div class=\"page-actions\">\n      <a href=\"{{ url_for('titulos_privados_emprestimo_detalhe', loan_id=loan.id) }}\" class=\"btn btn-secondary\">Cancelar</a>\n      <button type=\"submit\" class=\"btn btn-primary\">✓ Registrar Prorrogação</button>\n    </div>\n  </form>\n</div>\n\n{% endblock %}\n",
  "titulos_privados_prorrogacoes.html": "{% extends \"base.html\" %}\n{% block title %}Prorrogações — Títulos Privados{% endblock %}\n\n{% block content %}\n\n<div class=\"page-header\">\n  <div class=\"page-header-icon\">⏳</div>\n  <div class=\"page-header-title\">Prorrogações</div>\n  <div class=\"page-header-sub\">Todas as prorrogações registradas nos empréstimos privados.</div>\n</div>\n\n{% if prorrogacoes %}\n<div class=\"table-wrap\">\n  <table>\n    <thead>\n      <tr>\n        <th>Cliente</th><th>Empréstimo</th><th>Data do Pagamento</th>\n        <th style=\"text-align:right;\">Valor Pago</th><th>Coberto Até</th><th style=\"text-align:right;\">Ações</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for e in prorrogacoes %}\n      <tr>\n        <td>{{ e.client_name }}</td>\n        <td class=\"text-mono\">{{ e.loan_number or ('#' ~ e.loan_id) }}</td>\n        <td class=\"text-dim\">{{ formatar_data(e.paid_date) }}</td>\n        <td style=\"text-align:right;font-weight:600;\">{{ formatar_moeda(e.extension_amount) }}</td>\n        <td style=\"color:#d4af37;font-weight:600;\">{{ formatar_data(e.covered_until_date) }}</td>\n        <td style=\"text-align:right;\">\n          <a href=\"{{ url_for('titulos_privados_emprestimo_detalhe', loan_id=e.loan_id) }}\" class=\"btn btn-secondary btn-sm\">Ver Empréstimo</a>\n        </td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n<div class=\"text-dim\" style=\"font-size:12px;margin-top:10px;text-align:right;\">\n  {{ prorrogacoes | length }} prorrogação(ões) encontrada(s)\n</div>\n{% else %}\n<div class=\"empty-state\">\n  <div class=\"empty-state-icon\">⏳</div>\n  <div class=\"empty-state-title\">Nenhuma prorrogação registrada ainda</div>\n</div>\n{% endif %}\n\n{% endblock %}\n",
  "validacao_sistema.html": "{% extends \"base.html\" %}\n{% block title %}Validação Sistema — Grupo Capuzzo{% endblock %}\n\n{% block content %}\n\n<div class=\"page-header\">\n  <div class=\"page-header-icon\">🧾</div>\n  <div class=\"page-header-title\">Validação Sistema</div>\n  <div class=\"page-header-sub\">\n    Projeção gerencial cota a cota — simula a retirada de cada cota no vencimento\n  </div>\n</div>\n\n<!-- ═══ Aviso: simulação, não apuração ═══ -->\n<div class=\"note-box\" style=\"margin-bottom:18px;\">\n  <strong style=\"color:#d4af37;\">⚠️ Tela somente leitura — simulação gerencial.</strong>\n  Esta projeção assume que o cliente <strong>retira</strong> cada cota no vencimento\n  (não renova). Ela <strong>não</strong> altera cotas, não cria lançamentos e\n  <strong>não substitui a Apuração</strong>, que é o cálculo oficial do mês.\n</div>\n\n<!-- ═══ CARDS DE TOTAIS ═══ -->\n<div class=\"metrics-grid\" style=\"grid-template-columns:repeat(3,1fr);margin-bottom:14px;\">\n\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#d4af37;\">{{ formatar_moeda(totais.total_invested) }}</div>\n    <div class=\"metric-label\">Total investido ativo</div>\n    <div style=\"font-size:11px;color:#888;margin-top:4px;line-height:1.6;\">\n      🏗️ {{ formatar_moeda(totais.total_by_condominium.civil) }} ·\n      🌾 {{ formatar_moeda(totais.total_by_condominium.agro) }} ·\n      🏥 {{ formatar_moeda(totais.total_by_condominium.saude) }}\n    </div>\n  </div>\n\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#F5F5F5;\">{{ totais.clients_count }}</div>\n    <div class=\"metric-label\">Clientes com cotas</div>\n    <div style=\"font-size:11px;color:#888;margin-top:4px;\">\n      Apenas cotas com status <strong>ativa</strong>\n    </div>\n  </div>\n\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#F5F5F5;\">{{ totais.shares_count }}</div>\n    <div class=\"metric-label\">Cotas consideradas</div>\n    <div style=\"font-size:11px;color:{{ '#f0ad4e' if totais.shares_without_maturity else '#888' }};margin-top:4px;\">\n      {% if totais.shares_without_maturity %}\n        ⚠️ {{ totais.shares_without_maturity }} sem vencimento cadastrado\n      {% else %}\n        Todas com vencimento cadastrado\n      {% endif %}\n    </div>\n  </div>\n\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#4ade80;\">{{ formatar_moeda(totais.current_month_yield) }}</div>\n    <div class=\"metric-label\">Rendimento previsto — {{ inicio_label }}</div>\n    <div style=\"font-size:11px;color:#888;margin-top:4px;\">Primeiro mês da projeção</div>\n  </div>\n\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#4ade80;\">{{ formatar_moeda(totais.yield_12m) }}</div>\n    <div class=\"metric-label\">Rendimento previsto — próximos 12 meses</div>\n    <div style=\"font-size:11px;color:#888;margin-top:4px;\">{{ totais.window_12m_label }}</div>\n  </div>\n\n  <div class=\"metric-card\">\n    <div class=\"metric-value\" style=\"color:#f87171;\">{{ formatar_moeda(totais.leaving_base_12m) }}</div>\n    <div class=\"metric-label\">Deixa de render em 12 meses</div>\n    <div style=\"font-size:11px;color:#888;margin-top:4px;\">\n      {{ totais.leaving_shares_12m }} cota(s) saem da base por vencimento\n    </div>\n  </div>\n\n</div>\n\n<!-- ═══ FILTROS ═══ -->\n<form method=\"get\" class=\"toolbar\">\n  <div class=\"toolbar-left\" style=\"flex-wrap:wrap;gap:8px;\">\n    <div>\n      <label style=\"display:block;font-size:10px;color:#666;text-transform:uppercase;letter-spacing:.8px;margin-bottom:3px;\">Início da projeção</label>\n      <input type=\"month\" name=\"inicio\" value=\"{{ inicio_input }}\"\n             class=\"form-control form-control-sm\" style=\"width:150px;\">\n    </div>\n    <div>\n      <label style=\"display:block;font-size:10px;color:#666;text-transform:uppercase;letter-spacing:.8px;margin-bottom:3px;\">Meses</label>\n      <select name=\"meses\" class=\"form-control form-control-sm\" style=\"width:105px;\">\n        {% for m in [6, 12, 18, 24, 36, 48, 60] %}\n        <option value=\"{{ m }}\" {{ 'selected' if meses == m else '' }}>{{ m }} meses</option>\n        {% endfor %}\n      </select>\n    </div>\n    <div>\n      <label style=\"display:block;font-size:10px;color:#666;text-transform:uppercase;letter-spacing:.8px;margin-bottom:3px;\">Cliente</label>\n      <select name=\"cliente\" class=\"form-control form-control-sm\" style=\"width:250px;\">\n        <option value=\"\">Todos os clientes</option>\n        {% for c in clientes_filtro %}\n        <option value=\"{{ c.id }}\" {{ 'selected' if cliente_filtro == c.id|string else '' }}>\n          {{ c.full_name }} ({{ c.qtd_cotas }} cotas)\n        </option>\n        {% endfor %}\n      </select>\n    </div>\n    <div>\n      <label style=\"display:block;font-size:10px;color:#666;text-transform:uppercase;letter-spacing:.8px;margin-bottom:3px;\">Condomínio</label>\n      <select name=\"produto\" class=\"form-control form-control-sm\" style=\"width:170px;\">\n        <option value=\"\">Todos os condomínios</option>\n        {% for c in conds %}\n        <option value=\"{{ c.code }}\" {{ 'selected' if produto_filtro == c.code else '' }}>{{ c.name }}</option>\n        {% endfor %}\n      </select>\n    </div>\n    <div>\n      <label style=\"display:block;font-size:10px;color:#666;text-transform:uppercase;letter-spacing:.8px;margin-bottom:3px;\">Busca livre</label>\n      <input type=\"text\" name=\"q\" value=\"{{ q }}\" placeholder=\"Nome, CPF/CNPJ ou nº da cota…\"\n             class=\"form-control form-control-sm\" style=\"width:230px;\">\n    </div>\n    <div style=\"align-self:flex-end;display:flex;gap:8px;\">\n      <button type=\"submit\" class=\"btn btn-primary btn-sm\">Aplicar filtros</button>\n      <a href=\"{{ url_for('condominios_validacao_sistema') }}\" class=\"btn btn-secondary btn-sm\">Limpar</a>\n    </div>\n  </div>\n  <div class=\"toolbar-right\" style=\"align-self:flex-end;\">\n    <a class=\"btn btn-secondary btn-sm\"\n       href=\"{{ url_for('condominios_validacao_sistema_exportar') }}{% if query_export %}?{{ query_export }}{% endif %}\">\n      📊 Exportar Excel\n    </a>\n  </div>\n</form>\n\n<!-- ═══ LEGENDA DAS REGRAS ═══ -->\n<div class=\"card\" style=\"margin-bottom:16px;padding:14px 16px;\">\n  <div class=\"section-label\" style=\"margin-bottom:10px;\">Regras de retirada aplicadas na simulação</div>\n  <div style=\"display:grid;grid-template-columns:repeat(3,1fr);gap:12px;font-size:12px;color:#aaa;line-height:1.7;\">\n    <div>\n      <span class=\"badge badge-civil\">🏗️ Construção Civil</span>\n      <div style=\"margin-top:6px;\">\n        Taxa normal <strong style=\"color:#d4af37;\">1,7%</strong> ao mês.<br>\n        Rende <strong>até o mês do vencimento</strong>, inclusive.<br>\n        Retirada em 3 dias — <strong>sem mês extra</strong>.\n      </div>\n    </div>\n    <div>\n      <span class=\"badge badge-agro\">🌾 Agronegócio</span>\n      <div style=\"margin-top:6px;\">\n        Taxa normal <strong style=\"color:#d4af37;\">1,5%</strong> ao mês.<br>\n        No mês do vencimento: <strong style=\"color:#fbbf24;\">{{ agro_special_label }}</strong> (taxa especial fixa).<br>\n        Retirada em 30 dias — <strong>+1 mês a 1,5%</strong>.\n      </div>\n    </div>\n    <div>\n      <span class=\"badge badge-saude\">🏥 Saúde</span>\n      <div style=\"margin-top:6px;\">\n        Taxa normal <strong style=\"color:#d4af37;\">1,8%</strong> ao mês.<br>\n        No mês do vencimento: taxa normal.<br>\n        Retirada em 30 dias — <strong>+1 mês a 1,8%</strong>.\n      </div>\n    </div>\n  </div>\n  <div style=\"margin-top:10px;font-size:11px;color:#666;\">\n    As taxas normais vêm da tabela <span class=\"text-mono\">condominiums</span> do banco.\n    A taxa especial do Agro no vencimento é fixa em {{ agro_special_label }}.\n  </div>\n</div>\n\n{% import \"_validacao_sistema_macros.html\" as vsm with context %}\n\n{# ═══════════════════════════════════════════════════════════════\n   NÍVEL 1 — CLIENTES\n   ═══════════════════════════════════════════════════════════════ #}\n\n{% if not clientes %}\n  <div class=\"empty-state\">\n    <div class=\"empty-state-icon\">🔍</div>\n    <div class=\"empty-state-title\">Nenhum cliente encontrado</div>\n    <div class=\"empty-state-sub\">Ajuste os filtros acima para ver a projeção.</div>\n  </div>\n{% else %}\n\n<div style=\"font-size:11px;color:#666;margin-bottom:6px;\">\n  👆 Clique no cliente para abrir a <strong style=\"color:#d4af37;\">previsão mês a mês</strong>\n  com os vencimentos identificados. Dentro dela, clique no condomínio para ver cota a cota.\n</div>\n\n<div class=\"table-wrap\">\n  <table>\n    <thead>\n      <tr>\n        <th style=\"width:34px;\"></th>\n        <th>Cliente</th>\n        <th>CPF/CNPJ</th>\n        <th style=\"text-align:right;\">Total investido</th>\n        <th style=\"text-align:right;\">🏗️ Civil</th>\n        <th style=\"text-align:right;\">🌾 Agro</th>\n        <th style=\"text-align:right;\">🏥 Saúde</th>\n        <th style=\"text-align:center;\">Cotas</th>\n        <th style=\"text-align:center;\">Próx. venc.</th>\n        <th style=\"text-align:right;\">Rend. {{ inicio_label }}</th>\n        <th style=\"text-align:right;\">Rend. próx. mês</th>\n        <th style=\"text-align:right;\">Rend. 12 meses</th>\n        <th style=\"text-align:center;\">Último mês</th>\n      </tr>\n    </thead>\n    <tbody>\n      {% for cli in clientes %}\n      {% set cid = 'c' ~ cli.client_id %}\n\n      <tr class=\"vs-client-row\" onclick=\"vsToggle('{{ cid }}')\" style=\"cursor:pointer;\">\n        <td style=\"text-align:center;\">\n          <span id=\"arrow-{{ cid }}\" style=\"color:#d4af37;font-size:11px;\">▶</span>\n        </td>\n        <td style=\"font-weight:600;color:#F5F5F5;\">\n          {{ cli.client_name }}\n          {% if cli.client_status == 'inativo' %}\n            <span class=\"badge badge-inactive\" style=\"margin-left:6px;\">Cliente inativo</span>\n          {% endif %}\n        </td>\n        <td class=\"text-mono text-dim\">{{ formatar_documento(cli.client_document) }}</td>\n        <td style=\"text-align:right;font-weight:700;color:#d4af37;font-size:15px;\">\n          {{ formatar_moeda(cli.total_invested) }}\n        </td>\n        <td style=\"text-align:right;color:{{ '#818cf8' if cli.total_by_condominium.civil else '#3a3a3a' }};\">\n          {{ formatar_moeda(cli.total_by_condominium.civil) if cli.total_by_condominium.civil else '—' }}\n        </td>\n        <td style=\"text-align:right;color:{{ '#22c55e' if cli.total_by_condominium.agro else '#3a3a3a' }};\">\n          {{ formatar_moeda(cli.total_by_condominium.agro) if cli.total_by_condominium.agro else '—' }}\n        </td>\n        <td style=\"text-align:right;color:{{ '#f87171' if cli.total_by_condominium.saude else '#3a3a3a' }};\">\n          {{ formatar_moeda(cli.total_by_condominium.saude) if cli.total_by_condominium.saude else '—' }}\n        </td>\n        <td style=\"text-align:center;color:#888;\">{{ cli.shares_count }}</td>\n        <td style=\"text-align:center;color:{{ '#f87171' if cli.next_maturity_overdue else '#ccc' }};font-weight:600;\">\n          {{ vsm.data_br(cli.next_maturity_date) }}\n          {% if cli.next_maturity_overdue %}<br><span style=\"font-size:10px;\">vencida</span>{% endif %}\n        </td>\n        <td style=\"text-align:right;color:#4ade80;font-weight:600;\">{{ formatar_moeda(cli.current_month_yield) }}</td>\n        <td style=\"text-align:right;color:#4ade80;\">{{ formatar_moeda(cli.next_month_yield) }}</td>\n        <td style=\"text-align:right;color:#4ade80;font-weight:600;\">{{ formatar_moeda(cli.yield_12m) }}</td>\n        <td style=\"text-align:center;color:#a78bfa;font-size:12px;\">{{ cli.last_yield_month_label }}</td>\n      </tr>\n\n      {# ═══ NÍVEL 2 — previsão mês a mês do cliente, carregada sob demanda ═══ #}\n      <tr id=\"det-{{ cid }}\" style=\"display:none;background:rgba(0,0,0,0.3);\">\n        <td colspan=\"13\" style=\"padding:0;\">\n          <div class=\"vs-lazy\" id=\"lazy-{{ cid }}\"\n               data-client-id=\"{{ cli.client_id }}\"\n               data-loaded=\"0\"\n               style=\"padding:18px;color:#666;font-size:12px;\">\n            Carregando previsão mês a mês…\n          </div>\n        </td>\n      </tr>\n      {% endfor %}\n    </tbody>\n  </table>\n</div>\n\n<div style=\"margin-top:12px;font-size:11px;color:#666;\">\n  {{ clientes | length }} cliente(s) na projeção · horizonte de {{ meses }} meses a partir de {{ inicio_label }} ·\n  rendimento total previsto no horizonte:\n  <strong style=\"color:#4ade80;\">{{ formatar_moeda(totais.yield_horizon) }}</strong>\n</div>\n\n{% endif %}\n\n{% endblock %}\n\n{% block scripts %}\n<script>\n  /* Parâmetros da projeção — usados no carregamento sob demanda */\n  var VS_INICIO   = {{ inicio_input | tojson }};\n  var VS_MESES    = {{ meses | tojson }};\n  var VS_PRODUTO  = {{ produto_filtro | tojson }};\n  var VS_URL_CLI  = {{ url_for(\"condominios_validacao_sistema_cliente\") | tojson }};\n  var VS_URL_DET  = {{ url_for(\"condominios_validacao_sistema_detalhe\")  | tojson }};\n\n  /* Abre/fecha qualquer nível (cliente ou condomínio) */\n  function vsToggle(id) {\n    var linha = document.getElementById('det-' + id);\n    var seta  = document.getElementById('arrow-' + id);\n    if (!linha) return;\n\n    var abrir = (linha.style.display === 'none' || linha.style.display === '');\n    linha.style.display = abrir ? 'table-row' : 'none';\n    if (seta) seta.textContent = abrir ? '▼' : '▶';\n\n    if (abrir) vsCarregar(id);\n  }\n  window.vsToggle = vsToggle;\n\n  /* Carrega o conteúdo apenas na primeira abertura (mantém a tela leve).\n     Sem data-condominium-id → nível 2 (cliente); com → nível 3 (condomínio). */\n  function vsCarregar(id) {\n    var box = document.getElementById('lazy-' + id);\n    if (!box || box.dataset.loaded === '1' || box.dataset.loading === '1') return;\n    box.dataset.loading = '1';\n\n    var base = box.dataset.condominiumId ? VS_URL_DET : VS_URL_CLI;\n    var url  = base\n             + '?cliente='  + encodeURIComponent(box.dataset.clientId)\n             + '&inicio='   + encodeURIComponent(VS_INICIO)\n             + '&meses='    + encodeURIComponent(VS_MESES)\n             + '&produto='  + encodeURIComponent(VS_PRODUTO || '');\n    if (box.dataset.condominiumId) {\n      url += '&condominio=' + encodeURIComponent(box.dataset.condominiumId);\n    }\n\n    fetch(url, { headers: { 'X-Requested-With': 'fetch' } })\n      .then(function (r) {\n        if (!r.ok) throw new Error('HTTP ' + r.status);\n        return r.text();\n      })\n      .then(function (html) {\n        box.innerHTML = html;\n        box.style.padding = '0';\n        box.dataset.loaded = '1';\n        box.dataset.loading = '0';\n      })\n      .catch(function (err) {\n        box.innerHTML = '<div style=\"padding:18px;color:#f87171;font-size:12px;\">'\n                      + 'Não foi possível carregar: ' + err.message\n                      + ' — recarregue a página e tente novamente.</div>';\n        box.dataset.loading = '0';\n      });\n  }\n</script>\n{% endblock %}\n",
};
